// Automatisch erzeugt aus karten/*.json mit: node tools/build-karten.js. Nicht von Hand bearbeiten.
window.KARTEN = [{"id":"bonus.a-001","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Was bedeutet es, eine Bewegung zu gestalten, und welche zwei Bedeutungen hat das Wort „Gestaltung“?","a":"• Bewegung gestalten = einer Bewegung bewusst eine spezifische Form geben\n• „Gestaltung“: 1. Prozess des Gestaltens, 2. (vorläufiges) Ergebnis/Produkt","e":"Gestalten ist das Tun, Gestaltung kann das Tun oder das fertige Stück sein. Beispiel: Eine Tanzgruppe, die zu einer Musik Bewegungen ausprobiert, gestaltet (Prozess); die am Ende aufgeführte Kür ist die Gestaltung als Ergebnis.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-002","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Erläutere den Unterschied zwischen dem Gestalten eines Turners (Bodenturnen) und dem Gestalten einer Tanzgruppe.","a":"• Turner: meist vorgegebene Form, bewertet nach normierten Kriterien (Kampfrichter)\n• Tanzgruppe: reaktiv, spontan, durch Ausprobieren passend zur Musik\n• Beide: Gestaltung als Prozess und Ergebnis","e":"Der Turner arbeitet nach einem Regelwerk, die Kampfrichter prüfen festgeschriebene Kriterien. Die Tanzgruppe lässt sich vom Stil der Musik leiten und probiert Bewegungen aus, die passen und für alle ausführbar sind. Beispiel: Ein Doppelsalto mit Schraube muss eine genormte Form haben, während eine Hip-Hop-Gruppe ihre Moves aus dem Beat heraus entwickelt.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-003","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Warum ist das Gestalten von Bewegung nach Cabrera-Rivas (2010) ein universales und kulturstiftendes Phänomen?","a":"• Bedürfnis, Lebensbedingungen, Erfahrungen, Empfindungen und Neigungen zu formen und auszudrücken\n• damit verbunden: Mitteilungsbedürfnis\n• Mitteilen macht Gestalten kulturstiftend","e":"Menschen wollen ausdrücken, was sie erleben, und anderen davon erzählen, auch mit dem Körper. Weil dieses Bedürfnis überall vorkommt, ist Gestalten universal. Beispiel: Volkstänze oder Siegesjubel-Rituale entstehen so und werden Teil einer Kultur.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-004","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Nenne die vier Facetten des Gestaltens (nach Klinge & Schütte) und die Faktoren, die bestimmen, wie sie sich zeigen.","a":"Facetten:\n• ästhetisches Verhalten\n• expressives Hervorbringen\n• kompositorisches Ergebnis\n• performatives Präsentsein\nFaktoren:\n• Kontext (schulisch/außerschulisch)\n• situative Gegebenheiten\n• Gestaltungsabsicht\n• persönliche Dispositionen","e":"Eselsbrücke: „Ästhetisch – Expressiv – Kompositorisch – Performativ“ (Ä-E-K-P: wahrnehmen, ausdrücken, zusammensetzen, aufführen). Situative Gegebenheiten sind z. B. Raum und Material, die Absicht umfasst Motive und Vorhaben. Beispiel: Eine Schulklasse in der Turnhalle mit wenig Geräten gestaltet anders als ein Profi-Ensemble auf der Bühne, obwohl beide dieselben Facetten nutzen können.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-005","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Erläutere Gestalten als ästhetisches Verhalten.","a":"• aisthesis (griech.) = Wahrnehmung, Empfindung\n• persönliche Auseinandersetzung mit Wahrgenommenem und dessen individuelle Verarbeitung (nicht nur „schöne Darbietung“)\n• Gestaltete Bewegung = sichtbares Ergebnis dieser Reflexion","e":"Ästhetik heißt hier zuerst: genau wahrnehmen (Welt, Umgebung, soziales Umfeld, eigene sinnliche Verfassung) und das Wahrgenommene verarbeiten. Im Schulsport ist das besonders in Tanz und Gymnastik relevant: Sinnliche Wahrnehmung und Gestaltungsfähigkeit sollen verbessert werden. Beispiel: Eine Schülerin tanzt, wie sich für sie der Abschied von einer Freundin anfühlt; sie bringt in Bewegung, was sie bewegt.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-006","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Unterscheide die ausdrückend-expressive und die rituell-darstellende Dimension von Bewegung (nach Grupe).","a":"• Ausdrückend-expressiv: Stimmungen, Einstellungen, Gefühle über Bewegung (v. a. Gestik, Mimik) ausdrücken; Ausstrahlung und bewusster Ausdruck\n• Rituell-darstellend: Bewegungen mit sozialisierten, festgelegten Bedeutungen (Rituale)","e":"Expressiv = ich zeige mein Gefühl, ob als persönliche Ausstrahlung oder bewusst hergestellt (z. B. Tanz, Bewegungstheater); rituell = ich führe eine vereinbarte Geste aus, deren Sinn alle kennen. Beispiel: Ein wütender Tanz ist expressiv, das Abklatschen nach einem Schmetterschlag im Volleyball, der Handschlag unter Turnern oder die Verbeugung im Judo sind rituell-darstellend.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-007","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Welche Stilmittel werden eingesetzt, um Emotionen oder Ideen in Tanz und Bewegungstheater darzustellen, und welche Wirkungen können erzielt werden?","a":"Stilmittel:\n• Übertreibung\n• Verlangsamung\n• Verfremdung\nWirkungen:\n• mitreißen\n• aufwühlen, nachdenklich machen\n• unterhalten, zum Lachen bringen","e":"Gefühle werden auf der Bühne erst sichtbar, wenn man sie verstärkt oder verändert. Beispiel: Trauer lässt sich gut durch Verlangsamung zeigen (schwere, zähe Bewegungen), Freude oder Wut eher durch Übertreibung.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-008","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Erläutere Gestalten als kompositorisches Ergebnis.","a":"• Komposition (lat. componere = zusammenstellen): aus einzelnen Elementen eine komplexe Gestalt formen\n• Formen/Strukturen festgelegt, Ganzes variabel\n• Choreografie = „Endprodukt eines Gestaltungsprozesses“ (Meusel & Wieser)","e":"Man baut aus Bausteinen ein Ganzes: Elemente werden zusammengesetzt, geübt und durch schwierigere Varianten ergänzt. Im Wettkampfsport gelten andere Vorgaben als im Bewegungstheater oder Crossoversport; auch der Zufall kann eine Rolle spielen und Anlass für Improvisation sein. Beispiel: Kinder setzen beim Gummitwist einzelne Sprünge zu einer „Probe“ zusammen und erweitern sie um schwierigere Varianten, genau so arbeiten auch Choreografen.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-009","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Was bedeutet der Begriff Choreografie wörtlich, und welche zwei Bedeutungen unterscheidet Lampert?","a":"• choros = Tanz, graphein = schreiben → „Tanzschrift“\n• Lampert: 1. Aufzeichnungssystem (Bewegungen mit Symbolen notieren), 2. tänzerische Komposition","e":"Ursprünglich war Choreografie eine Art Notenschrift für Haltungen, Stellungen, Einzel- und Gruppenbewegungen und Richtungen. Heute meint man meist das zusammengestellte Stück selbst; diese Bedeutung hat sich auf viele kompositorische Sportarten ausgedehnt. Beispiel: Die Labanotation ist ein Aufzeichnungssystem; die Kür einer Rhythmischen Sportgymnastin ist eine Choreografie im Sinn von Komposition.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-010","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Erläutere Gestalten als performatives Präsentsein.","a":"• to perform: gegenwartsbezogene Aktivität mit unmittelbarer Wirkung auf andere\n• spontane, flüchtige, nicht wiederholbare Aufführungen statt einstudierter Darbietung\n• Nähe zur Improvisation","e":"Hier zählt der Moment: Durch Raum, Zeit, Situation und das Einbeziehen der Zuschauer entsteht etwas, das so nur einmal passiert. Performative Präsenz heißt, sich seines Körpers, seiner Bewegungsmuster und Rituale bewusst zu sein und sie spontan und unvorhersehbar nach außen wirken zu lassen (z. B. Tanzimprovisation, Improvisationstheater). Beispiel: Ein Straßenjongleur reagiert auf ein lachendes Kind im Publikum und baut es spontan in seine Show ein.","quelle":"L6.1","typ":"kern"},{"id":"bonus.a-011","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Was versteht man unter Gestaltungsfähigkeit, und wie zeigt sich Gestaltenkönnen?","a":"• Gestaltungsfähigkeit = kreativer, vom Alltagsdruck befreiter Umgang mit gestellten Aufgaben (Klinge & Schütte)\n• Gestaltenkönnen: konstruktiver, individueller Umgang mit ästhetischen Erfahrungen, Verunsicherungen, Problemen","e":"Gestaltungsfähig ist, wer mit einer offenen Aufgabe kreativ und eigenständig etwas Eigenes macht. Wegen der vielen Facetten lässt sie sich nicht genau definieren. Fördernde Aufgaben folgen einer Idee mit offenem Ausgang und vielen Lösungen. Beispiel: Wettkampfregeln im Eiskunstlauf sind die Aufgabe, aus der jede Läuferin eine Kür entwickelt, die zu ihren Voraussetzungen passt; beim Skaten kann ein Trick Ausgangspunkt einer Gestaltung sein.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-012","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Nenne die sechs Wirkungsabsichten bei Gestaltungsprozessen (nach Klinge & Schütte).","a":"• normierte Präsentation\n• kurzweilige Unterhaltung\n• spannendes Ereignis\n• humorvolle Darstellung\n• widerständige Vieldeutigkeit\n• provozierende Beteiligung","e":"Die Wirkungsabsicht ist Ausgangspunkt des Gestaltungsprozesses. Die Reihe geht von „Normen erfüllen“ bis „Zuschauer aktiv provozieren“. Eselsbrücke: N-K-S-H-W-P = „Nur Kinder Spielen Heute Wilde Partys“. Beispiel: Eine Turnkür will normiert präsentieren, ein Straßentheater will die Passanten zum Mitmachen provozieren.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-013","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Welche Rolle spielt die Absicht für eine Bewegungsgestaltung, und welche Spannweite von Absichten gibt es?","a":"• Absicht/Gestaltungsmotiv ist Ausgangspunkt; daraus entsteht eine Form\n• Gestaltungsmittel schaffen Kongruenz von Absicht und Wirkung\n• Spannweite: Normen bedienen … Erwartungen brechen, verunsichern, zum Mitgestalten provozieren","e":"Erst die Absicht, dann die Form, die sich oft auf Umwegen entwickelt und Erfahrungen der Gestaltenden ausdrückt. Der Beobachter kann sie interpretieren und bewerten; die gewählten Mittel sollen dafür sorgen, dass ankommt, was gemeint war. Zwischen den Polen liegen z. B. Eindruck hinterlassen und Zuschauergewohnheiten entsprechen. Beispiel: Wer zum Lachen bringen will, wählt Übertreibung und Slapstick, wer verunsichern will, eher rätselhafte, gebrochene Bewegungen.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-014","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Beschreibe die Wirkungsabsichten „normierte Präsentation“ und „kurzweilige Unterhaltung“ mit ihren Hauptmerkmalen und Anwendungsbereichen.","a":"• Normierte Präsentation: Regeln/Normen der Sportart bestimmen Absicht und Wirkung; Wettkampfsport kompositorischer Sportarten (z. B. RSG)\n• Kurzweilige Unterhaltung: Show und Vergnügen, großer Gestaltungsspielraum; Jazzdance, Schaulaufen, Turnfest-Vorführungen","e":"Bei der normierten Präsentation entscheiden Vorgaben, Vorbilder und das Regelwerk, bei der Unterhaltung der Spaß des Publikums. Weitere Bereiche der Unterhaltung: Video-Clip-Dancing, Folkloretänze. Beispiel: Eine RSG-Kür bei der Meisterschaft vs. ein Schaulaufen nach der Eiskunstlauf-WM mit Showeinlagen.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-015","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Beschreibe die Wirkungsabsichten „spannendes Ereignis“ und „humorvolle Darstellung“ mit ihren Hauptmerkmalen und Anwendungsbereichen.","a":"• Spannendes Ereignis: überraschende Bewegungen, Geschick, Originalität → intensives Miterleben; z. B. Akrobatik, Breakdance, Parkour\n• Humorvolle Darstellung: Witz, Komik, Bewegungen in ungewohnten Kontexten; z. B. Bewegungstheater, Comedy-Einlagen","e":"Spannung entsteht durch das „Wow, wie geht das?“, Humor durch das „Das passt doch gar nicht zusammen!“, wenn Alltags- und Sportbewegungen in neue Zusammenhänge gesetzt werden. Weitere Bereiche: Zirkus-Tanz-Theater, Skateboarding, Freerunning, Tricking, Biking bzw. clowneske, skurrile Darbietungen. Beispiel: Ein Freerunner springt überraschend über eine Häuserlücke; ein Trampolinturner tut so, als würde er vom Gerät fallen.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-016","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Beschreibe die Wirkungsabsichten „widerständige Vieldeutigkeit“ und „provozierende Beteiligung“ mit ihren Hauptmerkmalen und Anwendungsbereichen.","a":"• Widerständige Vieldeutigkeit: Absicht bewusst verfremdet, Erwartung gebrochen, Sinn erst im Nacherleben; z. B. Tanztheater, Ausdruckstanz\n• Provozierende Beteiligung: Zuschauer werden in die Gestaltung einbezogen; z. B. Straßen-, Improvisationstheater","e":"Bei der Vieldeutigkeit muss der Zuschauer selbst rätseln, bei der Beteiligung wird er sogar Teil der Aufführung; die Akteure nutzen ihn für die Entstehung und Fortentwicklung ihrer Aktionen. Weitere Bereiche: zeitgenössischer Tanz (Post Modern, New, Performance Dance), performativer Tanz. Beispiel: Ein Tanztheaterstück endet ohne Auflösung und man diskutiert danach über den Sinn; bei einer Straßenperformance wird ein Passant in den Tanz hineingezogen.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-017","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Nenne die fünf Gestaltungsprinzipien (nach Klinge & Schütte) und ihre Funktion.","a":"• Sich-ähnlich-Machen und Nachmachen\n• Ausgrenzen und Reduzieren\n• Rhythmisieren\n• Kontrastieren und Polarisieren\n• Verändern und Verfremden\nFunktion: gestalterische Auseinandersetzung anregen, Bewegungen inszenieren","e":"Diese Prinzipien sind Werkzeuge, mit denen man aus normalen Bewegungen etwas Gestaltetes macht. Eselsbrücke: „Nach-Aus-Rhy-Kon-Ver“. Beispiel: Eine Gruppe kopiert zuerst einen Move (Nachmachen) und spielt ihn dann in Zeitlupe gegen schnelle Moves (Kontrastieren).","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-018","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Erläutere das Gestaltungsprinzip „Sich-ähnlich-Machen und Nachmachen“.","a":"• Nachahmen und Anpassen als grundlegende menschliche Lernmöglichkeit\n• Soziale Vorbilder an eigene Bedürfnisse anpassen (nicht ohne Widerstände)\n• ermöglicht intrinsisch motiviertes Lernen","e":"Wir lernen viel, indem wir andere mimisch und gestisch kopieren und das an uns anpassen, schon vom Kind zum Erwachsenen. Ungewohntes kann dabei zunächst verunsichern. Eine moderne Sportpädagogik sollte das Nachahmen systematisch nutzen. Beispiel: Jugendliche bringen sich über YouTube-Videos komplizierte Tanzmoves, Turnelemente oder Basketball-Tricks selbst bei.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-019","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Erläutere das Gestaltungsprinzip „Ausgrenzen und Reduzieren“.","a":"• bewusste Beschränkung auf Teile des Ganzen\n• Aufmerksamkeit auf begrenzten Ausschnitt lenken → schärft Blick fürs Ganze\n• Je klarer die Einschränkung, desto leichter das Gestalten","e":"Wahrnehmung ist immer selektiv, sonst wären wir von der Fülle der Möglichkeiten überfordert. Weniger Möglichkeiten machen deshalb kreativer. Beispiel: Eine Bewegungsfolge zu zweit, bei der immer nur zwei Füße und eine Hand den Boden berühren dürfen.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-020","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Erläutere das Gestaltungsprinzip „Rhythmisieren“.","a":"• sich auf Rhythmen/Musik einlassen und sie sinnlich erfahren\n• aber auch Distanz zu „pathischen Zwängen“ (Bräuer) → eigenen Körperrhythmus finden\n• Zugänge: körpereigene Rhythmen (Puls, Atmung) und Umgebungsrhythmen","e":"Man lässt sich vom Takt mitnehmen, findet aber auch seinen eigenen, statt einen Rhythmus nur zu übernehmen. Beispiel: Eine Gruppe gestaltet eine Sequenz nach dem eigenen Atemrhythmus oder nach dem Klappern von Absätzen auf dem Hallenboden.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-021","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Erläutere die Gestaltungsprinzipien „Kontrastieren und Polarisieren“ sowie „Verändern und Verfremden“.","a":"• Kontrastieren/Polarisieren: Gewohntes durch Gegensätze durchkreuzen (schnell/langsam, groß/klein) → Bekanntes hervorheben\n• Verändern/Verfremden: kleine Änderungen am Gewohnten → Vertrautes mit anderen Augen sehen, neue Perspektiven","e":"Beide Prinzipien brechen Sehgewohnheiten, das eine durch Gegensätze (z. B. auch männliche/weibliche Gesten, verschiedene Tanzrichtungen), das andere durch kleine Veränderungen. Kontraste können auch unbemerkte Facetten des Bekannten akzentuieren; Verfremdung fordert heraus zu begreifen, was bekannt, was fremd ist und wie daraus Eigenes entsteht. Beispiel: Ein Tänzer bewegt sich in Zeitlupe, während alle anderen rasen (Kontrast); im Sportspiel wird nur eine Raumregel geändert (z. B. Tore nur aus einer Zone), und ein bekanntes Spiel wirkt völlig neu (Verfremdung).","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-022","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Was sind Gestaltungsparameter (Gestaltungskriterien), und welche fünf Bereiche umfassen sie?","a":"Möglichkeiten von Bewegungshandlungen in:\n• Raum\n• Zeit\n• Krafteinsatz (Dynamik)\n• Gruppenbezügen (sozial)\n• formalem Aufbau (Form)\nFunktion: Absichten verdeutlichen; Hilfe für Choreografie, Analyse und Beurteilung","e":"Mit diesen fünf „Stellschrauben“ kann man jede Bewegung verändern und eine Gestaltung beschreiben, verstehen und beurteilen. Beispiel: Dieselbe Armbewegung kann hoch oder tief (Raum), schnell oder langsam (Zeit), kraftvoll oder weich (Kraft), allein oder im Kanon (Gruppe) und am Anfang oder als Schluss (Aufbau) ausgeführt werden.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-023","thema":"B.L6","kapitel":"Gestaltungsprinzipien","q":"Warum sind Gestaltungsparameter für Gestaltungsaufgaben unverzichtbar, und was haben alle Gestaltungsanlässe bzw. -prinzipien gemeinsam?","a":"• Gemeinsam: Alle Anlässe/Prinzipien erzeugen Widerstände, die verarbeitet werden\n• Parameter ordnen die Fülle vager Ideen\n• Erst sie konkretisieren Aufgaben: legen fest, in welcher Hinsicht (Raum, Zeit, Dynamik, Form, sozial) gestaltet wird","e":"Ohne Parameter bleibt „gestaltet mal was“ zu offen. Durch die Orientierung an Raum, Zeit, Form und Kraft und die Beschränkung auf einzelne Bestandteile werden unklare Absichten strukturiert. Beispiel: Statt „Tanzt zu Wut“ sagt die Lehrkraft „Zeigt Wut nur auf tiefer Raumebene und mit plötzlichem Krafteinsatz“, so wird die Aufgabe greifbar.","quelle":"L6.2","typ":"kern"},{"id":"bonus.a-024","thema":"B.L6","kapitel":"Bewegungsgestaltung","q":"Was versteht man unter Crossoversport?","a":"Bewegungselemente, Regeln, Umgebungen oder Geräte verschiedener Sportarten werden systematisch oder zufällig kombiniert, vermischt und neu definiert (Brandl-Bredenbeck & Pfleger).","e":"Crossover heißt: Man mischt Bestandteile verschiedener Sportarten und es entsteht etwas Neues, also ein Gestaltungsprozess. Beispiel: Beachvolleyball verbindet Volleyball mit der Umgebung Strand/Sand, kleineren Teams und eigenen Regeln (z. B. Pokeshot erlaubt, Lob verboten).","quelle":"L6.3","typ":"kern"},{"id":"bonus.a-025","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Definiere Choreografie im Tanz.","a":"Geplante, festgelegte, wiederholbare Raumschrift mit festgelegtem Tanzrhythmus, die eine Idee, Emotion oder ein Thema ausdrückt (Lampert; Hessloehl).","e":"Eine Choreografie ist wie ein Drehbuch für Bewegungen: Wo, wann und wie getanzt wird, steht fest. Nach Jeschke ist sie eine vom Choreografen zusammengestellte Auswahl von Bewegungen und Positionen mit inhaltlichem und formalem Zusammenhang, die Tänzer in abgesprochenem Ablauf beliebig wiederholen können. Beispiel: Eine einstudierte Cheerleading-Kür wird bei jedem Auftritt in derselben Abfolge getanzt.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-026","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Erläutere die Wiederholbarkeit als zentrales Kriterium der Choreografie (Begriffe „ähnliche Unähnlichkeit“ und „memoriale Komposition“).","a":"• Wiederholung = Versuch exakter Nachahmung, zeigt aber immer Differenzen → „ähnliche Unähnlichkeit“ (Brandstetter)\n• trotzdem wiederholbar, da im Gedächtnis fixiert → „memoriale Komposition“ (Feist)","e":"Kein Auftritt ist exakt gleich, aber er ist „gleich genug“, weil der Ablauf im Kopf gespeichert ist. Beispiel: Eine Tanzgruppe tanzt dieselbe Choreografie an zwei Abenden; Kleinigkeiten wie Armhöhe oder Timing weichen ab, die Abfolge bleibt.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-027","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Unterscheide Mikro-Raumschrift und Makro-Raumschrift.","a":"• Mikro-Raumschrift: Raumwege der Körperteile innerhalb der Kinesphäre (Laban)\n• Makro-Raumschrift: Bodenwege und Raumordnung (Formation) im Raum","e":"Raumschrift entsteht aus der Bewegungsabfolge im Raum; der Tänzer speichert sie und „liest“ sie beim Tanzen aus der Erinnerung ab (imaginäre Bewegungsspuren). Mikro = was der Körper an seinem Platz macht, Makro = wohin er sich im Raum bewegt. Beispiel: Eine Armwelle ist Mikro-Raumschrift; dass die Gruppe von einer Linie in einen Kreis läuft, ist Makro-Raumschrift.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-028","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Was ist die Kinesphäre nach Laban?","a":"Raumkugel um den Körper, deren Rand man mit locker gestreckten Gliedmaßen erreicht, ohne den Platz zu verlassen; man trägt sie immer mit sich.","e":"Stell dir eine unsichtbare Blase um dich vor, so weit deine Arme und Beine reichen. Bewegt man sich darüber hinaus, schafft man einen neuen Standort; die Kinesphäre wandert „wie eine Aura“ mit. Beispiel: Ein Tänzer, der auf der Stelle Arme und Beine in alle Richtungen streckt, tastet seine Kinesphäre ab; geht er los, wandert die Blase mit.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-029","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Welche Rolle spielt der Rhythmus in der Choreografie?","a":"• festgelegter Parameter der Choreografie\n• gliedert zeitlichen Verlauf und zeitliche Verhältnisse der Bewegung\n• nicht nur Musikbetonung übertragen, auch Spannung durch kontrapunktische Entgegensetzung","e":"In der klassischen Choreografie wird versucht, die Betonung der Musik auf die Bewegung zu übertragen. Konsequent zum Musikrhythmus zu tanzen ist aber selten möglich; es geht eher darum, den Rhythmus des Tanzens zu verfolgen, und gerade das bewusste Gegenarbeiten macht es spannend. Beispiel: Zu schneller Musik bewegt sich eine Tänzerin plötzlich ganz langsam, das wirkt besonders eindrucksvoll.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-030","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Sind Improvisation und Choreografie Gegensatzpaare? Begründe.","a":"Nur scheinbar:\n• Improvisation enthält Vorbereitung, Übung, erlernte Erinnerung\n• Choreografie enthält Improvisation (Ideenfindung, „Durchspielen“)\n• Gegensatz nur bei Improvisation als eigene Bühnenform\n• Unterschiede: Zeitaufwand/Entscheidungszeit, Art der Erinnerung","e":"Auf den ersten Blick ist Choreografie vorher festgelegt und geplant, Improvisation spontan und frei erfunden. Bei näherer Betrachtung überlappen sie stark: Viele Choreografen nutzen Improvisation als erste Arbeitsstufe. Nur bei der Improvisational Dance Performance tritt Improvisation als konkurrierende Kunstform auf. Die Dichotomie ist daher weitgehend aufgehoben. Beispiel: Ein Choreograf lässt seine Tänzer erst zu einem Thema improvisieren und hält die besten Ideen dann als feste Choreografie fest.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-031","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Nenne die Merkmalspaare von Improvisation und Choreografie (Tab. 7.1).","a":"Improvisation ↔ Choreografie:\n• Spontanität ↔ Vorbereitung\n• Offenheit ↔ Geschlossenheit\n• Unvorhersehbarkeit ↔ Vorhersehbarkeit\n• Unwiederholbarkeit ↔ Wiederholbarkeit\n• Fehler zulassen ↔ vermeiden\n• Spiel ↔ Übung\n• spontane ↔ erlernte Erinnerung","e":"Die Tabelle zeigt die Gegensätze, die man auf den ersten Blick sieht; bei genauer Analyse überlappen sie sich aber. Beispiel: Ein Jam-Session-Tanz im Kreis (Improvisation) gegenüber einem eingeübten Formationstanz (Choreografie).","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-032","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Wie lässt sich das Spielerische sowohl der Improvisation als auch der Choreografie zuordnen?","a":"• Spiel = zweckfreie, intuitive Tätigkeit → zunächst Improvisation zugeordnet\n• aber auch Choreografieren „spielt“ Möglichkeiten durch\n• Choreografie = reflektierte und spontane Zusammensetzung/Variation von Elementen","e":"Spiel steht dem wiederholten Üben zunächst entgegen; auch in Sportspielen wird innerhalb der Regeln improvisiert. Doch beim Erfinden einer Choreografie wird ebenfalls herumprobiert, sodass Spontanität einfließt, mit dem Ziel einer spannenden, ansprechenden Darbietung. Beispiel: Eine Gruppe testet fünf verschiedene Übergänge zwischen zwei Teilen und entscheidet sich dann für den besten.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-033","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Definiere Üben (nach Hagedorn) und erläutere den Umgang mit Fehlern in Choreografie und Improvisation.","a":"• Üben = Überlernen durch gezielte Wiederholung und systematische Variation der Bedingungen, um Gelerntes zu sichern und verfügbar zu machen (Hagedorn)\n• Choreografie: Fehler = zu vermeidender Unfall\n• Improvisation: Fehler werden aufgefangen und eingebaut","e":"In der Choreografie soll häufiges Üben Sicherheit geben und Unvorhersehbares minimieren; in der Improvisation wird ein Fehler zum Material, weil Unvorhersehbares nicht eingeübt werden kann. Lampert nennt Improvisation „ein beherrschtes Scheitern“, das selbst viel Übung braucht (beherrschte Bewegungsmuster, Variationen, Habitus). Beispiel: Rutscht eine Improvisationstänzerin aus, macht sie aus dem Rutschen eine Bodenrolle und tanzt weiter, als wäre es geplant.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-034","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Wie unterscheiden sich Choreografie und Improvisation im Verhältnis von Entdecken und Ausführen?","a":"• Improvisation: Entdecken und Ausführen gleichzeitig\n• Choreografie: nacheinander → erleichtert Strukturierung und Planung","e":"In beiden wechseln sich entdeckende und ausführende Vorgänge ab. Beim Improvisieren erfindet man, während man tanzt; beim Choreografieren erfindet man erst und tanzt später. Beispiel: Ein Freestyle-Battle im Breakdance (zeitgleich) vs. eine wochenlang erarbeitete Showeinlage (nacheinander).","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-035","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Unterscheide strukturierte und offene Improvisation.","a":"• Strukturiert: vorab Entscheidungen nach einem Plan für die Struktur\n• Offen: ohne Plan/Absprachen, aus dem Stegreif, aber mit trainiertem Körper und Bewegungsrepertoire\n→ auch Improvisation enthält Vorbereitung","e":"Selbst die freieste Improvisation greift auf das zurück, was der Körper schon kann; sie beruht auf persönlichen Erfahrungen, sodass individuelle Tanzmuster und Bewegungsgewohnheiten sichtbar werden. Beispiel: Strukturiert: „Improvisiert 30 Sekunden nur auf tiefer Ebene, dann wechselt ihr zu Sprüngen.“ Offen: Musik an, los, ohne jede Vorgabe.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-036","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Worin liegt der entscheidende Unterschied zwischen Choreografie und Improvisation, und wie unterscheidet sich die Zeitwahrnehmung?","a":"• Entscheidend: Nur Ausführende wissen, ob choreografiert oder improvisiert\n• Improvisation: Zeitaufwand ≈ Darbietungszeit, kurze Entscheidungszeit\n• Choreografie: zeitintensiver Übungsprozess, keine Zeitgrenzen für Entscheidungen","e":"Von außen sieht man keinen Unterschied. Bei der Improvisation werden spontane, vorläufige Bewegungsantworten akzeptiert und weiterentwickelt. Bei der Choreografie wird der Ablauf durch Wiederholen und Variieren verinnerlicht und kann beliebig optimiert werden. Beispiel: Eine perfekt wirkende Contact-Improvisation kann genauso aussehen wie eine einstudierte Partnerfolge, aber die eine entstand in 3 Minuten, die andere in 3 Wochen.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-037","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Erläutere die beiden Gedächtnisformen nach Bergson und ihren Bezug zu Choreografie und Improvisation.","a":"• Erlernte Erinnerung (Choreografie): durch Wiederholung, wird automatisiert und unpersönlicher\n• Spontane Erinnerung (Improvisation): Form wird von Moment zu Moment neu entschieden\n• stützen sich gegenseitig: Umgesetztes Spontanes wird erlernt","e":"Bei der erlernten Erinnerung tritt wie bei einem auswendig gelernten Gedicht der individuelle Formgebungswille zurück. Die spontane Erinnerung schafft zunächst keine Gewohnheiten, persönliche Entscheidung und Form werden bewusst kontrolliert. Was man oft improvisiert, wird aber irgendwann zur Gewohnheit. Beispiel: Ein Breakdancer erfindet spontan einen Übergang; weil er ihn bei jedem Battle wieder benutzt, wird er zu einem festen Teil seines Repertoires.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-038","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Nenne die vier Aspekte, die Tanzimprovisation auszeichnen (nach Lampert).","a":"• körperliche Vorbereitung des Habitus\n• Veränderung des Habitus\n• Fallenlassen und Stabilisieren zwischen Unbekanntem und Bekanntem (emergent)\n• neuartige Bewegungen durch Erneuerung/Neukombination von Bekanntem","e":"Improvisation baut auf einem trainierten Körper auf und verändert ihn dabei; der Habitus ist das individuelle tänzerische Erscheinungsbild. Beispiel: Eine Ballett-Tänzerin improvisiert zu Hip-Hop-Musik, kombiniert ihre bekannten Drehungen neu und erweitert so ihren Stil.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-039","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Warum ist tänzerisches Improvisieren kein reines Nachahmen, und wie wird der Habitus aktualisiert?","a":"• Improvisieren aktualisiert immer den Habitus und verändert ihn dabei\n• daher Erweiterung des Repertoires statt reinen Nachahmens\n• besonders durch ergebnisoffenen Umgang mit Zufälligem","e":"Wer improvisiert, bleibt nicht derselbe Tänzer, sondern entwickelt sich weiter. Beispiel: Ein Tänzer, der nur Standardschritte kannte, findet in Improvisationsstunden neue Bodenbewegungen, die später zu seinem Stil gehören.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-040","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Beschreibe das Wellenmodell der improvisatorischen Bewegung (Fallenlassen und Stabilisieren).","a":"• Unvorhersehbares destabilisiert das Repertoire (Fall ins Unbekannte, „Chaos“)\n• neue Bewegungsformen stabilisieren („Ordnung“, Schwebezustand)\n• erneutes Fallenlassen usw.\n→ Erweiterung des Bewegungsrepertoires","e":"Improvisation ist wie Wellenreiten zwischen Chaos und Ordnung: Jeder „Wellenumbruch“ bringt neue Bewegungen hervor. Beispiel aus dem Buch: Gehen ist ein ständiges Fallen und Auffangen; bei jedem Schritt fällt man ein Stück nach vorn und fängt sich wieder.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-041","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Wie entstehen in der Improvisation neuartige Bewegungsformen, und was bedeutet Emergenz?","a":"• Neues entsteht durch vorhersehbare Erneuerung des Alten oder durch Emergenz\n• Emergenz (Riedl): Zusammentreten von Bausteinen bringt völlig neue, unvorhersehbare Eigenschaften hervor, die in den Bausteinen nicht vorkommen","e":"Das Ganze ist mehr als die Summe seiner Teile: Obwohl der Ablauf weitgehend kausal ist, steckt die neue Qualität nicht einmal in Spuren in den einzelnen Bausteinen. Beispiel: Zwei Tänzer kombinieren einen bekannten Sprung und eine bekannte Hebefigur und es entsteht eine völlig neue Flugbewegung, die in keinem der beiden Elemente steckte.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-042","thema":"B.L7","kapitel":"Choreografie & Improvisation","q":"Erläutere die Analogie zwischen tänzerischer Improvisationsfähigkeit und spielsportspezifischer Individualtaktik.","a":"• Voraussetzung: geformter Körper/Habitus bzw. koordinative, technische, konditionelle Ausbildung\n• Improvisationsfähigkeit = spontane Kombination tänzerischen Materials\n• Individualtaktik = effektive spielspezifische Handlungsvariabilität","e":"Nur wer viel kann, kann auch frei improvisieren, im Tanz wie im Spiel. Die Ausführung der Improvisation aktualisiert und verändert das tänzerische Erscheinungsbild; Individualtaktik ist auf hohe Effektivität ausgerichtet. Die Überlegungen lassen sich auf andere gestalterische Sportsituationen übertragen. Beispiel: Ein Basketballer kann im Spiel nur dann kreativ einen ungewöhnlichen Pass spielen, wenn er Technik und Individualtaktik sicher beherrscht.","quelle":"L7.1","typ":"kern"},{"id":"bonus.a-043","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Beschreibe den choreografischen Prozess (nach Hessloehl) mit seinen Stufen.","a":"• Reflexion: Absicht über W-Fragen klären (Wozu? Wer? Wo? Wann? Für wen? Wie? Was?)\n1. Bewegungen entwickeln (Impuls: auditiv, visuell, taktil, Thema)\n2. kombinieren und variieren\n3. Endform erstellen","e":"Erst klären, worum es geht, dann sammeln, dann sortieren und zusammenbauen, dann fertigstellen. Die W-Fragen schaffen einen Arbeitsrahmen, die Antworten können sich später ändern. In Stufe 2 werden Bewegungen verbunden, verändert, ausgewählt oder ergänzt. Beispiel: Für ein Schulfest (Wozu/Für wen) erfindet eine Gruppe zu einem Song (auditiver Impuls) Bewegungen, variiert sie und setzt daraus die fertige Show zusammen.","quelle":"L7.2","typ":"kern"},{"id":"bonus.a-044","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Welche fünf kombinatorischen Fähigkeiten werden auf Basis der Neun-Punkte-Technik geschult?","a":"• Responsivität (reagierender Körper)\n• Problemlösen\n• schnelles Denken/Antizipieren\n• schnelles Tanzen/Risiko eingehen\n• Imagination (bildliche Vorstellung)","e":"Kombinatorik ist die Lehre von den Möglichkeiten, Elemente anzuordnen; die „Kunst der Kombinatorik“ meint die Fähigkeit, bei einer Live-Performance tänzerisch zu improvisieren. Ein guter Improvisierer reagiert, löst Probleme, denkt voraus, traut sich etwas und arbeitet mit inneren Bildern. Beispiel: Beim Duett-Improvisieren reagiert die Tänzerin sofort auf einen Impuls des Partners (Responsivität) und stellt sich vor, sie wäre Wasser (Imagination).","quelle":"L7.2","typ":"kern"},{"id":"bonus.a-045","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Nenne die fünf Improvisationsgrade und erläutere ihren Zusammenhang mit dem Planungsgrad.","a":"• Imitation\n• Interpretation\n• Verkettung\n• geplante Improvisation\n• ungeplante Improvisation\nJe höher der Improvisationsgrad (1–10), desto niedriger der Planungsgrad (10–1).","e":"Die Grade bemessen sich daran, wie stark die Improvisation im Voraus geplant ist: Imitation = Improvisationsgrad 1, Planungsgrad 10 (geschlossen); ungeplante Improvisation = Improvisationsgrad 10, Planungsgrad 1 (offen). Je mehr vorher feststeht, desto weniger wird improvisiert. Beispiel: Eine Bewegungsfolge exakt nachtanzen ist Imitation; ohne jede Vorgabe zu unbekannter Musik tanzen ist ungeplante Improvisation.","quelle":"L7.2","typ":"kern"},{"id":"bonus.a-046","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Ordne den Improvisationsgraden Planungsgrad, Veränderungsgrad des Bewegungsrepertoires und Vermittlungstechnik zu (Tab. 7.3 nach Lampert).","a":"Grad (Impro/Planung, Veränderung): Technik\n• Imitation (1/10, sehr gering): Spiegelung\n• Interpretation (2–3/8–9, gering): Variation\n• Verkettung (3–4/7–8, gering): festgelegtes Material\n• geplante Impro (5–6/5–6, hoch): komplexe Strukturvorgaben\n• ungeplante Impro (10/1, gering–sehr gering): passives Geschehenlassen","e":"Die Veränderungsgrade sind mit a (Imitation) bis e/f (ungeplante Improvisation) bezeichnet. Auffällig: Die größte Veränderung des Repertoires gibt es in der Mitte, bei der geplanten Improvisation. Bei reiner Imitation lernt man nichts Neues, bei völlig ungeplanter Improvisation fällt man leicht in alte Gewohnheiten zurück. Beispiel: Die Aufgabe „Verbindet diese drei Elemente in beliebiger Reihenfolge, wechselt dabei zweimal die Raumebene“ ist eine komplexe Strukturvorgabe.","quelle":"L7.2","typ":"kern"},{"id":"bonus.a-047","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Wie hängen Improvisation und Veränderung des Bewegungsrepertoires zusammen, und wozu nutzt man diesen Zusammenhang in der Vermittlung?","a":"• Improvisation verändert das Bewegungsrepertoire (Neukombination → emergente Bewegungen)\n• Aus Planungs- und Improvisationsgrad lässt sich der Veränderungsgrad ablesen\n• Nutzen: passende Aufgaben/Techniken für jeden Grad formulieren","e":"Je stärker improvisiert wird, desto mehr Raum bietet das Zufällige für neue Kombinationen bekannter Muster. Aus Planung, Improvisation und Veränderung lässt sich das Veränderungspotenzial bestimmen, sodass die Lehrkraft gezielt wählen kann, wie viel Offenheit eine Aufgabe haben soll. Beispiel: Für Anfänger erst Spiegelung, dann Variation, dann Aufgaben mit festgelegtem Material, später komplexe Strukturvorgaben.","quelle":"L7.2","typ":"kern"},{"id":"bonus.a-048","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Was sind die Hauptziele im Vermittlungsprozess der Tanzimprovisation?","a":"• ganzheitliche Körperwahrnehmung\n• vollständiges Sich-gehen-Lassen (Flow)","e":"Ziel ist, ganz im Tanzen aufzugehen; im Flow lösen sich Zeit und Raum vollständig auf. Beispiel: Eine Schülerin tanzt so versunken, dass sie erst beim Musikende merkt, dass schon zehn Minuten vergangen sind.","quelle":"L7.2","typ":"kern"},{"id":"bonus.a-049","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Beschreibe die Neun-Punkte-Technik nach Laban.","a":"• Raummodell: Würfel mit 27 Punkten (26 um den Körper, 1 in der Körpermitte), auf 3 Ebenen à 9 Punkte\n• Tänzer trägt das Gerüst mit sich und bewegt sich vielfältig darin\n• Basis für Kombinatorik und Improvisation","e":"Man stellt sich einen unsichtbaren Würfel um sich vor und „berührt“ seine Punkte mit Körperteilen. Die Technik wurde für Profis entwickelt, eignet sich aber auch für Laien. Der Würfel kann verkleinert, vergrößert, verschoben oder um andere Körperteile gelegt werden, sogar außerhalb des Tänzers stehen und ihn „jagen“; wichtig ist die Anzahl der Punkte, nicht ihre Nummerierung. Beispiel: „Erreiche mit dem rechten Ellbogen Punkt oben-vorne-rechts, mit dem Knie Punkt unten-hinten-Mitte“, so entstehen ungewöhnliche Bewegungen.","quelle":"L7.2","typ":"kern"},{"id":"bonus.a-050","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Beschreibe die Begriffe Bewegungskombination und Bewegungsvariation im Tanz und ihre Beziehung zur Bewegungsharmonie.","a":"• Variation: Bewegung in Parametern verändern (Raum, Tempo, Dynamik, Richtung, Ebene, Körperteil)\n• Kombination: mehrere Bewegungen zu einer Abfolge verbinden\n• Harmonie: fließende Übergänge (Bewegungsfluss, Kopplung, Rhythmus)","e":"Variation ändert eine Bewegung, Kombination reiht Bewegungen aneinander, und Harmonie entsteht, wenn alles fließt. Variationen verändern Rhythmus und Kopplung und müssen so eingesetzt werden, dass ein stimmiger Gesamteindruck entsteht. Koordinativ erhöhen beide v. a. Komplexitäts-, Situations- und ggf. Zeitdruck sowie die Informationsanforderungen. Beispiel: Ein Chassé wird einmal schnell und hoch, einmal langsam und tief getanzt (Variation) und dann an eine Drehung angeschlossen (Kombination); stockt der Übergang, wirkt es unharmonisch.","quelle":"L7.3","typ":"zusatz"},{"id":"bonus.a-051","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Definiere den Begriff Wagnis (nach Neumann).","a":"Wagnis = das selbstständige und bewusste Aufsuchen und Akzeptieren einer unsicheren Situation, die mithilfe der eigenen Fähigkeiten gemeistert wird (Neumann, 1999).","e":"Entscheidend sind Freiwilligkeit, Bewusstheit und das eigene Können. „Wagen“ heißt, ein Risiko bewusst einzugehen, angetrieben von einem Wagnisgewinn („Wer nicht wagt, der nicht gewinnt“). Im Sport bedeutet das, eine reizvolle Bewegungsaufgabe mit unsicherem Ausgang einzugehen und motorisch zu bewältigen. Beispiel: Ein Schüler entscheidet sich selbst, zum ersten Mal vom 3-m-Brett zu springen, weil er sich den Sprung zutraut.","quelle":"L8.1","typ":"kern"},{"id":"bonus.a-052","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Wie wird Risiko mathematisch-naturwissenschaftlich beschrieben, und was ist die Schwäche dieser Sichtweise?","a":"• Risiko = Eintrittswahrscheinlichkeit × Schadenshöhe\n• Schwäche: vernachlässigt die subjektive Seite; Können der Person bleibt unberücksichtigt","e":"Die scheinbar objektive Beschreibung tut so, als wäre die Wahrscheinlichkeit des Scheiterns vorab festgelegt. Beispiel: Ein Sturz beim Freesolo-Klettern ist vielleicht unwahrscheinlich, aber der Schaden wäre tödlich, also ist das Risiko hoch; ob der Kletterer die Route sicher beherrscht, berücksichtigt die Formel aber kaum.","quelle":"L8.1","typ":"kern"},{"id":"bonus.a-053","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Grenze den Risikobegriff vom Wagnisbegriff im Sport ab (nach Krieger & Roschmann).","a":"• Risiko: objektive Seite (Wahrscheinlichkeit, Schaden); eher sportpsychologisch/-soziologisch\n• Wagnis: subjektive Seite (bewusst, freiwillig, eigenes Können, Erleben); eher sportpädagogisch","e":"Risiko ist die Außensicht (Wie gefährlich ist das?), Wagnis die Innensicht (Wie erlebe und bewältige ich das?). Beispiel: Für einen Profi-Kletterer kann eine Route objektiv riskant, subjektiv aber gut kontrollierbar sein; für einen Anfänger ist schon die Kletterwand ein großes Wagnis.","quelle":"L8.1","typ":"kern"},{"id":"bonus.a-054","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Was bedeuten die Begriffe Abenteuer und Erlebnis im Kontext von Wagnis und Risiko?","a":"• Abenteuer: länger andauernde Unternehmung mit unsicheren Zusammenhängen\n• Erlebnis: Ereignis, das sich stark vom Alltag abhebt und lange im Gedächtnis bleibt","e":"Der Erlebnisbegriff ist im Sport meist positiv besetzt, aber breit und unscharf, da Erlebnisse nicht immer mit Unsicherheit und Spannung verbunden sind. Beispiel: Eine mehrtägige Kanutour durch die Wildnis ist ein Abenteuer; der erste Sonnenaufgang auf einem Berggipfel ist ein Erlebnis.","quelle":"L8.1","typ":"kern"},{"id":"bonus.a-055","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Was kennzeichnet Wagnissport, und wie unterscheidet sich Neumanns Ansatz von früheren erlebnispädagogischen Ansätzen?","a":"• Wagnissport: individuelles, reflexionsbedürftiges Handeln in ausgangsoffenen, bedrohlichen Situationen, lösbar durch motorisches Können\n• Früher: Bewährung/Erlebnis im Vordergrund; Neumann (2013): das Prozesshafte","e":"Es geht nicht nur ums „Sich-Beweisen“, sondern um den ganzen Ablauf vom Entschluss bis zur Reflexion. Beispiel: Beim Klettern im Unterricht zählt nicht nur, ob man oben ankommt, sondern auch, wie man sich entschieden, die Angst ausgehalten und danach darüber gesprochen hat.","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-056","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Beschreibe den idealtypischen Handlungsverlauf in sportlichen Wagnissituationen (Aufsuchen, Aushalten, Auflösen).","a":"• Aufsuchen: bewusster, freiwilliger Entschluss (nicht von außen erzwungen)\n• Aushalten: Unsicherheit und Angst freiwillig aushalten\n• Auflösen: Nachbetrachtung, Reflexion über Gefühle, Grenzen, eigenes Können","e":"Merksatz: Wagnisse werden bewusst aufgesucht, freiwillig ausgehalten und durch Nachbetrachtung aufgelöst. Im Unterricht gehört zum Aufsuchen die Sensibilisierung für Gefahren. Manche Situationen lassen sich nach dem Start nicht mehr stoppen, daher braucht es eine schrittweise Heranführung; Aushalten betrifft motorische, emotionale, kognitive und soziale Fähigkeiten. Beispiel: Beim Turmspringen entscheidet man sich (Aufsuchen), muss nach dem Absprung Flug und Landung aushalten und bespricht danach, wie es sich angefühlt hat (Auflösen); vorher übt man Sprünge aus niedriger Höhe mit Körperspannung.","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-057","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Was versteht Neumann unter der doppelten pädagogischen Ambivalenz sportlicher Wagnisse?","a":"• Gelingen und Misslingen haben jeweils Sonnen- und Schattenseiten\n• jede Möglichkeit braucht Reflexion\n• Deutung hängt von der Attribution ab","e":"Doppelt, weil es zwei Ausgänge gibt und jeder Ausgang zwei Seiten hat. Gelingen kann das Selbstbewusstsein stärken, aber auch Übermut festigen; Misslingen kann eine wichtige Grenzerfahrung sein oder als Unfähigkeit erlebt werden. Erfolgszuversichtliche (selbstwertdienlich attribuierend) sehen eher die Sonnen-, Misserfolgsängstliche eher die Schattenseiten. Regelmäßige Reflexionsphasen beugen Schattenseiten vor. Beispiel: Gelingt ein Rückwärtssalto, ist man stolz (Sonne), probiert aber vielleicht gleich etwas viel zu Schweres (Schatten).","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-058","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Nenne Sonnen- und Schattenseiten des Gelingens sportlicher Wagnisse (Tab. 8.1 nach Neumann).","a":"Sonnenseiten:\n• Selbstwirksamkeit, Selbstvergewisserung\n• Selbstbewusstsein, -wert, -vertrauen\n• legitime Selbstermächtigung\n• positives Selbsterleben\n• Vertrauen, Verantwortungsübernahme\nSchattenseiten:\n• Identitätsauflösung\n• leichtfertiger Körpereinsatz\n• gelernte Sorglosigkeit\n• Steigerungsspirale\n• Gladiatorenkomponente","e":"Erfolg macht stark, kann aber auch leichtsinnig machen. Partnerschaftliches Vertrauen mindert das Risiko; Identitätsauflösung meint z. B. das Ankämpfen gegen Naturgewalten; bei der Gladiatorenkomponente wird gewagt, weil andere zuschauen. Beispiel: Wer den Sprung vom 3-m-Brett geschafft hat, fühlt sich selbstwirksam, will aber vielleicht sofort vom 10-m-Turm (Steigerungsspirale).","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-059","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Nenne Sonnen- und Schattenseiten des Misslingens sportlicher Wagnisse (Tab. 8.1 nach Neumann).","a":"Sonnenseiten:\n• Kontrollerfahrung trotz Scheitern\n• Akzeptanz, Anreiz zur Wiederholung\n• realistisches Selbstbild\n• Angstlust\n• erfülltes Vertrauen\nSchattenseiten:\n• Inkompetenz, Selbstverunsicherung\n• beschädigtes Selbstwertgefühl\n• unrealistisch-negatives Selbstbild\n• Angst\n• enttäuschtes Vertrauen","e":"Scheitern kann lehrreich oder entmutigend sein, je nachdem, wie man es verarbeitet und ob Dritte verantwortungsvoll handeln. Beispiel: Rutscht eine Kletterin ab und wird vom Partner sicher gehalten, erlebt sie Vertrauen und Kontrolle (Sonne); lässt der Partner sie unsicher fallen, ist das Vertrauen enttäuscht (Schatten).","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-060","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Was ist die Gladiatorenkomponente, und warum soll sie im Sportunterricht ausgeschlossen werden?","a":"• Gewagt wird, weil andere zuschauen, obwohl das Können nicht reicht (Präsentationseffekt)\n• Ausschluss wegen Verletzungsgefahr: Es geht nicht um Mutproben, sondern um realistische Selbsteinschätzung","e":"Wie ein Gladiator in der Arena wagt man etwas für das Publikum und die soziale Anerkennung statt für sich. Deshalb sollte man präventiv mit den Schülern darüber sprechen; zur verantwortungsvollen Einschätzung gehört auch die Einsicht, bestimmte Wagnisse nicht einzugehen. Beispiel: Orkan springt vom 3-m-Brett ohne Einspringen den „Ripper“, um vor der Klasse anzugeben, verliert die Körperspannung und fordert die anderen auf, es ihm nachzumachen.","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-061","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Nenne die didaktischen Grundsätze zur Wagnisvermittlung im Schulsport (nach Neumann & Katzer) und erläutere sie.","a":"• Beim Wagen zählt das eigene Können (nicht Glück)\n• Gladiatorenkomponente ausschließen\n• Anforderungen richtig einschätzen (auch Verzicht ist Kompetenz)\n• Misslungene Wagnisse richtig einordnen","e":"Vier Leitsätze: eigenes Können, kein Angeben, realistisch einschätzen, Scheitern verarbeiten. Gerade Misserfolgsängstliche sollen Erfolge internal-stabil (auf das eigene Können) attribuieren; Scheitern muss möglich sein und reflektiert werden. Beispiel: Die Lehrkraft lobt nach einem gelungenen Sprung ausdrücklich die gute Vorbereitung („Das hast du dir erarbeitet“) statt Glück.","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-062","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Welche Steigerungsmöglichkeiten gibt es bei Wagnisangeboten in der Schule, und welche weiteren Grundsätze sind zu beachten?","a":"Steigerung (heterogen):\n• Wagnisniveau\n• Wagniskomplexität\n• Wagnismenge\nGrundsätze:\n• Scheitern möglich, aber Sicherheit hat oberste Priorität\n• Ziele langfristig anbahnen","e":"Wagnisse sollen individuell steigerbar sein, aber immer sicher bleiben. Niveau: z. B. schwierigere Sprungfigur; Komplexität: z. B. Sicherheitsaspekte vertiefen; Menge: z. B. vom Stationsbetrieb zum Run. Ein realistisch-optimistisches Selbstbild und realistische Gefahreneinschätzung entstehen nicht in einem einmaligen Vorhaben. Beispiel: Beim Parkour üben manche zuerst einzelne Sprünge an Stationen, Fortgeschrittene verbinden sie zu einem ganzen Lauf.","quelle":"L8.2","typ":"kern"},{"id":"bonus.a-063","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Stelle einen Bezug zwischen Wagnisvermittlung im Schulsport und dem KAR-Modell nach Neumaier her.","a":"• Wagnisse erhöhen v. a. Situations-, Präzisions-, Zeit- und Belastungsdruck sowie vestibuläre/kinästhetische Anforderungen\n• Folge: Druckbedingungen schrittweise steigern, damit das Wagnis beherrschbar bleibt","e":"Das KAR-Modell beschreibt koordinative Anforderungen als Informationsanforderungen (optisch, akustisch, taktil, kinästhetisch, vestibulär) und Druckbedingungen (Präzision, Zeit, Komplexität, Situation, Belastung). Wagnisse sind unsicher (Situation), Fehler haben Folgen (Präzision), Flugphasen sind kurz (Zeit) und die Psyche ist belastet. So kann man genau benennen, was ein Wagnis schwer macht, und einzelne Bedingungen gezielt verändern. Beispiel: Ein Sprung vom 1-m-Brett hat geringeren Präzisions- und Belastungsdruck als derselbe Sprung vom 3-m-Brett.","quelle":"L8.2","typ":"zusatz"},{"id":"bonus.a-064","thema":"B.L8","kapitel":"Trendsport","q":"Was sind Trends, und welche drei zentralen gesellschaftlichen Trends nennt Schildmacher, die auch den Sport prägen?","a":"• Trends = tiefgreifende, nachhaltige Entwicklungen\n• Schildmacher (1998): Suche nach Authentizität, Konsumismus, Eventorientierung\n• Sportliche Trends münden in Trendsportarten","e":"Menschen wollen echt sein, konsumieren und Events erleben, und das spiegelt sich im Sport. Beispiel: Ein Skatecontest mit DJ und Markenausrüstung bedient alle drei Trends gleichzeitig.","quelle":"L8.3","typ":"kern"},{"id":"bonus.a-065","thema":"B.L8","kapitel":"Trendsport","q":"Welche Folgen haben Trends und Trendsportarten für den Sport und die Wirtschaft?","a":"• Trendsport als Werbeträger (authentisches, attraktives Image)\n• Veränderung traditioneller Strukturen des Sporttreibens\n• Mitgliederrückgang in Vereinen traditioneller Wettkampfsportarten\n• Neuausrichtung des Sportunterrichts","e":"Trendsport ist cool, deshalb hängen sich Marken daran, und er nimmt den Vereinen Mitglieder weg. Beispiel: Energydrink-Firmen sponsern Freeski- und BMX-Events, um ihr Image jugendlich und wild wirken zu lassen.","quelle":"L8.3","typ":"kern"},{"id":"bonus.a-066","thema":"B.L8","kapitel":"Trendsport","q":"Wie definieren Lamprecht und Stamm Trendsportarten?","a":"Trendsportarten als Gegenbewegung zu traditionellen Sportarten (nicht nur neue Geräte):\n• Spaß statt Leistung\n• informelle Gruppe statt Verein/Verband","e":"Trendsport ist das „Anti-Vereinsmodell“: Er propagiert ein Sportverständnis quer zum traditionellen Sportbegriff, Spaß statt Leistung, Freunde statt Verein. Beispiel: Skater treffen sich ohne Trainer und ohne Mitgliedsbeitrag im Skatepark und probieren Tricks.","quelle":"L8.3","typ":"kern"},{"id":"bonus.a-067","thema":"B.L8","kapitel":"Trendsport","q":"Nenne typische Merkmale von Trendsportarten.","a":"• Innovation, Gegenentwurf zum traditionellen Sport\n• eigener „Style“, kreative, nicht normierte Bewegungen\n• Spaß statt Leistung, informelle Gruppe statt Verein\n• neue Geräte; oft outdoor, risikoreich, unverbindlich\n• Lifestyle/Szene; Event- und Konsumorientierung","e":"Trendsport lebt vom eigenen Stil und der Szene mit eigener Mode und Sprache; statt verschulter Bewegungsmuster zählt jugendliche Freiheit. Beispiel: Beim Freerunning gibt es keine festgelegte Technik und keine Punktrichter, wichtig ist der eigene kreative Weg durch die Stadt.","quelle":"L8.3","typ":"kern"},{"id":"bonus.a-068","thema":"B.L8","kapitel":"Trendsport","q":"Nenne und beschreibe die fünf Entwicklungsphasen von Trendsportarten (nach Lamprecht & Stamm).","a":"• Invention: Erfindung durch Pioniere\n• Innovation: lokale Marktnischen\n• Entfaltung und Wachstum: überregional, Massenproduktion\n• Reife und Diffusion: weite Verbreitung\n• Sättigung: etabliert als „normale“ Sportart","e":"Das Muster ähnelt wirtschaftlichen Innovations- und Produktionszyklen: In der Innovationsphase gibt es Ausrüstung nur in kleiner Zahl für wenige Nutzer, im Wachstum wird sie weiterentwickelt und massenhaft produziert. Eselsbrücke: „In In Ent Rei Sät“. Beispiel: Snowboarden wurde von wenigen Surfern erfunden, war dann eine Szene, wuchs zum Massenmarkt und ist heute olympisch und in jedem Skigebiet normal.","quelle":"L8.3","typ":"kern"},{"id":"bonus.a-069","thema":"B.L8","kapitel":"Trendsport","q":"Nenne die fünf Entwicklungsschritte im Freizeitsport nach Schildmacher.","a":"• indoor → outdoor\n• normiert → nicht normiert\n• großer Mannschaftssport → kleiner Gruppensport\n• geschützt → risikoreich\n• verbindlich → unverbindlich","e":"Der Freizeitsport geht nach draußen, wird freier, kleiner, wagemutiger und lockerer. Beispiel: Aus Hallenvolleyball (6 gegen 6, im Verein, feste Trainingszeiten) wird Beachvolleyball (2 gegen 2, draußen, spontan mit Freunden).","quelle":"L8.3","typ":"kern"},{"id":"bonus.a-070","thema":"B.L8","kapitel":"Trendsport","q":"Wie verändern sich sportliche Bewegungen in Trendvarianten traditioneller Sportarten (z. B. Streetbasketball, Beachvolleyball)?","a":"• Umgebung (Sand, Asphalt, Wind) → höhere Gleichgewichts-/Anpassungsanforderungen\n• kleinere Teams → mehr Ballkontakte, Allroundtechnik, mehr Laufarbeit\n• andere Regeln → neue Techniken/Taktiken\n• mehr Kreativität und Style","e":"Die Bewegungen werden an neue Bedingungen angepasst und dadurch neu gestaltet. Im KAR-Modell steigen Situationsdruck und kinästhetisch-vestibuläre Anforderungen (Untergrund), Komplexitäts- und Belastungsdruck (2 gegen 2, 3 gegen 3). Regeln wie ein Korb beim Streetball oder Pokeshot statt Lob beim Beachvolleyball erfordern neue Lösungen; normierte Technikleitbilder treten zurück. Beispiel: Im Sand springt man niedriger und bewegt sich langsamer als in der Halle; deshalb sind Pritsche und Pokeshot wichtiger als harte Schmetterbälle aus großer Höhe.","quelle":"L8.4","typ":"zusatz"},{"id":"bonus.a-071","thema":"B.L8","kapitel":"Trendsport","q":"Welche Faktoren haben zur Popularisierung des Beachvolleyballs beigetragen, und warum ist das Medieninteresse am Hallenvolleyball geringer?","a":"Beach: Trends (Outdoor, Event, Lifestyle), leicht zugänglich, medienattraktiv (kleine Teams, Spektakel, Ästhetik), olympisch seit 1996\nHalle: traditioneller, 6er-Teams → weniger Identifikation, weniger telegen, unplanbare Spieldauer","e":"Beachvolleyball verkauft Sommer, Sonne und Stars, Hallenvolleyball „nur“ Sport. Zum Beach-Flair gehören Urlaub, Strand und Musik; wenige Spieler und Unverbindlichkeit machen ihn zum Freizeitsport, Werbung und Sponsoren verstärken die Medienpräsenz. In der Halle sind schnelle Ballwechsel schwerer zu verfolgen, und das Satzsystem macht die Spieldauer schwer planbar. Beispiel: Ein Beachvolleyballturnier am Stadtstrand mit DJ zieht viele Zuschauer an, obwohl manche kaum die Regeln kennen.","quelle":"L8.4","typ":"zusatz"},{"id":"bonus.a-072","thema":"B.L9","kapitel":"Motive","q":"Definiere den Begriff Motiv (nach Gabler).","a":"Motive sind aus Verhalten und Äußerungen erschlossene Bereitschaften, sich situationsüberdauernd, zeitstabil und persönlichkeitsspezifisch in einer Situation so und nicht anders zielgerichtet zu verhalten (Gabler).","e":"Ein Motiv ist eine stabile innere Bereitschaft, die man an einer Person immer wieder beobachten kann. Im Sport sind Motive persönlichkeitsspezifische Wertungsdispositionen, die auf sportliche Situationen gerichtet sind. Beispiel: Ein Schüler, der bei jeder Wettkampfaufgabe in jedem Sport besonders ehrgeizig ist, hat vermutlich ein stark ausgeprägtes Leistungsmotiv.","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-073","thema":"B.L9","kapitel":"Motive","q":"Erkläre, warum Motive hypothetische Konstrukte sind.","a":"• nicht direkt beobachtbar\n• gedankliche Hilfskonstruktion zwischen beobachtbarer Situation und beobachtbarem Handeln („intervenierende Variable“, Gabler)\n• nur aus Verhalten und Situation erschließbar","e":"Man sieht nur Situation und Verhalten; das Motiv dazwischen, das das Handeln steuert, muss man erschließen. Beispiel: Ein Schüler strengt sich bei einer Trefferübung an: Das kann auf ein Leistungsmotiv hindeuten; macht ein sonst unmotivierter Schüler erst beim Teamwettbewerb mit, deutet das eher auf ein Anschlussmotiv.","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-074","thema":"B.L9","kapitel":"Motive","q":"Erläutere das Bild von Motiv als Motor eines Autos.","a":"• Motiv = Motor (treibt an)\n• Bedürfnis/Defizit = Zündkerze (Startenergie)\n• Ziel erreichen befriedigt das Bedürfnis; wichtigeres Ziel → mehr Energie\n• Motivation = aktuelle Fahrweise, abhängig von Umweltbedingungen (Anreizen)","e":"Motiv ist der Motor, Motivation ist, wie gerade gefahren wird: gleichmäßig, schnell, langsam oder gar nicht, je nach Anreizen wie Wetter, Straße, Geld oder Zwängen. Beispiel: Eine Läuferin mit starkem Gesundheitsmotiv (Motor) läuft bei Sonnenschein locker los, bei Sturm bleibt sie vielleicht zu Hause (Fahrweise abhängig von Bedingungen).","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-075","thema":"B.L9","kapitel":"Motive","q":"Was versteht Gabler unter Grundsituationen im Sport?","a":"• häufig wiederkehrende Situationen, zu denen man aus Erfahrung stabile Bewertungssysteme entwickelt\n• dienen zur übersichtlichen Kategorisierung von Motiven\n• z. B. Leistung, Anschluss, Hilfe, Spiel, Aggression","e":"Bestimmte Situationen kommen im Sport immer wieder vor, man wird mit ihnen konfrontiert oder sucht sie auf, und relativ viele Personen entwickeln dazu überdauernde Wertungsdispositionen. Beispiel: Wettkämpfe (Leistung) liebt der eine, der andere meidet sie, das ist eine stabile Bewertung.","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-076","thema":"B.L9","kapitel":"Motive","q":"Nach welchen Kriterien kategorisiert Gabler Motive im Sport? Stelle das Raster (Tab. 9.1) dar.","a":"Bezug × Person (ichbezogen | sozial):\n• Sporttreiben selbst: Bewegung | soziale Interaktion\n• Ergebnis: Leistung als Selbstbestätigung | Fremdbestätigung\n• Mittel für weitere Zwecke: Gesundheit | Kontakt, Geselligkeit","e":"Zwei Dimensionen: Worauf bezieht sich das Motiv, und ist es ichbezogen oder sozial? 3 × 2 = sechs Felder. Beispiel: Jan spielt gern mit Kumpels Fußball, geht aber nicht mit in die Kneipe → Sporttreiben selbst, im sozialen Kontext (soziale Interaktion). Ulrike macht Rückentraining nach Bandscheibenvorfall → Mittel für weitere Zwecke, ichbezogen (Gesundheit).","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-077","thema":"B.L9","kapitel":"Motive","q":"Nenne die ichbezogenen Motive, die sich auf das Sporttreiben selbst beziehen, und das Motiv im sozialen Kontext (Tab. 9.2 nach Gabler).","a":"Ichbezogen:\n• Bewegung, körperliche Aktivität\n• Freude an Bewegungsformen\n• ästhetische Erfahrungen\n• Bewegungsempfindungen\n• Selbsterfahrung\n• Askese, Selbstüberwindung\n• Spiel\n• Risiko, Abenteuer, Spannung\nSozial:\n• soziale Interaktion","e":"Hier zählt das Sporttreiben an sich, nicht was dabei herauskommt. Beispiel: „Den Körper in lautloser Stille spüren“ beim Tauchen (Bewegungsempfindungen) oder „Den inneren Schweinehund überwinden“ (Askese).","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-078","thema":"B.L9","kapitel":"Motive","q":"Nenne die Motive, die sich auf das Ergebnis des Sporttreibens beziehen (Tab. 9.2 nach Gabler).","a":"Ichbezogen (Selbstbestätigung):\n• sachbezogener Erfolg\n• subjektbezogener Erfolg\n• sozialbezogener Erfolg\nSozial:\n• Leistung als Präsentation\n• Fremdbestätigung, Anerkennung\n• Prestige\n• Macht","e":"Bei Selbstbestätigung zählt das eigene Urteil, bei Fremdbestätigung das der anderen. Sachbezogen = die Aufgabe gelingt, subjektbezogen = besser als früher selbst, sozialbezogen = besser als andere. Beispiel: „Ich möchte erstmals unter vier Stunden laufen“ (subjektbezogen), „Dem habe ich's gezeigt“ (sozialbezogen), „Das haben die hoffentlich gefilmt“ (Präsentation).","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-079","thema":"B.L9","kapitel":"Motive","q":"Nenne die Motive, die sich auf das Sporttreiben als Mittel für weitere Zwecke beziehen (Tab. 9.2 nach Gabler).","a":"Ichbezogen:\n• Gesundheit\n• Fitness\n• Aussehen\n• Entspannung\n• Kompensation\n• Naturerlebnis\n• Freizeitgestaltung\n• materielle Gewinne\nSozial:\n• Kontakt, Anschluss\n• Geselligkeit\n• Aggression\n• sozialer Aufstieg\n• Ideologie","e":"Hier ist Sport nur Mittel zum Zweck, etwa für körperliche Tüchtigkeit, Zerstreuung oder Kameradschaft. Beispiel: „Das Laufen hat mir der Arzt verschrieben“ (Gesundheit), „Dabei kann ich meine Wut rauslassen“ (Kompensation), „Durch den Sport habe ich viele Leute kennengelernt“ (Kontakt).","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-080","thema":"B.L9","kapitel":"Motive","q":"Welche Motive gelten in der Sportpsychologie als (mehr oder weniger) theoretisch genau bestimmt, und warum ist das Gesundheitsmotiv umstritten?","a":"• Genau bestimmt: Aggressions-, Angst-, Fairness-, Hilfe-, Leistungs-, Machtmotiv (Gabler)\n• Gesundheitsmotiv umstritten: vermutlich keine eigene Motivklasse, sondern verschiedene Motive dahinter (Beckmann et al.)","e":"Nur wenige Motive sind begrifflich und theoretisch genau bestimmt und empirisch überprüft. „Ich mache Sport für meine Gesundheit“ klingt eindeutig, dahinter stecken aber oft Aussehen, Leistungsfähigkeit, Wohlbefinden, Angst vor Krankheit oder Anschluss. Beispiel: Jemand joggt „für die Gesundheit“, eigentlich aber, um schlanker auszusehen und mit Freunden zusammen zu sein.","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-081","thema":"B.L9","kapitel":"Motive","q":"Nenne und erläutere die „Big Three“ der Motivationsforschung mit ihrem affektiven Kern.","a":"• Leistung: Herausforderung durch schwierige, lösbare Aufgaben; Kern: Neugier, Stolz\n• Anschluss: Zugehörigkeit, Gemeinschaft, Geborgenheit; Kern: Liebe\n• Macht: Einfluss, Kontrolle, Autonomie; Kern: Selbstbehauptung, Stärke\n(Scheffler)","e":"Leistung, Anschluss, Macht: Das sind die drei großen Antriebe. Leistungsmotivierte suchen anregende, komplexe Aufgaben, Anschlussmotivierte Geselligkeit, Machtmotivierte Entscheidungsspielraum. Beispiel: Die eine will den Pokal (Leistung), der andere das Mannschaftsgefühl (Anschluss), der dritte will Kapitän sein und bestimmen (Macht).","quelle":"L9.1","typ":"kern"},{"id":"bonus.a-082","thema":"B.L9","kapitel":"Motive","q":"Wo lassen sich die Motive für Risikosport (Angstlust, Reizsuchverhalten) im Kategorisierungsraster von Gabler einordnen?","a":"• v. a. Sporttreiben selbst, ichbezogen: „Risiko, Abenteuer, Spannung“\n• auch: Ergebnis (Selbstbestätigung; sozial: Präsentation/Prestige)\n• auch: Mittel für Zwecke (Kompensation, Naturerlebnis)","e":"Risikosportler suchen vor allem den Kick im Tun selbst, auch Bewegungsempfindungen und Selbsterfahrung; oft spielen weitere Motive mit, etwa „etwas Besonderes geleistet“ oder kathartisch „Probleme vergessen“. Beispiel: Ein Freerider genießt den Nervenkitzel im Tiefschnee (Risiko, Spannung) und postet danach das Video (Leistung als Präsentation).","quelle":"L9.1","typ":"zusatz"},{"id":"bonus.a-083","thema":"B.L9","kapitel":"Motivation","q":"Unterscheide Motivierung und Motivation (nach Gabler).","a":"• Motivierung = Prozess der Motivanregung durch die Situation\n• Motivation = Ergebnis dieser Motivierung (aktueller Prozess aus Motiven und Anreizen)\n• Motiv = überdauernde Bereitschaft","e":"Motivierung ist das Anstoßen, Motivation das Ergebnis. Das Motiv ist persönlichkeitsmerkmalähnlich, die Motivation entsteht aktuell im Zusammenwirken mit umweltbezogenen Anreizen. Beispiel: Ein Basketballtrainer fragt „Wer schafft in zwei Minuten die meisten Treffer in Folge?“ (Motivierung des Leistungsmotivs); die Spieler strengen sich dann im Wurftraining stark an (Motivation).","quelle":"L9.2","typ":"kern"},{"id":"bonus.a-084","thema":"B.L9","kapitel":"Motivation","q":"Was motiviert uns zu einem bestimmten Handeln, und welche beiden Motivtendenzen werden unterschieden?","a":"• Anreizwerte der vorweggenommenen Handlungsfolgen und persönliche Präferenzen (positiv → anstreben, negativ → meiden)\n• Motivtendenzen: Hoffnung auf (z. B. Erfolg) und Furcht vor (z. B. Misserfolg)","e":"Wir handeln, weil wir die Folgen vorwegnehmen und bewerten; entscheidend ist die Wechselwirkung von Anreiz und Präferenz. Jedes Motiv hat eine Annäherungs- und eine Vermeidungsseite. Beispiel: Vor dem Elfmeter denkt der eine „Ich treffe bestimmt!“ (Hoffnung), der andere „Hoffentlich verschieße ich nicht!“ (Furcht).","quelle":"L9.2","typ":"kern"},{"id":"bonus.a-085","thema":"B.L9","kapitel":"Motivation","q":"Ordne Leistungs-, Anschluss- und Machtmotiv die Motivtendenzen Hoffnung und Furcht zu (nach Schmalt & Heckhausen).","a":"• Leistung: Hoffnung auf Erfolg / Furcht vor Misserfolg\n• Anschluss: Hoffnung auf Anschluss / Furcht vor Zurückweisung\n• Macht: Hoffnung auf Machtzuwachs und -ausübung / Furcht vor Macht(verlust), Gegenmacht, erfolglosem Machtverhalten","e":"Die Furcht beim Machtmotiv ist vielschichtig: vor Zuwachs oder Verlust eigener Machtquellen, vor der Ausübung eigener Macht, vor Gegenmacht und vor Erfolglosigkeit des eigenen Machtverhaltens. Beispiel Anschluss: Eine neue Spielerin freut sich auf die Mannschaft oder hat Angst, nicht aufgenommen zu werden. Beispiel Macht: Ein Kapitän genießt es, Entscheidungen zu treffen, oder fürchtet, dass das Team ihm nicht folgt.","quelle":"L9.2","typ":"kern"},{"id":"bonus.a-086","thema":"B.L9","kapitel":"Motivation","q":"Wie unterscheiden sich erfolgszuversichtliche und misserfolgsängstliche Personen in ihrer Aufgabenwahl?","a":"• Erfolgszuversichtliche: mittelschwere, lösbare Aufgaben → in kleinen Schritten an die Leistungsgrenze\n• Misserfolgsängstliche: sehr leichte oder viel zu schwere Aufgaben → Furcht verfestigt sich","e":"Misserfolgsängstliche schützen ihren Selbstwert: Bei leichten Aufgaben scheitern sie nicht („das schafft ja jeder“), bei zu schweren ist Scheitern entschuldigt („zu schwer“). Beispiel: Beim Hochsprung wählt der Erfolgszuversichtliche eine Höhe knapp über seiner Bestleistung, der Misserfolgsängstliche entweder eine sehr niedrige oder eine unerreichbare Höhe.","quelle":"L9.2","typ":"kern"},{"id":"bonus.a-087","thema":"B.L9","kapitel":"Motivation","q":"Beschreibe den Ablauf von Motivationsprozessen nach dem Grundschema von Gabler (Abb. 9.1).","a":"1. Anregung: Situation regt Motiv an (Motivierung)\n2. Motiviertsein: Kognitionen/Emotionen, Folgen antizipieren\n3. Zielorientierte Handlung (Realisation)\n4. Bewertung und Emotion (Interpretation)\n5. Rückwirkung auf das Motiv (und die Situation)","e":"Situation weckt Motiv → man überlegt (Kann ich das Ziel erreichen?) und fühlt (Hoffnung, Befürchtung) → man entscheidet sich und handelt → man bewertet Ausführung und Folgen (Freude, Enttäuschung) → das prägt das nächste Mal. Handlung und Folgen können auch die Situation beeinflussen, z. B. Lehrer oder Zuschauer. Beispiel: Ein Sportlehrer kündigt einen 1000-m-Test an (Anregung); die Schülerin glaubt, ihre Bestzeit schlagen zu können, läuft, freut sich über die neue Bestzeit und geht künftig motivierter in Ausdauertests.","quelle":"L9.2","typ":"kern"},{"id":"bonus.a-088","thema":"B.L9","kapitel":"Motivation","q":"Erläutere das Grundmodell der Motivationspsychologie (Motivation als Produkt von Person und Situation).","a":"• Person: Motive, Ziele, Bedürfnisse\n• Situation: Anreize, Gelegenheiten\n• Zusammenwirken → aktuelle Motivation → Handlung (Rheinberg & Vollmeyer)","e":"Ein Motiv allein reicht nicht, erst eine passende Situation mit Anreizen führt zur Handlung. Beispiel: Ein stark leistungsmotivierter Schüler zeigt im langweiligen Aufwärmen wenig Einsatz, im Wettkampfspiel aber volle Anstrengung.","quelle":"L9.2","typ":"kern"},{"id":"bonus.a-089","thema":"B.L9","kapitel":"Motivation","q":"Erläutere den Unterschied zwischen Motivation und Volition.","a":"• Motivation: vor der Entscheidung – Zielwahl durch Abwägen von Anreizen und Erfolgsaussichten\n• Volition (Wille): nach der Entscheidung – Umsetzung trotz Hindernissen (Selbstkontrolle, Abschirmen)\n(Rubikon-Modell, Heckhausen & Gollwitzer)","e":"Motivation bringt dich zum Entschluss, Volition zieht es durch. Mit der Entscheidung wird der „Rubikon“ überschritten. Volition ist besonders nötig, wenn die Tätigkeit selbst wenig Anreiz bietet (z. B. unangenehmes Training) oder konkurrierende Wünsche ablenken. Beispiel: Jörg will den Marathon unter vier Stunden laufen (Motivation); dass er auch bei Regen, Kälte oder Hitze im Urlaub läuft, „manchmal mit Überwindung“, ist Volition.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"bonus.a-090","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Definiere Emotionen (nach Gabler) und nenne ihre Funktionen in sportlichen Handlungssituationen.","a":"• Emotionen = subjektive Befindlichkeiten, verbunden mit Bewertung der Situation, physiologischer Erregung und Verhaltensimpulsen\n• Funktionen: vorbereitend, signalisierend, organisierend, kontrollierend","e":"Emotionen sind mehr als Gefühle: Sie umfassen Bewertung, Körperreaktion und Handlungsimpuls. Sie sind nicht nur Produkt, sondern auch Triebfeder dauerhafter sportlicher Aktivität. Beispiel: Der Ärger über eine Schiedsrichterentscheidung im Fechten zeigt sich im Denken („unfair!“), im Körper (Puls steigt) und im Impuls (Protestgeste).","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-091","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Was sind Kognitionen, und wie hängen Emotionen, Kognitionen und physiologische Erregung zusammen?","a":"• Kognitionen = alle Prozesse des Wahrnehmens, Denkens, Erkennens, Vorstellens, Erinnerns, Sprechens (Gabler)\n• regulieren die Emotionalität\n• Erregung treibt Emotionen an, Kognitionen geben die Richtung (Myers)","e":"Erregung ist das Gaspedal, Kognition das Lenkrad. Risiken müssen erkannt und mit dem eigenen Können abgewogen werden; nur ein gelungenes Zusammenspiel von Emotionen und Kognitionen sichert freudvolles Sporttreiben. Beispiel: Max steht auf dem 10-m-Turm, sein Herz rast (Erregung); ob er das als Angst oder Vorfreude erlebt und ob er springt, entscheidet seine Einschätzung der Situation (Kognition).","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-092","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Nenne und erläutere die fünf Komponenten des Konstrukts Emotion (nach Gabler).","a":"• kognitiv: Deutung der Situation\n• subjektives Erleben: das Gefühl\n• physiologisch: (De-)Aktivierung (Puls, Atmung, Muskeltonus)\n• Ausdruck: Mimik, Gestik, Stimme, Haltung\n• motorisches Verhalten: z. B. Abwehrbewegungen","e":"Beispiel Max am 10-m-Turm: Er denkt an Verletzungsgefahr (kognitiv), fühlt Angst und später Stolz (subjektiv), hat Herzrasen und Schweiß (physiologisch), ist bleich und kann kaum sprechen (Ausdruck) und weicht unwillkürlich vom Rand zurück (motorisch).","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-093","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Unterscheide Affekte, Gefühle und Stimmungen.","a":"Nach Intensität, Dauer, Qualität:\n• Affekte: sehr intensiv, kurz, kaum kontrollierbar\n• Gefühle: mittelfristig, Intensität variabel\n• Stimmungen: Tage bis Wochen, im Hintergrund","e":"Affekt = Explosion, Gefühl = Welle, Stimmung = Wetterlage. Stimmungen schwingen im Hintergrund mit und können aktuelle Handlungen beeinflussen. Beispiel: Ein Wutausbruch nach einer Roten Karte ist ein Affekt, die Vorfreude auf das Spiel ein Gefühl, die gedrückte Laune nach einer Niederlagenserie eine Stimmung.","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-094","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Bewerte kritisch die Einteilung von Emotionen in positive und negative Emotionen.","a":"• Einteilung: positiv (Freude, Stolz) vs. negativ (Ärger, Trauer, Angst) (Alfermann & Stoll)\n• Kritik: Zuordnung ist personen- und situationsabhängig (Angstlust, Freudentränen)\n• „negative“ können leistungsfördernd, „positive“ leistungsmindernd sein","e":"Ob eine Emotion gut oder schlecht ist, hängt davon ab, wer sie wann erlebt; sie kann vor, während und nach der Aktivität auftreten. Angst kann signalisieren und aktivieren, Freude kann überaktivieren oder leichtsinnig machen. Beispiel: Für einen Fallschirmspringer ist das Kribbeln der Angst genau das, was er sucht.","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-095","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Definiere Angst (Zustandsangst) und nenne typische bedrohliche Situationen im Sport.","a":"• Zustandsangst = momentaner Zustand von Bedrohung und Spannung mit körperlicher Aktivierung in als bedrohlich bewerteten Situationen (Weinberg & Gould)\n• Angst vor: Leistungsversagen, sozialer Blamage, Überforderung","e":"Angst entsteht, wenn man eine Situation als bedrohlich bewertet (State Anxiety). Die drei typischen Bedrohungen im Sport nennen Hackfort & Schwenkmezger. Beispiel: Eine Turnerin fürchtet beim Handstützüberschlag am Kasten, hängenzubleiben (Überforderung) und vor der Klasse ausgelacht zu werden (Blamage).","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-096","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Unterscheide Zustandsangst und Eigenschaftsangst und erläutere das State-Trait-Angst-Modell nach Spielberger.","a":"• State: momentaner Angstzustand\n• Trait (Ängstlichkeit): stabile Disposition, Situationen als bedrohlich zu bewerten\n• Spielberger: Trait beeinflusst State; hoch Ängstliche reagieren eher mit Zustandsangst","e":"Trait ist der Charakterzug, State der aktuelle Zustand. Bei hoch Ängstlichen lässt sich die Zustandsangst durch viele Vorerfahrungen mit der Situation und psychologische Trainingsverfahren (z. B. mentales Training) senken. Beispiel: Zwei Spieler stehen vor dem entscheidenden Siebenmeter; der grundsätzlich ängstliche Spieler bekommt viel stärkeres Herzklopfen als sein gelassener Mitspieler.","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-097","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Welche unterrichtlichen Maßnahmen können Ängste bei der Vermittlung turnerischer Fertigkeiten (z. B. Handstützüberschlag am Kasten) reduzieren?","a":"• kleine Gruppen, vertraute Partner (wenig Zuschauerdruck)\n• sichere Hilfe-/Sicherheitsstellung, Weichböden\n• methodische Reihe, Wahlmöglichkeiten, kein Zwang\n• reduziertes Tempo/Anlauf\n• mentales Training, positive Rückmeldung","e":"Angst sinkt, wenn die Situation kontrollierbar und überschaubar wirkt. Kurze Wartezeiten mindern die Angst vor Blamage; Vorübungen auf niedrigem Kasten oder Mattenberg sichern Erfolgserlebnisse; das Tempo wird erst bei Sicherheit gesteigert. Erfolge sollten auf das eigene Können zurückgeführt werden. Beispiel: Erst über einen Mattenberg mit Hilfestellung rollen, dann auf den Kasten, und erst wenn das sicher klappt, mit vollem Anlauf.","quelle":"L9.3","typ":"zusatz"},{"id":"bonus.a-098","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Nenne und erläutere die vier Funktionen von Emotionen im sportbezogenen Handeln (nach Hackfort & Birkner).","a":"• Vorbereitung: Aktivierung von Herz-Kreislauf, Hormonen, Muskulatur\n• Signal: anderen etwas mitteilen\n• Organisation: Wahrnehmung und Bewegung koordinieren (Flow)\n• Kontrolle: Handlung überwachen/korrigieren","e":"Eselsbrücke „V-S-O-K“. Bei der Vorbereitung steigen z. B. Herz- und Atemfrequenz, Adrenalin wird ausgeschüttet, Muskeltonus und Durchblutung nehmen zu. Zur Kontrolle: Ein „ungutes Gefühl“ kann zu einer erfolgreichen Bewegungskorrektur führen. Beispiel: Vor dem 100-m-Lauf aktiviert die Anspannung die Muskulatur (Vorbereitung), die Sprinterin nickt ihrer Trainerin lächelnd zu (Signal).","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-099","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Welche Auswirkungen kann die Aktivierung durch Emotionen auf die sportliche Leistung haben (Vorstartnervosität)?","a":"• Kraft/Schnelligkeit (Sprint, Gewichtheben): hohe Aktivierung leistungsbestimmend\n• Überaktivierung (Vorstartnervosität): vorzeitige Erschöpfung, fehlende gezielte Aktivierung\n• Feinmotorik (Golf, Schießen): Deaktivierung förderlich","e":"Zu viel Aufregung schadet, besonders bei Präzisionsaufgaben. Überaktivierung kann durch zu große Angst oder Freude entstehen: Die Muskulatur ist schon vor dem Anreißen des Gewichts erschöpft, oder der Start kommt zu spät. Zufriedenheit wirkt dagegen beruhigend. Beispiel: Ein Sprinter ist so nervös, dass er schon vorher verkrampft und den Startschuss verpasst; ein Golfer profitiert dagegen von innerer Ruhe beim Putt.","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-100","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Erläutere die Yerkes-Dodson-Hypothese (umgekehrte U-Funktion).","a":"• Höchste Leistung bei mittlerer Erregung (umgekehrtes U)\n• zu geringe/zu hohe Erregung → Leistungsminderung\n• Optimum abhängig von Aufgabe und Person (Gewichtheben hoch, Schießen niedrig)","e":"Nicht zu schlapp, nicht zu aufgedreht, die Mitte ist optimal. Bei Kraftaufgaben ist die Kurve nach rechts verschoben, bei Präzisionsaufgaben braucht es eine ruhige Hand und Konzentration. Beispiel: Gewichtheber schreien sich vor dem Versuch gegenseitig an, um hochzufahren; ein Schütze würde dadurch nur zittern.","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-101","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Erläutere das IZOF-Modell nach Hanin und grenze es von der Yerkes-Dodson-Hypothese ab.","a":"• IZOF (Hanin): höchste Leistung in einer individuellen, situationsabhängigen Zone der Erregung (niedrig, mittel oder hoch)\n• Abgrenzung: Yerkes-Dodson pauschal mittlere Erregung (ein Punkt), ohne individuelle/situative Unterschiede","e":"Jeder hat seine eigene Wohlfühlzone der Aufregung; außerhalb liegt geringere Leistung. Yerkes-Dodson wurde gerade deshalb scharf kritisiert. Gemeinsam ist beiden: Verschiebt sich das Gleichgewicht und bewertet man die Situation als die eigenen Fähigkeiten übersteigend, entstehen Stress oder Angst. Beispiel: Eine Handballtorhüterin bringt ihre beste Leistung, wenn sie richtig aufgedreht ist, ihre Mitspielerin dagegen nur, wenn sie eher ruhig ist.","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-102","thema":"B.L9","kapitel":"Emotionen & Angst","q":"Wann entstehen nach Alfermann & Stoll Stress bzw. Angst im Zusammenhang mit Aktivierung?","a":"• Wenn sich das Aktivierungsgleichgewicht verschiebt (modellunabhängig)\n• und der Sportler die Situation so bewertet, dass seine Fähigkeiten überschritten werden","e":"Entscheidend ist die Bewertung: Anforderungen größer als meine Fähigkeiten = Stress. Beispiel: Eine Schwimmerin, die glaubt, im Finale chancenlos zu sein, erlebt Stress; dieselbe Situation empfindet eine Favoritin als Herausforderung.","quelle":"L9.3","typ":"kern"},{"id":"bonus.a-103","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Welche Motive erklären das Betreiben von Risikosport?","a":"• Hauptmotive: Angstlust (thrill), Reizsuchverhalten (sensation seeking)\n• Mensch als wagendes, neugieriges Wesen\n• weitere (Kuhn): Leistung, Glück, Verausgabung, Katharsis („Probleme vergessen“)","e":"Risikosportler suchen intensive Reize, Flow, Grenzsituationen, außergewöhnliche Emotionen, Selbstbestätigung und Selbsterprobung, und sie wollen diese Erlebnisse wiederholen. Beispiel: Ein Kletterer genießt die Spannung an der Felswand, ist stolz auf die geschaffte Route und vergisst dabei allen Alltagsstress.","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-104","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Was versteht man unter Angstlust (thrill), und welche Merkmale haben Aktivitäten, in denen sie verspürt wird?","a":"• Angstlust = lustvolles Erleben von Angst/Nervenkitzel in gefährlichen Situationen\n• Merkmale: objektive Gefahr, freiwillig, mit hoher Wahrscheinlichkeit bewältigt","e":"Angstlust ist die Mischung aus „Hilfe!“ und „Geil!“, typisch bei hohen Geschwindigkeiten (Rennsport) oder Grenzsituationen (Klettern). Menschen reagieren unterschiedlich: Manche genießen das Aufgeben der Sicherheit, andere erleben Unbehagen und Angst (Allmer). Beispiel: Beim Bungee-Sprung ist die Gefahr real, man springt freiwillig und weiß, dass das Seil einen höchstwahrscheinlich hält.","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-105","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Erläutere die Reversionstheorie nach Apter.","a":"• Wechsel (reversal) zwischen Aufregungssuche und Angstvermeidung\n• hohe Erregung: Aufregung (angenehm) oder Angst\n• niedrige Erregung: Entspannung (angenehm) oder Langeweile\n• Entscheidend ist die Interpretation, nicht die Höhe","e":"Herzklopfen ist nicht automatisch Angst, es kommt auf die Brille an, durch die man es sieht; dieselbe Situation kann bei verschiedenen Personen Lust oder Unlust auslösen. Beispiel: In der Achterbahn schreit die eine vor Freude, der andere vor Panik, obwohl beide gleich hohe Erregung haben.","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-106","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Beschreibe die drei Zonen nach Apter und die Rolle des schützenden Rahmens.","a":"• Zonen: Sicherheits-, Gefahren-, Traumazone\n• Nervenkitzel braucht Risiko plus Gefühl eines schützenden Rahmens (fehlt bei Angstvermeidung)\n• Abenteuerlustige: stabilerer Rahmen durch mehr Vertrauen","e":"Nervenkitzel entsteht nur, wenn man sich trotz Gefahr irgendwie sicher fühlt; Abenteuerlustige vertrauen stärker auf das, was ihnen Sicherheit verspricht (vgl. Kohärenzgefühl). Der Übergang zwischen Gefahren- und Traumazone ist der „gefährliche Grat“. Beispiel: Ein erfahrener Kletterer vertraut Seil, Partner und eigenem Können (schützender Rahmen) und genießt die Höhe; ein Anfänger ohne dieses Vertrauen erlebt dieselbe Wand als Angst.","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-107","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Was versteht man unter Reizsuchverhalten (Sensation Seeking)?","a":"• Suche nach starken Reizen und stimulierenden Erlebnissen (Persönlichkeitsmerkmal)\n• eher bei Tätigkeitsorientierten: Anreiz liegt im Vollzug selbst, kein äußerer Zweck","e":"Sensation Seeker machen etwas um des Erlebens willen, nicht für ein Ziel danach; sie investieren viel Geld, Zeit und Anstrengung in oft teure Sportarten (Krieger & Roschmann; Apter). Beispiel: Eine Drachenfliegerin gibt viel Geld für Ausrüstung und Reisen aus, nur um das Gefühl des Fliegens zu erleben.","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-108","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Unterscheide tätigkeitsorientierte und zweckorientierte Anreize.","a":"• Tätigkeitsorientiert: Anreiz im Vollzug der Tätigkeit selbst (intrinsisch)\n• Zweckorientiert: Anreiz in einer Folge außerhalb der Tätigkeit (Gesundheit, Anerkennung, Geld)","e":"Tätigkeit: Der Weg ist das Ziel; typisch für Sensation Seeker und Flow. Zweck: Das Ziel ist das Ziel. Beispiel: Silke spielt Beachvolleyball aus Spaß am Spiel (tätigkeitsorientiert), Jörg läuft, um den Marathon unter vier Stunden zu schaffen und gesund zu bleiben (zweckorientiert).","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-109","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Wer entwickelte das Flow-Konzept, und welche sechs Komponenten des Flow-Erlebens werden unterschieden?","a":"Csikszentmihalyi (1975); Komponenten:\n• optimale Beanspruchung (Passung, Kontrolle)\n• klare Anforderungen und Rückmeldungen\n• flüssige Handlungsabläufe\n• zwanglose Konzentration\n• verändertes Zeitgefühl\n• Verschmelzung von Selbst und Tätigkeit","e":"Flow ist der Zustand, in dem alles „wie von selbst“ läuft (Komponenten nach Rheinberg & Vollmeyer). Man weiß ohne Nachdenken, was zu tun ist, ein Schritt geht in den nächsten über, Konzentration kommt wie die Atmung, Stunden vergehen wie Minuten. Beispiel: Roger Federer beschrieb, dass sein Schläger wie die Verlängerung seines Arms wirkte, er immer genug Zeit hatte und alles spielerisch leicht lief, ohne Gefühl übermäßiger Anstrengung.","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-110","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Wie kommt es zu einem Flow-Erleben (optimale Erfahrung), und was geschieht bei Über- bzw. Unterforderung?","a":"• Flow bei Gleichgewicht von wahrgenommenen Anforderungen und eigenen Fähigkeiten\n• Überforderung → Angst\n• Unterforderung → Langeweile\n• zurück: Können verbessern bzw. Anforderungen erhöhen","e":"Flow liegt im Kanal zwischen Angst und Langeweile. Das Gleichgewicht ist nicht absolut, sondern ein Spannungszustand zwischen aktuell wahrgenommener Herausforderung und Können. Beispiel aus dem Buch: Eine Anfängerfechterin besiegt alle (Freude, A1), verliert gegen eine starke Gegnerin (Angst, A2), trainiert, langweilt sich dann gegen Gleichaltrige (A3) und erlebt gegen eine ältere Gegnerin wieder Flow (A4).","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-111","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Wie kann sich die Organisationsfunktion von Emotionen im Flow zeigen, und welche Bedeutung hat Flow für Risikosport und Tanz?","a":"• Organisationsfunktion: Emotionen koordinieren Wahrnehmung und Bewegung → flüssige, automatische Handlungen\n• Risikosport: hohe Herausforderung + hohes Können → Flow als gesuchte Belohnung\n• Tanz: Ziel der Improvisation (Sich-gehen-Lassen)","e":"Flow verbindet viele Themen: Gestaltung, Wagnis und Motivation. Im Risikosport erklärt er, warum Menschen die Situation immer wieder aufsuchen; im Tanz lösen sich im Flow Zeit und Raum auf. Beispiel: Ein Freerider im Tiefschnee fährt am Limit, aber mit voller Kontrolle; er ist so konzentriert, dass er alles um sich vergisst, und will genau dieses Gefühl immer wieder erleben.","quelle":"L9.4","typ":"kern"},{"id":"bonus.a-112","thema":"B.L9","kapitel":"Flow & Angstlust","q":"Woran erkennt man, dass ein Sportler sich im Flow-Zustand befindet (z. B. anhand von Selbstbeschreibungen)?","a":"Aussagen den Komponenten zuordnen:\n• „völlige Kontrolle“ → optimale Beanspruchung\n• „wusste genau, was zu tun ist“ → klare Anforderungen\n• „fließend“ → glatter Ablauf\n• „alles andere egal“ → zwanglose Konzentration\n• „viel Zeit“ → Zeitgefühl\n• „Schläger als Armverlängerung“ → Verschmelzung","e":"Man ordnet die Selbstbeschreibungen des Sportlers den sechs Flow-Komponenten zu; weitere Hinweise sind z. B. „unschlagbar“, „Rhythmus“, „wie ferngesteuert“ oder „in sich versunken“. Beispiel: Federers Satz, Ausholbewegung und Ballflug seien „nur noch das Resultat meiner Gedanken“ gewesen, zeigt Verschmelzung von Selbst und Tätigkeit und glatte Handlungsabläufe.","quelle":"L9.5","typ":"kern"},{"id":"bonus.a-113","thema":"B.L7","kapitel":"Vermittlung im Tanz","q":"Arbeite Zusammenhänge zwischen den Improvisationsgraden und dem KAR-Modell nach Neumaier heraus.","a":"• Höherer Improvisationsgrad → mehr Situations-, Zeit-, Komplexitätsdruck und Informationsanforderungen\n• Imitation: v. a. Präzisionsdruck\n• Methodik: Improvisationsgrad = Druckbedingungen schrittweise steigern","e":"Je freier man tanzt, desto mehr muss man gleichzeitig wahrnehmen und spontan entscheiden: Der Ablauf ist unvorhersehbar (Situation), Entdecken und Ausführen fallen zusammen (Zeit), viele Elemente werden neu kombiniert (Komplexität). Gefordert sind v. a. optische, akustische (Musik), taktile (Partner), kinästhetische und vestibuläre Informationen. Beispiel: Spiegeln einer Partnerin verlangt vor allem Präzision; eine ungeplante Kontaktimprovisation verlangt schnelles Reagieren auf taktile Impulse in unvorhersehbaren Situationen.","quelle":"L7.3","typ":"zusatz"},{"id":"bonus.a-114","thema":"B.L8","kapitel":"Wagnis & Risiko","q":"Erläutere am Beispiel Freesolo-Klettern (ohne Sicherung) den Unterschied zwischen Risiko- und Wagnisperspektive.","a":"• Risiko (objektiv): Sturzwahrscheinlichkeit × Schaden (tödlich) → extrem riskant\n• Wagnis (subjektiv): Anforderung vs. Können; weit unter dem eigenen Niveau kontrollierbar\n• Kritik: subjektive Einschätzung kann täuschen","e":"Von außen sieht man nur die Gefahr, von innen zählt das Können. Es gibt eine persönliche Leistungsgrenze für Freesolo; Laien überschätzen das Risiko oft, die Vermarktung nährt das. Andererseits drohen gelernte Sorglosigkeit, Steigerungsspirale und Gladiatorenkomponente. Beispiel: Ein Kletterer im Forum meint, solo eine leichte Route sei für ihn nicht riskanter als mit Seil; ein anderer hält dagegen, das gelte nur weit unter dem eigenen Niveau.","quelle":"L8.4","typ":"kern"},{"id":"bonus.b-001","thema":"B.L15","kapitel":"Beweglichkeit","q":"Definiere den Begriff Beweglichkeit (Flexibilität).","a":"Fähigkeit, willkürliche Bewegungen mit großer bzw. optimaler Schwingungsweite (Bewegungsamplitude) in bestimmten Gelenken auszuführen.\n• Komponenten: Dehnfähigkeit und Gelenkigkeit","e":"Beweglichkeit sagt, wie weit du ein Gelenk bewegen kannst, ohne dass dich Muskeln oder Knochen bremsen. Man unterscheidet sie in drei Kategorien: allgemein/speziell, aktiv/passiv und statisch/dynamisch. Beispiel: Eine Hürdenläuferin muss das Schwungbein weit nach vorne bringen können, eine Turnerin braucht für den Spagat eine große Schwingungsweite im Hüftgelenk.","quelle":"L15.1","typ":"kern"},{"id":"bonus.b-002","thema":"B.L15","kapitel":"Beweglichkeit","q":"Erläutere den Unterschied zwischen Dehnfähigkeit und Gelenkigkeit als Komponenten der Beweglichkeit.","a":"• Dehnfähigkeit: Dehnbarkeit des tendomuskulären Systems (Muskeln, Sehnen, Bänder, Gelenkkapseln); trainierbar\n• Gelenkigkeit: Bau und Funktion der knöchernen Gelenkstrukturen; weitgehend anatomisch vorgegeben","e":"Stell dir ein Gelenk wie eine Tür vor: Die Gelenkigkeit ist das Scharnier (wie weit es überhaupt aufgehen kann), die Dehnfähigkeit sind die Gummibänder, die die Tür zurückhalten. Beispiel: Wer im Sitzen nicht an die Zehen kommt, scheitert meist an der Dehnfähigkeit der hinteren Oberschenkelmuskulatur, nicht am Hüftgelenk selbst.","quelle":"L15.1","typ":"kern"},{"id":"bonus.b-003","thema":"B.L15","kapitel":"Beweglichkeit","q":"Nenne und erläutere die drei Unterscheidungskategorien der Beweglichkeit.","a":"• Allgemein (wichtigste Gelenksysteme) vs. speziell (sportartspezifische Gelenke)\n• Aktiv (eigene Muskelkraft des Antagonisten) vs. passiv (äußere Kräfte: Partner, Schwerkraft, Gerät)\n• Statisch (Dehnstellung halten) vs. dynamisch (federnd)","e":"Die drei Paare kann man frei kombinieren, so entstehen Mischformen wie aktiv-statisch oder passiv-dynamisch. Beispiel: Ein Hürdenläufer braucht spezielle Beweglichkeit im Hüftgelenk; wenn er sein Bein ohne Hilfe hoch hält, ist das aktiv-statisch, wenn der Trainer es hochdrückt, passiv.","quelle":"L15.1","typ":"kern"},{"id":"bonus.b-004","thema":"B.L15","kapitel":"Beweglichkeit","q":"Erläutere die vier Mischformen der Beweglichkeit (aktiv/passiv kombiniert mit statisch/dynamisch).","a":"• Passiv-statisch: Dehnposition durch äußere Kräfte einnehmen und halten\n• Aktiv-statisch: Dehnposition durch eigene Muskelkraft einnehmen und halten\n• Aktiv-dynamisch: federnd, nur durch eigene Muskelkraft\n• Passiv-dynamisch: federnd, von außen unterstützt","e":"Äußere Kräfte sind z. B. Gewichtskraft oder ein Partner; beim aktiv-statischen Dehnen wird die Position über mehrere Sekunden gehalten. Das Buch erklärt das an einer Turnerin: Spagat im Stand, in den sie durch ihr Gewicht sinkt = passiv-statisch; Spagat im Handstand halten = aktiv-statisch; federnd zwischen Handstand und Spagat wechseln = aktiv-dynamisch; dasselbe mit Hilfe der Trainerin = passiv-dynamisch.","quelle":"L15.1","typ":"kern"},{"id":"bonus.b-005","thema":"B.L15","kapitel":"Beweglichkeit","q":"Wie verhalten sich aktive und passive Beweglichkeit zueinander? Begründe.","a":"Passive Beweglichkeit ist immer größer als aktive.\n• Grund: äußere Kräfte (Partner, Schwerkraft) können stärker sein als der eigene Antagonist\n• Differenz = Bewegungsreserve, abhängig v. a. von der Antagonistenkraft","e":"Mit Hilfe kommt man immer weiter als allein. Weil die Bewegungsreserve von der Kraft der Antagonisten abhängt, beeinflussen sich Kraft und Beweglichkeit gegenseitig. Beispiel: Du kannst dein gestrecktes Bein im Liegen vielleicht aktiv auf 70° heben, mit einem Partner, der nachdrückt, aber auf 90°. Wer die Oberschenkelvorderseite kräftigt, kann die Lücke verkleinern.","quelle":"L15.1","typ":"kern"},{"id":"bonus.b-006","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Was ist das Hauptziel des Dehnens?","a":"Muskeltonus senken, um:\n• Bewegungsausschlag zu vergrößern\n• Muskel dehnfähiger, elastischer, verletzungsresistenter zu machen\n• ökonomischen Energieumsatz zu ermöglichen","e":"Ein angespannter Muskel ist wie ein straff gespanntes Seil: Er lässt wenig Bewegung zu. Sinkt die muskuläre Anspannung, wird die Schwingungsweite in den Gelenken größer und die Muskelarbeit ökonomischer. Beispiel: Ein Speerwerfer braucht vor dem Abwurf eine große Vordehnung der Brust- und Schultermuskulatur; ist die Muskulatur zu angespannt, verliert er Amplitude und damit Wurfweite.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-007","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Definiere den Muskeltonus und erkläre, wie er gesteuert wird und warum er für die Beweglichkeit bedeutsam ist.","a":"• Muskeltonus: Grundspannung der Muskulatur, abhängig von der neuronalen Aktivierung\n• Steuerung: ZNS über Muskelspindeln (Innervation von mehr/weniger Muskelfasern)\n• Bedeutung: hoher Tonus erhöht den Dehnwiderstand → geringere Beweglichkeit","e":"Der Muskeltonus ist sozusagen der Leerlauf des Muskels: Auch in Ruhe ist er nie ganz aus, er ist z. B. für aufrechtes Stehen nötig. Ein erhöhter Tonus bzw. verminderte Entspannungsfähigkeit mindert die Leistung v. a. in Sportarten, die vor maximal schnellkräftigen Bewegungen eine gute Vordehnung brauchen (Speer-, Diskuswurf). Beispiel: Nach einem stressigen Klausurtag sind Nacken und Schultern verspannt; dann kommt man beim Dehnen deutlich weniger weit als nach einem warmen Bad.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-008","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Nenne Faktoren, die den Muskeltonus erhöhen bzw. senken (Abb. 15.1).","a":"Erhöhend: intensive Belastung, Stress/aufputschende Umgebung, psychische Erregung, Ermüdung, Kälte\nSenkend: Massage, Wärme/warme Bäder, autogenes Training, Meditation/Entspannung, Schlaf/Ruhe","e":"Ein erhöhter Tonus mindert die Beweglichkeit, ein gesenkter steigert sie. Faustregel: Alles, was dich aufregt, kalt oder müde macht, spannt die Muskeln an; alles, was dich wärmt und beruhigt, entspannt sie. Beispiel: Vor einem Finale ist ein Sprinter nervös und friert in der Startzone, seine Muskeln sind dadurch fester als im ruhigen Training an einem warmen Tag.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-009","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Welche Reflexe bestimmen, welchen Widerstand ein Muskel seiner Dehnung entgegensetzt?","a":"• Dehnungsreflex der Muskelspindeln (Muskelspindelreflex)\n• Autogene Hemmung durch die Golgi-Sehnenorgane\n• ergänzend: reziproke Antagonistenhemmung und -erregung","e":"Zusammen regeln diese Reflexe Länge und Spannung des Muskels und damit seinen Dehnwiderstand. Im Muskel sitzen zwei Messfühler: einer für die Länge, einer für die Spannung. Beispiel: Wenn du ruckartig in eine Dehnung wippst, meldet die Muskelspindel Gefahr und der Muskel zieht sich zusammen, statt nachzugeben.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-010","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Beschreibe Lage, Funktion und Reflex der Muskelspindeln (Muskelspindelreflex).","a":"• Lage: in der Muskelfaser\n• Funktion: Längenrezeptoren, messen Dehnungsgrad\n• Reflex: Dehnung → Erregung über sensorischen Nerv ins Rückenmark → motorischer Nerv → Kontraktion des gedehnten Agonisten\n• Aufgaben: Tonusregulation, Schutz vor Überdehnung","e":"Die Muskelspindel ist der Längenwächter: Bei Dehnung geben erst die kontraktilen Elemente nach, dann werden die Spindeln gedehnt und lösen den Reflex aus, unterstützt durch die reziproke Antagonistenhemmung. Dadurch begrenzen sie indirekt auch die Dehnfähigkeit. Beispiel: Beim Patellarsehnenreflex schlägt der Arzt unter die Kniescheibe, der Oberschenkelstrecker wird kurz gedehnt und nach etwa 40 Millisekunden schnellt der Unterschenkel nach vorne.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-011","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Erkläre die reziproke Antagonistenhemmung.","a":"Kontrahiert der Agonist reflektorisch (Muskelspindelreflex), wird gleichzeitig der Antagonist gehemmt.\n• unterstützt die Längenkontrolle\n• Nutzung beim Dehnen: Antagonist anspannen → Zielmuskel wird gehemmt","e":"Wenn ein Muskel arbeitet, bekommt sein Gegenspieler automatisch das Signal: Halt dich raus. So kann der Agonist ungestört auf die Dehnung reagieren. In der Dehnmethodik nutzt man das, indem man den Antagonisten anspannt, damit der zu dehnende Muskel nachgibt. Beispiel: Beim Patellarsehnenreflex streckt sich der Oberschenkelstrecker, und gleichzeitig wird die Oberschenkelrückseite gehemmt, damit sie nicht dagegenhält.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-012","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Beschreibe Lage, Funktion und Reflex der Sehnenspindeln (Golgi-Sehnenorgane).","a":"• Lage: Übergang Muskel–Sehne bzw. in der Sehne\n• Funktion: Spannungsrezeptoren\n• Reflex: bei maximaler Kontraktion/starker Dehnung autogene Hemmung (Agonist erschlafft) + reziproke Antagonistenerregung\n• höhere Reizschwelle als Muskelspindeln","e":"Die Sehnenspindel ist die Notbremse: Wird die Spannung gefährlich hoch, schaltet sie den Muskel ab, bevor die Sehne reißt. Der Antagonist kontrahiert zusätzlich und senkt die Dehnungsspannung im Agonisten. Wegen der hohen Reizschwelle greift sie nur bei erheblicher Dehnung. Beispiel: Beim Gewichtheben kann ein Athlet eine zu schwere Last plötzlich fallen lassen, weil der Muskel reflektorisch nachgibt.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-013","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Erkläre den Mechanismus der autogenen Hemmung am Beispiel des Umknickens im Sprunggelenk.","a":"• Seitliche Unterschenkelmuskeln kontrahieren maximal, Kraft reicht nicht\n• Sehnenspindeln melden extreme Spannung → autogene Hemmung (+ reziproke Antagonistenerregung): Muskel erschlafft\n• Folge: Außenbandriss statt Sehnen-/Muskelabriss","e":"Ohne die Hemmung droht ein Muskel- oder Sehnenabriss. Der Körper opfert lieber das Band, weil ein Bänderriss ausheilt, ein Sehnen- oder Muskelabriss aber bleibende Funktionseinschränkungen verursachen würde. Je nach Krafteinwirkung reißen die Außenbänder teilweise oder komplett. Beispiel: Eine Basketballerin landet nach dem Rebound auf dem Fuß einer Gegnerin; die Muskeln geben schlagartig nach, und statt eines Sehnenabrisses gibt es einen Außenbandriss, der nach einigen Wochen verheilt.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-014","thema":"B.L15","kapitel":"Biologische Grundlagen","q":"Vergleiche Muskelspindeln und Sehnenspindeln hinsichtlich Funktion und ausgelöster Reflexe (Tab. 15.1).","a":"Muskelspindeln: Längenkontrolle; bei Dehnung → Agonist kontrahiert (Muskelspindelreflex), Antagonist gehemmt\nSehnenspindeln: Spannungskontrolle; bei starker Dehnung/max. Kontraktion → Agonist gehemmt (autogene Hemmung), Antagonist kontrahiert","e":"Eselsbrücke: Muskelspindel = Muskel macht zu (Kontraktion), Sehnenspindel = Sehne schützt, Muskel lässt los (Hemmung). Beispiel: Wippendes Dehnen weckt die Muskelspindeln (Muskel wird fester), eine maximale Anspannung vor dem Dehnen soll dagegen die Sehnenspindeln reizen, damit der Muskel danach lockerer wird.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-015","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Nenne die erreichbaren (gesicherten) Trainingswirkungen von Beweglichkeitstraining.","a":"• Erhaltung/Verbesserung der Beweglichkeit\n• Wohlbefinden und Körpergefühl\n• Wiederherstellung nach Verletzungen\n• optimale Voraussetzungen für Leistung in Training und Wettkampf\n(Klee & Wiemann)","e":"Dehnen kann weniger, als oft behauptet wird, aber diese vier Dinge sind wissenschaftlich gesichert. Der Leistungsvorteil gilt nur bei angemessener, sportspezifischer Anwendung. Beispiel: Nach einer Knieoperation hilft gezieltes Beweglichkeitstraining, das Knie wieder voll beugen zu können.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-016","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Nenne die nicht erreichbaren Trainingswirkungen von Beweglichkeitstraining.","a":"• Senkung der akuten Verletzungsgefahr\n• Absenken der Muskelspannung\n• bessere Entspannungsfähigkeit\n• Behebung muskulärer Dysbalancen/Verkürzungen","e":"Viele dieser angenommenen Stretching-Wirkungen wurden mit der Aufklärung der Funktion des Titinmoleküls widerlegt; die Mythen halten sich trotzdem hartnäckig. Beispiel: Der Fußballtrainer, der vor dem Spiel lange statisch dehnen lässt, damit sich niemand verletzt, erreicht damit laut Forschung keinen Verletzungsschutz, sondern eher eine schwächere Schnellkraft.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-017","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Welche Rolle spielt das Titinmolekül für die Bewertung des Stretchings?","a":"Titin: elastisches Riesenprotein im Sarkomer, das den Muskel nach Dehnung in die Ausgangslänge zurückführt.\n• widerlegt viele Stretching-Wirkungen (z. B. dauerhafte Muskelverlängerung) (Klee & Wiemann)","e":"Titin wirkt im Muskel wie eine eingebaute Feder: Zieht man den Muskel lang, schnurrt er danach wieder auf seine Länge zurück. Deshalb beseitigt passiv-statisches Stretching keine Verkürzungen dauerhaft. Beispiel: Ein Gummiband, das man 30 Sekunden dehnt, ist danach nicht dauerhaft länger, ähnlich verhält es sich mit dem Muskel.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-018","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Erläutere den Zusammenhang zwischen Dehnen und Verletzungsprophylaxe.","a":"• Kurzfristig: Dehnen ungeeignet zur Verletzungsvorbeugung\n• Langfristig: Bindegewebe wird zugfester und belastungsresistenter\n• Merksatz: Verletzungsvorbeugung nur durch Langzeit-Dehnprogramme","e":"Die Muskelspannungen beim Dehnen übersteigen oft die Anforderungen der Sportart und begünstigen eher Verletzungen. Beweglichkeitstraining sollte daher ein eigenständiger Trainingsinhalt sein, nicht gewohnheitsmäßiger Teil des Aufwärmens. Beispiel: Eine Handballerin, die dreimal pro Woche separat 20 Minuten Beweglichkeitstraining macht, stärkt ihr Bindegewebe; fünf Minuten Stretching vor dem Spiel bringen dagegen keinen Schutz.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-019","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Welche Dehnmethode ist für Spielsportler die Methode der Wahl? Begründe.","a":"Aktiv-dynamisches Dehnen.\n• keine Einbußen bei Schnelligkeit/Schnellkraft (anders als Stretching)\n• entspricht dem dynamischen Bewegungsprofil der Sportspiele","e":"Passiv-statisches Stretching beeinträchtigt unmittelbar folgende Schnelligkeits- und Schnellkraftleistungen merklich; das lässt sich nur durch tonisierende Übungen abmildern. Im Spiel wird der Muskel fast ausschließlich dynamisch gedehnt, also sollte man ihn auch so vorbereiten. Merksatz: Kein statisches Dehnen im Aufwärmen und vor maximalen Belastungen! Beispiel: Basketballer machen beim Aufwärmen Beinschwünge und Ausfallschritte statt lange Dehnpositionen zu halten, damit ihre Sprungkraft beim Anpfiff voll da ist.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-020","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Erläutere, warum Dehnen muskuläre Dysbalancen nicht behebt und was stattdessen getan werden sollte.","a":"• Dehnen beseitigt vermeintliche Verkürzungen nicht dauerhaft → keine Behebung von Dysbalancen\n• Stattdessen: schwachen Muskel (meist Antagonist) kräftigen (Klee & Wiemann)","e":"Eine Dysbalance ist ein Kräfteungleichgewicht, und das lässt sich nur mit Kraft ausgleichen. Merksatz: Dehnen behebt keine muskulären Dysbalancen! Beispiel: Wer durch viel Sitzen ein Hohlkreuz mit schwacher Bauchmuskulatur hat, sollte vor allem die Bauchmuskeln kräftigen, statt nur den Hüftbeuger zu dehnen.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-021","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Kann Dehnen Muskelkater verhindern? Begründe.","a":"Nein.\n• Stretching verhindert Muskelkater nicht (Freiwald)\n• Starke Dehnspannungen können selbst Mikroverletzungen und damit Muskelkater auslösen (Klee & Wiemann)","e":"Muskelkater sind winzige Risse im Muskel, und die werden durch weiteres Ziehen nicht kleiner. Merksatz: Stretching verhindert keinen Muskelkater! Beispiel: Wer nach dem ersten Bergablauf des Jahres intensiv dehnt, hat am übernächsten Tag trotzdem Muskelkater in den Oberschenkeln.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-022","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Erkläre, was Muskelkater ist und wie er entsteht.","a":"Muskelkater = Verletzung des Muskels.\n• ungewohnte Bewegung/Ermüdung → Verlust der intra-/intermuskulären Koordination\n• Mikrotraumen in den Myofibrillen (Z-Streifen reißen), v. a. bei exzentrischer Arbeit\n• Ödeme und Schmerzmediatoren → Schmerz, Steifheit","e":"Muskelkater kommt nicht von Milchsäure, sondern von kleinen Rissen im Muskel. Durch die Risse dringt Wasser ein, nach ca. 24–36 Stunden bilden sich kleine Ödeme; schmerzauslösende Stoffe treten in den Extrazellularraum aus und führen zu reflektorischer Verspannung. Die Muskeln sind steif, hart, kraftlos und schmerzen bei Bewegung und Druck. Beispiel: Nach einer Wanderung bergab (exzentrische Arbeit der Oberschenkel) tun die Beine meist erst am nächsten oder übernächsten Tag weh, weil sich die Schwellungen erst langsam bilden.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-023","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Wie sollte man nach einem intensiven Training dehnen? Begründe.","a":"• Erst auslaufen und lockern\n• danach nur leichtes (statisches oder dynamisches) Dehnen\n• Grund: Dehnspannung senkt die Durchblutung → schlechterer Abtransport von Stoffwechselprodukten (z. B. Laktat)","e":"Ein stark gedehnter Muskel drückt seine Blutgefäße zusammen, wie ein Gartenschlauch, auf den man tritt. Direktes statisches Dehnen nach intensiver Belastung behindert deshalb die Regeneration. Merksatz: Nach einem intensiven Training zuerst lockern und dann leichtes Dehnen! Beispiel: Nach einem 400-m-Lauf sollte man erst locker austraben, damit das Laktat abtransportiert wird, und erst später sanft dehnen.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-024","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Nenne die Merksätze zum Dehnen.","a":"• Kein statisches Dehnen im Aufwärmen/vor Maximalbelastung\n• Verletzungsvorbeugung nur durch Langzeitprogramme\n• Spielsport: aktiv-dynamisch\n• Nach intensivem Training erst lockern, dann leicht dehnen\n• Kein Schutz vor Muskelkater\n• Behebt keine Dysbalancen\n• Steigert Wohlbefinden/Körpergefühl\n• Verbessert nicht die Entspannungsfähigkeit","e":"Diese acht Sätze fassen die moderne Sicht aufs Dehnen zusammen und räumen mit alten Mythen auf. Beispiel: Ein Sprinter sollte direkt vor dem Start auf statisches Dehnen verzichten, kann aber an trainingsfreien Tagen ein Dehnprogramm für sein Wohlbefinden und die langfristige Beweglichkeit machen.","quelle":"L15.2","typ":"kern"},{"id":"bonus.b-025","thema":"B.L15","kapitel":"Dehnwirkungen","q":"Begründe, weshalb sich Kraft und Beweglichkeit gegenseitig beeinflussen.","a":"• Aktive Beweglichkeit hängt von der Kraft des Antagonisten ab\n• Kraft hängt von der Beweglichkeit ab: große Amplitude = längerer Beschleunigungsweg, Nutzung elastischer Energie (DVZ)\n• Eingeschränkte Beweglichkeit erhöht den Widerstand des Antagonisten","e":"Der Antagonist muss das Gelenk in die Endstellung bewegen, mehr Kraft vergrößert also die aktive Beweglichkeit. Umgekehrt mindert ein steifer Gegenspieler die Kraftentfaltung des Agonisten. Einseitiges Krafttraining ohne volle Bewegungsamplitude kann die Beweglichkeit einschränken, Training über die volle Amplitude erhält sie. Beispiel: Ein Speerwerfer, der den Arm weit nach hinten führen kann, hat einen längeren Beschleunigungsweg und wirft weiter; gleichzeitig braucht er Kraft, um diese Position aktiv einzunehmen.","quelle":"L15.4","typ":"zusatz"},{"id":"bonus.b-026","thema":"B.L15","kapitel":"Dehnmethoden","q":"Nenne die Hauptdehnmethoden zur Verbesserung der Beweglichkeit und ihre Systematik (nach Klee & Wiemann).","a":"• Dynamisches Dehnen: aktiv-dynamisch, passiv-dynamisch\n• Statisches Dehnen (Stretching): passiv-statisch, aktiv-statisch\n• Neuromuskuläre Techniken (aktives Stretching): Kontraktions-Relaxations-Stretching (Agonist), Antagonisten-Kontraktions-Stretching","e":"Erst teilt man in federnd (dynamisch) und haltend (statisch), dann jeweils in mit eigener Kraft (aktiv) und mit Hilfe von außen (passiv). Bei den neuromuskulären Techniken wird entweder der Agonist oder der Antagonist aktiviert; das Antagonisten-Kontraktions-Stretching gibt es in zwei Varianten. Beispiel: Beinschwünge sind aktiv-dynamisch, das Ziehen der Ferse ans Gesäß mit der Hand ist passiv-statisch.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-027","thema":"B.L15","kapitel":"Dehnmethoden","q":"Beschreibe das dynamische Dehnen und seine beiden Formen.","a":"Wiederholte, federnde Bewegungen.\n• Aktiv-dynamisch: nur durch eigene Muskelkraft\n• Passiv-dynamisch: von außen (z. B. Partner) unterstützt\n• 3–5 Serien à 15–20 Wdh., steigende Intensität","e":"Beim dynamischen Dehnen bleibt man in Bewegung und federt rhythmisch in die Endposition; innerhalb jeder Serie wird die Intensität gesteigert (Tab. 15.2). Beispiel: Ein Fußballer schwingt beim Aufwärmen das gestreckte Bein mehrmals vor und zurück, jedes Mal etwas höher.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-028","thema":"B.L15","kapitel":"Dehnmethoden","q":"Beschreibe das statische Dehnen (Stretching) und unterscheide passives und aktives Stretching.","a":"Halten der Dehnposition über einen bestimmten Zeitraum.\n• Passiv: Position durch äußere Kräfte (Partner, Schwerkraft, Hilfsmittel)\n• Aktiv: Position unter Nutzung neuromuskulärer Reflexe durch Aktivierung von Agonist oder Antagonist","e":"Statisch heißt: rein in die Position und dort bleiben. Beim aktiven Stretching hilft die eigene Muskelaktivität, den Dehnwiderstand reflektorisch zu senken. Beispiel: Beim klassischen Wadendehnen an der Wand drückt das Körpergewicht die Ferse nach unten (passiv), beim Hochhalten des Beins mit eigener Kraft arbeitet man aktiv.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-029","thema":"B.L15","kapitel":"Dehnmethoden","q":"Erkläre das Kontraktions-Relaxations-Stretching und seinen neurophysiologischen Hintergrund.","a":"• Zu dehnenden Muskel 1–10 s maximal isometrisch kontrahieren, dann statisch dehnen\n• Hintergrund: Reizung der Sehnenspindeln → autogene Hemmung → Muskel entspannt, größere Amplitude","e":"Erst fest anspannen, dann loslassen und dehnen: Die Anspannung soll die Notbremse der Sehnenspindel auslösen. Es ist eine neuromuskuläre Technik des aktiven Stretchings mit Aktivierung des Agonisten. Beispiel: Zum Dehnen der Oberschenkelrückseite drückt man das gestreckte Bein gegen den Widerstand eines Partners nach unten, entspannt dann und lässt sich weiter in die Dehnung ziehen.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-030","thema":"B.L15","kapitel":"Dehnmethoden","q":"Beschreibe die beiden Verfahren des Antagonisten-Kontraktions-Stretchings und ihren Wirkmechanismus.","a":"• Verfahren 1: Agonist maximal dehnen, dann Antagonist 10–20 s maximal kontrahieren und Dehnung dabei verstärken\n• Verfahren 2: erst Antagonist 10–20 s maximal isometrisch kontrahieren, dann Agonist statisch dehnen\n• Mechanismus: reziproke Antagonistenhemmung","e":"Hier arbeitet der Gegenspieler, damit der zu dehnende Muskel abschaltet: Die Kontraktion des Antagonisten hemmt reflektorisch den Agonisten, er entspannt und lässt sich weiter dehnen. Beispiel: Um die Oberschenkelrückseite zu dehnen, spannt man aktiv den Oberschenkelstrecker an und zieht das gestreckte Bein in Richtung Brust; die Rückseite wird dadurch reflektorisch gehemmt.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-031","thema":"B.L15","kapitel":"Dehnmethoden","q":"Vergleiche Kontraktions-Relaxations-Stretching und Antagonisten-Kontraktions-Stretching.","a":"• KR-Stretching: Agonist kontrahiert (1–10 s); autogene Hemmung über Sehnenspindeln\n• AK-Stretching: Antagonist kontrahiert (10–20 s); reziproke Antagonistenhemmung\n• Gemeinsam: neuromuskuläre, aktiv-statische Techniken, senken reflektorisch den Dehnwiderstand","e":"Der Unterschied liegt darin, wer vorher arbeitet: der Muskel selbst oder sein Gegenspieler. Beide Kontraktionen erfolgen maximal. Beispiel: Für die Wade drückt man beim ersten Verfahren den Fußballen kräftig gegen die Wand (Wade arbeitet), beim zweiten zieht man die Fußspitze aktiv zum Schienbein (Schienbeinmuskel arbeitet).","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-032","thema":"B.L15","kapitel":"Dehnmethoden","q":"Beschreibe das aktiv-dynamische Dehnen nach Tab. 15.2 (Durchführung, Umfang, Vor- und Nachteile).","a":"• Durchführung: rhythmisch, langsam, steigende Intensität in der Serie\n• Umfang: 3–5 Serien, 15–20 Wdh.\n• Vorteile: koordinativ, kräftigt Antagonisten, disziplinspezifisch\n• Nachteil: erfordert hohe Kontrolle","e":"Diese Methode trainiert neben der Beweglichkeit auch Koordination und Kraft, weil die eigenen Muskeln die Bewegung erzeugen. Beispiel: Ein Hürdenläufer macht kontrollierte Schwungbeinbewegungen wie beim Hürdenüberlaufen, muss aber darauf achten, nicht unkontrolliert zu reißen.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-033","thema":"B.L15","kapitel":"Dehnmethoden","q":"Beschreibe das passiv-dynamische Dehnen nach Tab. 15.2 (Durchführung, Umfang, Vor- und Nachteile).","a":"• Durchführung: rhythmisch geführt, langsam, steigende Intensität\n• Umfang: 3–5 Serien, 15–20 Wdh.\n• Vorteile: weite Amplituden, Entspannung/Entlastung des Übenden\n• Nachteile: keine Kräftigung des Antagonisten, erfahrener Partner nötig","e":"Hier macht der Partner die Arbeit, deshalb erreicht man große Weiten, trainiert aber keine Kraft. Beispiel: Eine Trainerin führt das Bein einer liegenden Turnerin rhythmisch federnd in Richtung Kopf; sie muss genau wissen, wie weit sie gehen darf.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-034","thema":"B.L15","kapitel":"Dehnmethoden","q":"Beschreibe das aktiv-statische und das passiv-statische Dehnen nach Tab. 15.2 (Durchführung, Umfang, Vor- und Nachteile).","a":"Aktiv-statisch: langsam bis Spannungsgefühl; 15 s, 1–3 Wdh.; + präzise, schützt vor Überlastung; – in reiner Form nicht möglich\nPassiv-statisch: geführt, dann halten; 15 s, 1–3 Wdh.; + hohe Intensität/Reizdauer, gezielt, entspannend; – nicht koordinativ/kräftigend","e":"Beide halten die Position, der Unterschied ist, ob man selbst oder etwas von außen dehnt. Beispiel: Beim passiven Stretching der Oberschenkelvorderseite zieht man die Ferse mit der Hand zum Po und hält 15 Sekunden, das ist intensiv, aber trainiert keine Kraft.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-035","thema":"B.L15","kapitel":"Dehnmethoden","q":"Beschreibe die neuromuskulären Dehntechniken nach Tab. 15.2 (Durchführung, Umfang, Vor- und Nachteile).","a":"• Durchführung: Dauerdehnung nach Kontraktion von Agonist bzw. Antagonist\n• Umfang: ca. 20 s Kontraktion, 2–3 s Entspannung, ca. 20 s Dehnung; 1–3 Wdh.\n• Vorteile: gute Kontrolle, intensive Dehnung\n• Nachteile: zeitaufwendig, schwierig","e":"Diese Techniken sind sehr wirksam, aber aufwendig, weil man anspannen, kurz lösen und dann lange dehnen muss. Beispiel: Im Schulsport mit 30 Schülern dauert eine solche Übung für alle Muskelgruppen sehr lange und muss erst sorgfältig erklärt werden.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-036","thema":"B.L15","kapitel":"Dehnmethoden","q":"Was kennzeichnet ein Stretching-Basisprogramm und welche Ausführungshinweise gelten?","a":"Kennzeichen: alle wesentlichen Muskelbereiche, abwechslungsreich, regelmäßig/langfristig\nAusführung (Weineck): Dehnstellung langsam verstärken, nicht wippen, leichtes Ziehen ok, 15–30 s halten, ruhig atmen","e":"Ein Basisprogramm ist wie Zähneputzen für die Muskeln: wenige Übungen, aber regelmäßig, als Teil des langfristigen Trainingsaufbaus. Die Dehnstellung wird durch Bewegen in Pfeilrichtung verstärkt, ruckartige Bewegungen sind tabu. Beispiel: Das Programm Top Ten nach Weineck enthält zehn Übungen für die wichtigsten Muskeln, die man zweimal pro Woche in einer ruhigen Einheit durchführen kann.","quelle":"L15.3","typ":"kern"},{"id":"bonus.b-037","thema":"B.L15","kapitel":"Dehnmethoden","q":"Bewerte die Methoden des Beweglichkeitstrainings hinsichtlich ihrer Brauchbarkeit im Schulsport.","a":"• Aktiv-dynamisch: gut fürs Aufwärmen, braucht Anleitung\n• Statisch: einfach, für eigene Einheiten/Stundenausklang, nicht vor Schnellkraft\n• Passiv-dynamisch: problematisch (Überdehnungsgefahr)\n• Neuromuskulär: wirksam, aber aufwendig\n→ Methode nach Ziel und Zeitpunkt wählen","e":"Im Schulsport zählt, was sicher, einfach und zeitsparend ist. Aktiv-dynamisches Dehnen ist koordinativ, kräftigend und ohne Leistungseinbußen; statisches Dehnen gehört hinter die Lockerung. Passiv-dynamisch braucht erfahrene Partner, neuromuskuläre Techniken eher für Oberstufe oder Projekte. Zusätzlich sollte Wissen über Dehnmythen vermittelt werden. Beispiel: Für eine Basketballstunde eignen sich Ausfallschritte und Armkreisen zum Aufwärmen, während Partnerdehnungen mit Wippen bei unerfahrenen Schülern schnell zu Zerrungen führen können.","quelle":"L15.4","typ":"zusatz"},{"id":"bonus.b-038","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Was überprüfen die Janda-Tests und welchem Zweck dienen sie?","a":"Prüfen die wichtigsten Muskeln auf Dehnfähigkeit (Janda), um Verkürzungen zu erkennen und gezielt zu beheben (Verletzungsprophylaxe).\n• Wade, gerader Kniestrecker, Hüftlendenmuskel, Adduktoren, ischiocrurale Muskulatur, Rückenstrecker","e":"Janda-Tests (nach dem tschechischen Arzt und Physiotherapeuten Vladimir Janda) sind einfache Checks, ob ein Muskel verkürzt ist. Hintergrund: Starke Trainingsreize können langfristig zu Verkürzungen bestimmter Muskeln führen. Beispiel: Ein Fußballer stellt im Test fest, dass er die Ferse nicht ans Gesäß bekommt, sein Kniestrecker ist verkürzt, also baut er gezielte Übungen dafür ein.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-039","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Wie wird die Dehnfähigkeit des dreiköpfigen Wadenmuskels getestet und bewertet?","a":"• Test: tiefe Hocke barfuß, Füße parallel, fußbreit\n• Ganze Sohle am Boden → ausreichend\n• Fersen heben sich → Wadenmuskulatur verkürzt","e":"Die Wade neigt zur Verkürzung, besonders bei Läufern. Die Testposition heißt Sohlenhockstand. Beispiel: Wer beim tiefen Hocken immer auf den Zehenspitzen landet oder nach hinten kippt, hat meist eine verkürzte Wadenmuskulatur.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-040","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Wie wird die Dehnfähigkeit des geraden Kniestreckers getestet und bewertet?","a":"• Test: Bauchlage, Ferse mit leichter Partnerhilfe Richtung Gesäß\n• Ferse am Gesäß: optimal\n• Abstand bis 15 cm: leichte Verkürzung\n• über 15 cm: starke Verkürzung","e":"Der gerade Kniestrecker zieht über Hüfte und Knie und ist bei Sportlern und Büroarbeitern am häufigsten verkürzt, z. B. durch viel Sitzen und Sprinten. Beispiel: Bleibt bei einer Schülerin zwischen Ferse und Po eine Lücke von 20 cm, ist ihr Kniestrecker stark verkürzt.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-041","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Wie wird die Dehnfähigkeit des Hüftlendenmuskels getestet und welche Folgen hat seine Verkürzung?","a":"• Test: Rückenlage, Gegenbein Richtung Brust ziehen\n• Testbein hebt sich (oft mit Unterschenkelstreckung) → Verkürzung\n• Folge: v. a. bei schwacher Bauchmuskulatur Hohlkreuz und Rückenprobleme","e":"Der Hüftlendenmuskel verbindet Lendenwirbelsäule und Oberschenkel; ist er zu kurz, zieht er das Becken nach vorne. Häufig stark verkürzt ist er bei Fußballern und viel sitzenden Menschen. Beispiel: Ein Büroangestellter, der täglich acht Stunden sitzt, bekommt durch den verkürzten Hüftbeuger leicht ein Hohlkreuz und Rückenschmerzen.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-042","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Wie wird die Dehnfähigkeit der Schenkelanzieher (Adduktoren) bewertet?","a":"Abduktionswinkel (Abspreizen):\n• 60°: gute Dehnfähigkeit\n• 40–60°: leichte Verkürzung\n• unter 40°: starke Verkürzung","e":"Die Adduktoren ziehen das Bein zur Körpermitte und werden bei Seitwärtsbewegungen stark beansprucht; Adduktorenverletzungen gehören in vielen Sportarten zu den häufigsten Verletzungen. Beispiel: Fußballer und Eishockeyspieler ziehen sich häufig Leistenzerrungen zu; ein Abspreizwinkel unter 40° wäre ein Warnsignal.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-043","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Wie wird die Dehnfähigkeit der Sitzbeinunterschenkelmuskulatur (ischiocrurale Muskulatur) bewertet?","a":"• Test: Rückenlage, gestrecktes Bein anheben, Gegenbein fixiert\n• bis 90° ohne Ziehen in der Kniekehle: gut\n• 80–90°: leichte Verkürzung\n• 60–80°: starke Verkürzung","e":"Gemeint sind die Muskeln der Oberschenkelrückseite, die vom Sitzbein zum Unterschenkel ziehen. Beispiel: Wenn ein Partner dein gestrecktes Bein hebt und es bei 70° in der Kniekehle zieht, ist diese Muskulatur stark verkürzt.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-044","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Wie wird die Dehnfähigkeit des Rückenstreckers bewertet und welche Folgen hat eine Verkürzung?","a":"Stirn-Knie-Abstand im Langsitz bei max. Rumpfbeuge:\n• 0–10 cm: gut\n• 10–15 cm: leicht verkürzt\n• über 15 cm: stark verkürzt\nFolge: veränderte Lendenlordose, häufig Bandscheibenprobleme","e":"Der Rückenstrecker hält uns aufrecht, wird aber vor allem im Bereich der Lendenwirbelsäule leicht zu kurz. Beispiel: Wenn deine Stirn im Langsitz 20 cm vor den Knien stehen bleibt, deutet das auf einen stark verkürzten Rückenstrecker hin.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-045","thema":"B.L16","kapitel":"Beweglichkeitstests","q":"Fasse die Bewertungsgrenzen der Janda-Tests mit Messwerten in einer Übersicht zusammen.","a":"• Wade: Fersen heben sich in der Hocke = verkürzt\n• Kniestrecker: Ferse am Gesäß / bis 15 cm / über 15 cm\n• Hüftlendenmuskel: Testbein hebt sich = verkürzt\n• Adduktoren: 60° / 40–60° / unter 40°\n• Ischiocrurale: 90° / 80–90° / 60–80°\n• Rückenstrecker: 0–10 / 10–15 / über 15 cm\n(jeweils gut / leicht / stark verkürzt)","e":"Lerntipp: Bei den Strecken gilt die Grenze 15 cm (Kniestrecker und Rückenstrecker), bei den Winkeln je 20° Abstufung nach unten (Adduktoren 60/40, Oberschenkelrückseite 90/80/60). Beispiel: Wer beim Beinheben 85° schafft, ist leicht verkürzt.","quelle":"L16.5","typ":"kern"},{"id":"bonus.b-046","thema":"B.L17","kapitel":"Leistungsmotivation","q":"Nenne und erläutere die drei Bezugsnormen zur Bewertung sportlicher Leistungen.","a":"• Individuell: Vergleich mit eigenen früheren Leistungen\n• Sachbezogen: Vergleich mit objektiven Anforderungen/Kriterien der Aufgabe\n• Sozial: Vergleich mit der Leistung anderer","e":"Die Frage ist immer: Womit vergleiche ich meine Leistung? Bei der sachlichen Norm zählt das Handlungsergebnis als solches, gemessen an den objektiven Bewältigungsmöglichkeiten der Aufgabe. Beispiel: Eine Läuferin freut sich über 5:40 min auf 1000 m, weil sie sich um 10 s verbessert hat (individuell), weil sie die Note 2 erreicht (sachlich) oder weil sie die Schnellste der Klasse war (sozial).","quelle":"L17.1","typ":"kern"},{"id":"bonus.b-047","thema":"B.L17","kapitel":"Leistungsmotivation","q":"Nenne die fünf Bedingungen für leistungsmotiviertes Handeln (nach Heckhausen bzw. Gabler).","a":"1. Objektivierbares Ergebnis (Anfang und Ende)\n2. Gütemaßstab als Bezugsnorm\n3. Schwierigkeitsmaßstab (Gelingen/Misslingen möglich)\n4. Verbindlichkeit beider Maßstäbe für den Handelnden\n5. Ergebnis als selbst verursacht erlebt","e":"Nur wenn alle fünf Punkte erfüllt sind, spricht man von Leistungshandeln (Heckhausen bzw. Gabler). Die Bezugsnorm kann sachbezogen, individuell oder sozial sein. Beispiel: Ein Marathonläufer bei km 40 hat ein messbares Ziel (Zielzeit), sie kann scheitern, er nimmt sie ernst und weiß, dass es an ihm liegt, ob er die letzten Reserven mobilisiert.","quelle":"L17.1","typ":"kern"},{"id":"bonus.b-048","thema":"B.L17","kapitel":"Leistungsmotivation","q":"Erläutere die Bedingungen objektivierbares Ergebnis und Gütemaßstab für leistungsmotiviertes Handeln.","a":"• Objektivierbares Ergebnis: Handlung hat Anfang und Ende, Ergebnis ist erkennbar\n• Gütemaßstab: Ergebnis ist bewertbar, z. B. c-g-s-System (cm, g, s) oder Gestaltungskriterien","e":"Ohne Ziel und Maßstab weiß man nicht, ob man gut war. Tätigkeiten ohne markierbares Ende sind keine Leistungshandlung, es sei denn, man setzt sich ein Ziel. Sportergebnisse sind messbar, durch Regeln definiert oder ergeben sich aus der Aufgabe. Beispiel: Einfaches Jonglieren mit dem Ball ist keine Leistungshandlung; versucht der Spieler aber, den Ball möglichst oft hochzuhalten und zählt mit, wird es eine.","quelle":"L17.1","typ":"kern"},{"id":"bonus.b-049","thema":"B.L17","kapitel":"Leistungsmotivation","q":"Erläutere die Bedingungen Schwierigkeitsmaßstab, Verbindlichkeit und Selbstverursachung für leistungsmotiviertes Handeln.","a":"• Schwierigkeitsmaßstab: Fähigkeit und Anstrengung nötig, Gelingen und Misslingen möglich\n• Verbindlichkeit: Maßstäbe werden als für sich gültig angesehen\n• Selbstverursachung: Ergebnis wird als selbst bewirkt erlebt (nicht Zufall, nicht Doping)","e":"Leistung macht nur stolz, wenn sie schwer, gewollt und selbst geschafft war. Fehlt die Verbindlichkeit, reagiert man weder mit Freude noch mit Enttäuschung. Beispiel: Ein Salto, der nur passiert, weil man auf dem 3-m-Brett ausrutscht, ist keine Leistung, und ein Schüler, dem die Noten im Sport egal sind, erlebt seinen Sprint nicht als Leistung.","quelle":"L17.1","typ":"kern"},{"id":"bonus.b-050","thema":"B.L17","kapitel":"Leistungsmotivation","q":"Definiere Leistungsmotivation bzw. leistungsmotiviertes Handeln (nach Alfermann & Stoll).","a":"Bestreben, eine Aufgabe zu meistern und dabei einen Gütemaßstab zu erreichen oder zu übertreffen, Hindernisse zu überwinden, auch bei Misserfolg auszudauern und sich für das Ergebnis verantwortlich zu fühlen (Alfermann & Stoll).","e":"Merksatz: Der Kern der Leistungsmotivation ist die Auseinandersetzung mit einem Gütemaßstab. Leistungsmotiviert ist man, wenn man wissen will, was man selbst draufhat. Beispiel: Ein Freizeitjogger misst nach wenigen Läufen seine Zeit, um sie beim nächsten Mal zu unterbieten, das Erfolgserlebnis ist die eigentliche Belohnung.","quelle":"L17.1","typ":"kern"},{"id":"bonus.b-051","thema":"B.L17","kapitel":"Leistungsmotivation","q":"Grenze leistungsmotiviertes Handeln von anderem angestrengtem Verhalten ab.","a":"• Leistungsmotiviert nur, wenn Ziel die Selbstbewertung der eigenen Tüchtigkeit an einem Gütemaßstab ist (Rheinberg & Vollmeyer)\n• Anreiz: Stolz und Zufriedenheit (Erfolgserlebnis)\n• Nicht: Anstrengung für Geld, Prestige o. Ä.","e":"Nicht jedes angestrengte Bemühen ist leistungsmotiviert; Leistungsziele können auch aus anderen Gründen verfolgt werden, etwa für ein höheres Gehalt oder um eine Prüfung zu bestehen und nicht mehr lernen zu müssen. Entscheidend ist das Warum der Anstrengung. Beispiel: Ein Profi, der nur für die Siegprämie trainiert, ist extrinsisch motiviert; ein Hobbyradler, der sich über seine neue Bestzeit auf dem Tacho freut, ist leistungsmotiviert.","quelle":"L17.1","typ":"kern"},{"id":"bonus.b-052","thema":"B.L17","kapitel":"Leistungsmotivation","q":"Nenne die drei Modelle der kognitiven Leistungsmotivationsforschung und ihren jeweiligen Schwerpunkt.","a":"• Risikowahlmodell (Atkinson): Hoffnung auf Erfolg vs. Furcht vor Misserfolg\n• Attributionstheorie (Weiner, Heckhausen): Ursachenzuschreibung; inkl. Selbstbewertungsmodell (Heckhausen)\n• Zielorientierung: Aufgaben- vs. Wettbewerbs-/Egoorientierung","e":"Die Modelle bauen aufeinander auf: Erst wählt man eine Aufgabe (Risikowahl), dann erklärt man sein Ergebnis (Attribution), und dahinter steht, was man unter Erfolg versteht (Zielorientierung). Das Selbstbewertungsmodell ergänzt die Attributionstheorie um die Selbstbewertung. Beispiel: Eine Hochspringerin wählt eine Einstiegshöhe, reißt sie, erklärt das mit Pech und will sich vor allem selbst verbessern.","quelle":"L17.1","typ":"kern"},{"id":"bonus.b-053","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Erläutere die Kernaussage des Risikowahlmodells nach Atkinson.","a":"• Erfolgszuversichtliche wählen mittelschwere Aufgaben\n• Misserfolgsängstliche wählen sehr leichte oder sehr schwere Aufgaben\n• Grundlage: Motiv (HE, FM) × Erfolgswahrscheinlichkeit (W) × Anreizwert (A)","e":"Das Leistungsmotiv mit den Tendenzen Hoffnung auf Erfolg und Furcht vor Misserfolg wirkt zusammen mit den situativen Anreizen der Aufgabe. Mittelschwere Aufgaben sind spannend, weil Erfolg möglich, aber nicht sicher ist. Beispiel: Beim Hochsprung wählt der erfolgszuversichtliche Schüler eine Einstiegshöhe knapp unter seiner Bestleistung, der misserfolgsängstliche eine lächerlich niedrige oder eine unerreichbar hohe Höhe.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-054","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Beschreibe die Herkunft des Risikowahlmodells (McClelland und Atkinson).","a":"• McClelland (1953): Leistungsmotiv als Persönlichkeitsvariable mit Hoffnung auf Erfolg (aufsuchend) und Furcht vor Misserfolg (meidend)\n• Atkinson (1974): interaktionistisch, Zusammenwirken von Motiven und situativen Anreizen → Risikowahlmodell","e":"McClelland schaute nur auf die Person: Je nachdem, welche Tendenz überwiegt, ist jemand erfolgszuversichtlich (hoch motiviert) oder misserfolgsängstlich (niedrig motiviert). Atkinson nahm die Situation dazu. Beispiel: Ob ein Schüler sich beim Bodenturnen an den Salto traut, hängt nach Atkinson nicht nur von seiner Persönlichkeit ab, sondern auch davon, wie schwer und reizvoll der Salto für ihn ist.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-055","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Erkläre den Zusammenhang von Erfolgswahrscheinlichkeit und Anreizwert im Risikowahlmodell und begründe, warum mittelschwere Aufgaben für Erfolgszuversichtliche am attraktivsten sind.","a":"• W und A hängen umgekehrt zusammen: A = 1 − W\n• Motivation = Motiv × W × A; W × A maximal bei W = 0,5\n• daher bei Erfolgszuversichtlichen (HE > FM) höchste Anziehung, bei Misserfolgsängstlichen (FM > HE) höchste Vermeidung mittelschwerer Aufgaben","e":"Ein leichter Sieg ist wenig wert, ein unmöglicher Sieg ist unwahrscheinlich, in der Mitte stimmt die Mischung. Misserfolgsängstliche weichen auf sehr leichte Aufgaben (sicherer Erfolg) oder sehr schwere (Scheitern ist entschuldbar) aus. Beispiel: Ein Tennisspieler freut sich kaum über einen Sieg gegen einen Anfänger, aber sehr über einen Sieg gegen einen gleich starken Gegner; beim Profi verliert er dagegen ohne Gesichtsverlust.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-056","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Welche Einschränkung gilt bei der Charakterisierung von Personen als erfolgszuversichtlich oder misserfolgsängstlich?","a":"• Idealtypische Zuspitzung\n• HE ist nicht das genaue Gegenteil von FM\n• nur mittlere negative Zusammenhänge: beide Tendenzen können in einer Person vorkommen","e":"Menschen sind keine Schubladen. Beispiel: Ein Sportler kann sich sehr auf einen Wettkampf freuen und gleichzeitig große Angst vor dem Versagen haben; beide Tendenzen existieren nebeneinander.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-057","thema":"B.L17","kapitel":"Attribution","q":"Was versteht man unter Kausalattribution und wer sind die Hauptvertreter der Attributionstheorie?","a":"Kausalattributionen = Ursachenzuschreibungen für Erfolg und Misserfolg.\n• Sozial-kognitiver Prozessansatz (1970er)\n• Hauptvertreter: Weiner, Heckhausen (1974)","e":"Die Attributionstheorie betont kognitive Zwischenprozesse: Den Annahmen über die Ursachen von Erfolg und Misserfolg kommt im Motivationsgeschehen zentrale Bedeutung zu. Nach jedem Wettkampf fragt man sich: Woran lag es? Beispiel: Wer eine Niederlage auf fehlendes Training schiebt, trainiert mehr; wer sie auf fehlendes Talent schiebt, gibt eher auf.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-058","thema":"B.L17","kapitel":"Attribution","q":"Unterscheide prospektive und retrospektive Kausalattributionen und beschreibe ihre Wirkung.","a":"• Prospektiv: bei der Handlungsplanung, beeinflusst die aktuelle Handlung\n• Retrospektiv: nach der Handlung, beeinflusst künftiges Handeln (Aufgabenwahl, Ausdauer)\n• Beide lösen Emotionen aus (Stolz, Scham, Angst …)","e":"Attributionen können also sowohl Folge als auch Ursache von Handlungen sein. Man erklärt Ergebnisse vorher (Ich schaffe das, weil ich gut trainiert habe) und nachher (Ich habe es geschafft, weil ...); die ausgelösten Gefühle wie Vorfreude oder Scham bestimmen das Handeln mit. Beispiel: Eine Turnerin, die ihren Sturz am Balken auf Konzentrationsmangel zurückführt, geht den nächsten Wettkampf mit dem Plan an, sich besser zu fokussieren.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-059","thema":"B.L17","kapitel":"Attribution","q":"Beschreibe das Prozessmodell eines Motivationsprozesses in einer Leistungssituation nach Gabler (Abb. 17.3).","a":"Leistungsmotiv + Situation →\n• Abwägen/Planen: prospektive Bewertung, Emotion (Hoffnung/Furcht)\n• Handeln: beobachtbare Leistungshandlung\n• Bewerten: Kausalattribution, Selbstbewertung, Emotion (Stolz/Scham)","e":"Das Modell ist eine Zeitleiste: vorher abwägen, dann handeln, danach bewerten. Das Leistungsmotiv ist ein hypothetisches Konstrukt, das man nur indirekt aus der Person-Umwelt-Interaktion erschließen kann; von außen sichtbar sind nur Umweltbedingungen und Handlung, die Zwischenprozesse laufen kognitiv und emotional ab. Beispiel: Ein Elfmeterschütze überlegt, ob er treffen wird (Hoffnung oder Angst), schießt und erklärt danach sein Tor mit seiner guten Technik, worauf er stolz ist.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-060","thema":"B.L17","kapitel":"Attribution","q":"Erläutere die Klassifikation von Ursachen für Erfolg und Misserfolg nach Weiner (2x2-Schema).","a":"Lokalisation (internal/external) × Stabilität (stabil/variabel):\n• internal-stabil: Fähigkeit\n• internal-variabel: Anstrengung\n• external-stabil: Aufgabenschwierigkeit\n• external-variabel: Zufall\n(+ 3. Dimension: Kontrollierbarkeit)","e":"Stell dir ein Viererfeld vor: innen (in der Person) / außen (in der Umwelt) und dauerhaft/wechselnd. Beispiel Tennis: Talent ist internal-stabil, der Einsatzwille im Spiel internal-variabel, die Stärke des Gegners external-stabil und Windböen external-variabel.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-061","thema":"B.L17","kapitel":"Attribution","q":"Ordne typische Ursachen für Erfolg und Misserfolg in einem Tenniswettkampf dem Attributionsschema zu (Tab. 17.2).","a":"• Internal-stabil: Talent, Trainingszustand, Routine, Ehrgeiz\n• Internal-variabel: Einsatzwille, Tagesform, Spieltaktik\n• External-stabil: Gegnerstärke, Trainer, soziale Unterstützung, Spielklasse\n• External-variabel: Glück/Pech, Zuschauer, Wetter, Gegnerform","e":"So lässt sich fast jede Ausrede eines Sportlers einordnen. Beispiel: Sagt eine Spielerin nach einer Niederlage, der Gegner habe heute einen Sahnetag gehabt, ist das external-variabel; sagt sie, sie sei einfach nicht gut genug, internal-stabil.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-062","thema":"B.L17","kapitel":"Attribution","q":"Erläutere das Grundmodell der Attributionstheorie: Wie attribuieren Erfolgszuversichtliche und Misserfolgsängstliche?","a":"Erfolgszuversichtliche: Erfolg → internal (Fähigkeit, Anstrengung); Misserfolg → variabel (Pech, mangelnde Anstrengung)\nMisserfolgsängstliche: Erfolg → external (Glück, leichte Aufgabe); Misserfolg → internal-stabil (mangelnde Fähigkeit)","e":"Der Optimist nimmt Erfolge persönlich und Misserfolge nicht, das schützt sein Selbstwertgefühl und hält die Zuversicht für den nächsten Versuch. Beim Pessimisten ist es umgekehrt: Erfolge haben kaum Belohnungswert, und er strengt sich künftig weniger an. Beispiel: Reißt ein erfolgszuversichtlicher Schüler eine viel zu hohe Latte, sagt er: Heute war nicht mein Tag. Springt ein misserfolgsängstlicher über eine sehr niedrige Höhe, sagt er: Das war ja auch leicht.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-063","thema":"B.L17","kapitel":"Attribution","q":"Welche Bedeutung hat die Dimension Kontrollierbarkeit in der Attributionstheorie?","a":"Dritte Dimension neben Lokalisation und Stabilität.\n• Unkontrollierbare Ursachen → keine Anstrengung zur Veränderung\n• Erfolgszuversichtliche: Leistung kontrollierbar\n• Misserfolgsängstliche: Ursachen nicht kontrollierbar","e":"Die Kontrollierbarkeit wirkt sich vor allem auf die weiteren Folgen der Handlung aus. Was ich beeinflussen kann, versuche ich zu ändern, was ich nicht beeinflussen kann, nehme ich hin. Beispiel: Ein Schwimmer, der seine schlechte Zeit auf fehlendes Techniktraining zurückführt, übt gezielt; einer, der sie auf seine kurzen Arme schiebt, sieht keinen Sinn im Üben.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-064","thema":"B.L17","kapitel":"Attribution","q":"Beschreibe das Selbstbewertungsmodell der Leistungsmotivation nach Heckhausen.","a":"Leistungsmotiv als sich selbst stabilisierendes System aus:\n1. Zielsetzung (Anspruchsniveau)\n2. Kausalattribution\n3. Selbstbewertung (Affektbilanz)\n• Bilanz positiv (Erfolgszuversichtliche) bzw. negativ (Misserfolgsängstliche) → Verfestigung","e":"Heckhausen ergänzt die Attributionstheorie um weitere kognitive Prozesse; das Leistungsmotiv ist hier kein festes Persönlichkeitsmerkmal. Das Modell erklärt, warum Optimisten Optimisten und Pessimisten Pessimisten bleiben: Das System bestätigt sich selbst. Beispiel: Eine erfolgszuversichtliche Läuferin wählt passende Ziele, erklärt Erfolge mit ihrem Training, ist stolz und geht motivierter in den nächsten Lauf.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-065","thema":"B.L17","kapitel":"Attribution","q":"Vergleiche Erfolgszuversichtliche und Misserfolgsängstliche anhand der Komponenten des Selbstbewertungsmodells (Tab. 17.3).","a":"Erfolgszuversichtlich (E) / misserfolgsängstlich (M):\n• Anspruchsniveau: E realistisch-mittelschwer; M zu leicht/zu schwer\n• Erfolg: E Anstrengung, Tüchtigkeit; M Glück, leichte Aufgabe\n• Misserfolg: E fehlende Anstrengung, Pech; M fehlende Fähigkeit\n• Affektbilanz: E positiv; M negativ","e":"Die Tabelle zeigt drei Stellschrauben, die bei beiden Typen in entgegengesetzte Richtungen gedreht sind. Beispiel: Zwei Schüler bekommen beim Weitsprung dieselbe Note; der eine ist zufrieden und führt sie auf seinen Einsatz zurück, der andere findet sie Glück und fühlt sich trotzdem schlecht.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-066","thema":"B.L17","kapitel":"Attribution","q":"Erkläre, warum sich das Selbstbewertungssystem misserfolgsängstlicher Personen selbst stabilisiert.","a":"• Meiden realistischer Aufgaben → kein Erleben von Anstrengung-Ergebnis-Zusammenhang und Leistungszuwachs\n• Erfolge → Glück/leichte Aufgabe; Misserfolge → mangelnde Fähigkeit\n• negative Selbstbewertungsbilanz bestätigt das Selbstbild\n• Ziel: Selbstwertschutz statt Tüchtigkeitssteigerung","e":"Das ist ein Teufelskreis: Wer Angst vor dem Scheitern hat, sucht sich Aufgaben, an denen er nichts über sich lernt. Selbst bei gleich vielen Erfolgen und Misserfolgen ist die Bilanz negativ, weil ein Erfolg wenig bedeutet und ein Misserfolg sehr belastet. Realistische Leistungssituationen wirken bedrohlich, Selbstwirksamkeit wird nicht erlebt (Brunstein & Heckhausen). Beispiel: Ein ängstlicher Schüler meldet sich nur bei sehr leichten Turnübungen; gelingt sie, war sie ja leicht, misslingt sie, fühlt er sich bestätigt, dass er unsportlich ist.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-067","thema":"B.L17","kapitel":"Attribution","q":"Beschreibe den Ablauf des Selbstbewertungsmodells am Beispiel eines hoch motivierten Sportlers (Abb. 17.4).","a":"• Handlungsdirektive: eigene Tüchtigkeit steigern\n• Erwartung: Hoffnung auf Erfolg\n• Ziel: realistisch-anspruchsvolle Aufgabe\n• Ergebnisbilanz: ausgewogen\n• Attribution: Erfolg → Fähigkeit/Anstrengung; Misserfolg → Anstrengungsmangel/Pech\n• Affektbilanz positiv → verstärkt Leistungshandeln","e":"Beim Hochmotivierten greift ein Zahnrad ins andere und alles treibt ihn weiter an: Die positiven Selbstbewertungsemotionen überwiegen und motivieren zum nächsten Versuch. Beispiel: Ein Judoka sucht sich gleich starke Trainingspartner, gewinnt und verliert etwa gleich oft, erklärt Siege mit seinem Können, Niederlagen mit zu wenig Einsatz und geht mit Lust ins nächste Training.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-068","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Erläutere die Theorie der Zielorientierung und unterscheide Aufgaben- und Egoorientierung.","a":"Ziel: Kompetenz zeigen, Eindruck von Unfähigkeit vermeiden.\n• Aufgabenorientierung: Aufgabe meistern, Leistungsqualität; individueller/sachlicher Maßstab\n• Egoorientierung: andere übertreffen; sozialer Maßstab\n• Hochmotivierte eher aufgaben-, Niedrigmotivierte eher egoorientiert","e":"Die Ausrichtung gilt als gelernte, relativ stabile Motivdisposition. Bei der Egoorientierung hängt das eigene Erfolgserleben vom Können der anderen ab. Aufgabenorientiert fragt: Bin ich besser geworden? Egoorientiert fragt: Bin ich besser als die anderen? Beispiel: Eine Schwimmerin freut sich über ihre persönliche Bestzeit, auch wenn sie Fünfte wird (aufgabenorientiert); ihre Teamkollegin ist trotz Bestzeit frustriert, weil sie nicht gewonnen hat (egoorientiert).","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-069","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Mit welchen psychischen Merkmalen korrelieren Aufgaben- und Egoorientierung (Tab. 17.4)?","a":"Aufgabenorientierung: Erfolg durch Anstrengung; Fähigkeitsentwicklung, Teamzugehörigkeit; Kompetenzerleben, positive Emotionen, intrinsische Motivation\nEgoorientierung: Erfolg durch Begabung; Status, Macht, Anerkennung; unfaire Einstellungen, Aggression\n(jeweils auch entsprechende Elternorientierung)","e":"Aufgabenorientierte sehen Sport als Weg, Aufgaben zu bewältigen, fitter und selbstbewusster zu werden; sie zeigen Freude, Ausdauer nach Misserfolg und wählen mittlere Schwierigkeiten. Egoorientierte sehen den sozialen Status als zentralen Zweck des Sports. Aufgabenorientierte ähneln damit den Erfolgszuversichtlichen. Beispiel: Ein egoorientierter Fußballer, der unbedingt gewinnen will, greift eher zu einem Foul als ein aufgabenorientierter Mitspieler, dem es um gutes Spielen geht.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-070","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Vergleiche Hoch- und Niedrigmotivierte nach dem Risikowahlmodell hinsichtlich Motivrichtung, Ergebnis- und Affektbilanz, Aufgabenwahl und Wettkampfleistung (Tab. 17.5).","a":"Hochmotivierte: erfolgszuversichtlich; Ergebnis- und Affektbilanz positiv; mittelschwere Aufgaben (0,40 < p < 0,60); Wettkampf ≥ Training\nNiedrigmotivierte: misserfolgsängstlich; Bilanzen negativ; leichte (p > 0,75) oder zu schwere (p < 0,25) Aufgaben; Wettkampf < Training","e":"p steht hier für die Erfolgswahrscheinlichkeit. Hochmotivierte erinnern sich eher an Erfolge und erleben mehr Stolz und Freude, Niedrigmotivierte erinnern sich an Misserfolge und erleben mehr Scham und Enttäuschung. Beispiel: Ein misserfolgsängstlicher Turner zeigt im Training eine saubere Kür, im Wettkampf vor Publikum patzt er; sein erfolgszuversichtlicher Kollege turnt im Wettkampf sogar noch besser.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-071","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Fasse die Kernelemente und Kernaussagen des Risikowahlmodells, der Attributionstheorie und der Theorie der Zielorientierung zusammen (Abb. 17.5).","a":"• Risikowahl (HE, FM, Anreize): Hochmotivierte wählen mittelschwere, Niedrigmotivierte sehr leichte/schwere Aufgaben\n• Attribution (Stabilität, Lokalisation, Kontrolle): Hoch: Erfolg internal, Misserfolg variabel; Niedrig: Erfolg external, Misserfolg internal-stabil\n• Zielorientierung: Hoch: aufgaben-, Niedrig: egoorientiert","e":"Drei Brillen auf dasselbe Phänomen: Welche Aufgabe wähle ich, wie erkläre ich das Ergebnis, was bedeutet für mich Erfolg? Zu den Anreizen gehören in- und extrinsische; Aufgabenorientierte nutzen eine sachliche oder individuelle Bezugsnorm, Egoorientierte eine soziale. Beispiel: Ein hoch motivierter Kugelstoßer wählt eine realistische Zielweite, erklärt einen schlechten Stoß mit fehlender Konzentration und freut sich vor allem über persönliche Fortschritte.","quelle":"L17.2","typ":"kern"},{"id":"bonus.b-072","thema":"B.L17","kapitel":"Motivationsmodelle","q":"Welche praktischen Empfehlungen zur Steigerung der Leistungsmotivation lassen sich aus den Motivationstheorien ableiten (nach Alfermann & Stoll)?","a":"• Mittelschwere, realistische Aufgaben anbieten\n• Günstige Attributionen fördern (Reattributionstraining)\n• Individuelle Bezugsnorm nutzen\n• Aufgabenorientierung fördern\n• Positive Affektbilanz: Erfolge bewusst machen, loben","e":"Die Empfehlungen setzen genau an den Stellschrauben der Modelle an (Alfermann & Stoll): Erfolg soll auf Fähigkeit und Anstrengung, Misserfolg auf veränderbare Ursachen zurückgeführt werden; Fortschritte werden im Vergleich zu früheren eigenen Leistungen rückgemeldet, und Lernen steht vor dem Sieg über andere. Beispiel: Eine Sportlehrerin lässt beim Hochsprung jeden seine Einstiegshöhe nahe der eigenen Bestleistung wählen, lobt persönliche Verbesserungen und erklärt Fehlversuche mit veränderbaren Technikfehlern statt mit Talent.","quelle":"L17.3","typ":"zusatz"},{"id":"bonus.b-073","thema":"B.L19","kapitel":"Aggression","q":"Definiere Aggression und Aggressivität (nach Gabler).","a":"• Aggression: Verhalten, das auf Schädigung der sozialen Umwelt gerichtet ist (Handlung)\n• Aggressivität: relativ überdauernde Bereitschaft, sich aggressiv zu verhalten (Persönlichkeitsdisposition)","e":"Aggression ist das, was jemand tut, Aggressivität ist, wie schnell jemand dazu neigt. Beispiel: Ein Eishockeyspieler, der oft in Schlägereien verwickelt ist, hat eine hohe Aggressivität; der einzelne Faustschlag in einem Spiel ist eine Aggression.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-074","thema":"B.L19","kapitel":"Aggression","q":"Warum sind zielstrebiges Angreifen und zupackendes Verhalten im Sport nicht per se aggressiv?","a":"Weil zur Aggression die Schädigungsabsicht gehört. Engagiertes, körperbetontes Angreifen ohne Schädigungsabsicht ist nicht aggressiv; sonst wäre fast jedes Wettkampfverhalten aggressiv.","e":"Im Alltag nennt man zielstrebige, angriffslustige Handlungen oft aggressiv; Sportpsychologen nehmen den Aspekt der Schädigung deshalb ausdrücklich in die Definition auf. Wenn ein Trainer ruft: Spielt aggressiver!, meint er mutiger und entschlossener, nicht verletzender. Beispiel: Ein Handballer, der energisch zum Kreis zieht, verhält sich nicht aggressiv im wissenschaftlichen Sinn, solange er den Gegner nicht schädigen will.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-075","thema":"B.L19","kapitel":"Aggression","q":"Begründe, warum eine Aggressionsdefinition die Absicht (Intention) und nicht nur die Wirkung der Handlung berücksichtigen muss.","a":"• Nur über die Wirkung: erfolglose Schädigungsversuche wären nicht aggressiv\n• unbeabsichtigte Verletzungen wären fälschlich aggressiv\n→ Entscheidend ist die Schädigungsabsicht","e":"Es zählt die Absicht, nicht nur das Ergebnis: Eine Handlung ist schon aggressiv, wenn die Schädigungsabsicht besteht. Beispiel aus dem Buch: Ein Boxer schlägt gezielt nach dem Kopf, der Gegner weicht aus, das ist trotzdem aggressiv; im Eishockey verletzt sich ein Spieler nach einem Zusammenprall auf dem Eis, ohne dass jemand das wollte, das ist nicht aggressiv.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-076","thema":"B.L19","kapitel":"Aggression","q":"Welche Rolle spielen Regeln und Normen bei der Abgrenzung aggressiver von nicht aggressiven Handlungen im Sport?","a":"• Aggressiv erst bei Abweichung von den als verbindlich anerkannten Normen (Gabler)\n• Normabweichung ≠ Regelwidrigkeit: auch regelgerechtes Verhalten kann aggressiv sein\n• Akzeptierte regelkonforme Härte (Bodycheck, Tackling) ist nicht aggressiv","e":"Den Gegner an seinen Zielen zu hindern, ist Wettkampf und keine soziale Schädigung; Regeln und Normen stecken den Rahmen ab. Regeln sind die geschriebenen Gesetze, Normen die ungeschriebenen Erwartungen. Beispiel: Ein Tackling ist im Rugby normal, im Basketball dagegen grob unsportlich und aggressiv; ein absichtlicher Wurf auf den Kopf des Handballtorwarts kann regelkonform wirken, weil der Schiedsrichter die Absicht nicht erkennt, ist aber normabweichend.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-077","thema":"B.L19","kapitel":"Aggression","q":"Gib Gablers Definition einer aggressiven Handlung im Sport wieder und erläutere den Unterschied zwischen sozialer Behinderung und personaler Schädigung.","a":"Aggressiv ist eine Handlung, wenn jemand in Abweichung von sportlichen Normen beabsichtigt, einer anderen Person personalen Schaden (Verletzung, Schmerz) zuzufügen (Gabler).\n• Soziale Behinderung: Gegner in Aktionen hindern, legitim\n• Personale Schädigung: Angriff auf die Person, aggressiv","e":"Den Gegner am Torschuss zu hindern ist Sport, ihm wehtun zu wollen ist Aggression; die Schädigung kann körperlich oder psychisch sein. Merksatz: Aggressives Verhalten weicht immer von der sportlichen Norm ab, kann aber als implizite Aggression durchaus regelentsprechend sein. Beispiel: Ein Verteidiger, der den Ball wegspitzelt, behindert sozial; einer, der gezielt auf den Knöchel tritt, schädigt personal.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-078","thema":"B.L19","kapitel":"Aggression","q":"Unterscheide explizit und implizit norm- bzw. regelabweichende Handlungen.","a":"Normabweichend (= aggressiv): explizit = Schädigung beabsichtigt; implizit = Schädigung in Kauf genommen\nRegelabweichend: explizit = Regelverstoß beabsichtigt; implizit = Regelverstoß in Kauf genommen","e":"Explizit heißt: Ich will es; implizit heißt: Ich nehme es in Kauf. Normentsprechende Handlungen sind nicht aggressiv, auch wenn sie Regeln verletzen; ein absichtlicher Regelverstoß ist selten und soll vom Schiedsrichter erkannt werden. Beispiel: Das taktische Foul im Basketball zum Stoppen der Uhr ist explizit regelabweichend, aber normentsprechend; das überharte Attackieren des besten Gegenspielers ist implizit normabweichend.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-079","thema":"B.L19","kapitel":"Aggression","q":"Erläutere das Klassifikationsraster aggressiver und nicht aggressiver Handlungen nach Gabler (Tab. 19.1) und begründe, warum zwei Zellen leer bleiben.","a":"Zeilen: Norm (entsprechend = nicht aggressiv; implizit/explizit abweichend = aggressiv); Spalten: Regel (entsprechend; implizit/explizit abweichend).\n• Leer: normabweichend + explizit regelabweichend, weil wer schädigen will, dies verdeckt tut und keinen sichtbaren Regelverstoß beabsichtigt","e":"Das Raster kombiniert zwei Fragen: Weicht die Handlung von der Fairness-Norm ab, und wie verhält sie sich zum Regelwerk? Handball-Beispiele: normentsprechend sind zufälliges Berühren der Wurfhand, Klammern des Kreisläufers und das taktische Foul; implizit normabweichend der Einschüchterungswurf auf den Torwartkopf und das überharte Attackieren des besten Spielers; explizit normabweichend der Kopfwurf mit Schädigungsabsicht und das Revanchefoul. Beispiel: Ein taktisches Foul in der Schlussphase im Basketball ist ein absichtlicher Regelverstoß, aber völlig normal und damit nicht aggressiv.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-080","thema":"B.L19","kapitel":"Aggression","q":"Unterscheide explizite und instrumentelle Aggression (nach Gabler).","a":"• Explizit: Ziel ist die personale Schädigung; offen oder verdeckt; = Gewalt\n• Instrumentell: Ziel ist Leistungsverbesserung, Schädigung wird in Kauf genommen; zentrales Problem des Sports","e":"Bei der expliziten Aggression ist das Wehtun das Ziel, bei der instrumentellen nur das Mittel zum Zweck. Explizite Aggression kann sich auch gegen Schiedsrichter, Trainer oder Zuschauer richten. Instrumentelle Aggression ist so problematisch, weil sie oft verdeckt und mehr oder minder regelgerecht erfolgt und von Trainern, Mitspielern oder Zuschauern teils sogar erwartet wird. Beispiel: Der Faustschlag nach einem Foul ist explizit, das rücksichtslose Hineingrätschen, um den Ball zu erobern, oder das angezogene Knie beim Sprungwurf ist instrumentell.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-081","thema":"B.L19","kapitel":"Aggression","q":"Nenne und erläutere die drei äußeren Erscheinungsformen aggressiver Handlungen.","a":"• Körperlich: mit Körperteilen oder Sportgeräten\n• Verbal: Beleidigen, Fluchen, Drohen\n• Symbolisch: Gesten, z. B. Drohen mit der Faust, abfällige Handbewegungen","e":"Aggression kann man mit dem Körper, mit Worten oder mit Gesten zeigen; Ziel der verbalen Aggression ist die persönliche Herabsetzung von Gegner, Mitspieler oder Schiedsrichter. Beispiel aus dem Buch: Ein gefoulter Fußballer zeigt dem Verteidiger einen Vogel (symbolisch), drückt ihn mit der Brust weg (körperlich) und beschimpft ihn (verbal).","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-082","thema":"B.L19","kapitel":"Aggression","q":"Was versteht man unter Assertivität im Sport und wie grenzt sie sich von Aggression ab?","a":"Assertivität: selbstbehauptendes, sich durchsetzendes Verhalten im Rahmen von Normen und Regeln (Schlicht & Strauß).\n• Abgrenzung: keine Schädigungsabsicht; Aggression zielt auf Schädigung bzw. nimmt sie in Kauf","e":"Assertive Handlungen wirken vermeintlich aggressiv, werden in der Sportart aber nicht so wahrgenommen. Im Einzelfall liegen beide nah beieinander, Sportler müssen die Grenze lernen. Assertiv heißt: Ich setze mich durch, ohne dir zu schaden. Beispiel: Ein Center, der unter dem Korb mit vollem Körpereinsatz seine Position behauptet, ist assertiv; hebt er dabei absichtlich den Ellbogen ins Gesicht des Gegners, wird es aggressiv.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-083","thema":"B.L19","kapitel":"Aggression","q":"Was versteht man unter Autoaggression im Sport?","a":"Aggressive Handlung gegen die eigene Person.\n• z. B. Doping, Rauschmittel, Essstörungen\n• oft gestörtes Körperbild als Ursache","e":"Aggression muss sich nicht gegen andere richten, man kann sich auch selbst schaden. Der Dopingsünder ist zugleich Täter und Opfer, weil er den eigenen Körper schädigt. Mädchen und Frauen zeigen eher autoaggressives Verhalten als Jungen und Männer. Beispiel: Eine Turnerin, die sich für ein niedriges Wettkampfgewicht krankhaft herunterhungert, verhält sich autoaggressiv.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-084","thema":"B.L19","kapitel":"Aggression","q":"Vergleiche die Aggressionsdefinition von Tiedemann mit der von Gabler.","a":"• Tiedemann: Aggression = stammesgeschichtliches Affekt-Muster (Angriff statt Flucht), wertneutral, im Sport notwendig; Umgang damit erlernbar\n• Gabler: Aggression an Schädigungsabsicht und Normabweichung gebunden, negativ; normgerechtes Durchsetzen = Assertivität","e":"Für Tiedemann ist Aggression eine Energie, die man gut oder schlecht nutzen kann: Sie ist kulturell in Grenzen formbar, und Ziel ist ein sauberer Zweikampf mit Aggressivität, aber ohne Gewalt. Die Frage angeboren oder erworben hält er für falsch gestellt. Gablers Sicht ist die gängige Lehrmeinung. Beispiel: Ein Boxer, der entschlossen angreift, ist bei Tiedemann aggressiv, aber nicht gewalttätig; bei Gabler wäre er assertiv, solange er regel- und normgerecht kämpft.","quelle":"L19.1","typ":"kern"},{"id":"bonus.b-085","thema":"B.L19","kapitel":"Aggressionstheorien","q":"In welche Gruppen lassen sich die Theorien zur Entstehung von Aggression einteilen?","a":"Nach Schlicht & Strauß:\n• Individuumsbezogen (Trieb, Frustration-Aggression, soziales Lernen)\n• Gruppenbezogen (Deindividuation, emergente Normen, Gruppenkonflikte, bloße Zugehörigkeit)\n• Gesellschaftsbezogen (soziale Schicht, Desintegration)\n• Motivationspsychologisch","e":"Man kann Aggression beim Einzelnen, in der Gruppe, in der Gesellschaft oder in der Motivation suchen (Zielorientierung, Risikowahlmodell, Attribution). Jede Theorie erklärt nur einen Teil des vielfältigen Phänomens. Beispiel: Randale von Fußballfans lässt sich durch Gruppeneffekte erklären, ein einzelnes Revanchefoul eher durch Frustration oder Motivanregung.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-086","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Erläutere die genetischen Ansätze (Trieb-/Instinkttheorie) zur Entstehung von Aggression.","a":"• Freud, Lorenz: Aggression ist angeboren, unvermeidbar\n• staut sich als innerer Spannungszustand auf\n• Katharsishypothese: Abbau durch aggressives Verhalten (Sport als Ventil)","e":"Nach dieser Vorstellung ist Aggression wie Dampf in einem Kessel, der irgendwann raus muss. Kritik: Die Katharsishypothese ist empirisch kaum belegt, Ausleben von Aggression kann sie eher verstärken. Beispiel: Die Idee, dass Kampfsport aggressive Jugendliche friedlicher macht, weil sie dort Dampf ablassen, beruht auf der Katharsishypothese.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-087","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Erläutere die Frustrations-Aggressions-Theorie und ihre Weiterentwicklung.","a":"• Dollard et al. (1939): jede Aggression folgt auf Frustration, Frustration führt immer zu Aggression\n• Berkowitz (1962): Frustration kann zu Aggression führen; aggressive Hinweisreize erhöhen das Potenzial\n• Kritik: zu einseitig, ignoriert Bewertungen und instrumentelle Aggression","e":"Frustration ist das Erlebnis von Enttäuschung oder der Störung einer zielgerichteten Aktivität. Wer an seinem Ziel gehindert wird, wird wütend, so die Grundidee. Aber Frustration kann auch zu Rückzug oder mehr Anstrengung führen, und nicht jede Aggression beruht auf Frustration. Beispiel: Ein Stürmer, dem ein klarer Elfmeter verweigert wird, foult kurz danach seinen Gegenspieler; aggressive Hinweisreize wären etwa gegnerische Fans mit Schalke-Trikots im Dortmunder Fanblock.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-088","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Erläutere die soziale Lerntheorie der Aggression nach Bandura.","a":"Bandura (1973): Aggression ist erlernt, nicht angeboren.\n• Lernen am Modell (v. a. erfolgreiche Vorbilder)\n• Lernen am Erfolg (Verstärkung)\n• daher auch verlernbar","e":"Kinder machen nach, was sie sehen, besonders wenn es sich lohnt; Vorbilder sind z. B. Profisportler, Trainer und Eltern. Faire Vorbilder und konsequente Sanktionen wirken entgegen. Beispiel: Ein Jugendspieler sieht im Fernsehen, wie ein Profi mit einer Schwalbe einen Elfmeter herausholt und gefeiert wird, und probiert das am Wochenende selbst aus.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-089","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Nenne die gruppenbezogenen Theorien der Aggressionsentstehung mit Vertretern und Kernaussagen.","a":"• Deindividuation (Zimbardo): Anonymität in der Masse\n• Emergente Normen (Turner & Killian): situativ entstehende Gruppennormen\n• Realistische Gruppenkonflikte (Sherif): konkurrierende Gruppenziele\n• Bloße Zugehörigkeit (Tajfel): schon Gruppenmitgliedschaft führt zu Diskriminierung","e":"In der Gruppe verhalten sich Menschen anders als allein. Nach Sherif reduzieren kooperative Handlungen zwischen Gruppen die Aggression. Jahreszahlen: Zimbardo 1969, Turner & Killian 1972, Sherif et al. 1955, Tajfel 1978. Beispiel: Ein vermummter Fan im Block zündet Pyrotechnik, was er allein nie täte (Deindividuation); bei einem Derby führen die konkurrierenden Ziele beider Fangruppen zu Feindseligkeiten (realistische Gruppenkonflikte).","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-090","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Nenne die gesellschaftsbezogenen Theorien der Aggressionsentstehung mit Vertretern und Kernaussagen.","a":"• Soziale Schicht (Geiger, 1932): Schicht und Lebensstil prägen die Einstellung zu Aggression\n• Desintegration (Heitmeyer, 1995): soziale Desintegration → Gewalt als Kompensation von Perspektivlosigkeit","e":"Hier sucht man die Ursachen in den Lebensumständen der Gesellschaft. Beispiel: Junge Männer ohne Ausbildung und Zukunftsperspektive finden in gewaltbereiten Fangruppen Anerkennung und Zugehörigkeit, die ihnen sonst fehlt (Desintegrationsansatz).","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-091","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Nenne die motivationspsychologischen Theorien der Aggressionsentstehung mit Vertretern und Kernaussagen.","a":"• Zielorientierungstheorie (Nicholls, 1984): Egoorientierte neigen eher zu Aggression und Unfairness\n• Risikowahlmodell/Attributionstheorien (Konrath, 1982; Gabler, 2002): Aggression als Ergebnis der Motivanregung aus Aggressions- und Hemmungstendenz","e":"Diese neueren Ansätze übertragen die Erkenntnisse der Leistungsmotivation auf Aggression. Aufgabenorientierte zeigen eher positives sportliches Benehmen; bei der Aggressionsmotivanregung spielen Absichtsattribution und affektive Prozesse eine besondere Rolle. Beispiel: Ein Spieler, der unbedingt gewinnen will (egoorientiert), ist eher bereit, den Gegner umzutreten, als einer, der vor allem gut spielen möchte.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-092","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Erläutere das Prozessmodell der Aggressionsmotivation (nach Konrath bzw. Beckmann et al.).","a":"Motiv aus Aggressionstendenz (aufsuchend) und Hemmungstendenz (meidend).\n1. Frustration regt Motiv an\n2. Absichtsattribution\n3. Affekt (Ärger, Wut)\n4. Aktivierung beider Tendenzen\n5. Überwiegt die Aggressionstendenz → Handlung, sonst Hemmung\n6. Zielerreichung → Deaktivierung","e":"Das Aggressionsmotiv ist wie das Leistungsmotiv zweiteilig aufgebaut. Es ist ein inneres Tauziehen zwischen Wut und Selbstbeherrschung. Beispiel aus dem Buch: Ein Angreifer wird zum dritten Mal vom selben Verteidiger gefoult und unterstellt Absicht; ist er schon gelb vorbelastet, siegt die Hemmung und er schimpft nur; ist er reizbar und die Stimmung aufgeheizt, schubst er den Verteidiger; zeigt der Schiedsrichter dem Verteidiger Gelb, beruhigt er sich.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-093","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Welche Bedeutung hat die Absichtsattribution im Prozessmodell der Aggressionsmotivation?","a":"Bewertung, ob dem Verursacher einer Schädigung Absicht unterstellt wird.\n• bestimmt Art und Stärke von Ärger/Wut\n• keine Absicht unterstellt → geringer Ärger, Aggression unwahrscheinlich","e":"Ob man sich rächt, hängt davon ab, ob man glaubt, es war Absicht. Hinweise dafür sind die Wiederholung eines Fouls, das bisherige Verhalten von Gegenspieler oder Mannschaft, der Ruf des Spielers und die Spielsituation. Beispiel: Ein erstes, unglückliches Foul nimmt ein Stürmer mit Ärger hin; tritt derselbe Verteidiger ihn auch an der Mittellinie um, unterstellt er Absicht und wird wütend.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-094","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Beschreibe das erweiterte Prozessmodell zum Ablauf einer Aggressionssituation nach Gabler (Abb. 19.2).","a":"Person (Aggressivität) + Situation →\n• Situationsbewertung (Ärger, Wut) → Aggressionstendenz\n• Bewertung erwarteter Folgen (Hoffnung, Furcht) → Entschluss\n• aggressive Handlung\n• Bewertung der Folgen (Befriedigung/Abreaktion)","e":"Gabler erweiterte Konraths Modell um handlungsbegleitende Emotionen, Handlungskontrolle und Selbstbewertung; es ähnelt seinem Leistungsmotivationsmodell: abwägen, handeln, bewerten. Beobachtbar ist nur die Handlung; Emotionen erkennt man an Ausdruck, Physiologie und Befragung, kognitive Prozesse nur über Selbstaussagen. Beispiel: Zidane wird von Materazzi beleidigt (Situation, Wut), wägt kaum Folgen ab, entschließt sich zum Kopfstoß und muss danach mit der Roten Karte leben.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-095","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Vergleiche die Frustrations-Aggressions-Theorie nach Dollard mit der motivationstheoretischen Erklärung nach Gabler und zeige, welche Schwächen Gablers Ansatz behebt.","a":"• Dollard: monokausal, Frustration → immer Aggression; erklärt keine instrumentelle Aggression, ignoriert Bewertungen und Hemmungen\n• Gabler: Frustration nur ein Auslöser; Absichtsattribution, erwartete Folgen, Emotionen; Aggressions- vs. Hemmungstendenz; Person und Situation berücksichtigt","e":"Dollard sieht einen Automatismus, Gabler einen Abwägungsprozess. Dadurch erklärt Gabler, warum dieselbe Frustration bei verschiedenen Personen oder in verschiedenen Situationen (z. B. Gelbe Karte, Spielstand) unterschiedlich wirkt. Beispiel Revanchefoul: Nach Dollard foult der gefoulte Spieler zurück, weil er frustriert ist; nach Gabler nur dann, wenn er Absicht unterstellt, die Folgen (Rote Karte) geringer gewichtet und seine Wut die Hemmung übersteigt.","quelle":"L19.5","typ":"zusatz"},{"id":"bonus.b-096","thema":"B.L19","kapitel":"Aggressionstheorien","q":"Erläutere den Zusammenhang zwischen Zielorientierung und Aggressionsneigung im Sport.","a":"• Egoorientierte neigen eher zu Aggression und Unfairness (andere übertreffen; Machtmotiv)\n• Aufgabenorientierte eher zu fairem Verhalten (sich verbessern; Leistungsmotiv)\n• Beleg: Duda et al. (1991), Basketball","e":"Aufgabenorientierte nutzen individuelle und sachliche Bezugsnormen und verbinden Erfolg mit Anstrengung; Egoorientierte sehen im Erfolg Chancen auf sozialen Aufstieg und Geld. Studien in Eishockey, Handball und Fußball bestätigen den Zusammenhang. Wer nur gewinnen will, dem ist jedes Mittel recht. Beispiel: Ein Basketballer, dem nur der Sieg zählt, foult in der Schlussphase hart, während ein aufgabenorientierter Spieler versucht, mit sauberer Verteidigung zu bestehen.","quelle":"L19.2","typ":"kern"},{"id":"bonus.b-097","thema":"B.L19","kapitel":"Fairness","q":"Definiere Fairness im Sport.","a":"Moralische Haltung, durch die Reglement und sportliche Einstellung gewahrt werden; sie sichert aus eigenem Antrieb den Sinn von Wettkampf und Spiel (Court).\n• Geist der Regeln, Schiedsrichterurteile, Chancengleichheit/-gerechtigkeit, Achtung aller als Person","e":"Fairness geht über das bloße Einhalten konstitutiver und strategischer Regeln hinaus. Fair ist nicht nur, wer keine Regeln bricht, sondern wer den Sinn des Spiels respektiert. Beispiel: Katrin Green setzte sich dafür ein, dass ihre stärkste Konkurrentin mit ihren Spikes laufen durfte, obwohl sie dadurch selbst nur Silber gewann.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-098","thema":"B.L19","kapitel":"Fairness","q":"Was ist mit dem Geist der Regeln gemeint?","a":"Handeln nach Sinn und Zweck der Regeln, nicht nur nach ihrem Buchstaben, auch in Situationen, die die Regeln nicht erfassen (von Weizsäcker).","e":"Regeln können nie alle Situationen abdecken; in offenen Situationen soll man so handeln, wie es dem Sinn des Wettkampfs entspricht: Chancengleichheit, Unversehrtheit, Achtung des Gegners. Beispiel: Kein Regelwerk verlangt, den Ball ins Aus zu spielen, wenn ein Gegner verletzt am Boden liegt; wer es trotzdem tut, handelt im Geist der Regeln.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-099","thema":"B.L19","kapitel":"Fairness","q":"Erläutere die drei zentralen Kriterien der Fairness: Regeleinhaltung, Chancengleichheit und Achtung des Gegners.","a":"• Regeleinhaltung: Regeln und ihren Geist beachten\n• Chancengleichheit: gleiche Siegchancen, keine Vorteile jenseits der Regeln\n• Achtung des Gegners: Spielpartner, nicht Feind","e":"Eigene taktische und technische Überlegenheit darf im Rahmen der Regeln voll ausgeschöpft werden (strategische Regeln). Das Spiel braucht funktional einen unverletzten Gegner, und Regelwerke enthalten moralische Werte, deshalb werden grobe Fouls und Beleidigungen hart bestraft. Beispiel: Ein Kampfrichter, der nach Ansicht einer Fotoserie einen fälschlich ungültig gegebenen Kugelstoßversuch von David Storl doch wertet, sorgt für Chancengleichheit.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-100","thema":"B.L19","kapitel":"Fairness","q":"Nenne die Aspekte von Fairness im erweiterten Sinne (Abb. 19.4).","a":"• Konstitutive Regeln einhalten\n• Strategische Regeln beachten\n• Sportidee berücksichtigen\n• Geist der Regeln achten\n• Schiedsrichterurteile befolgen\n• Chancengleichheit garantieren\n• Chancengerechtigkeit anstreben\n• Gegner und Schiedsgericht als Person achten","e":"Die Aspekte überlappen sich teilweise und gehen vom reinen Regelbefolgen bis zur menschlichen Haltung. Fairness betrifft nicht nur Sportler, sondern auch ihr Umfeld: Kampfrichter, Zuschauer, Fotografen. Sportidee heißt: das Spiel mit seiner Idee wirklich spielen wollen. Beispiel: Badmintonspielerinnen, die 2012 absichtlich verloren, hielten zwar die konstitutiven Regeln ein, verletzten aber die Sportidee, weil sie gar nicht gewinnen wollten.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-101","thema":"B.L19","kapitel":"Fairness","q":"Unterscheide formelle und informelle Fairness (nach Lenk).","a":"• Formell: Einhalten der Spielregeln; durch Sanktionen erzwingbar\n• Informell: Ritterlichkeit, Achtung von Gegner und Schiedsrichter; nicht erzwingbar\n(nach Lenk)","e":"Formell fair ist, wer nicht foult; informell fair, wer dem Gegner aufhilft. Gabler sieht schon das bewusste, konsequente Einhalten der Regeln, auch unter erschwerten Bedingungen, als Kern der Fairness. Beispiel: Ein Tennisspieler, der einen falschen Aus-Ruf des Linienrichters zu seinen Ungunsten korrigiert, zeigt informelle Fairness.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-102","thema":"B.L19","kapitel":"Fairness","q":"Unterscheide Chancengleichheit und Chancengerechtigkeit im Sport und setze sie in Beziehung zur Fairness.","a":"• Chancengleichheit: formal gleiche Wettkampfbedingungen, keine Vorteile jenseits der Regeln\n• Chancengerechtigkeit (Rawls, Loland): Ausgleich unverschuldeter, unkontrollierbarer Ungleichheiten (z. B. Körpergewicht)\n• Beides sind Aspekte der Fairness","e":"Gleichheit heißt: gleiche Regeln für alle; Gerechtigkeit heißt: unverschuldete Nachteile ausgleichen. Gleiche Vorbereitungsbedingungen sind bei ungleichen Ressourcen (Budget, Technik, Material) kaum erreichbar. Zugleich soll Wettkampf gerade Leistungsungleichheit sichtbar machen (Null-Summen-Spiel, Gabler). Beispiel: Im Hochsprung springen alle über dieselbe Latte (Chancengleichheit); Gewichtsklassen im Boxen oder ein Draft-System wie in der NBA gleichen dagegen unverschuldete Unterschiede aus (Chancengerechtigkeit).","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-103","thema":"B.L19","kapitel":"Fairness","q":"Erläutere die Einordnung sportlicher Handlungen auf einem Kontinuum zwischen fair und unfair (nach Gabler, Tab. 19.3).","a":"• Fair: Regeln, Chancengleichheit und Gegner bewusst achten\n• Neutral: regelentsprechend oder regelwidrig, aber normentsprechend (z. B. normales Foul)\n• Unfair (normabweichend): aggressiv (Revanchefoul) oder betrügerisch (Schwalbe, Doping)\n→ Nicht fair ≠ unfair","e":"Zwischen fair und unfair gibt es eine große neutrale Mitte. Aggressiv unfair ist bewusst schädigendes oder Schaden in Kauf nehmendes Verhalten; betrügerisch unfair ist ein Verstoß gegen die Chancengleichheit, etwa durch Spielmanipulation oder Wettbetrug. Beispiel Volleyball: Akzeptiert ein Spieler eine knappe Schiedsrichterentscheidung zu seinen Gunsten, ist das weder fair noch unfair; korrigiert er sie freiwillig zu seinem Nachteil, ist es fair.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-104","thema":"B.L19","kapitel":"Fairness","q":"Wie hängen Fairness und Motivation zusammen?","a":"• Intrinsisch: fair um der Fairness willen → sittlich gut\n• Extrinsisch: fair wegen Folgen (Lob, Preis, Strafvermeidung) → nur sittlich richtig","e":"Entscheidend ist, warum jemand fair ist: Die Bewertung einer fairen Handlung hängt von ihrer Motivation ab. Beispiel: Ein Spieler, der ein Handspiel zugibt, weil er es richtig findet, handelt intrinsisch fair; einer, der es nur zugibt, weil die Kamera ihn ohnehin überführt, handelt extrinsisch.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-105","thema":"B.L19","kapitel":"Fairness","q":"Warum ist faires Handeln aus der Außenperspektive oft nicht feststellbar? Nenne die Einflussfaktoren.","a":"Fairness hängt von Kontext und Gesinnung ab. Einflussfaktoren (Gabler, Loland):\n• Erfolgsdruck\n• Innenperspektive des Sportlers\n• Innenperspektive der Sportart\n• situative Zwänge\n• Chancengleichheit/-gerechtigkeit","e":"Faires Handeln muss immer im Kontext sportartspezifischer Regeln und Normen, der Situation und der Gesellschaft bewertet werden. Was von außen fair aussieht, muss innerlich nicht fair gemeint sein, und dieselbe Handlung kann je nach Sportart unterschiedlich bewertet werden; der Erfolgsdruck entsteht v. a. durch Kommerzialisierung. Beispiel: Alpay Özalan bekam den UEFA-Fair-Play-Preis, weil er einen Stürmer nicht foulte, sagte aber selbst, er hätte foulen müssen und sei nur zu spät gewesen.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-106","thema":"B.L19","kapitel":"Fairness","q":"Erläutere, wie Erfolgsdruck, die Innenperspektive einer Sportart und situative Zwänge die Beurteilung von Fairness beeinflussen.","a":"• Erfolgsdruck: erschwert faire Entscheidungen; Pilz: Unfairness wird dann sinnhaft\n• Sportart: Normen sind sportartspezifisch (z. B. Windschattenfahren im Radsport)\n• Situative Zwänge: z. B. feststehender Meister schont Kräfte und benachteiligt Dritte","e":"Fairness ist nicht in jeder Sportart und Situation gleich zu bewerten. Pilz hält es für unredlich, Fairplay einzufordern, solange der Erfolgsdruck nicht gemindert wird. Im Radsport darf ein Ausreißer bei einer Etappe im Windschatten fahren und am Ende vorbeiziehen, beim Eintagesrennen gilt Abwechseln in der Führung als fair. Beispiel: Ein Bundesligist, der vor dem Champions-League-Finale mit der B-Elf antritt, verschenkt Punkte an einen Abstiegskandidaten, was für dessen Konkurrenten unfair wirkt.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-107","thema":"B.L19","kapitel":"Fairness","q":"Wo stößt der Fairnessbegriff im Sport an seine Grenzen?","a":"• Profisport: ungleiche Ressourcen → Spannung zwischen Fairness und Chancengleichheit/-gerechtigkeit\n• Jugendsport: Erfolgsdruck und Egoorientierung erschweren Fairnesserziehung\n• Fair-Play-Auszeichnungen können Scheinmoral sein","e":"Wo viel Geld im Spiel ist, wird Fairness schnell zum Luxus: Budget, Technik und Material sind ungleich verteilt. Auszeichnungen, die etwa nur Gelbe Karten zählen, verfehlen den Kern (Fair is foul, and foul is fair). Beispiel: Kolumbien erhielt 2014 den FIFA-Fair-Play-Preis wegen weniger Gelber Karten, obwohl ein Kolumbianer mit einem brutalen Foul Neymar verletzt hatte.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-108","thema":"B.L19","kapitel":"Fairness","q":"Was bedeutet Fairness der Zuschauer?","a":"• Parteilichkeit in Grenzen (Anfeuern) ist normgerecht\n• Unfair, wenn sie die Chancengleichheit beeinträchtigt (Auspfeifen)\n• Fair: Leistungen aller Athleten unterstützen","e":"Auch das Publikum kann fair oder unfair sein, gerade bei Heimspielen beeinflussen Zuschauer die Chancengleichheit. Beispiel: Wenn Zuschauer beim Freiwurf des Gegners pfeifen und kreischen, stören sie die Chancengleichheit; applaudieren sie auch einem gelungenen Spielzug des Gegners, verhalten sie sich fair.","quelle":"L19.3","typ":"kern"},{"id":"bonus.b-109","thema":"B.L19","kapitel":"Fairness","q":"Nimm kritisch Stellung zur Fairnessdefinition von Heringer.","a":"Heringer: Fair ist, was nicht unfair ist; unfair ist, was den Witz des Spiels (gemeinsam spielen und durch Spielen gewinnen) zerstört.\n• Stärke: bindet Fairness an die Sportidee\n• Kritik: keine neutrale Kategorie, kein Unterschied zu informeller Fairness, Gegnerachtung fehlt","e":"Heringers Definition ist elegant, sie erfasst z. B. absichtliches Verlieren oder Manipulation als unfair. Aber sie macht jeden zum fairen Sportler, der nur nicht stört: Vorbildliches faires Verhalten wird nicht von bloß regelkonformem unterschieden, Chancengerechtigkeit fehlt ebenfalls. Beispiel: Ein normales Foul im Handball zerstört den Witz des Spiels nicht, wäre bei Heringer also fair, während Gabler es als neutral einstuft.","quelle":"L19.3","typ":"zusatz"},{"id":"bonus.b-110","thema":"B.L19","kapitel":"Fairnesserziehung","q":"In welchem Verhältnis stehen Aggressionsvermeidung und Fairnesserziehung?","a":"Zwei Seiten einer Medaille mit dem Ziel eines ethisch guten Sports: Untugenden unterlassen (Aggressionsvermeidung) und Tugenden fördern (Fairnesserziehung) (Gabler).","e":"Die eine Seite verhindert Schlechtes, die andere fördert Gutes; beides muss pädagogisch gefordert und gefördert werden. Beispiel: Ein Jugendtrainer bestraft Revanchefouls konsequent (Aggressionsvermeidung) und lobt gleichzeitig Spieler, die dem Gegner aufhelfen (Fairnesserziehung).","quelle":"L19.4","typ":"kern"},{"id":"bonus.b-111","thema":"B.L19","kapitel":"Fairnesserziehung","q":"Nenne Programme und Ansätze zur Aggressionsvermeidung im Sport.","a":"Prävention plus klare Definition und konsequente Sanktion. Programme:\n• Schulprogramme (bewegte/gesunde Schule)\n• Streitschlichter\n• Stressmanagement\n• therapeutische Ansätze\n• Projekte Gewalt und Sport\n• Fanprojekte","e":"Weil Aggression viele Ursachen hat, braucht es viele Gegenmittel. Stressmanagement nutzt z. B. Muskelentspannung und Copingstrategien, therapeutisch etwa kognitive Verhaltenstherapie. Beispiel: Fanprojekte arbeiten mit jugendlichen Fußballfans, um Gewalt im Stadion vorzubeugen, während Streitschlichter in der Schule Konflikte schon im Sportunterricht entschärfen.","quelle":"L19.4","typ":"kern"},{"id":"bonus.b-112","thema":"B.L19","kapitel":"Fairnesserziehung","q":"Welche Empfehlungen gibt die International Society of Sport Psychology (ISSP) zur Vermeidung von Aggression im Sport?","a":"• Strikte Bestrafung\n• Fairnesserziehung ab dem Jugendalter\n• realistischer Umgang der Medien mit Aggression\n• Fortbildung aller Akteure\n• Anti-Aggressions-Programme für alle\n• Alkoholverbot bei Veranstaltungen","e":"Die ISSP setzt bei allen Beteiligten an, nicht nur bei den Spielern, sondern auch bei Trainern, Managern und Medien. Beispiel: Wenn Medien eine Rudelbildung nicht als spektakuläres Highlight in Endlosschleife zeigen, wird Aggression weniger als cool vermittelt.","quelle":"L19.4","typ":"kern"},{"id":"bonus.b-113","thema":"B.L19","kapitel":"Fairnesserziehung","q":"Nenne Gablers Leitlinien zur Aggressionsvermeidung in der Schule und die beiden Sanktionsformen.","a":"Leitlinien (Gabler, 1996):\n• Aggression definieren und nach Schwere klassifizieren\n• Regeln mit Schülern aufstellen und begründen\n• Sanktionen konsequent durchführen\n• Täter trägt die Konsequenzen\nSanktionen: repressive Bestrafung; Wiedergutmachung/Versöhnung","e":"Regeln wirken besser, wenn die Schüler sie selbst mitgestaltet haben. Bei der Wiedergutmachung missbilligt der Täter seine Tat und stellt so Normvertrauen und Ordnung wieder her. Beispiel: Wer im Sportunterricht absichtlich einen Mitschüler umrennt, setzt aus (repressiv) oder entschuldigt sich und hilft beim Kühlen (Wiedergutmachung); bei schweren oder wiederholten Taten ist eher Strafe angezeigt, bei spontanen leichteren eher Versöhnung.","quelle":"L19.4","typ":"kern"},{"id":"bonus.b-114","thema":"B.L19","kapitel":"Fairnesserziehung","q":"Wie sind Fairnessprojekte und moralische Kampagnen im Sport zu bewerten?","a":"• Zunehmende Fairnessprojekte wegen Doping, Schwalben, instrumenteller Aggression\n• Erfolg rein moralischer Kampagnen fraglich\n• Erfolge im Kleinen ermutigen (z. B. Berliner Mini-Liga mit Verhaltenskodex)","e":"Ein Beispiel für eine große Kampagne ist Gemeinsam gegen Doping des DOSB: Aufklärung und moralischer Appell, ergänzt durch harte Strafen und Forschung zu Nachweisverfahren. Große Appelle verpuffen oft, kleine konkrete Regeln vor Ort wirken. Beispiel: In der Berliner Mini-Liga gilt für alle in der Halle (Trainer, Zuschauer, Spieler, Schiedsrichter) ein Kodex mit Respekt, Anerkennung der Schiedsrichterentscheidungen und Lernen aus Fehlern, und die Kinder spielen dort tatsächlich in fairer Atmosphäre.","quelle":"L19.4","typ":"kern"},{"id":"bonus.b-115","thema":"B.L19","kapitel":"Fairnesserziehung","q":"Warum kann eine hohe technisch-taktische Ausbildung mit starker Aufgabenorientierung zu einem ethisch guten Sport beitragen?","a":"• Automatisierte faire Lösungen auch unter Stress → unfaire Mittel überflüssig\n• variables Repertoire hilft, Konflikten/Verletzungen auszuweichen\n• Aufgabenorientierung als Gegengewicht zur Egoorientierung des Showsports","e":"Wer es technisch kann, muss nicht foulen. Assertives, regelgerechtes Durchsetzen bleibt Teil des Sports, Sportler müssen aber lernen, wo Assertivität endet und Aggression beginnt. Leistung wird bei Aufgabenorientierung als Streben nach der persönlichen Grenze verstanden. Beispiel: Ein Fußballverteidiger, der sauberes Tackling automatisiert hat, trennt den Gegner auch in der Nachspielzeit fair vom Ball; Dirk Nowitzki entzog sich mit seinem Fadeaway-Wurf dem harten Körperkontakt.","quelle":"L19.4","typ":"kern"},{"id":"bonus.b-116","thema":"B.L19","kapitel":"Fairness","q":"Erkläre, warum man beim Ins-Aus-Spielen des Balls bei einem verletzten Spieler im Fußball von Pseudofairness sprechen könnte.","a":"• Ritualisierte, erwartete Norm; Unterlassen wird sanktioniert → oft extrinsisch motiviert (sittlich richtig, nicht unbedingt gut)\n• taktisch missbrauchbar (vorgetäuschte Verletzung, Zeitschinden)\n• echte informelle Fairness wäre freiwillig","e":"Wenn alle es erwarten, ist es keine besondere Ritterlichkeit mehr: Die Geste wird mit Applaus belohnt und mit Rückgabe des Balls beantwortet, Zuschauer und Medien bestrafen das Unterlassen. Beispiel: Eine Mannschaft lässt sich in der Schlussphase bei knapper Führung auffällig oft fallen, weil sie weiß, dass der Gegner den Ball ins Aus spielen wird.","quelle":"L19.3","typ":"zusatz"},{"id":"bonus.c-001","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Wie wird der Begriff Gesundheit in der aktuellen Forschung verstanden?","a":"• mehrperspektivisch: körperlich, psychisch, sozial\n• dynamisch: verändert sich ständig\n• mehrdimensional: Kontinuum zwischen Polen statt „gesund oder krank“\n• Abkehr vom bloßen Freisein von Krankheit","e":"Früher hieß gesund einfach: nicht krank (eindimensionales Verständnis). Heute schaut man auf Körper, Psyche und soziales Leben gleichzeitig und weiß, dass sich Gesundheit ständig ändert. Man bewegt sich zwischen den Polen gesund und krank, statt entweder das eine oder das andere zu sein. Beispiel: Eine Schülerin mit gebrochenem Arm ist körperlich eingeschränkt, kann sich aber psychisch und sozial sehr gesund und wohl fühlen.","quelle":"L20.1","typ":"kern"},{"id":"bonus.c-002","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Nenne die Dimensionen von Gesundheit, die Alexa Franke (2012) unterscheidet.","a":"Gesundheit als …\n• Störungsfreiheit\n• Wohlbefinden\n• Leistungsfähigkeit/Rollenerfüllung\n• Gleichgewicht (Homöostase)\n• Flexibilität (Heterostase)\n• Anpassung\n• höchstes Gut\n• relativer Wert\n• Geschenk, Leistung oder Pflicht","e":"Franke zeigt, dass jeder etwas anderes meint, wenn er „gesund“ sagt. Für den einen heißt es, keine Beschwerden zu haben, für den anderen, im Job voll funktionieren zu können. Beispiel: Ein Leistungssportler versteht Gesundheit oft als Leistungsfähigkeit, eine ältere Person eher als Wohlbefinden und Schmerzfreiheit.","quelle":"L20.1","typ":"kern"},{"id":"bonus.c-003","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Erläutere die Gesundheitsdefinition der WHO und den dadurch ausgelösten Paradigmenwechsel.","a":"WHO (1946/48): „Zustand des völligen körperlichen, psychischen und sozialen Wohlbefindens und nicht nur das Freisein von Krankheit und Gebrechen.“\nParadigmenwechsel:\n• weg von Gesundheit = Abwesenheit von Krankheit\n• hin zu mehrdimensionalem, subjektivem Wohlbefinden","e":"Die Definition stammt aus der Gründungsakte der WHO von 1946, in Kraft trat sie 1948. Vor ihr war man gesund, wenn der Arzt nichts fand. Danach zählt auch, wie man sich fühlt und ob man sozial eingebunden ist: Das subjektive Erleben der Person rückt in den Mittelpunkt, Gesundheit wird zu einem individuellen Zustand. Beispiel: Jemand ohne Befund, der sich einsam und dauerhaft niedergeschlagen fühlt, gilt nach der WHO nicht als vollständig gesund.","quelle":"L20.1","typ":"kern"},{"id":"bonus.c-004","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Welche Dimension von Gesundheit betont die Ottawa-Charta der WHO (1986)?","a":"Die politische (gesellschaftliche) Dimension:\n• Gesundheit wird im Alltag geschaffen (für sich/andere sorgen, selbst entscheiden, Kontrolle über Lebensumstände)\n• Gesellschaft muss die Bedingungen dafür schaffen","e":"Die Ottawa-Charta sagt: Gesundheit wird von den Menschen in ihrem Alltag gelebt. Sie entsteht, wenn man für sich und andere sorgt, selbst Entscheidungen trifft und die eigenen Lebensumstände kontrollieren kann. Gesundheit ist damit nicht nur Privatsache, sondern auch Aufgabe von Politik und Gesellschaft. Beispiel: Eine Stadt, die sichere Radwege und Sportplätze baut, schafft Bedingungen, unter denen sich Menschen gesund verhalten können.","quelle":"L20.1","typ":"kern"},{"id":"bonus.c-005","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Wie beschreibt der Gesundheitspsychologe Peter Becker (2006) Gesundheit?","a":"Mehrdimensionaler Zustand, erfasst über Indikatoren:\n• subjektives Wohl-/Missbefinden\n• körperliche und psychische Leistungsfähigkeit\n• physiologische/biochemische Parameter\n• Verhaltensmerkmale\n• Anatomie und Aussehen\nEinstufung zwischen „zurzeit krank“ und „zurzeit gesund“","e":"Becker misst Gesundheit wie mit mehreren Messgeräten gleichzeitig: physiologische Parameter sind z. B. Blutdruck, Blutzucker oder Cortisol, Verhaltensmerkmale z. B. Essen, Schlafen und soziales Rollenverhalten, Anatomie und Aussehen z. B. Körperbau, Gewicht und Hautfarbe. Wichtig ist das Wort „zurzeit“: Gesundheit ist eine Momentaufnahme. Beispiel: Ein Schüler hat gute Blutwerte, schläft aber in der Abiturphase schlecht und fühlt sich gestresst. Er ist körperlich eher gesund, psychisch zurzeit eher eingeschränkt.","quelle":"L20.1","typ":"kern"},{"id":"bonus.c-006","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Wie definieren Hurrelmann und Richter (2013) Gesundheit?","a":"• Gleichgewichtszustand zwischen Anforderungen und Bewältigungsressourcen\n• dynamisch: durch wechselnde Anforderungen und Ressourcen ständig gestört, muss immer wieder neu stabilisiert werden","e":"Stell dir eine Waage vor: Auf der einen Seite liegen die Anforderungen des Alltags (Arbeit, Schule, Sport, Familie), auf der anderen deine Ressourcen (z. B. Fitness, Selbstkonzept, Einkommen). Weil sich beide Seiten ständig ändern, muss das Gleichgewicht in jeder Lebenslage neu hergestellt werden. Beispiel: In der Klausurphase steigen die Anforderungen; wer dann gut organisiert ist und Freunde zum Lernen hat, hält das Gleichgewicht.","quelle":"L20.1","typ":"kern"},{"id":"bonus.c-007","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Nenne die vier Kernaspekte der WHO-Gesundheitsdefinition von 1946 und erkläre, woraus sie sich ergeben.","a":"• subjektive Einschätzung („Wohlbefinden“)\n• Idealstatus („völliges“)\n• Mehrdimensionalität (körperlich, psychisch, sozial)\n• Gegenüberstellung Gesundheit vs. Krankheit („nicht nur das Freisein von Krankheit“)","e":"Man liest die Kernaspekte direkt aus den Wörtern der Definition ab. „Wohlbefinden“ kann nur die Person selbst beurteilen, „völlig“ steht für einen Idealzustand, die drei Bereiche für die Mehrdimensionalität. Durch „nicht nur das Freisein von Krankheit“ werden Gesundheit und Krankheit als Gegensätze (diametral) verstanden. Beispiel: Wer nach einer Trennung traurig ist, fühlt sich nicht „völlig“ wohl und wäre streng genommen nicht gesund.","quelle":"L20.3","typ":"kern"},{"id":"bonus.c-008","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Beurteile die WHO-Gesundheitsdefinition von 1946 kritisch.","a":"Stärken:\n• erstmals mehrdimensional\n• subjektives Befinden zählt\nSchwächen:\n• „völliges“ Wohlbefinden unerreichbar\n• statisch statt dynamisch\n• Dichotomie statt Kontinuum\n• kaum messbar, objektive Befunde vernachlässigt","e":"Die Definition war ein großer Fortschritt, aber sie ist zu streng: Wenn nur „völliges“ Wohlbefinden zählt, ist kaum jemand gesund. Außerdem bleiben Gesundheit und Krankheit Gegensätze, statt Pole eines Kontinuums zu sein. Weiterentwickelt wurde das Verständnis z. B. durch die Salutogenese (HEDE-Kontinuum) und das SAR-Modell. Beispiel: Ein Mensch mit gut eingestelltem Diabetes, der Sport treibt und glücklich lebt, wäre nach der WHO trotzdem nicht gesund – das wirkt unrealistisch.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"bonus.c-009","thema":"B.L20","kapitel":"Gesundheitsbegriffe","q":"Welche Gesundheitsmodelle sind medizinisch und welche sozialwissenschaftlich orientiert?","a":"Medizinisch:\n• Risikofaktorenmodell (pathogenetisch)\nSozialwissenschaftlich:\n• Salutogenesemodell (Antonovsky)\n• SAR-Modell (Becker)\n• Konzept zur Gesundheitsförderung (Beckers)","e":"Die Medizin fragt: Was macht krank? Die Sozialwissenschaften fragen: Was hält gesund und wie bewältigt man den Alltag? Beispiel: Ein Arzt misst den Blutdruck (Risikofaktor), ein Gesundheitspsychologe fragt nach Freunden, Selbstvertrauen und Stress (Ressourcen).","quelle":"L20.1","typ":"kern"},{"id":"bonus.c-010","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Beschreibe die Grundidee des Risikofaktorenmodells.","a":"• pathogenetische Sicht (vom kranken Menschen aus)\n• untersucht Risikofaktoren und Schutzfaktoren\n• Interventionen an diesen Faktoren verbessern die Gesundheit\n• in der Medizin am weitesten verbreitet","e":"Das Modell geht davon aus, dass sich Beschwerden aus ungünstigen körperlichen Bedingungen und der Lebenssituation ableiten lassen. Es sucht nach physischen und psychischen „Gefahrenquellen“ und nach Schutzfaktoren, die das Krankwerden verhindern. Greift man dort ein, verbessert sich die Gesundheit nachhaltig. Beispiel: Ein Arzt stellt Bluthochdruck, Übergewicht und Rauchen fest und rät zu Medikamenten, Gewichtsabnahme und Rauchstopp, um einen Herzinfarkt zu verhindern.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-011","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Definiere den Begriff Risikofaktor (nach Graf, 2012).","a":"Faktoren, die statistisch mit bestimmten Erkrankungen zusammenhängen und deren Entstehung begünstigen, ohne zwingend deren Ursache zu sein (kein Kausalzusammenhang).","e":"Risikofaktor heißt: Wer ihn hat, erkrankt statistisch häufiger, aber nicht zwingend. Beispiel: Rauchen, Bluthochdruck und Bewegungsmangel sind Risikofaktoren für Arteriosklerose; sie gelten nicht als alleinige Ursache, machen die Erkrankung aber deutlich wahrscheinlicher.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-012","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"In welche drei Gruppen lassen sich Risikofaktoren einteilen (nach Graf, 2012)?","a":"• konstitutionell (unveränderbar): Alter, Geschlecht, Herkunft, Genetik\n• extern (Verhalten/Lebensbedingungen): Rauchen, Bewegungsmangel, Fehlernährung\n• intern (bestehende Erkrankung): Bluthochdruck, Diabetes, Fettstoffwechselstörung","e":"Eselsbrücke: konstitutionell = angeboren, extern = selbst gemacht, intern = schon im Körper krank. Interne Risikofaktoren sind Zustände, die selbst schon eine innere Erkrankung sind und z. B. das Arterioskleroserisiko erhöhen. Beispiel: Ein 60-jähriger Mann (konstitutionell) raucht (extern) und hat hohen Blutdruck (intern) – er vereint alle drei Gruppen.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-013","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Nenne die wichtigsten externen und internen Risikofaktoren für Herz-Kreislauf-Erkrankungen.","a":"Extern:\n• Bewegungsmangel\n• Fehlernährung\n• Rauchen\nIntern:\n• Bluthochdruck\n• Diabetes\n• Fettstoffwechselstörung\n• Adipositas","e":"Die internen Faktoren treten oft in Kombination auf, und alle wirken mit Genetik, Umweltbedingungen und Stress zusammen. Bewegungsmangel ist besonders tückisch, weil er als Auslöser weiterer Risikofaktoren gilt. Beispiel: Wer sich kaum bewegt, nimmt leichter zu, bekommt dadurch eher hohen Blutdruck und erhöhte Blutfette.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-014","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Was versteht man im Risikofaktorenmodell unter Schutzfaktoren?","a":"Faktoren, die den Risikofaktoren gegenüberstehen und die Erkrankungsgefahr vermindern (z. B. sportliche Aktivität gegen Arteriosklerose).","e":"Schutzfaktoren sind das Gegengewicht zu den Risikofaktoren. Inhaltlich entsprechen sie den Widerstandsressourcen im Salutogenesemodell. Beispiel: Regelmäßiges Joggen senkt Blutdruck und Blutfette und schützt so vor Arteriosklerose – auch wenn jemand familiär vorbelastet ist.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-015","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Beschreibe die zwei Phasen in der Entwicklung des Risikofaktorenmodells (nach Franke, 2012).","a":"1. Phase (ab 1960er): Identifizieren der Risikofaktoren\n2. Phase: Erforschen, unter welchen Bedingungen Menschen risikoreiches Verhalten zeigen","e":"In der ersten Phase stellte man neben konstitutionellen Faktoren Zusammenhänge von Bluthochdruck, Übergewicht, Rauchen und Bewegungsarmut mit Erkrankungen fest. Dann merkte man: Das Wissen allein reicht nicht, die Leute ändern ihr Verhalten trotzdem nicht. Also fragt man, warum jemand zu viel isst, trinkt, raucht oder zu wenig Sport treibt. Beispiel: Fast jeder Raucher weiß, dass Rauchen schadet – die zweite Phase fragt, warum er trotzdem weiterraucht.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-016","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Erläutere den zentralen Kritikpunkt am Risikofaktorenmodell in Bezug auf das Gesundheitsverständnis.","a":"• wichtig für Behandlung und Prävention\n• aber: Gesundheit nur als Abwesenheit von Krankheit\n• Gesundheitsressourcen werden kaum beachtet","e":"Das Modell weiß sehr genau, was krank macht, aber kaum, was gesund hält. Deshalb trägt es wenig zu einem vertieften Gesundheitsverständnis, etwa im Sinne der WHO, bei. Beispiel: Es erklärt, warum Rauchen schadet, sagt aber nichts darüber, wie Freundschaften, Selbstvertrauen oder Freude an Bewegung die Gesundheit stärken.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-017","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Nenne weitere Kritikpunkte am Risikofaktorenmodell.","a":"• eindimensional: nur biomedizinisch, soziales Umfeld fehlt\n• Kluft zwischen Wissen und Verhaltensänderung\n• Statistik sagt wenig über den Einzelfall\n• Wegnahme von Risiken schafft nicht automatisch Gesundheit (Franke)","e":"Wissen über Risiken führt nicht automatisch zu Verhaltensänderung; gute Vorsätze werden schnell gebrochen. Weil Statistik wenig über den Einzelnen sagt, rechtfertigen Menschen ihr Risikoverhalten. Und Franke betont: „Eine Wegnahme negativer Faktoren muss nicht automatisch in Positivem resultieren.“ Beispiel: „Helmut Schmidt war Kettenraucher und wurde über 90“ – mit solchen Einzelfällen reden sich Raucher ihr Risiko klein.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-018","thema":"B.L20","kapitel":"Risikofaktorenmodell","q":"Erläutere am Beispiel des Herzinfarkts die Grundidee des Risikofaktorenmodells.","a":"• Risikofaktoren: z. B. Rauchen, Bluthochdruck, Fettstoffwechselstörung, Diabetes, Bewegungsmangel, Stress, Alter, Vererbung\n• erhöhen statistisch die Wahrscheinlichkeit, verstärken sich gegenseitig\n• Prävention: Risiken abbauen, Schutzfaktoren stärken","e":"Die Risikofaktoren (dazu auch Übergewicht und Geschlecht) verursachen den Infarkt nicht direkt, sondern begünstigen die Arteriosklerose der Herzkranzgefäße. Je mehr zusammenkommen, desto höher das Risiko – oft nicht nur addiert, sondern vervielfacht. Prävention heißt z. B. Rauchstopp, Blutdrucksenkung, Bewegung, gesunde Ernährung und Ausdauersport als Schutzfaktor. Beispiel aus dem Buch: Rauchen und die Pille erhöhen bei Frauen das Herzinfarktrisiko jeweils um das Zwei- bis Vierfache, zusammen um das Vierzigfache.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-019","thema":"B.L20","kapitel":"Salutogenese","q":"Was bedeutet Salutogenese und welcher Perspektivwechsel ist damit verbunden?","a":"Salutogenese (Antonovsky) = Entstehung von Gesundheit, Gegenbegriff zur Pathogenese.\nPerspektivwechsel: von der Krankheits- zur Gesundheitsdynamik – Was erhält und fördert Gesundheit?","e":"Der Begriff setzt sich zusammen aus Salus (Gesundheit) und Genese (Entstehung); Pathos heißt Krankheit. Die Leitfrage ändert sich von „Warum werden Menschen krank?“ zu „Warum bleiben Menschen trotz Belastungen gesund?“. Beispiel: Statt zu erforschen, warum Schüler im Abitur Burn-out bekommen, fragt man, was die Schüler stark macht, die den Stress gut wegstecken.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-020","thema":"B.L20","kapitel":"Salutogenese","q":"Nenne die wesentlichen Bestandteile des Salutogenesemodells nach Antonovsky.","a":"• Heterostase\n• Gesundheits-Krankheits-Kontinuum (HEDE-Kontinuum)\n• Stressoren und Widerstandsressourcen\n• Kohärenzgefühl (zentraler Bestandteil)","e":"Diese vier Bausteine solltest du sicher aufzählen können. Eselsbrücke: „Hilf Hede Stress kohärent bewältigen“ (Heterostase, HEDE, Stressoren/Ressourcen, Kohärenz). Beispiel: Ein Schüler erlebt Prüfungsstress (Stressor), hat Freunde und Wissen (Ressourcen), sieht einen Sinn im Abi (Kohärenz) und bleibt so näher am gesunden Pol (HEDE).","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-021","thema":"B.L20","kapitel":"Salutogenese","q":"Erläutere den Begriff Heterostase im Salutogenesemodell.","a":"• Heterostase = Ungleichgewicht (Gegenbegriff zur Homöostase)\n• Krankheit ist normaler Teil des Lebens, keine Abweichung\n• Ziel: Ungleichgewicht akzeptieren und überwinden","e":"In der Pathogenese ist Gesundheit der Normalzustand und Krankheit die Abweichung. Antonovsky sagt dagegen: Ungleichgewicht, Belastung und Krankheit gehören einfach zum Leben dazu. Entscheidend ist, wie man damit umgeht. Beispiel: Eine Erkältung im Winter ist kein Unfall, sondern normal – gesund ist, wer sich davon gut erholt und weitermacht.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-022","thema":"B.L20","kapitel":"Salutogenese","q":"Erläutere die Flussmetapher zum Salutogenesemodell.","a":"• Leben = Fluss mit Gefahren, in dem alle schwimmen (bis zum Wasserfall = Tod)\n• Pathogenese: rettet Ertrinkende\n• Salutogenese: fragt, wie Menschen gute Schwimmer werden","e":"Der Fluss hat Biegungen, Stromschnellen und Strudel; alle schwimmen von der Empfängnis bis zum Tod darin. Die Pathogenese tut so, als sei man meist an Land und müsse nur bei Krankheit ins Wasser – sie ist wie ein Rettungsschwimmer. Die Salutogenese sieht Heterostase, Krankheit und Tod als Teil des Lebens und ist wie ein Schwimmlehrer, der allen beibringt, den Fluss zu meistern. Beispiel: Ein Stressbewältigungskurs für alle Schüler entspricht dem Schwimmlehrer, eine Therapie nach einem Zusammenbruch dem Rettungsschwimmer.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-023","thema":"B.L20","kapitel":"Salutogenese","q":"Was versteht man unter dem HEDE-Kontinuum?","a":"Kontinuum zwischen den Polen „health-ease“ und „dis-ease“:\n• hebt die Dichotomie gesund/krank auf\n• Gesundheit als dynamische Position, je Dimension verschieden\n• Bewegung abhängig von Stressoren und ihrer Bewältigung","e":"Statt eines Lichtschalters (an = gesund, aus = krank) gibt es einen Dimmer zwischen „völlig gesund“ und „völlig krank“. Jeder steht irgendwo dazwischen und kann sich in beide Richtungen bewegen – je nachdem, wie er mit Stressoren umgeht. Beispiel: Ein Sportler mit Kreuzbandriss ist körperlich nahe am kranken Pol, kann psychisch und sozial aber weit am gesunden Pol stehen.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-024","thema":"B.L20","kapitel":"Salutogenese","q":"Nach welchen Kriterien wird die Position auf dem HEDE-Kontinuum bestimmt?","a":"Ganzheitlicher Befund aus:\n• objektiven Parametern (medizinische, psychologische, logopädische Befunde)\n• subjektiven Parametern (Befinden, Schmerzerleben, erlebte Funktionstüchtigkeit)\nfür jede Dimension getrennt","e":"Man schaut also nicht nur auf Laborwerte, sondern auch darauf, wie es sich für die Person anfühlt. Die Position kann in jeder Dimension verschieden sein. Beispiel: Zwei Menschen mit gleichem Röntgenbefund am Knie können ganz unterschiedlich stark Schmerzen haben und im Alltag eingeschränkt sein – sie stehen damit an verschiedenen Stellen.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-025","thema":"B.L20","kapitel":"Salutogenese","q":"Wie wird Krankheit aus salutogenetischer Sicht verstanden?","a":"• kein isolierter Systemausfall, sondern Prozess der „Ent-Gesundung“ (dis-ease) in der Lebensbiografie\n• nur aus der gesamten Lebenssituation verständlich\n• der Mensch ist immer auch teilweise gesund (Schutzfaktoren = gesunde Anteile)","e":"Der Betroffene ist kein bloßer „Krankheitsträger“; sein Krankwerden versteht man nur über seine innere und äußere Situation. Auch wer in einem Bereich nahe am kranken Pol steht, kann in anderen gesund sein. Die Salutogenese schaut deshalb auf den ganzen Menschen mit seiner Geschichte, nicht nur auf die Diagnose. Beispiel: Bei einer Läuferin mit Ermüdungsbruch fragt man auch nach Trainingsdruck, Ernährung und Lebensumständen, und man stärkt ihre gesunden Anteile wie Motivation und Unterstützung durch die Familie.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-026","thema":"B.L20","kapitel":"Salutogenese","q":"Welche Rolle spielen Stressoren im Salutogenesemodell?","a":"• Stressoren = Anforderungen ohne direkt verfügbare automatische Antwort (Antonovsky)\n• allgegenwärtig, nicht grundsätzlich schädlich\n• erfolgreiche Bewältigung (mit Widerstandsressourcen) bewegt Richtung gesunden Pol","e":"Ob Stress positiv oder negativ wirkt, hängt von der Art des Stressors und seiner Bewältigung ab. Stress ist hier nicht der Feind, sondern eine Chance zu wachsen – wenn man ihn bewältigt. Beispiel: Wer eine schwere Prüfung erfolgreich meistert, geht gestärkt daraus hervor und traut sich beim nächsten Mal mehr zu.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-027","thema":"B.L20","kapitel":"Salutogenese","q":"Was sind Widerstandsressourcen und wie werden sie eingeteilt (nach Franke, 2012)?","a":"Faktoren, die die Bewegung zum gesunden Pol ermöglichen.\n• gesellschaftlich: Stabilität, Frieden, intakte Sozialstrukturen\n• individuell: kognitiv, psychisch, physiologisch, ökonomisch-materiell","e":"Widerstandsressourcen entsprechen den Schutzfaktoren des Risikofaktorenmodells. Kognitive Ressourcen sind z. B. Wissen und Problemlösefähigkeit, psychische z. B. Selbstvertrauen, Ich-Identität und Optimismus, physiologische körperliche Stärken und Fertigkeiten, ökonomische z. B. Geld, finanzielle Sicherheit und ein sicherer Arbeitsplatz. Ressourcen sind wie ein Werkzeugkasten gegen Stress. Beispiel aus dem Buch: Eine alleinerziehende Mutter, die sich einen Babysitter leisten kann (ökonomische Ressource), gerät gar nicht erst in bestimmte Stresssituationen.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-028","thema":"B.L20","kapitel":"Salutogenese","q":"Was ist das Kohärenzgefühl und aus welchen drei Komponenten besteht es?","a":"Grundlegendes Vertrauen in sich und die Welt (Kern des Salutogenesemodells):\n• Verstehbarkeit\n• Handhabbarkeit\n• Bedeutsamkeit (Sinnhaftigkeit)","e":"Verstehbarkeit heißt, Ereignisse erscheinen geordnet und erklärbar. Handhabbarkeit heißt, man vertraut darauf, mit den Anforderungen umgehen zu können, weil Ressourcen verfügbar sind. Bedeutsamkeit heißt, die Anforderungen sind es wert, sich zu engagieren. Je stärker diese Überzeugung, desto näher am gesunden Pol des HEDE-Kontinuums. Eselsbrücke: „Verstehen – Können – Wollen“. Beispiel: Ein verletzter Sportler versteht, was passiert ist, weiß, dass er mit Physiotherapie wieder fit wird, und will unbedingt zurück ins Team.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-029","thema":"B.L20","kapitel":"Salutogenese","q":"Unter welchen Bedingungen entwickelt sich ein hohes Kohärenzgefühl?","a":"• subjektiv wichtige Lebensbereiche (Grenzen ziehen, Unwichtiges ausklammern)\n• nicht ausgeschlossen werden dürfen:\n  – eigene Gefühle\n  – unmittelbare Beziehungen\n  – wichtigste eigene Tätigkeit\n  – existenzielle Fragen","e":"Fehlen Lebensbereiche, die einem wirklich wichtig sind, ist das Kohärenzgefühl eher gering. Man muss sich aber nicht für alles interessieren – die Grenzen dürfen nur nicht so eng sein, dass die vier Kernbereiche wegfallen. Beispiel: Eine Schülerin, der Politik egal ist, die aber ihre Freunde, ihren Handballverein und ihre Gefühle ernst nimmt, kann ein hohes Kohärenzgefühl haben.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-030","thema":"B.L20","kapitel":"Salutogenese","q":"Ist das Kohärenzgefühl veränderbar und welche Folgen hat ein hohes bzw. niedriges Kohärenzgefühl?","a":"• nach dem jungen Erwachsenenalter kaum noch veränderbar (Antonovsky)\n• hoch: Stressoren werden mit Ressourcen abgewehrt, Gesundheit bleibt erhalten\n• niedrig: keine Erfolgserlebnisse, Gefahr zunehmender Schwächung","e":"Wer ein niedriges Kohärenzgefühl hat, kann Stressoren weder mithilfe von Schutzfaktoren ausweichen noch Erfolgserlebnisse im Umgang mit ihnen sammeln. Was für den einen ein „Klacks“ ist, wird für den anderen zur Überforderung. Deshalb ist die Jugend so wichtig: Hier wird das Kohärenzgefühl geprägt – auch durch Sport und Schule. Beispiel: Ein Referat ist für den einen ein „Klacks“, für den anderen mit niedrigem Kohärenzgefühl eine schlaflose Nacht.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-031","thema":"B.L20","kapitel":"Salutogenese","q":"Fasse das Salutogenesemodell nach Antonovsky zusammen.","a":"• Krankheit ist normal (Heterostase)\n• Stressoren erzeugen Spannung\n• Kohärenzgefühl + Widerstandsressourcen → positive Verarbeitung, Spannung sinkt\n• Gesundheit/Krankheit als Pole eines Kontinuums (HEDE)\n• Bewältigung → Richtung gesunder Pol","e":"Kurz gesagt: Stress trifft jeden, aber Kohärenzgefühl und Ressourcen entscheiden, ob man ihn gut verarbeitet und sich so Richtung Gesundheit bewegt. Beispiel: Zwei Spieler verlieren ein Finale; der eine mit starkem Kohärenzgefühl und gutem Team verarbeitet es, der andere zerbricht daran.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-032","thema":"B.L20","kapitel":"Salutogenese","q":"Nenne Kritikpunkte am Salutogenesemodell.","a":"• direkt gesundheitsfördernde Ressourcen (Humor, Genuss, Optimismus) vernachlässigt\n• fragt eher, wie man nicht krank wird\n• keine Aussagen über das ganze Spektrum bis sehr guter Gesundheit\n• Zusammenhang psychisch–physisch ausgeklammert (Becker)","e":"Das Modell konzentriert sich stark auf Stressbewältigung. Dabei erleichtern Genussfähigkeit, Humor, Optimismus oder die Fähigkeit zu verzeihen nicht nur die Anpassung an Stress, sondern steigern die Gesundheit aktiv. Was gute Gesundheit ausmacht, bleibt offen. Beispiel: Mit Freunden lachen oder ein gutes Essen genießen macht gesünder, auch wenn gerade gar kein Stress zu bewältigen ist.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-033","thema":"B.L20","kapitel":"Salutogenese","q":"Welche Stärken des Salutogenesemodells hebt Franke (2012) hervor?","a":"• betont soziale Beziehungen als Stress reduzierende Variable\n• schließt den Tod ein: bis zuletzt ist etwas in uns gesund\n• praktische Bedeutung bei chronisch/unheilbar Kranken und Sterbebegleitung","e":"Sich auf andere wirklich verlassen zu können, ist in einer ichbezogenen Gesellschaft nicht nur ein sozialer Wert, sondern senkt messbar Stress. Und weil Sterben zum Leben gehört, gibt das Modell auch Menschen eine Perspektive, die nicht mehr „ganz gesund“ werden. Beispiel: Ein unheilbar kranker Mensch kann durch Familie, Sinn und gute Begleitung trotzdem gesunde Anteile stärken und Lebensqualität gewinnen.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-034","thema":"B.L20","kapitel":"Salutogenese","q":"Vergleiche Pathogenese- und Salutogenesemodell hinsichtlich Selbstregulierung, Gesundheitsbegriff, Reichweite des Krankheitsbegriffs und Ursachen (nach Bengel et al., 2001).","a":"Pathogenese | Salutogenese:\n• Selbstregulierung: Homöostase | Überwindung der Heterostase\n• Begriff: Dichotomie | Kontinuum\n• Reichweite: Pathologie | Biografie\n• Ursachen: Risikofaktoren, Stressoren | Ressourcen, Kohärenzgefühl","e":"Die Pathogenese schaut auf die Krankheit, die Salutogenese auf den Menschen und seine Krankheitsgeschichte. Beispiel: Bei Rückenschmerzen fragt die Pathogenese nach dem Bandscheibenbefund, die Salutogenese auch nach Arbeit, Stress und Bewegungsgewohnheiten des Patienten.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-035","thema":"B.L20","kapitel":"Salutogenese","q":"Vergleiche Pathogenese- und Salutogenesemodell hinsichtlich Wirkung von Stressoren, Intervention und Funktion von Gesundheitssport.","a":"Pathogenese | Salutogenese:\n• Stressoren: krankheitsfördernd | krankheits- und gesundheitsfördernd\n• Intervention: Heilmittel („Wunderwaffen“) | aktive Anpassung, Ressourcenentwicklung\n• Gesundheitssport: Prävention | Gesundheitsförderung","e":"In der Salutogenese gehört zur Intervention neben aktiver Anpassung und Ressourcenentwicklung auch die Risikoreduktion. Für die Pathogenese ist Sport eine Art Medizin gegen Krankheit, für die Salutogenese ein Weg, Stärken aufzubauen. Beispiel: Ein Lauftreff kann als Blutdrucksenker (Prävention) oder als Quelle von Selbstvertrauen und Gemeinschaft (Förderung) verstanden werden.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-036","thema":"B.L20","kapitel":"Salutogenese","q":"Wie kam Aaron Antonovsky zur Idee der Salutogenese?","a":"• Medizinsoziologe, forschte in Israel zu Stress\n• untersuchte Frauen in den Wechseljahren, u. a. KZ-Überlebende\n• ein Teil war trotz extremer Belastung gesund\n• Frage: Was hält Menschen gesund?","e":"Antonovsky emigrierte 1960 nach Israel. Er wunderte sich nicht darüber, dass Menschen krank werden, sondern darüber, dass manche trotz schrecklicher Erlebnisse gesund bleiben – dieses „Wunder des Gesundbleibens“ wollte er erforschen. Beispiel: Genau diese Frage stellt man heute auch bei Sportlern, die nach schweren Verletzungen stärker zurückkommen.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-037","thema":"B.L20","kapitel":"SAR und Beckers","q":"Wie definiert das Systemische Anforderungs-Ressourcen-Modell (SAR-Modell) nach Becker Gesundheit?","a":"• dynamisches Gleichgewicht zwischen Anforderungen und Ressourcen\n• pendelt körperlich, seelisch und sozial zwischen „zurzeit völlig krank“ und „zurzeit völlig gesund“\n• Weiterentwicklung der Salutogenese","e":"Anforderungen sind z. B. Schule, Beruf, eigene Bedürfnisse, Risikofaktoren und Ziele; Ressourcen z. B. Selbstkonzept, Fitness, gesunde Ernährung und das soziale Umfeld. Das SAR-Modell ist wie eine Waage zwischen dem, was das Leben von dir verlangt, und dem, was du zur Verfügung hast. Beispiel: Ein Schüler mit Abi, Nebenjob und Training (Anforderungen) bleibt gesund, wenn er fit ist, gut schläft und Unterstützung von Familie und Freunden hat (Ressourcen).","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-038","thema":"B.L20","kapitel":"SAR und Beckers","q":"Welche Grundannahme liegt dem SAR-Modell zugrunde?","a":"Gesundheit hängt davon ab, wie gut externe und interne Anforderungen mithilfe externer und interner Ressourcen bewältigt werden (Becker, 2006).","e":"Entscheidend ist also, ob das Bewältigungsverhalten erfolgreich ist – nicht die Menge an Stress. Das Modell verbindet Umwelt, Verhalten und Erleben sowie psychophysische Merkmale des Menschen (Bewältigungs- und Gesundheitsverhalten, Bedürfnisbefriedigung, Lebenszufriedenheit). Beispiel: Zwei Spielerinnen haben denselben Trainingsplan; die mit guter Erholung und Unterstützung bewältigt ihn, die andere ohne diese Ressourcen wird krank.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-039","thema":"B.L20","kapitel":"SAR und Beckers","q":"Unterscheide externe und interne Anforderungen im SAR-Modell und erkläre, wann sie zu Stressoren werden.","a":"• extern: aus der Umwelt (Beruf, soziales Umfeld)\n• intern: aus Bedürfnissen, Zielen, Werten und Normen\n• Stressor: wenn Anforderungen im Vergleich zu den Ressourcen als zu hoch eingeschätzt werden","e":"Anforderungen sind Bedingungen, mit denen man sich auseinandersetzen muss. Interne Anforderungen entstehen z. B. aus Bedürfnissen nach Anerkennung, Geborgenheit, Schlaf oder Bewegung und aus Zielen in Schule, Beruf und Sport. Werden sie zu Stressoren, lösen sie negative Emotionen wie Angst mit Körperreaktionen (z. B. Schweißausbruch) aus und drängen zum Handeln. Beispiel: Der Trainer verlangt mehr Einheiten (extern), du selbst willst unbedingt in die Landesauswahl (intern). Wächst dir beides über den Kopf, wird es zum Stressor.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-040","thema":"B.L20","kapitel":"SAR und Beckers","q":"Welche internen und externen Ressourcen unterscheidet das SAR-Modell?","a":"Intern:\n• physisch (Konstitution, Fitness)\n• psychisch (Wissen, Selbstkonzept, Kohärenzgefühl)\nExtern:\n• sozial (Beziehungen, Unterstützung)\n• materiell (Einkommen)\n• ökologisch (gesunde Nahrung)","e":"Interne Ressourcen trägst du in dir, externe findest du in deiner Umwelt. Zu den psychischen zählt z. B. auch die Stimmung. Beispiel: Gute Ausdauer (intern, physisch) und Selbstvertrauen (intern, psychisch) helfen ebenso wie eine Trainingsgruppe (extern, sozial) und genug Geld für gutes Essen (extern, materiell).","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-041","thema":"B.L20","kapitel":"SAR und Beckers","q":"Welche Folgen hat ein dauerhaftes Ungleichgewicht zwischen Anforderungen und Ressourcen im SAR-Modell – und was fördert Gesundheit?","a":"Dauerhaftes Übergewicht der Anforderungen:\n• negative Gefühle, Unzufriedenheit, Risikoverhalten, Rückzug\n• Beeinträchtigung der Gesundheit\nGesundheitsfördernd:\n• wohldosierte Anforderungen\n• Ressourcen erhalten und vergrößern\n• erfolgreiche Bewältigung","e":"Wer dauerhaft überfordert ist, ändert oft sein Konsumverhalten (z. B. mehr Alkohol) und Freizeitverhalten (z. B. sozialer Rückzug); psychische und physische Gesundheit leiden stark. Gelingt die Bewältigung dagegen, entstehen Wohlbefinden, Lebensfreude und körperliche wie seelische Gesundheit. Zu viel auf Dauer macht krank, gut dosierte Herausforderungen machen stark. Beispiel: Ein Schüler, der monatelang überfordert ist, zieht sich zurück und schläft schlecht; ein Schüler mit fordernden, aber machbaren Aufgaben wächst daran.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-042","thema":"B.L20","kapitel":"SAR und Beckers","q":"Welche drei Aspekte umfasst Gesundheit im Konzept zur Gesundheitsförderung nach Beckers (2007)?","a":"• biologische Funktionsfähigkeit\n• soziokulturelle Leistungsfähigkeit\n• individuelle Gestaltungsfähigkeit","e":"Das Konzept steht in der Tradition der Salutogenese und legt den Fokus auf aktive Gesundheitsförderung in und durch Sport, besonders im Schulsport. Eselsbrücke: Körper funktioniert – Alltag klappt – Leben selbst gestalten. Beispiel: Schulsport trainiert das Herz (biologisch), die Belastbarkeit für den Alltag (soziokulturell) und die Fähigkeit, eigene Bewegungsziele zu setzen (Gestaltung).","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-043","thema":"B.L20","kapitel":"SAR und Beckers","q":"Erläutere die biologische Funktionsfähigkeit und die soziokulturelle Leistungsfähigkeit nach Beckers.","a":"• biologische Funktionsfähigkeit: möglichst einwandfreies Funktionieren der Organsysteme; Basis für die anderen Ebenen\n• soziokulturelle Leistungsfähigkeit: Voraussetzungen, private, berufliche und soziale Anforderungen zu bewältigen","e":"Die biologische Funktionsfähigkeit ist das Fundament: Ist sie eingeschränkt, leiden oft auch die anderen beiden Aspekte stark. Zur soziokulturellen Leistungsfähigkeit gehören eine optimierte körperliche Belastbarkeit sowie Fähigkeit und Bereitschaft zu zielgerichtetem Handeln. Beispiel: Wer wegen Asthma kaum Treppen steigen kann (biologisch), hat auch Mühe, den Schulweg oder einen Ferienjob zu bewältigen (soziokulturell).","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-044","thema":"B.L20","kapitel":"SAR und Beckers","q":"Was versteht Beckers unter individueller Gestaltungsfähigkeit und wann liegt subjektive Gesundheit vor?","a":"• Kompetenz, eigene Wünsche („Wollen“) und Ressourcen („Können“) mit äußeren Anforderungen („Sollen“) in Einklang zu bringen\n• subjektive Gesundheit: „Sollen“, „Können“ und „Wollen“ im Gleichgewicht","e":"Gefördert wird die Gestaltungsfähigkeit durch eine geschärfte Wahrnehmung und einen sinnvollen Umgang mit Verhaltensmustern und Regeln. Sport, besonders Schulsport, bietet dafür geeignete, risikoarme Übungsfelder. Beispiel: Im Sportunterricht soll eine Turnkür gezeigt werden (Sollen); eine Schülerin wählt Elemente, die sie sicher beherrscht (Können) und die ihr Spaß machen (Wollen) – so gestaltet sie ihre Aufgabe gesund und selbstbestimmt.","quelle":"L20.2","typ":"kern"},{"id":"bonus.c-045","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Ist Sport grundsätzlich gesund? Begründe.","a":"Nein, nicht pauschal:\n• oft kein nachweisbarer Zusammenhang mit besserer Gesundheit\n• nicht immer gesundheitlich motiviert\n• kann selbst Risikofaktor sein (Verletzung, Überlastung)\nAber: angemessen dosiert und reflektiert wirkt Sport positiv (Bös & Brehm)","e":"Viele Studien fanden keinen Zusammenhang zwischen Sporttreiben und besserem Gesundheitszustand. Viele treiben Sport aus Freude, wegen der Natur, des Wagnisses oder des Wettkampfs, nicht wegen der Gesundheit. Richtig strukturierte Aktivität wirkt aber positiv auf physische und psychische Gesundheit. Sport ist wie ein Medikament: In der richtigen Dosis hilft er, falsch dosiert schadet er. Beispiel: Moderates Joggen dreimal pro Woche stärkt das Herz, ein Marathon ohne Vorbereitung kann Knie und Herz überlasten.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-046","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche physischen Gesundheitsressourcen gibt es und welche sind am wichtigsten?","a":"Konditionelle und koordinative Fähigkeiten: Ausdauer, Kraft, Schnelligkeit, Beweglichkeit, Koordination.\nAm wichtigsten: Ausdauer und Kraft.","e":"Ausdauer und Kraft sind entscheidend für Erhalt und Wiederherstellung der Gesundheit – die „Hauptdarsteller“. Ein gesundheitsorientiertes Programm sollte aber immer auch Koordination und Beweglichkeit enthalten. Beispiel: Ein gutes Fitnessprogramm für Erwachsene kombiniert Radfahren und Krafttraining mit Dehn- und Gleichgewichtsübungen.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-047","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche gesundheitlichen Wirkungen hat regelmäßiges Ausdauertraining?","a":"• Muskulatur: besserer Fett-/Kohlenhydratstoffwechsel\n• Immunsystem gestärkt\n• Herz-Kreislauf: ökonomischere Herzarbeit, niedrigerer Blutdruck und Ruhepuls\n• Gehirn: bessere Stimmung\n• senkt Sterblichkeit und Krankheitshäufigkeit am stärksten","e":"Das Immunsystem profitiert von einer besseren Regulation von Entzündungsprozessen, das Herz braucht weniger Sauerstoff. Ältere bewältigen ihren Alltag besser und fühlen sich körperlich und psychosozial wohler. Von allen motorischen Beanspruchungsformen ist Ausdauer der „Allrounder“. Beispiel: Wer ein halbes Jahr regelmäßig joggt, hat oft einen deutlich niedrigeren Ruhepuls, weil das Herz pro Schlag mehr Blut pumpt und daher seltener schlagen muss.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-048","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche Mindestbelastung empfehlen Hollmann und Strüder (2009) für ein gesundheitsorientiertes Ausdauertraining?","a":"• leichte bis mittlere Intensität\n• ca. 1.500–2.000 kcal Energieverbrauch durch Sport pro Woche","e":"Diese Belastung reicht aus, um Bewegungsmangelkrankheiten entgegenzuwirken und durch Anpassungen gesundheitlichen Schutz zu erlangen. Man muss sich nicht quälen – lockeres Training genügt, wenn genug zusammenkommt. Beispiel: Etwa drei- bis viermal pro Woche 45 Minuten zügiges Radfahren oder lockeres Joggen erreicht ungefähr diesen Wochenverbrauch.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-049","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche gesundheitlichen Wirkungen hat Krafttraining?","a":"• Kraftausdauer: ähnliche Effekte wie Ausdauertraining\n• Muskelwachstum\n• Halte-/Stützarbeit fällt leichter\n• Muskeln entlasten passiven Bewegungsapparat\n• Schnellkraft verdichtet Knochen (höhere Bruchfestigkeit)","e":"Kraftausdauer wirkt ähnlich wie Ausdauertraining, weil sie ebenfalls weitgehend energetisch bestimmt ist; bei höheren Kraftanteilen wächst die Skelettmuskulatur deutlich. Muskuläre Stabilität entlastet Knochen, Bindegewebe, Sehnen und Knorpel – starke Muskeln sind wie ein Stützkorsett. Beispiel: Eine kräftige Rumpfmuskulatur entlastet die Bandscheiben und beugt Rückenschmerzen vor; Sprungübungen machen die Knochen fester und schützen vor Osteoporose.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-050","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche Empfehlungen geben Hollmann und Strüder (2009) für ein gesundheitsorientiertes Krafttraining?","a":"• vorher internistische Unbedenklichkeit klären\n• nach Anpassungsphase 3×/Woche je 20 Min.\n• körperstabilisierende Übungen einbauen","e":"Die ärztliche Abklärung ist wichtig, weil Krafttraining den Blutdruck kurzfristig stark ansteigen lässt. Im Rahmen eines umfassenden Fitnesstrainings bringt die genannte Dosis hohen Nutzen bei geringem Risiko. Wenig, aber regelmäßig ist die Devise. Beispiel: Ein 50-jähriger Einsteiger lässt zuerst beim Arzt den Blutdruck prüfen und trainiert dann dreimal pro Woche 20 Minuten an Geräten plus Rumpfstabilisation.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-051","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Warum sollte ein gesundheitsorientiertes Training auch Beweglichkeit, Schnelligkeit und Koordination enthalten?","a":"• mehr Bewegungsfreiheit im Alltag\n• Sturzprophylaxe bei Älteren\n• komplexe Alltagsbewegungen werden besser bewältigt","e":"Bessere, stabile Beweglichkeit zusammen mit guter Koordination erweitert den Bewegungsspielraum. Im Alltag braucht man selten maximale Kraft, aber oft schnelle, sichere Reaktionen. Beispiel: Ein älterer Mensch mit gutem Gleichgewicht fängt sich beim Stolpern auf dem Bürgersteig noch ab, statt zu stürzen und sich die Hüfte zu brechen.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-052","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche psychosozialen Gesundheitsressourcen werden in der Gesundheitspsychologie genannt?","a":"• Selbstkonzept\n• Körperkonzept\n• Selbstwirksamkeit\n• sozialer Rückhalt\n• Stimmung\n• Motivation\n(Brehm & Wagner, 2006)","e":"Diese Ressourcen tragen zu guter psychosozialer Gesundheit bei und lassen sich durch Sport positiv beeinflussen. Sport trainiert also nicht nur Muskeln, sondern auch den Kopf und das Miteinander. Beispiel: Wer im Verein regelmäßig mit anderen trainiert, erlebt Erfolge (Selbstwirksamkeit), fühlt sich wohl in seinem Körper (Körperkonzept) und hat Freunde, auf die er zählen kann (sozialer Rückhalt).","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-053","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Erläutere die Stimmung als Gesundheitsressource und die beiden Strategien des Stimmungsmanagements nach Brehm (2006).","a":"Stimmung = emotionaler Zustand; Ressource und Ausdruck von Wohlbefinden.\n• Wiederherstellungsstrategie (Fitnesssport): negative Stimmung abschwächen, positive stärken\n• Ablenkungsstrategie (Wettkampf): Spannung erst steigern, danach Auflösung","e":"Stimmungen können aktuell oder dauerhaft, positiv (gute Laune, Gelassenheit) oder negativ (Verstimmung, Ärger) sein. Sport dient als Instrument des Stimmungsmanagements: Gezielte Fitnessaktivitäten wirken ausgleichend; im Wettkampf steigen positive und negative Spannung zunächst stark an und lösen sich im Verlauf oder danach auf. Wiederherstellung = runterkommen, Ablenkung = Kopf frei durch Aufregung. Beispiel: Ein lockerer Lauf beruhigt nach einem stressigen Tag; ein spannendes Fußballspiel lässt den Ärger über die Mathearbeit vergessen.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-054","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Was ist das Selbstkonzept und wie ist es nach dem hierarchischen Modell aufgebaut?","a":"Selbstkonzept = Bild, das ein Mensch von sich selbst hat.\n• kognitiv\n• emotional\n• sozial\n• physisch (Körperkonzept: u. a. Attraktivität, Sportlichkeit)\n(Alfermann & Wagner)","e":"Das physische Selbstkonzept ist das Bild von der eigenen körperlichen Erscheinung und Fitness. Das Selbstkonzept ist wie ein inneres Foto von dir, nur aus mehreren Blickwinkeln. Beispiel: Ein Schüler hält sich für schlau (kognitiv), beliebt (sozial) und sportlich, findet sich aber nicht attraktiv (Körperkonzept).","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-055","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche Funktion hat das Selbstkonzept für die Gesundheit und wie entwickelt sich das Körperkonzept?","a":"Funktion:\n• steuert Verhalten; Ressource zur Bewältigung von Anforderungen\n• positives Körperkonzept fördert Sportbindung und Wohlbefinden\nEntwicklung des Körperkonzepts:\n• Sporterfahrungen (Erfolg/Misserfolg)\n• Rückmeldungen\n• soziale Vergleiche","e":"Das Selbstkonzept verarbeitet selbstbezogene Informationen. Wer ein positives Selbstbild hat, geht Anforderungen eher aktiv an und überwindet Widerstände – es wirkt wie ein Motor. Das Körperkonzept entsteht in ständiger Auseinandersetzung mit der Umwelt, etwa durch Leistung und motorisches Können sowie Rückmeldungen von Trainern und Lehrern. Beispiel: Eine Schülerin, die vom Trainer gelobt wird und ihre Laufzeit verbessert, entwickelt ein positives Körperkonzept und bleibt eher beim Sport.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-056","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Nenne zentrale Bestandteile des kognitiven, emotionalen und sozialen Selbstkonzepts.","a":"• kognitiv: eigene intellektuelle Fähigkeiten (Leistung, Wissen)\n• emotional: eigene Gefühle (Stabilität, Umgang mit Angst/Ärger, Selbstwert)\n• sozial: sich in Beziehungen (Beliebtheit, Kontaktfähigkeit, Anerkennung)","e":"Jeder Teil beantwortet eine andere Frage: Wie klug bin ich (z. B. auch Problemlösefähigkeit)? Wie fühle ich mich (z. B. Gelassenheit)? Wie komme ich bei Gleichaltrigen und Familie an? Beispiel: Ein Spieler mit gutem sozialen Selbstkonzept übernimmt gerne die Rolle des Mannschaftskapitäns.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"bonus.c-057","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Wie wirkt sportliche Aktivität auf Risikofaktoren?","a":"• Ausdauertraining beugt den 4 klassischen Herz-Kreislauf-Risikofaktoren vor: Bluthochdruck, Fettstoffwechselstörung, Übergewicht, gestörte Glukosetoleranz\n• Kraft-/Beweglichkeitstraining beugt Risiken des Bewegungsapparats vor","e":"Auch Kraftausdauertraining wirkt präventiv. Kraft- und Beweglichkeitstraining verhindern z. B. muskuläre Dysbalancen und damit Osteoporose, Bandscheibenvorfall und Rückenschmerzen. Sportliche Aktivität hängt stark mit längerer Lebensdauer und geringerem Herz-Kreislauf-Risiko zusammen; Bewegungsmangel, Übergewicht, Fehlernährung und Stress senken dagegen die Lebenserwartung. Beispiel: Ein Jugendlicher, der regelmäßig schwimmt und Rad fährt, entwickelt deutlich seltener Übergewicht und Bluthochdruck als ein Gleichaltriger vor dem Bildschirm.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-058","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Welche Wirkungen hat Gesundheitssport bei bereits vorliegenden Risikofaktoren?","a":"• Blutdruck sinkt\n• LDL sinkt, HDL steigt\n• Übergewicht sinkt\n• vegetatives Nervensystem ökonomischer (Sympathikus ↓, Parasympathikus ↑)\n• mit Ernährung kombiniert am wirksamsten","e":"LDL gilt als „schlechtes“, HDL als „gutes“ Cholesterin. Der Sympathikus wirkt anregend, der Parasympathikus beruhigend. Sport und ausgewogene Ernährung zusammen wirken besser als jede Maßnahme allein – Sport ist also nicht nur Vorbeugung, sondern auch Behandlung. Beispiel: Ein Mann mit leicht erhöhtem Blutdruck kann durch regelmäßiges Walking und gesündere Ernährung seine Werte oft so verbessern, dass er weniger Medikamente braucht.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-059","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Was versteht man unter Wohlbefinden und wie gliedert es sich nach Brehm & Wagner (2006)?","a":"Subjektiver Ausdruck physischer, psychischer und sozialer Gesundheit; nur die Person selbst beurteilt es.\n• physisch: fit, beschwerdefrei\n• psychisch: positiv gestimmt, ausgeglichen, kompetent\n• sozial: gemocht, eingebunden, gebraucht","e":"Wohlbefinden gilt als subjektives Regulativ der objektiv messbaren Gesundheit – nicht Ärzte oder Experten, sondern die Person selbst entscheidet darüber. Es zeigt, ob die objektiven Werte auch im Leben ankommen. Zum physischen Befinden gehört auch, sich im eigenen Körper sicher und gut zu fühlen. Beispiel: Nach dem Volleyballtraining fühlt sich eine Schülerin fit (physisch), gut gelaunt (psychisch) und als Teil des Teams gebraucht (sozial).","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-060","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Erläutere die Funktion des Begriffs Wohlbefinden im Wirkungsgefüge von Sport und Gesundheit.","a":"• subjektives Regulativ: zeigt, ob Verhalten guttut\n• Sport wirkt direkt darauf (Fitness, Kompetenz, Stimmung, Einbindung)\n• motiviert zum Weitermachen\n→ Ergebnis und Antrieb zugleich","e":"Wenn Sport sich gut anfühlt, bindet er an sich – das ist auf lange Sicht der eigentliche Gesundheitseffekt. Wohlbefinden entsteht also durch Sport und hält zugleich die sportliche Aktivität aufrecht. Beispiel: Wer nach dem Lauftreff jedes Mal gut gelaunt nach Hause kommt, wird eher dabeibleiben als jemand, der sich nur aus Pflicht quält.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-061","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Beschreibe das Modell der Wirkungsannahmen von sportlicher Aktivität und Gesundheit (Brehm et al., 2008).","a":"• Rahmenbedingungen (Sozialstatus, Schule, Verein …)\n• Steuerung über motorische Belastungsparameter und psychosoziale Parameter\n• stärkt physische und psychosoziale Ressourcen\n• mindert physische und psychosoziale Belastungssymptome","e":"Motorische Parameter sind Intensität, Dauer, Dichte, Umfang, Häufigkeit und Komplexität; psychosoziale sind Inhalt, Trainingsklima (Übungsleiter, Gruppe) und Emotionalisierung. Gestärkt werden z. B. Ausdauer, Kraft, Selbstkonzept und sozialer Rückhalt; vermindert werden Schmerzen, Risikofaktoren, Stress, Angst und Depression. Fazit: Nur eine angemessene, systematische Belastung, abgestimmt auf die Zielgruppe, wirkt positiv. Beispiel: Ein Rückenkurs mit passender Intensität und guter Gruppenatmosphäre stärkt Rumpf und Stimmung und senkt Rückenschmerzen und Stress.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-062","thema":"B.L21","kapitel":"Sport und Gesundheit","q":"Erläutere die Ambivalenz von Verletzungsrisiko und Gesundheitsförderung im Sport.","a":"• Sport fördert Gesundheit\n• und ist zugleich Risikofaktor (Unfälle, Überlastung, Verletzungen, chronische Schmerzen), v. a. bei falscher Dosierung\n• bewusster Umgang mit dem Risiko kann das Kohärenzgefühl stärken","e":"Fast jeder Sport hat zwei Seiten: Ausdauertraining hilft z. B. gegen Übergewicht und Arteriosklerose, fehlendes Ausgleichstraining oder falsche Dosierung schaden. Wer verantwortungsvoll mit Risiken umgeht, tut damit etwas für seine Gesundheit. Beispiel aus dem Buch: Inlineskating trainiert die aerobe Ausdauer sehr gut, birgt aber ein hohes Sturzrisiko und kann die Knie überlasten. Mit Schutzausrüstung und Ausgleichstraining überwiegt der Nutzen.","quelle":"L21.1","typ":"kern"},{"id":"bonus.c-063","thema":"B.L21","kapitel":"Gesundheitssport","q":"Was kennzeichnet Gesundheitssport und wie grenzt er sich von anderen Sportbereichen ab?","a":"• zielt auf Gesundheits-, Verhaltens- und Verhältniswirkungen\n• diese werden systematisch geplant und gesteuert\n• Wettkampf-, Fun- oder Fitnesssport ist nicht automatisch Gesundheitssport (Brehm)","e":"Der Unterschied liegt in der Absicht und Planung. Andere Sportbereiche können auch gesund sein, verfolgen aber andere Ziele. Beispiel: Ein Fußballspiel kann gesund sein, ist aber auf Sieg ausgerichtet. Ein Rückenkurs bei der Krankenkasse plant dagegen gezielt Übungen, Belastung und Verhaltensänderung für die Gesundheit.","quelle":"L21.2","typ":"kern"},{"id":"bonus.c-064","thema":"B.L21","kapitel":"Gesundheitssport","q":"Nenne die sechs Kernziele des Gesundheitssports nach Bös und Brehm (2006).","a":"1. physische Ressourcen stärken\n2. psychosoziale Ressourcen stärken\n3. Risikofaktoren vermindern\n4. Beschwerden/Missbefinden bewältigen\n5. Bindung an Gesundheitssport\n6. unterstützende Settings schaffen","e":"Die Ziele stehen in Wechselwirkung. Merkhilfe in Paaren: Ressourcen stärken (1, 2), Risiken und Beschwerden senken (3, 4), dranbleiben und Umfeld schaffen (5, 6). Beispiel: Ein Lauftreff stärkt Ausdauer und Selbstvertrauen, senkt Blutdruck und Stress, bindet durch die Gruppe und schafft feste Termine und Strecken.","quelle":"L21.2","typ":"kern"},{"id":"bonus.c-065","thema":"B.L21","kapitel":"Gesundheitssport","q":"Erläutere die Wechselbeziehung der sechs Kernziele des Gesundheitssports.","a":"• 1 (physische Ressourcen) → 3 (Risikofaktoren ↓)\n• 2 (psychosoziale Ressourcen) → 4 (Beschwerden bewältigen)\n• nachhaltig nur durch 5 (Bindung)\n• 6 (Settings) erleichtert Bindung\n• Fortschritte (1–4) fördern Bindung","e":"Die Ziele greifen wie Zahnräder ineinander. Unterstützende Settings sind z. B. eine Gruppe, passende Angebote und gute Erreichbarkeit. Erlebt man Fortschritte und Wohlbefinden, bleibt man eher dabei. Beispiel: Wer im Firmen-Sportkurs (Setting) merkt, dass der Rücken weniger schmerzt (Beschwerden) und er fitter wird (Ressource), bleibt dabei (Bindung) – und senkt so langfristig sein Risiko.","quelle":"L21.2","typ":"kern"},{"id":"bonus.c-066","thema":"B.L21","kapitel":"Gesundheitssport","q":"Unterscheide Krankheitsprävention und Gesundheitsförderung.","a":"Prävention: Risikofaktorenmodell; Risiken/Symptome abbauen; individuell, krankheitsorientiert\nGesundheitsförderung: Salutogenese; Schutzfaktoren stärken; ökologisch (Lebensumfeld), gesundheitsorientiert\nBeide ergänzen sich","e":"Beide wollen einen Gesundheitsgewinn – sie sind zwei Seiten einer Medaille. Prävention fragt: Was muss weg? Förderung fragt: Was muss dazu? Beispiel: Ausdauertraining senkt Blutdruck und Blutfette (Prävention gegen Herzinfarkt) und baut gleichzeitig Ausdauerleistungsfähigkeit als Schutzfaktor auf (Förderung).","quelle":"L21.2","typ":"kern"},{"id":"bonus.c-067","thema":"B.L21","kapitel":"Gesundheitssport","q":"Nach welchen Kriterien beurteilt man die Eignung einer Sportart für den Gesundheitssport?","a":"• Belastung des passiven Bewegungsapparats\n• Verletzungsgefahr\n• Blutdruckwirkung (Pressatmung, Spitzen)\n• Herz-Kreislauf-Anpassung (aerob, gleichmäßig)\nGut: zyklische Ausdauersportarten","e":"Gesundheitssport sollte das Herz gleichmäßig fordern und Gelenke schonen. Sehr gut geeignet sind Walking, Radfahren, Schwimmen, Skilanglauf, Jogging und Wassergymnastik. Eher ungeeignet sind Sportarten mit hoher Verletzungsgefahr, Stop-and-go-Belastungen oder Pressatmung, z. B. Squash, Ski alpin oder Bodybuilding mit Maximallasten. Beispiel: Bei Bluthochdruck sind Radfahren und Walking gut geeignet; Squash ist wegen plötzlicher, sehr hoher Belastungsspitzen eher ungeeignet.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"bonus.c-068","thema":"B.L21","kapitel":"Stress","q":"Woher stammt der Begriff Stress und was haben seine historischen Verwendungen gemeinsam?","a":"• lat. „stringere“: anspannen, zusammenziehen\n• Ingenieurwesen: Beanspruchung von Maschinen\n• 17./18. Jh.: Hungersnot, soziale Not\nGemeinsam: Druck/Anforderung, die ein System schwächt","e":"Im Ingenieurwesen wurde der Begriff bis Mitte des 20. Jahrhunderts verwendet: Material unter Spannung. Alltagssprachlich meint Stress heute meist negative Erlebnisse wie Angst, Anspannung oder Überforderung. Beispiel: So wie eine Brücke unter zu viel Last nachgibt, kann auch ein Mensch unter zu viel Druck „nachgeben“.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-069","thema":"B.L21","kapitel":"Stress","q":"Definiere Stress aus psychologischer Sicht und unterscheide Eustress und Disstress.","a":"Stress = Prozess, in dem Stressoren wahrgenommen werden und man darauf reagiert (Myers).\n• Disstress: Bewertung als Bedrohung → Angst, Flucht, Blockade\n• Eustress: Bewertung als Herausforderung → Motivation, Handeln","e":"Ob Stress gut oder schlecht ist, entscheidet vor allem deine Bewertung. Disstress verunsichert und lähmt, Eustress regt an. Beispiel: Ein Elfmeter im Finale ist für die eine Spielerin eine tolle Chance (Eustress), für die andere eine bedrohliche Situation, die sie lähmt (Disstress).","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-070","thema":"B.L21","kapitel":"Stress","q":"Beschreibe die drei Phasen der Stressreaktion nach Selye.","a":"Allgemeines Adaptationssyndrom (Selye):\n1. Alarmreaktion: akute Aktivierung\n2. Widerstandsreaktion: Anpassung der Körperfunktionen\n3. Erschöpfung: bei Dauerstress, im Extremfall Tod","e":"Selye beschrieb das Modell 1936 und verstand Stress als körperliche Anpassungsreaktion. Beispiel: In der ersten Klausurwoche ist man hellwach (Alarm), in der zweiten hält man durch (Widerstand); dauert der Druck wochenlang ohne Pause an, wird man krank und ausgelaugt (Erschöpfung).","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-071","thema":"B.L21","kapitel":"Stress","q":"Beschreibe die physiologischen Vorgänge der Stressreaktion.","a":"• Sympathikus aktiviert („Kampf oder Flucht“)\n• Nebenniere schüttet Adrenalin/Noradrenalin (kurz) und Cortisol (lang) aus → Energiebereitstellung\n• Puls und Blutdruck ↑, Atmung schneller, Muskeln gespannt, Verdauung ↓\n• danach Abbau durch Parasympathikus","e":"Viele Systeme reagieren gemeinsam: Atmung, Herz-Kreislauf, Stoffwechsel und Muskulatur. Innerhalb von Millisekunden werden Neurotransmitter freigesetzt, Blut wird in die Muskeln umgelenkt, die Pupillen weiten sich. Weil die Stresshormone im Blut bleiben, klingt die Reaktion nur langsam ab. Der Körper macht sich bereit für Kampf oder Flucht – ein Programm aus der Steinzeit. Beispiel: Kurz vor dem 100-m-Start rast das Herz, die Hände schwitzen und die Muskeln sind gespannt; nach dem Lauf dauert es eine Weile, bis man sich beruhigt.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-072","thema":"B.L21","kapitel":"Stress","q":"Vergleiche die Wirkungen von Sympathikus und Parasympathikus (vegetatives Nervensystem).","a":"Sympathikus (erregend) | Parasympathikus (hemmend):\n• Pupillen: weit | eng\n• Speichel: weniger | mehr\n• Haut: schweißnass | trocken\n• Atmung, Herzschlag: schneller | langsamer\n• Verdauung: gehemmt | aktiviert\n• Muskeln: angespannt | entspannt\n• Stresshormone: Ausschüttung | weniger","e":"Sympathikus = Gaspedal, Parasympathikus = Bremse. Beispiel: Bei einer Prüfung hat man einen trockenen Mund und schwitzige Hände (Sympathikus); nach dem Essen auf dem Sofa ist man ruhig und verdaut (Parasympathikus, „rest and digest“).","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-073","thema":"B.L21","kapitel":"Stress","q":"Warum ist Sport ein gutes Ausgleichsmittel bei psychosozialem Stress und warum ist Stress im modernen Alltag oft schädlich?","a":"• Stressreaktion bereitet auf körperliche Aktivität vor\n• Sport (v. a. aerob) baut die Stresshormone „naturgemäß“ ab\n• im modernen Alltag folgt keine Bewegung → Disstress, begünstigt Herz-Kreislauf-Erkrankungen","e":"Die Ausschüttung von Adrenalin, Noradrenalin und Kortikoiden ist natürlich und lebensnotwendig. Sport führt diese Hormone ihrer „naturgegebenen Verwendung“ zu; möglicherweise spielen auch Endorphine eine Rolle. Moderne Stresssituationen lösen dieselbe Reaktion aus, aber ohne anschließende Bewegung oder Bewältigung – das begünstigt z. B. Herzinfarkte. Unser Körper macht sich bereit zu rennen, im Büro rennt aber keiner. Beispiel: Wer sich über den Chef ärgert und abends joggen geht, baut die Stresshormone ab.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-074","thema":"B.L21","kapitel":"Stress","q":"Unter welcher Voraussetzung wirkt Stress gesundheitsfördernd (Eustress)?","a":"Die Belastung ist nur vorübergehend: Auf die Aktivierung muss eine Entladung folgen, das Hormonsystem muss wieder zur Ruhe kommen.","e":"Punktuelle Stressreaktionen können den Körper kurzfristig bis an die Grenzen fordern, die Gesundheit langfristig aber fördern: besserer Schlaf, mehr Ausgeglichenheit, mehr Vitalität im Alter. Entscheidend ist das Signal „Gefahr vorbei, alles klar“ – wie beim Training der Wechsel von Belastung und Erholung. Beispiel: Ein spannendes Turnier am Wochenende mit anschließender Erholung tut gut; Dauerstress ohne Pause dagegen nicht.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-075","thema":"B.L21","kapitel":"Stress","q":"Erläutere das transaktionale Stressmodell nach Lazarus.","a":"Stress = Prozess aus Bewertung und Bewältigung:\n• primäre Bewertung: Ist das Ereignis bedrohlich?\n• sekundäre Bewertung: Reichen meine Ressourcen?\n• ja → Bewältigung (Coping), Eustress/kein Stress\n• nein → Disstress","e":"Stress ist bei Lazarus weder nur Reiz noch nur Reaktion. Die Reaktion hängt nicht direkt vom Stressor ab, sondern von der zwischengeschalteten kognitiven Bewertung (Appraisal); beide Bewertungen können nacheinander oder parallel ablaufen. Dein Kopf ist der Filter. Beispiel: Ein Turner sieht ein schweres Gerät („anspruchsvoll“), denkt dann „Das habe ich oft geübt“ und erlebt Eustress. Ein ungeübter Mitschüler bewertet es als Bedrohung und erlebt Disstress.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-076","thema":"B.L21","kapitel":"Stress","q":"Welche Rolle spielt das Kohärenzgefühl bei der Stressbewältigung?","a":"Kein Coping-Mechanismus, sondern Voraussetzung, flexibel mit Anforderungen umzugehen und über viele Coping-Fertigkeiten zu verfügen (Franke).","e":"Das Kohärenzgefühl prägt auch keinen bestimmten Bewältigungsstil. Es ist eher das Vertrauen, im Werkzeugkasten das passende Werkzeug zu finden. Beispiel: Eine Spielerin mit hohem Kohärenzgefühl reagiert je nach Situation mal mit Atemübung, mal mit Gespräch, mal mit mehr Training.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-077","thema":"B.L21","kapitel":"Stress","q":"Welche Bedeutung hat das Stressniveau für die sportliche Leistung?","a":"• individuell optimales Erregungsniveau nötig (IZOF, Hanin)\n• zu viel Stress: höhere Muskelspannung, unkoordinierte, „unrunde“ Bewegungen, Konzentrationsstörungen\n→ Entspannungsverfahren","e":"Bei zu hoher Anspannung werden die Bewegungen kleiner, Bewegungsfluss und -rhythmus leiden, Aufmerksamkeit und Wahrnehmung nehmen ab. Ein bisschen Nervosität macht schnell, zu viel macht steif. Beispiel: Ein Basketballer, der beim entscheidenden Freiwurf zu angespannt ist, wirft mit verkrampftem Arm und trifft schlechter als im Training.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-078","thema":"B.L21","kapitel":"Stress","q":"Beschreibe die progressive Muskelentspannung (PME) nach Jacobson.","a":"• Jacobson (1930er)\n• Muskelgruppen nacheinander anspannen (max. ca. 5 s), dann lösen und Entspannung wahrnehmen (mind. 15 s)\n• baut mit Stress verbundene Muskelspannung ab","e":"Die Grundidee: Stress, innere Unruhe und Angst gehen mit erhöhter Muskelspannung einher; baut man diese gezielt ab, sinkt auch der Stress. Langsames Sprechen und Vorstellungskraft unterstützen das Verfahren. Durch bewusstes Anspannen spürt man die Entspannung danach umso deutlicher. Beispiel: Eine Schwimmerin ballt vor dem Start nacheinander Fäuste, zieht Schultern hoch und spannt die Beine an, lässt jeweils los und wird spürbar ruhiger.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-079","thema":"B.L21","kapitel":"Stress","q":"Beschreibe das autogene Training nach Schultz.","a":"• Schultz (1932)\n• Selbstentspannung durch formelhafte Selbstsuggestion („Ich bin ganz ruhig.“)\n• Stufen: Schwere, Wärme, Atmung, Herz-Kreislauf\n• im Sport zur Regeneration","e":"Man übt im Liegen oder in der „Kutscherhaltung“ im Sitzen. Eingesetzt wird es auch in Rehabilitation und Gesundheitsförderung – aber nur, wenn danach keine Phase hoher Aktivität folgt. Beispiel: Ein Leichtathlet liegt nach dem Wettkampf in der Halle und sagt sich innerlich „Mein rechter Arm ist ganz schwer … ganz warm“, um schneller zu regenerieren.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-080","thema":"B.L21","kapitel":"Stress","q":"Welche Nachteile haben PME und autogenes Training im Sport und was sind naive Bewältigungsstrategien?","a":"Nachteile PME/AT:\n• aufwendig zu erlernen\n• senken nur Erregung, nicht die Ursache\n• nicht im Wettkampf anwendbar\nNaive Strategien: Alltagstechniken, im Wettkampf nutzbar (Selbstgespräche, Ablenkung, Bewegung)","e":"Die Ursache bleibt bei PME und autogenem Training unbearbeitet, weil die Einstellung zum Stressor nicht verändert wird. Naive Strategien sind keine wissenschaftlich erprobten Programme, sondern die schnellen Hausmittel der Sportler. Beispiel: Ein Tennisspieler tänzelt beim Return auf der Stelle und sagt sich „Ich bin ganz konzentriert und ruhig“ – das geht mitten im Match, PME dagegen nicht.","quelle":"L21.3","typ":"kern"},{"id":"bonus.c-081","thema":"B.L22","kapitel":"Doping Definition","q":"Woher stammt der Begriff Doping?","a":"• engl. „dope“: verabreichen / Rauschgift\n• 1889 im Wörterbuch: Schmerzmittel-Opium-Mischung bei Pferderennen\n• evtl. von „dop“ (südafrikan. Schnaps)","e":"„Dop“ bezeichnet in einem südafrikanischen Bantudialekt einen starken Schnaps; das Adjektiv „dopy“ heißt benebelt oder dämlich. In Dopingkreisen steht es spöttisch für die Unachtsamkeit dessen, der sich erwischen lässt. Beispiel: Rennpferden wurden Ende des 19. Jahrhunderts Opiummischungen verabreicht, um sie schneller oder ruhiger zu machen.","quelle":"L22.1","typ":"kern"},{"id":"bonus.c-082","thema":"B.L22","kapitel":"Doping Definition","q":"Erläutere die Aussage von Sir Arthur Porritt zur Definition von Doping.","a":"• Doping ist kaum exakt definierbar\n• aber jeder Sportler weiß, was gemeint ist\n• die Definition liegt in der charakterlichen Integrität → Frage der Moral, nicht nur der Regeln","e":"Porritt sagt sinngemäß: Wer dopt, weiß, dass er betrügt. Eine begriffliche Abgrenzung scheitert an Grenzfällen und ständig neuen Mitteln, doch Athleten wissen intuitiv, wann sie unerlaubt manipulieren. Beispiel: Ein Radfahrer, der heimlich Eigenblut zurückführt und das versteckt, weiß genau, dass das nicht in Ordnung ist – auch wenn er Lücken in den Regeln sucht.","quelle":"L22.1","typ":"kern"},{"id":"bonus.c-083","thema":"B.L22","kapitel":"Doping Definition","q":"Wie definieren Hollmann und Strüder (2009) Doping und warum wählen sie eine praxisorientierte Definition?","a":"Versuch der Leistungssteigerung mit chemischen, pharmakologischen oder physikalischen Methoden, die laut Liste des Sportfachverbands oder des IOC verboten sind.\nGrund: exakte Definition aus somatisch-psychisch-juristischen Gründen unmöglich.","e":"Somatisch: Viele Substanzen sind körpereigen oder Medikamente, die Grenze zwischen Therapie und Leistungssteigerung ist unscharf. Psychisch: Wirkungen auf die Psyche sind schwer messbar. Juristisch: Verbote müssen eindeutig und rechtssicher sein. Also pragmatisch: Doping ist, was auf der Liste steht. Beispiel: Ein Asthmaspray kann Therapie oder Doping sein – entscheidend ist, was die Liste und eine Ausnahmegenehmigung sagen.","quelle":"L22.1","typ":"kern"},{"id":"bonus.c-084","thema":"B.L22","kapitel":"Doping Definition","q":"Welche Gemeinsamkeit haben alle Dopingdefinitionen (nach Daumann, 2003)?","a":"Einsatz von Präparaten/Methoden, die gegen sportethische Normen verstoßen, auf Leistungssteigerung zielen und Gesundheitsschäden in Kauf nehmen.","e":"Drei Bausteine: Regelverstoß, Leistungssteigerung, Gesundheitsrisiko billigen. Beispiel: Ein Sprinter nimmt Anabolika, obwohl er von Leberschäden weiß – alle drei Merkmale sind erfüllt.","quelle":"L22.1","typ":"kern"},{"id":"bonus.c-085","thema":"B.L22","kapitel":"Doping Definition","q":"Welche Verstöße gelten nach dem Nationalen Anti-Doping-Code (NADC) als Doping?","a":"• Substanz in der Probe\n• (versuchter) Gebrauch\n• Umgehen/Verweigern der Probenahme\n• Meldepflichtverstöße\n• Einflussnahme auf Kontrolle\n• Besitz\n• Handel\n• Verabreichung\n• Tatbeteiligung\n• verbotener Umgang","e":"Als Nachweis zählen auch Metaboliten oder Marker der Substanz. Verbotener Umgang heißt z. B. die Zusammenarbeit mit wegen Dopings gesperrten Trainern. Doping ist also viel mehr als ein positiver Test. Beispiel: Eine Athletin, die eine Dopingkontrolle verweigert oder mehrfach ihren Aufenthaltsort nicht meldet, begeht ebenfalls einen Dopingverstoß – auch ohne nachgewiesene Substanz.","quelle":"L22.1","typ":"kern"},{"id":"bonus.c-086","thema":"B.L22","kapitel":"Doping Definition","q":"Nach welchen Kriterien wird ein Wirkstoff oder eine Methode auf die Verbotsliste der WADA aufgenommen?","a":"Mindestens 2 von 3 Kriterien:\n• K1: Leistungssteigerung möglich\n• K2: Gesundheitsrisiko\n• K3: Verstoß gegen den Geist des Sports","e":"Die WADA wurde 1999 gegründet; seit 2004 gibt es die jährlich aktualisierte Verbotsliste nach dem Welt-Anti-Doping-Code. Beispiel: Cannabis steigert die Leistung kaum, ist aber gesundheitlich riskant (K2) und widerspricht dem Geist des Sports (K3) – deshalb ist es im Wettkampf verboten.","quelle":"L22.1","typ":"kern"},{"id":"bonus.c-087","thema":"B.L22","kapitel":"Doping Definition","q":"Welche Probleme ergeben sich aus den offiziellen Dopingdefinitionen und wie nennt man Doping im Breitensport?","a":"• gewisse Willkür: Verbote sind festgelegt, nicht naturgegeben\n• ständige Anpassung an neue Mittel nötig\n• im Breitensport: Medikamentenmissbrauch","e":"Wegen technischer und pharmazeutischer Innovationen muss die Liste jährlich angepasst werden und läuft neuen Mitteln immer ein Stück hinterher. Beispiel: Ein Hobby-Bodybuilder im Fitnessstudio, der Anabolika nimmt, „dopt“ formal nicht, weil er keinem Verband untersteht – man spricht von Medikamentenmissbrauch.","quelle":"L22.1","typ":"kern"},{"id":"bonus.c-088","thema":"B.L22","kapitel":"Dopingmittel","q":"Welche drei Bereiche umfasst die Verbotsliste der WADA?","a":"• verbotene Substanzen (S0–S9)\n• in bestimmten Sportarten verboten (P1 Betablocker)\n• verbotene Methoden: M1 Blutmanipulation, M2 chemische/physikalische Manipulation, M3 Gen- und Zelldoping","e":"Die Liste unterscheidet „Stoffe“ und „Verfahren“. Gendoping heißt seit 2019 „Gen- und Zelldoping“. Beispiel: EPO ist eine verbotene Substanz, das Zurückführen von Eigenblut eine verbotene Methode.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-089","thema":"B.L22","kapitel":"Dopingmittel","q":"Welche Substanzklassen sind grundsätzlich und welche nur im Wettkampf verboten?","a":"Immer verboten:\n• S0 nicht zugelassene Substanzen\n• S1 anabole Substanzen\n• S2 Peptidhormone (z. B. EPO)\n• S3 Beta-2-Agonisten\n• S4 Hormon-/Stoffwechselmodulatoren\n• S5 Diuretika/Maskierungsmittel\nNur im Wettkampf:\n• S6 Stimulanzien\n• S7 Narkotika\n• S8 Cannabinoide\n• S9 Glukokortikoide","e":"S2 umfasst ausführlich Peptidhormone, Wachstumsfaktoren, verwandte Substanzen und Mimetika. Faustregel: Was im Training Vorteile bringt (Muskelaufbau, Blutbildung), ist immer verboten, auch im Training; was nur im Moment des Wettkampfs wirkt (Aufputschen, Schmerz dämpfen), nur im Wettkampf. Beispiel: Anabolika wirken über Wochen Training – deshalb gibt es Trainingskontrollen.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-090","thema":"B.L22","kapitel":"Dopingmittel","q":"Beschreibe Definition bzw. Wirkung der Substanzklassen S0 bis S5.","a":"• S0: nicht zugelassene Arzneimittel (Designerdrogen)\n• S1: Anabolika – Eiweißaufbau, Regeneration\n• S2: Peptidhormone – Botenstoffe (EPO)\n• S3: Beta-2-Agonisten – bronchienerweiternd\n• S4: Hormonmodulatoren – mindern Anabolika-Nebenwirkungen\n• S5: Diuretika – Gewicht ↓, Maskierung","e":"S0 umfasst Mittel in Entwicklung, vom Markt genommene oder nur im Tierversuch erprobte Stoffe. Anabolika wirken teils auch androgen (z. B. Testosteron, Clenbuterol). Beta-2-Agonisten wirken teils anabol und sympathikusaktivierend (z. B. Fenoterol), Modulatoren sind z. B. Insulin oder Antiöstrogene. Diuretika beschleunigen auch die Ausscheidung von Dopingmitteln. Beispiel: Ein Gewichtheber nimmt kurz vor dem Wiegen ein Diuretikum, um Wasser auszuscheiden und in eine leichtere Gewichtsklasse zu kommen.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-091","thema":"B.L22","kapitel":"Dopingmittel","q":"Beschreibe Definition bzw. Wirkung der im Wettkampf verbotenen Substanzklassen S6 bis S9.","a":"• S6 Stimulanzien: aufputschend (Amphetamin, Kokain)\n• S7 Narkotika: schmerzstillend, euphorisierend (Morphin)\n• S8 Cannabinoide: beruhigend, entspannend\n• S9 Glukokortikoide: entzündungshemmend, immunsuppressiv (Cortison)","e":"Stimulanzien werden meist kurz vor dem Wettkampf genommen und sind im Urin gut nachweisbar. Narkotika beseitigen Angst und Unlust. Glukokortikoide sind Steroidhormone der Nebenniere und beeinflussen Stoffwechsel, Wasserhaushalt, Kreislauf und Nervensystem. Alle wirken akut – deshalb sind sie nur im Wettkampf verboten. Beispiel: Ein Radfahrer, der vor einer Bergetappe Amphetamine nimmt, unterdrückt Müdigkeit und Erschöpfung, riskiert aber Überhitzung und Herzversagen.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-092","thema":"B.L22","kapitel":"Dopingmittel","q":"Erläutere die Wirkung anabol-androgener Steroide (Anabolika).","a":"• anabol (erwünscht): Eiweißaufbau → mit Krafttraining Muskelwachstum; bessere Regeneration\n• androgen (unerwünscht): vermännlichend, wirkt auf Geschlechtsmerkmale und Psyche\n• deutliche Leistungssteigerung, v. a. bei Frauen","e":"Anabol heißt aufbauend, androgen heißt vermännlichend; man versucht, den androgenen Anteil gering zu halten. DDR-Testbefunde zeigten bei Frauen z. B. 10–20 m mehr im Diskuswurf und 0,4–0,8 s schnellere 100-m-Zeiten. Beispiel: Viele Frauen-Weltrekorde der 1980er-Jahre im 400-m- und 800-m-Lauf sind bis heute unerreicht – ein Hinweis auf den damals verbreiteten Anabolikamissbrauch.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-093","thema":"B.L22","kapitel":"Dopingmittel","q":"Nenne Nebenwirkungen eines übermäßigen Konsums anabol-androgener Steroide.","a":"• Herz/Gefäße: HDL ↓, LDL ↑, Arteriosklerose, früher Herzinfarkt\n• Leberschäden\n• Steroidakne, Wachstumsfugen schließen früh\n• Männer: Hodenschwund, Gynäkomastie\n• Frauen: Virilisierung, Zyklusstörungen\n• Psyche: Aggressivität, Depression","e":"Am Herzen wachsen die Muskelzellen, während die Kapillarisierung abnimmt; auch quergestreifte Muskulatur kann sich auflösen. Bei Männern sinken Spermienbildung und Libido, bei Frauen werden die Stimme tiefer und Haare fallen aus, bis hin zur Unfruchtbarkeit. Depressionen treten oft nach dem Absetzen auf. Ordne die Nebenwirkungen nach Organen. Beispiel: Ein junger Bodybuilder mit Anabolikamissbrauch kann mit Ende 20 einen Herzinfarkt erleiden, weil sich seine Blutfettwerte massiv verschlechtert haben.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-094","thema":"B.L22","kapitel":"Dopingmittel","q":"Erläutere die Wirkung von EPO, die Gesundheitsrisiken und die Problematik des Nachweises.","a":"• Wirkung: körpereigenes Hormon (Niere) → mehr rote Blutkörperchen → besserer O₂-Transport, Ausdauer ↑\n• Risiken: Bluteindickung, Thrombosen, Embolie, Herzstillstand\n• Nachweis schwierig: körpereigen, Verschleierung möglich","e":"EPO steigert auch das Blutvolumen und wird seit etwa 1990 synthetisch im Ausdauersport missbraucht. Das Blut wird trotz Blutverdünnern wie ASS zähflüssig, es drohen Bluthochdruck und Gerinnsel in Gehirn oder Herz. Synthetisches EPO ist schwer vom körpereigenen zu unterscheiden; verschleiert wird z. B. mit Plasmaexpandern (ebenfalls verboten). Beispiel: Radprofis sollen nachts auf den Hotelfluren auf und ab gegangen sein, damit ihr eingedicktes Blut im Schlaf nicht verklumpt.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-095","thema":"B.L22","kapitel":"Dopingmittel","q":"Wie wirken Betablocker und warum sind sie in bestimmten Sportarten verboten?","a":"• hemmen die Wirkung von Adrenalin/Noradrenalin\n• senken Herzfrequenz und Blutdruck, mindern Zittern → beruhigend, konzentrationsfördernd\n• verboten in Präzisionssportarten (z. B. Schießen, Bogenschießen, Golf, Darts)","e":"Betablocker blockieren die Betarezeptoren und werden medizinisch z. B. bei Bluthochdruck und Tremor eingesetzt. Im Wettkampf verboten sind sie u. a. in Automobilsport, Billard, Darts, Golf, Teilen des Skisports und Unterwassersport; im Bogenschießen und Schießsport sogar außerhalb des Wettkampfs. Bis 2017 stand dort auch Alkohol auf der Liste. Beispiel: Ein Sportschütze mit langsamerem Herzschlag und ruhigerer Hand kann zwischen zwei Herzschlägen präziser abdrücken.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-096","thema":"B.L22","kapitel":"Dopingmittel","q":"Was versteht man unter Blutdoping und wie wird es durchgeführt?","a":"Infusion von Fremdblut, Eigenblut oder Erythrozytenkonzentrat.\nEigenblut: ca. 1,2 l entnehmen und lagern → Körper bildet nach → kurz vor dem Wettkampf Rückinfusion → mehr Erythrozyten, Ausdauer ↑","e":"Blutdoping ist seit den 1960er-Jahren bekannt. Das Erythrozytenkonzentrat wird mit Konservierungsstoffen kühl gelagert; der Athlet trainiert weiter und hat nach etwa drei Wochen wieder normale Hämoglobinwerte. Nach der Rückinfusion bindet das Blut mehr Sauerstoff. Beispiel: Ein Skilangläufer lässt sich Wochen vor Olympia Blut abnehmen und kurz vor dem Rennen zurückgeben.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-097","thema":"B.L22","kapitel":"Dopingmittel","q":"Welche Gefahren und Risiken hat Blutdoping und welche legale Alternative gibt es?","a":"Gefahren:\n• Bluteindickung: Thrombosen, Embolie, Herztod\n• bakterielle Verunreinigung\n• Fremdblut: Allergien, Nierenschäden, Infektionen (Hepatitis, HIV)\nLegale Alternative: Höhentraining","e":"Der Vorteil (mehr rote Blutkörperchen) ist zugleich die Gefahr (dickes Blut); sogar Erblindung ist möglich. Schon die Blutentnahme kann Schwindel, Schwäche und ein geschwächtes Immunsystem verursachen. Höhentraining steigert den Erythrozytengehalt auf natürliche Weise. Beispiel: Ein Ausdauersportler, der drei Wochen in 2.000 m Höhe trainiert, erhöht seine Blutwerte legal und ohne Transfusionsrisiko.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-098","thema":"B.L22","kapitel":"Dopingmittel","q":"Was versteht man unter chemischer und physikalischer Manipulation?","a":"Methoden, die Dopingkontrollproben verändern:\n• chemisch: Zusätze zerstören Dopingsubstanzen in der Probe\n• physikalisch: Fremdurin abgeben, Blaseninhalt austauschen","e":"Hier wird nicht die Leistung manipuliert, sondern die Kontrolle. Chemisch geschieht das durch Chemikalien oder Enzyme, die Dopingmittel oxidieren und abbauen; physikalisch durch Täuschung des Kontrolleurs oder per Katheter kurz vor der Kontrolle. Beispiel: Ein Athlet versucht, mit einem versteckten Beutel sauberen Fremdurin abzugeben – das gilt selbst als schwerer Dopingverstoß.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-099","thema":"B.L22","kapitel":"Dopingmittel","q":"Was ist Gendoping?","a":"Nicht therapeutischer Eingriff in die Erbsubstanz (Gene, Genelemente, Zellen) zur Leistungssteigerung; seit 2019 „Gen- und Zelldoping“; bisher kein dokumentierter Fall.","e":"Denkbar wäre z. B., Gene einzuschleusen, die die Aktivität von Enzymen und damit die Kraftentwicklung erhöhen. Gendoping steckt im eigenen Erbgut und wäre deshalb besonders schwer nachweisbar. Beispiel: Theoretisch könnte man ein Gen einschleusen, das die Muskeln dauerhaft mehr eigenes EPO oder Wachstumsfaktoren produzieren lässt.","quelle":"L22.2","typ":"kern"},{"id":"bonus.c-100","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Welche drei Hauptargumente begründen das Dopingverbot und wie lassen sie sich aus den WADA-Kriterien ableiten?","a":"• Gesundheitsargument (K2: Gesundheitsrisiko)\n• Fairness-/Chancengleichheitsargument (K1: unfairer Leistungsvorteil, K3)\n• Natürlichkeitsargument (K3: Geist des Sports, Authentizität)","e":"Gesundheit, Fairness, Natürlichkeit – das sind die drei Säulen. Doping gefährdet gleiche Startvoraussetzungen und verletzt die Authentizität der Leistung. Beispiel: Anabolika schaden der Leber (Gesundheit), verschaffen einen Vorsprung gegenüber sauberen Konkurrenten (Fairness), und die Leistung beruht nicht mehr nur auf Talent und Training (Natürlichkeit).","quelle":"L22.3","typ":"kern"},{"id":"bonus.c-101","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Wo liegen die Grenzen des Gesundheitsarguments (nach Emrich et al., 2013)?","a":"• gesundheitsschädliche Sportarten sind legitim (Boxen, Ski alpin)\n• schädliches Verhalten erlaubt (Gewichtmachen, Essstörungen)\n• manche verbotene Mittel könnten präventiv wirken (Regeneration, Verletzungsschutz)","e":"Beim Boxen und Kampfsport sind Verletzungen des Gegners sozial legitimiert, im Automobilsport ist die Eigengefährdung hoch. Essstörungen sind z. B. in rhythmischer Sportgymnastik oder im Skispringen verbreitet. Manche verbotenen Substanzen könnten Übertraining vermeiden und nach Verletzungen schneller heilen lassen. Wenn es wirklich nur um Gesundheit ginge, müsste man auch Boxen verbieten. Beispiel: Ein Judoka darf sich in der Sauna Kilos „abschwitzen“ – ein Diuretikum mit ähnlicher Wirkung ist verboten.","quelle":"L22.3","typ":"kern"},{"id":"bonus.c-102","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Was versteht man unter Chancengleichheit und wo liegen die Grenzen des Fairness- und Chancengleichheitsarguments?","a":"Chancengleichheit: gleiche Startvoraussetzungen; Ausgang nur durch Talent und Anstrengung.\nGrenzen:\n• trägt nur bei weltweit wirksamen Kontrollen\n• außerhalb des Wettkampfs ohnehin ungleiche Chancen (Geld, Infrastruktur, Förderung)","e":"Sind die Kontrollen in verschiedenen Ländern unterschiedlich streng, fühlen sich Sportler aus strengen Ländern benachteiligt und rechtfertigen Doping subjektiv, um Nachteile zu vermeiden (spieltheoretische Analysen). Völlige Chancengleichheit gibt es im Sport nie. Beispiel: Ein Athlet aus einem reichen Land hat Höhenkammern und Sportmediziner, einer aus einem armen Land nicht – trotzdem ist nur Doping verboten.","quelle":"L22.3","typ":"kern"},{"id":"bonus.c-103","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Warum würde auch eine Freigabe (Legalisierung) von Doping dem Chancengleichheitsargument widersprechen?","a":"• Wirksamkeit hinge vom Geld ab (effizienter, sicherer dopen)\n• wer aus Gesundheits- oder Moralgründen nicht dopt, wäre vom Sieg ausgeschlossen","e":"Legalisierung würde die Ungleichheit nur verschieben – vom Kontrollsystem zum Geldbeutel. Beispiel: Ein Team mit eigenem Labor und Ärzten hätte bessere Mittel als ein Athlet, der sich Präparate im Internet besorgt.","quelle":"L22.3","typ":"kern"},{"id":"bonus.c-104","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Was meint Authentizität der sportlichen Leistung und wo liegen die Grenzen des Natürlichkeitsarguments?","a":"Authentizität: Leistung beruht nur auf natürlichen Möglichkeiten (Talent, Training, Motivation).\nGrenzen:\n• viele künstliche Hilfen erlaubt (OPs, Unterdruckkammer, Kreatin)\n• natürliche Vorteile nur teils begrenzt (Hämatokrit ja, Körpergröße nein)","e":"Ungereimt ist z. B., dass die Unterdruckkammer zum Ausgleich des Höhenvorteils erlaubt ist, EPO mit ähnlichem Effekt aber verboten. Hochbegabte werden bei Blutwerten durch Grenzwerte gebremst, beim Basketball (Körpergröße) oder Diskuswurf (Gewicht) nicht. Was „natürlich“ ist, ist schwer abzugrenzen. Beispiel: Ein Läufer aus dem Flachland darf im Höhenzelt schlafen, um wie ein Kenianer aus dem Hochland mehr rote Blutkörperchen zu haben.","quelle":"L22.3","typ":"kern"},{"id":"bonus.c-105","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Welche zwei soziologischen Erklärungsansätze für Doping werden unterschieden?","a":"• methodologischer Kollektivismus (Homo sociologicus): Doping als Systemproblem, Athlet unterliegt Zwängen\n• methodologischer Individualismus (Homo oeconomicus): Doping als Kosten-Nutzen-Entscheidung des Einzelnen","e":"Beim Homo sociologicus ordnet sich der Athlet den sozialen Zwängen des Spitzensports teils unreflektiert unter und ist in seiner Freiheit eingeschränkt. Beim Homo oeconomicus wägt er Nutzen (Absicherung, Siegesgefühl) gegen Kosten (Strafrisiko, Gesundheit) ab. Die Soziologie betrachtet Doping zunächst amoralisch und fragt, welche Bedingungen es unwahrscheinlich machen. Beispiel: Ein Radfahrer dopt, weil das ganze Team dopt (sociologicus); ein anderer, weil der Sponsorvertrag das Sperrrisiko überwiegt (oeconomicus).","quelle":"L22.4","typ":"kern"},{"id":"bonus.c-106","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Welche intervenierenden Bedingungen machen Doping unwahrscheinlicher (Moraläquivalente nach Bette & Schimank, 2006)?","a":"• Angst vor Gesundheitsschäden\n• Angst vor Entdeckung/Diffamierung\n• wirksames Kontrollsystem\n• sozial-moralisches Milieu\n• großes Talent\n• Verletzungsfreiheit\n• berufliche Alternativen\n• kein Zugang zu Dopingmilieus\n• Geldknappheit","e":"Moraläquivalente wirken wie Moral, obwohl sie aus ganz anderen Gründen vor Doping schützen. Zur Angst vor Gesundheitsschäden gehört auch die Angst vor Sucht; Verletzungsfreiheit wird z. B. durch gute physiotherapeutische Betreuung gefördert; Alternativen ergeben sich aus Herkunft oder Ausbildung. Beispiel: Eine Athletin mit abgeschlossenem Studium (Positionsalternative) und stabilem Freundeskreis ist weniger darauf angewiesen, um jeden Preis zu gewinnen.","quelle":"L22.4","typ":"kern"},{"id":"bonus.c-107","thema":"B.L22","kapitel":"Dopingverbot und Soziologie","q":"Beurteile, ob moralische Appelle an jugendliche Leistungssportler Doping wirkungsvoll verhindern können.","a":"Kaum, allein:\n• Doping ist auch systembedingt (Homo sociologicus)\n• Prämien und geringes Entdeckungsrisiko wiegen oft schwerer (Homo oeconomicus)\nWirksamer: veränderte Bedingungen (Moraläquivalente), ergänzt durch Werteerziehung","e":"Appelle setzen nur beim Einzelnen an. Wirksamer sind funktionierende Kontrollen, Ausbildung und berufliche Alternativen, stabile soziale Milieus und gute medizinische Betreuung. Erziehung hilft ergänzend, wenn sie Werte vorlebt und Athleten stärkt, Druck zu widerstehen. Moral predigen reicht nicht, wenn das Umfeld Doping belohnt. Beispiel: Ein Nachwuchsathlet hört im Präventionsseminar, Doping sei falsch, sieht aber, dass gedopte Konkurrenten Sponsoren bekommen – ohne Kontrollen und Alternativen verpufft der Appell.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"bonus.c-108","thema":"B.L23","kapitel":"Ernährung","q":"Beschreibe das Ernährungsverhalten in Deutschland und nenne ernährungsbedingte Krankheiten.","a":"• Mehrheit der Erwachsenen übergewichtig, ca. jeder 4. adipös\n• ca. 15 % der Kinder/Jugendlichen übergewichtig\n• ca. jeder 5. Jugendliche mit Essstörungsmerkmalen\nKrankheiten: Herz-Kreislauf, Karies, Diabetes, Adipositas, Krebs","e":"Bei Kindern hat sich der Anteil seit 1975 etwa verdoppelt; Essstörungsmerkmale zeigen Mädchen fast doppelt so häufig wie Jungen. Adipositas verursacht ca. 30 Mrd. Euro Folgekosten pro Jahr, Einkommensschwächere sind häufiger betroffen. Im Leistungssport kommt krankhaftes Essverhalten zur Gewichtsreduktion hinzu. Beispiel: Während viele Jugendliche durch Fast Food und Bewegungsmangel zunehmen, hungern sich manche Turnerinnen oder Läuferinnen in ein gefährliches Untergewicht.","quelle":"L23","typ":"kern"},{"id":"bonus.c-109","thema":"B.L23","kapitel":"Ernährung","q":"Woraus setzt sich die Nahrung zusammen?","a":"• Makronährstoffe (energieliefernd): Kohlenhydrate, Fette, Proteine (auch Alkohol, Ballaststoffe)\n• Mikronährstoffe: Vitamine, Mineralstoffe (Mengen-, Spuren-, Ultraspurenelemente)\n• Wasser","e":"Makronährstoffe sind der Treibstoff, Mikronährstoffe die Schmiermittel und Werkzeuge im Motor. Beispiel: Nudeln liefern vor allem Energie (Kohlenhydrate), ein Apfel zusätzlich Vitamin C, das selbst keine Energie liefert, aber viele Stoffwechselvorgänge ermöglicht.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-110","thema":"B.L23","kapitel":"Ernährung","q":"Wie viel Energie liefern die energieliefernden Nahrungsbestandteile pro Gramm?","a":"• Kohlenhydrate: 4 kcal/g\n• Fett: 9 kcal/g\n• Protein: 4 kcal/g\n• Alkohol: 7 kcal/g\n• Ballaststoffe: 2 kcal/g","e":"Kohlenhydrate sind Einfach-, Zweifach- und Mehrfachzucker, Fette v. a. Neutralfette aus Fettsäuren und Glycerin, Proteine bestehen aus Aminosäuren, Ballaststoffe sind unverdauliche Mehrfachzucker wie Zellulose. Fett hat mehr als doppelt so viele Kalorien wie Kohlenhydrate oder Eiweiß. Beispiel: 10 g Butter liefern etwa 90 kcal, 10 g Zucker nur etwa 40 kcal.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-111","thema":"B.L23","kapitel":"Ernährung","q":"Wie werden Vitamine und Mineralstoffe eingeteilt?","a":"Vitamine:\n• fettlöslich: A, D, E, K\n• wasserlöslich: C, B-Komplex\nMineralstoffe:\n• Mengenelemente (z. B. Natrium, Kalium, Kalzium, Magnesium)\n• Spurenelemente (z. B. Eisen, Jod, Zink)\n• Ultraspurenelemente (z. B. Nickel)","e":"Weitere Mengenelemente sind Chlorid, Phosphor und Schwefel; weitere Spurenelemente z. B. Fluorid, Selen, Kupfer, Mangan. Eselsbrücke für die fettlöslichen Vitamine: „EDEKA“ (E, D, K, A). Beispiel: Vitamin D aus Fisch wird besser aufgenommen, wenn etwas Fett dabei ist; für Ausdauersportler ist das Spurenelement Eisen wichtig für die Blutbildung.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-112","thema":"B.L23","kapitel":"Ernährung","q":"Welche Nährstoffe sind essenziell und warum?","a":"Wasser, einige Amino- und Fettsäuren, die meisten Vitamine, alle Mengen- und Spurenelemente – der Körper kann sie nicht selbst herstellen, sie müssen mit der Nahrung zugeführt werden.","e":"Essenziell heißt: ohne Zufuhr von außen geht es nicht. Beispiel: Omega-3-Fettsäuren kann der Körper nicht selbst bilden – man muss sie z. B. über Fisch, Walnüsse oder Rapsöl aufnehmen.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-113","thema":"B.L23","kapitel":"Ernährung","q":"Unterscheide Nährstoffbedarf und Nährstoffzufuhrempfehlung.","a":"• Bedarf: individuell nötige Menge, damit alle Körperfunktionen gesichert sind (abhängig von Alter, Geschlecht, Gesundheit, Sport, Klima)\n• Zufuhrempfehlung: Menge, die die Bevölkerung vor Unterversorgung schützt","e":"Bedarf gilt für dich persönlich, die Empfehlung für die Bevölkerung im Durchschnitt. Empfehlungen werden als tägliche Verzehrmenge oder als Nährstoffdichte angegeben. Leistungssportler haben einen höheren Bedarf an Kohlenhydraten und Proteinen als Gesundheitssportler. Beispiel: Ein Triathlet mit 20 Trainingsstunden pro Woche hat einen viel höheren Kohlenhydratbedarf, als die allgemeine Empfehlung angibt.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-114","thema":"B.L23","kapitel":"Ernährung","q":"Was ist die Nährstoffdichte und wie wird sie berechnet?","a":"Nährstoffzufuhr ÷ Energiezufuhr\n• Mikronährstoffe: mg pro 1.000 kcal\n• Makronährstoffe: En% = (g × kcal/g) ÷ Gesamtenergie × 100\nHoch bei nährstoffreichen/energiearmen Lebensmitteln","e":"Die Nährstoffdichte zeigt, wie viel „Gutes“ pro Kalorie drin ist, und dient auch zur Bewertung einzelner Lebensmittel; niedrig ist sie bei nährstoffarmen oder energiereichen Lebensmitteln. Beispiel aus dem Buch: 100 g Hüttenkäse liefern 12,6 g Eiweiß bei 102 kcal; 12,6 × 4 = 50,4 kcal, also rund 50 En% Eiweiß. Joghurt kommt nur auf etwa 15 En%.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-115","thema":"B.L23","kapitel":"Ernährung","q":"Welche Verteilung der Makronährstoffe empfiehlt die DGE und warum sind Prozentangaben für Sportler oft ungeeignet?","a":"DGE: Kohlenhydrate ca. 55 %, Fett ca. 30 %, Eiweiß 12–15 % der Energie.\nBei sehr hoher oder niedriger Energiezufuhr ungeeignet → für Sportler Angabe in g/kg Körpergewicht/Tag","e":"Prozent ist relativ: Bei riesigen Kalorienmengen ergeben 12–15 % viel mehr Eiweiß als nötig, bei sehr niedriger Zufuhr zu wenig. Deshalb gibt man für Sportler Kohlenhydrate und Eiweiß in g/kg/d an. Beispiel: Ein 75-kg-Radprofi mit über 5.000 kcal am Tag käme mit 12–15 % auf 150–188 g Eiweiß, also 2–2,5 g/kg – deutlich mehr als für Ausdauersportler empfohlen.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-116","thema":"B.L23","kapitel":"Ernährung","q":"Welche Tageszufuhr an Makronährstoffen wird für Freizeit-, Ausdauer- und Kraftsportler empfohlen (nach Schek, 2018)?","a":"Kohlenhydrate (g/kg/d): Freizeit 3–5 | Ausdauer 6–10 (1–3 h/d), 8–12 (4–5 h/d) | Kraft 5–7\nProtein (g/kg/d): Freizeit 0,8–1 | Ausdauer 1,2–1,4 | Kraft 1,2–1,7\nFett: 30 En% (Ausdauer 20–35 En%)","e":"Ausdauersportler brauchen vor allem viele Kohlenhydrate, Kraftsportler etwas mehr Eiweiß – aber weniger, als viele denken. Die Angaben richten sich nach der täglichen Trainingsdauer. Beispiel: Eine 60 kg schwere Läuferin mit 2 Stunden Training pro Tag braucht etwa 360–600 g Kohlenhydrate täglich.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-117","thema":"B.L23","kapitel":"Ernährung","q":"Welche Basiskost eignet sich für Sportler?","a":"Ausgewogene, abwechslungsreiche vollwertige Mischkost nach mediterranem Vorbild – wie für Nichtsportler; Wegweiser: 10 Regeln der DGE.","e":"Typisch mediterran sind Oliven- und Rapsöl, Nüsse und Samen. Sportler brauchen keine Spezialdiät, sondern eine gute normale Ernährung – nur eventuell mehr davon. Beispiel: Vollkornnudeln mit Gemüse, Olivenöl und etwas Fisch passen genauso für eine Handballerin wie für ihre Eltern.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-118","thema":"B.L23","kapitel":"Ernährung","q":"Nenne die Regeln 1 bis 5 der DGE für eine vollwertige Ernährung.","a":"1. Lebensmittelvielfalt genießen (überwiegend pflanzlich)\n2. Gemüse und Obst – „5 am Tag“\n3. Vollkorn wählen\n4. tierische Lebensmittel ergänzend\n5. gesundheitsfördernde Fette nutzen","e":"„5 am Tag“ heißt mindestens 3 Portionen Gemüse und 2 Portionen Obst, auch Hülsenfrüchte und ungesalzene Nüsse zählen. Tierisch: Milchprodukte täglich, Fisch 1–2-mal pro Woche, höchstens 300–600 g Fleisch pro Woche. Bei Fetten pflanzliche Öle wie Rapsöl bevorzugen und versteckte Fette (Wurst, Gebäck, Fast Food) meiden. Beispiel: Müsli mit Haferflocken, Joghurt und Beeren erfüllt gleich mehrere Regeln auf einmal.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-119","thema":"B.L23","kapitel":"Ernährung","q":"Nenne die Regeln 6 bis 10 der DGE für eine vollwertige Ernährung.","a":"6. Zucker und Salz einsparen\n7. Am besten Wasser trinken (ca. 1,5 l)\n8. Schonend zubereiten\n9. Achtsam essen und genießen\n10. Auf das Gewicht achten und in Bewegung bleiben","e":"Statt mit Salz würzt man mit Kräutern; getrunken werden Wasser oder ungesüßter Tee, keine zuckerhaltigen oder alkoholischen Getränke. Schonend heißt: so kurz wie möglich mit wenig Wasser und Fett garen, nichts verbrennen. Ernährung und körperliche Aktivität gehören zusammen. Beispiel: Wer Gemüse dämpft statt frittiert, Wasser statt Cola trinkt und mit dem Rad zur Schule fährt, setzt die Regeln 6, 7, 8 und 10 um.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-120","thema":"B.L23","kapitel":"Ernährung","q":"Was kennzeichnet die mediterrane Ernährung und welche gesundheitlichen Vorteile hat sie?","a":"Merkmale:\n• viel Pflanzliches (Obst, Gemüse, Hülsenfrüchte, Nüsse, Vollkorn)\n• Olivenöl als Hauptfett\n• mäßig Tierisches, wenig Süßes\nVorteile:\n• schützt vor Fettstoffwechselstörungen\n• beugt Glukosetoleranzstörungen (Typ-2-Diabetes) vor","e":"Tierische Lebensmittel sind v. a. Fisch, Geflügel, Eier und Milchprodukte; zum Essen ist bis zu ein Glas Wein üblich. Die begrenzte glykämische Last schützt vor Diabetes-Vorstufen. Im mediterranen Ernährungskreis (Schek) bildet der Außenkreis (Obst, Gemüse, Vollkorn …) zwei Drittel der Nahrung, der Innenkreis (Süßwaren, Weißmehl, Alkohol) ein Drittel. Beispiel: Ein Linsensalat mit Tomaten, Olivenöl und Vollkornbrot, dazu etwas Fisch, ist typisch mediterran.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-121","thema":"B.L23","kapitel":"Ernährung","q":"Welche täglichen Portionen einer mediterranen Ernährung empfiehlt Schek (2018) für Leistungssportler?","a":"• 9 Obst und Gemüse\n• 6 Vollkornprodukte\n• 3 stark blutzuckerwirksame Produkte (z. B. Reis, Nudeln, Bananen)\n• 3 fettarme Milchprodukte\n• 2 sonstige tierische Produkte\n• mit Raps-, Oliven- oder Walnussöl","e":"Eine Portion ist mindestens eine Handvoll, je nach Energiebedarf. Beim Obst und Gemüse dürfen 2 Portionen Saft sein, je eine lässt sich durch Nüsse bzw. Hülsenfrüchte ersetzen; tierische Produkte sind Fisch, Geflügel, Eier, mageres Fleisch; gelegentlich ist eine Portion Alkohol möglich. Merkhilfe: 9 – 6 – 3 – 3 – 2. Beispiel: Ein Ruderer isst morgens Müsli mit Obst, mittags Vollkornnudeln mit Gemüse und Hähnchen, nachmittags Banane und Quark.","quelle":"L23.1","typ":"kern"},{"id":"bonus.c-122","thema":"B.L23","kapitel":"Ernährung","q":"Erläutere die Bedeutung der energieliefernden Nährstoffe für ein gesundheitsorientiertes Fitnesstraining.","a":"• Kohlenhydrate: schnelle Energie für intensive Belastung (Glykogen)\n• Fette: Hauptenergie bei langer, mäßiger Belastung; essenzielle Fettsäuren, fettlösliche Vitamine\n• Proteine: Baustoff, Regeneration; kaum Energielieferant","e":"Gefüllte Glykogenspeicher erhalten Leistungsfähigkeit und Konzentration und müssen nach dem Training wieder aufgefüllt werden. Proteine bauen Muskulatur, Enzyme und Hormone auf und sind wichtig für die Anpassung nach Krafttraining. Alle drei gehören in ausgewogener Mischung nach DGE auf den Teller. Kohlenhydrate sind das Benzin für schnelle Fahrt, Fette der große Tank, Eiweiß das Baumaterial. Beispiel: Nach einem sanften Krafttraining hilft ein Vollkornbrot mit Quark beim Auffüllen der Speicher und beim Muskelaufbau.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"bonus.c-123","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Inwiefern kann das in der Werbung präsentierte Körperideal krank machen?","a":"• Werbung zeigt sehr schlanke Frauen und athletische Männer\n• Frauenideal gesundheitlich abzulehnen\n• kann zu gestörtem Essverhalten und Essstörungen führen (häufig bei Jugendlichen und Athleten)","e":"Das Männerideal kann gesundheitlich durchaus wünschenswert sein. Laut KiGGS-Studie zeigen 21,9 % der 11- bis 17-Jährigen Merkmale einer Essstörung, Mädchen fast doppelt so häufig; laut GOAL-Studie zeigen 35,5 % der 14- bis 18-jährigen Kaderathleten krankhaftes Essverhalten. Dabei bevorzugen Männer meist eine mittlere, nicht die dünnste Figur (Miller, 2001). Beispiel: Im Marathon heißt es spöttisch „Vorne laufen die Bleistifte, hinten tappen die Radiergummis“ – manche Läuferinnen hungern sich in die Magersucht.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-124","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Woraus setzt sich der Gesamtenergieumsatz eines Menschen zusammen?","a":"• Grundumsatz: lebensnotwendige Funktionen in Ruhe\n• Leistungsumsatz: körperliche Aktivität\n• thermogene Wirkung der Nahrung: Energie für die Nahrungsverarbeitung","e":"Gesamtumsatz = Grundumsatz + Leistungsumsatz + Thermogenese. Ist ein Bereich niedrig, begünstigt das eine Gewichtszunahme; hohe Werte schützen vor Übergewicht. Beispiel: Ein Schüler verbraucht im Schlaf (Grundumsatz), beim Fußballtraining (Leistungsumsatz) und sogar beim Verdauen seines Mittagessens (Thermogenese) Energie.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-125","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Welchen Einfluss hat die Muskelmasse auf den Grundumsatz und welche Folgen hat langes Fasten?","a":"• mehr Muskelmasse → höherer Grundumsatz (Muskel stoffwechselaktiver als Fett)\n• langes Fasten → Muskelabbau, GU sinkt (10 % Gewichtsverlust ≈ 16 % weniger GU)\n→ Abnehmen immer mit Krafttraining","e":"Muskeln sind „Kalorienfresser“, auch in Ruhe. Übergewichtige haben oft trotz geringerer Aktivität einen gleich hohen oder höheren Gesamtumsatz, weil sie mehr Muskulatur zum Tragen ihres Gewichts besitzen. Sport erzeugt eine negative Energiebilanz, die eine Ernährungsumstellung verstärkt. Beispiel: Wer durch eine Crash-Diät Muskeln verliert, verbraucht danach im Alltag weniger Energie und nimmt bei normalem Essen schnell wieder zu.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-126","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Was ist der PAL-Wert und wie schätzt man damit den Gesamtumsatz?","a":"PAL (physical activity level) = Maß für körperliche Aktivität.\nGesamtumsatz ≈ Grundumsatz × PAL\nWerte: 1,2 (nur sitzend/liegend) bis 2,4 (Schwerstarbeit)","e":"Der PAL-Wert ist ein international anerkannter Multiplikator für deinen Alltag. Beispiel: Eine Schülerin mit 1.400 kcal Grundumsatz und überwiegend sitzender Tätigkeit plus etwas Sport (PAL etwa 1,6) verbraucht rund 2.240 kcal pro Tag.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-127","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Welche einfachen Verfahren zur Ermittlung von Übergewicht gibt es?","a":"• Broca-Formel\n• Body-Mass-Index (BMI)\n• Taillen-Hüft-Verhältnis (Waist-to-Hip-Ratio, WHR) und Taillenumfang","e":"Alle drei kommen ohne teure Geräte aus – nur Waage und Maßband. Beispiel: Beim Sportarzt werden oft BMI und Taillenumfang zusammen bestimmt, weil sich die Verfahren gegenseitig ergänzen.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-128","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Erläutere die Broca-Formel und ihre Grenzen.","a":"• Normalgewicht (kg) = Größe (cm) – 100\n• Sollgewicht: Frauen × 0,85, Männer × 0,90\n• Übergewicht ab 1,10 × Normalgewicht\nGrenzen: ungeeignet für Kinder/Jugendliche; Kleine zu oft, Große zu selten übergewichtig","e":"Der Vorteil ist die sehr einfache Handhabung – die Formel ist schnell im Kopf gerechnet, aber grob. Beispiel: Ein 180 cm großer Mann hat ein Normalgewicht von 80 kg, ein Sollgewicht von 72 kg und gilt ab 88 kg als übergewichtig.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-129","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Wie berechnet man den BMI und wie klassifiziert die WHO das Körpergewicht danach?","a":"BMI = Gewicht (kg) ÷ Größe (m)²\nWHO (kg/m²):\n• Untergewicht < 18,5 (stark < 16, mäßig 16–17, leicht 17–18,5)\n• Normalgewicht 18,5–25\n• Präadipositas 25–30\n• Adipositas I 30–35, II 35–40, III ≥ 40","e":"Die Klassifikation gilt für Erwachsene. Wichtig sind vor allem die Grenzen 18,5, 25 und 30. Beispiel aus dem Buch: Ein 1,83 m großer Mann mit 85 kg hat einen BMI von 85 ÷ 1,83² ≈ 25,4 und gilt laut WHO als übergewichtig (präadipös).","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-130","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Bewerte den BMI kritisch.","a":"• Vorteil: einfach, schnell, vergleichbar\n• unterscheidet nicht zwischen Fett- und Muskelmasse (bei Sportlern ungeeignet)\n• Fettverteilung (Bauchfett) nicht erfasst\n• feste Grenzwerte daher umstritten","e":"Ein hohes Gewicht kann auch durch viel Muskelmasse, hohe Knochendichte, starke Knochen oder breite Schultern entstehen; Männer haben zudem mehr Muskeln als Frauen. Der BMI sieht nur das Gewicht, nicht, woraus es besteht. Beispiel: Ein Rugbyspieler mit 1,85 m und 100 kg hat einen BMI von etwa 29 und wäre „übergewichtig“, obwohl er kaum Körperfett hat. Eine Körperanalysewaage würde das zeigen.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-131","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Wie wird das Taillen-Hüft-Verhältnis (THV) berechnet und interpretiert?","a":"THV = Taillenumfang ÷ Hüftumfang; hoher Wert = erhöhtes Herz-Kreislauf-/Stoffwechselrisiko.\nFrauen | Männer:\n• gering: < 0,80 | < 0,90\n• leicht erhöht: 0,80–0,85 | 0,90–1,0\n• hoch: > 0,85 | > 1,0\nTaille: Risiko ab > 88 | > 102 cm","e":"Gemessen wird die Taille in der Mitte zwischen unterer Rippe und oberem Beckenkamm, die Hüfte an der breitesten Stelle. Hohe Werte weisen auch auf ein metabolisches Syndrom hin. Zielwerte für den Taillenumfang sind unter 80 cm (Frauen) bzw. unter 94 cm (Männer). Das THV erfasst, wo das Fett sitzt – und Bauchfett ist besonders gefährlich. Beispiel: Ein Mann mit 100 cm Taille und 95 cm Hüfte hat ein THV von etwa 1,05 und damit ein hohes Risiko, auch wenn sein BMI unauffällig sein mag.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-132","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Warum ist Krafttraining ein unverzichtbarer Bestandteil eines Programms zur Gewichtsreduktion?","a":"• erhält/erhöht Muskelmasse → höherer Grundumsatz → Fettabbau\n• ohne Krafttraining bis zu 50 % des Gewichtsverlusts aus Muskeln → GU sinkt → erneute Zunahme","e":"Bei kalorienreduzierter Ernährung ohne Krafttraining und genug Eiweiß verliert man viel Muskulatur; danach braucht der Körper weniger Kalorien und nimmt leichter wieder zu. Muskeln verbrauchen rund um die Uhr Energie, auch im Schlaf: 0,5–1 kg Muskelmasse verbrennen etwa 50 kcal pro Tag mehr als Fett. Beispiel: Zwei Personen machen dieselbe Diät; die mit Krafttraining hat am Ende einen höheren Grundumsatz und hält ihr Gewicht leichter.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-133","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Warum ist beim Abnehmen der Körperfettanteil wichtiger als das Körpergewicht?","a":"• Ziel ist Fettabbau, nicht bloß Gewichtsverlust\n• Muskeln sind schwerer als Fett: Bei Muskelerhalt sinkt das Gewicht langsamer\n• langfristig höherer Grundumsatz","e":"Die Waage kann täuschen: Wer vor allem Fett abbaut und Muskeln erhält, sieht anfangs weniger Erfolg auf der Waage als jemand, der gleichzeitig Muskeln verliert. Beispiel: Eine Frau, die mit Krafttraining beginnt, verliert in einem Monat nur 1 kg, ihre Hose sitzt aber deutlich lockerer – sie hat Fett ab- und Muskeln aufgebaut.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-134","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Welche Bedeutung hat Ausdauertraining für die Gewichtsreduktion?","a":"• erhöht den Leistungs- und damit den Gesamtumsatz\n• erschwert Fetteinlagerung\n• stärkt Herz-Kreislauf, Wohlbefinden\n• entscheidend: negative Energiebilanz, nicht die Art der Energiebereitstellung","e":"Intensives Ausdauertraining ist ebenso empfehlenswert wie moderates, langes Training, sofern keine Gelenkschäden drohen. Abnehmen tut man aber nur, wenn insgesamt mehr verbraucht als gegessen wird. Beispiel: Wer nach dem Joggen zur Belohnung ein großes Stück Kuchen isst, hat den Kalorienverbrauch schnell wieder ausgeglichen.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-135","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Erläutere das Missverständnis vom „Fettverbrennungstraining“ mit niedriger Intensität (Vergleich zweier Läufer).","a":"• Abnehmen hängt von der Energiebilanz ab, nicht vom Fettanteil der Energiebereitstellung\n• Läufer 1 (langsam): 300 kcal, 70 % Fett = 210 kcal\n• Läufer 2 (intensiver, gleiche Dauer): 500 kcal, 50 % Fett = 250 kcal","e":"„Fettverbrennung“ beschreibt nur die Art der Energiebereitstellung. Beim langsamen Laufen (extensive Dauermethode) ist der prozentuale Fettanteil höher, die absolute Menge aber geringer als bei der intensiven Dauermethode. Niedrige Intensität bleibt trotzdem sinnvoll, weil sie schonend und gut für Einsteiger ist. Beispiel: 70 % von 300 kcal sind weniger als 50 % von 500 kcal – wer gleich lange schneller läuft, verbrennt insgesamt mehr Fett.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-136","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Was bedeutet der Begriff Diät und welche Grundsätze gelten für Diäten zur Gewichtsreduktion?","a":"Griech. „diaita“ = Lebensführung; auf Kranke/Übergewichtige abgestimmte Ernährung.\nGrundsätze:\n• gesunde Ernährung + Gewichtsreduktion\n• keine einseitigen Crashdiäten\n• nur ärztlich begleitet, im ganzheitlichen Programm","e":"Umgangssprachlich meint Diät eine Reduktionsdiät. Neben mediterraner und vollwertiger Kost gibt es Low Carb (kohlenhydratreduziert) und Low Fat (fettreduziert). Von stark kalorienreduzierten Diäten mit rigidem Essverhalten ist dringend abzuraten; Ernährungsberatung gehört dazu. Eigentlich meint Diät eine dauerhafte Lebensweise. Beispiel: Eine dauerhafte Umstellung auf mediterrane Kost ist eine sinnvolle „Diät“, eine zweiwöchige Saftkur nicht.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-137","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Welche Ernährungsmuster eignen sich zur Gewichtsreduktion und was ist bei ihnen zu beachten (nach Schek, 2018)?","a":"Voraussetzung immer: negative Energiebilanz.\n• mediterran, vollwertig, vegetarisch: sportgerecht, gesund\n• paläolithisch: wenig Kohlenhydrate/Ballaststoffe\n• Low Glycemic: wenig schnelle Kohlenhydrate\n• Low Carb: nur in Sportpausen\n• Low Fat","e":"Mediterrane, vollwertige und vegetarische Kost sind mit hohen Leistungen vereinbar und mit hoher Lebenserwartung verbunden. Paläo heißt naturbelassene Pflanzenkost, Eier, mageres Fleisch, aber kein Getreide und keine Milch. Low Glycemic meidet Stärke und Zucker, wodurch rund um die Belastung schnelle Energie fehlt. Die Wahl hängt von Gesundheit, Genetik, Umsetzbarkeit und Vorlieben ab, der Einstieg am besten mit Fachkraft. Beispiel: Eine Ausdauersportlerin sollte im Training nicht Low Carb essen, weil ihr dann die Energie für intensive Einheiten fehlt.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-138","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Welche Nachteile haben einseitige Reduktionsdiäten?","a":"• Muskel- statt Fettabbau\n• Sparbetrieb (GU ↓), danach vermehrte Fetteinlagerung\n• Nährstoffmangel\n• Leistungsabfall (Müdigkeit, Heißhunger, Konzentration ↓)\n• Essstörungen\n• psychischer Teufelskreis\n• keine dauerhafte Verhaltensänderung","e":"Der Körper deutet die Diät als Hungersnot und kompensiert danach über. Typisch sind auch Kreislaufstörungen und Verstopfung; Heißhungerattacken können z. B. in eine Bulimie führen. Erneute Zunahme wird als Versagen erlebt, die nächste Diät folgt. Anfangserfolge sind oft nur Wasser und Muskeln. Beispiel: Bei einer Hollywood-Diät mit etwa 450 kcal am Tag verliert man in einer Woche einige Kilo – und ist danach müde, schlapp und schnell wieder schwerer.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-139","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Erkläre den Jo-Jo-Effekt.","a":"• sehr geringe Energiezufuhr → Körper schaltet auf Sparbetrieb (GU ↓, Muskelabbau)\n• nach der Diät Überkompensation mit vermehrten Fettdepots\n• Gewicht steigt rasch, oft über den Ausgangswert\n• wiederholter Kreislauf","e":"Der Körper deutet die geringe Zufuhr als Hungersnot und sichert sein Überleben, indem er spart und anschließend Reserven anlegt. Wie ein Jo-Jo geht das Gewicht runter und wieder hoch. Beispiel: Jemand nimmt mit einer Crash-Diät 6 kg ab, isst danach normal und wiegt nach drei Monaten 2 kg mehr als vor der Diät.","quelle":"L23.2","typ":"kern"},{"id":"bonus.c-140","thema":"B.L23","kapitel":"Gewichtsreduktion","q":"Entwirf die Grundzüge eines ganzheitlichen Programms zur Gewichtsreduktion.","a":"• Ernährung: moderate negative Energiebilanz, vollwertig/mediterran, genug Eiweiß\n• Bewegung: Krafttraining, Ausdauertraining, aktiver Alltag\n• Psyche/Umfeld: realistische Ziele, soziale Unterstützung, Stressbewältigung, fachliche Begleitung","e":"Kein Crash: viel Gemüse, Vollkorn, Wasser statt Softdrinks. Krafttraining 2–3-mal pro Woche erhält Muskeln und Grundumsatz, Ausdauer erhöht den Leistungsumsatz, Rad und Treppe machen den Alltag aktiv. Maßstab ist der Körperfettanteil statt der Waage; Selbstkonzept, Gruppe, Schlaf und achtsames Essen fördern die Bindung, Arzt und Ernährungsfachkraft begleiten. Beispiel: Ein übergewichtiger Jugendlicher, der in einer Sportgruppe zweimal pro Woche trainiert, Softdrinks durch Wasser ersetzt und von Freunden unterstützt wird, hält sein Gewicht langfristig besser als mit einer Hungerkur.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.1-001","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Aus welchen wissenschaftlichen Perspektiven kann sportliche Leistung betrachtet werden? Nenne die Disziplinen und ihren jeweiligen Schwerpunkt.","a":"• Biomechanik: P = Arbeit/Zeit (Watt)\n• Sportmedizin: Watt bezogen auf physiologische Kriterien (VO2max, Laktat)\n• Trainingslehre: systematische Leistungsansteuerung\n• Bewegungslehre: Bewegungslernen, Koordination\n• Sportpädagogik: Leistungsentwicklung/-bewertung\n• Sportpsychologie: Leistungsmotivation\n• Sportsoziologie: gesellschaftliche Bezugssysteme","e":"Leistung ist im Sport kein eindeutiger Begriff: Jede Wissenschaft schaut mit einer eigenen Brille darauf. Die Pädagogik denkt dabei an Bildung und Erziehung, die Psychologie an Leistungsmotiv und Motivation. Beispiel: Ein 100-m-Lauf ist für die Biomechanik eine Frage von Kraft und Geschwindigkeit, für die Psychologie eine Frage der Motivation und für die Pädagogik eine Frage, ob der Schüler sich verbessert hat.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-002","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Wie wird Leistung in der Biomechanik definiert?","a":"Leistung (P, power) = Geschwindigkeit, mit der mechanische Arbeit verrichtet wird:\nP = W / t, Einheit Watt.","e":"Wer dieselbe Arbeit schneller verrichtet, leistet mehr. Beispiel: Zwei Sportler laufen dieselbe Treppe hinauf und haben gleiches Gewicht. Wer schneller oben ist, hat die gleiche Arbeit in kürzerer Zeit verrichtet und damit eine höhere Leistung in Watt erbracht.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-003","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Wie wird sportliche Leistung in Sportbiologie/Sportmedizin und in der Trainingslehre verstanden?","a":"• Sportbiologie/-medizin: Leistung in Watt, interpretiert über physiologische Kriterien (VO2max, Laktat)\n• Trainingslehre: systematische Ansteuerung; Leistung = Ergebnis in einer Wettkampfsituation (Zeit, Punkte, Tore)","e":"Die Sportmedizin fragt: Was passiert im Körper bei einer bestimmten Wattzahl? Sie bezieht die Leistung z. B. auf das Herz-Kreislauf-System (maximale Sauerstoffaufnahme pro Minute) oder den Stoffwechsel (Laktat im Blut). Die Trainingslehre orientiert sich am Sprachgebrauch des Wettkampfsports und fragt: Wie bekomme ich durch Training ein besseres Wettkampfergebnis? Beispiel: Auf dem Fahrradergometer wird bei 200 Watt der Laktatwert gemessen (Sportmedizin); die Trainingslehre nutzt das, um die Laufzeit über 5.000 m zu verbessern.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-004","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Was versteht die Bewegungslehre unter sportlicher Leistung und was meint die übersummative Dominanz der Gesamtleistung?","a":"• Bewegungslehre: Prozesse/Strukturen, die Bewegungsleistungen hervorbringen (Bewegungslernen, Koordination als leistungsbestimmend)\n• Übersummative Dominanz (Prohl): Die Gesamtleistung ist mehr als die Summe ihrer Teilleistungen.","e":"Eine Bewegungsleistung ist also keine bloß linear aneinandergereihte Kette von Teilleistungen. Ein Speerwurf ist nicht einfach Anlauf + Stemmschritt + Abwurf, die man getrennt verbessert und dann addiert. Erst das flüssige Zusammenspiel aller Teile ergibt die Weite. Beispiel: Ein Werfer mit schnellem Anlauf, aber schlechtem Timing beim Abwurf wirft trotzdem kurz.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-005","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Wie betrachten Sportsoziologie und Sportpsychologie die sportliche Leistung?","a":"Sportsoziologie:\n• gesellschaftliche Bedingungen und Wertesystem\n• magisches Viereck: Leistung – Konkurrenz – Gleichheit – Freiheit\nSportpsychologie:\n• Motivation und Lernen\n• Leisten als Auseinandersetzung mit einem Gütemaßstab, Ergebnis als selbst verursacht erlebt","e":"Die Soziologie fragt, welchen Wert eine Gesellschaft der Leistung gibt; Leistung dient dort als Differenzierungskriterium. Die Psychologie fragt, warum ein Mensch überhaupt etwas leisten will: Leistungsmotiviertes Handeln will das eigene Können zeigen. Beispiel: Ein Schüler trainiert für das Sportabzeichen, weil er stolz sein will, es selbst geschafft zu haben (Psychologie). Dass es überhaupt Abzeichen und Urkunden gibt, zeigt den gesellschaftlichen Wert von Leistung (Soziologie).","quelle":"L10.1","typ":"kern"},{"id":"q1.1-006","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Wie wird Leistung in der Sportpädagogik verstanden?","a":"• Leistung im Kontext von Bildung und Erziehung\n• Leistungsvollzug (Prozess) vor Leistungsergebnis\n• zentrale Rolle der Bezugsnorm: von individuell über interindividuell zu sozial","e":"Für die Pädagogik zählt nicht nur, wer gewinnt, sondern was ein Kind beim Leisten erlebt und lernt. Pädagogisch begleitete Leistungsentwicklung beginnt bei der Steigerung der eigenen Leistung, geht über spielerisches Wetteifern und endet bei den sozialen Normen des Wettkampfsports. Beispiel: Ein Kind lernt zuerst, die eigene Weitsprungweite zu verbessern, dann misst es sich spielerisch mit Mitschülern und erst später bei Bundesjugendspielen mit Normtabellen.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-007","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Erläutere den Unterschied zwischen Leistung als Produkt (Ergebnis) und Leistung als Prozess.","a":"• Produkt: Ergebnis einer Handlung in einer Anforderungssituation (Trainings-/Bewegungslehre, Biomechanik, Sportbiologie)\n• Prozess: aktuelles Handeln bezogen auf Leistungsmöglichkeiten/-fortschritte über längere Zeit (Sportpädagogik)\n• Bewertung hängt von der Bezugsnorm ab (Franke & Prohl).","e":"Beim Produkt zählt nur die Zahl am Ende, beim Prozess der Weg dorthin, also das Leisten selbst. Beispiel: Eine 1.500-m-Zeit von 6:30 min ist als Produkt eher schwach. Als Prozess betrachtet kann sie stark sein, wenn die Schülerin vor einem halben Jahr noch 8 Minuten gebraucht hat.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-008","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Nenne und erläutere die drei Bezugsnormen zur Bewertung sportlicher Leistung.","a":"• Individuell: Vergleich mit eigener früherer Leistung\n• Sozial: Vergleich mit anderen (Altersgruppe, Tabellen)\n• Sachlich: Vergleich mit objektivem Gütemaßstab (Kriterium erreicht oder nicht)","e":"Dieselbe Leistung kann je nach Maßstab ganz unterschiedlich bewertet werden. Beispiel Cooper-Test: 2.200 m sind für einen 15-Jährigen laut Tabelle befriedigend (sozial). Hat er sich um 400 m verbessert, kann der Lehrer das mit sehr gut bewerten (individuell). Verlangt der Lehrer nur 30 Minuten Laufen mit mindestens 6 km/h, ist das eine sachliche Norm.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-009","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Welche Faktoren beeinflussen, welche individuelle Bedeutung ein Sportler einer gemessenen Leistung zuschreibt?","a":"• Können\n• Aufgabenschwierigkeit\n• Tagesform\n• Anspruchsniveau\n• äußere Bedingungen","e":"Leistungen werden immer von einzelnen Menschen erbracht, die den Messwerten eine eigene Bedeutung geben. Deshalb können je nach Situation unterschiedliche Bezugsnormen (individuell, sozial, sachlich) zum Tragen kommen. Beispiel: Eine 100-m-Zeit von 13,5 s ist für eine Sprinterin bei Gegenwind und schlechter Tagesform ein Erfolg, für eine andere mit hohem Anspruchsniveau bei Idealbedingungen eine Enttäuschung.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-010","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Beurteile, welche Bezugsnormen in verschiedenen Bewegungsfeldern hauptsächlich zum Tragen kommen.","a":"• Sozial: messbare Wettkampfsportarten (Leichtathletik, Schwimmen), Sportspiele\n• Sachlich: feste Kriterien, z. B. Turnen, Akrobatik, Klettern, Sportabzeichen\n• Individuell: Gesundheits-, Freizeitsport, Schulsport (Lernfortschritt)\n• oft kombiniert","e":"Je mehr eine Sportart auf Rekorde und Ranglisten ausgerichtet ist, desto stärker zählt der Vergleich mit anderen (Sieg/Niederlage, Tabellen). Im Turnen zählen Ausführungskriterien, im Freizeitsport wie Inlineskaten oder Fitness eher der eigene Fortschritt. Beispiel: Beim Klettern zählt vor allem, ob man eine Route im Schwierigkeitsgrad 6 schafft (sachlich), beim 100-m-Finale nur die Platzierung (sozial).","quelle":"L10.1","typ":"zusatz"},{"id":"q1.1-011","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Beurteile den schulischen Leistungsbegriff im Sport kritisch.","a":"• oft soziale Norm (Tabellen, Bundesjugendspiele) → ergebnisorientiert\n• Problem: ungleiche Voraussetzungen, Demotivation, Bloßstellung\n• gefordert: Vollzug vor Ergebnis, individuelle Norm\n• aber: Wettkampf gehört zum Sport, Noten brauchen Maßstäbe\n• Fazit: Mischung der drei Normen","e":"Konstitution, Talent und Vorerfahrung sind ungleich verteilt. Wer nur nach Tabelle benotet, belohnt vor allem Begabung. Wer nur den Fortschritt (Lernzuwachs, Anstrengung) bewertet, benachteiligt Schüler, die schon gut sind und sich kaum noch steigern können. Beispiel: Eine Turnnote kann aus der Ausführung (sachlich), dem Vergleich mit der Klasse (sozial) und dem Lernzuwachs (individuell) zusammengesetzt werden.","quelle":"L10.3","typ":"zusatz"},{"id":"q1.1-012","thema":"Q1.1","kapitel":"Leistung im Sport","q":"Erörtere, ob die Bundesjugendspiele verbindlicher Teil des Sportunterrichts sein sollten.","a":"Pro:\n• Leistung/Wettkampf als Kern des Sports, Umgang mit Erfolg/Misserfolg\n• objektive Messung, Leistungsanreiz\nContra:\n• Zwang, Demütigung, sozialer Druck\n• individuelle Fortschritte unberücksichtigt\nKompromiss:\n• Teamwertung, vielseitige Aufgaben, Würdigung individueller Verbesserung","e":"Hier steht die soziale gegen die individuelle Bezugsnorm. Die Spiele können Anlass für Training und Bewegungsförderung sein, chancenlose Schüler erleben sie aber oft als sinnlos. Denkbar sind auch eine freiwillige Wettkampfform und der Verzicht auf öffentliche Bloßstellung. Beispiel: Ein Kompromiss ist, dass die Klasse als Team Punkte sammelt und jeder Schüler zusätzlich für eine persönliche Bestleistung belohnt wird. So bleibt der Wettkampfgedanke erhalten, ohne einzelne Schüler vorzuführen.","quelle":"L10.3","typ":"zusatz"},{"id":"q1.1-013","thema":"Q1.1","kapitel":"Komponentenmodell","q":"Beschreibe das Komponentenmodell der sportlichen Leistung (nach Ehlenz et al.).","a":"Sechs sich gegenseitig beeinflussende Komponenten:\n• Kondition\n• Technik/Koordination\n• Taktik\n• Psyche (Motivation, Volition, Emotion)\n• Rahmenbedingungen (Talent, Gesundheit, Konstitution)\n• äußere Bedingungen (Material, Umfeld, Trainer)","e":"Die Komponenten gehen fließend ineinander über. Zur Kondition gehören Ausdauer, Kraft, Schnelligkeit und Beweglichkeit, zur Taktik sensomotorische und kognitive Fähigkeiten. Niemand gewinnt nur durch Kraft oder nur durch Technik. Beispiel: Ein Tennisspieler mit perfekter Vorhand (Technik) verliert, wenn er nach zwei Sätzen konditionell einbricht oder bei Matchball nervös wird (Psyche). Eselsbrücke: KoTe-TaPsy-RaÄu (Kondition, Technik, Taktik, Psyche, Rahmen, Äußeres).","quelle":"L10.1","typ":"kern"},{"id":"q1.1-014","thema":"Q1.1","kapitel":"Komponentenmodell","q":"Worin unterscheiden sich im Komponentenmodell die Rahmenbedingungen von den äußeren Bedingungen?","a":"• Rahmenbedingungen: personeninterne, weitgehend vorgegebene Voraussetzungen (Talent, Gesundheit, Konstitution)\n• Äußere Bedingungen: Umwelteinflüsse (Wettkampf, Material, Trainingsumgebung, Familie, Beruf, Trainer)","e":"Rahmenbedingungen trägt man in sich, äußere Bedingungen kommen von außen. Beispiel: Die Körpergröße eines Basketballers ist eine Rahmenbedingung, die Qualität seines Trainers oder ein rutschiger Hallenboden sind äußere Bedingungen.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-015","thema":"Q1.1","kapitel":"Komponentenmodell","q":"Erläutere die Bedeutung der Kondition für die sportliche Leistung im Rahmen des Komponentenmodells.","a":"• eine von sechs Komponenten; körperlich-energetische Basis\n• Voraussetzung, damit Technik und Taktik unter Ermüdung stabil bleiben\n• Anteil sportartabhängig (Marathon vs. Schießen)\n• außer Ausdauer eng mit Koordination verknüpft","e":"Kondition umfasst Ausdauer, Kraft, Schnelligkeit und Beweglichkeit und wirkt immer mit den anderen Komponenten zusammen. Sie ist sozusagen der Motor, Technik das Lenkrad. Beispiel: Ein Fußballer kann in der 85. Minute nur dann noch präzise flanken, wenn seine Ausdauer verhindert, dass Ermüdung seine Technik zerstört.","quelle":"L10.1","typ":"zusatz"},{"id":"q1.1-016","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Definiere Kondition.","a":"Kondition (lat. conditio = Bedingung) ist der Sammelbegriff für die konditionellen Fähigkeiten Ausdauer, Kraft, Schnelligkeit und Beweglichkeit.","e":"Diese vier werden auch konditionelle Grundeigenschaften genannt. Kondition ist also kein einzelnes Merkmal, sondern ein Oberbegriff. Beispiel: Wenn jemand sagt, ein Fußballer habe eine gute Kondition, meint er streng genommen nicht nur die Ausdauer, sondern auch Kraft, Schnelligkeit und Beweglichkeit.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-017","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Nenne die Kurzdefinitionen der vier konditionellen Fähigkeiten.","a":"• Ausdauer: Ermüdungswiderstandsfähigkeit + rasche Erholungsfähigkeit\n• Kraft: neuromuskuläres Vermögen, Widerstände zu überwinden, zu halten oder abzubremsen\n• Schnelligkeit: Aktionen möglichst schnell ausführen\n• Beweglichkeit: Muskeldehnfähigkeit + Gelenkigkeit","e":"Diese vier Formeln sind das Grundgerüst für Lektion 12 bis 15. Gelenkigkeit meint den Aktionsradius der Gelenke. Beispiel: Bei der Übung Auf und ab (Ball hochwerfen, hinsetzen, fangen, aufstehen) braucht man Kraft zum Aufstehen, Beweglichkeit für den tiefen Hockstand, Ausdauer für viele Durchgänge und Schnelligkeit, wenn man möglichst viele in 30 Sekunden schaffen will.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-018","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Definiere Ausdauer und erläutere ihre zwei Komponenten.","a":"Ausdauer = Ermüdungswiderstandsfähigkeit + rasche Erholungsfähigkeit\n• Ermüdungswiderstand: Ermüdung bei (langer) Belastung widerstehen\n• Erholungsfähigkeit: sich nach Belastung schnell erholen","e":"Beide Komponenten zusammen bestimmen die Ausdauerleistungsfähigkeit: Ein ausdauernder Sportler wird langsamer müde und ist schneller wieder fit. Beispiel: Im Fußball muss ein Spieler 90 Minuten durchhalten (Ermüdungswiderstand) und sich nach jedem Sprint in kurzen Gehpausen schnell erholen (Erholungsfähigkeit).","quelle":"L10.1","typ":"kern"},{"id":"q1.1-019","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Definiere Kraft und Beweglichkeit (Kurzformeln aus dem Grundlagenkapitel).","a":"• Kraft: neuromuskuläres Vermögen, Widerstände zu überwinden, zu halten oder abzubremsen\n• Beweglichkeit = Muskeldehnfähigkeit + Gelenkigkeit (Aktionsradius der Gelenke)","e":"Das Wort neuromuskulär zeigt schon: Kraft ist nicht nur Muskelmasse, das Nervensystem steuert mit. Beispiel: Beim Aufstehen aus dem Sitzen ohne Hände braucht man Beinkraft, aber auch Gleichgewicht. Für den Sohlenhockstand braucht man ein bewegliches Sprunggelenk (Gelenkigkeit) und eine dehnfähige Wadenmuskulatur.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-020","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Erläutere den Unterschied zwischen energetisch und informationell determinierten Fähigkeiten und ordne Kondition und Koordination zu.","a":"• Energetisch: abhängig von Energiebereitstellung (Stoffwechsel)\n• Informationell: abhängig von Steuerung/Regelung durch das ZNS\nZuordnung:\n• Ausdauer: energetisch\n• Kraft, Schnelligkeit, Beweglichkeit: energetisch + informationell\n• Koordination: informationell","e":"Energetisch heißt: Der Tank entscheidet. Informationell heißt: Die Steuerzentrale entscheidet, also Informationsaufnahme und -verarbeitung im Gehirn. Beispiel: Bei einem Marathon zählt vor allem die Energiebereitstellung, beim Sprintstart dagegen stark, wie schnell und gut das Nervensystem die Muskeln ansteuert.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-021","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Erkläre den Zusammenhang zwischen konditionellen und koordinativen Fähigkeiten.","a":"Außer der (energetischen) Ausdauer sind alle konditionellen Fähigkeiten eng mit Koordination verknüpft:\n• Kraft: inter-/intramuskuläre Koordination\n• Schnelligkeit: neuromuskuläre Steuerung\n• Beweglichkeit: Zusammenspiel der Muskeln","e":"Muskelaktivität hat immer auch mit vom Gehirn gesteuerten Informationsprozessen zu tun. Bei der Kraft müssen die Muskeln z. B. so zusammenarbeiten, dass das Gleichgewicht gehalten wird. Kondition und Koordination sind keine getrennten Schubladen, sondern überlappen sich. Beispiel: Ein Sprinter kann noch so starke Beine haben – wenn Beuger und Strecker nicht im richtigen Moment an- und abschalten, wird er nicht schnell.","quelle":"L10.1","typ":"kern"},{"id":"q1.1-022","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Wie lassen sich die motorischen Fähigkeiten grundsätzlich einteilen?","a":"• Konditionell (vorwiegend energetisch): Ausdauer, Kraft, Schnelligkeit, Beweglichkeit\n• Koordinativ (vorwiegend informationell): z. B. Kopplung, Differenzierung, Gleichgewicht, Orientierung, Rhythmisierung, Reaktion, Umstellung\n• Mischformen: z. B. Kraftausdauer, Schnellkraft","e":"Motorische Fähigkeiten sind relativ verfestigte, verallgemeinerte Leistungsvoraussetzungen für Bewegungen. Man kann sich eine Skala vorstellen: links das rein Energetische (Ausdauer), rechts das rein Informationelle (Koordination), dazwischen Kraft, Schnelligkeit und Beweglichkeit. Schnelligkeit und Beweglichkeit gelten daher als konditionell-koordinativ; auch Schnelligkeitsausdauer ist eine Mischform. Beispiel: Schnelligkeit wird im Buch ausdrücklich als konditionell und koordinativ bestimmte Fähigkeit definiert.","quelle":"L10.1/L14.1","typ":"zusatz"},{"id":"q1.1-023","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Erläutere den Unterschied zwischen Fähigkeiten und Fertigkeiten.","a":"• Fähigkeiten: allgemeine, sportartübergreifende Leistungsvoraussetzungen\n• Fertigkeit (Technik): konkrete Bewegungshandlung zur Lösung einer sporttypischen Bewegungsaufgabe (Bösing et al.)\n• Fähigkeiten sind Grundlage für Fertigkeiten.","e":"Fähigkeiten sind wie das Werkzeug, Fertigkeiten wie das fertige Werkstück. Beispiel: Die Rhythmisierungsfähigkeit ist eine Fähigkeit; der Flop im Hochsprung ist eine Fertigkeit, die unter anderem einen gut rhythmisierten Anlauf voraussetzt.","quelle":"L04.1","typ":"kern"},{"id":"q1.1-024","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Definiere Koordination aus sportmedizinischer Sicht und als Leistungskomponente.","a":"• Sportmedizinisch (Hollmann/Strüder): Zusammenwirken von ZNS und Skelettmuskulatur innerhalb eines gezielten Bewegungsablaufs\n• Leistungskomponente (Hohmann et al.): Sammelbezeichnung für die koordinativen Fähigkeiten","e":"Das Wort kommt von lat. cum ordo = mit Ordnung: Koordination bringt Ordnung in die Bewegung. Das Gehirn muss sehr viele Muskeln zeitlich und kräftemäßig aufeinander abstimmen. Beispiel: Beim Kraulschwimmen müssen Armzug, Beinschlag und Atmung zusammenpassen – sonst kommt man trotz viel Kraft kaum voran.","quelle":"L04.1","typ":"kern"},{"id":"q1.1-025","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Nenne die sieben koordinativen Fähigkeiten und ordne sie den koordinativen Grundfähigkeiten nach Hirtz zu.","a":"Kopplung, Differenzierung, Gleichgewicht, Orientierung, Rhythmisierung, Reaktion, Umstellung\nHirtz:\n• Steuerungsfähigkeit: Kopplung, Differenzierung, Gleichgewicht, Orientierung, Rhythmisierung\n• Adaptionsfähigkeit: Gleichgewicht, Orientierung, Rhythmisierung, Reaktion, Umstellung\n• Motorische Lernfähigkeit: alle sieben","e":"Gleichgewicht, Orientierung und Rhythmisierung gehören zu beiden Grundfähigkeiten. Das beste koordinative Lernalter liegt bei etwa 7 bis 12 Jahren. Eselsbrücke: K-D-G-O-R-R-U. Beispiel: Ein Handballer beim Kempa-Trick braucht Orientierung in der Luft, Kopplung von Sprung und Wurf und Reaktion auf den Pass.","quelle":"L04.2","typ":"kern"},{"id":"q1.1-026","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Beschreibe, wie man die Ausdauer differenzieren kann (Überblick).","a":"• Sportspezifik: allgemein / speziell\n• Energiebereitstellung: aerob / anaerob\n• Dauer: Kurzzeit (35 s–2 min), Mittelzeit (2–10 min), Langzeit (>10 min)\n• Muskelmasse: lokal (<1/6) / global (>1/6)\n• Belastungsform: statisch / dynamisch\n• Mischformen (Kraft-, Schnelligkeitsausdauer)","e":"Allgemeine Ausdauer nennt man auch Grundlagenausdauer. Ausdauer ist nicht gleich Ausdauer. Beispiel: Eine Schwimmerin mit hervorragender Ausdauer im Wasser kann beim Bergauflaufen trotzdem schnell schnaufen, weil dort andere Muskeln (lokal/global) und eine andere Belastungsform gefordert sind.","quelle":"L12.1","typ":"kern"},{"id":"q1.1-027","thema":"Q1.1","kapitel":"Konditionelle Fähigkeiten","q":"Wie werden Kraft, Schnelligkeit und Beweglichkeit in den Detaillektionen genauer definiert und unterteilt (Überblick)?","a":"• Kraft: Widerstände überwinden (konzentrisch), entgegenwirken (exzentrisch), halten (isometrisch); >30 % des Maximums\n• Schnelligkeit: Reaktions-, elementare (Aktions-, Frequenz-) und komplexe Schnelligkeit\n• Beweglichkeit: Dehnfähigkeit + Gelenkigkeit; allgemein/speziell, aktiv/passiv, statisch/dynamisch","e":"Kraft entsteht durch Innervations- und Stoffwechselprozesse im neuromuskulären System. Schnelligkeit ist konditionell und koordinativ bestimmt: schnellstmöglich auf Reize reagieren bzw. Bewegungen bei geringen Widerständen mit höchster Geschwindigkeit ausführen. Beweglichkeit heißt, Bewegungen mit großer Schwingungsweite auszuführen. Beispiel: Beim Klimmzug arbeitet der Bizeps konzentrisch beim Hochziehen, isometrisch beim Halten und exzentrisch beim Herablassen.","quelle":"L13.1/L14.1/L15.1","typ":"kern"},{"id":"q1.1-028","thema":"Q1.1","kapitel":"Sportliches Training","q":"Definiere sportliches Training (nach Hohmann et al.).","a":"Sportliches Training ist die geplante und systematische Realisation von Maßnahmen (Inhalte, Methoden) zum nachhaltigen Erreichen von Trainingszielen im und durch Sport.","e":"Die wichtigsten Schlüsselwörter: geplant, systematisch, Ziele, nachhaltig, im und durch Sport. Ziele sind z. B. Erhalt, Steigerung oder Wiederherstellung der Leistungsfähigkeit. Beispiel: Wer jede Woche nach Plan dreimal läuft, um im Mai den Halbmarathon zu schaffen, trainiert. Wer ab und zu spontan joggen geht, bewegt sich, trainiert aber im engeren Sinne nicht.","quelle":"L10.2","typ":"kern"},{"id":"q1.1-029","thema":"Q1.1","kapitel":"Sportliches Training","q":"Beschreibe die wichtigsten Merkmale von sportlichem Training.","a":"• Planmäßigkeit (Trainingsplan)\n• Systematik\n• Zielorientierung (Erhalt, Steigerung, Wiederherstellung)\n• Maßnahmen (Inhalte, Methoden)\n• Nachhaltigkeit\n• Ziele im oder durch Sport","e":"Systematik heißt: Ziele werden aus einer Systematik abgeleitet und methodisch umgesetzt. Nachhaltig heißt: Training ist nicht zweckfrei, die Ziele reichen über die Durchführung hinaus. Nicht jede Sportaktivität ist Training. Beispiel: Ein Lauf-ABC in der Leichtathletik ist Training, wenn es gezielt die Lauftechnik verbessern soll. Ein zweckfreies Herumtollen auf dem Spielplatz ist kein Training.","quelle":"L10.2","typ":"kern"},{"id":"q1.1-030","thema":"Q1.1","kapitel":"Sportliches Training","q":"Erkläre den Unterschied zwischen Trainingszielen im Sport und durch Sport.","a":"• Im Sport: sportbezogene Leistungsziele (Sportabzeichen, Olympiasieg, Kader)\n• Durch Sport: außersportliche Ziele, Sport als Mittel (Gesundheit, Gewichtsreduktion, Gewaltprävention)","e":"Im Sport heißt: Der Sport selbst ist das Ziel. Durch Sport heißt: Der Sport ist das Werkzeug für etwas anderes. Beispiel: Ein Boxtraining im Jugendzentrum kann das Ziel haben, Aggressionen kontrollieren zu lernen – das ist ein Ziel durch Sport.","quelle":"L10.2","typ":"kern"},{"id":"q1.1-031","thema":"Q1.1","kapitel":"Sportliches Training","q":"Warum ist die Definition von sportlichem Training bewusst offen gehalten? Nenne die Felder, in denen Training offen ist.","a":"Die Definition legt weder Maßnahmen noch Ziele fest (im und durch Sport) → Training nicht nur im Wettkampfsport.\nOffen bezüglich:\n• Anwendungsfeldern (Leistungs-, Schul-, Gesundheits-, Behindertensport, Justizvollzug)\n• Zielen (Erfolg, Gewichtsreduktion, Gewaltreduktion)\n• Inhalten (Ausdauer-, mentales, Entspannungstraining, Kennenlernspiele)","e":"Training findet überall statt, wo systematisch und planmäßig Ziele im oder durch Sport verfolgt werden – sogar beim Abtrainieren nach dem Karriereende. Training ist kein Privileg von Profis. Beispiel: Auch ein Entspannungstraining in der Reha oder Kennenlernspiele zu Beginn eines Schuljahres können Training sein, wenn sie geplant ein Ziel verfolgen (z. B. Gruppenzusammenhalt).","quelle":"L10.2","typ":"kern"},{"id":"q1.1-032","thema":"Q1.1","kapitel":"Sportliches Training","q":"Nimm Stellung zur Aussage: „In meinem Sportunterricht gibt es kein sportliches Training, da er breitensportorientiert ist.“","a":"• Vorurteil: Training gebe es nur im Leistungssport\n• Nach Hohmann et al. ist geplanter, systematischer, zielgerichteter Unterricht Training; Schulsport ist ein Anwendungsfeld\n• Einschränkung: zweckfreier, unsystematischer Unterricht ist kein Training","e":"Der Lehrer verwechselt Training mit Leistungssport. Ziele im Schulsport können z. B. Gesundheit, Ausdauerverbesserung oder Technikerwerb sein. Wirft der Lehrer dagegen nur den Ball in die Mitte, ohne Ziel, liegt tatsächlich kein Training vor. Beispiel: Ein Unterrichtsvorhaben, in dem die Klasse über sechs Wochen ihre Ausdauer für einen 30-Minuten-Lauf aufbaut, ist eindeutig Training – auch im Breitensport.","quelle":"L10.2","typ":"kern"},{"id":"q1.1-033","thema":"Q1.1","kapitel":"Sportliches Training","q":"Begründe, warum ein freies Fußballspiel im Unterricht je nach Situation Training sein kann oder nicht (Zweideutigkeiten).","a":"• Kein Training: Ball in die Mitte, ohne Ziel und Planung\n• Training: freies Spiel als Teil einer geplanten Vermittlungsstrategie, gezielt beobachtet und reflektiert\n• Entscheidend: Planung, Systematik, Ziel – nicht die äußere Form","e":"Von außen sieht beides gleich aus, der Unterschied liegt in der Absicht; man muss die Gesamtsituation analysieren. Bei einer offenen Vermittlungsstrategie wird das Spiel bewusst eingesetzt und danach ausgewertet. Beispiel: Ein Aufwärmspiel ist Training, wenn es gezielt Herz-Kreislauf und Muskulatur vorbereiten soll, aber nicht, wenn es nur Zeit füllt.","quelle":"L10.2","typ":"kern"},{"id":"q1.1-034","thema":"Q1.1","kapitel":"Sportliches Training","q":"Was bedeutet der Begriff „nachhaltig“ in der Definition von sportlichem Training?","a":"Training ist nicht zweckfrei: Seine Ziele reichen über die eigentliche Durchführung der Maßnahme hinaus.","e":"Nachhaltig heißt: Die Wirkung soll bleiben. Zweckfreies Spielen oder bloße Sportanimation sind daher kein Training. Beispiel: Ein Krafttraining im Unterrichtsvorhaben soll die Kraft dauerhaft verbessern, nicht nur in der Stunde für Bewegung sorgen.","quelle":"L10.2","typ":"kern"},{"id":"q1.1-035","thema":"Q1.1","kapitel":"Sportliches Training","q":"Begründe, inwiefern Kennenlernspiele ein Trainingsinhalt sein können.","a":"Training ist offen für Inhalte und soziale Ziele durch Sport. Geplant und systematisch zu einem nachhaltigen Ziel eingesetzt (Gruppenzusammenhalt, Kooperation), erfüllen Kennenlernspiele die Trainingsmerkmale; ohne Ziel sind sie bloßes Spiel.","e":"Auch eine Mannschaft muss zusammenwachsen, das kann man trainieren. Beispiel: Eine neue Jugendmannschaft beginnt die Saisonvorbereitung gezielt mit Kennenlernspielen, damit sich die Spieler später im Spiel besser abstimmen.","quelle":"L10.2","typ":"kern"},{"id":"q1.1-036","thema":"Q1.1","kapitel":"Biologische Anpassung","q":"Definiere Anpassung (Adaptation) im Sport.","a":"Anpassung ist die Umstellung des Organismus oder seiner Teilsysteme auf innere (endogene) und äußere (exogene) Anforderungen. Sie ist reversibel.","e":"Leistungssteigerung durch Training beruht auf solchen Anpassungen; sie müssen ständig aktiv erhalten oder neu erworben werden. Der Körper ist faul, aber lernfähig: Er baut nur das auf, was regelmäßig gefordert wird. Beispiel: Wer regelmäßig Kniebeugen macht, bekommt kräftigere Oberschenkel; hört er auf, bildet sich die Kraft wieder zurück. Hinweis: Im Buch sind endogen/exogen vertauscht – endogen heißt von innen, exogen von außen.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-037","thema":"Q1.1","kapitel":"Biologische Anpassung","q":"Nenne die verschiedenen Ebenen (Parameter) von Anpassungserscheinungen durch Sport.","a":"• Funktionell (Funktionen)\n• Morphologisch (Strukturen, z. B. Muskelquerschnitt, Sportherz)\n• Neuronal (Nerv-Muskel-Steuerung)\n• Kognitiv (Wissen, Taktik)\n• Metabolisch (Stoffwechsel, Enzyme)\n• Endokrin (Hormone)","e":"Anpassung passiert nicht nur am Muskel. Funktionell kann z. B. auch eine Bewegungseinschränkung nach Verletzung sein, neuronal etwa eine bessere intramuskuläre Koordination, endokrin z. B. die Ausschüttung von Endorphinen. Eselsbrücke: F-M-N-K-M-E (Funktion, Morphologie, Nerven, Kopf, Metabolismus, Endokrin). Beispiel: Ein Basketballprofi, der 50 Spielsysteme lernt, passt sich kognitiv an; ein Ausdauerläufer metabolisch (mehr Enzyme) und morphologisch (größeres Herz).","quelle":"L11.1","typ":"kern"},{"id":"q1.1-038","thema":"Q1.1","kapitel":"Biologische Anpassung","q":"Welcher Zusammenhang besteht zwischen Lebensalter und Anpassungsfähigkeit?","a":"Je jünger, desto schneller und ausgeprägter die Anpassungsfähigkeit (Trainierbarkeit).","e":"Anpassung und Anpassungsfähigkeit sind Kennzeichen des Lebens; Anpassungen sind reversibel. Kinder und Jugendliche reagieren besonders stark auf Trainingsreize. Beispiel: Ein Zehnjähriger lernt Jonglieren mit dem Ball oft viel schneller als ein Erwachsener, und auch konditionell reagieren junge Menschen schneller auf Training.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-039","thema":"Q1.1","kapitel":"Biologische Anpassung","q":"Nenne die sechs allgemeinen Gesetze zur biologischen Anpassung durch Training.","a":"• Qualitätsgesetz\n• Reizstufen- und Funktionszustandsregel\n• Gesetz der Homöostase und der Superkompensation\n• Gesetz der Anpassungsfestigkeit\n• Gesetz zum Verlauf der Leistungsentwicklung\n• Gesetz der Trainierbarkeit\n(nach Friedrich; Friedmann)","e":"Diese Gesetze erklären, wie der Körper auf Training reagiert; aus ihnen leitet man die Trainingsprinzipien ab. Eselsbrücke: Qualität Reizt Homöostatisch An Leistung und Training (Q-R-H-A-L-T).","quelle":"L11.1","typ":"kern"},{"id":"q1.1-040","thema":"Q1.1","kapitel":"Biologische Anpassung","q":"Warum muss man die Gesetze der biologischen Anpassung für die Trainingsplanung kennen?","a":"• Nur wer die Anpassungsgesetze kennt, kann gezielt und leistungsoptimierend trainieren.\n• Aus ihnen werden passende Reize und die Trainingsprinzipien abgeleitet.","e":"Jedes der sechs Gesetze beschreibt zugleich ein Trainingsprinzip, weil sich daraus praktische Hinweise ergeben, welche Reize zu einem höheren Funktionszustand führen. Wer die Regeln nicht kennt, trainiert nach Gefühl und riskiert Stillstand oder Überlastung. Beispiel: Wer das Superkompensationsgesetz kennt, weiß, dass tägliches maximales Krafttraining für denselben Muskel eher schadet.","quelle":"L11.1/L11.2","typ":"kern"},{"id":"q1.1-041","thema":"Q1.1","kapitel":"Anpassungsgesetze","q":"Erläutere das Qualitätsgesetz.","a":"Form und Funktion bedingen sich gegenseitig:\n• Funktion verändert Form (Belastung → Anpassung, z. B. Sportherz; fehlende Belastung → Atrophie)\n• Form ermöglicht Funktion (größerer Muskel → höhere Lasten)","e":"Was man benutzt, wird stärker, was man nicht benutzt, schwindet. Ebenso ermöglicht ein größeres Herz höhere Ausdauerleistungen. Beispiel: Nach sechs Wochen Gips am Sprunggelenk ist die Wade deutlich dünner (fehlende Funktion → Formverlust). Ein großes Sportherz kann pro Schlag mehr Blut pumpen und so mit niedrigerer Herzfrequenz arbeiten (Volumenarbeit kostet weniger Energie).","quelle":"L11.1","typ":"kern"},{"id":"q1.1-042","thema":"Q1.1","kapitel":"Anpassungsgesetze","q":"Erläutere die Reizstufenregel (nach Roux).","a":"Die Wirkung eines Reizes hängt von seiner Intensität ab:\n• unterschwellig: keine Wirkung\n• schwach überschwellig: funktionserhaltend\n• stark überschwellig: optimale Anpassung, Leistungssteigerung\n• zu stark überschwellig: funktionsschädigend","e":"Neben der Intensität ist auch die Regelmäßigkeit wichtig (z. B. mindestens 2–3-mal pro Woche). Stark überschwellige Reize bewirken physiologische und anatomische Veränderungen. Der Reiz muss wie bei Goldlöckchen genau richtig sein. Beispiel: Zwei Freundinnen, die gemütlich plaudernd 45 Minuten joggen, erhalten ihre Fitness (schwach überschwellig), werden aber kaum besser. Ein Anfänger, der gleich mit Maximalgewicht trainiert, riskiert Verletzungen.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-043","thema":"Q1.1","kapitel":"Anpassungsgesetze","q":"Wo liegt die Reizschwelle im Maximalkrafttraining bei Untrainierten und Hochtrainierten?","a":"• Untrainierte: ca. 30 % des Leistungsvermögens\n• Hochtrainierte: selbst 70 % reichen nicht (Leistungseinbußen)\n→ Reizschwelle hängt vom Trainingszustand ab.","e":"Bei hochtrainierten Gewichthebern führt eine regelmäßige Belastung mit 70 % der Maximalkraft schon nach wenigen Wochen zu Leistungseinbußen – das passt zur Funktionszustandsregel. Was für den Anfänger ein starker Reiz ist, ist für den Profi Erholung. Beispiel: Ein Untrainierter wird schon mit leichten Hanteln kräftiger, ein Gewichtheber muss sehr nahe an sein Maximum gehen, um noch Fortschritte zu machen.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-044","thema":"Q1.1","kapitel":"Anpassungsgesetze","q":"Erläutere die Funktionszustandsregel.","a":"Je höher der Trainingszustand, desto stärker und spezifischer müssen die Reize sein, um ihn zu erhalten oder zu steigern. Training verschiebt die Mobilisationsschwelle nach oben.","e":"Konsequenz: Intensität und Umfang müssen gesteigert und Methoden individuell angepasst werden. Je besser man ist, desto mehr muss man tun, um noch besser zu werden. Beispiel: Ein Fitnesssportler, der nach Monaten keinen Muskelzuwachs mehr hat, muss Gewicht und Umfang erhöhen oder z. B. auf ein Training der intramuskulären Koordination umsteigen. Die beiden Läuferinnen brauchen für den Marathon mehr Umfang und Intensität (z. B. intensive Dauermethode).","quelle":"L11.1","typ":"kern"},{"id":"q1.1-045","thema":"Q1.1","kapitel":"Anpassungsgesetze","q":"Beschreibe die vier Leistungsbereiche bezogen auf die absolute Leistungsfähigkeit (nach Hollmann/Hettinger).","a":"• Automatisch: <15 %\n• Physiologische Leistungsbereitschaft: 15–35 %\n• Gewöhnliche Einsatzreserven: 35–70 % (Willenskraft)\n• Autonom geschützte Reserven: 70–100 %\nGrenze zwischen den letzten beiden: Mobilisationsschwelle.","e":"Die Prozentwerte beziehen sich auf die absolute Leistungsfähigkeit. Automatische Leistungen kosten kaum Anstrengung, die gewöhnlichen Einsatzreserven erfordern ausgeprägte Willenskraft und führen zu starker Ermüdung. Die autonom geschützten Reserven schützen vor Überforderung und sind nur in Todesangst, unter Hypnose oder durch Doping erreichbar. Beispiel: Berichte, dass Menschen in Panik ein Auto anheben konnten, erklären sich mit dem Zugriff auf diese Reserven.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-046","thema":"Q1.1","kapitel":"Anpassungsgesetze","q":"Was ist die Mobilisationsschwelle und wie verändert sie sich durch Training?","a":"Übergang von den gewöhnlichen Einsatzreserven zu den autonom geschützten Reserven.\n• Untrainierte: ca. 70 %\n• Hochtrainierte: bis 95–98 % (Hollmann/Strüder)","e":"Trainierte können also einen größeren Teil ihrer absoluten Leistungsfähigkeit willentlich abrufen. Training öffnet einen Teil des Tresors mit den Notreserven. Beispiel: Ein Untrainierter kann nur etwa 70 % seiner möglichen Muskelkraft willentlich einsetzen, ein Gewichtheber dagegen fast alles.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-047","thema":"Q1.1","kapitel":"Anpassungsgesetze","q":"Welche Konsequenz haben Reizstufen- und Funktionszustandsregel für die Belastungsdosierung?","a":"• Belastung individuell an die Leistungsfähigkeit anpassen\n• mit steigendem Trainingszustand Reize steigern\n• über die Belastungskomponenten (Intensität, Dichte, Dauer, Umfang, Häufigkeit, Komplexität)","e":"Ein Trainingsplan muss mitwachsen. Beispiel: Ein Läufer beginnt mit 3 × 20 Minuten pro Woche locker; nach einigen Monaten erhöht er auf 4 Einheiten, längere Läufe und einzelne schnellere Abschnitte.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-048","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Formuliere das Gesetz der Homöostase und der Superkompensation.","a":"• Anpassung an einen Reiz erfolgt in zeitlich gestaffelten Phasen.\n• Neuer Reiz am Gipfel der Superkompensation.\n• Zu kurze Pausen senken langfristig die Leistungsfähigkeit.","e":"Auf dem Gipfel sind die Energiespeicher übervoll (superkompensiert). Der Körper repariert nach einer Belastung nicht nur, er baut etwas mehr auf als vorher – als Vorsorge für die nächste Belastung. Beispiel: Wer jeden Tag bis zur Erschöpfung trainiert, gibt dem Körper nie Zeit für diesen Mehraufbau und wird schwächer statt stärker.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-049","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Nenne und beschreibe die fünf Phasen der biologischen Anpassung nach einem Trainingsreiz.","a":"• Homöostase: Fließgleichgewicht vor Belastung\n• Heterostase: Störung, Ermüdung\n• Erholung: Rückkehr zum Ausgangsniveau\n• Gegenregulation (Superkompensation): erhöhtes Niveau\n• Reversibilität: ohne Reiz zurück zum Ausgangsniveau","e":"In der Heterostase sinkt die Leistungsfähigkeit vorübergehend. In der Erholung wird die Störung aktiv kompensiert, in der Gegenregulation werden neue Strukturen gebildet – es entsteht eine neue Homöostase auf höherem Niveau. Eselsbrücke: Ho-He-Er-Ge-Re. Beispiel: Nach einem harten Lauf ist man am Abend müde (Heterostase), am nächsten Tag erholt (Erholung), nach etwa zwei Tagen leistungsfähiger (Gegenregulation). Läuft man dann eine Woche nicht, ist der Gewinn wieder weg (Reversibilität).","quelle":"L11.1","typ":"kern"},{"id":"q1.1-050","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Definiere Homöostase und Heterostase.","a":"• Homöostase: Fließgleichgewicht der Körperfunktionen und des inneren Milieus vor Belastung\n• Heterostase: Störung dieses Gleichgewichts durch Belastung, mit vorübergehendem Leistungsabfall","e":"Homöostase heißt: alles im Lot (z. B. Temperatur, pH-Wert, Energiespeicher). Heterostase heißt: aus dem Lot gebracht. Beispiel: Nach einem 400-m-Lauf sind Herzfrequenz, Laktat und Körpertemperatur stark erhöht und die Glykogenspeicher teilweise geleert – der Körper ist in der Heterostase.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-051","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Was versteht man unter Superkompensation?","a":"Steigerung der Leistungsfähigkeit über das Ausgangsniveau hinaus (v. a. Energiestoffwechsel): Energiespeicher werden nach der Belastung übervoll aufgefüllt.","e":"Super-kompensieren heißt: mehr als ausgleichen. Erfolgt der neue Reiz am Gipfel dieser erhöhten Leistungsfähigkeit, steigt das Leistungsniveau stufenweise an. Beispiel: Nach einem langen Lauf füllt der Körper die Glykogenspeicher in den Muskeln etwas stärker auf als vorher; beim nächsten Training stehen mehr Energiereserven zur Verfügung.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-052","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Erläutere, wie sich der Zeitpunkt der neuen Reizsetzung auf die Leistungsentwicklung auswirkt.","a":"• Optimal (Gipfel der Superkompensation): treppenförmiger Anstieg\n• Zu früh: unvollständige Erholung, Leistungsabnahme (Übertraining)\n• Zu spät (Reversibilität): Gewinn verloren, Stagnation","e":"Timing ist alles. Ein zu früher Reiz trifft den Körper noch in der Ermüdungs- oder Erholungsphase. Beispiel: Zwei Läuferinnen, die eine Woche nach ihrem ersten Marathon schon den zweiten laufen, setzen den Reiz viel zu früh – ihre Leistungsfähigkeit sinkt. Wer dagegen nur alle zwei Wochen trainiert, verpasst den Superkompensationsgipfel und tritt auf der Stelle.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-053","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Für welche Trainingsbereiche gilt das Superkompensationsprinzip und für welche nicht?","a":"• Gilt v. a. für Glykogenspeicher (Muskel, Leber) → Ausdauer- und Krafttraining\n• Nicht für Technik, Koordination, kognitive Prozesse und andere Konditionsbereiche\n• Kritik: starke Vereinfachung","e":"Das Modell vereinfacht, weil verschiedene Systeme unterschiedlich schnell regenerieren. Superkompensation ist ein Modell für das Auffüllen von Energiespeichern, nicht für das Lernen. Beispiel: Ein Basketballer kann seinen Freiwurf jeden Tag üben, ohne auf eine Superkompensation warten zu müssen.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-054","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Welche Erholungszeiten und Trainingshäufigkeit werden für das Konditionstraining empfohlen?","a":"• 2–3 Belastungen pro Woche\n• Kraft/Schnelligkeit: 48–72 h Erholung\n• Ausdauer: mind. 18–36 h","e":"Faustregel: Kraft braucht etwa zwei bis drei Tage Pause, Ausdauer etwa ein bis eineinhalb Tage, damit die Glykogenspeicher wieder aufgefüllt sind. Beispiel: Wer montags ein intensives Beintraining macht, sollte die Beine frühestens am Mittwoch wieder hart belasten.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-055","thema":"Q1.1","kapitel":"Homöostase und Superkompensation","q":"Erkläre mithilfe des Superkompensationsmodells, warum ein Fitnesssportler, der fast täglich trainiert, plötzlich einen Leistungseinbruch erlebt.","a":"• Reize zu dicht: neuer Reiz trifft ermüdeten Organismus\n• keine Superkompensation, Ermüdung summiert sich\n• Folge: Leistungsabfall bis Übertraining\n• Lösung: Erholung einplanen (48–72 h je Muskelgruppe)","e":"Die Erholungsphase wird nie abgeschlossen, der Körper bleibt in der Heterostase. Am Anfang wirken die vielen Reize, weil der Trainingszustand niedrig ist; doch die Erholung kommt nicht hinterher. Belastung und Erholung müssen deshalb gemeinsam geplant werden. Beispiel: Wie ein Konto, von dem man jeden Tag mehr abhebt als eingezahlt wird – irgendwann ist es im Minus.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-056","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"Erläutere das Gesetz der Anpassungsfestigkeit.","a":"Langfristig aufgebaute Leistung baut sich langsamer ab als kurzfristig erworbene.\nTrainingsprinzip: Wiederholung und Kontinuität.","e":"Untersuchungen zeigen: Schnell (z. B. durch tägliches intensives Training) aufgebaute Kraft verschwindet nach Trainingsende ähnlich schnell; langsam aufgebaute bleibt deutlich länger. Schnell gewonnen, schnell zerronnen. Beispiel: Ein Sportler, der fünf Jahre Krafttraining gemacht hat und sich dann das Bein bricht, ist nach der Gipspause relativ schnell wieder auf seinem alten Niveau – im Gegensatz zu jemandem, der nur acht Wochen Crash-Training gemacht hat.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-057","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"In welcher Reihenfolge bilden sich die konditionellen Fähigkeiten nach Trainingsende zurück?","a":"• Relativ schnell: Schnelligkeit\n• Etwas stabiler: Kraftausdauer und anaerobe Ausdauer\n• Längste Resteffekte: Maximalkraft und Grundlagenausdauer","e":"Was viel mit feiner Nervensteuerung zu tun hat, geht schnell verloren; was auf Strukturen beruht, bleibt länger. Beispiel: Nach den Sommerferien sind Sprinter oft deutlich langsamer, während Läuferinnen ihre Grundlagenausdauer zu großen Teilen noch haben.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-058","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"Erläutere das Gesetz zum Verlauf der Leistungsentwicklung.","a":"• Je trainierter, desto geringer der Leistungszuwachs.\n• Natürliche Grenze (maximale Funktionskapazität, genetisch mitbestimmt).\n• Verlauf: nach oben beschränkt, abflachende Kurve.","e":"Anfänger und Fortgeschrittene entwickeln sich deutlich schneller als Hochtrainierte. Am Anfang geht es steil bergauf, später kämpft man um jede Sekunde. Beispiel: Eine Läuferin verbessert sich im Marathon von 3:45 h auf unter 3 h, danach aber nur noch um wenige Minuten, z. B. auf 2:54 h – sie nähert sich ihrer persönlichen Grenze.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-059","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"Erläutere den Zusammenhang zwischen dem Prinzip der progressiven Belastungssteigerung, der Reizschwelle (Reizstufen-/Funktionszustandsregel) und dem Gesetz zum Verlauf der Leistungsentwicklung.","a":"• Reizstufenregel: nur stark überschwellige Reize wirken\n• Funktionszustandsregel: Training hebt die Reizschwelle\n• → Belastung progressiv steigern\n• Leistungsentwicklung: Zuwachs wird kleiner, Steigerung muss größer und spezifischer werden bis zur Leistungsgrenze","e":"Bisher wirksame Reize werden mit der Zeit unterschwellig bzw. nur noch erhaltend. Die drei Regeln greifen wie Zahnräder ineinander. Beispiel: Ein Anfänger verbessert sich beim Bankdrücken schon mit 40 kg; ein Fortgeschrittener muss auf 80 kg gehen und neue Methoden nutzen, gewinnt aber trotzdem weniger dazu.","quelle":"L11.3","typ":"kern"},{"id":"q1.1-060","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"Erläutere das Gesetz der Trainierbarkeit.","a":"Ziele, Inhalte und Belastungen müssen alters- und geschlechtsgemäß sein:\n• biologisches statt kalendarisches Alter\n• sensible Phasen beachten\n• im Grundschulalter spielerisch","e":"Kurz: Die Altersstufe ist das Maß aller Dinge. Sturer Drill langweilt Kinder und hält sie vom Sport fern. Kinder sind keine kleinen Erwachsenen. Beispiel: Ein Fußballtraining für Achtjährige, das aus Einlaufen, Gymnastik und Torschusstraining besteht und kaum Spiel enthält, frustriert die Kinder – altersgemäß wären viele kleine Spiele.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-061","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"Was versteht man unter sensiblen Phasen? Beschreibe das Modell günstiger Phasen der Trainierbarkeit für die konditionellen Fähigkeiten.","a":"Lebensabschnitte besonders guter Trainierbarkeit einer Fähigkeit (Steinhöfer):\n• Schnelligkeit: ca. 6/7–12/13 J.\n• Schnellkraft: v. a. 10/12–12/13 J.\n• Maximalkraft: 12/13–16/18 J.\n• Aerobe Ausdauer: immer, am besten 14/15–16/18 J.\n• Anaerobe Ausdauer: ab später Kindheit, zunehmend bis 16/18 J.\n• Koordination: 7–12 J.","e":"Die sensiblen Phasen sind Zeitfenster, in denen Training besonders gut anschlägt. Wer eine Phase verpasst, kann die Fähigkeit später trotzdem trainieren, nur mit mehr Aufwand. Beispiel: Ein kindgerechtes Krafttraining im Grundschulalter ist erwünscht – die verbreitete Meinung, Krafttraining sei erst ab der Pubertät sinnvoll, ist falsch.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-062","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"Welche Kritik wird am Modell der sensiblen Phasen geübt?","a":"• ignoriert biologisches Alter und genetische Disposition\n• unterscheidet nicht zwischen basisbildenden und spezifischen Fähigkeiten\n• suggeriert fälschlich, Fähigkeiten seien zu anderen Zeiten kaum trainierbar","e":"Basisbildend ist z. B. die Maximalkraft, die Schnelligkeit und Schnellkraft mit beeinflusst. Auch Talente (z. B. für Schnelligkeit oder Ausdauer) bleiben unberücksichtigt. Das Modell ist eine grobe Orientierung, kein starrer Fahrplan. Beispiel: Ein 13-Jähriger, der biologisch schon wie ein 15-Jähriger entwickelt ist, kann anders trainiert werden als ein gleichaltriger Spätentwickler.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-063","thema":"Q1.1","kapitel":"Anpassungsfestigkeit und Trainierbarkeit","q":"Warum muss Training nach dem biologischen und nicht nach dem kalendarischen Alter ausgerichtet werden, und was bedeutet geschlechtsspezifische Orientierung?","a":"• Kalendarisches Alter: Lebensjahre; biologisches Alter: tatsächlicher Entwicklungsstand (kann um Jahre abweichen)\n• Nur am biologischen Alter orientiert: keine Über-/Unterforderung\n• Geschlechtsspezifisch: geschlechtsspezifische Merkmale beachten, aber vielseitiges Angebot für alle","e":"Früh- und Spätentwickler unterscheiden sich stark; nur angepasste Belastungen schöpfen das Potenzial aus. Ein vielseitiges Grundschulangebot muss für Jungen und Mädchen Ballspiele ebenso wie turnerische und gestalterische Elemente bieten. Zwei Zwölfjährige können körperlich wie ein Zehn- und ein Vierzehnjähriger wirken. Beispiel: In einer Ballspielgruppe für Grundschulkinder sollten Jungen und Mädchen gemeinsam spielen dürfen, statt einseitig nach Geschlechterklischees zu trennen.","quelle":"L11.1","typ":"kern"},{"id":"q1.1-064","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Was sind Trainingsprinzipien und welche Funktion haben sie?","a":"Allgemeine, übergeordnete Handlungsorientierungen für das Training (Hohmann et al.).\nFunktion: Kernstück der Trainingslehre, Brücke zwischen Theorie und Praxis.","e":"Sie sind eher Orientierungsgrundlage als konkrete Handlungsrichtlinie. Grundlage sind wissenschaftliche Erkenntnisse und Praxiserfahrungen; manche sind wissenschaftlich noch nicht abgesichert. Auch die sechs Anpassungsgesetze gelten als Trainingsprinzipien. Sie sind wie Verkehrsregeln: Sie sagen nicht genau, wohin man fährt, aber wie man sicher ankommt. Beispiel: Das Prinzip der progressiven Belastungssteigerung sagt nicht, wie viel Kilo man auflegen soll, sondern dass man regelmäßig steigern muss.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-065","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der Entwicklungs- und Gesundheitsförderung.","a":"Übergeordnetes pädagogisches Leitprinzip: Training darf die körperliche, seelische und motorische Entwicklung nie hemmen, soll Gesundheit fördern und Risiken vermeiden.","e":"Es steht vor allen Prinzipien der Leistungsentwicklung und orientiert sich an einer humanistischen Ethik des Sports (Schnabel). Leistung darf nie auf Kosten der Gesundheit oder Entwicklung gehen. Beispiel: Ein Trainer im Kinderturnen darf trotz Medaillenhoffnung keine Belastungen verlangen, die Wachstumsfugen schädigen oder die Kinder seelisch überfordern.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-066","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Nenne die Prinzipien sportlichen Trainings nach Steinhöfer und ordne sie den drei Gruppen zu.","a":"Auslösung:\n• wirksamer Belastungsreiz\n• progressive Belastungssteigerung\n• Variation der Belastung\nFestigung:\n• optimale Gestaltung von Belastung und Erholung\n• Wiederholung und Kontinuität\n• Periodisierung und Zyklisierung\nSteuerung:\n• Individualität und Altersgemäßheit\n• zunehmende Spezialisierung\n• regulierende Wechselwirkung","e":"Die drei Gruppen folgen einer Logik: Erst muss eine Anpassung ausgelöst, dann gefestigt und schließlich gezielt gesteuert werden. Eselsbrücke: Auslösen – Festigen – Steuern, je drei Prinzipien.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-067","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip des wirksamen Belastungsreizes.","a":"Der Reiz muss die individuelle Reizschwelle überschreiten (stark überschwellig), darf aber nicht zu stark sein; seine Wirkung hängt von Reizhöhe und Trainingszustand ab.","e":"Grundlage sind Reizstufen- und Funktionszustandsregel; das Prinzip gehört zur Gruppe Auslösung der Anpassung. Ohne ausreichend starken Reiz keine Anpassung. Beispiel: Ein trainierter Läufer, der nur locker 20 Minuten trabt, setzt keinen wirksamen Reiz mehr für seine Ausdauer; ein Einsteiger dagegen schon.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-068","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der progressiven Belastungssteigerung. Wie kann die Belastung gesteigert werden?","a":"Gleichbleibende Belastung bringt keinen Fortschritt mehr → Belastung regelmäßig steigern durch:\n• Häufigkeit\n• Umfang\n• kürzere Pausen\n• Intensität\n• koordinative Ansprüche\n• mehr Wettkämpfe","e":"Der Organismus hat sich an den bisherigen Reiz angepasst; der Körper gewöhnt sich an jeden Reiz – also muss der Reiz mitwachsen. Typische Reihenfolge: erst Häufigkeit und Umfang, dann Intensität steigern. Beispiel: Ein Schüler läuft zuerst 2 × pro Woche 20 Minuten, dann 3 × 30 Minuten und später mit Tempoabschnitten.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-069","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der Variation der Trainingsbelastung.","a":"Gleichartige Reize führen langfristig zur Stagnation → Belastung variieren (Intensität, Inhalte, Bewegungsdynamik, Pausen, Methoden).","e":"Abwechslung verhindert, dass der Körper sich an einen Reiz gewöhnt und nichts mehr passiert. Variiert werden sollten nicht nur die Intensität, sondern vor allem Inhalte und Methoden. Beispiel: Ein Kraftsportler, der monatelang immer die gleichen Übungen mit 3 × 10 Wiederholungen macht, kann durch Wechsel auf andere Übungen oder eine andere Methode (z. B. Pyramide) wieder Fortschritte erzielen.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-070","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der optimalen Gestaltung von Belastung und Erholung.","a":"Belastung und Erholung gemeinsam planen; neuer Reiz in der Phase erhöhter Leistungsfähigkeit (Gesetz der Homöostase/Superkompensation).","e":"Zu kurze Pausen führen zu Leistungsabnahme, zu lange zur Reversibilität. Das Prinzip gehört zur Gruppe Festigung der Anpassung. Die Pause ist Teil des Trainings, nicht verlorene Zeit. Beispiel: Ein Krafttrainingsplan mit Ganzkörpertraining montags, mittwochs und freitags lässt der Muskulatur jeweils etwa 48 Stunden Erholung.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-071","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der Wiederholung und Kontinuität.","a":"Regelmäßig und ohne längere Unterbrechungen trainieren, damit Anpassungen stabil werden (Gesetz der Anpassungsfestigkeit).","e":"Langsam aufgebaute Form baut sich langsam ab, schnell erworbene schnell. Das Prinzip gehört zur Gruppe Festigung der Anpassung. Dranbleiben ist wichtiger als kurzfristige Gewaltakte. Beispiel: Wer das ganze Jahr zweimal pro Woche läuft, verliert nach einer Grippe kaum Form; wer nur vier Wochen vor dem Lauf hart trainiert, ist nach einer kurzen Pause wieder am Anfang.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-072","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der Periodisierung und Zyklisierung.","a":"Training wird in Zyklen geplant, sodass die Höchstform zu den wichtigsten Wettkämpfen erreicht wird.\nJahr: Vorbereitungs-, Wettkampf-, Übergangsperiode.","e":"Das Ganzjahrestraining soll einen hohen Leistungszuwachs bringen; das Prinzip gehört zur Gruppe Festigung der Anpassung. Niemand kann das ganze Jahr in Topform sein. Beispiel: Ein Leichtathlet baut im Winter Grundlagen auf (Vorbereitung), ist im Sommer bei den Meisterschaften in Bestform (Wettkampf) und erholt sich im Herbst aktiv (Übergang).","quelle":"L11.2","typ":"kern"},{"id":"q1.1-073","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Beschreibe die drei Perioden der Jahresperiodisierung.","a":"• Vorbereitung: Aufbau der Grundlagen; erst allgemein mit hohem Umfang, dann spezieller und intensiver\n• Wettkampf: Höchstform; hohe Intensität, geringer Umfang\n• Übergang: aktive Erholung, Ausgleichssport","e":"Wie ein Jahreskreislauf: säen, ernten, ruhen. In der Übergangsperiode wird die Belastung nach der Saison reduziert, damit sich der Körper regenerieren kann. Beispiel: Eine Fußballmannschaft absolviert im Sommer die Vorbereitung mit viel Laufarbeit, spielt dann die Saison (Wettkampf) und macht in der Winter- bzw. Sommerpause aktive Erholung.","quelle":"L11.2","typ":"zusatz"},{"id":"q1.1-074","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der Individualität und Altersgemäßheit.","a":"Training an biologisches Alter, Belastbarkeit, Trainingszustand und persönliche Voraussetzungen anpassen (Gesetz der Trainierbarkeit).","e":"Kurz: Die Altersstufe ist das Maß der Dinge. Das Prinzip gehört zur Gruppe spezifische Steuerung der Anpassung. Ein Trainingsplan von der Stange passt selten jedem. Beispiel: In einer Schulklasse sollten beim Ausdauerlauf unterschiedliche Tempovorgaben gelten, weil die Leistungsvoraussetzungen sehr verschieden sind.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-075","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der zunehmenden Spezialisierung.","a":"Erst breite allgemeine Ausbildung, dann gezielte Schulung der leistungsbestimmenden Faktoren der Sportart; auch das Allgemeine ist auf die Sportart auszurichten.","e":"Das Allgemeine hat stets Vorrang vor dem Speziellen, z. B. allgemeine Kräftigung aller großen Muskelgruppen am Anfang. Erst das Fundament, dann das Dach. Beispiel: Ein Kugelstoßer kräftigt zunächst alle großen Muskelgruppen; danach ergänzt er das Drücken in Rückenlage gezielt durch Drücken in Schrägrückenlage, weil dieser Winkel seiner Stoßbewegung ähnelt.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-076","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere das Prinzip der regulierenden Wechselwirkung einzelner Trainingselemente.","a":"Alle leistungsbestimmenden Faktoren und ihr Zusammenwirken beachten; einseitige Belastung vermeiden, da sich Trainingselemente positiv oder negativ beeinflussen.","e":"Vielseitig orientierte Elemente schließen negative Effekte aus; so beeinflussen sich z. B. Ausdauer- und Krafttraining gegenseitig. Die Teile eines Trainings müssen zueinander passen. Beispiel: Im Sportspiel gibt es keine einseitige Belastung – Ausdauer, Schnelligkeit, Kraft, Technik und Taktik sind je nach Spielsituation gefragt. Deshalb kann ein Sportspiel auch die Gesundheit fördern.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-077","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Ordne den Trainingsprinzipien die zugrunde liegenden Gesetze der biologischen Anpassung zu.","a":"• wirksamer Belastungsreiz ↔ Reizstufen-/Funktionszustandsregel\n• progressive Steigerung ↔ Funktionszustandsregel, Verlauf der Leistungsentwicklung\n• Belastung/Erholung ↔ Homöostase/Superkompensation\n• Wiederholung/Kontinuität ↔ Anpassungsfestigkeit\n• Individualität/Altersgemäßheit ↔ Trainierbarkeit\n• Qualitätsgesetz ↔ Grundlage aller","e":"Jedes Prinzip ist die praktische Übersetzung eines biologischen Gesetzes; das Qualitätsgesetz (Form und Funktion bedingen sich) steckt hinter allen. Beispiel: Weil sich schnell erworbene Form schnell wieder abbaut (Gesetz), soll man kontinuierlich trainieren (Prinzip).","quelle":"L11.2","typ":"kern"},{"id":"q1.1-078","thema":"Q1.1","kapitel":"Trainingsprinzipien","q":"Erläutere die unterschiedliche Bedeutung der Trainingsprinzipien für den Leistungssport und für den Schulsport.","a":"Leistungssport:\n• alle Prinzipien konsequent, v. a. Progression, Periodisierung, Spezialisierung\nSchulsport:\n• übergeordnet: Entwicklungs- und Gesundheitsförderung\n• v. a. Individualität, Vielseitigkeit, Variation\n• Grenzen: wenig Stunden, heterogene Gruppen → Belastung/Erholung, Kontinuität eingeschränkt","e":"Im Leistungssport ist das Ziel maximale Leistung zum Saisonhöhepunkt, im Schulsport steht die Entwicklung des Kindes im Vordergrund. Mit 2–3 Stunden pro Woche und wechselnden Inhalten ist Training trotzdem möglich, z. B. in Unterrichtsvorhaben mit Hausaufgaben oder ergänzendem Training. Beispiel: Ein sechswöchiges Ausdauervorhaben mit zwei Sportstunden und einem zusätzlichen selbstständigen Lauf pro Woche erfüllt die Prinzipien, ein einmaliger Cooper-Test ohne Vorbereitung nicht.","quelle":"L11.3","typ":"zusatz"},{"id":"q1.1-079","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Was sind Belastungskomponenten (Belastungsnormative) und welche gibt es?","a":"Beschreibungsgrößen zur Dosierung der Trainingsbelastung:\n• Intensität\n• Dauer\n• Dichte\n• Umfang\n• Häufigkeit\n• Komplexität","e":"Sie steuern die Belastungsreize, die für die körperliche Anpassung nötig sind – sie sind die Stellschrauben des Trainings. Eselsbrücke: I-D-D-U-H-K: Ich Darf Doch Unbedingt Hart Kämpfen. Beispiel: 4 × 400 m in 80 s mit 3 min Pause, dreimal pro Woche – darin stecken Intensität, Dauer, Dichte, Umfang und Häufigkeit.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-080","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Definiere die Belastungsintensität und nenne, wie sie angegeben wird.","a":"Stärke des Belastungsreizes.\nAngabe: Zeit, Geschwindigkeit, Last (% Maximalkraft), physiologische Werte (Herzfrequenz, Laktat, % VO2max) oder subjektive Skalen.","e":"Die Intensität sagt, wie hart eine Belastung ist, und kann auch über das Anstrengungsempfinden erfasst werden. Beispiel: Ein Lauf bei 140 Schlägen pro Minute ist weniger intensiv als einer bei 180; im Krafttraining sind 80 % der Maximalkraft intensiver als 50 %.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-081","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Definiere Belastungsdauer und Belastungsumfang und grenze sie voneinander ab.","a":"• Dauer: Zeit eines Einzelreizes/einer Serie (Zeit, Wiederholungen)\n• Umfang: Gesamtmenge aller Reize einer Einheit oder Phase (km, Wiederholungen, Tonnage)","e":"Die Dauer bezieht sich auf den einzelnen Reiz, der Umfang auf die Summe aller Reize. Dauer ist ein Stück, Umfang die ganze Menge. Beispiel: Beim Intervalltraining 6 × 400 m beträgt die Belastungsdauer eines Laufs etwa 90 Sekunden, der Umfang insgesamt 2.400 m.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-082","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Definiere die Belastungsdichte und unterscheide vollständige und unvollständige Pause.","a":"Dichte: zeitliches Verhältnis von Belastung und Erholung (Pausengestaltung).\n• Vollständige Pause: Ermüdung ganz abgebaut\n• Unvollständige (lohnende) Pause: nur teilweise erholt","e":"Dichte heißt: Wie eng liegen die Belastungen beieinander? Bei unvollständiger Pause beginnt der nächste Reiz im noch nicht erholten Zustand. Beispiel: Ein Sprinter macht zwischen 60-m-Sprints vier Minuten Pause, damit er wieder voll erholt ist (vollständig). Ein Mittelstreckler läuft 400-m-Intervalle mit nur 90 Sekunden Trabpause (unvollständig).","quelle":"L11.2","typ":"kern"},{"id":"q1.1-083","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Definiere Belastungshäufigkeit und Belastungskomplexität.","a":"• Häufigkeit: Anzahl der Trainingseinheiten pro Zeiteinheit (meist Woche)\n• Komplexität: Zusammensetzung einer Einheit aus verschiedenen Inhalten","e":"Häufigkeit heißt: wie oft, Komplexität: wie gemischt, z. B. Kombination von Technik-, Kraft- und Ausdauerelementen. Beispiel: Eine Handballerin trainiert viermal pro Woche (Häufigkeit); eine Einheit enthält Wurftechnik, Sprints und Abwehrtaktik (hohe Komplexität).","quelle":"L11.2","typ":"kern"},{"id":"q1.1-084","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Erläutere die Wechselwirkung der Belastungskomponenten, insbesondere zwischen Intensität und Umfang.","a":"Die Komponenten beeinflussen sich gegenseitig:\n• hohe Intensität → geringer Umfang (und umgekehrt)\n• hohe Intensität → längere Pausen (geringere Dichte)","e":"Ändert man eine Komponente, wirkt sich das auf die anderen aus. Man kann nicht gleichzeitig sehr schnell und sehr lange laufen. Beispiel: Ein Sprinter läuft kurze Strecken mit maximaler Intensität und geringem Umfang, ein Langstreckenläufer lange Strecken mit geringer Intensität und großem Umfang.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-085","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Wie lassen sich Trainingsmethoden anhand der Belastungsdichte unterscheiden?","a":"• Dauermethode: ohne Pause\n• Intervallmethode: unvollständige (lohnende) Pausen\n• Wiederholungsmethode: vollständige Pausen","e":"Aus den Belastungskomponenten ergeben sich Belastungsprofile, die die Methoden kennzeichnen – im Ausdauer-, Kraft- und Schnelligkeitstraining. Die Pause ist das Erkennungsmerkmal der Methode. Beispiel: 45 Minuten ununterbrochenes Joggen = Dauermethode; 10 × 200 m mit 1 Minute Trabpause = Intervallmethode; 3 × 600 m mit voller Erholung = Wiederholungsmethode.","quelle":"L11.2","typ":"kern"},{"id":"q1.1-086","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Was versteht man unter Belastung und Beanspruchung, und wie unterscheiden sie sich?","a":"• Belastung: von außen einwirkende, objektiv messbare Anforderung (Belastungskomponenten)\n• Beanspruchung: individuelle Reaktion des Organismus darauf (Herzfrequenz, Laktat, Anstrengungsempfinden)","e":"Dieselbe Belastung führt je nach Trainingszustand, Alter und Tagesform zu unterschiedlicher Beanspruchung. Belastung ist, was man dem Körper aufgibt; Beanspruchung, was es für ihn bedeutet. Beispiel: 5 km in 30 Minuten sind für eine Marathonläuferin ein lockerer Lauf (geringe Beanspruchung), für einen untrainierten Schüler eine starke Beanspruchung mit hohem Puls.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.1-087","thema":"Q1.1","kapitel":"Belastungskomponenten","q":"Beurteile, inwiefern sportliches Training im Schulsport nach dem Prinzip der optimalen Relation von Belastung und Erholung möglich ist.","a":"• Problem: 2–3 Stunden/Woche, ungünstig verteilt, Unterbrechungen; nötig wären 2–3 Reize mit 18–72 h Erholung\n• heterogene Gruppen erschweren Dosierung\n• Lösungen: Hausaufgaben-Training, mehrwöchige Vorhaben, Vereinssport\n• Fazit: eingeschränkt möglich, wenn geplant und langfristig","e":"Eine Doppelstunde einmal pro Woche, Ferien und Themenwechsel stören den Rhythmus aus Belastung und Erholung. Der Schulsport allein reicht für große Anpassungen oft nicht aus, kann aber Training anstoßen. Beispiel: Wenn die Klasse in einem Ausdauervorhaben neben dem Sportunterricht einmal pro Woche selbstständig 30 Minuten läuft, entsteht ein sinnvoller Belastungs-Erholungs-Rhythmus.","quelle":"L11.3","typ":"zusatz"},{"id":"q1.2-001","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Woher stammt das Wort „Sport“ und warum ist eine eindeutige Begriffsbestimmung schwierig?","a":"• Herkunft: engl. „disport“ = Zeitvertreib, Zerstreuung, Vergnügen\n• Heute weltweit umgangssprachlich gebraucht → kaum eindeutig abgrenzbar (Prohl & Röthig)\n• Sportwissenschaft ist integrativ: Jede Teildisziplin definiert Sport anders","e":"Seit Beginn des 20. Jahrhunderts ist „Sport“ ein weltweit gebrauchter Alltagsbegriff. Heute nennt man fast alles Sport, vom Schach bis zum Marathon, deshalb gibt es keine Definition, auf die sich alle einigen. Dazu kommt, dass Teildisziplinen wie Sportmedizin oder Sportsoziologie unterschiedlich auf Sport blicken. Beispiel: Ein Sportmediziner denkt bei Sport an muskuläre Belastung, ein Soziologe eher an Vereine und Regeln.","quelle":"L01.1","typ":"kern"},{"id":"q1.2-002","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Nenne die Kennzeichen (Elemente) des klassischen Sports nach den Sportsoziologen Heinemann und Grieswelle.","a":"• Sport ist körperliche Bewegung\n• Sport unterliegt dem Leistungsprinzip\n• Sport ist durch soziale Normen (Regeln) geregelt\n• Sport bildet eine zweckfreie und unproduktive Eigenwelt\n• Sport findet in Vereinen statt","e":"Diese Merkmale beschreiben den „klassischen“ Wettkampfsport. Beispiel: Ein Fußballspiel im Verein erfüllt alles: Bewegung, man will gewinnen (Leistung), es gibt ein Regelwerk, und es wird nichts Nützliches produziert. Eselsbrücke: „Bewegung – Leistung – Regeln – Eigenwelt – Verein“.","quelle":"L01.1","typ":"kern"},{"id":"q1.2-003","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Wie definiert Tiedemann (2019) den Begriff „Sport“?","a":"Sport ist ein kulturelles Tätigkeitsfeld, in dem Menschen sich freiwillig in Beziehung zu anderen begeben, um bewusst ihre Fähigkeiten und Fertigkeiten (v. a. Bewegungskunst) zu entwickeln und sich mit ihnen nach selbstgesetzten oder übernommenen Regeln auf Grundlage gesellschaftlich akzeptierter ethischer Werte zu vergleichen.","e":"Kern der Definition: Freiwilligkeit, Bezug zu anderen, Entwicklung von Fähigkeiten und Vergleich nach Regeln und ethischen Werten. Tiedemann meint: Wer Sport wissenschaftlich untersucht, braucht eine klare Definition. Entscheidend ist bei ihm das Vergleichen mit anderen nach Regeln. Beispiel: Boxen im Verein ist Sport, weil man sich freiwillig und nach Regeln mit einem Gegner misst.","quelle":"L01.1","typ":"kern"},{"id":"q1.2-004","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Wie grenzt Tiedemann den Begriff „Bewegungskultur“ vom Sportbegriff ab?","a":"Bewegungskultur: Tätigkeitsfeld, in dem Menschen sich mit Natur und Umwelt auseinandersetzen und bewusst ihre (v. a. körperlichen) Fähigkeiten entwickeln, gestalten und darstellen, um individuellen oder gemeinsamen Gewinn und Genuss zu erleben.\nUnterschied: kein Vergleich mit anderen nach Regeln.","e":"Bewegungskultur ist der weitere Begriff: Im Vordergrund stehen Auseinandersetzung, Gestaltung und Erleben, nicht das Messen. Sport ist der Teil der Bewegungskultur, in dem man sich nach Regeln vergleicht. Beispiel: Freies Tanzen auf einer Party ist Bewegungskultur; ein Tanzturnier mit Wertungsrichtern wäre nach Tiedemann Sport, weil man sich nach Regeln vergleicht.","quelle":"L01.1","typ":"kern"},{"id":"q1.2-005","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Wie definieren die Sportmediziner Hollmann und Strüder Sport?","a":"Aus medizinischer Sicht ist Sport eine muskuläre Beanspruchung\n• mit Wettkampfcharakter oder\n• mit dem Ziel einer herausragenden persönlichen Leistung.","e":"Die Mediziner schauen vor allem auf die körperliche Belastung. Beispiel: Ein gemütlicher Spaziergang ist nach dieser Definition kein Sport, ein Training für einen Halbmarathon mit Bestzeitziel dagegen schon.","quelle":"L01.1","typ":"kern"},{"id":"q1.2-006","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Warum wird die Sportwissenschaft als integrative Wissenschaft bezeichnet? Nenne Teildisziplinen.","a":"• Vereint viele Teildisziplinen, die Sport aus eigener Perspektive untersuchen\n• z. B. Sportmedizin, -psychologie, -soziologie, -biologie, -geschichte, -didaktik, -philosophie, Trainings- und Bewegungslehre","e":"Integrativ heißt: Viele Fächer arbeiten am selben Gegenstand zusammen, weitere sind z. B. Sportmethodik. Deshalb verbinden die Disziplinen mit „Sport“ unterschiedliche Bedeutungen. Beispiel: Beim Thema Doping fragt die Sportmedizin nach Wirkungen im Körper, die Soziologie nach gesellschaftlichen Ursachen und die Philosophie nach Fairness.","quelle":"L01.1","typ":"kern"},{"id":"q1.2-007","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Nenne die drei Merkmale sportlicher Bewegungen nach Göhner.","a":"Sportliche Bewegungen\n• sind zweckfrei,\n• dürfen nicht durch maschinelle Vorgänge ersetzt werden,\n• sind Lösungen einer sporttypischen Bewegungsaufgabe (durch sporttypische Bewegungsaufgaben bestimmt).","e":"Mit diesen drei Merkmalen trennt man Sport- von Alltagsbewegungen. Beispiel: Einkaufstaschen tragen hat einen Zweck (Essen nach Hause bringen) und könnte auch ein Lieferwagen erledigen, also keine sportliche Bewegung. Ein 400-m-Lauf hat keinen Alltagszweck, ein Fahrrad ist verboten, und es gibt eine klare Aufgabe.","quelle":"L01.2","typ":"kern"},{"id":"q1.2-008","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Erläutere das Merkmal der Zweckfreiheit sportlicher Bewegungen in Abgrenzung zu Alltagsbewegungen.","a":"• Alltagsbewegungen sind zweckgerichtet (erledigen eine Alltagsaufgabe)\n• Sportliche Bewegungen sind für den Alltag nicht notwendig; ihr Sinn liegt in der Bewegung selbst\n• Dieselbe Bewegungsform kann je nach Zweck Alltags- oder Sportbewegung sein","e":"Man muss im Alltag nicht um die Wette rennen oder möglichst weit springen; Gehen, um irgendwohin zu kommen, ist dagegen zweckgerichtet. Zweckfrei heißt nicht sinnlos, sondern: Der Sinn liegt in der Bewegung selbst. Beispiel: Ein 400-m-Läufer kommt genau dort ins Ziel, wo er gestartet ist, und ist völlig erschöpft. Für den Alltag hat er nichts erreicht, sportlich aber sehr viel.","quelle":"L01.2","typ":"kern"},{"id":"q1.2-009","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Was bedeutet das Merkmal, dass sportliche Bewegungen nicht durch maschinelle Vorgänge ersetzt werden dürfen?","a":"• Mühselige Alltagsbewegungen werden durch Maschinen ersetzt\n• Im Sport wäre das möglich, ist aber verboten\n• Sportliche Bewegung = motorische Aktivität des Menschen, die nicht durch Maschinen ersetzt werden darf","e":"Im Alltag sind wir froh über Maschinen, im Sport würden sie den Sinn zerstören. Beispiel: Wo gelaufen wird, darf man nicht Rad fahren; beim Speerwurf ist keine Wurfmaschine erlaubt; beim Schwimmen keine Antriebsgeräte. Den Kuchenteig darf dagegen problemlos die Küchenmaschine kneten.","quelle":"L01.2","typ":"kern"},{"id":"q1.2-010","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Wann ist eine menschliche Bewegung nach Göhner eine sportliche Bewegung? Wie nennt man eine solche Bewegung noch?","a":"• Göhner: Eine menschliche Bewegung ist genau dann sportlich, wenn sie die Lösung einer im Sport anerkannten Bewegungsaufgabe ist.\n• Andere Bezeichnung: Technik bzw. (Bewegungs-)Fertigkeit","e":"Sportliche Bewegung und Lösung einer sporttypischen Bewegungsaufgabe sind also gleichbedeutend (Äquivalenz). Für eine Aufgabe kann es mehrere Lösungen geben. Die Bewegungsaufgabe ist sozusagen die Frage, die Technik die Antwort. Beispiel: Die Aufgabe im Hochsprung lautet „einbeinig abspringen und eine hochgelegte Latte überqueren“. Anfänger lösen sie mit dem Schersprung, Fortgeschrittene mit dem Flop; beides sind sportliche Bewegungen.","quelle":"L01.2","typ":"kern"},{"id":"q1.2-011","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Welche zwei Zugänge nutzt Göhner, um sportliche Bewegungen zu kennzeichnen?","a":"• Indirekter Zugang: Abgrenzung von Alltagsbewegungen → Zweckfreiheit, keine Ersetzung durch Maschinen, Lösung einer sporttypischen Bewegungsaufgabe\n• Versporten von Alltagsbewegungen → Unproduktivität/Eigenwelt, Leistungsprinzip, Normen/Regelwerk","e":"Beim indirekten Zugang fragt man zuerst, welche Bewegungen keine sportlichen sind, und leitet daraus die Merkmale ab. Beim Versporten untersucht man, was sich verändert, wenn eine Alltagsbewegung zum Sport gemacht wird. Einmal schaut man also, was Sport nicht ist, einmal, wie etwas zu Sport wird. Beispiel: Reifenwechseln ist kein Sport (Zugang 1), aber der Reifenwechsel als Wettbewerb auf Zeit könnte versportet werden (Zugang 2).","quelle":"L01.2","typ":"kern"},{"id":"q1.2-012","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Nenne und erläutere die Einflussgrößen einer Bewegungsaufgabe.","a":"• Movendum und seine Attribute (was bewegt wird)\n• Bewegungsziel/Zielsituation\n• Regeln\n• Bedingungen der Sportstätte\n• Hilfsmittel des Bewegers","e":"Das Movendum ist ein Gerät oder der eigene Körper. Das Ziel kann z. B. Distanzmaximierung, Zeitminimierung oder Trefferoptimierung sein. Regeln legen die Vorschriften fest, die Sportstätte muss bestimmten Vorgaben genügen, und erlaubte Hilfsmittel sind z. B. Schuhe, Kleidung, Schläger. Beispiel Speerwurf: Movendum ist der Speer, Ziel ist maximale Weite, Regeln verbieten das Schleudern, die Sportstätte ist der Anlauf mit Wurfsektor, und Spikes sind erlaubt. Eselsbrücke: „M-Z-R-S-H: Mein Ziel: Regeln schlau halten“.","quelle":"L01.2","typ":"kern"},{"id":"q1.2-013","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Was versteht man unter dem „Movendum“?","a":"Movendum = das Objekt, das in einer Bewegungsaufgabe in eine Zielsituation gebracht werden soll: Sportgerät oder eigener Körper. Seine Attribute (z. B. Masse, Form) beeinflussen die Lösung.","e":"Movendum kommt aus dem Lateinischen und heißt „das zu Bewegende“. Ein schwerer Ball verlangt eine andere Technik als ein leichter. Beispiel: Beim Fußball ist das Movendum der Ball, beim Brustschwimmen dagegen der Schwimmer selbst.","quelle":"L01.2","typ":"kern"},{"id":"q1.2-014","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Welche typischen Merkmale sportlicher Bewegungen werden durch das Versporten von Alltagsbewegungen deutlich?","a":"• Unproduktivität (nichts Nützliches wird erzeugt)\n• Eigenwelt (nur der Bewegungsvorgang zählt)\n• Leistungsprinzip (schneller, weiter, höher)\n• Normen und Regelwerk (gleiche Bedingungen für alle)","e":"Beim Versporten wird die traditionelle Sinngebung aufgehoben, die Bewegung ist vom Alltagsgebrauch befreit. Versporten heißt, eine Arbeitsbewegung zum Wettkampf zu machen. Beispiel: Beim Holzfäller-Wettbewerb geht es nicht mehr um Brennholz (Unproduktivität, Eigenwelt), sondern darum, möglichst schnell zu sägen (Leistungsprinzip), wobei alle gleiche Stämme und Werkzeuge haben (Regeln).","quelle":"L01.2","typ":"kern"},{"id":"q1.2-015","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Wie kann man begründet entscheiden, ob eine Bewegung (z. B. Jonglieren) eine sportliche Bewegung ist?","a":"Prüfen nach Göhner:\n• zweckfrei?\n• nicht durch Maschinen ersetzbar?\n• Lösung einer im Sport anerkannten Bewegungsaufgabe?\n• zusätzlich: Leistungsprinzip und Regelwerk?\nEntscheidend ist der Kontext.","e":"Zur anerkannten Bewegungsaufgabe gehören Movendum, Ziel, Regeln, Sportstätte und Hilfsmittel. Nur wenn die Bewegung eine solche Aufgabe löst, ist sie eindeutig sportlich; dieselbe Bewegung kann je nach Kontext sportlich oder nicht sportlich sein. Beispiel: Jonglieren als Straßenkünstler zum Geldverdienen hat einen Zweck; Jonglieren in einem Wettbewerb („Wer hält 5 Bälle am längsten in der Luft?“) mit festen Regeln ist dagegen die Lösung einer sporttypischen Bewegungsaufgabe.","quelle":"L01.4","typ":"kern"},{"id":"q1.2-016","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Erläutere den Unterschied zwischen Außenaspekt und Innenaspekt sportlicher Bewegungen.","a":"• Außenaspekt: Sicht des Beobachters; Bewegung wird mit der Biomechanik beobachtet, beschrieben, begründet, optimiert\n• Innenaspekt: Sicht des Sportlers; Motorikforschung untersucht innere Prozesse (Steuerung, Regelung, Lernen)","e":"Beim Innenaspekt gilt der Mensch als wahrnehmendes, denkendes und handelndes Wesen. Außen = was man sieht und messen kann; innen = was im Kopf und Nervensystem passiert. Beispiel: Beim Freiwurf misst man außen Abwurfwinkel und Ballflug, innen fragt man, wie das Gehirn die Bewegung plant und Rückmeldungen verarbeitet.","quelle":"L01.3","typ":"kern"},{"id":"q1.2-017","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Welche Fragestellungen und Methoden kennzeichnen die Betrachtung des Außenaspekts von Bewegungen?","a":"Fragen:\n• Wie lässt sich die Bewegung strukturieren und beschreiben?\n• Welche mechanischen/biologischen Voraussetzungen gibt es?\n• Was ist eine zweckmäßige Technik?\nMethoden: Beobachtung, Bewegungsanalyse, Vergleich, Anwendung physikalischer und biologischer Erkenntnisse","e":"Beim Außenaspekt ist man wie ein Kameramann oder Physiker. Beispiel: Ein Trainer filmt den Weitsprung seines Athleten, vergleicht ihn mit einem Weltklassespringer und berechnet, ob der Absprungwinkel günstig ist.","quelle":"L01.3","typ":"kern"},{"id":"q1.2-018","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Welche Fragestellungen und Methoden kennzeichnen die Betrachtung des Innenaspekts von Bewegungen?","a":"Fragen:\n• Welche Prozesse laufen im Sportler ab?\n• Wie werden Bewegungen gelernt, gesteuert, reguliert?\nGrundlagen: Gesetzmäßigkeiten der Bewegungskoordination, Neurophysiologie, Handlungspsychologie","e":"Beim Innenaspekt schaut man „unter die Haut“. Beispiel: Wie schafft es ein Tennisspieler, in Sekundenbruchteilen den Ball zu sehen, die Flugbahn vorherzusagen und den Schläger richtig zu führen? Das erklären Nervensystem und Psychologie.","quelle":"L01.3","typ":"kern"},{"id":"q1.2-019","thema":"Q1.2","kapitel":"Sport und Bewegung","q":"Nenne die Anwendungsfelder der Bewegungslehre, in denen Innen- und Außenaspekt sportlicher Bewegungen behandelt werden.","a":"• Bewegungsanalyse (v. a. Außenaspekt)\n• Motorisches Lernen (Innenaspekt)\n• Koordinationsschulung\n• Lernen und Lehren sportlicher Bewegungen\n• Gestaltung und Gestalten von Bewegungen\n• Sportspielvermittlung","e":"Die Bewegungsanalyse beobachtet, beschreibt und begründet Bewegungen, um sie zu optimieren; motorisches Lernen fragt nach neuromuskulären Steuerungsprozessen. In der Koordinationsschulung verändern Druckbedingungen und Informationsanforderungen das Anforderungsniveau. Beim Lehren werden Lernprozesse geplant und an Lernende angepasst, beim Gestalten wird variiert, choreografiert und improvisiert, und die Sportspielvermittlung vermittelt Spielidee und komplexe Spielhandlungen. Beispiel: Wer einer Klasse den Handballwurf beibringt, braucht Bewegungsanalyse, Wissen über motorisches Lernen und Methoden der Sportspielvermittlung.","quelle":"L01.3","typ":"kern"},{"id":"q1.2-020","thema":"Q1.2","kapitel":"Betrachtungsweisen der Analyse","q":"Was ist eine Bewegungsanalyse und aus welchen Perspektiven können sportliche Bewegungen analysiert werden?","a":"• Bewegungsanalyse: zerlegt Bewegungen in Bestandteile und untersucht deren Beziehungen (Olivier et al.)\n• Hauptansätze: biomechanisch, morphologisch, funktional\n• Weitere: anatomisch-physiologisch, fähigkeitsanalytisch, psychologisch, soziokulturell","e":"Wie bei einem Auto, das man als Ingenieur, Designer oder Mechaniker anschauen kann, kann man auch eine Bewegung aus verschiedenen Blickwinkeln zerlegen. Beispiel Weitsprung: Physik (Absprungwinkel), Gestalt (Anlauf – Absprung – Landung) oder Funktion (Wozu dient das Vorbringen der Beine?).","quelle":"L02.1","typ":"kern"},{"id":"q1.2-021","thema":"Q1.2","kapitel":"Betrachtungsweisen der Analyse","q":"Erläutere die biomechanische, morphologische und funktionale Betrachtungsweise einer Bewegung und nenne jeweils typische Analysefragen.","a":"• Biomechanisch: physikalische Einflussgrößen (Kräfte, Geschwindigkeiten, Winkel)\n• Morphologisch: äußere Form, Phasen, qualitative Bewegungsmerkmale\n• Funktional: Wozu dienen einzelne Aktionen für die Bewegungsaufgabe?","e":"Typische biomechanische Fragen: Was ist der optimale Absprungwinkel? Wie wird die Anlaufgeschwindigkeit in einen hohen Kraftstoß umgesetzt? Morphologisch (griech. morphé = Gestalt): Welche Bedeutung haben Rhythmus und Bewegungsfluss? Funktional: Wozu werden am Ende der Flugphase Arme und Beine klappmesserartig nach vorn gebracht, welche Funktion hat der Absprung? Kurz: Physik – Aussehen – Zweck. Beispiel Weitsprung: biomechanisch Abfluggeschwindigkeit und -winkel, morphologisch die Phasen Anlauf – Absprung/Flug – Landung, funktional der Zweck der Flugtechnik (Landungsvorbereitung).","quelle":"L02.1","typ":"kern"},{"id":"q1.2-022","thema":"Q1.2","kapitel":"Betrachtungsweisen der Analyse","q":"Beschreibe die anatomisch-physiologische, fähigkeitsanalytische, psychologische und soziokulturelle Betrachtungsweise einer Bewegung.","a":"• Anatomisch-physiologisch: Rolle des neuromuskulären Systems (Muskeln, Nerven, Gelenke)\n• Fähigkeitsanalytisch: benötigte (konditionelle, koordinative) Fähigkeiten\n• Psychologisch: psychische Einflussfaktoren\n• Soziokulturell: soziokulturelle Entwicklung von Bewegungen","e":"Diese Perspektiven ergänzen die drei Hauptansätze (biomechanisch, morphologisch, funktional). Beispiel Elfmeter: anatomisch – welche Muskeln strecken das Knie; fähigkeitsanalytisch – Schnellkraft und Präzision; psychologisch – Nervosität; soziokulturell – wie sich die Schusstechnik im Lauf der Jahrzehnte verändert hat.","quelle":"L02.1","typ":"kern"},{"id":"q1.2-023","thema":"Q1.2","kapitel":"Betrachtungsweisen der Analyse","q":"Warum werden leichtathletische Bewegungen eher biomechanisch, Bewegungen aus Tanz und Gymnastik eher morphologisch betrachtet?","a":"• Leichtathletik: Leistung objektiv messbar und von physikalischen Größen abhängig → biomechanisch\n• Tanz/Gymnastik: bewertet werden Gestalt, Ausdruck, Bewegungsqualität → morphologisch (Beobachtung)","e":"In der Leichtathletik zählen Zeit, Weite, Höhe, und diese hängen direkt von Abfluggeschwindigkeit, Abflugwinkel oder Kraftstoß ab. In Tanz und Gymnastik geht es um Rhythmus, Fluss, Harmonie und Präzision, die man durch Beobachtung wahrnimmt. Die Analyseform passt sich also dem Bewegungsziel an. Beispiel: Beim Kugelstoßen zählt nur die Weite, also hilft die Physik. Bei einer Tanzchoreografie zählt, wie fließend und rhythmisch es aussieht, also hilft die Gestaltanalyse.","quelle":"L02.1","typ":"zusatz"},{"id":"q1.2-024","thema":"Q1.2","kapitel":"Translation und Rotation","q":"Was versteht man unter Biomechanik im Sport?","a":"Die Biomechanik im Sport befasst sich mit mechanischen Aspekten lebender Systeme im Sport; sie nutzt Begriffe, Methoden und Gesetze der Physik.","e":"Das Wort setzt sich aus „bios“ (griech. Leben) und „Mechanik“ (Teildisziplin der Physik) zusammen. Die Biomechanik wendet also Physik auf den menschlichen Körper an. Beispiel: Mit einer Kraftmessplatte misst man, wie viel Kraft ein Hochspringer beim Absprung auf den Boden bringt, und kann so seine Technik verbessern.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-025","thema":"Q1.2","kapitel":"Translation und Rotation","q":"Definiere den Begriff Translation (nach Göhner) und nenne mögliche Bahnformen.","a":"• Translation: alle Punkte des Körpers durchlaufen deckungsgleiche Bahnen\n• Bahnformen: geradlinig oder gekrümmt (z. B. parabelförmig)\n• Oft nur Translation eines Teilkörpers","e":"Bei einer Translation „verschiebt“ sich der Körper, ohne sich zu drehen. Führt nur ein Teilkörper eine Translation aus, durchlaufen nur dessen Punkte deckungsgleiche Bahnen. Beispiel: Ein Skifahrer, der auf flacher Piste geradeaus fährt, macht eine geradlinige Translation; ein Fußsprung ins Wasser ist parabelförmig. Teilkörper-Beispiel: Bei der Kniebeuge mit dem Rücken an der Wand bewegt sich der Oberkörper translatorisch nach unten.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-026","thema":"Q1.2","kapitel":"Translation und Rotation","q":"Definiere den Begriff Rotation (nach Göhner).","a":"• Rotation: Bewegung, bei der alle Punkte des betrachteten Körpers um eine gemeinsame Achse drehen\n• Die Drehachse kann im Körper liegen (z. B. Gelenkachse) oder außerhalb (z. B. Reckstange)","e":"Bei einer Rotation dreht sich alles um eine Achse. Beispiel: Bei der Riesenfelge dreht sich der ganze Turner um die Reckstange; beim Radfahren drehen sich die Räder um ihre Radachsen.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-027","thema":"Q1.2","kapitel":"Translation und Rotation","q":"Nenne die drei Drehachsen des menschlichen Körpers und ordne ihnen typische Drehbewegungen zu.","a":"• Körperbreitenachse (links–rechts): Salti vorwärts/rückwärts\n• Körperlängsachse (Kopf–Fuß): Schrauben, Pirouetten\n• Körpertiefenachse (vorne–hinten): Rad, Salto seitwärts","e":"Stell dir drei Spieße durch deinen Bauchnabel vor. Beispiel: Ein Salto rückwärts dreht um die Breitenachse, eine Pirouette im Eiskunstlauf um die Längsachse und ein Rad (Turnen) um die Tiefenachse.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-028","thema":"Q1.2","kapitel":"Translation und Rotation","q":"Erläutere, dass die meisten sportlichen Bewegungen aus Überlagerungen von Translation und Rotation bestehen. Welcher Grenzfall wird beschrieben?","a":"• Meist überlagern sich Translationen und Rotationen verschiedener Teilkörper\n• Grenzfall Salto vorwärts aus dem Anlauf: nur der KSP bewegt sich translatorisch (Parabel), der Körper rotiert um eine sich räumlich verändernde Breitenachse","e":"Reine Translation oder reine Rotation ist im Sport selten. Beim Kugelstoßen (O'Brien-Technik) bewegen sich Kugel, Stoßarm und Rumpf translatorisch, während Unter- und Oberschenkel um Sprung- bzw. Kniegelenk rotieren. Beispiel Radfahren: Der Rumpf bewegt sich geradeaus (Translation), Ober- und Unterschenkel drehen sich um Hüft- und Kniegelenk (Rotation), und die Räder drehen sich um ihre Achsen.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-029","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Formuliere das erste Newtonsche Gesetz (Trägheitsgesetz).","a":"Ein Körper verharrt im Zustand der Ruhe oder der gleichförmigen geradlinigen Bewegung, solange keine Kraft ihn zwingt, diesen Zustand zu ändern.","e":"Jede Änderung des Bewegungszustands erfordert also eine (äußere) Kraft. Körper „wollen“ so weitermachen, wie sie gerade sind. Beispiel: Ein Skateboarder fährt gegen eine Bordsteinkante. Das Brett wird gebremst, er selbst bewegt sich aber mit gleicher Geschwindigkeit weiter und fällt nach vorn, weil auf seinen Oberkörper keine bremsende Kraft wirkt.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-030","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Erkläre den Zusammenhang von Masse und Trägheit bei Translationen sowie von Trägheitsmoment (Drehwiderstand) und Trägheit bei Rotationen.","a":"• Translation: Trägheit = Masse (größere Masse braucht größere Kraft)\n• Rotation: Trägheit = Trägheitsmoment (Drehwiderstand), abhängig von der Massenverteilung um die Achse\n• Masse ist fix, Drehwiderstand über die Körperhaltung veränderbar\n• Masse nah an der Achse → kleiner Drehwiderstand","e":"Die Masse beschreibt, wie schwer und wie träge ein Körper ist. Je näher die Masse an der Drehachse liegt, desto leichter lässt sich der Körper in Drehung versetzen; ein gehockter Körper dreht deshalb leichter als ein gestreckter. Beispiel: Ein gehockter Salto vorwärts hat ein kleineres Trägheitsmoment als ein gestreckter. Deshalb winkeln Sprinter Arme und Schwungbein stärker an als Geher: Die Gliedmaßen lassen sich so schneller vor- und zurückschwingen.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-031","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Formuliere das zweite Newtonsche Gesetz (Bewegungsgesetz, dynamisches Grundgesetz).","a":"• Kraft ist Ursache von Geschwindigkeitsänderungen; Kraft ∼ Beschleunigung\n• F = m · a\n• Doppelte Kraft → doppelte Beschleunigung; bei gleicher Kraft sind m und a umgekehrt proportional","e":"Je mehr Kraft, desto mehr Beschleunigung; je schwerer der Körper, desto weniger. Beispiel Kugelstoßen: Eine 6-kg-Kugel wird bei gleicher Kraft und gleicher Einwirkdauer nur halb so stark beschleunigt wie eine 3-kg-Kugel. Doppelte Kraft bringt zwar doppelte Beschleunigung, aber nicht die doppelte Weite.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-032","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Nenne Kräfte, die für sportliche Bewegungen bedeutsam sind, und was sie bewirken können.","a":"Kräfte bewirken Beschleunigung oder Verformung:\n• Gewichtskraft\n• Reibungskraft\n• Muskelkraft\n• Aktionskräfte (Sprung-, Wurf-, Stoßkraft)\n• Widerstandskraft (Luft, Wasser)\n• Zentrifugal-/Zentripetalkraft","e":"Zentrifugal- und Zentripetalkraft treten bei Kurvenbewegungen auf, Widerstandskräfte z. B. auch beim Segel im Wind. Im Sport wirken fast immer mehrere Kräfte gleichzeitig. Beispiel Skispringen: Die Gewichtskraft zieht nach unten, die Luftwiderstandskraft trägt den Springer, und beim Absprung erzeugt die Muskelkraft der Beine die Sprungkraft.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-033","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Erkläre den Unterschied zwischen Zentrifugalkraft und Zentripetalkraft.","a":"• Zentrifugalkraft: vom Sportler in der Kurve wahrgenommene, nach außen drängende Scheinkraft\n• Zentripetalkraft: von außen betrachtet nach innen (zum Kurvenmittelpunkt) wirkende Kraft, die den Körper auf der Kreisbahn hält","e":"Ohne Zentripetalkraft würde der Sportler tangential aus der Bahn getragen. Zentri-fugal = „vom Zentrum fliehend“, zentri-petal = „zum Zentrum strebend“. Beispiel: Ein 200-m-Läufer in der Kurve spürt einen Zug nach außen (Zentrifugalkraft) und legt sich deshalb nach innen; die Reibung zwischen Spikes und Bahn liefert die Zentripetalkraft, die ihn auf der Kurve hält.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-034","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Nenne sportliche Situationen, in denen Reibungskräfte erwünscht bzw. unerwünscht sind.","a":"Erwünscht (Haftung, Kraftübertragung):\n• Abdruck beim Laufen (Spikes)\n• Griff am Gerät (Magnesia), Ballkontrolle (Harz)\n• Stoppen, Richtungswechsel\nUnerwünscht (Bremswirkung):\n• Gleiten (Ski wachsen)\n• Rollreibung (Rad, Inliner)\n• Wasser-/Luftwiderstand","e":"Reibung ist Freund und Feind zugleich: Wo Kraft übertragen werden soll, will man viel davon, wo gleiten oder rollen soll, möglichst wenig. Beispiel: Ein Sprinter trägt Spikes, damit er sich gut abdrücken kann; ein Skilangläufer wachst seine Ski, damit sie möglichst gut gleiten.","quelle":"L02.2","typ":"zusatz"},{"id":"q1.2-035","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Formuliere das dritte Newtonsche Gesetz (Wechselwirkungsgesetz). Was ist dabei besonders zu beachten?","a":"• Übt ein Körper eine Kraft auf einen zweiten aus (actio), übt dieser eine gleich große, entgegengesetzte Kraft auf den ersten aus (reactio)\n• Beachte: Kraft und Gegenkraft greifen nie am selben Körper an","e":"Das Gesetz ist die Grundlage aller sportlichen Fortbewegung und steckt im biomechanischen Prinzip der Gegenwirkung. Wer drückt, wird zurückgedrückt. Beispiel: Zwei Inlineskater halten ein Seil, einer zieht. Beide rollen aufeinander zu, weil der Gezogene mit gleicher Kraft zurückzieht. Und weil die beiden Kräfte an verschiedenen Körpern angreifen, heben sie sich nicht auf.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-036","thema":"Q1.2","kapitel":"Newtonsche Gesetze und Kräfte","q":"Erläutere die Bedeutung des Wechselwirkungsgesetzes für die Fortbewegung und unterscheide Aktions- und Reaktionskraft an sportlichen Beispielen.","a":"• Aktionskraft geht vom Sportler aus, Reaktionskraft wirkt auf ihn zurück\n• Laufen: Abdruck nach hinten unten → Bodenreaktionskraft nach vorn oben\n• Fußballstoß: Bein → Ball; Ball bremst das Bein\n• Hockstand: Aktionskraft = Gewichtskraft","e":"Fortbewegung ist nur möglich, weil der Boden mit der Bodenreaktionskraft zurückdrückt. Beim Schuss gibt die Aktionskraft dem Ball die Flugrichtung, die Reaktionskraft des Balls bremst den Beinvorschwung. Im ruhigen Hockstand muss die senkrechte Aktionskraft so groß sein wie die Gewichtskraft, damit die am Körper angreifende Reaktionskraft diese aufhebt. Beispiel Medizinball fangen: Die Hände bremsen den Ball, der Ball drückt mit gleich großer Kraft Arme und Körper nach hinten, deshalb macht man einen Ausfallschritt.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-037","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Definiere den Körperschwerpunkt (KSP).","a":"• Wird ein Körper im KSP unterstützt, ist er in jeder Lage im Gleichgewicht\n• Am KSP greift die Gewichtskraft an\n• Kann im oder außerhalb des Körpers liegen und verändert ständig seine Lage","e":"Im Stand liegt der KSP etwa in Höhe des Bauchnabels, bei guter Floptechnik außerhalb des Körpers. Weil Körperteile gegeneinander bewegt werden, wandert er beim Sportler ständig. Der KSP ist der „Mittelpunkt“ der Masse. Beispiel: Bei einem Lineal, das du auf einem Finger balancierst, liegt der Finger genau unter dem Schwerpunkt; dort bleibt es in jeder Lage im Gleichgewicht.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-038","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Wie kann der Körperschwerpunkt bestimmt werden?","a":"• Nur über seine Wirkung erkennbar (im KSP gelagert: kein Drehmoment)\n• Zweimaliges Aufhängen: KSP = Schnittpunkt der beiden Lote\n• Heute: rechnerisch über 3D-Computermodelle (Teilschwerpunkte, Gewebedichten)","e":"Ein frei beweglicher Körper hängt so, dass der KSP senkrecht unter dem Aufhängepunkt auf der Wirkungslinie der Gewichtskraft liegt. Hängt man ihn an zwei verschiedenen Punkten auf, kreuzen sich die Lote im KSP. Beispiel: Ein Pappmodell, an einer Ecke aufgehängt, pendelt so lange, bis der Schwerpunkt genau unter dem Faden hängt; zeichnet man zwei solche Lotlinien ein, kreuzen sie sich im Schwerpunkt.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-039","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Warum kann ein guter Hochspringer die Latte überqueren, während sein Körperschwerpunkt unter der Latte bleibt?","a":"• Beim Flop wird der Körper bogenförmig über die Latte gebracht → KSP liegt außerhalb des Körpers unter dem Bogen\n• Körperteile gleiten nacheinander über die Latte, KSP bleibt darunter\n• Vorteil: KSP muss weniger hoch gebracht werden","e":"Der KSP kann außerhalb des Körpers liegen, wenn die Körperteile entsprechend angeordnet sind. So spart der Springer Energie bzw. schafft bei gleicher Energie mehr Höhe. Biegt man ein Hufeisen, liegt sein Schwerpunkt in der Luft zwischen den Enden. Beispiel: Beim Flop macht der Springer über der Latte ein Hohlkreuz; Kopf und Beine hängen nach unten, der KSP liegt unterhalb des Rückens und damit unter der Latte. Das gilt auch beim Stabhochsprung.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-040","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Wann befindet sich ein Körper aus physikalischer Sicht im (Gesamt-)Gleichgewicht?","a":"Ein Körper befindet sich im Gleichgewicht, wenn\n• die Summe aller (eine Translation bewirkenden) Kräfte null ist und\n• die Summe aller (eine Rotation bewirkenden) Drehmomente null ist.","e":"Gleichgewicht heißt: Nichts schiebt und nichts dreht den Körper. Beispiel Hockstand: Die Bodenreaktionskraft ist genauso groß wie die Gewichtskraft und entgegengesetzt, beide addieren sich zu null; da die Schwerelinie durch die Standfläche geht, entsteht auch kein Drehmoment.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-041","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Nenne das Kriterium für die Standfestigkeit eines Körpers und erkläre, was beim Kippen passiert.","a":"• Kriterium: Schwerelinie verläuft durch die Unterstützungsfläche → Gleichgewicht\n• Außerhalb → Körper kippt\n• Kippen durch Drehmoment = Gewichtskraft × Kraftarm (Abstand Schwerelinie – Kippkante)","e":"Die Schwerelinie ist die Wirkungslinie der Gewichtskraft; der Drehpunkt beim Kippen ist die Kante der Standfläche. Solange das „Lot“ vom Schwerpunkt innerhalb der Füße landet, steht man. Beispiel: Kippt man aus dem Hockstand so weit nach vorn, dass der KSP vor den Zehen liegt, erzeugt die Gewichtskraft ein Drehmoment um die Zehen und man fällt nach vorne.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-042","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Unterscheide stabiles und labiles Gleichgewicht und nenne Situationen, in denen das Gleichgewicht im Sport hergestellt bzw. bewusst labil gestaltet wird.","a":"• Stabil: Bei kleinen Abweichungen stellt sich das Gleichgewicht von selbst wieder ein\n• Labil: Kleinste Abweichungen führen zum Gleichgewichtsverlust\n• Herstellen: z. B. Akrobatik-Pyramiden, Handstand → Stützwaage\n• Bewusst labil: z. B. Sprintstart","e":"Beim Übergang vom Handstand in die Stützwaage bringt man Kopf und Schultern nach vorn, damit der KSP über der Stützstelle bleibt und kein Drehmoment entsteht. Stabil ist wie eine Kugel in einer Schüssel, labil wie eine Kugel auf einem Hügel. Beispiel: Der 100-m-Sprinter verlagert in der Fertigposition den KSP so weit nach vorn, dass er fast umfällt; so kommt er beim Startschuss sofort in Bewegung.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-043","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Durch welche Maßnahmen kann die Standfestigkeit eines Sportlers verbessert werden?","a":"• Unterstützungsfläche vergrößern\n• KSP senken\n• KSP mittig halten bzw. zur erwarteten Kraft verlagern\n• Masse erhöhen\n• Reibung zum Boden erhöhen","e":"Füße weiter auseinander oder eine Schrittstellung in Kraftrichtung vergrößern die Fläche; in die Knie gehen senkt den KSP, sodass ein größerer Kippwinkel nötig ist. Mehr Masse erfordert ein größeres Kippmoment, mehr Reibung verhindert Wegrutschen. Wer stabil stehen will, macht sich breit und tief. Beispiel: Ein Sumoringer steht mit weit gespreizten Beinen und tiefem Schwerpunkt; ein Basketballverteidiger nimmt aus demselben Grund eine breite, tiefe Grundstellung ein.","quelle":"L02.2","typ":"zusatz"},{"id":"q1.2-044","thema":"Q1.2","kapitel":"Körperschwerpunkt und Gleichgewicht","q":"Was ist ein Drehmoment und wovon hängt es ab?","a":"• Drehmoment = Drehwirkung einer Kraft um eine Achse\n• M = F × r (Kraftarm r = senkrechter Abstand der Wirkungslinie von der Drehachse)\n• Kraftarm = 0 → kein Drehmoment\n• Ursache für Änderungen der Drehbewegung","e":"Das Drehmoment spielt bei Rotationen dieselbe Rolle wie die Kraft bei Translationen. Es ist der „Hebel-Effekt“ einer Kraft. Beispiel: Eine Tür lässt sich an der Klinke (großer Kraftarm) viel leichter öffnen als nahe der Scharniere. Beim Kippen aus dem Stand wirkt die Gewichtskraft mit dem Abstand zur Fußkante als Kraftarm.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.2-045","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Definiere den Impuls.","a":"• Impuls = Masse × Geschwindigkeit (p = m · v)\n• Beschreibt den Bewegungszustand bei einer Translation („Wucht“)","e":"Zwei Körper mit gleicher Geschwindigkeit und Richtung haben nur bei gleicher Masse den gleichen Impuls. Der Impuls sagt, wie schwer es ist, einen bewegten Körper zu stoppen. Beispiel: Ein Rugbyspieler mit 110 kg hat bei gleichem Tempo einen viel größeren Impuls als ein 70-kg-Spieler, deshalb ist er viel schwerer aufzuhalten.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-046","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Definiere den Kraftstoß und formuliere den Impulssatz.","a":"• Kraftstoß = Kraft × Einwirkzeit (F · Δt)\n• Impulssatz: Kraftstoß = Impulsänderung: F · Δt = m · Δv\n• Da die Masse konstant ist: Impulsänderung = Geschwindigkeitsänderung","e":"Der Sportler kann seine Masse während des Kraftstoßes nicht ändern, deshalb bestimmt der Kraftstoß direkt die Geschwindigkeitsänderung. Um schnell zu werden, braucht man viel Kraft oder lange Krafteinwirkung, am besten beides. Beispiel Rodelstart: Der Rodler zieht mit größter Kraft am Startbügel und paddelt danach noch auf dem Eis, um die Krafteinwirkung zu verlängern; so wird der Kraftstoß und damit seine Endgeschwindigkeit größer.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-047","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Warum spielt im Sport vor allem die Impulsänderung eine Rolle und wie kann sie vergrößert werden?","a":"• Ziel im Sport: hohe Endgeschwindigkeit von Gerät oder Körper → erfordert einen Kraftstoß\n• Vergrößern durch:\n  – größere Kraft (Prinzip der Anfangskraft)\n  – längere Zeit bzw. längeren Weg der Krafteinwirkung (optimaler Beschleunigungsweg)","e":"Ob Speer, Kugel oder der eigene Körper beim Sprung: Eine Geschwindigkeitsänderung erfordert nach dem dynamischen Grundgesetz eine Kraft, also einen Kraftstoß. Nicht der Impuls an sich zählt, sondern wie stark man ihn verändert. Beispiel: Ein Speerwerfer will den Speer von null auf möglichst hohe Geschwindigkeit bringen; dazu nimmt er den Speer weit zurück (längere Krafteinwirkung) und wirft explosiv (große Kraft).","quelle":"L02.2","typ":"kern"},{"id":"q1.2-048","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Zeige mithilfe des Impulssatzes, wie sich die Endgeschwindigkeit eines Körpers berechnen lässt.","a":"• F · Δt = m · (vEnde − vAnfang)\n• vEnde = vAnfang + (F · Δt) / m\n• Aus der Ruhe: vEnde = Kraftstoß / Masse","e":"Die Endgeschwindigkeit hängt also von der Höhe des Kraftstoßes, der Masse und der Anfangsgeschwindigkeit ab. Beispiel: Ein Kraftstoß von 20 N·s auf eine 4-kg-Kugel in Ruhe ergibt vEnde = 20 / 4 = 5 m/s. Hat die Kugel durch das Angleiten schon 2 m/s, beträgt die Endgeschwindigkeit 7 m/s.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-049","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Wie kann die Höhe eines Kraftstoßes aus einer Kraft-Zeit-Kurve ermittelt werden?","a":"• Kraftstoß = Fläche zwischen Kraft-Zeit-Kurve und Zeitachse\n• Bei Sprüngen: Fläche relativ zur Gewichtslinie (FG): darüber = beschleunigend nach oben, darunter = nach unten\n• Größere Fläche → größere Impulsänderung","e":"Man trägt die Kraft auf der y-Achse und die Zeit auf der x-Achse ab; Fläche = Kraft mal Zeit = Kraftstoß. Auf der Kraftmessplatte wird die Gewichtslinie y = FG als Bezug genommen. Je größer die Fläche, desto größer die Endgeschwindigkeit. Beispiel: Zwei Sprünge mit gleicher Maximalkraft können unterschiedlich hoch werden, wenn bei einem die Kraft länger über dem Körpergewicht liegt, denn dann ist die Fläche größer.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-050","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Definiere den Drehimpuls.","a":"• Drehimpuls L = Trägheitsmoment × Winkelgeschwindigkeit (L = J · ω)\n• Erfasst den Drehzustand inklusive Massenverteilung","e":"Er ist das Gegenstück zum Impuls: Impuls (Translation) = Masse × Geschwindigkeit, Drehimpuls (Rotation) = Drehwiderstand × Drehgeschwindigkeit. Der Drehimpuls ist der „Dreh-Schwung“. Beispiel: Ein Turmspringer verlässt das Brett mit einem bestimmten Drehimpuls; ob er sich schnell oder langsam dreht, hängt dann davon ab, wie eng er sich zusammenhockt.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-051","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Definiere den Drehmomentenstoß und formuliere den Drehimpulssatz.","a":"• Drehmomentenstoß = Drehmoment × Einwirkzeit (M · Δt)\n• Drehimpulssatz: Drehmomentenstoß = Drehimpulsänderung: M · Δt = J · Δω","e":"Je länger und je höher ein Drehmoment wirkt, desto größer sind Drehmomentenstoß und Änderung der Winkelgeschwindigkeit. Das ist der Impulssatz für Drehungen. Beispiel: Beim Flick-Flack geben zwei Helfer mit Schub- und Drehhilfe am Gesäß einen Drehmomentenstoß; dadurch bekommt der Turner genug Drehimpuls für die Rückwärtsdrehung.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-052","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Unterscheide zentralen und nicht zentralen Kraftstoß beim Abspringen.","a":"Entscheidend: Lage der Bodenreaktionskraft zum KSP\n• Zentral: Wirkungslinie durch den KSP → Translation ohne Rotation\n• Nicht zentral: am KSP vorbei → Translation mit Rotation (vorwärts/rückwärts)","e":"Drückt man ein Buch genau in der Mitte, rutscht es gerade; drückt man an der Ecke, dreht es sich. Beispiel: Ein Fußsprung im Trampolin ohne Drehung ist ein zentraler Kraftstoß, ein Salto rückwärts ein nicht zentraler.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-053","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Welche neun Grundmöglichkeiten des Abspringens ergeben sich nach Göhner? Wovon hängt die Richtung der Translation ab?","a":"• Richtung: KSP-Projektion auf, vor oder hinter der Absprungstelle → nach oben, vorne oben, hinten oben\n• Bewegungsart: Bodenreaktionskraft durch den KSP (keine Rotation) oder davor/dahinter (Rotation vorwärts/rückwärts)\n• 3 × 3 = 9 Möglichkeiten","e":"Man kombiniert „wohin fliege ich“ mit „drehe ich mich“. Beispiele: Fußsprünge ohne Rotation; Salto vorwärts/rückwärts im Trampolin (nach oben); Salto vorwärts und Auerbachsprung im Wasserspringen (nach vorne oben); Delfinsprung und Salto rückwärts im Bodenturnen (nach hinten oben). Beim Auerbachsprung springt der Wasserspringer nach vorne oben ab, dreht aber rückwärts: Der KSP liegt vor der Absprungstelle, die Bodenreaktionskraft läuft hinter dem KSP vorbei.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-054","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Wie lässt sich mithilfe des zentralen und nicht zentralen Kraftstoßes zwischen „Stoß“ und „Wurf“ bei Geräten unterscheiden?","a":"• Stoß: zentraler Kraftstoß durch den Geräteschwerpunkt → keine Rotation (Kugelstoßen)\n• Wurf: nicht zentraler Kraftstoß → Rotation (z. B. Fastball im Baseball)","e":"Beim Stoßen schiebt man genau durch die Mitte, beim Werfen erhält das Gerät Drall. Beispiel Basketball-Positionswurf: Das Stoßen des Balls ist zentral (Kraftimpulse in Abwurfrichtung), erst das Abklappen des Handgelenks ist ein Werfen mit Rückwärtsdrall.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-055","thema":"Q1.2","kapitel":"Impuls und Kraftstoß","q":"Warum muss beim Weitsprung möglichst ein zentraler Kraftstoß beim Absprung erfolgen?","a":"• Ziel: möglichst weite Translation des KSP\n• Nicht zentraler Kraftstoß → unerwünschte (Vorwärts-)Rotation\n• Erschwert die Landehaltung (Beine vorne) → kürzere Weite","e":"Eine Vorwärtsdrehung würde den Springer in der Luft nach vorne kippen lassen, sodass die Beine nicht weit nach vorne kommen. Eine Saltotechnik im Weitsprung wurde nach ihrer Entdeckung übrigens verboten. Beispiel: Weitspringer arbeiten mit Hang- oder Laufsprungtechnik, um die Vorwärtsrotation aus dem Absprung abzufangen.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-056","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Was versteht man unter biomechanischen Prinzipien?","a":"Sportartübergreifende Gesetzmäßigkeiten, mit denen die biomechanische Zweckmäßigkeit einer Technik bewertet wird (Hochmuth 1967); gelten nur für Gruppen strukturverwandter Bewegungen bzw. Zielstellungen.","e":"Hochmuth hat die Prinzipien bis 1981 so modifiziert, dass sie nur noch für bestimmte Bewegungsgruppen gelten. Sie sind wie Faustregeln aus der Physik, mit denen man prüft, ob eine Technik sinnvoll ist. Beispiel: Ein Speerwerfer führt den Speer weit zurück (langer Beschleunigungsweg), ein Basketballer beim Freiwurf dagegen kaum, weil dort Genauigkeit wichtiger ist. Das Ziel bestimmt also, welche Gestaltung zweckmäßig ist.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-057","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Nenne die sieben biomechanischen Prinzipien (nach Hochmuth, Wick, Olivier et al.).","a":"1. Prinzip der Anfangskraft\n2. Prinzip des optimalen Beschleunigungswegs\n3. Prinzip der zeitlichen und räumlichen Koordination von Einzelimpulsen\n4. Prinzip der optimalen Tendenz im Beschleunigungsverlauf\n5. Prinzip der Impulserhaltung\n6. Prinzip der Gegenwirkung\n7. Prinzip der Kinetion und Modulation","e":"Eselsbrücke: „Anfang – Weg – Koordination – Tendenz – Erhaltung – Gegen – Kinetion“, etwa „Alle Wege Kommen Täglich Einmal Gut Klar“. Beispiel: Beim Basketballsprungwurf lassen sich alle sieben Prinzipien wiederfinden.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-058","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Welche Kritik wird an den biomechanischen Prinzipien geäußert und warum sind sie trotzdem nützlich?","a":"Kritik (Baumann):\n• Teils nur mechanische Gesetze (Impulserhaltung = Drehimpulserhaltungssatz)\n• Nur für bestimmte Situationen gültig\nNutzen: kritisch angewendet hilfreiche Leitlinien; Göhner nutzt nur die ersten drei","e":"Göhner beschränkt sich auf Anfangskraft, optimalen Beschleunigungsweg und Koordination von Einzelimpulsen. Die Prinzipien sind keine Naturgesetze, sondern Daumenregeln mit begrenzter Reichweite. Beispiel: Das Prinzip der Anfangskraft hilft beim Hochsprung, beim Fechtstoß spielt es dagegen kaum eine Rolle.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-059","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Welche Kriterien neben den biomechanischen Prinzipien bestimmen die Zweckmäßigkeit einer sportlichen Technik? Wann ist eine sportliche Bewegung optimal?","a":"Weitere Kriterien (Wick): Technikleitbilder, Lernzeit, Belastungsverträglichkeit, individuelle Voraussetzungen (Größe, Hebel, Kraft).\nOptimal: biomechanisch zweckmäßig und zugleich möglichst hohes Niveau der individuellen biomechanischen Voraussetzungen.","e":"Technikleitbilder orientieren sich an Spitzensportlern; die Lernzeit ist die Zeit, die man zum Aneignen der Bewegung braucht. Die physikalisch beste Technik nützt nichts, wenn der Sportler sie körperlich nicht umsetzen kann. Beispiel: Eine extrem tiefe Ausholbewegung beim Sprung mag theoretisch den Beschleunigungsweg verlängern, ist aber für einen Sportler mit wenig Beinkraft ungünstig.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-060","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Formuliere das Prinzip der Anfangskraft.","a":"• Bei Beuge-Streck-Bewegung mit sofortiger Umkehr liefert das Abbremsen der Ausholbewegung eine positive Anfangskraft für die Beschleunigung\n• Verhältnis von Brems- und Beschleunigungskraftstoß muss optimal sein\n• Kraftmaximum erst im Beschleunigungskraftstoß (Göhner)","e":"Eine kurze Gegenbewegung „lädt“ den Muskel auf. Wird das Kraftmaximum schon beim Abbremsen erreicht, fehlt es in der eigentlichen Beschleunigung. Beispiel: Beim Strecksprung geht man kurz in die Knie und springt sofort ab; dadurch springt man höher als aus einer ruhigen Hockposition.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-061","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Unterscheide Counter-Movement-Jump (CMJ) und Squat-Jump (SJ). Welcher Sprung erzielt die größere Höhe und warum?","a":"• CMJ: Strecksprung mit Gegenbewegung (Tiefgehen) und fließender Umkehr\n• SJ: Strecksprung aus statischer Hockposition ohne Auftaktbewegung\n• CMJ höher: Abbremsen erzeugt positive Anfangskraft FA (beim SJ FA = 0) → größere positive Kraftstoßbilanz","e":"Beim CMJ werden Sprung-, Knie- und Hüftgelenke gebeugt, die Hände liegen z. B. auf dem Rücken, und es geht ohne Pause in die Streckung. Merksatz: Ein Strecksprung mit optimaler Auftaktbewegung der Beine erzielt eine bessere Sprunghöhe als ohne. Counter-Movement heißt Gegenbewegung. Beispiel: Wenn du aus der tiefen Hocke ohne Schwung hochspringst (SJ), kommst du weniger hoch, als wenn du aus dem Stand kurz in die Knie federst und sofort abspringst (CMJ).","quelle":"L02.2","typ":"kern"},{"id":"q1.2-062","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Beschreibe den Verlauf der Kraft-Zeit-Kurve beim Counter-Movement-Jump (Zeitpunkte t0 bis t4).","a":"• bis t0: Ruhe, Kurve = FG\n• t0–t1: Abwärts, Kraft < FG (A1); t1 max. Abwärtsgeschwindigkeit\n• t1–t2: Abbremsen, Kraft > FG (A2); t2 tiefster Punkt\n• t2–t3: Streckung (A3); t3 max. Aufwärtsgeschwindigkeit\n• t3–t4: Kraft < FG (A4)\n• t4: Abheben","e":"Bei t2 gilt A2 = A1; der Anteil über FG an diesem Punkt ist die Anfangskraft FA. Zwischen t3 und t4 wird die Aufwärtsbewegung schon abgebremst, obwohl noch kein freier Flug besteht. Die Kurve sinkt zuerst unter das Körpergewicht (man lässt sich fallen), steigt dann weit darüber (man bremst und drückt ab) und fällt kurz vor dem Abheben wieder darunter. Beispiel: Ein 70-kg-Sportler belastet beim Tiefgehen die Platte kurz mit weniger als 700 N, beim Abdruck dann mit über 1500 N.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-063","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Erläutere die vier charakteristischen Kraftstöße A1 bis A4 beim Strecksprung (CMJ). Welcher Kraftstoß bestimmt die Flughöhe?","a":"• A1: Abwärtskraftstoß\n• A2: Bremskraftstoß der Abwärtsbewegung (A1 = A2)\n• A3: Aufwärtskraftstoß\n• A4: Bremskraftstoß vor dem Abheben\n• Flughöhe wird durch A3 − A4 bestimmt","e":"Die vier Kraftstöße sind die Flächen zwischen Bodenreaktionskraft und Gewichtslinie. A1 und A2 heben sich gegenseitig auf (runter und abbremsen), A3 liefert den Bewegungsimpuls nach oben, A4 vermindert die Aufwärtsgeschwindigkeit schon vor dem Verlassen des Bodens. Beispiel: Ein Sportler, der beim Abdruck die Fußgelenke nicht vollständig streckt, hat ein großes A4 und springt weniger hoch.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-064","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Warum soll die Anfangskraft beim CMJ optimal und nicht maximal sein und das Kraftmaximum erst in der Absprungphase erreicht werden?","a":"• Kraftmaximum schon beim Abbremsen → fehlt in der Beschleunigungsphase\n• Anfangskraft soll die Streckung unterstützen, nicht ersetzen\n• Optimum individuell (abhängig von Kraft-/Reaktivkraftfähigkeit)\n• Zu starkes Bremsen/zu tiefes Ausholen verkleinert A3","e":"Größe der Anfangskraft und Tiefe der Gegenbewegung müssen zur Leistungsfähigkeit des Sportlers passen. Wer beim Abbremsen schon alles gibt, hat für den Abdruck nichts mehr übrig. Beispiel: Ein Sprinter, der beim Absprung vom Weitsprungbalken „einknickt“, weil er die Bremskraft nicht halten kann, verliert Sprunghöhe.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-065","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Erkläre das Prinzip der Anfangskraft physiologisch.","a":"Abbremsen der Auftaktbewegung dehnt die Arbeitsmuskulatur abrupt vor:\n• Elastische Energie in Muskeln und Sehnen\n• Dehnungsreflex (Muskelspindeln) → zusätzliche Muskelfasern, schnellere Kraftentwicklung\n• Voraussetzung: fließende Umkehr (DVZ)","e":"Die gespeicherte elastische Energie vergrößert den anschließenden Aufwärtskraftstoß. Der Dehnungsreflex innerviert zusätzlich Muskelfasern, die sonst nicht aktiv wären. Muskel und Sehne wirken wie ein Gummiband, das man vorspannt, und der Reflex „weckt“ weitere Fasern auf. Beispiel: Beim Absprung im Basketball nach einem kurzen Stoppschritt nutzt der Spieler beides und springt deutlich höher.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-066","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Was passiert, wenn beim CMJ keine fließende Bewegungsumkehr erfolgt? Gilt das Prinzip der Anfangskraft auch außerhalb von Sprüngen?","a":"• Ohne fließende Umkehr verpufft die Anfangskraft → niedrigerer Absprungstoß (eigentlich SJ)\n• Gilt auch bei Würfen/Stößen (z. B. Speerwurf aus dem Stand)\n• Ausnahme: Speerwurf aus dem Lauf mit bewusster Wurfverzögerung (Go-and-Stop)","e":"Wer in der Hockstellung stehen bleibt, macht in Wirklichkeit ein Tiefgehen und danach einen Squat-Jump. Beim Speerwurf aus dem Stand wird der Speer mit fließender Umkehr zurückgenommen. Aus dem Lauf verzögert der Werfer dagegen bewusst, um Kraftimpulse von den Beinen auf den Oberkörper zu übertragen (Koordination von Einzelimpulsen). Die gespeicherte Energie zerfällt schnell, wenn man pausiert. Beispiel: Wer beim Volleyball-Blocksprung in der Hocke kurz wartet, kommt merklich weniger hoch als jemand, der direkt aus dem Tiefgehen abspringt.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-067","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Warum kann eine zu starke (zu tiefe) Ausholbewegung beim Strecksprung die Sprunghöhe verringern?","a":"• Muskulär: keine optimale Vordehnung des M. quadriceps femoris → ungünstige Überlappung von Aktin und Myosin\n• Mechanisch: ungünstige Hebel (größere Lastarme)\n• Folge: kleinerer Aufwärtskraftstoß trotz längerem Weg","e":"Bei kleinen Gelenkwinkeln liegt z. B. die Kniegelenkachse weiter von der Schwerkraftlinie entfernt; für dieselbe Vertikalkraft braucht der Muskel deutlich mehr Zugkraft. Die Vertikalkräfte nehmen so stark ab, dass Endgeschwindigkeit und Sprunghöhe sinken. Mehr Weg ist also nicht immer mehr Höhe. Beispiel: Aus einer ganz tiefen Hocke (Gesäß fast am Boden) springt man schlechter als aus einer Kniebeugung von etwa 90–100°.","quelle":"L02.2 / L02.5","typ":"kern"},{"id":"q1.2-068","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Beschreibe den typischen Verlauf der Kraft-Zeit-Kurve beim Drop-Jump (Niedersprung mit sofortigem Absprung).","a":"• Fall: Kraft = 0\n• Landung: sehr steiler Anstieg auf hohen Kraftgipfel (großer Bremskraftstoß)\n• Fließender Übergang in den Beschleunigungskraftstoß (DVZ)\n• Sehr kurze Kontaktzeit, hohe Kraftwerte\n• Vor dem Abheben unter FG, dann 0","e":"Der Bremskraftstoß fängt die Fallgeschwindigkeit ab; bei direkter Umkehr entsteht eine hohe Anfangskraft. Der Drop-Jump ist ein CMJ „mit Anlauf von oben“: Die Fallgeschwindigkeit sorgt für eine extrem starke Vordehnung. Beispiel: Er wird im Reaktivkrafttraining (Plyometrie) von Sprintern und Springern genutzt, um kurze Bodenkontakte zu trainieren.","quelle":"L02.5","typ":"zusatz"},{"id":"q1.2-069","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Formuliere das Prinzip des optimalen Beschleunigungswegs. Welcher geometrische Verlauf ist günstig?","a":"• Optimale (nicht maximale) Länge des Beschleunigungswegs, abhängig von Winkelstellungen und zeitlichen Bedingungen\n• Ziel: maximale Endgeschwindigkeit\n• Verlauf: geradlinig oder stetig gekrümmt","e":"Geradlinig ist z. B. die O'Brien-Technik im Kugelstoßen oder der Weitsprunganlauf, stetig gekrümmt bzw. kreisförmig der Hammerwurf oder die Drehstoßtechnik. Je länger man beschleunigen kann, desto schneller wird das Gerät, aber nur bis zu einem gewissen Punkt, und der Weg sollte keine Zacken haben. Beispiel: Anfänger im Kugelstoßen machen oft eine Hoch-tief-Bewegung, Profis schieben die Kugel geradlinig, damit keine Geschwindigkeit verloren geht.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-070","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Durch welche Aktionen kann der Beschleunigungsweg optimiert werden?","a":"• Anlauf\n• Senkung des KSP\n• Verwringung (Schulter- gegen Hüftachse)\n• Bogenspannung","e":"Anlauf z. B. im Weitsprung; KSP senken z. B. beim Kugelstoßen oder Gewichtheben. Beim Diskuswurf läuft die Hüftachse der Schulterachse voraus (Verwringung). Die Bogenspannung bei Speer- und Handballwurf liefert Vorspannung, deren Auflösung die Abwurfgeschwindigkeit maximiert. All diese Aktionen verlängern den Weg, auf dem Kraft wirken kann. Beispiel: Ein Handballer macht beim Schlagwurf ein leichtes Hohlkreuz und nimmt den Wurfarm weit zurück; wenn sich der Bogen löst, schnellt der Arm nach vorn.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-071","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Formuliere das Prinzip der zeitlichen und räumlichen Koordination von Einzelimpulsen und nenne die zwei Arten von Bewegungen, für die es gilt.","a":"• Beschleunigungskraftstöße der Teilbewegungen müssen zeitlich (Reihenfolge, Zeitpunkt) und räumlich (gleiche Richtung) optimal abgestimmt sein\n• Gilt für: maximale Beschleunigung eines Körperteils/Geräts (Würfe, Stöße, Schüsse) und des ganzen Körpers (Sprünge)","e":"Wie bei einer Peitsche muss eine Bewegung nach der anderen ihren Schwung weitergeben, und alle Teilimpulse sollen möglichst in dieselbe Richtung zeigen. Beispiel: Beim Hochsprung-Flop zeigen Sprungbein, Schwungbein und Arme beim Absprung alle in dieselbe Richtung (räumlich) und werden zeitlich abgestimmt eingesetzt.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-072","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Erläutere die Impulsübertragung beim Speerwurf und formuliere das Go-and-Stop-Prinzip (Göhner).","a":"• Geschwindigkeitsmaxima von Hüfte, Schulter, Ellbogen, Hand nacheinander\n• Nach Stemmschritt Teilkörper nacheinander abbremsen → Impuls wird weitergegeben\n• Go-and-Stop (Göhner): Zum Objekt hin werden die Körperteile nacheinander beschleunigt und abgestoppt","e":"Nach dem Aufsetzen des Stemmbeins werden nacheinander Hüfte, Schulter und Ellbogen abgebremst; so wird der Impuls jeweils auf den nächsten Körperteil und schließlich auf den Speer übertragen. Pausen und Verzögerungen in dieser Kette mindern die Endgeschwindigkeit. Beschleunigen, stoppen, weitergeben, wie eine Kette von Dominosteinen, die immer schneller wird. Beispiel: Beim Peitschenknall bewegt sich der Griff langsam, aber die Spitze extrem schnell, weil der Schwung von Abschnitt zu Abschnitt übertragen wird.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-073","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Welche Aussagen gelten nach Göhner und Hochmuth für den Armschwung beim Counter-Movement-Jump?","a":"• Arme hochschwingen und in der Waagerechten vor dem Take-off blockieren\n• Armschwung optimal kurz vor der Beinstreckung\n• ca. 10 % mehr Sprunghöhe\n• Kraftstöße von Armen und Beinen nicht einfach addierbar","e":"Nur rechtzeitiges Abstoppen überträgt den Impuls der Arme auf den Gesamtkörper; zu langes Hochschwingen ohne Blockieren bringt nichts. Beginnt der Armschwung etwas vor der Beinstreckung, dauert der Beschleunigungskraftstoß länger und die Endgeschwindigkeit steigt. Die Kraftstöße beeinflussen sich gegenseitig, deshalb addieren sie sich nicht einfach. Beispiel: Beim „Jump and Reach“-Test schwingen gute Springer die Arme schwungvoll hoch und bremsen sie kurz vor dem Abheben, so kommen sie gut 10 % höher.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-074","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Formuliere das Prinzip der optimalen Tendenz im Beschleunigungsverlauf und unterscheide abfallende und ansteigende Beschleunigungstendenz.","a":"Verschiedene Beschleunigungs-Zeit-Verläufe je nach Ziel:\n• Abfallend: maximale Beschleunigung zu Beginn → Weg in kürzester Zeit (Fechtstoß, Boxschlag)\n• Ansteigend: maximale Beschleunigung am Ende → maximale Endgeschwindigkeit (Würfe, Sprünge)","e":"Hintergrund: Maximale Beschleunigungskräfte können nur kurzzeitig wirken, man muss also entscheiden, wann. Abfallend z. B. auch Karate oder der Sprintstart; ansteigend z. B. Speerwurf, Kugelstoßen, Würfe im Basketball und Handball, Weitsprunganlauf. Beispiel: Ein Boxer will, dass die Faust möglichst früh beim Gegner ist, damit dieser nicht ausweichen kann (abfallend). Der Weitspringer steigert sein Tempo im Anlauf bis zum Balken, weil dort die Geschwindigkeit am höchsten sein muss (ansteigend).","quelle":"L02.2","typ":"kern"},{"id":"q1.2-075","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Formuliere das Prinzip der Impulserhaltung und erläutere es mithilfe des Drehimpulserhaltungssatzes.","a":"• Extremitäten an die Drehachse → schnellere Drehung, von der Achse weg → langsamere (ohne mehr Kraft)\n• Drehimpulserhaltungssatz: ohne äußere Drehmomente bleibt L = J · ω konstant\n• Gehockt statt gestreckt: J ca. ⅓ → ca. dreifache Drehgeschwindigkeit","e":"Wird der Drehwiderstand J kleiner, steigt die Winkelgeschwindigkeit ω entsprechend und umgekehrt. So kann der Sportler seine Drehgeschwindigkeit aktiv kontrollieren (Zahlen nach Hochmuth). Im Flug ist der Drehimpuls fest, aber man kann ihn auf „schnell“ oder „langsam“ stellen. Beispiel: Eine Eiskunstläuferin zieht bei der Pirouette die Arme an und dreht sich rasant; ein Turmspringer hockt sich für mehrere Saltos zusammen und streckt sich vor dem Eintauchen, um die Drehung zu bremsen.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-076","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Formuliere das Prinzip der Gegenwirkung und nenne seine Funktionen bei sportlichen Bewegungen.","a":"• Bewegung von Körperteilen erzeugt Gegenbewegung anderer Körperteile\n• Grundlage: actio = reactio (Translation), Drehmoment-Reaktion (Rotation)\n• Funktionen: Gleichgewicht halten; Beschleunigung und Zielgenauigkeit verbessern; zweckmäßige Flug- und Landehaltung","e":"Beispiele für die Funktionen: Gleichgewicht beim Laufen, besserer Beschleunigungsverlauf beim Handballschlagwurf, Klappmesserhaltung im Weitsprung. Bewegt sich ein Teil des Körpers in eine Richtung, reagiert ein anderer Teil entgegengesetzt. Beispiel: Beim Laufen schwingt der rechte Arm vor, wenn das linke Bein vorgeht; ohne diesen Gegenschwung würde sich der ganze Körper hin- und herdrehen.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-077","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Was versteht man unter der Drehmoment-Reaktion (Kassat)?","a":"• Begriff (Kassat) für Rotationen, da actio = reactio nur für Translationen gilt\n• Ein kontrahierender Muskel erzeugt an beiden Körperteilen gleich große, entgegengesetzte Drehmomente\n• Dieses gemeinsame Auftreten = Drehmoment-Reaktion","e":"Kontrahiert z. B. der Oberarmbeuger, wirken an beiden Muskelenden gleich große, entgegengesetzte Kräfte auf Ober- und Unterarm. Weil sie exzentrisch zur Gelenkachse wirken, erhalten beide Teile gleich große, entgegengesetzte Drehmomente. Wie ein Taschenmesser, das zuklappt: Beide Teile bewegen sich aufeinander zu. Beispiel: Beim Schmetterschlag im Volleyball klappen Ober- und Unterkörper um das Hüftgelenk gegeneinander; der Einsatz des Oberkörpers erhöht die Wucht.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-078","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Welche zwei Situationen werden beim Prinzip der Gegenwirkung unterschieden? Erläutere sie am Beispiel des Weitsprungs.","a":"1. Körper mit Bodenkontakt: Anlauf mit Kreuzkoordination (Drehmoment-Reaktion Hüft- gegen Schulterachse); Absprung: Aktionskraft gegen den Boden → Bodenreaktionskraft\n2. Frei bewegtes System (Flug): Oberkörper nach vorn → Beine heben sich (Klappmesser) → größere Weite","e":"Im Anlauf verhindert die Kreuzkoordination (linkes Bein und rechter Arm vor und umgekehrt) eine Gesamtdrehung um die Längsachse und vergrößert über die Hüftdrehung die Schrittlänge; Spikes nutzen die horizontalen Kräfte. Beim Absprung (Sprungauslage – Amortisation – Streckung) wirkt die Aktionskraft nach vorn, senkrecht bzw. nach hinten unten. Im Flug ist die KSP-Bahn festgelegt, nur Körperteile können gegeneinander bewegt werden. Beispiel: Der Weitspringer klappt den Oberkörper nach vorn, dadurch kommen die Beine höher und er landet weiter vorne.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-079","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Erläutere das Prinzip der Gegenwirkung am Beispiel des Handballschlagwurfs.","a":"• Wurfschulter wird zurückgenommen, Hüfte entgegengesetzt nach vorn gedreht\n• Verwringung (Hüft- gegen Schulterachse) verlängert den Beschleunigungsweg und erhöht die Anfangskraft (Vorspannung)\n• Stabilisiert die Wurfauslage, erhöht Zielgenauigkeit","e":"Die Gegendrehung der Hüfte verhindert, dass der ganze Rumpf um die Längsachse rotiert. Durch Verwringung und Vorspannung der Wurfmuskulatur verbessert sich der Beschleunigungsverlauf. Schulter zurück, Hüfte vor: So wird der Körper wie ein Handtuch verdreht und setzt beim Aufdrehen viel Energie frei. Beispiel: Ein Rückraumspieler dreht beim Schlagwurf die Hüfte zum Tor, während die Wurfschulter noch hinten ist, und erzielt so harte, genaue Würfe.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-080","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Formuliere das Prinzip der Kinetion und Modulation. Was sind Kinetoren und Modulatoren?","a":"• Kinetion: Kräftige Muskeln von Beinen und Hüfte liefern die Antriebsenergie (Kinetoren)\n• Energie wird auf Schulter und Arme übertragen\n• Modulation: Feinmotorische Hand- und Fingermuskeln dosieren sie (Modulatoren)","e":"Das Prinzip gilt für zielgerichtete Bewegungen in aufrechter Haltung, z. B. in Handball, Volleyball, Basketball. Die Beine sind der Motor, die Hände das Lenkrad. Beispiel Handballschlagwurf: Anlauf, Hüftverwringung und Rumpf erzeugen die Wucht (Kinetion), Hand und Finger sorgen dafür, dass der Ball genau in die Torecke fliegt (Modulation).","quelle":"L02.2","typ":"kern"},{"id":"q1.2-081","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Erläutere die biomechanischen Prinzipien am Beispiel des Basketballsprungwurfs aus der Ballannahme.","a":"• Beschleunigungsweg: KSP-Senkung beim Stoppen\n• Anfangskraft: Bremskraftstoß unterstützt den Absprung\n• Gegenwirkung: Ball abbremsen → Reaktionskraft nach hinten\n• Koordination der Teilimpulse: fließende Übergänge\n• Kinetion/Modulation: Beine/Rumpf vs. Arme/Hände\n• Ansteigende Beschleunigungstendenz","e":"Beim Absenken entsteht ein nach oben gerichteter Bremskraftstoß, der bei fließendem Übergang als Anfangskraft wirkt. Das Abbremsen der Anreißbewegung des Balls in die Wurfauslage überträgt den Impuls auf den Gesamtkörper; der Abwurf folgt kurz vor dem „toten“ Punkt. Rumpf und Beine liefern die Sprungenergie, Arme und Hände die Zielgenauigkeit; die optimale Abwurfgeschwindigkeit wird erst im Abwurf erreicht. Beispiel: Ein Spieler fängt den Pass, stoppt mit gebeugten Knien (etwa 100°), springt explosiv ab und lässt den Ball im höchsten Punkt mit Rückwärtsdrall los.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-082","thema":"Q1.2","kapitel":"Biomechanische Prinzipien","q":"Warum soll beim Basketballsprungwurf das Handgelenk im „toten“ Punkt nachgedrückt werden („Sprung-Wurf“ statt „Wurf-Sprung“)?","a":"• Im „toten“ Punkt ist die vertikale KSP-Geschwindigkeit null\n• Keine störende senkrechte Komponente addiert sich zur Abwurfgeschwindigkeit\n• Früher/später werfen → Komponente muss ausgeglichen werden → zusätzliche Fehlerquelle","e":"Wirft man in der Aufwärts- oder Abwärtsbewegung, muss die Ball-Hand-Führung die nach oben oder unten gerichtete Geschwindigkeit koordinativ ausgleichen, was die Zielgenauigkeit verschlechtert. Im höchsten Punkt „steht“ man für einen Moment in der Luft, das ist wie ein Wurf aus dem Stand, nur höher. Beispiel: Wer schon während des Hochspringens wirft, gibt dem Ball ungewollt zusätzlichen Schwung nach oben und wirft dann oft zu weit.","quelle":"L02.2","typ":"kern"},{"id":"q1.2-083","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Was ist eine morphologische Bewegungsanalyse und wie unterscheidet sie sich von der biomechanischen Analyse?","a":"• Zerlegt Bewegungen in von außen wahrnehmbare Merkmale der Form/Gestalt und untersucht deren Beziehung\n• Beruht auf Beobachtung (Trainer, Lehrer)\n• Biomechanische Analyse: Aussagen über Messinstrumente","e":"Da in der Praxis meist keine Messgeräte wie Kraftmessplatten zur Verfügung stehen, wird häufig morphologisch analysiert. Die Bewegungsmerkmale lenken die Aufmerksamkeit des Beobachters auf das Wesentliche. Morphologisch heißt: nach der Gestalt, also mit dem „Trainerauge“. Beispiel: Ein Schwimmtrainer am Beckenrand hat keine Messgeräte, er sieht aber, ob der Armzug rhythmisch und fließend ist.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-084","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Nenne die neun Bewegungsmerkmale nach Meinel und Schnabel.","a":"1. Struktur sportlicher Bewegungsakte (Phasenstruktur)\n2. Bewegungsrhythmus\n3. Bewegungskopplung\n4. Bewegungsfluss\n5. Bewegungspräzision\n6. Bewegungskonstanz\n7. Bewegungsstärke\n8. Bewegungstempo\n9. Bewegungsumfang\n(Merkmale 2–9 heißen qualitative Bewegungsmerkmale)","e":"Das erste Merkmal beschreibt den Aufbau in Phasen, die übrigen acht die Qualität der Ausführung. Eselsbrücke für 2–9: „Rhythmus koppelt Fluss, präzise und konstant, stark, schnell und umfangreich“. Beispiel: Beim Hürdenlauf kann man sowohl die Phasen (Anlauf, Hürdenschritt, Landung) als auch den Rhythmus zwischen den Hürden beurteilen.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-085","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Was versteht man unter der Struktur einer sportlichen Bewegung und warum kann es mehrere Strukturen derselben Bewegung geben?","a":"• Struktur: Aufbau aus wechselseitig verbundenen Bestandteilen und deren Verknüpfung (Schnabel)\n• Bei Bewegungen = Ergebnis einer Bewegungsanalyse\n• Mehrere Strukturen je nach Analyseziel und sportartspezifischen Bedingungen","e":"Durch die Strukturanalyse wird ein Objekt als System gekennzeichnet und von anderen abgehoben. Streicher verdeutlicht das so: Ein Zoologe zerlegt ein Tier anders als eine Köchin, die gleiche Portionen braucht. Beispiel: Ein Schlusssprung ist an sich nur ein Beinstrecken, beim Skispringen, Turnen oder Wasserspringen muss er aber jeweils an Tempo und Bedingungen angepasst werden und hat eine andere Struktur.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-086","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Nenne die Elemente der morphologischen Grundstruktur sportlicher Bewegungen nach Meinel/Schnabel und beschreibe ihre Funktionen.","a":"• Vorbereitungsphase: schafft optimale Voraussetzungen für die Hauptphase (z. B. Ausholbewegung)\n• Hauptphase: löst die Bewegungsaufgabe direkt\n• Endphase: führt aus labiler Position in stabiles Gleichgewicht","e":"Vorbereiten – Ausführen – Ausklingen. Die Vorbereitung soll eine erfolgreiche und ökonomische Hauptphase ermöglichen; nach der Hauptphase ist man meist in einer labilen Lage, die die Endphase in einen statischen Zustand überführt. Beispiel Handstütz-Sprungüberschlag seitwärts: Anlauf und Einsprung sind Vorbereitung, Absprung, 1. Flugphase, Stütz und 2. Flugphase die Hauptphase, die Landung die Endphase.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-087","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Welche Beziehungen bestehen zwischen den Phasen einer azyklischen Bewegung? Definiere Zweck-, Ergebnis- und Kausalbeziehung.","a":"• Ergebnisbeziehung: Jede Phase hängt von der vorhergehenden ab (V → H → E)\n• Kausalbeziehung: Hauptphase erzwingt Endphase; Vorbereitung kann abgebrochen werden\n• Zweckbeziehung: Spätere Phase beeinflusst den Verlauf der vorhergehenden","e":"Die Zweckbeziehung muss schon bei der geistigen Programmierung der Bewegung berücksichtigt werden. Merkhilfe: Ergebnis = „vorne bestimmt hinten“, Zweck = „hinten bestimmt vorne“, Kausal = „Hauptphase erzwingt Endphase“. Beispiel Pferdsprung: Ohne schnellen Anlauf misslingt der Absprung (Ergebnis); wer gesprungen ist, muss landen (Kausal); der Anlauf wird von vornherein auf den Absprung abgestimmt (Zweck).","quelle":"L02.3","typ":"kern"},{"id":"q1.2-088","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Zwischen welchen Phasen bestehen starke bzw. schwache Zweckbeziehungen?","a":"• Stark: Hauptphase → Vorbereitungsphase\n• Schwach: Endphase → Hauptphase\n• Schwach, einseitig: Endphase → Vorbereitungsphase","e":"Die Vorbereitungsphase ordnet sich der Hauptphase funktional unter. Die Hauptphase ist der Endphase untergeordnet, weil eine misslungene Landung alles zunichtemacht. Und Anlauf und Ansprung werden so abgestimmt, dass eine Landung auf den Füßen überhaupt möglich ist. Die späteren Phasen „bestellen“ etwas bei den früheren. Beispiel Pferdsprung: Der Turner läuft so an, dass der Absprung optimal wird (stark), und richtet Stütz und 2. Flugphase so ein, dass er sicher stehen kann (schwach).","quelle":"L02.3","typ":"kern"},{"id":"q1.2-089","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Unterscheide azyklische und zyklische Bewegungen hinsichtlich ihrer Struktur.","a":"• Azyklisch: Zweck durch eine Hauptphase erreicht; dreiphasig (Vorbereitungs-, Haupt-, Endphase), z. B. Würfe, Sprünge\n• Zyklisch: Wiederholung gleicher Zyklen; zweiphasig (Haupt- und Zwischenphase) durch Phasenverschmelzung, z. B. Laufen, Schwimmen","e":"Bei zyklischen Bewegungen verschmelzen End- und Vorbereitungsphase zur Zwischenphase, weil der Zweck nur durch Wiederholung erreicht wird (auch Rudern, Radfahren). Azyklisch sind z. B. auch Kugelstoßen und Gewichtheben. Azyklisch = einmal, zyklisch = immer wieder. Beispiel: Beim Kugelstoßen gibt es einen klaren Anfang und ein Ende; beim Rudern geht das Ende eines Schlags (Ausheben der Blätter) direkt in die Vorbereitung des nächsten über.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-090","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Beschreibe die Phasenstruktur der leichtathletischen Laufbewegung (Sprint) als Beispiel für eine zyklische Bewegung.","a":"• Hauptphase: Abdruck im hinteren Stütz + Flugphase (hintere und vordere Schwungphase/Kniehub)\n• Zwischenphase: vorderer Stütz/Amortisation (Bodenfassen, Abbremsen) = verschmolzene End- und Vorbereitungsphase, kurz","e":"Die hintere Schwungphase ist das entspannte Durchschwingen nach dem Abdruck; die vordere Schwungphase (Kniehub) zählt zur Hauptphase, weil das Vorbringen des Schwungbeins durch Impulsübertragung den Abdruck beeinflusst. In der Zwischenphase fängt ein bremsender Kraftstoß den fallenden Körper ab, während das andere Bein herangeführt wird. Der Übergang in den hinteren Stütz beginnt die nächste Hauptphase. Beispiel: Die Landung auf dem Vorfuß bremst kurz (Zwischenphase), danach drückt sich der Sprinter sofort wieder kraftvoll ab (Hauptphase).","quelle":"L02.3","typ":"kern"},{"id":"q1.2-091","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Wie und warum wird die Grundstruktur durch die Unterdrückung von Ausholbewegungen verändert?","a":"• Ausholbewegung wird weitgehend unterdrückt, Beschleunigungsweg verkürzt\n• Anlass: Taktik, Regeln, technische Besonderheiten (v. a. Zielwürfe)\n• Gründe: höhere Zielgenauigkeit, schnellere Ausführung, Überraschung","e":"Das betrifft vor allem Sportspiele. Weniger Ausholen heißt weniger Fehlerquellen und weniger Zeit für den Gegner zu reagieren oder zu blocken. Eine große Ausholbewegung verrät dem Gegner, was man vorhat. Beispiel: Beim Positionswurf im Basketball wird der Ball ohne Ausholen aus der Grundstellung geworfen, so ist der Wurf genauer und schwerer zu blocken.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-092","thema":"Q1.2","kapitel":"Morphologische Bewegungsanalyse","q":"Erläutere, wie bei Täuschungshandlungen in Sportspielen die Grundstruktur einer Bewegung verändert wird.","a":"• Vorbereitungsphase wird angedeutet, aber nicht in die erwartete Hauptphase überführt (möglich nach Kausalbeziehung)\n• Stattdessen folgt eine andere Hauptphase\n• Vorbereitungsphase erhält taktische Funktion (Fehlreaktion des Gegners)","e":"Nach der Kausalbeziehung kann eine Vorbereitungsphase abgebrochen werden, ohne dass die Hauptphase folgen muss. Sie verliert dadurch ihre ursprüngliche Zweckbeziehung. Statt Wurf folgt z. B. ein Pass oder Durchbruch. Die Täuschung nutzt aus, dass der Gegner die Phasenstruktur kennt. Beispiel: Ein Handballer holt zum Wurf aus, der Torwart reagiert, doch statt zu werfen passt der Spieler zum frei stehenden Kreisläufer.","quelle":"L02.3","typ":"zusatz"},{"id":"q1.2-093","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Welche Bewegungsmerkmale werden als qualitative Bewegungsmerkmale bezeichnet und welche Bedeutung haben sie in der Praxis?","a":"• Rhythmus, Kopplung, Fluss, Präzision, Konstanz, Stärke, Tempo, Umfang\n• Bedeutung: zeigen den Lernfortschritt, Grundlage für Bewegungsanweisung und Fehlerkorrektur, lenken die Beobachtung aufs Wesentliche","e":"Beim Erlernen einer Bewegung sind diese Merkmale zunächst unzureichend ausgeprägt; je besser sie werden, desto weiter ist der Lernende. Mit ihnen kann ein Trainer genau sagen, was an einer Bewegung noch nicht stimmt. Beispiel: Die Anweisung „Mach immer fünf gleiche Schritte zwischen den Hürden“ zielt auf den Bewegungsrhythmus.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-094","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was beschreibt das Bewegungsmerkmal Bewegungsrhythmus?","a":"Zeitlich-dynamische Ordnung einer Bewegung: charakteristischer Wechsel von Spannung und Entspannung bzw. betonten und unbetonten Bewegungsteilen.","e":"Rhythmus ist wie der Takt in der Musik. Beispiel: Beim Hürdenlauf ist ein gleichmäßiger Rhythmus zwischen den Hürden (z. B. Fünf-Schritt-Rhythmus) entscheidend; beim Dreisprung der typische Rhythmus „lang – kurz – lang“.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-095","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was beschreibt das Bewegungsmerkmal Bewegungskopplung?","a":"Räumlich-zeitliche und dynamische Verbindung der Teilbewegungen: zweckmäßiges Zusammenspiel, Reihenfolge und Impulsübertragung zwischen den Teilkörpern.","e":"Kopplung heißt: Die Teilbewegungen greifen ineinander wie Zahnräder. Beispiel Kugelstoßen: erst die Beine, dann die Hüfte und zum Schluss die Arme strecken.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-096","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was beschreibt das Bewegungsmerkmal Bewegungsfluss?","a":"Grad der Kontinuität (Stetigkeit, Flüssigkeit) im Bewegungsablauf; gut = ohne Stockungen, Unterbrechungen oder ruckartige Übergänge.","e":"Fluss heißt: alles wie aus einem Guss. Beispiel: Bei ungeübten Werfern erkennt man einen schlechten Bewegungsfluss daran, dass sie nach dem Anlauf kurz stoppen, bevor sie werfen.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-097","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was beschreibt das Bewegungsmerkmal Bewegungspräzision? Welche zwei Formen werden unterschieden?","a":"Grad der Übereinstimmung mit geplantem Verlauf oder Ziel:\n• Verlaufspräzision (Ablaufgenauigkeit): Ablauf entspricht dem Soll-Verlauf\n• Zielpräzision (Treffgenauigkeit): Ergebnis entspricht dem Ziel","e":"Präzision heißt Genauigkeit, entweder im Ablauf oder im Ergebnis. Beispiel: Beim Wasserspringen braucht man eine hohe Verlaufspräzision (Haltung und Ablauf werden bewertet), beim Basketballwurf eine hohe Zielpräzision (der Ball muss in den Korb).","quelle":"L02.3","typ":"kern"},{"id":"q1.2-098","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was beschreibt das Bewegungsmerkmal Bewegungskonstanz?","a":"Grad der Übereinstimmung wiederholter Bewegungen (Wiederholungsgenauigkeit); hohe Konstanz zeigt hohen Automatisierungsgrad.","e":"Hohe Konstanz bedeutet, dass die Bewegung bei jeder Wiederholung nahezu identisch ausgeführt wird. Konstanz heißt: immer wieder gleich. Beispiel: Ein Basketballer, der seinen Freiwurf jedes Mal exakt gleich ausführt, hat eine hohe Trefferquote.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-099","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was beschreibt das Bewegungsmerkmal Bewegungsstärke?","a":"• Bewegungsaspekt: der Krafteinsatz bei sportlichen Bewegungen\n• Gemeint ist der situations- und aufgabenangemessene, dosierte Krafteinsatz, nicht unbedingt der maximale","e":"Bewegungsstärke heißt: so viel Kraft wie nötig. Beispiel: Bei einer Flanke im Fußball ist der richtige Krafteinsatz des Schussbeins leistungsbestimmend; zu fest fliegt der Ball ins Aus, zu schwach landet er beim Verteidiger.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-100","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was beschreiben die Bewegungsmerkmale Bewegungsumfang und Bewegungstempo?","a":"• Bewegungsumfang: räumliche Ausdehnung/Amplitude (z. B. Ausholweite, Gelenkwinkel)\n• Bewegungstempo: Geschwindigkeit und Frequenz von (Teil-)Bewegungen","e":"Umfang = wie groß, Tempo = wie schnell bzw. wie oft. Beispiel: Beim Handballwurf bestimmt die Weite der Ausholbewegung den Bewegungsumfang; beim Radfahren ist die Trittfrequenz, beim Rudern die Schlagfrequenz ein Ausdruck des Bewegungstempos.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-101","thema":"Q1.2","kapitel":"Qualitative Bewegungsmerkmale","q":"Was versteht man unter Bewegungsharmonie und welche Bedeutung hat sie?","a":"• Ausgewogenes Verhältnis aller Bewegungsmerkmale (Schnabel)\n• Kein eigenes Merkmal, sondern ästhetische Kategorie\n• Bedeutung: Bewertung ästhetischer Sportarten; gestörte Harmonie deckt koordinative Mängel auf","e":"In Turnen, Eiskunstlauf oder rhythmischer Sportgymnastik fließt Harmonie in die Bewertung ein. Im Techniktraining hat sie aufdeckende Funktion: Wirkt eine Bewegung unharmonisch, lässt sich der Mangel in einzelnen Bewegungsmerkmalen genauer feststellen. Eine harmonische Bewegung sieht einfach „schön und stimmig“ aus. Beispiel: Wirkt die Kür einer Eiskunstläuferin unharmonisch, kann der Trainer genauer hinschauen und z. B. feststellen, dass der Bewegungsfluss beim Absprung gestört ist.","quelle":"L02.3","typ":"kern"},{"id":"q1.2-102","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Was bezeichnet der Begriff „Funktion“ allgemein und übertragen auf sportliche Bewegungen?","a":"• Allgemein: Aufgabe/Zweck eines Teils innerhalb eines geordneten Ganzen\n• Sport: Aufgabe, die eine Aktion für die Gesamtbewegung bzw. Bewegungsaufgabe erfüllt","e":"Funktion beantwortet die Frage „Wozu ist das da?“. Beispiel: Beim Schweizer Taschenmesser hat jedes Teil eine Funktion; beim Weitsprung hat das Vorbringen der Beine die Funktion, die Landung zu optimieren.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-103","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Definiere die funktionale Bewegungsanalyse nach Göhner.","a":"Systematische Suche nach den Bestandteilen einer sportlichen Bewegung, die im Blick auf die zu lösende Bewegungsaufgabe eine Funktion haben (Göhner). Ausgangspunkt: die Bewegungsaufgabe.","e":"Die Analyse benennt sichtbare Aktionen, beschreibt sie und prüft deren Funktion für die Bewegungsaufgabe mit ihren Einflussgrößen. Man fragt bei jedem Teil: Was trägt es zur Lösung bei? Beispiel Counter-Movement-Jump: Das Tiefgehen hat die Funktion, einen optimalen Beschleunigungsweg vorzubereiten, der Armschwung die Funktion, durch Impulsübertragung zusätzlich Energie zu liefern.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-104","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Welche Bezugsgrundlagen hat die funktionale Bewegungsanalyse nach Göhner?","a":"Einflussgrößen der Bewegungsaufgabe:\n• Bewegungsziel\n• Movendum und Attribute\n• Beweger und Attribute/Hilfsmittel\n• Umgebungsbedingungen\n• Regelbedingungen","e":"Ändert sich eine Bezugsgrundlage, können sich auch die Funktionen und damit die zweckmäßigen Aktionen ändern. Ziele sind z. B. Distanzmaximierung, Zeitminimierung oder Treffergenauigkeit; Umgebung meint Sportstätte und äußere Bedingungen. Eine Funktion gibt es also nie „an sich“. Beispiel: Die Schleudertechnik im Speerwurf erfüllte die Funktion „langer Beschleunigungsweg“ hervorragend, wurde aber durch eine Regeländerung verboten; damit fiel sie als Lösung weg.","quelle":"L02.4 / Zusatzwissen","typ":"zusatz"},{"id":"q1.2-105","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Welche zwei Ausgangspunkte einer Funktionsanalyse unterscheidet Göhner?","a":"• Von der Bewegungsaufgabe aus: Suche nach Teilzielen unabhängig von bekannten Lösungen\n• Von vorhandenen Lösungen aus: deren Aktionen sind Basis → aktionsorientierte Funktionsanalyse","e":"Man kann eine Technik neu erfinden oder eine bestehende Technik erklären. Beispiel: Fosbury fragte gewissermaßen neu, wie man am besten über die Latte kommt; ein Trainer, der den Flop seines Athleten analysiert, geht dagegen aktionsorientiert vor.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-106","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Nenne und erläutere die vier Schritte der aktionsorientierten Funktionsanalyse nach Göhner.","a":"1. Aktionsskizze (Was?)\n2. Verlauf mit Aktionsmodalitäten beschreiben (Wie?)\n3. Aktionen/Modalitäten mit Funktionen belegen (Wozu?)\n4. Funktionsbelegungen überprüfen","e":"In der Aktionsskizze listet man die sichtbaren Aktionen auf, die zur Lösung der Aufgabe in jedem Fall nötig sind. Schritt 3 ist der wichtigste: Jeder Aktion und Modalität wird mindestens eine Funktion zugeordnet. Schritt 4 ist nötig, weil fehlerhafte Belegungen vorkommen. Beispiel Positionswurf: Aktionen sind u. a. Grundstellung, Stoßen und Werfen; im Verlauf hält man z. B. „Handgelenk weit zurückgespannt“ fest; Funktion: optimaler Beschleunigungsweg für das Nachdrücken; zuletzt prüft man, ob das wirklich so wirkt.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-107","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Was sind Aktionsmodalitäten? Nenne die Bereiche, auf die sie sich beziehen.","a":"Aktionsmodalitäten beschreiben, wie eine Aktion ausgeführt wird (exakte Verlaufsform). Angaben zu:\n• Raumrichtung\n• zeitlicher Abfolge\n• Geschwindigkeit\n• Krafteinsatz\n• Gelenkstellungen","e":"Typische Angaben: Raumrichtung (links, oben, schulterbreit), Abfolge (zuerst, danach), Geschwindigkeit (schnell, langsam), Krafteinsatz (explosiv, schwunghaft), Gelenkstellung (schwache Hüftbeugung, maximal zurückgespanntes Handgelenk). Die Aktion sagt, was passiert, die Modalität, wie genau. Beispiel: Aktion „Absprung“, Modalitäten „explosiv, einbeinig, mit leicht gebeugtem Knie, nach vorne oben“.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-108","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Nenne die fünf Aktionen des Positionswurfs im Basketball und ihre Funktionen (nach Tab. 2.3).","a":"• Grundstellung: günstige Voraussetzungen schaffen\n• Einleiten: KSP nach vorn, Vorspannung\n• Stoßen: Kraftimpulse in Abwurfrichtung übertragen (Kinetion)\n• Werfen: optimale Flugbahn (Modulation)\n• Vollenden: stabile Position, nicht übertreten, Follow-Through","e":"Beim Einleiten werden Anfangskraft und optimaler Beschleunigungsweg genutzt. Beim Stoßen kommen die Impulse aus Bein- und Hüftstreckung, Schulter, Ellbogenstreckung und Handgelenk. Das Vollenden umfasst Recovery, Nicht-Übertreten beim Freiwurf und Follow-Through. Beispiel: Das Stoßen ist ein zentraler Stoß durch den Ballschwerpunkt, erst das Werfen (Abklappen des Handgelenks, Zeige- und Mittelfinger) gibt dem Ball Rückwärtsdrall und die genaue Flugbahn.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-109","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Was versteht man unter einer rückwirkenden Aktionsüberprüfung bei der Funktionsanalyse?","a":"• Prüfen, ob eine Aktion ihre zugewiesene Funktion wirklich erfüllt\n• Prüfen, ob andere Aktionen gleich gut oder besser wären\n• Überflüssige oder störende Aktionen weglassen","e":"Alternativen können z. B. für bestimmte Lernende günstiger sein. Man stellt jede Aktion auf den Prüfstand. Beispiel: Manche Autoren empfehlen beim Positionswurf, den Ball aus der Wurftasche vor der Brust in die Wurfauslage zu reißen. Diese Anreißbewegung bringt den Ball nur in die Wurfauslage und schafft Fehlerquellen; günstiger ist es, ihn gleich über dem Kopf zu halten und Ball und Korb von Beginn an zu sehen.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-110","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Welchen Nutzen haben Funktionsanalysen?","a":"• Bewegungsspielräume (Funktionsäquivalenz, -verbesserung)\n• Hierarchien (Haupt-/Hilfsaktionen)\n• Aufdecken von Bewegungsfehlern\n• Bewegungsverwandtschaften\n• Hilfe bei Lehr-Lern-Problemen","e":"Hierarchien zeigen funktionale Abhängigkeiten; bei Lernproblemen kann man Aufgabe oder Ablauf verändern. Die Funktionsanalyse ist ein vielseitiges Werkzeug für Trainer und Lehrer. Beispiel: Sie erklärt, warum ein Fehler ein Fehler ist, und zeigt zugleich, welche Abwandlungen der Technik erlaubt sind.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-111","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Was versteht man unter Bewegungsspielräumen, Funktionsäquivalenz und Funktionsverbesserung?","a":"• Bewegungsspielraum: Aktionen können verändert/ersetzt werden\n• Funktionsäquivalenz: gleiche Funktion erreicht\n• Funktionsverbesserung: Funktion besser erfüllt\n→ Es gibt mehrere funktionserfüllende Lösungen","e":"Es gibt also nicht die eine richtige Technik; viele Wege führen nach Rom, solange die Funktion erfüllt wird. Beispiel: Dirk Nowitzki sprang beim Sprungwurf nach hinten statt nach oben (Fadeaway). Der Ball kommt trotzdem auf eine günstige Flugbahn, und der Wurf ist zusätzlich schwer zu blocken, also eine Funktionsverbesserung gegen Verteidiger.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-112","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Erkläre die Begriffe funktional abhängig und funktional unabhängig sowie Haupt- und Hilfsaktion.","a":"• Funktional abhängig: Funktion nur mit Verweis auf eine andere Aktion definierbar → Hilfsaktion\n• Funktional unabhängig: dient unmittelbar der Bewegungsaufgabe → Hauptaktion","e":"Die Hauptaktion hat die Hauptfunktion und löst die Aufgabe direkt, Hilfsaktionen haben Hilfsfunktionen und unterstützen andere Aktionen. Beispiel Positionswurf: Nur das Werfen des Balls bringt den Ball direkt auf die Flugbahn (Hauptaktion). Die Grundstellung dient dem Einleiten, Stoßen und Werfen, ist also eine Hilfsaktion.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-113","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Was versteht man unter Funktionsphasen (Funktionsphasenanalyse) und welche Einschränkung ist zu beachten?","a":"• Aus Haupt- und Hilfsaktionen abgeleitet: Hauptfunktionsphase + vorbereitende, überleitende, unterstützende Hilfsfunktionsphasen (1., 2. Ordnung)\n• Einschränkung: Göhners Analyse ist kein Phasenkonzept; Phasengrenzen schwer bestimmbar","e":"Hilfsfunktionsphasen 1. Ordnung beziehen sich direkt auf die Hauptfunktionsphase, solche 2. Ordnung auf eine andere Hilfsfunktionsphase. Anders als die morphologische Analyse ist Göhners Ansatz im Kern kein Phasenkonzept, und Start- und Endzeitpunkt einer Teilphase sind oft schwer anzugeben. Funktionsphasen ordnen den Ablauf nach ihrer Aufgabe statt nach ihrem Aussehen. Beispiel Weitsprung: Der Absprung ist Hauptfunktionsphase, der Anlauf eine vorbereitende, Flug- und Landungsaktionen sind unterstützende bzw. überleitende Hilfsfunktionsphasen.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-114","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Wie werden Bewegungsfehler in der funktionalen Bewegungsanalyse bestimmt?","a":"Fehler = jede Aktion oder Aktionsmodalität, die ihre Funktion nicht erfüllt; nicht die Abweichung von einem Idealbild.","e":"Zur Fehlerbestimmung prüft man die beobachtete Ausführung auf ihre Funktionserfüllung. Nicht „anders als das Lehrbuchbild“ ist ein Fehler, sondern „erfüllt seinen Zweck nicht“. Beispiel: Ist beim Positionswurf das Handgelenk in der Wurfauslage nicht weit zurückgespannt, wird der Kraftstoß aus der Ellbogenstreckung nicht in Abwurfrichtung übertragen, also ein Fehler.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-115","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Was versteht man unter Bewegungsverwandtschaften und welchen Nutzen hat ihre Erkenntnis?","a":"• Sportartübergreifende Gemeinsamkeiten von Bewegungen mit gleichen Funktionen\n• Nutzen: Probleme vergleichen, Erkenntnisse austauschen, Transfer beim Lernen","e":"Die Funktionsanalyse erlaubt den Blick über die Sportart hinaus, denn in vielen Sportarten wird gelaufen, gesprungen und geworfen. Gleiche Funktion, verschiedene Sportart. Beispiel: Der „Jugo-Step“, eine Korblegervariante im Basketball mit der Schrittfolge rechts – rechts – links, entspricht der Dreisprungtechnik aus der Leichtathletik.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-116","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Welche zwei Arten von Lernhilfen lassen sich nach Göhner aus Funktionsanalysen ableiten?","a":"• Veränderung der Bewegungsaufgabe (z. B. Regeln): geringeres koordinatives Niveau, Hauptaktion bleibt\n• Veränderung des Bewegungsablaufs: Hilfsaktionen vereinfachen/weglassen, Hauptaktion von Beginn an üben","e":"Die Hauptaktion bleibt, das Drumherum wird vereinfacht. Beispiel Basketballsprungwurf: Zunächst wird die Schrittregel ignoriert (Aufgabe verändert); oder man wirft zuerst aus dem Stand mit dem Ball schon über dem Kopf (Ablauf verändert). In beiden Fällen wird das Werfen im toten Punkt von Anfang an geübt.","quelle":"L02.4","typ":"kern"},{"id":"q1.2-117","thema":"Q1.2","kapitel":"Funktionale Bewegungsanalyse","q":"Stelle die morphologische und die funktionale Bewegungsanalyse gegenüber und erörtere Vor- und Nachteile.","a":"Morphologisch (Meinel/Schnabel):\n+ ohne Messgeräte, praxisnah, klare Beobachtungskriterien\n− beschreibt nur das Äußere, teils subjektiv, Idealbild\nFunktional (Göhner):\n+ erklärt den Zweck, zeigt Spielräume, begründet Fehler und Lernhilfen\n− aufwendig, Belegungen können falsch sein, kein Phasenkonzept\nFazit: ergänzen sich","e":"Die Morphologie liefert mit Phasenstruktur und qualitativen Merkmalen Beobachtungs- und Korrekturkriterien, erklärt aber nicht, warum eine Aktion nötig ist. Die Funktionsanalyse zeigt Haupt- und Hilfsaktionen und erlaubt sportartübergreifende Vergleiche, verlangt aber genaue Kenntnis der Bewegungsaufgabe und der Biomechanik. Die Morphologie beschreibt, wie es aussieht, die Funktionsanalyse begründet, warum es so sein muss. Beispiel Flop: Morphologisch erkennt man Anlauf – Absprung/Lattenüberquerung – Landung; funktional versteht man, warum der Bogenlauf vor dem Absprung die Drehung um die Längsachse einleitet.","quelle":"L02.5","typ":"zusatz"},{"id":"q1.4-001","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Welche zwei Positionen stehen sich seit den 1970er-Jahren in der Diskussion um die Rolle der Sportspiele im Schulsport gegenüber?","a":"• Sportpädagogen: Sportspiel als Erziehungsmittel (Kooperation, Selbstständigkeit, Konfliktlösen) → „Spielen lernen“\n• Traditionalisten: Sportspiel in regelgerechter Form vermitteln (Technik, Taktik, Regeln) → „ein Spiel erlernen“","e":"Die einen fragen: Was lernen Kinder durch das Spielen fürs Leben? Die anderen fragen: Wie werden Kinder gute Basketballer? Beide Seiten haben ihre Berechtigung; moderne Konzepte verbinden das Spielerleben (Spielidee, Freude, soziales Lernen) mit dem schrittweisen Heranführen an das Zielspiel. Beispiel: Eine Klasse handelt selbst faire Teams und Regeln aus (pädagogische Sicht), eine andere übt Korbleger und Positionsangriff, um das Regelspiel zu beherrschen (traditionelle Sicht).","quelle":"L18.1","typ":"kern"},{"id":"q1.4-002","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Nach welchen drei Gesichtspunkten kann das Phänomen „Spielen“ in Anlehnung an Grupe (1982) analysiert werden?","a":"• Ursachen des Spiels (Warum spielt der Mensch?)\n• Struktur-/Wesensmerkmale (Was macht Spiel aus?)\n• Funktionen und Ziele (Was bewirkt Spielen?)","e":"Man kann das Spiel wie ein Werkzeug untersuchen: Woher kommt es, wie ist es gebaut, wofür ist es gut? Die Betrachtung ist anthropologisch, bezieht sich also auf das Wesen des Menschen, berücksichtigt aber auch gesellschaftliche und kulturelle Gegebenheiten. Beispiel: Beim Fangenspielen fragt man, warum Kinder es spielen (Ursache), dass es keinen äußeren Zweck hat (Merkmal) und dass es Regeln einüben lässt (Funktion).","quelle":"L18.1","typ":"kern"},{"id":"q1.4-003","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Nenne und erläutere die drei Richtungen der Ursachenforschung zum Spiel (nach Grupe).","a":"• Triebtheoretisch: angeborener Spieltrieb/Instinkt\n• Konflikttheoretisch (psychoanalytisch): gefahrloses Verarbeiten erlebter Konflikte\n• Sozialisationstheoretisch: beiläufiges Aneignen von Normen, Werten, Regeln (König)","e":"Drei Brillen auf dieselbe Sache: Trieb (es steckt in uns), Konflikt (wir verarbeiten etwas), Sozialisation (wir lernen die Regeln der Gesellschaft – implizit, „spielerisch-beiläufig“). Keiner der Ansätze kann das vielschichtige Phänomen Spielen allein vollständig erklären. Beispiel: Ein Kind spielt nach einem Streit „Vater-Mutter-Kind“ – konflikttheoretisch verarbeitet es den Streit, sozialisationstheoretisch übt es Rollen ein.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-004","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Welche Kritik wird an triebtheoretischen Erklärungen des Spiels geübt?","a":"Ein angeborener, universeller Spieltrieb müsste bei allen Menschen auftreten – es gibt aber Menschen, Gruppen und Kulturen, die kaum oder gar nicht spielen.","e":"Wenn Hunger ein Trieb ist, haben ihn alle Menschen. Beim Spielen ist das offenbar nicht so eindeutig, deshalb reicht die Triebtheorie als alleinige Erklärung nicht aus. Beispiel: In Gesellschaften, in denen Kinder früh mitarbeiten müssen, wird kaum gespielt – ein reiner Trieb wäre so nicht einfach abschaltbar.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-005","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Nenne die fünf Wesensmerkmale des Spiels (nach Grupe).","a":"• Zweckfreiheit\n• Zwanglosigkeit\n• Einzigartigkeit\n• Lustvolles Streben nach Wiederholung\n• Gegenwärtigkeit","e":"Eselsbrücke „ZZ-ELG“: zwei Z (Zweckfrei, Zwanglos), dann Einzigartig, Lust auf Wiederholung, Gegenwart. Beispiel: Kinder kicken auf dem Bolzplatz ohne Auftrag (zwanglos), nur um zu kicken (zweckfrei), völlig im Moment (gegenwärtig) und wollen gleich noch eine Runde (Wiederholung).","quelle":"L18.1","typ":"kern"},{"id":"q1.4-006","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Erläutere die Wesensmerkmale Zweckfreiheit und Zwanglosigkeit des Spiels und grenze sie voneinander ab.","a":"• Zweckfreiheit: Zweck liegt im Spiel selbst (Ziele nur innerhalb des Spiels)\n• Zwanglosigkeit: freiwillig, keine lebensnotwendige Bedürfnisbefriedigung, materiell nutzlos\n• Abgrenzung: Zweckfreiheit betrifft das Ziel, Zwanglosigkeit die Freiwilligkeit","e":"Zweckfrei heißt: Das Tor ist das Ziel, nicht Geld oder Noten. Zwanglos heißt: Keiner zwingt dich mitzuspielen, und du überlebst auch ohne Spiel. Beispiel: Ein Profi, der nur für sein Gehalt spielt, verliert ein Stück dieser Spielmerkmale – sein Spiel bekommt einen äußeren Zweck und wird zur Arbeit.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-007","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Erläutere die Wesensmerkmale Einzigartigkeit, lustvolles Streben nach Wiederholung und Gegenwärtigkeit.","a":"• Einzigartigkeit: existenziell, vermittelt unersetzbare Erfahrungen\n• Streben nach Wiederholung: lustvoll und spannend, drängt nach Wiederholung\n• Gegenwärtigkeit: dem Augenblick verpflichtet, macht im Moment Spaß (Schmidt)","e":"Spiel betrifft grundlegend menschliches Erleben und Handeln. Gute Spiele erlebt man im Hier und Jetzt und will sie sofort nochmal spielen. Beispiel: Nach einem spannenden Völkerballspiel rufen alle „Nochmal!“ – das ist das Streben nach Wiederholung; während des Spiels denkt niemand an die Mathearbeit – das ist Gegenwärtigkeit.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-008","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Welche Ziele und Funktionen haben Spiele für die Persönlichkeitsentwicklung (nach König, 2013)?","a":"• Illusion und Fiktion (Kreativität)\n• Emotionen erleben und verarbeiten\n• personale und soziale Entwicklung\n• Vereinbarungen treffen und einhalten\n• moralische Entwicklung\n• Gesundheitsförderung","e":"Spielen ist eine Schule fürs Leben, ohne dass es sich wie Schule anfühlt – die Wirkungen entstehen implizit durch gelingendes Spielen. Sozial lernt man z. B., Sieg und Niederlage zu akzeptieren und zwischen Kooperation und Konkurrenz zu wechseln; moralisch, Regeln als verpflichtend anzusehen und Rechte anderer zu achten. Beispiel: Nach einem Foul ist man wütend, gibt danach aber die Hand – man lernt, Gefühle zu verarbeiten und fair zu bleiben.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-009","thema":"Q1.4","kapitel":"Spiel und Spielen","q":"Erläutere den Unterschied zwischen „Spielen lernen“ und „ein Spiel erlernen“.","a":"• Spielen lernen: allgemeine Spielfähigkeit, Spielfreude, soziale Ziele, spielübergreifend (pädagogische/integrative/genetische Ansätze)\n• Ein Spiel erlernen: ein Sportspiel in normierter Form mit Technik, Taktik, Regeln (traditionelle Ansätze)","e":"Das eine ist wie „Sprechen lernen“, das andere wie „Französisch lernen“. Beim Spielen lernen geht es auch darum, Regeln auszuhandeln, zu kooperieren und Konflikte zu lösen; beim Spiel erlernen um das Beherrschen des Zielspiels. Beispiel: Ein Kind in der Ballschule lernt, Lücken zu erkennen und sich anzubieten (Spielen lernen); ein Jugendlicher im Volleyballverein lernt das Pritschen und die Rotationsregel (ein Spiel erlernen).","quelle":"L18.1","typ":"kern"},{"id":"q1.4-010","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Definiere den Begriff Wettkampf (nach Güllich & Krüger).","a":"Kulturelle Institution, in der Bewegungsaufgaben nach einem sportartspezifischen Regelwerk gelöst werden und die Gegner sich gegenseitig am Erfolg zu hindern versuchen.","e":"Ein Wettkampf ist ein geregeltes Gegeneinander mit Siegerermittlung. Das sportwissenschaftliche Lexikon (Starischka) ergänzt: Auseinandersetzung zwischen Sportlern bzw. Mannschaften nach vorher festgelegten Regeln mit dem Ziel, den Sieger zu ermitteln. Beispiel: Im Tennis will jeder den Punkt machen und gleichzeitig verhindern, dass der Gegner ihn macht – nach Regeln, die beide vorher kennen.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-011","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Was legt ein sportartspezifisches Regelwerk fest?","a":"Bündel von Normen, das festlegt:\n• Ziel der Bewegungshandlung\n• zulässige/unzulässige Handlungen\n• Ausführungsmöglichkeiten\n• Materialbeschaffenheit\n• Maßstab für den Leistungsvergleich","e":"Das Regelwerk ist die „Verfassung“ einer Sportart: ein Bündel von Normen und Interaktionsmustern. Beispiel: Im Speerwurf ist festgelegt, wie schwer der Speer ist, dass man nicht übertreten darf und dass die Weite zählt.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-012","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Welche vier zentralen Merkmale von Wettkämpfen werden durch Regelwerke gewährleistet (nach Güllich & Krüger)?","a":"• Chancengleichheit\n• formale Konkurrenzsysteme und Leistungsvergleich nach akzeptierten Maßstäben\n• Sicherheit und Unversehrtheit\n• gemeinsames Sporttreiben durch einfache Gütekriterien und feste Regeln","e":"Ohne Regeln kein fairer, sicherer und vergleichbarer Wettkampf. Einfache Gütekriterien sind z. B. Zeitminimierung oder Distanz-, Gewichts-, Treffer- und Punktemaximierung; die Regeln müssen nicht von Fall zu Fall neu ausgehandelt werden. Beispiel: Weil im 100-m-Lauf überall gleich gemessen wird, kann man eine Zeit aus Tokio mit einer aus Berlin vergleichen, und niemand muss vor dem Start diskutieren, was zählt.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-013","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Erläutere die Herkunft des Wortes „Wettkampf“.","a":"• „Kampf“: Agonalität, besser sein wollen als andere – seit der Antike (Homer)\n• „Wett“: Wetten; im England des 18./19. Jh. wurden Wettkämpfe ausgetragen, damit „Gentlemen“ auf Sieger setzen konnten","e":"Wett-Kampf = ein Kampf, auf den man wetten kann. Kämpfe gibt es in allen gesellschaftlichen Bereichen. England gilt als „Geburtsland“ des Sports: Pferdesport, Boxen, Rudern und Laufen wurden ausgetragen, weil reiche Gentlemen Spannung und Nervenkitzel liebten. Beispiel: Das berühmte Ruderrennen Oxford gegen Cambridge war früher auch ein Wettereignis für reiche Zuschauer.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-014","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Welche Merkmale kennzeichnen Regeln im Sport?","a":"• beruhen auf Konventionen (nicht angeboren, erlernbar)\n• regulieren Handeln (erlaubt/verboten)\n• werden meist unbewusst befolgt\n• veränderbar","e":"Regeln sind von Menschen gemacht und deshalb auch von Menschen änderbar: Abweichungen sind möglich, und kollektive Verstöße können zu neuen Regeln führen. Man kann regelgerecht spielen, ohne das ganze Regelwerk zu kennen. Beispiel: Weil Torhüter ständig Zeit schindeten, indem sie Rückpässe aufnahmen, wurde 1992 im Fußball die Rückpassregel eingeführt.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-015","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Unterscheide konstitutive und strategische Regeln (nach Digel, 1982).","a":"• Konstitutive Regeln: legen das Regelwerk fest, machen die Sportart erst aus\n• Strategische Regeln: taktische Maßnahmen, die die Spielräume der konstitutiven Regeln ausschöpfen","e":"Konstitutiv = „Was ist erlaubt?“, strategisch = „Wie nutze ich das Erlaubte klug aus?“. Strategische Regeln zeigen sich im Handeln von Trainern, Spielern und Mannschaften. Beide Regelarten lassen sich nach Inventar, Personal, Raum, Zeit und Handlungen ausdifferenzieren. Beispiel: Dass im Handball sieben Spieler pro Team auf dem Feld stehen, ist konstitutiv (Personal); den Torwart durch einen siebten Feldspieler zu ersetzen, ist strategisch.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-016","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Nach welchen fünf Kategorien lassen sich Regeln (und Regelvereinfachungen) nach Digel unterscheiden?","a":"• Inventarregeln (z. B. Größe des Tores, Ball)\n• Zeitregeln (z. B. Dauer des Spiels)\n• Raumregeln (z. B. Spielfeldgröße)\n• Personalregeln (z. B. Anzahl der Spieler)\n• Handlungsregeln (z. B. Foulregel)","e":"Eselsbrücke „IZ-RPH“: Inventar, Zeit, Raum, Personal, Handlung – alles, was man an einem Spiel verändern kann. Beispiel: Im Schulvolleyball spielt man 3 gegen 3 (Personal) auf kleinem Feld (Raum) mit leichterem Ball (Inventar) und darf den Ball fangen (Handlung).","quelle":"L18.1","typ":"kern"},{"id":"q1.4-017","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Welche Funktion haben Regelvereinfachungen im Sportspiel?","a":"Sie passen das komplexe Regelwerk an Können und Bedürfnisse der Anfänger an und ermöglichen freudvolle Teilnahme – die Spielidee des Zielspiels bleibt erhalten.","e":"Regeln vereinfachen heißt: das Spiel passend machen, damit alle mitspielen können. Das bringt mehr Ballkontakte, mehr Erfolgserlebnisse und mehr Spielfluss. Vereinfachen kann man nach den Kategorien Inventar, Zeit, Raum, Personal und Handlung. Beispiel: Ohne Abseitsregel im Fußball oder ohne Schrittregel im Handball kommen Anfänger ins Spiel, statt ständig abgepfiffen zu werden.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-018","thema":"Q1.4","kapitel":"Wettkampf und Regeln","q":"Erläutere, wie Regelvereinfachungen im Kontext des KAR-Modells nach Neumaier zu sehen sind.","a":"Regelvereinfachungen wirken als „Regler“ im KAR-Modell: Sie senken gezielt Druckbedingungen (Präzisions-, Zeit-, Komplexitäts-, Situations-, Belastungsdruck); umgekehrt können sie sie für Stärkere erhöhen (Differenzierung).","e":"Das KAR-Modell (Koordinations-Anforderungs-Regler) beschreibt Anforderungen über Informationsanforderungen (optisch, akustisch, taktil, kinästhetisch, vestibulär) und Druckbedingungen. Größere Tore senken den Präzisionsdruck, weniger Bedrängnis den Zeitdruck, weniger Regeln oder Spieler den Komplexitätsdruck, Überzahl oder kleinere Felder den Situationsdruck. Beispiel: Im Basketball für Anfänger einen tieferen Korb zu nehmen, dreht den Präzisionsdruck herunter; Spielen in Unterzahl dreht den Zeit- und Situationsdruck für Fortgeschrittene hoch.","quelle":"L18.1","typ":"kern"},{"id":"q1.4-019","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Welche drei Begriffe sind zentral für alle Konzepte der Sportspielvermittlung, und welche Hauptkonzepte werden unterschieden?","a":"Begriffe: Spielidee, Spielform, Spielfähigkeit\nKonzepte:\n• Spielgemäßes Konzept (Dietrich u. a.)\n• Integrative Sportspielvermittlung (Ballschule; Kröger & Roth)\n• Genetisches Lernen (Loibl)\n• Taktik-Spiel-Konzept (Mitchell u. a.)","e":"Die drei Begriffe sind das Werkzeug, mit dem man alle Konzepte beschreiben kann. Das spielgemäße Konzept stammt von Dietrich, Dürrwächter und Schaller, das genetische Lernen von Loibl nach Wagenschein, der Tactical Games Approach von Mitchell, Oslin & Griffin. Ergänzend gibt es die vielseitig orientierte Sportspielvermittlung. Beispiel: Egal ob Ballschule oder Taktik-Spiel-Konzept – beide wollen Spielfähigkeit erreichen und arbeiten mit Spielformen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-020","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Was versteht man unter der Spielidee eines Sportspiels?","a":"Kern eines Sportspiels (Kuhlmann): Jede Mannschaft will ein Ziel erreichen (z. B. Tore) und es dem Gegner verwehren; Angriff und Abwehr laufen simultan und korrespondierend ab.","e":"Die Spielidee ist das, was übrig bleibt, wenn man alle Detailregeln weglässt. Der Angriff von A entspricht immer der Abwehr von B und umgekehrt. Alle modernen Vermittlungskonzepte berücksichtigen die Spielidee schon bei der Einführung, weil Sportspielen mehr ist als das Beherrschen von Techniken. Beispiel Basketball: Beide Teams wollen Körbe erzielen und Körbe des Gegners verhindern – ob mit oder ohne Dribbelregel.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-021","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Definiere den Begriff Spielform und grenze ihn von einer „spielerisch eingekleideten Übungsform“ ab (nach Schaller).","a":"• Spielform: vereinfachte Form eines Sportspiels, die stets die Spielidee des Zielspiels enthält\n• Spielerisch eingekleidete Übungsform: Übung mit Wettbewerb, aber ohne die Spielidee","e":"Nicht alles, was nach Spiel aussieht, ist eine Spielform. Entscheidend ist, ob die Spielidee (Gegeneinander um Tore/Körbe mit Angriff und Abwehr) vorhanden ist – nicht, ob es einen Wettbewerb gibt. Beispiel: Eine Dribbelstaffel hat Wettkampf, aber kein Angriff-Abwehr-Spiel um Körbe – sie ist eine eingekleidete Übungsform. Ein 2-gegen-2 auf einen Korb ist dagegen eine Spielform.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-022","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Was ist eine Spielreihe?","a":"Methodische Anordnung von Spielformen mit der Spielidee des Zielspiels und steigender Komplexität, die schrittweise zum Zielspiel hinführt.","e":"Die Spielreihe ist eine Treppe aus Spielen, bei der jede Stufe schon nach dem Zielspiel aussieht. Typische Prinzipien: vom Einfachen zum Komplexen, vom Leichten zum Schweren, von kleinen zu größeren Mannschaften, vom Bekannten zum Unbekannten. Der Begriff wurde v. a. durch das spielgemäße Konzept geprägt. Beispiel Fußball: 1:1 auf ein Tor, dann 2:1 auf ein Tor, dann 3:3 auf zwei Tore bis zum Kleinfeldspiel.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-023","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Definiere den Begriff Spielfähigkeit.","a":"Komplexe Qualifikation aus spielmotorischer, kognitiver, sozialer und emotional-affektiver Kompetenz, die neue Handlungsmöglichkeiten im Spiel und ein freudvolles Spielerlebnis eröffnet (Kuhlmann).","e":"Spielfähig ist, wer nicht nur Techniken kann, sondern im Spiel mit Kopf, Körper, Gefühl und im Team klarkommt. Der Erwerb von Spielfähigkeit ist das Hauptziel der Vermittlung Großer Spiele. Beispiel: Eine Spielerin, die gut passt, die Situation liest, fair bleibt und auch nach einem Fehler weiterspielt.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-024","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Unterscheide die Spielfähigkeit im weiteren und im engeren Sinne (nach König, 1997).","a":"• Weiterer Sinn: „Drumherum“ (Dietrich) – Spiele in Gang setzen, organisieren, Spielverlauf sichern, bei Störung wiederherstellen\n• Engerer Sinn: Vollzug des Spiels – technische, konditionelle, taktische Fähigkeiten","e":"Weiterer Sinn = alles, damit das Spiel überhaupt stattfinden kann (z. B. gerechte Mannschaften bilden, Regeln einhalten, Ungleichgewichte ausgleichen); engerer Sinn = gut spielen, wenn es läuft (Umgang mit dem Ball, Spielraum mit Partnern und Gegnern bewältigen). Beispiel: Fair Teams wählen und einen Streit über einen Ausball schlichten (weiterer Sinn); einen Doppelpass spielen (engerer Sinn).","quelle":"L18.2","typ":"kern"},{"id":"q1.4-025","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Unterscheide die allgemeine und die spezielle Spielfähigkeit.","a":"Teile der Spielfähigkeit im engeren Sinne:\n• Speziell: nur für ein Sportspiel\n• Allgemein: sportspielübergreifend, Grundlage aller Sportspiele","e":"Allgemein = was in jedem Ballspiel hilft, z. B. Übersicht behalten, Gegner abdecken, Ball im Spiel halten, sich vom Gegner lösen, sich anbieten; speziell = was nur in einer Sportart wie Basketball oder Volleyball gebraucht wird. Beispiel: Freilaufen in eine Lücke hilft im Fußball wie im Handball (allgemein), der Sprungwurf nur im Handball (speziell).","quelle":"L18.2","typ":"kern"},{"id":"q1.4-026","thema":"Q1.4","kapitel":"Grundbegriffe Spielvermittlung","q":"Beschreibe den Aufbau des Modells der Spielfähigkeit (nach Kolb, Abb. 18.2).","a":"• Weiterer Sinn: Spiele in Gang setzen, Spielverlauf sichern, bei Störung wiederherstellen\n• Engerer Sinn: technische, konditionelle, taktische Fähigkeiten\n  – spezielle Spielfähigkeit (einzelnes Sportspiel)\n  – allgemeine Spielfähigkeit (Grundlage aller Sportspiele)","e":"Stell dir einen Baum vor: Stamm = Spielfähigkeit, zwei Äste = weiterer und engerer Sinn, und der Ast „engerer Sinn“ teilt sich nochmal in allgemein und speziell. Beispiel: Die Ballschule zielt auf den Zweig „allgemein“, ein Handballverein auf den Zweig „speziell“.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-027","thema":"Q1.4","kapitel":"Spielgemäßes Konzept","q":"Beschreibe die Grundidee des spielgemäßen Konzepts nach Dietrich et al.","a":"Ganzheitlich: Von Beginn an vereinfachte Spielformen mit Spielidee, über eine „Hauptstraße“ (Spielreihe) zum Zielspiel; bei technischen Defiziten „Nebenstraßen“ aus Übungsformen. Ziel: allgemeine Spielfähigkeit.","e":"Vertreter sind Dietrich, Dürrwächter und Schaller; Grundlage ist eine „pädagogische Theorie der Bewegungsspiele“. Das Konzept prägte die Begriffe Spielidee, Spielform und Spielreihe. Man lernt Fußball, indem man (vereinfachten) Fußball spielt – nicht erst monatelang Pässe übt. Beispiel: Die Klasse spielt Torschussspiele, und wenn das Schießen hakt, gibt es eine kurze Schussübung, danach geht es direkt zurück ins Spiel.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-028","thema":"Q1.4","kapitel":"Spielgemäßes Konzept","q":"Mit welcher traditionellen Vermittlungsforderung bricht das spielgemäße Konzept?","a":"Mit der elementhaft-synthetischen Vermittlung (erst isolierte Techniken, Taktik, Kondition, Regeln, dann Zusammensetzen) – stattdessen ganzheitlich mit vereinfachten Spielformen; Üben nur als Korrektiv.","e":"Früher lernte man Spiele wie ein Puzzle: erst alle Teile einzeln, dann zusammensetzen. Das spielgemäße Konzept zeigt von Anfang an das ganze Bild in einfacher Form; das Üben sportspielspezifischer Fertigkeiten dient nur noch als zusätzliches Korrektiv. Beispiel: Statt Wochen mit Pritschen- und Baggerübungen gibt es sofort ein 1:1 im Volleyball auf kleinem Feld.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-029","thema":"Q1.4","kapitel":"Spielgemäßes Konzept","q":"Nenne die drei zentralen Grundsätze des spielgemäßen Konzepts (Resümee nach Schaller, 2012).","a":"• Spielfähigkeit durch handelnde Auseinandersetzung mit Spielen (Lernen durch Spielen)\n• vereinfachte, steigerbare Formen mit identischer Spielidee\n• Üben und Trainieren als ergänzende Handlungsform im gesamten Lernprozess","e":"Kurz: Spielen, vereinfachen ohne die Spielidee zu verlieren, und Üben als Ergänzung. Die Vereinfachung ist nötig, weil Sportspiele für Lernende zu komplex sind. Beispiel: Basketball beginnt mit 2:2 auf einen Korb (vereinfacht, gleiche Spielidee), zwischendurch wird der Korbleger geübt.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-030","thema":"Q1.4","kapitel":"Spielgemäßes Konzept","q":"Welche Grundsituationen unterscheidet Dietrich im Fußball, und welche methodischen Schritte leiten sich daraus ab?","a":"• A: Torschuss – Torabwehr → Torschussspiele\n• B: Torschussgelegenheit herausspielen – Tor abschirmen → Kampfspiele auf ein Tor\n• C: Angriffsaufbau – Stören des Angriffs → Kampfspiele auf zwei Tore","e":"Dietrich fasst sechs Angriff-Abwehr-Situationen zu drei Grundsituationen zusammen; Fußballspielen lernen heißt, in diesen Situationen angemessen handeln zu können. Die Spielreihe geht vom Tor nach außen: erst schießen, dann sich die Chance erarbeiten, dann das ganze Spiel aufbauen. Beispiel: Zuerst schießen zwei Spieler abwechselnd auf ein Tor mit Torwart, dann 3 gegen 2 auf ein Tor, zum Schluss 4 gegen 4 auf zwei Tore.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-031","thema":"Q1.4","kapitel":"Spielgemäßes Konzept","q":"Welche Rolle spielt das Üben im spielgemäßen Konzept?","a":"Üben ist nur Korrektiv („Nebenstraße“), kein Selbstzweck: Hauptinhalt sind Spielformen; geübt werden nur Fertigkeiten, die die Spieler selbst als Mangel empfinden.","e":"Geübt wird nur, wenn das Spiel es verlangt und die Schüler es selbst merken – also wenn eine Fertigkeit von einem gemeinsamen Gütemaßstab abweicht. Systematisches Üben ist in Spielformen nicht ausreichend möglich, daher braucht es Übungsaufgaben. Die Übungsformen sollen Lehrer und Schüler gemeinsam analytisch entwickeln (Dietrich). Beispiel: Die Klasse stellt fest, dass im Torschussspiel kaum Tore fallen, weil die Schüsse ungenau sind – gemeinsam überlegt man eine Schussübung und kehrt danach ins Spiel zurück.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-032","thema":"Q1.4","kapitel":"Spielgemäßes Konzept","q":"Erläutere die Metapher der Autofahrt für das spielgemäße Konzept.","a":"• Auto = Lernender\n• Hauptstraße = Spielreihe\n• Zielort = Zielspiel\n• Baustelle = Problem in der Spielform\n• Umleitung über Nebenstraßen = Üben, danach zurück auf die Hauptstraße","e":"Man fährt so lange wie möglich auf der Hauptstraße „Spielen“ und nimmt die Nebenstraße „Üben“ nur bei einer Baustelle, z. B. bei technischen Mängeln. Geübt werden dort Fertigkeiten und spezielle Spielsituationen. Beispiel: Im Handball klappt das Fangen nicht – kurze Fangübung (Umleitung), dann weiter mit der nächsten Spielform.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-033","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Beschreibe die Grundidee der integrativen Sportspielvermittlung.","a":"Zuerst sportspielübergreifende, allgemeine Spielfähigkeit (taktische, koordinative, technische Basiskompetenzen), dann über sportspielorientiertes zum sportspielspezifischen Lernen (Roth & Kröger, Heidelberger Ballschule).","e":"Erst das „ABC“ der Ballspiele, dann die einzelnen „Sprachen“ Fußball, Handball, Volleyball. Einzelne Sportspiele werden also nicht isoliert vermittelt; der Weg führt von der allgemeinen Ballschule über sportspielorientiertes zum sportspielspezifischen Lernen. Beispiel: Grundschulkinder spielen viele kleine Ballspiele mit Hand, Fuß und Schläger, bevor sie sich auf eine Sportart spezialisieren.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-034","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Nenne und erläutere die drei Stufen der Anfängerausbildung in der Ballschule nach Kröger & Roth.","a":"Jeweils spielerisch-implizit:\n• Stufe 1: sportspielübergreifend (allgemeine Ballschule, „ABC des Spielens“)\n• Stufe 2: sportspielgerichtet (Rückschlag- und Zielschussspiele)\n• Stufe 3: sportspielspezifisch (drei Sportspielblöcke)","e":"Wie ein Trichter: oben breit (alle Ballspiele), unten schmal (eine Sportart) – das Modell ist hierarchisch vom Allgemeinen zum Spezifischen. Stufe 1 vermittelt taktische, koordinative und technische Basiskompetenzen. In Stufe 3 gibt es Block 1 (Volleyball, Badminton …), Block 2 (Fußball, Hockey …) und Block 3 (Basketball, Handball …). Beispiel: Ein Kind spielt erst allgemeine Fang- und Zielspiele, dann Zielschussspiele, und schließlich Handball und Basketball.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-035","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Wie begründen Kröger und Roth die Notwendigkeit der Ballschule?","a":"Die „Straßenspielkultur“ als natürliche Ballschule ist ausgestorben → Kinder sammeln kaum vielseitige Ballerfahrungen → systematische, kindorientierte Vermittlung nötig.","e":"Früher hat der Hinterhof das Ballgefühl beigebracht – heute muss die Schule das übernehmen. Kinder sollen wieder kreative Spiele lernen und allgemeine koordinative und technische Basiskompetenzen entwickeln, bevor sie sich spezialisieren. Beispiel: Wo Kinder früher stundenlang auf der Straße kickten, Dosen warfen und Völkerball spielten, sitzen sie heute eher vor Bildschirmen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-036","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Nenne die vier Leitsätze der integrativen Sportspielvermittlung.","a":"• Vom Allgemeinen zum Spezifischen\n• Prinzip der Entwicklungsgemäßheit\n• Prinzip der Vielseitigkeit\n• Prinzip der Freudbetontheit","e":"Eselsbrücke „A-E-V-F“: Allgemein vor speziell, Entwicklung beachten, Vielseitig, Freude. Beispiel: Achtjährige machen keine Handball-Kreisläuferübungen, sondern vielfältige, altersgerechte Ballspiele, die Spaß machen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-037","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Welches Ziel verfolgt die allgemeine Ballschule, und welche Basiskompetenzen werden unterschieden?","a":"Ziel: sportspielübergreifende Basiskompetenzen als Fundament für schnelles Lernen in allen Sportspielen:\n• taktisch\n• koordinativ\n• technisch","e":"Die Basiskompetenzen sind das Fundament eines Hauses, auf das später jede Sportart gebaut werden kann. Zielgruppe sind vor allem Kinder im Grundschulalter; inhaltlich orientiert sich die allgemeine Ballschule stark an den Kleinen Spielen (Döbler & Döbler). Beispiel: Wer gelernt hat, Flugbahnen von Bällen einzuschätzen (technisch) und Lücken zu erkennen (taktisch), lernt später Volleyball und Handball schneller.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-038","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Stelle Zugang, Ziele sowie Inhalte und Methoden der allgemeinen Ballschule dar (Tab. 18.1).","a":"• A situationsorientiert: „Spielen lernen“ – Spielen in Taktikbausteinen\n• B fähigkeitsorientiert: Ballkontrolle – Üben von Koordinationsbausteinen\n• C fertigkeitsorientiert: Ballfertigkeiten – Üben von Technikbausteinen","e":"Drei Säulen: A = taktisch spielen, B = koordinativ üben, C = technisch üben – alle sportspielübergreifend. Die Spielbausteine (Inhalte) wurden über Expertenumfragen aus den Basiskompetenzen (Zielen) abgeleitet. Beispiel: A ist ein Parteiballspiel, bei dem man Lücken nutzen muss; B ist Prellen unter Zeitdruck; C ist das Einschätzen der Flugbahn beim Fangen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-039","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Unterscheide Bausteinspiele und Bausteinübungen in der Ballschule.","a":"• Bausteinspiele: Kleine Spiele zur ausgewogenen Vermittlung der Spielbausteine, v. a. Taktik (A); dominieren zu Beginn\n• Bausteinübungen: verbessern Koordination und Technik (B, C); gewinnen später an Bedeutung","e":"Der Ballschulweg führt vom Spielen zum Spielen und Üben. Bausteinspiele sollen nicht zu einem bestimmten Sportspiel hinführen; Bausteinübungen sind weder Teil einer Übungsreihe noch an bestimmte Fertigkeiten gebunden. Beispiel: Bausteinspiel „Parteiball“ (freilaufen, anbieten), Bausteinübung „zwei Bälle gleichzeitig prellen“ (Koordination).","quelle":"L18.2","typ":"kern"},{"id":"q1.4-040","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Welche Bedeutung hat implizites Lernen in der Ballschule?","a":"Alle drei Stufen sind spielerisch-implizit angelegt: Fähigkeiten werden beim freien Spielen ohne bewusste Instruktion erworben („Nebenbeilernen“); explizite Korrekturen treten zurück.","e":"Kinder lernen beim Spielen vieles, ohne dass ihnen jemand erklärt, wie es geht. Deshalb hat nach Kröger & Roth auch nicht angeleitetes, freies Spielen wichtige Lerneffekte. Beispiel: Beim häufigen Fangenspielen mit Ball lernt ein Kind ganz nebenbei, Laufwege des Gegners vorherzusehen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-041","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Beschreibe den Aufbau eines integrativen Lehrgangs im Handball nach Bucher.","a":"• Stufe 1: elementare Bewegungs- und Ballbehandlungsformen\n• Stufe 2: handballspezifische Ballbehandlung und Zusammenspiel (gegen andere, mit Tor)\n• Stufe 3: Handball in einfachen, schulgemäßen Formen","e":"Prinzip: vom Allgemeinen über das Sportspielgerichtete zum Spezifischen. Der Lehrgang wird vom einfachen Ballgefühl bis zum vereinfachten Handballspiel (Grundaufstellung, vereinfachte Regeln) immer handballähnlicher. Beispiel: Stufe 1 Bälle jonglieren, Stufe 2 Parteiball und Zuspiel mit Torwurf, Stufe 3 Handball mit vereinfachten Regeln.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-042","thema":"Q1.4","kapitel":"Integratives Konzept","q":"Wie hängen die Koordinationsbausteine der Ballschule mit dem KAR-Modell zusammen?","a":"Wie im KAR-Modell: einfache Ballfertigkeiten werden unter variierten Druckbedingungen (Zeit-, Präzisions-, Komplexitäts-, Organisations-, Variabilitäts-, Belastungsdruck) geübt → sportspielübergreifende Ballkoordination.","e":"Die Technik bleibt einfach, aber die Bedingungen werden schwerer. Die Koordinationsbausteine (Säule B) orientieren sich an den Druckbedingungen, unter denen Ballspieler handeln müssen; die so erworbene Ballkoordination lässt sich später auf alle Sportspiele übertragen. Beispiel: Ein Kind prellt einen Ball (einfach) und muss dabei schnell laufen (Zeitdruck) und gleichzeitig Farben ansagen, die der Lehrer zeigt (Komplexitätsdruck).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.4-043","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Wodurch ist die Sportspielvermittlung nach dem Ansatz des genetischen Lernens gekennzeichnet?","a":"Ausgangspunkt sind Spielprobleme, für die Lernende und Lehrende gemeinsam Lösungen (oft Regeländerungen) entwickeln (Loibl nach Wagenschein). Prinzipien:\n• genetisch\n• sokratisch\n• exemplarisch","e":"Die Schüler erfinden das Spiel quasi selbst neu, indem sie Probleme lösen. Genetisch heißt schülerorientierte Lösungsfindung am ursprünglichen Problem, sokratisch fragend entwickelte Selbstständigkeit, exemplarisch Arbeit an ausgewählten Beispielen. Loibl übertrug den Ansatz auf Basketball. Beispiel: Die Klasse merkt, dass im Basketball nur die Guten den Ball bekommen, und überlegt gemeinsam, welche Regel das ändert.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-044","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Erläutere das Prinzip des genetischen Lehrens (nach Wagenschein).","a":"Lernende arbeiten am ursprünglichen Problem und entwickeln selbsttätig Lösungen; Wissen wird nicht vorgegeben, sondern im Lernprozess neu „erzeugt“ (griech. gignomai = entstehen).","e":"Man lernt eine Sache, indem man sie so entdeckt, als würde man sie zum ersten Mal erfinden – man vollzieht ihre Entstehung nach. Beispiel: Statt die Dribbelregel einfach zu erklären, erleben die Schüler, warum ein Spiel ohne Regel für das Laufen mit Ball problematisch oder hilfreich ist.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-045","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Erläutere das Prinzip des sokratischen Lehrens.","a":"Selbsttätigkeit fordern, indem Fragen an die Lernenden zurückgegeben werden; der Lehrer gibt keine Lösungen vor, sondern lenkt indirekt durch Fragen.","e":"Der Lehrer ist Fragensteller, nicht Antwortgeber. Benannt ist das Prinzip nach Sokrates, der durch Fragen zur Erkenntnis führte („Hebammenkunst“). Beispiel: Statt „Ihr müsst mehr passen!“ fragt er: „Was bedeutet es eigentlich, den Ball zu haben? Wer hatte heute kaum Ballkontakte und warum?“","quelle":"L18.2","typ":"kern"},{"id":"q1.4-046","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Erläutere das Prinzip des exemplarischen Lehrens.","a":"Genetisch-sokratisches Vorgehen nur an ausgewählten Beispielen, an denen zentrale Erkenntnisse prägnant gewonnen werden; darauf baut darlegender Unterricht auf.","e":"Nicht alles wird entdeckend gelernt, sondern nur ausgewählte Schlüsselprobleme – genetisches Lernen ist zu zeitaufwendig für alle Inhalte. Beispiel: Am Problem „Wie bekommen alle den Ball?“ verstehen Schüler das Grundprinzip des Freilaufens; weitere Taktiken kann der Lehrer danach direkt erklären.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-047","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Unterscheide unverzichtbare Grundregeln und selbstverständliche Regeln im Basketball (Tab. 18.2).","a":"• Unverzichtbare Grundregeln: Aus, Foul, Schrittfehler, Doppeldribbling, Sprungball\n• Selbstverständliche Regeln: zwei Mannschaften, je fünf Feldspieler, zwei Körbe, Spiel mit der Hand","e":"Selbstverständliche Regeln machen Basketball zu Basketball und sichern die Spielidee; Grundregeln sind die „Feinregeln“, die im genetischen Lehrgang problematisiert und ggf. verändert werden. Zu Beginn wird nach beiden gespielt. Beispiel: Ohne Körbe wäre es kein Basketball mehr, ohne Doppeldribbel-Regel aber schon noch.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-048","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Beschreibe den Ablauf eines genetischen Lehrgangs zur Einführung des Basketballspiels nach Loibl.","a":"• Einstieg (Spielbesuch/Video)\n• Spielen nach Grund- und selbstverständlichen Regeln\n• Problematisierung durch Fragen\n• Lösung „Üben“ hilft kurzfristig kaum\n• gemeinsame Regeländerungen\n• Dribbelregel entfällt, Laufen mit Ball erlaubt","e":"Der Lehrgang ist eine Kette aus Problem, gemeinsamer Lösungssuche und Ausprobieren. Fragen wie „Hat das Spiel Spaß gemacht? Was bedeutet es, den Ball zu haben?“ zeigen: Viele haben kaum Spielanteile, weil Wurf und Dribbling ungeübt sind. Mögliche Regeländerungen: Spiel ohne Dribbling, jeder muss vor einem Korbwurf den Ball gehabt haben, großzügige Schrittregel. Beispiel: Erst merkt die Klasse, dass Üben allein nicht schnell hilft, und kommt dann selbst darauf, das Laufen mit dem Ball zu erlauben.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-049","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Welche Effekte hat das Weglassen der Dribbelregel im genetischen Basketball-Lehrgang (nach Loibl)?","a":"• Ungeübte beteiligen sich aktiv\n• Aufmerksamkeit aufs Spielgeschehen statt auf den Ball\n• Lösung komplexer Situationen per Korbleger\n• alle können Mitspieler freispielen\n• basketballähnliche, dynamische Spielstruktur","e":"Wer nicht mehr aufs Prellen achten muss, kann auf das Spiel schauen. Im 1:1 können alle Spieler Mitspieler freispielen; die Angreifer dominieren als perfekte „Dribbler“, die Verteidiger müssen sich anstrengen und gegenseitig helfen. Beispiel: Ein schwächerer Schüler läuft mit dem Ball zum Korb und erzielt per Korbleger seinen ersten Treffer – die Verteidiger müssen lernen, sich gegenseitig auszuhelfen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-050","thema":"Q1.4","kapitel":"Genetisches Konzept","q":"Beschreibe die Struktur des genetischen Lehrgangs (nach Loibl, Abb. 18.6).","a":"Kreislauf:\n• neue Spielsituation\n• Problem entsteht\n• Dialog: Lösungssuche\n• Erprobung\n• Lösung → neue Spielsituation (sonst neue Lösungssuche)","e":"Der Lehrgang dreht sich wie ein Rad: Spielen, Problem entdecken, Lösung finden, ausprobieren, weiterspielen. Im günstigsten Fall wird das Problem gelöst und es folgt freudvolles Üben taktischer Fähigkeiten und vereinfachter Fertigkeiten in komplexen Spielsituationen. Beispiel: Die Verteidiger kommen gegen Läufer mit Ball nicht an – Problem; Lösung: sich gegenseitig helfen; Erprobung im nächsten Spiel.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-051","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"Beschreibe die Grundidee des Taktik-Spiel-Konzepts (Tactical Games Approach).","a":"Ausgangspunkt ist eine Spielform mit taktischem Problem: Schüler erarbeiten erst, WAS taktisch zu tun ist, dann WIE es spielnah geübt wird. Ziel: Spielverständnis und Transfer innerhalb einer Spielkategorie.","e":"Erst verstehen, was im Spiel nötig ist (Taktik), dann lernen, wie man es technisch umsetzt. Vertreter sind Mitchell, Oslin und Griffin (USA, 2006); das Konzept entwickelt den britischen TGfU-Ansatz weiter. Beispiel: Im 3:3 ohne Tore merkt die Klasse, dass sie den Ball halten muss (WAS) – danach übt sie sicheres Passen und Annehmen (WIE).","quelle":"L18.2","typ":"kern"},{"id":"q1.4-052","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"In welche vier Kategorien teilen Mitchell, Oslin und Griffin die Sportspiele ein?","a":"• Invasionsspiele (z. B. Fußball, Handball)\n• Feld-/Schlagspiele (z. B. Baseball, Brennball)\n• Netz-/Wandspiele (z. B. Volleyball, Tennis)\n• Zielspiele (z. B. Bowling, Curling)","e":"Eselsbrücke „I-F-N-Z“: Eindringen, Schlagen und Laufen, übers Netz, aufs Ziel. Spiele derselben Kategorie haben ähnliche taktische Probleme, das erleichtert den Transfer. Zielspiele haben keinen Invasionsanspruch, Netz-/Wandspiele sind Rückschlagspiele. Beispiel: Wer im Handball gelernt hat, durch Freilaufen Überzahl zu schaffen, kann das auf Basketball übertragen, weil beides Invasionsspiele sind.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-053","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"Beurteile, inwiefern die vier Sportspielkategorien des Taktik-Spiel-Konzepts den Gedanken einer Spielidee verfolgen, und gib eine Spielidee von Baseball an.","a":"• Kategorien beruhen auf gemeinsamer Grundstruktur (Angriff-Abwehr-Verhältnis) → Spielidee auf Ebene der Spielfamilie\n• Baseball: Schlagpartei schlägt den Ball, Läufer umrunden die Bases für Punkte; Feldpartei will Läufer durch Fangen und Zurückspielen aus machen","e":"Die Kategorien sind „Spielideen-Familien“: Invasionsspiele = eindringen und Ziel treffen; Netz-/Wandspiele = Ball so spielen, dass er nicht regelgerecht zurückkommt; Feld-/Schlagspiele = schlagen und Läufe erzielen; Zielspiele = präziser treffen ohne direkte Behinderung. Beispiel: Brennball und Baseball sehen verschieden aus, haben aber dieselbe Grundidee: schlagen/werfen, laufen, Punkte machen – und die Gegner wollen den Läufer stoppen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-054","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"Beschreibe den Ablauf einer Unterrichtseinheit nach dem Taktik-Spiel-Konzept.","a":"Spiel – Reflexion – Üben – Spiel:\n• Spielform mit taktischem Problem\n• Reflexion (WAS? WIE?)\n• spielnahe Fertigkeitsübung\n• abschließende Spielform","e":"Das Prinzip ist ein Sandwich: Spiel – Üben – Spiel, mit Nachdenken dazwischen. In der Reflexion geht es um Zeit, Raum und Risiko; beim Üben werden Technik und Individualtaktik gleichzeitig im taktischen Kontext gelernt; die Schlussspielform ist die erste oder eine Variante davon. Beispiel Fußball: 3:3 ohne Tore (Ziel: fünf Pässe in Folge), Frage „Wie bleibt dein Team in Ballbesitz?“, paarweise Passübung mit der Innenseite, dann 3:3 auf zwei Tore.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-055","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"Welche drei Kategorien sollen die Fragestellungen in der Reflexionsphase des Taktik-Spiel-Konzepts abdecken?","a":"• Zeit: Wann ist der beste Moment, um …? (z. B. abzuspielen, sich freizulaufen)\n• Raum: Wo ist oder wo kann …? (z. B. freier Raum, Anspielposition)\n• Risiko: Welche Entscheidung ist die sicherste und welche die riskanteste?","e":"Drei Fragen an jede Spielsituation: wann, wo, wie riskant? Beispiel Basketball: „Wann ist der beste Moment für den Pass zum Center? Wo kann sich der Flügelspieler anbieten? Ist der lange Pass zu riskant?“","quelle":"L18.2","typ":"kern"},{"id":"q1.4-056","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"Wodurch definieren sich die Niveaustufen im Lehrgang des Taktik-Spiel-Konzepts, und wie erfolgt die Lösungsfindung?","a":"Jede Niveaustufe definiert sich durch taktisches Problem, nötige „Bewegung ohne Ball“ und nötige „Fertigkeiten mit Ball“. Lösungsfindung induktiv: Lernende entdecken Lösungen selbst.","e":"Jede Stufe hat ein eigenes taktisches Rätsel, das man mit Laufwegen und Balltechnik löst. Wie beim genetischen Lernen setzen sich die Lernenden erst spielerisch mit dem Problem auseinander; erst danach werden die Lösungen bewusst gemacht. Beispiel: Stufe „Ball halten“ verlangt Anbieten (ohne Ball) und sicheres Passen (mit Ball); eine höhere Stufe „Raum zum Angriff schaffen“ verlangt Freilaufen in die Tiefe und Pässe in den Lauf.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-057","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"Stelle dar, wie das Taktik-Spiel-Konzept zur Verbesserung der Spielfähigkeit beitragen kann.","a":"• kognitiv: Spielverständnis und Entscheidungsfähigkeit (Zeit, Raum, Risiko)\n• motorisch: Technik im taktischen Kontext\n• Transfer auf Spiele derselben Kategorie\n• sozial/emotional: Lösungssuche im Team, Motivation durch frühes Spielen","e":"Spielfähigkeit umfasst spielmotorische, kognitive, soziale und emotional-affektive Kompetenzen – das Konzept spricht alle an. Weil Techniken spielnah geübt werden, sind sie im Spiel besser anwendbar. Das Konzept macht Spieler „schlau“ und nicht nur technisch sauber. Beispiel: Ein Schüler weiß nach der Einheit nicht nur, wie man mit der Innenseite passt, sondern auch, wann und wohin er passen sollte.","quelle":"L18.4","typ":"kern"},{"id":"q1.4-058","thema":"Q1.4","kapitel":"Taktik-Spiel-Konzept","q":"Beschreibe das Modell „Teaching Games for Understanding“ (TGfU) nach Bunker & Thorpe.","a":"Bunker & Thorpe (1982): Taktik vor Technik. Kreislauf:\n• Spiel\n• Spielverständnis\n• taktisches Bewusstsein\n• Entscheidungen treffen\n• technische Ausführung\n• Leistung","e":"TGfU entstand aus Kritik am technikorientierten Unterricht: Schüler beherrschen Techniken, verstehen aber das Spiel nicht und wenden sie kaum an. Es ist die Grundlage des Tactical Games Approach und dreht den klassischen Unterricht um: erst das Spiel verstehen, dann gezielt die nötige Technik lernen. Beispiel Badminton: Erst erkennen, dass man den Gegner nach hinten treiben muss, dann den Clear üben.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.4-059","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Welches Ziel verfolgt die vielseitig orientierte Sportspielvermittlung?","a":"• möglichst viele Kinder für Sport begeistern\n• vielseitig ausbilden\n• begründete Empfehlung für eine Sportspielart (Leistung oder Freizeit)","e":"Erst breit begeistern, dann die passende Sportart finden. Die Sportspielvermittlung wird dabei in ein vielseitiges Sportkonzept eingeordnet; die enge Bindung anderer Konzepte an bestimmte Zielgruppen soll überwunden werden. Beispiel: Ein Kind probiert in der Schule Handballrugby, Basketball und Volleyball aus und erfährt so, dass es im Volleyball besonders begabt ist.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-060","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Welches Problem der meisten Vermittlungskonzepte greift die vielseitig orientierte Sportspielvermittlung auf?","a":"Die enge Bindung an bestimmte Zielgruppen und Zielperspektiven; Lösung: Spielformen, die per Regelveränderung an alle Leistungsniveaus und Ziele anpassbar sind.","e":"Ein Konzept passt oft nur für eine Gruppe: Hagedorn et al. stellen etwa das Wettkämpfen mit „richtigen“ Techniken ins Zentrum (leistungsorientiert), Loibl wählt eine erlebnisorientierte Annäherung. Beispiel: Ein rein erlebnisorientierter Basketball-Lehrgang langweilt ehrgeizige Vereinsspieler, ein rein technikorientierter frustriert Anfänger.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-061","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Welche Kernfragen muss ein Vermittlungskonzept nach Remmert positiv beantworten, um einer universellen Anfängerausbildung zu genügen?","a":"• Wird früh und häufig gespielt?\n• Ist die Spielidee des Zielspiels von Beginn an erlebbar?\n• Wann/wie werden Technik und Taktik einbezogen?\n• Gibt es Anreize für Leistungswillige (Wettkampf)?\n• Passt es zu unterschiedlichen Zielsetzungen?","e":"Die fünf Fragen sind eine Checkliste, mit der man jedes Konzept prüfen kann. Bei der dritten Frage geht es um die unverzichtbaren technischen und taktischen Elemente – wann, wie und in welchem Ausmaß sie einfließen. Beispiel: Die Ballschule erfüllt „früh spielen“, aber die Spielidee eines bestimmten Zielspiels ist zu Beginn noch nicht erlebbar.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-062","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Welche Eigenschaften besitzen vielseitig orientierte Spielformen?","a":"• Spielidee großer Sportspiele erlebbar\n• fordern viele komplexe Sportspielelemente\n• per Regeländerung ohne Motivationsverlust an Niveau und Ziele anpassbar\n• in allen Konzepten und Altersstufen einsetzbar","e":"Eine vielseitig orientierte Spielform ist wie ein Baukasten-Spiel: gleiche Idee, aber per Regel für jede Gruppe passend einstellbar. Sie lässt sich im spielgemäßen, integrativen, genetischen und Taktik-Spiel-Konzept nutzen und bleibt dabei intensiv und freudvoll. Beispiel: Handballrugby funktioniert in Klasse 6 wie im Leistungskurs – man verändert nur die Zahl der Vorfeld- und Rückfeldspieler.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-063","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Welche Hauptziele werden mit dem Handballrugbyspiel verfolgt?","a":"• Spielidee des Handballs erleben\n• handballspezifische Elemente situativ anwenden\n• faire Körperbetonung und Härte erfahren\n• spielspezifische Ausdauer und Schnelligkeit verbessern\n• Spielfähigkeit im engeren und weiteren Sinne","e":"Handballrugby ist Handball mit vereinfachten Regeln und viel Körperkontakt. Beispiel: Weil der Ballbesitzer geklammert werden darf, lernen Schüler, sich im Zweikampf zu behaupten – wie später im echten Handball.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-064","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Stelle die Spielidee des Handballspiels dar und erläutere anhand des Handballrugbyspiels drei Vereinfachungsstrategien mit ihrer Zielsetzung.","a":"Spielidee: Ball mit der Hand ins gegnerische Tor werfen und Gegentore verhindern.\n• Handlung: Laufen mit Ball → weniger Technikanforderung, Schwächere beteiligt\n• Raum: kein Aus → Spielfluss, Intensität\n• Raum/Personal: Vor- und Rückfeld, Wechsel nach Tor → klare Aufgaben, Rotation","e":"Jede Vereinfachung dreht an einer Regelkategorie nach Digel und hat ein Ziel. Im Vorfeld stehen 3 Angreifer, im Rückfeld Torwart und 5 Feldspieler; Tore nur aus dem Vorfeld, die Überzahl der Abwehr fordert Durchsetzungsvermögen. Weitere Strategien: Klammern des Ballbesitzers erlaubt (faire Körperbetonung, Fouls → 7 m) und ein zweiter Ball bei Gerangel (Inventar). Beispiel: Ohne Aus muss kein Einwurf ausgeführt werden – das Spiel läuft weiter, und alle bleiben in Bewegung.","quelle":"L18.4","typ":"kern"},{"id":"q1.4-065","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Begründe, warum Handballrugby gut geeignet ist, um Anfänger auf das Sportspiel Handball vorzubereiten.","a":"• Spielidee von Beginn an erlebbar\n• Laufen mit Ball senkt technische Hürden, Schwächere beteiligt\n• Spielfluss und hohe Intensität\n• faire Körperbetonung wird gelernt\n• per Regeln an Leistungsniveau anpassbar","e":"Handballrugby ist „echtes Handballgefühl light“ und erfüllt damit Remmerts Kriterien und die Merkmale einer vielseitig orientierten Spielform. Prellen und Schrittregel entfallen; Spielen ohne Aus und ggf. mit zweitem Ball sichern den Spielfluss. Torwurf, Freilaufen, Zusammenspiel und Abwehr werden situativ angewendet. Anpassen kann man z. B. die Zahl der Vorfeldspieler, Aufbauspieler für Schwächere oder koedukative Varianten. Beispiel: Eine Schülerin, die noch nicht prellen kann, läuft mit dem Ball durch die Abwehr und wirft aufs Tor.","quelle":"L18.4","typ":"kern"},{"id":"q1.4-066","thema":"Q1.4","kapitel":"Vielseitige Spielvermittlung","q":"Was ist FooBaSKILL, und warum eignet es sich für eine vielseitig orientierte Sportspielvermittlung?","a":"Schweizer Crossover-Spiel: eine Feldhälfte Fußball, die andere Basketball. Eignung: Spielideen zweier Großer Spiele erlebbar, Hand und Fuß gefordert, übergreifende Spielfähigkeit, Begabungen werden erkennbar.","e":"Ein Spiel, zwei Sportarten: Beim Überqueren der Mittellinie ändert sich das Zielspiel. Gespielt wird mit einem Spezialball mit glatter und griffiger Oberfläche, etwa so groß und schwer wie ein 5er-Basketball. Beispiel: Ein Spieler dribbelt den Ball mit dem Fuß bis zur Mittellinie, nimmt ihn dann in die Hand und spielt Basketball weiter.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-067","thema":"Q1.4","kapitel":"Grundsätze der Spielvermittlung","q":"Was kann als kleinster gemeinsamer Nenner aller Konzepte der Sportspielvermittlung herausgestellt werden?","a":"„Spielen und Üben!“ – aber „Spielen vor Üben!“ (Roth, 2005); die Spielidee bleibt bei allen Vereinfachungen erhalten.","e":"Egal welches Konzept: Spielen und Üben sind beide nötig, aber erst wird gespielt, geübt wird ergänzend. Beispiel: Selbst im Taktik-Spiel-Konzept steht am Anfang eine Spielform, die Übung kommt erst danach.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-068","thema":"Q1.4","kapitel":"Grundsätze der Spielvermittlung","q":"Welche allgemeinen Grundsätze gelten für alle Spielvermittlungskonzepte (nach Söll)?","a":"Bei Erhalt der Spielidee:\n• zu Beginn möglichst wenige Spieler\n• optimale Spielerzahl je Feldgröße nicht überschreiten\n• Spielanteile gleichmäßig verteilen\n• wenn üben, dann spielnah und intensiv","e":"Wenige Spieler, passendes Feld, alle kommen dran, und Üben nah am Spiel – alles auf Grundlage von Regelvereinfachungen, die die unverzichtbaren Regeln bewahren. Beispiel: Statt 11 gegen 11 auf dem Großfeld spielt die Klasse 3 gegen 3 auf vier Kleinfeldern – jeder hat viel mehr Ballkontakte.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-069","thema":"Q1.4","kapitel":"Grundsätze der Spielvermittlung","q":"Durch welche Maßnahmen kann eine höhere Schüleraktivität beim Spielen und Üben erreicht werden?","a":"• neutrale Spieler\n• Verteidigeraufgaben erschweren\n• Trefferwahrscheinlichkeit erhöhen\n• Überzahl schaffen\n• Kontinuumübungen\n• ausreichend Wiederholungen\n• Technik vereinfachen\n• Taktik vereinfachen","e":"Mehr Aktivität heißt: mehr Erfolg für Angreifer, weniger Warten. Neutrale Spieler können im Rückraum, an den Seiten oder in der Mitte stehen; Kontinuumübungen sind sich wiederholende Endlosübungen. Beispiel: Handball nach Basketballregeln (Verteidiger dürfen nicht klammern), Wurf vom Kasten oder größere Tore, im Volleyball Kleinfeld 2 mit 2 statt 6 mit 6.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-070","thema":"Q1.4","kapitel":"Grundsätze der Spielvermittlung","q":"Wie kann man mithilfe des KAR-Modells eine Spielform so gestalten, dass leistungsstarke und leistungsschwache Schüler eine Technik spielnah üben können?","a":"• Technik im Spiel nach Druckbedingungen analysieren (Präzision, Zeit, Komplexität, Situation, Belastung)\n• Druck als „Regler“ differenzieren: für Schwächere senken, für Stärkere erhöhen\n• Spielform mit Spielidee und vielen Wiederholungen","e":"Die Technik bleibt gleich, nur die Schwierigkeit wird je Schüler „eingestellt“. Beim Handballsprungwurf im 1:1 heißt das z. B.: genau am Blocker vorbei treffen (Präzision), schnell abspringen (Zeit), Anlauf, Absprung und Wurf koppeln (Komplexität), auf den Gegner reagieren (Situation). Senken lässt sich der Druck durch mehr Abstand, Überzahl oder größeres Ziel, erhöhen durch aktiven Blocker oder kleineres Ziel. Beispiel: Bei „Handball über die Schnur“ erzwingt die Zauberschnur den Sprungwurf; Starke spielen gegen aktive Blocker, Schwache bekommen mehr Abstand.","quelle":"L18.4","typ":"kern"},{"id":"q1.4-071","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Nenne Vor- und Nachteile des spielgemäßen Konzepts (nach Söll).","a":"Vorteile:\n• Motivierend, da zielspielnah\n• Vermittelt eine spezielle und eine allgemeine Spielfähigkeit\nNachteile:\n• Übertragbarkeit des Gelernten in das komplexe Zielspiel ist fraglich\n• Üben wird als „lästiges Übel“ gesehen","e":"Spielen macht Spaß, aber ob die vereinfachten Spielformen wirklich zum großen Spiel führen, ist offen. Beispiel: Wer gut im 2:2 auf ein Tor ist, kommt nicht automatisch im 11 gegen 11 zurecht; und die eingeschobenen Übungen wirken auf Schüler oft wie eine Strafe.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-072","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Nenne Vor- und Nachteile des integrativen Konzepts (Ballschule).","a":"Vorteile:\n• Keine frühzeitige Spezialisierung\n• Vermitteln von Spielanlässen\n• Schulen sportspielübergreifender Skills\nNachteile:\n• Kinder wollen direkt „richtig“ spielen\n• Zeitaufwendig\n• Transfer auf das Zielspiel fraglich","e":"Das breite Fundament ist sinnvoll, aber es dauert und die Kinder wollen lieber „echten“ Fußball. Beispiel: Ein Neunjähriger fragt nach zwei Wochen Ballschule: „Wann spielen wir endlich Fußball?“","quelle":"L18.2","typ":"kern"},{"id":"q1.4-073","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Nenne Vor- und Nachteile des genetischen Konzepts.","a":"Vorteile:\n• Das Kind steht im Zentrum des Lernens\n• Einbinden Leistungsschwächerer\nNachteile:\n• Motivationsverlust Leistungsstärkerer\n• Zeitaufwendig","e":"Schwächere profitieren von den selbst gefundenen Regeländerungen, Starke langweilen sich eventuell. Beispiel: Ein Vereinsbasketballer findet es frustrierend, wenn plötzlich ohne Dribbelregel gespielt und lange über Regeln diskutiert wird.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-074","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Nenne Vor- und Nachteile des Taktik-Spiel-Konzepts.","a":"Vorteile:\n• Schülerorientiert, da induktiv vermittelt\n• Motivierend durch frühzeitiges Spielen\n• Spielnahes Üben möglich\nNachteile:\n• Üben in spielnahen Situationen wird als „lästiges Übel“ gesehen\n• Rücktransfer in das Zielspiel fraglich","e":"Die Schüler verstehen das Spiel besser, aber ob das in Spielformen Gelernte im echten Spiel ankommt, ist nicht sicher. Beispiel: Fünf Pässe in Folge im 3:3 gelingen, im großen Spiel unter Gegnerdruck dann aber nicht.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-075","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Nenne Vor- und Nachteile der vielseitig orientierten Sportspielvermittlung.","a":"Vorteile:\n• Motivierend durch frühzeitiges Spielen\n• Sehr schülerorientiert\n• Kinder erkennen ihre Begabungen\nNachteile:\n• Hohe Qualifikation der Lehrenden notwendig, da zunächst eine breite Sportausbildung angestrebt wird","e":"Gut für die Kinder, anspruchsvoll für die Lehrkraft, die viele Sportarten beherrschen muss. Beispiel: Wer Handballrugby, FooBaSKILL und Volleyballformen anleiten will, braucht breites Fachwissen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-076","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Welche Nachteile haben die Vermittlungskonzepte gemeinsam, wenn sie in Reinform angewendet werden?","a":"• Transfer ins Zielspiel fraglich (spielgemäß, integrativ, Taktik-Spiel)\n• Üben als „lästiges Übel“ (spielgemäß, Taktik-Spiel)\n• zeitaufwendig (integrativ, genetisch)\n• Motivationsprobleme (integrativ, genetisch)","e":"Kein Konzept ist perfekt, deshalb mischen gute Lehrkräfte sie und passen sie an Lerngruppe und Ziel an. Bei der Ballschule wollen Kinder direkt „richtig“ spielen, beim genetischen Konzept verlieren Leistungsstärkere die Motivation. Beispiel: Eine Lehrerin startet genetisch mit Regelfindung, nutzt dann Taktik-Spiel-Einheiten und Spielreihen aus dem spielgemäßen Konzept.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-077","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Vergleiche das spielgemäße Konzept mit dem integrativen Konzept.","a":"Gemeinsam: Spielen vor Üben, Ziel Spielfähigkeit, vereinfachte Spielformen.\nUnterschiede:\n• Start: Spielidee des Zielspiels vs. übergreifende Basiskompetenzen\n• Weg: Spielreihe vs. drei Stufen allgemein → spezifisch\n• Lernen: eher bewusst vs. implizit","e":"Spielgemäß fährt direkt auf ein bestimmtes Ziel zu, integrativ baut erst eine breite Straße und biegt später ab. Die Ballschule richtet sich v. a. an Grundschulkinder, das spielgemäße Konzept an die Einführung eines bestimmten Spiels. Spielgemäß ist motivierender (zielspielnah), integrativ vermeidet frühe Spezialisierung, ist aber zeitaufwendig. Beispiel: Spielgemäß beginnt man Fußball mit Torschussspielen, integrativ spielt man zunächst allgemeine Zielschussspiele mit Hand und Fuß.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-078","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Vergleiche das genetische Konzept mit dem Taktik-Spiel-Konzept.","a":"Gemeinsam: induktiv, schülerorientiert, Problem in Spielsituation, Reflexion, frühes Spielen.\nUnterschiede:\n• Problem: Spielproblem, gelöst durch Regeländerung vs. gezieltes taktisches Problem\n• Struktur: offen, sokratisch vs. fest (Spiel – Reflexion – Üben – Spiel)","e":"Beide lassen Schüler denken, aber das genetische Konzept ist offener, das Taktik-Spiel-Konzept planmäßiger. Genetisch wird v. a. im Spiel mit veränderten Regeln geübt, im Taktik-Spiel-Konzept in spielnahen Fertigkeitsübungen; Letzteres zielt auf Transfer innerhalb der Spielkategorie. Nachteile: genetisch zeitaufwendig und demotivierend für Starke; Taktik-Spiel: Rücktransfer fraglich, Üben wirkt lästig. Beispiel: Genetisch erfinden Schüler eine Regel gegen Ballmonopole; im Taktik-Spiel-Konzept stellt der Lehrer ein 3:3 mit dem Problem „Ball halten“.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-079","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Vergleiche das spielgemäße mit dem genetischen Konzept.","a":"Gemeinsam: ganzheitlich, von Beginn an Spielidee des Zielspiels, gegen elementhaft-synthetisches Vorgehen.\nUnterschiede:\n• Steuerung: lehrergesteuert/deduktiv vs. schülerorientiert/induktiv\n• Vereinfachung: geplante Spielreihe vs. gemeinsam erarbeitete Regeländerungen","e":"Beide wollen zum Zielspiel, aber beim spielgemäßen Konzept hat der Lehrer die Landkarte, beim genetischen suchen die Schüler den Weg (sokratisch). Geübt wird spielgemäß über „Nebenstraßen“, genetisch in komplexen Spielsituationen. Das genetische Konzept ist deutlich zeitaufwendiger. Beispiel Basketball: Spielgemäß gibt der Lehrer 2:2 ohne Dribbling vor; genetisch kommen die Schüler selbst auf die Idee, die Dribbelregel abzuschaffen.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-080","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Vergleiche das integrative Konzept mit dem Taktik-Spiel-Konzept hinsichtlich Transfer und Spezialisierung.","a":"• Integrativ: Transfer von breiter, übergreifender Basis auf alle Spiele; Spezialisierung erst in Stufe 3; implizit\n• Taktik-Spiel: Spielverständnis in einer Sportart → Transfer innerhalb der Kategorie; explizit durch Reflexion","e":"Gemeinsam ist beiden die Annahme sportspielübergreifender taktischer Gemeinsamkeiten. Die Ballschule baut zuerst ein breites Fundament (eher Grundschulalter), das Taktik-Spiel-Konzept nimmt eine Sportart als „Lehrbeispiel“ für ihre ganze Familie (eher ältere Lernende, die reflektieren können). Beispiel: Die Ballschule spielt allgemeine Lückenspiele; das Taktik-Spiel-Konzept lehrt Freilaufen im Basketball und überträgt es auf Handball.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-081","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Ordne die Vermittlungskonzepte nach den Kriterien Lehrweg (deduktiv/induktiv), Ausgangspunkt und Lernende im Mittelpunkt ein.","a":"• Spielgemäß: deduktiv; Spielidee des Zielspiels\n• Integrativ: Angebote vorgegeben, implizites Lernen; übergreifende Basiskompetenzen\n• Genetisch: induktiv, stark schülerorientiert; Spielprobleme\n• Taktik-Spiel: induktiv, strukturiert; taktisches Problem\n• Vielseitig: übergreifend; vielseitige Spielformen","e":"Eine Übersicht hilft, die Konzepte im Abitur schnell gegenüberzustellen. Das spielgemäße Konzept plant eine Spielreihe und zielt auf allgemeine Spielfähigkeit; das integrative geht vom Allgemeinen zum Spezifischen; das Taktik-Spiel-Konzept will Transfer in die Spielkategorie; das vielseitige will Begeisterung und Begabungserkennung. Beispiel: Wird gefragt „Welches Konzept ist am stärksten schülerorientiert?“, lautet die Antwort genetisch (und vielseitig orientiert), weil Schüler dort Lösungen selbst erarbeiten.","quelle":"L18.2","typ":"kern"},{"id":"q1.4-082","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Welches Vermittlungskonzept eignet sich für welche Lerngruppe bzw. Zielsetzung? Begründe.","a":"• Grundschulkinder: integrativ (vielseitig, keine Frühspezialisierung)\n• heterogene Anfänger: genetisch (bindet Schwächere ein)\n• Ältere, Spielverständnis: Taktik-Spiel\n• bestimmtes Zielspiel: spielgemäß\n• Begeisterung/Begabung: vielseitig orientiert","e":"Das „beste“ Konzept gibt es nicht – es hängt von Gruppe und Ziel ab, in der Praxis werden Konzepte kombiniert. Gemeinsamer Grundsatz: Spielen und Üben, aber Spielen vor Üben. Das Taktik-Spiel-Konzept setzt auf Reflexion und Transfer, das spielgemäße auf Motivation durch Zielspielnähe und eine systematische Spielreihe. Beispiel: In einer 5. Klasse mit vielen Nichtvereinsspielern ist ein genetischer Basketball-Einstieg sinnvoll, im Sport-LK eher ein Taktik-Spiel-Konzept mit Reflexion.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.4-083","thema":"Q1.4","kapitel":"Konzeptvergleich","q":"Beurteile die Ballschule anhand der Kernfragen von Remmert.","a":"• früh spielen: ja\n• Spielidee des Zielspiels früh erlebbar: eher nein\n• Technik/Taktik: ja, aber allgemein\n• Anreize für Leistungswillige: bedingt\n• verschiedene Ziele: teilweise\nFazit: wertvolle Basis, allein ergänzungsbedürftig","e":"Mit Remmerts Checkliste lässt sich jedes Konzept bewerten. In der Ballschule dominieren Bausteinspiele, spezifische Elemente kommen erst in Stufe 3; die allgemeine Ballschule führt bewusst nicht zu einem bestimmten Zielspiel. Sie schafft eine breite Grundlage für Freizeit- und Leistungssport, ist aber zeitaufwendig, und Kinder wollen direkt „richtig“ spielen. Beispiel: Ein Kind in der Ballschule spielt viel, erlebt aber noch kein „richtiges“ Handball – deshalb erfüllt die Ballschule nicht alle Kriterien.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.4-084","thema":"Q1.4","kapitel":"Methoden der Spielvermittlung","q":"Unterscheide Ganzheitsmethode und Teilmethode bei der Vermittlung von Sportspielen.","a":"• Ganzheitsmethode: Spiel von Beginn an als Ganzes (ggf. vereinfacht)\n• Teilmethode: Zerlegen in Elemente, isoliert üben, dann zusammensetzen\n• Ganz-Teil-Ganz: spielen, Teile üben, wieder spielen","e":"Ganzheitlich = gleich das Spiel, teilweise = erst die Bausteine. Die Ganzheitsmethode erhält Sinnzusammenhang, Motivation und Spielverständnis, ist aber komplex, Fehler sind schwer zu korrigieren. Die Teilmethode erlaubt gezieltes Üben, hat aber keinen Spielbezug, ein Transferproblem und wenig Motivation. Die Ganz-Teil-Ganz-Methode entspricht weitgehend den modernen Konzepten. Beispiel: Ganzheitlich spielt man sofort 3 gegen 3 Basketball; teilmethodisch übt man erst Dribbeln, Passen und Korbleger einzeln und spielt erst nach Wochen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.4-085","thema":"Q1.4","kapitel":"Methoden der Spielvermittlung","q":"Unterscheide Spielreihe und Übungsreihe als methodische Wege in der Sportspielvermittlung.","a":"• Übungsreihe: Übungen bauen eine Technik schrittweise auf, Spiel am Ende (traditionell, fertigkeitsorientiert)\n• Spielreihe: Spielformen mit gleicher Spielidee und steigender Komplexität, Spiel von Anfang an (spielgemäß)","e":"Die Übungsreihe ist eine Leiter aus Übungen (Technik zuerst), die Spielreihe eine Leiter aus Spielen (Spiel zuerst, Übungen nur ergänzend). Beispiel Volleyball: Übungsreihe = Pritschen gegen die Wand, zu zweit, über das Netz; Spielreihe = 1:1, 2:2, 3:3 auf Kleinfeldern.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.4-086","thema":"Q1.4","kapitel":"Methoden der Spielvermittlung","q":"Unterscheide deduktives und induktives Vorgehen in der Sportspielvermittlung und ordne die Konzepte zu.","a":"• Deduktiv: Lehrer gibt Lösungen vor (spielgemäß, Übungsreihen)\n• Induktiv: Lernende entdecken Lösungen selbst, Lehrer stellt Probleme und fragt (genetisch, Taktik-Spiel)\n• Ballschule: implizites Lernen durch vorgegebene Spiele","e":"Deduktiv: „So geht das!“ – zeitsparend und zielgerichtet, aber wenig Selbstständigkeit und Verständnis. Induktiv: „Wie könnte das gehen?“ – fördert Verständnis, Selbstständigkeit und Motivation, ist aber zeitaufwendig. Beispiel: Deduktiv erklärt der Lehrer den Doppelpass; induktiv fragt er im 2:1, wie man den Verteidiger überwinden kann, und die Schüler entdecken den Doppelpass.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q1.4-087","thema":"Q1.4","kapitel":"Methoden der Spielvermittlung","q":"Unterscheide implizites und explizites Lernen im Sportspiel und ordne es den Vermittlungskonzepten zu.","a":"• Implizit: unbewusst, beiläufig durch Spielen, ohne Anweisungen → Ballschule\n• Explizit: bewusst durch Instruktion und Reflexion → Taktik-Spiel (Reflexion), genetisch (Dialog)\n• Beide ergänzen sich","e":"Implizit lernt man wie die Muttersprache, explizit wie Grammatikregeln. Implizites Lernen gilt bei Kindern als besonders wirksam und unter Druck robust. Beispiel: Ein Kind lernt beim freien Spielen, wann es abspielen muss, ohne es erklären zu können (implizit); ein LK-Schüler formuliert nach dem Spiel bewusst „Bei Überzahl sofort abspielen“ (explizit).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.1-001","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Definiere den Begriff Ausdauer.","a":"Ausdauer ist die Ermüdungswiderstandsfähigkeit bei lang andauernden Belastungen sowie die Fähigkeit zur raschen Erholung.","e":"Zwei Komponenten gehören zusammen: eine Belastung lange durchhalten, ohne an Leistung zu verlieren (Ermüdungswiderstand), und sich nach Belastungen bzw. in Pausen schnell regenerieren (Erholungsfähigkeit). Beispiel: Beim Waldlauf ermüden die trainierten Läuferinnen Marie und Yvonne am Anstieg weniger als die untrainierte Claudia und erholen sich danach auch schneller wieder.","quelle":"L12.1","typ":"kern"},{"id":"q2.1-002","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Nach welchen Aspekten kann die Ausdauer differenziert werden?","a":"Nach Eisenhut & Zintl:\n• Sportartspezifik: allgemein / speziell\n• Energiebereitstellung: aerob / anaerob\n• Zeitdauer: KZA, MZA, LZA\n• Muskelmasse: lokal / global\n• Arbeitsweise: statisch / dynamisch\n• Mischformen: Kraft-, Schnelligkeitsausdauer","e":"Es gibt nicht „die eine“ Ausdauer. Je nachdem, welche Brille man aufsetzt, bekommt man andere Kategorien. Eselsbrücke: „SEZ-MBM“ – Sportart, Energie, Zeit, Muskulatur, Belastungsform, Mischform. Beispiel: Ein 800-m-Lauf fordert eine spezielle, global-dynamische Mittelzeitausdauer mit großem anaeroben Anteil.","quelle":"L12.1","typ":"kern"},{"id":"q2.1-003","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Erläutere den Unterschied zwischen allgemeiner und spezieller Ausdauer.","a":"• Allgemeine Ausdauer (Grundlagenausdauer): sportartunabhängig, Basis für alle Sportarten, gesundheitsfördernd\n• Spezielle Ausdauer: sportartspezifisch, an das Anforderungsprofil einer Sportart angepasst","e":"Die Grundlagenausdauer ist wie das Fundament eines Hauses, die spezielle Ausdauer das passende Stockwerk für die eigene Sportart. Spezielles Ausdauertraining muss sich daher an Bewegungsform, Belastungswechsel und beanspruchter Muskulatur der Sportart orientieren. Beispiel: Die Schwimmerin Yvonne hat eine gute Ausdauer im Wasser, tut sich aber beim Lauf im hügeligen Gelände mit ständigem Tempowechsel schwerer als die Fußballerin Marie, deren spezielle Ausdauer genau solche Wechsel gewohnt ist.","quelle":"L12.1","typ":"kern"},{"id":"q2.1-004","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Unterscheide lokale und globale Ausdauer.","a":"• Lokale Ausdauer: weniger als ca. 1/6 der Skelettmuskulatur beteiligt\n• Globale Ausdauer: mehr als 1/6 der Skelettmuskulatur beteiligt","e":"Die Grenze „ein Sechstel“ entspricht ungefähr der Muskelmasse eines Beines. Bei globaler Ausdauer wird das Herz-Kreislauf-System deutlich stärker beansprucht, bei lokaler eher die Muskulatur vor Ort. Beispiel: Viele Liegestütze oder Bizepscurls belasten nur wenige Muskeln (lokal), ein Dauerlauf oder Rudern dagegen große Teile des Körpers (global).","quelle":"L12.1","typ":"kern"},{"id":"q2.1-005","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Unterscheide aerobe und anaerobe Ausdauer.","a":"• Aerobe Ausdauer: Energiebereitstellung überwiegend mit Sauerstoff; O2-Aufnahme deckt den Bedarf\n• Anaerobe Ausdauer: Energiebereitstellung überwiegend ohne Sauerstoff; O2-Aufnahme reicht nicht → Sauerstoffdefizit","e":"„Aer“ ist griechisch für Luft – aerob heißt „mit Luft (Sauerstoff)“, anaerob „ohne Luft“. Anaerob wird es, wenn die Belastung so intensiv ist, dass die aufgenommene Sauerstoffmenge nicht mehr ausreicht („Laufen ohne Schnaufen“ ist aerob). Beispiel: Beim lockeren Joggen kann man sich unterhalten (aerob), beim Bergsprint muss man schnaufen, weil der Sauerstoff nicht reicht (anaerob).","quelle":"L12.1","typ":"kern"},{"id":"q2.1-006","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Wie werden Kurzzeit-, Mittelzeit- und Langzeitausdauer zeitlich abgegrenzt?","a":"Nach Dauer einer maximalen Ausdauerbelastung:\n• KZA: ca. 35 s – 2 min\n• MZA: ca. 2 – 10 min\n• LZA: über 10 min","e":"Die Einteilung richtet sich danach, wie lange man bei höchstmöglicher Intensität (erschöpfend) durchhält. Beispiel: 400-m-Lauf (KZA), 1.500-m-Lauf (MZA), 5.000-m-Lauf oder Marathon (LZA).","quelle":"L12.1","typ":"kern"},{"id":"q2.1-007","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Begründe, warum es keine Kurzzeitausdauer unter ca. 35 Sekunden gibt.","a":"• Unter ca. 35 s ist Schnelligkeit bzw. Schnelligkeitsausdauer leistungsbestimmend, nicht der Ermüdungswiderstand.\n• Erst ab ca. 35 s begrenzt Laktatanhäufung die Leistung (Ausdauer im eigentlichen Sinn).","e":"Unter einer halben Minute ist man noch nicht „müde“ im Ausdauersinn. Die Energie kommt fast ausschließlich anaerob, erst aus den Phosphatspeichern, dann aus der anaeroben Glykolyse, die erst nach ca. 30 Sekunden ihr Maximum erreicht. Beispiel: Beim 100-m- oder 200-m-Sprint entscheidet die Schnelligkeit(sausdauer); beim 400-m-Lauf dagegen kämpft man auf den letzten Metern mit Übersäuerung – das ist schon Kurzzeitausdauer.","quelle":"L12.1","typ":"zusatz"},{"id":"q2.1-008","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Unterscheide statische und dynamische Ausdauer.","a":"• Statische Ausdauer: Ermüdungswiderstand bei haltender Muskelarbeit (ohne Längenänderung)\n• Dynamische Ausdauer: Ermüdungswiderstand bei bewegender Muskelarbeit (überwindend und nachgebend)","e":"Statisch = man hält eine Position, dynamisch = man bewegt sich. Die Einteilung erfolgt nach der muskulären Arbeitsweise. Beispiel: Wandsitzen über 60 Sekunden trainiert die statische Kraftausdauer der Oberschenkel, eine Minute Liegestütze die dynamische Kraftausdauer des Ellbogenstreckers.","quelle":"L12.1","typ":"kern"},{"id":"q2.1-009","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Was versteht man unter Mischformen der Ausdauer? Nenne die wichtigsten.","a":"Verknüpfung von Ausdauer mit anderen konditionellen Fähigkeiten:\n• Kraftausdauer: Ermüdungswiderstand bei wiederholten/andauernden Kraftleistungen\n• Schnelligkeitsausdauer: Ermüdungswiderstand bei wiederholten Belastungen mit (sub)maximaler Geschwindigkeit","e":"Bei Mischformen geht es darum, eine andere Fähigkeit möglichst lange auf hohem Niveau zu halten. Bei der Schnelligkeitsausdauer muss man trotz Ermüdung schnell bleiben und sich in kurzen Pausen erholen. Beispiel: Bei einer Pendelstaffel muss jeder Schüler alle 45 Sekunden 50 m so schnell wie möglich laufen – nach jeder kurzen Erholung wieder voll. Das ist Schnelligkeitsausdauer.","quelle":"L12.1","typ":"kern"},{"id":"q2.1-010","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Welche Bedeutung hat die Grundlagenausdauer für Sportler (nach Weineck)?","a":"• Höhere physische Leistungsfähigkeit\n• Bessere Erholungsfähigkeit\n• Höhere psychische Belastbarkeit\n• Konstante Reaktions- und Handlungsschnelligkeit\n• Weniger Verletzungen\n• Weniger technische Fehler\n• Weniger ermüdungsbedingte taktische Fehler\n• Stabilere Gesundheit","e":"Die Grundlagenausdauer ist für alle Sportarten wichtig: Wer sie gut ausgebildet hat, wird später müde – und müde Sportler machen Fehler und verletzen sich eher. Beispiel: Eine Handballerin mit guter Grundlagenausdauer trifft auch in den letzten zehn Minuten noch sicher und trifft taktisch kluge Entscheidungen, während konditionsschwache Spielerinnen Fehlpässe spielen.","quelle":"L12.1","typ":"kern"},{"id":"q2.1-011","thema":"Q2.1","kapitel":"Grundbegriffe Ausdauer","q":"Welche Nachteile kann ein zu umfangreiches allgemeines Ausdauertraining haben?","a":"• Verluste an Schnelligkeit und Schnellkraft\n• Für Nicht-Ausdauerspezialisten nicht Hauptziel; Training muss an Sportart angepasst sein\n• Bei hoher Belastung (Saison) keine zusätzlichen intensiven Ausdauereinheiten","e":"Viel langsames Ausdauertraining macht den Körper „ökonomisch“, aber nicht explosiv. Das Ausdauertraining muss daher an die individuellen Bedürfnisse und die Sportart angepasst werden. Beispiel: Die Fußballerin Marie sollte während der Saison neben dem täglichen Training keine zusätzlichen intensiven Dauerläufe machen, sonst leiden ihre Antritte und Sprünge.","quelle":"L12.1","typ":"kern"},{"id":"q2.1-012","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Welcher Zusammenhang besteht zwischen Belastungsintensität und Art der Energiegewinnung?","a":"• Niedrige Intensität (LZA): vorwiegend aerob\n• Mittlere Intensität: aerob und anaerob\n• Hohe Intensität (KZA): vorwiegend anaerob, mit Sauerstoffdefizit","e":"Je schneller man wird, desto weniger kommt der Sauerstoff hinterher – dann muss der Körper „ohne Luft“ Energie gewinnen und geht ein Sauerstoffdefizit ein (im Bereich der KZA ab ca. 35 Sekunden). Beispiel: Die Schwimmerin Yvonne schwimmt 800 m locker und kann danach direkt mit dem Trainer reden (aerob); nach 100 m fast maximal ist sie völlig außer Atem (anaerob).","quelle":"L12.2","typ":"kern"},{"id":"q2.1-013","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Woran kann die Belastungsintensität im Ausdauerbereich festgemacht (operationalisiert) werden?","a":"• Bewegungsgeschwindigkeit (z. B. Laufgeschwindigkeit, Watt)\n• Herzfrequenz\n• Blutlaktat\n• Subjektives Belastungsempfinden\n• Atmung / Anteil der VO2max","e":"Intensität ist nicht direkt sichtbar, deshalb braucht man messbare Größen. Beispiel: Ein Läufer kann sein Tempo über die Pulsuhr (Herzfrequenz), über eine Laktatmessung beim Arzt oder ganz einfach über das Gefühl „leicht bis mittel“ steuern.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-014","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Erkläre das Sauerstoffdefizit und wozu die erhöhte Sauerstoffaufnahme nach Belastungsende dient.","a":"• Sauerstoffdefizit: zu Belastungsbeginn zu wenig O2 → Energie anaerob\n• Nach Belastung: O2-Mehraufnahme über Ruhebedarf („Sauerstoffschuld“) zum\n – Auffüllen der ATP-/KP-Speicher\n – Auffüllen der O2-Speicher (Blut, Muskel)\n – Abbau der Milchsäure\n – Versorgen von Herz- und Atemmuskulatur","e":"Der Körper „leiht“ sich zu Beginn Energie ohne Sauerstoff und muss diesen Kredit hinterher „abatmen“. Die ATP-/KP-Speicher sind nach ca. 2 Minuten wieder gefüllt, die Hälfte der Milchsäure ist nach ca. 15 Minuten abgebaut. Im Buch wird auch die Mehraufnahme als Sauerstoffdefizit bezeichnet. Beispiel: Nach einem 400-m-Lauf atmet man noch minutenlang schwer, obwohl man längst steht – man atmet das Defizit ab.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-015","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Welche Funktion haben die Mitochondrien?","a":"Mitochondrien sind die „Kraftwerke der Zelle“: In ihnen werden Kohlenhydrate und Fette unter Sauerstoffverbrauch (aerob) verbrannt; die Energie wird im ATP gespeichert.","e":"Die Nährstoffe im Blut sind wie Benzin – sie müssen erst „verbrannt“ werden. Das passiert in diesen Zellorganellen; das entstandene ATP wandert dann zu den Myofibrillen. Beispiel: Ausdauersportler haben deutlich mehr Mitochondrien in ihren Muskeln als Untrainierte und können deshalb mehr Energie aerob gewinnen.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-016","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Welche Nährstoffe dienen als „Treibstoff“ für Muskelarbeit und welche Rolle spielen Eiweiße?","a":"• Treibstoffe: Kohlenhydrate, Fette (und Eiweiße); Energie muss erst in ATP umgewandelt werden\n• Eiweiße: v. a. Baustoffwechsel; Energiegewinnung nur im Notfall (Hunger, extreme Belastung)","e":"Die Nährstoffe gelangen über das Blut zur Muskelzelle. Ihre Energie ist chemisch gebunden und muss erst in den Mitochondrien umgewandelt und im ATP gespeichert werden. Kohlenhydrate und Fette sind das eigentliche Benzin, Eiweiß ist eher das Baumaterial der Karosserie (z. B. Muskelwachstum). Beispiel: Erst bei sehr langen Belastungen wie einem Ultramarathon mit leeren Speichern greift der Körper verstärkt auf Eiweiß zurück.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-017","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Welche Rolle spielt das ATP für die Muskelarbeit?","a":"• ATP ist der einzige direkte Energielieferant des Muskels: ATP → ADP + Pi + Energie\n• „Weichmacherfunktion“: löst die Myosinköpfchen vom Aktin\n• Alle anderen Stoffwechselwege dienen der ATP-Resynthese","e":"ATP ist die einzige „Münze“, mit der der Muskel bezahlen kann; KP, Glukose und Fett dienen nur dazu, neue Münzen zu prägen. Der Vorrat reicht bei starker Belastung nur für 1–3 Kontraktionen, Training erhöht die Depots nur um bis zu 20 %. Beispiel: Ohne ATP bleiben die Myosinköpfchen am Aktin hängen – das erklärt die Totenstarre, bei der kein ATP mehr nachgeliefert wird.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-018","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Beschreibe die anaerob-alaktazide Energiebereitstellung.","a":"• ATP-Spaltung, dann Resynthese über Kreatinphosphat: KP + ADP → Kreatin + ATP\n• Ohne Sauerstoff, ohne Laktat, sofort verfügbar\n• Sehr hohe Energierate, geringe Energiemenge: Speicher nach ca. 6–8 (max. 10) s erschöpft","e":"Die Phosphatspeicher sind wie ein Turbo-Boost: extrem schnell verfügbar, aber nach wenigen Sekunden leer. Merksatz: Bei maximalen Belastungen bis ca. 8 Sekunden läuft die Energiegewinnung weitgehend über den Abbau der Phosphatspeicher. Beispiel: Ein 60-m-Sprint, ein Antritt zum Korb oder ein Sprungwurf im Basketball werden fast nur über ATP und KP gespeist.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-019","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Beschreibe die anaerob-laktazide Energiebereitstellung (anaerobe Glykolyse).","a":"• Glykogen/Glukose wird ohne O2 zu Laktat abgebaut (3 ATP pro Glukose)\n• Vorteil: schnelle Bereitstellung, hohe Energierate\n• Nachteil: geringe Ausbeute, Laktat → Übersäuerung, schnelle Ermüdung\n• Maximum nach ca. 30 s, versiegt nach ca. 2 min","e":"Die anaerobe Glykolyse springt ein, wenn mehr ATP gebraucht wird, als aerob geliefert werden kann. Sie ist wie ein Kredit mit hohen Zinsen: schnell Energie, aber die Rechnung (Laktat) kommt sofort – Enzymhemmung, schwere Beine, Schnaufen. Bei erschöpfender Belastung von ca. 1 Minute ist sie weitgehend ausgereizt. Beispiel: Beim 400-m-Lauf werden auf der Zielgeraden die Beine „schwer wie Blei“, weil sich Laktat angehäuft hat.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-020","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Beschreibe die aerobe Glykolyse.","a":"• Glukose wird in den Mitochondrien mit O2 vollständig zu CO2 und H2O abgebaut\n• Hohe Ausbeute: 31 ATP pro Glukose (ca. 10:1 gegenüber anaerob)\n• Geringere Energierate, kein Laktat\n• Dominiert bei ca. 2–90 min","e":"Gleichung: 1 Glukose + 6 O2 + 31 ADP + 31 Pi → 6 CO2 + 6 H2O + 31 ATP. Mit Sauerstoff wird der Zucker komplett „verbrannt“ und liefert zehnmal so viel Energie wie ohne – nur langsamer und mit geringer Ermüdung. Die Kohlenhydratspeicher reichen je nach Intensität bis ca. 90 Minuten. Beispiel: Ein 10.000-m-Läufer bezieht seine Energie überwiegend aus der aeroben Glykolyse.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-021","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Beschreibe die aerobe Lipolyse (Fettverbrennung).","a":"• Fettsäuren werden in den Mitochondrien mit O2 abgebaut (kein Laktat)\n• Sehr hohe Ausbeute: ca. 130 ATP pro Fettsäure\n• Sehr langsame Energielieferung, hoher O2-Bedarf → nur bei geringer Intensität\n• Nahezu unerschöpfliche Speicher","e":"Fett ist der riesige Reservetank des Körpers – fast unendlich groß, aber mit dünnem Schlauch: Die Energie fließt nur langsam. Deshalb ist die Lipolyse vor allem bei lang andauernden Belastungen niedriger Intensität bedeutsam (z. B. 6-Stunden-Lauf, Ultratriathlon). Beispiel: Beim stundenlangen lockeren Radfahren deckt der Körper einen großen Teil seines Bedarfs aus Fett.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-022","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Stelle die vier Formen der Energiebereitstellung im Muskel systematisch dar (Abb. 12.7).","a":"Anaerob:\n• alaktazid: ATP, Kreatinphosphat\n• laktazid: anaerobe Glykolyse\nAerob (alaktazid):\n• glykolytisch: aerobe Glykolyse\n• lipolytisch: aerobe Lipolyse","e":"Zwei Fragen genügen zum Einordnen: Reicht der Sauerstoff (aerob/anaerob)? Entsteht Laktat (laktazid/alaktazid)? Beispiel: Ein Kugelstoß (alaktazid), ein 400-m-Lauf (laktazid), ein Halbmarathon (aerob-glykolytisch) und eine lange Wanderung (aerob-lipolytisch) decken alle vier Wege ab.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-023","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Vergleiche aerobe und anaerobe Glykolyse anhand wichtiger Parameter (Tab. 12.2).","a":"Anaerob / aerob:\n• Laktat: ja / nein\n• ATP pro Glukose: 3 / 31\n• Bereitstellung: schnell / langsam\n• Leistung: groß / klein\n• Gesamtenergie: klein / groß\n• Disziplin: 100/400 m / 10.000 m","e":"Anaerob = Sprinter-Stoffwechsel (schnell, aber kurz), aerob = Marathon-Stoffwechsel (langsam, aber ergiebig). Beispiel: Ein 10.000-m-Läufer kann nicht das Tempo eines 400-m-Läufers laufen, weil die aerobe Glykolyse pro Sekunde weniger Energie liefert.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-024","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Warum stellt die anaerobe Glykolyse schneller Energie bereit als die aerobe Glykolyse?","a":"• Anaerob: Glukose wird nur einmal gespalten (zu Milchsäure) → wenige Reaktionsschritte\n• Aerob: mehrfache Spaltung bis CO2 und H2O, viele Schritte, O2 nötig\n→ anaerob schneller, aber nur 3 statt 31 ATP","e":"Weniger Arbeitsschritte bedeuten ein schnelleres Ergebnis, aber man lässt viel Energie im Laktat ungenutzt liegen (C6H12O6 → 2 C3H6O3). Aerob wird das Molekül fünfmal gespalten und vollständig abgebaut. Beispiel: Wie beim Kochen – ein Fertiggericht (anaerob) ist schnell fertig, ein aufwendiges Menü (aerob) dauert länger, macht aber viel satter.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-025","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Was versteht man unter Glykogen und welche Bedeutung haben Muskel- und Leberglykogen?","a":"Glykogen = Speicherform der Glukose.\n• Muskelglykogen: direkt für die Muskelarbeit\n• Leberglykogen: hält den Blutzucker konstant, versorgt v. a. das Gehirn/ZNS","e":"Der Muskel hat seinen eigenen Vorratsschrank (ca. 1,5 g pro 100 g Gewebe), die Leber (ca. 75–90 g) versorgt Blut und Gehirn – ca. 60 % der abgegebenen Glukose gehen ans Gehirn. Bei langen submaximalen Belastungen wird die Glukoseaufnahme aus dem Blut wichtig. Ausdauertraining kann die Glykogenbestände verdoppeln. Beispiel: Beim Marathon-„Mann mit dem Hammer“ ab ca. Kilometer 30 sind die Glykogenspeicher leer – Leistung und Konzentration brechen ein.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-026","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Beschreibe den zeitlichen Verlauf der Energiebereitstellung bei einer maximalen Belastung wie dem 800-m-Lauf.","a":"Alle Systeme laufen parallel, zeitlich gestaffelt:\n• bis ca. 10 s: anaerob-alaktazid dominiert\n• danach anaerob-laktazid (Maximum ca. 30 s)\n• ab ca. 70 s: aerob dominiert\n• nach ca. 2 min: ca. 50 % aerob","e":"Die Energiesysteme sind wie Staffelläufer, die sich überlappend den Stab übergeben – zu Beginn werden alle gleichzeitig in Gang gesetzt und laufen mit, nur die Führungsrolle wechselt. Beispiel: Ein 800-m-Läufer startet mit Phosphaten, läuft die erste Runde stark laktazid und wird in der zweiten Runde zunehmend aerob versorgt, während die Übersäuerung ihn bremst.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-027","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Fasse zusammen: Woher bezieht der Körper seine Treibstoffe und wie lange reichen sie?","a":"• Phosphate (ATP, KP): bei maximaler Belastung nach ca. 6–8, maximal 10 Sekunden verbraucht\n• Kohlenhydrate (Glykogen/Glukose): reichen je nach Intensität bis zu ca. 90 Minuten\n• Fette: nahezu unerschöpfliche Kapazität","e":"Je schneller der Treibstoff verfügbar ist, desto kleiner ist der Tank. Beispiel: Ein Sprinter lebt von den Phosphaten, ein 10-km-Läufer von Kohlenhydraten und ein Ultraläufer zu großen Teilen von Fett.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-028","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Welche Grundprinzipien gelten für den gleichzeitigen Ablauf der Energiegewinnungsprozesse?","a":"• Alle Prozesse laufen immer gleichzeitig, aber „auf unterschiedlichen Touren“.\n• Hohe Intensität: anaerobe Prozesse überwiegen\n• Niedrige Intensität: aerobe Prozesse dominieren\n• Bei genug O2 hat das aerobe System „Vorfahrt“.","e":"Es gibt keinen Schalter, der von einem System aufs andere umlegt – eher ein Mischpult, bei dem die Regler unterschiedlich hoch stehen, solange die Speicher nicht leer sind. Beispiel: Auch beim lockeren Joggen entsteht etwas Laktat, und auch beim Sprint arbeitet der aerobe Stoffwechsel ein wenig mit.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-029","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Erkläre, warum ein Spieler bei Belastungen über 6–8 Sekunden (z. B. Kontrollform 1:1 im Basketball) zunehmend ermüdet.","a":"• Nach 6–8 s sind die Phosphatspeicher leer.\n• Aerob kommt zu wenig O2 an → Lücke wird anaerob-laktazid geschlossen.\n• Laktat häuft sich an (Maximum der Glykolyse ca. 30 s) → Übersäuerung, Leistungsabfall.","e":"Nach dem „Turbo“ der Phosphate muss der Körper auf die laktazide Notlösung zurückgreifen – und die macht sauer. Folgen sind schwere Beine, langsamere Antritte, ungenauere Würfe sowie Fang- und Dribbelfehler; nur Trainierte halten die Intensität auch nach 60 Sekunden. Beispiel: Ein ungeübter Basketballer verliert in einer 60–90 Sekunden langen 1:1-Übung schon nach ca. 30 Sekunden deutlich an Intensität.","quelle":"L12.2","typ":"kern"},{"id":"q2.1-030","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Welche Arten der Energiegewinnung überwiegen bei Laufstrecken von 100 m bis 5.000 m bei Spitzenleichtathleten?","a":"• 100 m: alaktazid, zunehmend laktazid\n• 200 m: alaktazid und laktazid\n• 400 m: überwiegend laktazid\n• 800 m: laktazid ≈ aerob (leicht aerob)\n• 1.500 m: überwiegend aerob, großer laktazider Anteil\n• 5.000 m: deutlich aerob","e":"Faustregel: Je länger die Strecke, desto größer der aerobe Anteil; die 800 m (ca. 1:45 min) sind ungefähr der Wendepunkt. Richtzeiten: 100 m ca. 10 s, 400 m ca. 45 s, 1.500 m ca. 3:30 min, 5.000 m ca. 13 min. Beispiel: Ein 400-m-Läufer ist auf der Zielgeraden völlig übersäuert, ein 5.000-m-Läufer kann dagegen lange ein gleichmäßiges Tempo laufen und noch spurten.","quelle":"L12.2","typ":"zusatz"},{"id":"q2.1-031","thema":"Q2.1","kapitel":"Energiebereitstellung","q":"Welche Arten der Energiegewinnung sind im Basketball leistungsbestimmend und warum?","a":"• Anaerob-alaktazid: Sprints, Sprünge, Würfe, Antritte (< 6–8 s)\n• Anaerob-laktazid: gehäufte intensive Phasen (Laktat > 4 mmol/l)\n• Aerob: Basis für Spieldauer, Erholung in Pausen (Phosphat-Wiederauffüllung, Laktatabbau)","e":"Das Belastungsprofil zeigt: viele Kurzsprints von 1,7–5 s, ca. 45 Maximalsprünge, Belastungs-Pausen-Verhältnis 2:1 bis 1:2, Laktat meist 4–9 mmol/l, 4,6–5,4 km Laufstrecke. Die Aktionen sind kurz und anaerob, die Erholung dazwischen gelingt nur mit guter aerober Basis. Beispiel: Die Fußballerin Marie hält das 3:3 besser durch als die Schwimmerin Yvonne, weil sie ihre ATP-Speicher in den kurzen Pausen schneller wieder auffüllt.","quelle":"L12.7","typ":"zusatz"},{"id":"q2.1-032","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Welche zwei wesentlichen Kriterien stehen zur Messung der aeroben Ausdauerleistungsfähigkeit zur Verfügung?","a":"• Blutlaktat: Belastungsintensität an der anaeroben Schwelle (4 mmol/l)\n• Maximale Sauerstoffaufnahme (VO2max), v. a. für die MZA (2–10 min)","e":"Einmal schaut man ins Blut (wie viel „Abfall“ entsteht), einmal in die Atemluft (wie viel Sauerstoff kann verwertet werden). Beispiel: Ein Leistungsdiagnostiker misst beim Läufer auf dem Laufband Laktat am Ohrläppchen und die O2-Aufnahme über eine Atemmaske.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-033","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Definiere die aerobe Schwelle (AS).","a":"Belastungsintensität, bei der der Laktatspiegel ca. 2 mmol/l übersteigt (Sauerstoff-Steady-State). Darunter fast ausschließlich aerobe Energiegewinnung; HF ca. 120–140.","e":"Ab der aeroben Schwelle wird zusätzlich anaerob-laktazid Energie bereitgestellt und der Laktatspiegel beginnt zu steigen; darunter bleibt er nahe dem Ruhewert. Anzeichen für das Überschreiten ist ein gesteigertes Atemzugvolumen. Unterhalb läuft man „ohne Schnaufen“ – ideal für Gesundheitssport und Aufwärmen. Beispiel: Ein lockerer Dauerlauf, bei dem man sich noch gut unterhalten kann, liegt unterhalb bzw. im Bereich der aeroben Schwelle.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-034","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Definiere die anaerobe Schwelle (ANS) und erkläre den Begriff Laktat-Steady-State.","a":"• ANS: bei 4 mmol Laktat/l Blut (empirisch festgelegt)\n• Laktat-Steady-State: maximales Gleichgewicht von Laktatbildung und -abbau\n• Darüber: starker Laktatanstieg, rasche Erschöpfung","e":"Die ANS ist die rote Linie: Bis hierhin kann der Körper das entstehende Laktat gerade noch wegschaffen, darüber läuft die Badewanne über – schwere Beine, Mundatmung. Bei Normaltrainierten liegt sie bei ca. 175 Schlägen/min und etwa 80 % der maximalen Intensität. Beispiel: Ein 10-km-Wettkampf wird von Trainierten ungefähr im Bereich der anaeroben Schwelle gelaufen.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-035","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Was versteht man unter dem aerob-anaeroben Übergangsbereich (AANÜ)?","a":"Bereich zwischen aerober (2 mmol/l) und anaerober Schwelle (4 mmol/l): aerobe Energiegewinnung wird anaerob-laktazid unterstützt; Laktatbildung und -abbau noch im Gleichgewicht.","e":"Im Übergangsbereich arbeiten beide Systeme zusammen – man fängt an zu schnaufen, kann das Tempo aber noch lange halten. Die Laktatbildung steigt mit der Intensität; Herzfrequenz ca. 120–175, 4–8 Laufschritte pro Atemzyklus. Beispiel: Ein zügiger Tempodauerlauf, bei dem Reden nur noch in kurzen Sätzen möglich ist.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-036","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Stelle den Zusammenhang von Laktatkonzentration, Herzfrequenz, Atmung und Energiegewinnung dar (Tab. 12.3).","a":"Laktat | HF | Schritte/Atemzyklus | Energie:\n• aerob: < 2 | < 120 | > 8 | aerob\n• AS: 2 | 120–140 | ca. 8 | aerob\n• AANÜ: 2–4 | 120–175 | 4–8 | aerob + anaerob\n• ANS: 4 | ca. 175 | ca. 4 | zunehmend anaerob\n• anaerob: > 4 | > 175 | < 4 | anaerobe Glykolyse","e":"Mit steigendem Tempo steigen Laktat und Puls, und man macht immer weniger Schritte pro Atemzug. Aerob heißt hier aerobe Glykolyse und Lipolyse. Die HF-Werte hängen von Trainingszustand und Alter ab. Beispiel: Wer beim Laufen nur noch zwei Schritte ein- und zwei ausatmet (4 Schritte pro Zyklus), ist an oder über der anaeroben Schwelle.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-037","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Woran erkennt ein Sportler ohne Messgerät, dass er die anaerobe Schwelle überschritten hat?","a":"• Weniger als 4 Laufschritte pro Atemzyklus\n• Mundatmung bzw. Schnaufen\n• Reden fällt schwer\n• Schwere Beine","e":"Der Körper verrät die Schwelle über die Atmung; die schweren Beine kommen von der Übersäuerung. Beispiel: Beim Bergauflaufen merkt man plötzlich, dass man nur noch durch den Mund hechelt und keinen Satz mehr herausbekommt – dann ist man über der ANS.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-038","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Was versteht man unter der individuellen anaeroben Schwelle (IANS)?","a":"Individueller Punkt des kritischen (überproportionalen) Laktatanstiegs, z. B. per Tangentenmethode bestimmt.\n• Untrainierte: über 4 mmol/l (ca. 5–6)\n• Trainierte: unter 4 mmol/l (ca. 2,5–3)","e":"Die feste 4-mmol-Grenze ist ein Durchschnittswert – wie eine Kleidergröße „M“, die nicht jedem passt. Deshalb bestimmt man die Schwelle individuell aus der Laktat-Leistungs-Kurve. Beispiel: Ein Marathonläufer kippt schon bei 3 mmol/l in den steilen Anstieg, ein Untrainierter erst bei 5–6 mmol/l; nach starrer 4-mmol-Regel würde der Marathonläufer zu hart trainieren.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-039","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Welche maximalen Laktatkonzentrationen erreichen Spitzensportler und Untrainierte?","a":"• Spitzensportler: bis ca. 25 mmol/l\n• Untrainierte: ca. 7–8 mmol/l","e":"Trainierte haben eine deutlich größere anaerobe Kapazität und Laktattoleranz – sie können sich viel stärker „übersäuern“ und trotzdem weitermachen. Beispiel: Ein 400-m-Läufer misst nach dem Wettkampf Werte, die ein Untrainierter nie erreichen würde, weil dieser vorher abbricht.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-040","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Nenne das Kriterium für die aerobe Leistungsfähigkeit über die anaerobe Schwelle.","a":"Je höher die Belastungsintensität (z. B. Laufgeschwindigkeit), bei der die anaerobe Schwelle (4 mmol/l) erreicht wird, desto besser die aerobe Leistungsfähigkeit.","e":"Nicht die Laktatmenge an sich zählt, sondern wie schnell man laufen kann, bevor die 4 mmol/l erreicht sind. Beispiel: Läuferin A erreicht 4 mmol/l bei 12 km/h, Läuferin B erst bei 15 km/h – B ist aerob leistungsfähiger.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-041","thema":"Q2.1","kapitel":"Laktat und Schwellen","q":"Wie wirkt sich Ausdauertraining auf die Laktat-Leistungs-Kurve aus?","a":"• Rechtsverschiebung der Laktat-Leistungs-Kurve\n• Bei gleicher Belastung weniger Laktat\n• Höhere Leistung an der 4-mmol-Schwelle\n→ verbesserte aerobe Leistungsfähigkeit","e":"Rechtsverschiebung = gut: Man kann schneller laufen, bevor die Übersäuerung beginnt. Beispiel: Ein Athlet erreicht 4 mmol/l zu Beginn einer Trainingsperiode bei 3 m/s, nach drei Monaten Training erst bei 5 m/s.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-042","thema":"Q2.1","kapitel":"Maximale Sauerstoffaufnahme","q":"Definiere die maximale Sauerstoffaufnahme (VO2max).","a":"Die VO2max ist die maximale Sauerstoffmenge, die der Organismus pro Minute in den Geweben verbrauchen kann (ml/min bzw. ml/(min · kg)); Kriterium der aeroben Ausdauer v. a. für die MZA.","e":"Sie wird bestimmt durch Atmung, Sauerstofftransport (Herz-Kreislauf-System) und vor allem die Sauerstoffverwertung in den Muskelzellen; besonders aussagekräftig ist sie für Belastungen von 2–10 Minuten. Die VO2max ist sozusagen die Hubraumgröße des aeroben Motors. Beispiel: Ein untrainierter Jugendlicher hat ca. 40–45 ml/(min · kg), Weltklasse-Ausdauerathleten erreichen 80 ml/(min · kg) und mehr.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-043","thema":"Q2.1","kapitel":"Maximale Sauerstoffaufnahme","q":"Welcher Zusammenhang besteht zwischen Sauerstoffaufnahme, Herzminutenvolumen und arteriovenöser Sauerstoffdifferenz?","a":"VO2 = HMV · AVDO2\n• HMV: pro Minute vom Herzen gepumptes Blutvolumen\n• AVDO2: Differenz des O2-Gehalts zwischen arteriellem und venösem Blut (O2-Ausschöpfung im Muskel)","e":"Wie viel Sauerstoff man aufnimmt, hängt davon ab, wie viel Blut vorbeifließt und wie viel O2 der Muskel daraus „herausfischt“. Die AVDO2 beträgt in Ruhe ca. 25 % und kann unter Belastung auf ca. 75 % steigen. Beispiel: Ausdauertraining erhöht sowohl das HMV (größeres Herz) als auch die AVDO2 (mehr Kapillaren und Mitochondrien) – beides steigert die VO2max.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-044","thema":"Q2.1","kapitel":"Maximale Sauerstoffaufnahme","q":"Wie wird die VO2max gemessen?","a":"Spiroergometrie: Stufentest mit Atemmaske auf Laufband-, Fahrrad- oder Ruderergometer; gemessen werden v. a. O2-Aufnahme, CO2-Abgabe, Atemminutenvolumen.","e":"Bei der Spiroergometrie wird mit hohem apparativem Aufwand die Atemluft analysiert, während die Belastung stufenweise gesteigert wird – möglichst sportartspezifisch. Auch die Atemfrequenz wird erfasst. Beispiel: Ein Radprofi tritt im Labor mit Maske auf dem Ergometer, bis er nicht mehr kann – der höchste O2-Wert ist seine VO2max.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-045","thema":"Q2.1","kapitel":"Maximale Sauerstoffaufnahme","q":"Unterscheide absolute und relative VO2max und erläutere, für welche Sportarten welche Größe leistungslimitierend ist.","a":"• Absolut (ml/min): limitierend, wenn das Körpergewicht nicht getragen wird (Rudern, Radfahren, Schwimmen)\n• Relativ (ml/(min · kg)): limitierend, wenn der Körper getragen wird (Langstreckenlauf, Skilanglauf)","e":"Wer sein Gewicht selbst tragen muss, profitiert von wenig Gewicht pro Liter Sauerstoff; die relative VO2max bezieht die Aufnahme deshalb auf das Körpergewicht. Beispiel: Ein schwerer Ruderer kann eine riesige absolute VO2max haben; ein leichter Marathonläufer punktet dagegen mit einer hohen relativen VO2max.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-046","thema":"Q2.1","kapitel":"Maximale Sauerstoffaufnahme","q":"Warum gilt die VO2max vor allem im Bereich der Mittelzeitausdauer als Kriterium der aeroben Leistungsfähigkeit, und wie stark ist sie trainierbar?","a":"• Belastung an der VO2max ist nur max. ca. 10 min durchzuhalten → aussagekräftig für 2–10 min (MZA)\n• Trainierbarkeit: max. ca. 40 % (Hollmann & Strüder); stark genetisch bestimmt","e":"Bei längeren Belastungen läuft man unterhalb der VO2max, dann ist eher die anaerobe Schwelle entscheidend. Die Steigerung um bis zu 40 % gilt für Erwachsene und ist individuell sehr verschieden. Beispiel: Ein 1.500-m- oder 3.000-m-Läufer läuft nahe seiner VO2max, ein Marathonläufer deutlich darunter.","quelle":"L12.3","typ":"kern"},{"id":"q2.1-047","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Über welche Parameter kann die Belastungsintensität im Ausdauertraining gesteuert werden?","a":"• Herzfrequenz\n• Subjektives Belastungsempfinden\n• Atmung\n• Bewegungsgeschwindigkeit\n• Blutlaktat\n• Anteil der VO2max","e":"Es gibt aufwendige (Laktat, VO2max) und alltagstaugliche Methoden (Puls, Gefühl, Atemrhythmus, Nasen-/Mundatmung). Beispiel: Ein Freizeitläufer nutzt Pulsuhr und das Motto „Laufen ohne Schnaufen“, ein Profi lässt zusätzlich regelmäßig Laktatwerte bestimmen.","quelle":"L12.4","typ":"kern"},{"id":"q2.1-048","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Definiere Herzfrequenz, Ruhepuls und Belastungspuls und beschreibe, wie der Puls gemessen wird.","a":"• Herzfrequenz: Herzschläge pro Minute\n• Ruhepuls: direkt nach dem Aufstehen\n• Belastungspuls: unmittelbar nach der Belastung\n• Messung: Handgelenk (Daumenseite) oder Halsschlagader; 10 s zählen × 6","e":"Man legt Zeige-, Mittel- und Ringfinger leicht auf. Nach der Belastung zählt jede Sekunde, weil der Puls rasch sinkt – längeres Messen als 10 Sekunden liefert zu niedrige Werte. Beispiel: Man zählt 27 Schläge in 10 Sekunden: 27 · 6 = 162 Schläge pro Minute (Trick: erst verdreifachen = 81, dann verdoppeln = 162).","quelle":"L12.4","typ":"kern"},{"id":"q2.1-049","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Wozu dient die Pulsfrequenzkontrolle im Ausdauertraining und wie unterscheiden sich Trainierte und Untrainierte hinsichtlich der Herzfrequenz?","a":"Zweck:\n• individuelle Belastung feststellen\n• Erholungsgrad prüfen\n• Belastung/Pause bei Intervall- und Wiederholungsmethode einhalten\nTrainierte: gleiche Leistung bei geringerer HF, schnellere Erholung.","e":"Der Puls ist der Drehzahlmesser des Körpers. Trainierte sind dadurch im Training besser belastbar. Die Pulsmessung muss geübt werden, damit sie zuverlässig ist. Beispiel: Beim Intervalltraining startet man den nächsten Lauf erst, wenn der Puls auf ca. 120–130 gesunken ist – so wird die „lohnende Pause“ exakt eingehalten.","quelle":"L12.4","typ":"kern"},{"id":"q2.1-050","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Nenne die Karvonen-Formel und erkläre ihre Größen.","a":"HFT = (HFmax – HFR) · I + HFR\n• HFT: Trainingsherzfrequenz\n• HFmax: max. HF (≈ 220 – Alter)\n• HFR: Ruheherzfrequenz\n• I: Intensität (0–1)","e":"(HFmax – HFR) nennt man Herzfrequenzreserve. Die Formel berücksichtigt den individuellen Ruhepuls und ist dadurch genauer als ein bloßer Prozentsatz der HFmax. Beispiel: HFR = 60, HFmax = 200, I = 0,6 → HFT = (200 – 60) · 0,6 + 60 = 144 Schläge/min.","quelle":"L12.4","typ":"kern"},{"id":"q2.1-051","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Welche Intensitätsbereiche bei Ausdauerbelastungen werden nach Haas unterschieden und welche Trainingswirkung haben sie?","a":"• < 60 %: regenerativ / Gesundheit (unter AS)\n• 60–75 %: aerob (Bereich AS)\n• 75–85 %: aerob-anaerober Übergangsbereich\n• > 85 %: anaerob-laktazid (über ANS)","e":"Die Prozentwerte sind die Intensität I in der Karvonen-Formel, die Bereiche entsprechen den Laktatzonen; aerob heißt aerobe Glykolyse und Lipolyse. Beispiel: Für einen Sportler mit HFR 60 und HFmax 200 ergeben sich: unter 144 (regenerativ), 144–165 (aerob), 165–179 (AANÜ), über 179 (anaerob).","quelle":"L12.4","typ":"kern"},{"id":"q2.1-052","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Berechne mit der Karvonen-Formel die Trainingsherzfrequenz für ein aerobes Training (60–75 %) einer 18-Jährigen mit Ruhepuls 65.","a":"• HFmax = 220 – 18 = 202; Reserve = 202 – 65 = 137\n• 60 %: 137 · 0,6 + 65 ≈ 147\n• 75 %: 137 · 0,75 + 65 ≈ 168\n→ ca. 147–168 Schläge/min","e":"Erst HFmax bestimmen, dann Reserve bilden, mit der Intensität malnehmen und den Ruhepuls wieder addieren (82,2 + 65 bzw. 102,75 + 65). Beispiel: Genau so kann eine Schülerin vor dem Abi-Lauftraining ihren persönlichen Pulsbereich für lockere Grundlagenläufe festlegen.","quelle":"L12.4","typ":"zusatz"},{"id":"q2.1-053","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Welche Bedeutung hat das subjektive Belastungsempfinden für die Intensitätssteuerung?","a":"• Eignet sich zur Intensitätssteuerung für Geübte und Einsteiger; zuverlässig bei guter Körperwahrnehmung\n• Skalen: 7-stufig (Boeckh-Behrens & Buskies) oder Borg (6–20)\n• Gesundheitssport: „leicht bis mittel“","e":"Man „hört in sich hinein“ statt auf ein Gerät zu schauen. Die 7-stufige Skala reicht von „sehr leicht“ bis „sehr schwer“; bei der Borg-Skala gilt Wert · 10 ≈ Herzfrequenz. Neueinsteiger beginnen „leicht“, um länger durchzuhalten; beim Radfahren darf es etwas höher sein, da „mittel“ dort deutlich unter 4 mmol/l Laktat liegt. Beispiel: Ein Wert von 13 („etwas anstrengend“) auf der Borg-Skala entspricht ungefähr einem Puls von 130.","quelle":"L12.4","typ":"kern"},{"id":"q2.1-054","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Wie kann die Atmung zur Steuerung der Ausdauerintensität genutzt werden?","a":"• Gesundheitsorientiert: 6–8 Schritte pro Atemzyklus, Nasenatmung („Laufen ohne Schnaufen“)\n• ≤ 4 Schritte pro Atemzyklus bzw. Mundatmung mit Schnaufen: über der (individuellen) ANS","e":"Die Atmung ist ein kostenloses Messgerät. Ältere bzw. leistungsschwächere Personen nehmen ca. 8, Jüngere 6–7 Schritte pro Atemrhythmus. Nasenatmung heißt hier: Einatmen durch die Nase, Ausatmen durch den Mund; bei Mundatmung fällt Reden schwer. Beispiel: Beim Einlaufen im Sportunterricht gilt „Sprechend laufen“ – wer sich noch unterhalten kann, liegt im aeroben Bereich.","quelle":"L12.4","typ":"kern"},{"id":"q2.1-055","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Warum sollte bei intensiver Belastung die Atemmittellage in Richtung Ausatmung verschoben werden?","a":"• Weniger Restluft in den Alveolen (kleinerer Totraumanteil)\n• → höherer O2-Gehalt im Alveolarraum\n• → bessere O2-Diffusion ins Blut","e":"Wer gründlich ausatmet, schafft Platz für mehr frische Luft, weil sich die eingeatmete Luft mit weniger verbrauchter Luft vermischt. Beispiel: Läufer, die bewusst kräftig ausatmen, haben bei hohem Tempo oft das Gefühl, „mehr Luft zu bekommen“.","quelle":"L12.4","typ":"kern"},{"id":"q2.1-056","thema":"Q2.1","kapitel":"Intensitätssteuerung","q":"Welche Möglichkeiten zur Dosierung der Belastungsintensität beim gesundheitsorientierten (aeroben) Ausdauertraining gibt es (Tab. 12.7)?","a":"• Laktat: bis ca. 4 mmol/l\n• HF Laufen: Karvonen 60–75 % bzw. 190/195 – Alter (± 5)\n• HF Rad: Karvonen 60–70 % bzw. 180 – Alter (± 3)\n• Empfinden: leicht bis mittel\n• Atmung: Nasenatmung, 6–8 Schritte/Atemzyklus\n• „Laufen ohne Schnaufen“, Wohlbefinden","e":"Es gibt keine universellen Intensitätsvorgaben; die Werte sind praktikable Richtwerte. Beim Radfahren darf das Empfinden auch „mittel bis schwer“ sein; Motto „Sprechend laufen/radeln“. Für den Gesundheitssport reicht meist ein einfaches Kriterium – wichtig ist, sich wohlzufühlen. Beispiel: Ein 40-Jähriger läuft nach Faustformel mit ca. 150–155 Schlägen/min (190 – 40 = 150 ± 5).","quelle":"L12.4","typ":"kern"},{"id":"q2.1-057","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Welche Anpassungen des Herzens bewirkt intensives Ausdauertraining (Sportherz)?","a":"• Herzvergrößerung (alle vier Höhlen, Herzmuskel dicker)\n• Weitere Herzkranzgefäße\n• Höheres Schlagvolumen\n• Höheres maximales HMV\n• Niedrigerer Ruhepuls","e":"Ein größeres Herz pumpt pro Schlag mehr Blut, also braucht es in Ruhe weniger Schläge. Schlagvolumen: untrainiert ca. 60–70 ml, trainiert bis ca. 200 ml; max. HMV ca. 25–40 statt 20 l/min; Ruhepuls 30–40 statt 60–80. Ein Sportherz gibt es in jedem Alter und bei beiden Geschlechtern. Beispiel: Radprofis haben oft einen Ruhepuls um 35 – ihr Herz arbeitet extrem ökonomisch.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-058","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Vergleiche die Herzparameter von Untrainierten und Ausdauertrainierten (Tab. 12.8).","a":"Untrainiert / trainiert:\n• Herzgewicht: 250–300 / 350–500 g\n• Herzvolumen: 600–800 / 900–1.300 ml\n• SV Ruhe: 60–90 / 95–115 ml\n• SV Belastung: 75–105 / 170–200 ml\n• HF Ruhe: 60–80 / 40–60\n• HF max: ca. 200 / ca. 200\n• HMV Ruhe: ca. 5 / ca. 5 l\n• HMV Belastung: ca. 20 / ca. 40 l","e":"Wichtig: Das HMV in Ruhe und die maximale Herzfrequenz bleiben gleich – Trainierte erreichen das Ruhe-HMV aber mit weniger Schlägen und unter Belastung ein doppelt so hohes HMV. Beispiel: 5 l/min schafft der Trainierte mit 50 Schlägen à 100 ml, der Untrainierte braucht 70 Schläge à ca. 70 ml.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-059","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Welche Anpassungen der Blutgefäße bewirkt Ausdauertraining?","a":"• Kapillarisierung: mehr und weitere Kapillaren → bessere O2-/Nährstoffversorgung\n• Kollateralenbildung: Querverbindungen der Arteriolen → bessere Blutumverteilung\n• Stabilisierung des Blutdrucks","e":"Mehr Kapillaren bedeuten mehr „Lieferstraßen“ zum Muskel, Kollateralen sind „Umgehungsstraßen“. Gesundheitlich wichtig: Bei einem Gefäßverschluss (Arteriosklerose) können Kollateralen die Hauptströmung übernehmen. Beispiel: Bei einem Herzinfarkt kann ein Ausdauertrainierter dank Kollateralen geringere Schäden davontragen, weil Blut über Umwege fließt.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-060","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Welche Anpassungen des Muskelstoffwechsels bewirkt Ausdauertraining?","a":"• Mehr und größere Mitochondrien (v. a. ST-Fasern)\n• Leistungsfähigere aerobe Enzyme\n• Größere Glykogenspeicher (etwa Verdopplung)\n• Größere intrazelluläre Fettspeicher (bis 3-fach)\n• Mehr Myoglobin","e":"Der Muskel baut mehr Kraftwerke und größere Lager. Untrainiert speichert die Leber 60–100 g, die Muskulatur 200–300 g Glykogen; das Fett liegt als Triglyzeridtröpfchen direkt im Muskel. Beispiel: Ein trainierter Marathonläufer kann dadurch länger Kohlenhydrate verbrennen und mehr Fett direkt im Muskel nutzen – der „Mann mit dem Hammer“ kommt später.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-061","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Welche Funktion hat das Myoglobin und wie verändert es sich durch Ausdauertraining?","a":"Roter Muskelfarbstoff der ST-Fasern mit sehr hoher O2-Bindung:\n• unterstützt die O2-Diffusion in die Muskelzelle\n• dient als O2-Speicher im Muskel\nAusdauertraining erhöht den Myoglobingehalt.","e":"Myoglobin ist der Sauerstoff-Zwischenspeicher im Muskel; es bindet O2 ca. 200-mal stärker als Hämoglobin und verhindert so ein zu starkes O2-Defizit zu Belastungsbeginn. Es macht die ST-Fasern tiefrot. Beispiel: Das dunkle Fleisch von Zugvögeln oder die rote Brustmuskulatur von Enten enthält viel Myoglobin, weil diese Muskeln lange Ausdauerarbeit leisten.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-062","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Welche Anpassungen des Blutes bewirkt Ausdauertraining?","a":"• Mehr Blutvolumen (v. a. Plasma, ca. 1–2 l)\n• Mehr Erythrozyten und Hämoglobin\n• Geringere Viskosität\n• Höhere Pufferkapazität","e":"Mehr und flüssigeres Blut bedeutet mehr Transportkapazität bei weniger Pumpaufwand: Das Plasma liefert Wasser zum Schwitzen, mehr Hämoglobin erhöht den O2-Transport, und weil das Plasma stärker zunimmt, wird das Blut dünnflüssiger. Die Puffer wirken gegen Übersäuerung. Beispiel: Ein trainierter Läufer kann an heißen Tagen besser schwitzen und kühlt sich dadurch effektiver als ein Untrainierter.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-063","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Welche Anpassungen von Atmung und Nervensystem bewirkt Ausdauertraining?","a":"Atmung:\n• vertiefte Atmung\n• größeres Atemminutenvolumen\n• höhere Vitalkapazität\nNervensystem:\n• beruhigende Wirkung, mehr Parasympathikus-Aktivität\n• bessere Entspannungsfähigkeit","e":"Ausdauertraining verändert nicht nur Herz und Muskeln, sondern macht auch „ruhiger“. Achtung: Die Vitalkapazität ist kein Parameter für eine gute Ausdauerleistungsfähigkeit. Beispiel: Viele Menschen gehen nach einem stressigen Tag joggen, weil sie sich danach entspannter fühlen – das ist die parasympathische Wirkung.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-064","thema":"Q2.1","kapitel":"Biologische Anpassungen","q":"Gib einen Überblick über die Wirkungen des Ausdauertrainings auf den Organismus (Tab. 12.9).","a":"• Herz-Kreislauf: größeres Herz, mehr SV/HMV, niedriger Ruhepuls, Kapillarisierung, größere AVDO2\n• Muskel: mehr Mitochondrien, Enzyme, Glykogen-/Fettspeicher, Myoglobin\n• Blut: mehr Erythrozyten, Plasma, Pufferkapazität\n• Atmung: tiefer, größeres AMV\n• Nerven: Parasympathikus ↑","e":"Eselsbrücke „HMBLN“: Herz, Muskel, Blut, Lunge, Nerven. Dazu gehören auch eine verbesserte O2-Aufnahme, ein stabiler Blutdruck, eine höhere Vitalkapazität und die beruhigende Wirkung aufs Nervensystem. Beispiel: Ein Halbjahr regelmäßiges Joggen senkt den Ruhepuls, macht die Treppe leichter und verbessert den Schlaf – alles Folgen dieser Anpassungen.","quelle":"L12.5","typ":"kern"},{"id":"q2.1-065","thema":"Q2.1","kapitel":"Methodenüberblick","q":"Nenne die drei Hauptmethoden des Ausdauertrainings und erläutere, wodurch sie sich unterscheiden.","a":"Unterschied: Pausengestaltung\n• Dauermethode: ohne Pause\n• Intervallmethode: unvollständige, „lohnende“ Pause\n• Wiederholungsmethode: vollständige Pause","e":"Merke: Keine Pause – lohnende Pause – volle Pause. Bei der Intervallmethode beginnt der nächste Reiz im nicht vollständig erholten Zustand, bei der Wiederholungsmethode erreicht man vorher etwa den Ausgangszustand. Ergänzend gibt es Wettkampfmethode, Höhentraining und Hügelläufe. Beispiel: 45 Minuten Joggen (Dauermethode), 6 × 800 m mit 2 Minuten Trabpause (Intervallmethode), 3 × 1.000 m mit 10 Minuten Pause (Wiederholungsmethode).","quelle":"L12.6","typ":"kern"},{"id":"q2.1-066","thema":"Q2.1","kapitel":"Methodenüberblick","q":"Welche Belastungsnormative (Belastungskomponenten) werden zur Beschreibung von Ausdauertrainingsmethoden verwendet?","a":"• Intensität: Stärke des einzelnen Reizes\n• Dauer: Dauer des einzelnen Reizes\n• Umfang: Gesamtmenge der Reize\n• Dichte: Verhältnis von Belastung und Pause\n• (Trainingshäufigkeit)","e":"Mit diesen Stellschrauben lässt sich jede Trainingsmethode exakt beschreiben. Die Intensität gibt man z. B. in % der Maximalgeschwindigkeit, als Laktatwert, % HFmax, % VO2max, über das Empfinden oder die Atmung an; den Umfang in km, Wiederholungen oder Gesamtdauer. Beispiel: 5 × 1.000 m (Umfang) in 4:00 min (Dauer) bei 85 % (Intensität) mit 3 Minuten Trabpause (Dichte).","quelle":"L12.6","typ":"kern"},{"id":"q2.1-067","thema":"Q2.1","kapitel":"Dauermethoden","q":"Charakterisiere die Dauermethode und ihre Belastungskomponenten.","a":"Lang andauernde, gleichmäßige Belastung ohne Pause.\n• Intensität: sehr gering (extensiv, AS) bis Wettkampftempo (intensiv, ANS)\n• Umfang: sehr groß\n• Dauer: ca. 20 min bis 1,5 h und mehr","e":"Die Dauermethode ist das klassische „lange Laufen“ ohne Stopp; extensiv ist sie rein aerob. Beispiel: Ein 60-minütiger lockerer Lauf im Wald am Sonntag oder ein 30-minütiger zügiger Tempodauerlauf.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-068","thema":"Q2.1","kapitel":"Dauermethoden","q":"Wie werden die Dauermethoden untergliedert?","a":"• Kontinuierliche DM (gleichmäßig): extensiv / intensiv\n• Variable DM (wechselnd): Wechselmethode (planmäßig) / Fahrtspiel (unplanmäßig)","e":"Erst fragt man: gleichmäßiges oder wechselndes Tempo? Dann: wie intensiv bzw. geplant oder spontan (z. B. geländeabhängig, lustbetont)? Der Übergang von der variablen DM zur Intervallmethode ist fließend. Beispiel: Wechselmethode = jeden zweiten Kilometer schneller nach Plan; Fahrtspiel = im Wald spontan den Hügel hochsprinten, dann wieder locker traben.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-069","thema":"Q2.1","kapitel":"Dauermethoden","q":"Welche Belastungsnormative kennzeichnen die extensive kontinuierliche Dauermethode?","a":"• Intensität: 60–80 % vmax; ca. 2 mmol/l (AS); 65–75 % HFmax; leicht bis mittel\n• Dauer: 30 min bis mehrere Stunden\n• Umfang: 5–30 km\n• Dichte: ohne Pause","e":"Weitere Intensitätsangaben: 45–70 % VO2max, Nasenatmung, 6–8 Schritte pro Atemzyklus („Laufen ohne Schnaufen“). Wirkung: Ökonomisierung des Herz-Kreislauf-Systems, bessere Durchblutung, Ausbau von aerober Glykolyse und Lipolyse, bessere Regeneration. Die extensive DM ist das Fundament: locker, lang, gesprächstauglich. Beispiel: 75 Minuten ruhiger Lauf, bei dem man sich mit der Trainingspartnerin unterhalten kann.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-070","thema":"Q2.1","kapitel":"Dauermethoden","q":"Welche Belastungsnormative kennzeichnen die intensive kontinuierliche Dauermethode?","a":"• Intensität: 80–90 % vmax; ca. 3–4 mmol/l (ANS); 75–85 % HFmax; mittel bis schwer\n• Dauer: 20–120 min\n• Umfang: 5–20 km\n• Dichte: ohne Pause","e":"Weitere Angaben: 75–85 % VO2max, Nasen- und Mundatmung, 4–6 Schritte pro Atemzyklus. Wirkung: bessere Kapillarisierung, Herzvergrößerung, höhere VO2max, bessere Ausschöpfung der Glykogenspeicher und besserer Laktatabbau. Die intensive DM ist der „Tempodauerlauf“ knapp unter der Schmerzgrenze. Beispiel: 30 Minuten zügiger Lauf an der anaeroben Schwelle, bei dem man nur noch kurze Sätze sprechen kann.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-071","thema":"Q2.1","kapitel":"Dauermethoden","q":"Welche Belastungsnormative kennzeichnen die variable Dauermethode?","a":"• Formen: Wechselmethode (planmäßig), Fahrtspiel (unplanmäßig)\n• Intensität: 60–90 % vmax; Wechsel zwischen AS und ANS (ca. 1,5–5 mmol/l); leicht bis schwer\n• Dauer: 1–3 h\n• Umfang: 10–30 km\n• Dichte: ohne Pause","e":"Hier wechselt das Tempo ständig, ohne dass man stehen bleibt (HF in aeroben Phasen unter 75 %, in anaeroben 85–90 % HFmax; 4–8 Schritte pro Atemzyklus). Wirkung: bessere Umstellung zwischen anaerober und aerober Glykolyse, Laktatabbau in den ruhigen Phasen, dazu die Effekte der kontinuierlichen DM. Beispiel: Ein Fußballer läuft eine Stunde durch hügeliges Gelände, sprintet die Anstiege hoch und erholt sich im lockeren Trab bergab.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-072","thema":"Q2.1","kapitel":"Dauermethoden","q":"Warum eignet sich das Fahrtspiel besonders für Spielsportler?","a":"• Sportspiele haben wechselnde, unplanmäßige Belastungen – wie das Fahrtspiel.\n• Trainiert die Umstellung aerob ↔ anaerob und den Laktatabbau in Erholungsphasen.","e":"Das Fahrtspiel bildet den unregelmäßigen Rhythmus eines Spiels nach. Zur reinen Grundlagenausdauer nimmt man dagegen eher kontinuierliche DM; Individualsportler mit gutem Tempogefühl bevorzugen kontinuierliche DM und Wechselmethode. Beispiel: Ein Handballteam läuft durch den Wald, auf Zuruf des Trainers wird bis zum nächsten Baum gesprintet, dann wieder getrabt.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-073","thema":"Q2.1","kapitel":"Intervallmethoden","q":"Charakterisiere die Intervallmethode und erkläre den Begriff „lohnende Pause“.","a":"Wechsel von Belastung und unvollständiger Pause.\nLohnende Pause: keine vollständige Erholung; nächste Belastung, sobald man sie sich wieder zutraut (HF ca. 120–130).\n• Extensive IM: geringere Intensität, höherer Umfang\n• Intensive IM: höhere Intensität, geringerer Umfang","e":"„Lohnend“ heißt: Die ersten Erholungsminuten sind am effektivsten, danach lohnt sich das Warten kaum noch. Der Puls bleibt deutlich über dem Ausgangswert (oft auch bis 140, je nach Trainingszustand und Strecke). Ziel extensiv: aerobe Glykolyse; intensiv: gemischte aerob-anaerobe Glykolyse. Beispiel: Nach einem 400-m-Lauf trabt man locker, bis der Puls auf ca. 125 gesunken ist, und startet dann den nächsten Lauf.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-074","thema":"Q2.1","kapitel":"Intervallmethoden","q":"Welche Belastungskomponenten kennzeichnen die Intervallmethode allgemein (Abb. 12.14)?","a":"• Intensität: extensiv 60–80 %, intensiv 80–90 %\n• Pause: unvollständig (lohnend)\n• Dauer: ca. 15 s – 10 min pro Reiz\n• Umfang: abhängig von der Reizdauer","e":"Die Intervallmethode deckt eine große Spannbreite ab. Die extensive Form verbessert die aerobe, die intensive die aerob-anaerobe Energiebereitstellung. Beispiel: 10 × 200 m zügig (intensiv) oder 4 × 2.000 m im mittleren Tempo (extensiv).","quelle":"L12.6","typ":"kern"},{"id":"q2.1-075","thema":"Q2.1","kapitel":"Intervallmethoden","q":"Welche Belastungsnormative kennzeichnen die extensive Intervallmethode (für Spielsportler nach Steinhöfer)?","a":"• Intensität: 60–80 % vmax; Laktat 3–4 mmol/l; 85–90 % HFmax\n• Dauer: 30–180 s\n• Umfang: hoch, z. B. 4 Serien à 5; 45–60 min\n• Pausen: 45–120 s; Serienpause 5 min","e":"Viele, eher lockere Intervalle mit kurzen Pausen. Wirkung: Sportherzentwicklung, Kapillarisierung, Verbesserung der aeroben Glykolyse und der Laktatelimination. Beispiel: 4 Serien à 5 × 1 Minute zügiges Laufen mit jeweils 1 Minute Trabpause und 5 Minuten Pause zwischen den Serien.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-076","thema":"Q2.1","kapitel":"Intervallmethoden","q":"Welche Belastungsnormative kennzeichnen die intensive Intervallmethode (für Spielsportler nach Steinhöfer)?","a":"• Intensität: 80–90 % vmax; Laktat 4–8 mmol/l; ca. 90 % HFmax\n• Dauer: 15–120 s\n• Umfang: mittel, z. B. 2–3 Serien à 3–4; 30–45 min\n• Pausen: 1–3 min; Serienpause 5 min","e":"Weniger, dafür härtere Intervalle mit längeren Pausen. Wirkung: Herzvergrößerung, Aktivierung der gemischten anaerob-aeroben Energiebereitstellung aus Glykogen, Laktatproduktion (in ST-Fasern). Beispiel: Ein Basketballer sprintet ca. 100 m (3,5 Feldlängen) in 17–20 s, 3–5 Serien à 3–5 Läufe, mit 40 s Wurfpause und 5 Minuten aktiver Serienpause.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-077","thema":"Q2.1","kapitel":"Intervallmethoden","q":"Wie wirkt die Intervallmethode auf das Herz?","a":"• Belastung: Druckarbeit → Hypertrophie des Herzmuskels\n• Lohnende Pause: Volumenarbeit → Dilatation der Herzhöhlen\n(doppelte Wirkung, Weineck)","e":"Das Herz bekommt in der Belastung „Krafttraining“ (Verdickung) und in der Pause „Dehntraining“ (Erweiterung). Beispiel: Gerade in den ersten Sekunden nach einem schnellen 400-m-Lauf pumpt das Herz besonders viel Blut pro Schlag – das weitet die Kammern.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-078","thema":"Q2.1","kapitel":"Intervallmethoden","q":"Bewerte die Eignung der extensiven und intensiven Intervallmethode für Sportspieler.","a":"• Extensive IM: für Sportspieler weitgehend verzichtbar\n• Intensive IM: gut geeignet, entspricht der intervallartigen Spielbelastung (gemischt anaerob-aerob)\n• Aber: erfordert viel Erfahrung bei der Dosierung, nicht für Unerfahrene","e":"Früher galten Intervallmethoden als „die“ Ausdauermethoden; heute favorisieren v. a. Individualsportler kontinuierliche Dauerbelastungen. Die intensive IM ähnelt der Spielbelastung, muss aber sehr genau dosiert werden. Beispiel: Ein Jugendtrainer ohne Erfahrung sollte mit seinem Team lieber Fahrtspiele machen als harte Sprintintervalle, um Überlastung zu vermeiden.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-079","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Charakterisiere die Wiederholungsmethode und ihre Belastungskomponenten (Abb. 12.15).","a":"• Vollständige Pause (Rückkehr zum Ausgangszustand)\n• Sehr hohe Intensität (ca. 80/90–100 %)\n• Dauer ca. 15 s – 3 min, geringer Umfang\n• Ziel: anaerobe Energiebereitstellung (Glykolyse bzw. Phosphate), auch Schnelligkeit","e":"Wenige Läufe, jeder fast im Wettkampftempo – die hohe Intensität ist nur durch die langen Pausen möglich. Belastungen von ca. 45–180 Sekunden trainieren die anaerobe Glykolyse, solche von 15–20 Sekunden die Phosphatspeicher (alaktazid). Beispiel: 3 × 600 m mit 10 Minuten Pause für einen 800-m-Läufer.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-080","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Welche drei Formen der Wiederholungsmethode unterscheiden Grosser und Zintl und durch welche Belastungsnormative sind sie gekennzeichnet?","a":"• Langzeitintervalle: 75–90 %, 2–3 min, 3–5 Wdh., Pause 10–12 min → anaerobe Glykolyse\n• Mittelzeitintervalle: 80–90 %, 45–60 s, 4–6 Wdh., Pause 8–10 min → anaerobe Glykolyse, Laktattoleranz\n• Kurzzeitintervalle: 90–100 %, 15–20 s, 6–8 Wdh., Pause 7–10 min → anaerob-alaktazid","e":"Je kürzer der Lauf, desto höher die Intensität und desto mehr Wiederholungen. Die LZI verbessern die Laktattoleranz bei mittleren Konzentrationen, die KZI fördern zusätzlich eine schnelle Laktatproduktion. Beispiel: 4 × 1.000 m in 3:30 min mit 10 Minuten aktiver Pause (LZI) – so bereitet sich ein Basketballer in der Saisonvorbereitung vor.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-081","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Welche Bedeutung hat die Wiederholungsmethode für Spielsportler?","a":"• Für die Ausdauer eher untergeordnet: lange Tempoläufe entsprechen nicht dem Spielprofil (Steinhöfer)\n• Aber: steigert Willenskraft, Leistungsbereitschaft und Belastungsverträglichkeit → z. B. in der Saisonvorbereitung sinnvoll","e":"Besser geeignet ist die WM für leichtathletische Mittel- und Langstreckenläufer. Fürs Spiel selbst passt sie nicht perfekt, für den Kopf aber sehr (pädagogisch-psychologische Wirkung). Beispiel: Ein Basketballteam läuft in der Vorbereitung 4 × 1.000 m auf Zeit – das stärkt den „Biss“ für enge Spielphasen.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-082","thema":"Q2.1","kapitel":"Methodenüberblick","q":"Beschreibe die Dauer-, Intervall- und Wiederholungsmethode als Intensitäts-Zeit-Verlauf.","a":"• Dauermethode: durchgehende Linie ohne Unterbrechung\n• Extensive IM: viele niedrige Blöcke, kurze Pausen\n• Intensive IM: weniger, höhere Blöcke, etwas längere Pausen\n• Wiederholungsmethode: wenige sehr hohe Blöcke, sehr lange Pausen","e":"Stell dir die Methoden als Diagramm vor: eine lange flache (oder wellige) Linie, viele kleine Treppchen, einige höhere Treppchen und wenige hohe Türme mit großen Lücken. Beispiel: Im Abi wird oft verlangt, eine solche Skizze einer Methode zuzuordnen.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-083","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Charakterisiere die Wettkampfmethode.","a":"• Komplexeste Methode: schult alle sportartspezifischen Fähigkeiten zugleich\n• Trainings- und Aufbauwettkämpfe\n• Einmalige Belastung mit höchster Intensität\n• Hohe Motivation durch Wettkampfcharakter","e":"Der Wettkampf ist das ehrlichste Training, weil alles gleichzeitig gefordert ist und wettkampfgemäße Funktionszustände erreicht werden. Die Anstrengungsbereitschaft ist höher als im normalen Training. Beispiel: Ein Basketball-Jugendtrainer nutzt Turniere und Freundschaftsspiele, um spielspezifische Ausdauer zu schulen und gleichzeitig eine neue Pressverteidigung einzuüben.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-084","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Erörtere, was für und gegen häufige Freundschaftsspiele zur Entwicklung der sportspielspezifischen Ausdauer spricht.","a":"Pro:\n• spielspezifische Belastung\n• hohe Motivation\n• Technik, Taktik, Psyche unter Belastung\nContra:\n• schwer dosierbar, individuell ungleich\n• keine gezielte Grundlagenausdauer\n• Überlastungs-/Verletzungsrisiko\nFazit: Ergänzung, kein Ersatz","e":"Freundschaftsspiele sind spezifisch (Belastungswechsel, Sprints, Sprünge) und motivierend, aber kein präzises Werkzeug; bei zu vielen Spielen fehlt zudem die Regeneration. Beispiel: Ein Ersatzspieler, der nur 10 Minuten spielt, bekommt kaum Ausdauerreiz, während der Spielmacher 40 Minuten voll belastet wird.","quelle":"L12.6","typ":"zusatz"},{"id":"q2.1-085","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Beschreibe Wirkung und Besonderheit des Höhentrainings.","a":"• O2-Mangel in der Höhe → Vermehrung der Erythrozyten → bessere O2-Transportkapazität\n• Danach im Flachland höhere Ausdauerleistung möglich\n• Besonderheit: Erythrozyten nehmen stärker zu als Plasma → Hämatokrit steigt","e":"Wegen des geringeren O2-Partialdrucks ist das Blut schlechter mit Sauerstoff gesättigt; der Körper reagiert mit mehr roten Blutkörperchen – die größte relative Zunahme aller Ausdauermethoden. Anders als beim Flachlandtraining (v. a. mehr Plasma) dickt das Blut dadurch ein. Beispiel: Viele Langstreckenläufer trainieren mehrere Wochen in Höhenlagen wie St. Moritz oder in Kenia, bevor sie im Flachland Wettkämpfe laufen.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-086","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Welche Wirkung haben Hügelläufe in Abhängigkeit von der Streckenlänge?","a":"• Steigung ca. 10–15 %; gut für spezielle Ausdauer\n• ca. 150 m: anaerobe Kapazität ↑\n• über 400 m: aerobe Kapazität und VO2max ↑\n• Zusätzlich Kräftigung von Waden- und Hüftbeugemuskulatur","e":"Kurze Hügel = anaerob (stärkerer Milchsäureanstieg), lange Hügel = aerob. Der Kohlenhydratstoffwechsel wird intensiv beansprucht; die Waden arbeiten durch die verstärkte Fußstreckung, die Hüftbeuger durch den höheren Kniehub. Beispiel: Ein Fußballteam sprintet in der Vorbereitung 8 × 150 m einen steilen Hang hoch, um die anaerobe Kapazität zu verbessern.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-087","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Erläutere die Trainingspyramide zum Ausdauertraining.","a":"• Basis: umfangsbetontes aerobes Training\n• Mitte: gemischt aerob-anaerob\n• Spitze: intensitätsbetontes anaerobes Training\nGrundsatz: Je anaerober, desto geringer der Umfang; aerobes Training ist Voraussetzung.","e":"Wie bei einer echten Pyramide: Ohne breites Fundament trägt die Spitze nicht. Zur Basis gehören extensive Dauer- und Intervallmethode, zur Spitze intensive Dauer- und Intervallmethode sowie die Wiederholungsmethode. Beispiel: Ein Schüler, der für den 5.000-m-Lauf im Abi trainiert, macht zuerst viele lockere Dauerläufe und erst in den letzten Wochen kürzere, schnellere Intervalle.","quelle":"L12.6","typ":"kern"},{"id":"q2.1-088","thema":"Q2.1","kapitel":"Weitere Methoden","q":"Welche Ausdauertrainingsmethoden eignen sich besonders zur Verbesserung der basketballspezifischen Ausdauer? Begründe.","a":"• Extensive kontinuierliche DM: aerobe Basis für schnelle Erholung\n• Fahrtspiel: unplanmäßige Belastungswechsel, Umstellung aerob/anaerob\n• Intensive IM: entspricht intervallartiger Spielbelastung\n• Spielnahe Formen/Wettkampfmethode: spezifisch, motivierend","e":"Basketball verlangt kurze, harte Aktionen mit schneller Erholung – also eine aerobe Basis (Laktatabbau, Wiederauffüllen der Phosphatspeicher) plus spielnahe intensive Intervalle (Laktat 4–9 mmol/l). Spielnahe Formen sind z. B. 1:1 oder 3:3 mit Belastungsvorgaben. Die Wiederholungsmethode spielt nur eine Nebenrolle (psychische Wirkung, Vorbereitungsphase). Beispiel: 3–5 Serien à 3–5 Sprints über 100 m mit 40 Sekunden Freiwurf-Pause.","quelle":"L12.7","typ":"zusatz"},{"id":"q2.1-089","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Definiere den Begriff sportmotorischer Test.","a":"Sportmotorische Tests sind wissenschaftliche Prüfverfahren unter standardisierten Bedingungen, die möglichst genaue (quantitative) Aussagen über die Ausprägung sportmotorischer Merkmale liefern (nach Lienert).","e":"Ein Test ist mehr als „mal schauen, wie gut jemand ist“ – er ist ein genau geregeltes Messverfahren, das festgelegten Kriterien genügen muss. Umgangssprachlich heißt jede Leistungsüberprüfung „Test“, das ist irreführend. Beispiel: Der Cooper-Test mit festgelegter Dauer, Strecke und Messung ist ein Test; ein lockeres „Lauf mal ein paar Runden“ nicht.","quelle":"L16.1","typ":"kern"},{"id":"q2.1-090","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Welche Merkmale muss ein sportmotorischer Test laut Definition erfüllen?","a":"• Standardisierung (gleiche, reproduzierbare Bedingungen)\n• Erfassung abgrenzbarer Merkmale\n• Möglichst quantitative Ergebnisse\n• Einordnung in Ergebnisse von Bezugsgruppen","e":"Kurz: gleiche Bedingungen, klares Merkmal (z. B. Sprungkraft, Wurfgenauigkeit), Zahlenwert (Häufigkeiten, Entfernungen, Zeiten), Vergleichbarkeit. Beispiel: Beim Standweitsprung sind Absprunglinie, Messverfahren und Anzahl der Versuche festgelegt, gemessen wird in cm und man kann das Ergebnis mit Normtabellen vergleichen.","quelle":"L16.1","typ":"kern"},{"id":"q2.1-091","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Nenne die Haupt- und Nebengütekriterien sportmotorischer Tests.","a":"Hauptgütekriterien:\n• Objektivität\n• Reliabilität\n• Validität\nNebengütekriterien:\n• Normierung\n• Vergleichbarkeit\n• Ökonomie\n• Nützlichkeit","e":"Eselsbrücke für die Hauptgütekriterien: „ORV“ – Objektiv, Reliabel, Valide. Sie sind unverzichtbar, die Nebengütekriterien nur eine „bedingte Forderung“. Beispiel: Ein Ausdauertest muss vom Prüfer unabhängig, wiederholbar genau und wirklich ausdauermessend sein; dass er wenig Zeit kostet (Ökonomie), ist schön, aber zweitrangig.","quelle":"L16.1","typ":"kern"},{"id":"q2.1-092","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Definiere das Gütekriterium Objektivität.","a":"Objektivität ist der Grad der Unabhängigkeit des Testergebnisses vom Untersucher: Verschiedene Beurteiler kommen zum gleichen Ergebnis.","e":"Objektiv heißt: Egal wer misst, es kommt dasselbe heraus. Tester dürfen durch Sprache, Mimik oder Gestik (z. B. motivierende Ansprache) keinen Einfluss nehmen. Stoppuhr, Maßband oder Lichtschranke sind hochgradig objektiv, subjektive Bewertungen (z. B. Haltungsnoten) meist wenig. Beispiel: Eine Turnübung, die von einer Lehrerin nach Gefühl benotet wird, ist weniger objektiv als ein 100-m-Lauf mit Lichtschranke.","quelle":"L16.1","typ":"kern"},{"id":"q2.1-093","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Definiere das Gütekriterium Reliabilität und nenne ein Verfahren zu ihrer Bestimmung.","a":"Reliabilität ist der Grad der Genauigkeit, mit der ein Merkmal bei wiederholter Durchführung gemessen wird (Zufallsunabhängigkeit).\nBestimmung: Test-Retest-Methode","e":"Reliabel heißt: Bei mehrmaliger Durchführung kommt das gleiche Ergebnis heraus. Beim Test-Retest wird der Test wiederholt und die Übereinstimmung mit den ersten Ergebnissen bestimmt. Erhöhen lässt sich die Reliabilität z. B. durch mehr Versuche (Gesetz der großen Zahlen). Beispiel: Eine Schützin, die nur zwei Schüsse hat, kann zufällig zweimal treffen oder zweimal danebenschießen – bei 50 Schüssen nähert sich das Ergebnis ihrer echten Trefferquote.","quelle":"L16.1","typ":"kern"},{"id":"q2.1-094","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Definiere das Gütekriterium Validität und begründe, warum es das wichtigste Hauptgütekriterium ist.","a":"Validität ist der Grad der Sicherheit, mit der ein Test das zu prüfende Merkmal tatsächlich erfasst.\nWichtigstes Kriterium: Ein objektiver und reliabler Test ist nutzlos, wenn er nicht misst, was er messen soll.","e":"Valide heißt: Der Test misst das, was er messen soll. Die Validität sinkt z. B., wenn ein Ausdauertest stark von Technik oder Koordination abhängt. Beispiel: Ein Ausdauertest im Skilanglauf in Skatingtechnik misst bei einem Läufer mit schlechter Technik eher dessen Technikdefizit als seine Ausdauer.","quelle":"L16.1","typ":"kern"},{"id":"q2.1-095","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Welche Funktion haben sportmotorische Tests im Trainingsprozess? Unterscheide intra- und interindividuellen Vergleich.","a":"Funktion: Ist-Soll-Vergleich zur Trainingsplanung und -steuerung.\n• Intraindividuell: Vergleich mit eigenen früheren Leistungen\n• Interindividuell: Vergleich mit anderen (Bezugsgruppe, Normen)","e":"„Intra“ = innerhalb einer Person, „inter“ = zwischen Personen. Der Ist-Soll-Vergleich ist kurz-, mittel- und langfristig möglich. Beispiel: Ein Schüler vergleicht seinen Cooper-Test im Mai mit dem vom Januar (intraindividuell) oder mit dem Kursdurchschnitt (interindividuell).","quelle":"L16.1","typ":"kern"},{"id":"q2.1-096","thema":"Q2.1","kapitel":"Sportmotorische Tests","q":"Beschreibe je eine Überprüfungsform, bei der genau ein Hauptgütekriterium unzureichend erfüllt ist.","a":"• Objektivität: Bodenturnen nach freiem Eindruck einer Lehrkraft bewertet\n• Reliabilität: Freiwurftest mit nur zwei Würfen\n• Validität: 400-m-Lauf als Test der aeroben Ausdauer","e":"Man muss jeweils nur ein Kriterium „kaputt machen“: Ein zweiter Beurteiler käme beim Turnen zu anderen Noten; bei zwei Würfen hängt das Ergebnis vom Zufall ab; der 400-m-Lauf misst überwiegend die anaerobe Leistungsfähigkeit. Beispiel: Beim Freiwurftest mit zwei Würfen ist die Zählung objektiv und es geht klar um Wurfgenauigkeit (valide) – nur die geringe Versuchszahl macht ihn unzuverlässig.","quelle":"L16.1","typ":"zusatz"},{"id":"q2.1-097","thema":"Q2.1","kapitel":"Ausdauertests","q":"Unter welchen Bedingungen sind der 12-Minuten-Lauf und der 6-Minuten-Lauf gute Überprüfungsformen der aeroben Ausdauer?","a":"12 min für Ausdauertrainierte, 6 min für weniger Trainierte, jeweils bei:\n• gleicher (höchster) Motivation\n• gleichen Rahmenbedingungen (Wetter, Ernährung, Vorbelastung)\n• gleichmäßigem Tempo (kein Endspurt)","e":"Nur wenn alle Bedingungen gleich sind, sind die Ergebnisse vergleichbar. Beispiel: Wer den Cooper-Test einmal bei 30 °C nach einem Fußballspiel und einmal ausgeruht bei 15 °C läuft, kann die Ergebnisse nicht sinnvoll vergleichen.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-098","thema":"Q2.1","kapitel":"Ausdauertests","q":"Beschreibe den Cooper-Test und seine Aussagekraft.","a":"• 12-Minuten-Lauf: möglichst weite Strecke bei gleichmäßigem Tempo\n• Häufigster Test der aeroben Leistungsfähigkeit; erfüllt bei richtiger Durchführung die Gütekriterien\n• Laufleistung korreliert mit der VO2max (Cooper 1968)","e":"Beim Cooper-Test zählt die Strecke, nicht die Zeit. Bei weniger Trainierten ist die Energie zu ca. 90 % aerob, die mittlere Laufgeschwindigkeit korreliert sehr hoch mit der ANS. Trainierte laufen dagegen weit über der ANS, also mit beträchtlichem anaeroben Anteil. Beispiel: In Baden-Württemberg brauchte man im Abitur (2019) laut Tabelle etwa 2.675 m bzw. 3.175 m (je nach Tabelle/Geschlecht) für 15 Punkte.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-099","thema":"Q2.1","kapitel":"Ausdauertests","q":"Warum ist der Cooper-Test im Schulsport nur eingeschränkt geeignet?","a":"• Nur für leistungsstarke Schüler geeignet\n• Weniger Trainierte laufen ständig im Bereich der ANS → psychisch sehr belastend, geringe Akzeptanz\n• Alternative: 6-Minuten-Lauf","e":"Zwölf Minuten an der Schwelle zu laufen, ist für Untrainierte eine Qual – und die meisten Schüler sind nur mittelmäßig ausdauertrainiert. Der kürzere 6-Minuten-Lauf eignet sich für Jüngere und weniger Trainierte. Beispiel: In der Grundschule nutzt man deshalb den 6-Minuten-Lauf.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-100","thema":"Q2.1","kapitel":"Ausdauertests","q":"Warum haben 1.000-m-, 3.000-m- und 5.000-m-Läufe als Tests der aeroben Ausdauer eine eingeschränkte Validität?","a":"• Hohe Anstrengung → sie testen eher die gemischte aerob-anaerobe Ausdauer.\n• Je kürzer die Strecke, desto größer der anaerob-laktazide Anteil.","e":"Ein 1.000-m-Lauf auf Zeit ist ein Mittelzeitausdauertest mit viel Laktat – kein reiner Aerob-Test. Ergänzend gilt: In Sportarten mit anderer Fortbewegung (Radfahren, Schwimmen, Skilanglauf) sollte sportartspezifisch getestet werden, da andere Muskelgruppen die Leistung tragen. Beispiel: Ein Schwimmer sollte seine Ausdauer im Becken testen, nicht beim Laufen, sonst misst man eher seine Lauftechnik und Beinmuskulatur.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-101","thema":"Q2.1","kapitel":"Ausdauertests","q":"Beschreibe Zielsetzung und Grundidee des Conconi-Tests.","a":"• Ziel: aerobe Ausdauer bestimmen und anaerobe Schwelle „unblutig“ über die Herzfrequenz ermitteln\n• Idee: HF steigt im aeroben Bereich linear mit der Geschwindigkeit, oberhalb der ANS flacht sie ab (Deflektionspunkt)\n• Je später der Knick, desto besser die aerobe Ausdauer","e":"Der Puls steigt mit dem Tempo erst gleichmäßig (ca. 120–170 Schläge/min), um den steigenden O2-Bedarf zu decken – bis er „abknickt“. Am Deflektionspunkt ist das aerobe System an seiner Grenze, der Mehrbedarf wird anaerob gedeckt. Beispiel: Steigt die Herzfrequenz eines Läufers bis 14 km/h linear an und flacht dann ab, liegt sein Deflektionspunkt bei ca. 14 km/h.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-102","thema":"Q2.1","kapitel":"Ausdauertests","q":"Beschreibe die Durchführung des Conconi-Tests.","a":"• Ca. 5 min einlaufen\n• Start: 72 s pro 200 m (400-m-Bahn)\n• Alle 200 m 2 s schneller (unter 40 s: 1 s)\n• Tempo per Pfiff alle 50 m (Hütchen)\n• Protokollanten notieren Strecke und HF\n• Ende, wenn das Tempo nicht mehr gehalten wird","e":"Das Tempo wird stufenweise schneller, ein Pfiff gibt den Takt vor – wer den Pfiff nicht mehr erreicht, ist raus. Organisatorisch: Alle 200 m eine besondere Markierung, am besten zwei Pfeifer im Wechsel; eine Lauf- und eine Protokollgruppe mit je zwei Protokollanten pro Läufer. Beispiel: Start 72 s/200 m (10 km/h), nach 3.000 m ist man bei 44 s/200 m (ca. 16,4 km/h).","quelle":"L16.2","typ":"kern"},{"id":"q2.1-103","thema":"Q2.1","kapitel":"Ausdauertests","q":"Wie wird der Conconi-Test ausgewertet und wie zeigt sich ein Trainingseffekt?","a":"• HF gegen Laufgeschwindigkeit auftragen; Deflektionspunkt = Abknicken der Linearität\n• Trainingseffekt: Deflektionspunkt verschiebt sich nach rechts; gleiches Tempo bei niedrigerer HF","e":"Rechts ist gut: Wer trainiert, knickt erst bei höherem Tempo ab und läuft dasselbe Tempo mit niedrigerem Puls; nachlassende Ausdauer zeigt sich als Linksverschiebung. Den Deflektionspunkt bestimmt man z. B. als Schnittpunkt zweier Regressionsgeraden; je länger der Kurvenabschnitt danach, desto höher die anaerobe Kapazität. Beispiel: Ein Kind, das nach 40 Tagen Inaktivität (Beinbruch) erneut getestet wird, zeigt einen nach links verschobenen Deflektionspunkt.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-104","thema":"Q2.1","kapitel":"Ausdauertests","q":"Nenne Vor- und Nachteile des Conconi-Tests.","a":"Vorteile:\n• gut für aerobe Ausdauer und Leistungsfortschritt (intraindividuell)\n• unblutig, kostengünstig\n• kurze „Leidensstrecke“, beliebt\nNachteile:\n• organisatorischer Aufwand\n• Deflektionspunkt nicht immer erkennbar, oft ≠ IANS → nur bedingt zur Trainingssteuerung","e":"Der Test ist gut für den Vergleich mit sich selbst, aber unzuverlässig als exakter Schwellenwert, z. B. wenn die Geschwindigkeit nicht linear gesteigert wurde. Die „Leidensstrecke“ ist anders als beim Cooper-Test auf unter 100 m reduziert. Beispiel: Bei manchen Läufern zeigt die Kurve gar keinen Knick – dann kann man aus dem Test keine Trainingsherzfrequenz ableiten.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-105","thema":"Q2.1","kapitel":"Ausdauertests","q":"Beschreibe Durchführung und Ziel des Laktat-Stufen-Tests.","a":"• Ziel: aerobe Leistungsfähigkeit und (individuelle) anaerobe Schwelle bestimmen → Trainingssteuerung\n• Laufband, Ergometer oder Laufstrecke; stufenweise Steigerung bis zur Erschöpfung\n• Nach jeder Stufe Laktat (Ohrläppchen), dazu Herzfrequenz","e":"Man wird nach ca. 5 Minuten Aufwärmen stufenweise härter belastet, und nach jeder Stufe (sowie zu Beginn und am Ende) wird ein Tropfen Blut aus dem Ohr genommen. So lassen sich individuelle Trainingspläne erstellen. Beispiel: Ein Radfahrer tritt 3 Minuten 30 Watt, dann 70, dann 110 Watt usw., bis er nicht mehr kann.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-106","thema":"Q2.1","kapitel":"Ausdauertests","q":"Erläutere das Hollmann-Schema für den Laktat-Stufen-Test auf dem Fahrradergometer.","a":"• Start: 30 Watt\n• Alle 3 min + 40 Watt (30 – 70 – 110 – 150 …)\n• Blutentnahme am Ende jeder Stufe\n• Bis zur völligen Erschöpfung","e":"Das Schema sorgt dafür, dass Tests vergleichbar (standardisiert) sind; Blut wird nach 3, 6, 9, 12 … Minuten abgenommen. Beispiel: Im Labor startete ein 42-jähriger Mann bei 70 Watt und steigerte nach Hollmann-Schema jeweils um 40 Watt.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-107","thema":"Q2.1","kapitel":"Ausdauertests","q":"Wie wird die Laktat-Leistungs-Kurve aus einem Laktat-Stufen-Test interpretiert?","a":"• Laktat steigt erst flach, dann steil an → (individuelle) anaerobe Schwelle\n• Ablesbar: HF an AS (2 mmol/l) und ANS (4 mmol/l) → Trainingsbereiche\n• Rechtsverschiebung = verbesserte Ausdauer","e":"Die Kurve zeigt, ab welchem Tempo der Körper „sauer“ wird. Verschiebt sie sich im Laufe eines Trainingsjahres nach rechts, entsteht bei gleicher Belastung weniger Laktat. Beispiel: Erreicht ein Läufer 4 mmol/l nach einem Jahr Training erst bei 15 statt 13 km/h, hat sich seine aerobe Leistungsfähigkeit verbessert.","quelle":"L16.2","typ":"kern"},{"id":"q2.1-108","thema":"Q2.1","kapitel":"Ausdauertests","q":"Wie werden aus einem Laktat-Stufen-Test Trainingsempfehlungen abgeleitet?","a":"HF an AS (2 mmol/l) und ANS (4 mmol/l) bestimmen:\n• unter AS: Regeneration\n• zwischen AS und ANS: Grundlagenausdauer\n• über ANS: intensives Ausdauertraining\nSportartspezifisch anpassen (Laufen ca. 10 Schläge höher als Rad).","e":"Die Schwellenwerte werden zu persönlichen Pulszonen: Regeneration nutzt v. a. Fette, Grundlagentraining v. a. aerob Kohlenhydrate, über der ANS läuft die anaerobe Glykolyse mit Laktat. Bei Radfahren und Skilanglauf liegt die Trainings-HF ca. 8–10 %, beim Schwimmen ca. 6–7 % unter der beim Laufen. Beispiel: Ein 42-Jähriger erreicht auf dem Rad die AS bei Puls 118 und die ANS bei 154; also: Regeneration unter 118, Grundlagentraining 118–154, intensiv über 154 – beim Laufen jeweils ca. 10 Schläge mehr (128–164).","quelle":"L16.2","typ":"kern"},{"id":"q2.1-109","thema":"Q2.1","kapitel":"Ausdauertests","q":"Vergleiche Cooper-Test, Conconi-Test und Laktat-Stufen-Test hinsichtlich Aufwand und Aussagekraft.","a":"• Cooper: geringer Aufwand, viele gleichzeitig; korreliert mit VO2max; motivationsabhängig, keine Trainingsbereiche\n• Conconi: mittlerer Aufwand, unblutig; gut für Leistungsfortschritt; Schwelle unsicher\n• Laktat-Stufen-Test: hoher Aufwand; präziseste Schwellenbestimmung, ideal zur Trainingssteuerung","e":"Je genauer der Test, desto aufwendiger ist er. Der Cooper-Test ist zudem psychisch belastend und tempoabhängig; beim Conconi-Test ist der Deflektionspunkt nicht immer erkennbar und nicht immer gleich der IANS; der Laktattest braucht Labor, Blutentnahme und Geld. Beispiel: Für einen ganzen Kurs eignet sich der Cooper-Test, für den Profi-Triathleten der Laktat-Stufen-Test im Labor.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.2-001","thema":"Q2.2","kapitel":"Kraftbegriff und Arbeitsweisen","q":"Definiere Kraft im Sport (biologische Definition).","a":"Fähigkeit des neuromuskulären Systems, durch Innervations- und Stoffwechselprozesse mit Muskelkontraktionen > 30 % des Kraftmaximums Widerstände zu überwinden (konzentrisch), ihnen entgegenzuwirken (exzentrisch) oder sie zu halten (isometrisch). (Grosser & Zintl; Steinhöfer; Harre)","e":"Kraft ist im Sport nicht nur Physik, sondern das Zusammenspiel von Nerven (Innervation) und Muskeln (Stoffwechsel). Erst ab etwa 30 % des Maximums spricht man von Kraft, darunter eher von Ausdauer. Beispiel: Beim Klimmzug überwindest du dein Körpergewicht (hochziehen), hältst es (oben verharren) und bremst es (herablassen) – alles sind Kraftleistungen.","quelle":"L13.1","typ":"kern"},{"id":"q2.2-002","thema":"Q2.2","kapitel":"Kraftbegriff und Arbeitsweisen","q":"Grenze den physikalischen vom biologischen Kraftbegriff ab.","a":"• Physikalisch: F = m · a (2. Newtonsches Axiom); für die Biomechanik\n• Biologisch: Fähigkeit des neuromuskulären Systems, Widerstände zu überwinden, ihnen entgegenzuwirken oder sie zu halten (> 30 % des Kraftmaximums); für die Trainingslehre","e":"Die Trainingslehre nutzt vor allem den biologischen Begriff, weil er die trainierbaren Voraussetzungen (Nerven, Muskeln) beschreibt. Die Physik fragt: Wie groß ist die Kraft, die wirkt? Die Trainingslehre fragt: Was kann der Körper leisten und wie verbessert man das? Beispiel: Ein Biomechaniker misst beim Sprint die Bodenreaktionskraft in Newton, ein Trainer überlegt, wie er die Beinstrecker des Sprinters kräftiger macht.","quelle":"L13.1","typ":"kern"},{"id":"q2.2-003","thema":"Q2.2","kapitel":"Kraftbegriff und Arbeitsweisen","q":"Nenne und beschreibe die drei Arbeitsweisen eines Skelettmuskels.","a":"• Isometrisch (statisch-haltend): Spannung ohne Längenänderung\n• Konzentrisch (positiv-dynamisch, überwindend): Spannung mit Verkürzung\n• Exzentrisch (negativ-dynamisch, nachgebend): Spannung bei Verlängerung, Bewegung wird gebremst","e":"Konzentrische und exzentrische Arbeit zusammen nennt man dynamische Arbeit. Bei konzentrischer Arbeit wird der Muskel kürzer, dicker und härter. Merke: konzentrisch = zum Zentrum hin, exzentrisch = vom Zentrum weg (Muskel wird lang, bremst aber). Beispiel Klimmzug: Hochziehen = Bizeps konzentrisch, oben halten = isometrisch, langsam herablassen = Bizeps exzentrisch.","quelle":"L13.1","typ":"kern"},{"id":"q2.2-004","thema":"Q2.2","kapitel":"Kraftbegriff und Arbeitsweisen","q":"Beschreibe anhand des Muskelmodells (Tab. 13.1), was bei isometrischer, konzentrischer und exzentrischer Arbeitsweise mit kontraktilen Elementen, elastischen Elementen, Muskellänge und Muskelspannung passiert.","a":"• Isometrisch: KE kontrahieren, EE gedehnt; Länge gleich\n• Konzentrisch: KE kontrahieren, EE gedehnt; Muskel verkürzt\n• Exzentrisch: KE und EE gedehnt; Muskel verlängert\n→ Spannung nimmt immer zu\n(KE = kontraktile, EE = elastische Elemente)","e":"Stell dir den Muskel als Motor (kontraktile Elemente) mit Gummiband (elastische Elemente, z. B. Sehne) vor. Bei der isometrischen Arbeit zieht der Motor, das Gummiband dehnt sich, aber nach außen bewegt sich nichts. Beispiel: Zwei Sportler drücken beim Armdrücken gleich stark – beide Bizepse arbeiten isometrisch. Drückt der rechte stärker, arbeitet sein Bizeps konzentrisch und der des linken exzentrisch.","quelle":"L13.1","typ":"kern"},{"id":"q2.2-005","thema":"Q2.2","kapitel":"Kraftbegriff und Arbeitsweisen","q":"Erkläre, warum isometrische Haltearbeit zeitlich begrenzt ist.","a":"• Spannung ohne Verkürzung → Kapillaren dauerhaft zusammengepresst\n• Durchblutung stark eingeschränkt: wenig O₂/Nährstoffe, schlechter Abtransport von Stoffwechselprodukten\n• → schnelle Ermüdung","e":"Bei isometrischer Arbeit wird der Muskel härter und leicht dicker, so drückt er die Gefäße ab. Bei dynamischer Arbeit wirkt er dagegen wie eine Pumpe (Muskelpumpe) – statisch ist er wie ein geknickter Gartenschlauch. Beispiel: Wer beim Klimmzug oben hängen bleibt, spürt nach wenigen Sekunden ein starkes Brennen in den Armen.","quelle":"L13.1","typ":"kern"},{"id":"q2.2-006","thema":"Q2.2","kapitel":"Kraftbegriff und Arbeitsweisen","q":"Wann spricht man von dynamischer Muskelarbeit?","a":"Wenn der Muskel konzentrisch und/oder exzentrisch arbeitet, sich also seine Länge ändert (Gegensatz: statisch/isometrisch).","e":"Dynamisch heißt: Es bewegt sich etwas. Beispiel: Eine Kniebeuge ist dynamisch – beim Runtergehen arbeiten die Oberschenkelstrecker exzentrisch, beim Hochdrücken konzentrisch. Eine Wandsitz-Übung (Stuhl ohne Stuhl) ist dagegen statisch.","quelle":"L13.1","typ":"kern"},{"id":"q2.2-007","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere Maximalkraft.","a":"Höchstmögliche Kraft, die das neuromuskuläre System bei maximaler willkürlicher Kontraktion gegen einen Widerstand entfalten kann (statisch, konzentrisch oder exzentrisch).","e":"Die Maximalkraft ist die Basisfähigkeit für alle anderen Kraftarten (Schnellkraft, Reaktivkraft, Kraftausdauer). Sie hängt v. a. von Muskelquerschnitt, Faserzusammensetzung und intramuskulärer Koordination ab. Beispiel: Das schwerste Gewicht, das ein Gewichtheber genau einmal zur Hochstrecke bringt, zeigt seine Maximalkraft. Auch Hochspringer, Basketballer (Rebound) und Fußballer (Kopfball) brauchen viel Maximalkraft in der Beinstreckerkette.","quelle":"L13.2","typ":"zusatz"},{"id":"q2.2-008","thema":"Q2.2","kapitel":"Kraftarten","q":"Was versteht man unter der willkürlichen neuromuskulären Aktivierungsfähigkeit?","a":"= intramuskuläre Koordination: Vermögen, möglichst viele motorische Einheiten gleichzeitig hochfrequent zu innervieren (Boeckh-Behrens & Buskies). Maß: Kraftdefizit.","e":"Sie ist eine wichtige Komponente der Maximalkraft. Ein Muskel besteht aus vielen motorischen Einheiten; Untrainierte können nur einen Teil davon gleichzeitig „anschalten“. Wer seine Aktivierungsfähigkeit verbessert, holt mehr aus dem gleichen Muskel heraus. Beispiel: Ein schlanker Kletterer kann erstaunlich viel Kraft entwickeln, weil er seine Muskeln fast vollständig aktivieren kann.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-009","thema":"Q2.2","kapitel":"Kraftarten","q":"Vergleiche statische, konzentrische und exzentrische Maximalkraft und begründe die Unterschiede.","a":"konzentrisch < statisch < exzentrisch\n• Konzentrisch: zusätzlich Beschleunigungsarbeit nötig\n• Exzentrisch: zusätzliche reflektorische Kraft durch Dehnungsreflex (Muskelspindel)","e":"Die statische Maximalkraft ist die höchste willkürliche Haltekraft. Konzentrisch ist sie geringfügig niedriger, weil neben der Gegenkraft zur Last noch Kraft für die Beschleunigung gebraucht wird. Exzentrisch (Dehnung eines maximal kontrahierten Muskels) ist sie deutlich höher. Bremsen kann man mehr als heben. Beispiel: Eine Hantel, die du beim Bankdrücken nicht mehr hochdrücken kannst, kannst du oft noch kontrolliert herablassen.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-010","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere das Kraftdefizit und erläutere seine Bedeutung.","a":"• Differenz zwischen exzentrischer und statischer Maximalkraft (Grosser & Zintl)\n• Untrainierte 10–40 %, Trainierte ≤ 5 %\n• Maß für die intramuskuläre Koordination; wird durch IK-Training kleiner","e":"Je kleiner das Kraftdefizit, desto mehr vom vorhandenen Kraftpotenzial kann willkürlich genutzt werden. Die exzentrische Maximalkraft zeigt ungefähr, was im Muskel steckt; die statische, was man willentlich abrufen kann. Die Lücke ist ungenutztes Potenzial. Beispiel: Ein Anfänger mit 30 % Kraftdefizit kann durch IK-Training stark an Kraft gewinnen, ohne dass sein Muskel dicker wird.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-011","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere Absolutkraft und erläutere, woraus sie sich zusammensetzt und wie sie gemessen wird.","a":"• Höchstes Kraftpotenzial eines Muskels aufgrund von Querschnitt und Qualität\n• = willkürliche Maximalkraft + autonom geschützte Reserve\n• Messung: über exzentrische Maximalkraft oder Elektrostimulation","e":"Die Reserve kann z. B. in lebensbedrohlichen Situationen ausgeschöpft werden. Der Körper gibt nicht alles frei, was der Muskel könnte – sonst würden Sehnen reißen. Die exzentrische Maximalkraft weicht nur geringfügig von der Absolutkraft ab. Beispiel: Berichte über Menschen, die in Panik ein Auto anheben, um ein Kind zu retten, zeigen, dass diese Reserve in Notsituationen angezapft werden kann.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-012","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere relative Kraft und nenne ihre Bedeutung.","a":"• Maximalkraft im Verhältnis zum Körpergewicht (Maximalkraft : Körpergewicht)\n• Wichtig, wenn das eigene Körpergewicht bewegt wird (Turnen, Sprünge, Klettern); Kräftevergleich zwischen Sportlern","e":"Es zählt nicht nur, wie stark du bist, sondern wie stark im Verhältnis zu dem, was du tragen musst. Über die relative Kraft kann man auch Sportler unterschiedlichen Gewichts vergleichen. Beispiel: Ein 60-kg-Turner mit 90 kg Maximalkraft hat eine relative Kraft von 1,5 – er hält sich mühelos im Stütz, ein schwerer Kugelstoßer mit gleicher Maximalkraft nicht.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-013","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere Kraftausdauer.","a":"Ermüdungswiderstandsfähigkeit bei lang andauernden oder sich wiederholenden dynamischen und statischen Kraftleistungen (> 30 % des Kraftmaximums). (Grosser & Zintl; Steinhöfer; Harre)","e":"Kraftausdauer ist eine Mischung aus Kraft- und Ausdauerleistungsfähigkeit, je nach Belastung eher kraft- oder ausdauerbetont. Kraft immer wieder einsetzen, ohne schnell schlapp zu machen. Beispiel: Ein Ruderer muss über 2000 m ca. 230 kraftvolle Ruderschläge möglichst ermüdungsfrei durchziehen – typische Kraftausdauersportarten sind Rudern und Wildwasserkanu.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-014","thema":"Q2.2","kapitel":"Kraftarten","q":"Was versteht man unter Ermüdungswiderstandsfähigkeit?","a":"Vermögen, eine gegebene Kraftbelastung möglichst lange aufrechtzuerhalten; entscheidende Komponente der Kraftausdauer (Boeckh-Behrens & Buskies).","e":"Gemessen wird sie z. B. über die Anzahl der Wiederholungen oder die Haltedauer. Sie ist dein „Durchhaltevermögen“ unter Last. Beispiel: Wer 40 statt 25 Liegestütze schafft oder den Unterarmstütz 2 statt 1 Minute hält, hat bei dieser Übung die bessere Ermüdungswiderstandsfähigkeit.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-015","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere Schnellkraft.","a":"Fähigkeit, optimal schnell Kraft zu bilden, d. h. den Körper oder ein Gerät mit höchster Geschwindigkeit zu bewegen bzw. Widerstände mit höchstmöglicher Kontraktionsgeschwindigkeit zu überwinden. (Grosser & Zintl; Steinhöfer; Harre)","e":"Anders gesagt: einem Körper einen möglichst großen Impuls in möglichst kurzer Zeit erteilen. Kennzeichen ist, dass für die Kraftentwicklung nur begrenzte Zeit zur Verfügung steht – es zählt nicht nur wie viel, sondern wie schnell die Kraft kommt. Beispiel: Ein Speerwerfer muss in Sekundenbruchteilen einen großen Kraftstoß auf den Speer bringen; ein Boxer muss seinen Schlag ins Ziel bringen, bevor der Gegner ausweicht.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-016","thema":"Q2.2","kapitel":"Kraftarten","q":"Erläutere, wovon die Schnellkraftleistung abhängt, und vergleiche dabei Speerwerfer und Fechter.","a":"• Speerwerfer (hoher Widerstand): v. a. Maximalkraft\n• Fechter (geringer Widerstand): v. a. schnelle Kontraktionsfähigkeit (FT-/FTG-Fasern)\n→ Je höher der Widerstand, desto wichtiger die Maximalkraft","e":"Schnelle Kontraktionsfähigkeit ist das Vermögen, Kraft unabhängig vom Maximalkraftniveau möglichst schnell zu entwickeln (Boeckh-Behrens & Buskies). Sie hängt von der Faserzusammensetzung ab, v. a. von schnell zuckenden FTG-Fasern mit großem Querschnitt. Beispiel: Die Fechtklinge ist so leicht, dass Muskelmasse kaum hilft – es kommt auf schnelle Fasern an. Beim Kugelstoßen (7,26 kg) dagegen hilft jede Extraportion Maximalkraft.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-017","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere Reaktivkraft.","a":"(= exzentrisch-konzentrische Schnellkraft) Fähigkeit, bei Dehnungs-Verkürzungs-Zyklen einen hohen Kraftstoß zu erzeugen; Umkehr exzentrisch → konzentrisch < 200 ms.","e":"Reaktivkraft ist eine Sonderform der Schnellkraft mit Zwischenstellung zwischen Maximal- und Schnellkraft. Der Muskel wird erst blitzschnell gedehnt (bremsend) und schnellt dann zurück (überwindend). Beispiel: Ein Basketballer stoppt nach einer Dribbelfinte ab und springt sofort zum Sprungwurf ab – je kürzer die Phase zwischen Abstoppen und Absprung, desto weniger Zeit hat der Gegner zum Blocken.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-018","thema":"Q2.2","kapitel":"Kraftarten","q":"Wovon hängt die Reaktivkraft ab? Erkläre dabei den Begriff reaktive Spannungsfähigkeit.","a":"Abhängig von: Maximalkraft, schneller Kontraktionsfähigkeit, reaktiver Spannungsfähigkeit.\nReaktive Spannungsfähigkeit: Spannung in der exzentrischen Phase des DVZ halten und direkt danach konzentrisch einen hohen Kraftstoß erzeugen.","e":"Die reaktive Spannungsfähigkeit (Boeckh-Behrens & Buskies) beruht auf dem Elastizitäts- und Innervationsverhalten von Muskeln, Sehnen und Bändern und ist Grundvoraussetzung der Reaktivkraft. Wer beim Landen „weich wie Pudding“ einknickt, verliert die gespeicherte Energie; wer die Spannung hält, federt kraftvoll ab. Beispiel: Ein Weitspringer muss beim Absprung den Aufprall mit hoher Spannung abfangen, um sofort explosiv abzuspringen.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-019","thema":"Q2.2","kapitel":"Kraftarten","q":"Erkläre den Dehnungs-Verkürzungs-Zyklus (DVZ) mit dem Gummiband-Modell.","a":"• Exzentrische Dehnung: elastische Energie wird gespeichert (gespanntes Gummiband) + Dehnungsreflex\n• Direkt folgende konzentrische Phase: Energie + Reflexinnervation freigesetzt → höherer Kraftstoß\n• Umkehr < 200 ms","e":"Ist die Umkehr zu langsam, verpufft die gespeicherte Energie als Wärme. Der Dehnungsreflex wird über die Muskelspindel ausgelöst. Spannst du ein Gummiband und lässt sofort los, fliegt es weit; hältst du es lange gespannt, wird der Effekt schwächer. Beispiel: Beim Drop-Jump springt man nach dem Aufkommen sofort wieder hoch und kommt dadurch höher als bei einem Sprung aus der ruhigen Hocke.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-020","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere Startkraft und nenne ihre Grundlage.","a":"• Kraftwert 30 ms nach Kontraktionsbeginn (hohe Anfangskraft)\n• Grundlage: zu Beginn möglichst viele motorische Einheiten der FTG-Fasern innervieren","e":"Die Startkraft ist eine Zwischenform zwischen Schnellkraft und Reaktivkraft – sozusagen der allererste Ruck einer Bewegung. Beispiel: Beim Boxen, bei Schlägen im Badminton oder beim Antritt nach einer Täuschung im Basketball entscheidet der Kraftwert in den ersten Millisekunden, ob die Aktion gelingt.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-021","thema":"Q2.2","kapitel":"Kraftarten","q":"Definiere Explosivkraft und grenze sie von der Startkraft ab.","a":"• Explosivkraft: maximaler Kraftanstieg (steilste Stelle) im Kraft-Zeit-Verlauf bei maximal schneller Kontraktion gegen Widerstand; stark von der Maximalkraft abhängig\n• Startkraft: Kraftwert zu Beginn (30 ms); v. a. FTG-Aktivierung","e":"Die Explosivkraft ist eine Zwischenform zwischen Reaktiv- und Maximalkraft und zeigt sich z. B. bei Maximalsprung, maximalem Stoß oder Wurf. Im Kraft-Zeit-Diagramm ist die Startkraft der Wert am Anfang, die Explosivkraft die steilste Stelle der Kurve. Beispiel: Kugelstoßer, Gewichtheber und Hochspringer brauchen viel Explosivkraft (oft „Sprungkraft“ genannt), weil sie einen schweren Widerstand möglichst schnell beschleunigen müssen.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-022","thema":"Q2.2","kapitel":"Kraftarten","q":"Welche Kraftart dominiert in Abhängigkeit von der Höhe des Widerstands? (Merksatz)","a":"• Niedriger Widerstand → Startkraft\n• Zunehmende Last → Explosivkraft\n• Hohe Last → Maximalkraft","e":"Mit steigender Last dauert der Krafteinsatz länger, deshalb verschiebt sich die dominierende Kraftart. Die Schnellkraft (Quotient aus Kraft und Zeit) hängt daher von Start-, Explosiv- und Maximalkraft ab. Beispiel: Tischtennisschlag → Startkraft, Kugelstoß → Explosivkraft, Reißen im Gewichtheben mit Höchstlast → Maximalkraft.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-023","thema":"Q2.2","kapitel":"Kraftarten","q":"Beschreibe die Wechselbeziehung der Haupterscheinungsformen der Kraft (Abb. 13.2).","a":"• Grundachse: Maximalkraft (Basis) → Explosivkraft → Reaktivkraft → Startkraft → Schnellkraft\n• Darüber: Kraftausdauer (Maximalkraftausdauer, Schnellkraftausdauer)\n(nach Steinhöfer)","e":"Die Maximalkraft ist die Basis aller Kraftarten. Explosivkraft liegt zwischen Maximal- und Reaktivkraft, Startkraft zwischen Reaktiv- und Schnellkraft. Die Kraftarten sind keine getrennten Schubladen, sondern ein Kontinuum mit fließenden Übergängen. Beispiel: Ein Sprinter braucht Startkraft im Block, Reaktivkraft bei jedem Schritt und Schnellkraftausdauer, um bis 100 m nicht langsamer zu werden.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-024","thema":"Q2.2","kapitel":"Kraftarten","q":"Was versteht man unter einem Kraftanforderungsprofil?","a":"Zusammenstellung der Kraftanforderungen einer Sportart: besonders beanspruchte Muskelgruppen und dominierende Kraftarten; Grundlage für die Inhalte des speziellen Krafttrainings.","e":"Das Kraftanforderungsprofil ist der „Steckbrief“ einer Sportart in Sachen Kraft (Maximal-, Explosiv-, Reaktiv-, Start-, Schnellkraft, Kraftausdauer). Beispiel: Fußball – Schusskraft (Schnellkraft) und Sprungkraft für den Kopfball (Explosivkraft) der Beinstreckerkette; daraus folgt ein gezieltes Training der unteren Extremitäten.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-025","thema":"Q2.2","kapitel":"Kraftarten","q":"Nenne die dominierenden Kraftanforderungen für Basketball, Biathlon, Diskuswurf, Klettern, Rudern und Tennis und begründe sie kurz.","a":"• Basketball: Explosiv-, Reaktiv-, Start-, Schnellkraft (Sprünge, Antritte)\n• Biathlon: Schnellkraft, Kraftausdauer (lange Belastung)\n• Diskus: Maximal-, Explosiv-, Schnellkraft (schweres Gerät)\n• Klettern: Maximalkraft, Kraftausdauer\n• Rudern: Maximalkraft, Kraftausdauer\n• Tennis: Start-, Schnellkraft","e":"Begründungen: Basketballer springen, sprinten und stoppen über die ganze Spielzeit (daher auch etwas Kraftausdauer). Biathleten leisten lange Lauf-/Stockarbeit mit schnellen Abstößen. Kletterer halten ihr Körpergewicht an kleinen Griffen über lange Routen. Ruderer überwinden hohen Wasserwiderstand bei vielen Schlägen. Tennisspieler schlagen schnell mit leichtem Schläger in vielen Ballwechseln. Frage dich immer: Wie schwer ist der Widerstand, wie schnell, wie lange? Beispiel: Ein Diskuswerfer wirft wenige Male mit maximalem Einsatz – daher Maximal- und Explosivkraft statt Kraftausdauer.","quelle":"L13.2","typ":"kern"},{"id":"q2.2-026","thema":"Q2.2","kapitel":"Kraftarten","q":"Ordne Sportarten den Polen Ausdauer- und Kraftkomponente der Kraftausdauer zu (Tab. 13.9) und nenne jeweils die Energiebereitstellung.","a":"• Ausdauerkomponente (aerob): Langstreckenschwimmen, Skilanglauf\n• Mittel (anaerob-aerob): Radrennsport, Kajak, Rudern, Sprintschwimmen\n• Kraftkomponente (anaerob-laktazid): Kunstturnen, Ringen, Klettern","e":"Kraftausdauer ist ein Spektrum: Je höher der Krafteinsatz pro Wiederholung, desto anaerober. Am Kraftpol spricht man von Maximalkraftausdauer. Beispiel: Ein Turner im Kreuzhang hält extreme Last nur Sekunden (laktazid), ein Langstreckenschwimmer macht tausende leichte Züge (aerob).","quelle":"L13.2","typ":"kern"},{"id":"q2.2-027","thema":"Q2.2","kapitel":"Kraftarten","q":"Erkläre, warum ein Hochspringer und ein Gewichtheber unterschiedliche Kraftschwerpunkte haben, obwohl beide Maximalkraft brauchen.","a":"• Gewichtheber: möglichst hohe Last → absolute Maximalkraft, Muskelmasse erwünscht\n• Hochspringer: eigenes Körpergewicht schnell beschleunigen → Reaktiv-, Explosivkraft, hohe relative Kraft; Maximalkraft eher über IK-Training","e":"Beim Hochspringer ist die Bodenkontaktzeit sehr kurz. Zusätzliche Muskelmasse würde sein Körpergewicht erhöhen und die Sprunghöhe verringern; deshalb steigert er die Maximalkraft eher über bessere Ansteuerung. Beide brauchen starke Beine, aber der Hochspringer muss sich selbst tragen. Beispiel: 3 kg mehr Muskeln helfen einem Superschwergewichtler, kosten einen Hochspringer aber womöglich Zentimeter.","quelle":"L13.2","typ":"zusatz"},{"id":"q2.2-028","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Was ist eine motorische Einheit und welche Bedeutung hat sie für die Kraftentfaltung?","a":"• Ein Motoneuron + alle von ihm innervierten Muskelfasern; kontrahieren gemeinsam (Alles-oder-nichts)\n• Kraftabstufung über Rekrutierung, Frequenzierung, Synchronisation","e":"Rekrutierung = Anzahl aktivierter Einheiten, Frequenzierung = Impulsfrequenz, Synchronisation = zeitliche Abstimmung. Große motorische Einheiten (viele Fasern) bringen viel Kraft, aber wenig Feinabstimmung. Stell dir jede Einheit als Lichtschalter für eine Gruppe Lampen vor: mehr Schalter an = mehr Kraft. Beispiel: Augenmuskeln haben ca. 10 Fasern pro Einheit (sehr fein), der Bizeps ca. 1000 (sehr kräftig, weniger fein).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.2-029","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Vergleiche ST-Fasern und FT-Fasern (einschließlich FTO und FTG) hinsichtlich ihrer Eigenschaften.","a":"• ST (Typ I): langsam, wenig Kraft, ermüdungsresistent, aerob, kleiner Querschnitt\n• FT (Typ II): schnell, viel Kraft, schnell ermüdend, anaerob, großer Querschnitt\n  – FTO (IIa): schnell + oxidativ (Mischtyp)\n  – FTG (IIx): schnellste, stärkste, glykolytisch","e":"ST-Fasern sind rot, weil sie viele Mitochondrien, Myoglobin und Kapillaren haben; sie bilden kleine motorische Einheiten. FT-Fasern sind weiß und bilden große Einheiten. Die Faserverteilung ist weitgehend genetisch festgelegt. ST-Fasern sind die Marathonläufer, FTG die Sprinter, FTO die 400-m-Läufer dazwischen. Beispiel: Weltklasse-Sprinter haben oft über 70 % FT-Fasern in der Wade, Marathonläufer über 70 % ST-Fasern.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.2-030","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Erläutere, wie Belastungsintensität und Bewegungsausführung die Beanspruchung der Muskelfasertypen beeinflussen.","a":"• Langsam + niedrige Intensität (≤ 50 %) → v. a. ST-Fasern\n• Langsam + > 60 % Kmax → auch FT-Fasern\n• Explosive Ausführung → FT-Fasern, auch bei 30–35 % Last","e":"Merke: langsam + leicht → ST; schwer oder schnell → FT. Der Körper rekrutiert sparsam: erst die kleinen ST-Einheiten, erst bei hoher Kraft- oder Tempoanforderung die großen FT-Einheiten (Größenordnungsprinzip). Beispiel: Wer seine schnellen Fasern trainieren will, kann sehr schwer heben oder leichte Gewichte explosiv bewegen – langsames Training mit leichten Gewichten erreicht sie kaum.","quelle":"L13.3","typ":"kern"},{"id":"q2.2-031","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Erkläre das Rekrutierungsprinzip (Größenordnungsprinzip nach Henneman).","a":"Motorische Einheiten werden nach ihrer Größe aktiviert: bei geringer Kraftanforderung kleine (ST), mit steigender Anforderung größere (FTO, zuletzt FTG).","e":"Folge für das Training: Die stärksten FT-Fasern werden nur bei hohen Lasten bzw. maximal schneller Ausführung angesprochen – nur dann können sie sich auch anpassen. Wie bei der Feuerwehr: Für ein kleines Feuer rückt ein Wagen aus, erst beim Großbrand alle. Beispiel: Beim lockeren Gehen arbeiten fast nur ST-Fasern der Beine, erst beim maximalen Sprung kommen die FTG-Fasern dazu.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.2-032","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Definiere intramuskuläre Koordination und nenne ihre Komponenten.","a":"Zusammenspiel der motorischen Einheiten innerhalb eines Muskels (möglichst viele Fasern synchron aktivieren).\n• Rekrutierung\n• Frequenzierung\n• Synchronisation","e":"Rekrutierung = Anzahl gleichzeitig aktivierter Einheiten, Frequenzierung = Impulsfrequenz, Synchronisation = gleichzeitiges Feuern. Die intramuskuläre Koordination entspricht der willkürlichen Aktivierungsfähigkeit; ihr Maß ist das Kraftdefizit. Optimal steigern lässt sie sich bei großem Querschnitt v. a. der schnellen Fasern. Beispiel: Ein Untrainierter zieht wie ein ungeübtes Tauziehteam, bei dem jeder zu einer anderen Zeit zieht; ein Gewichtheber zieht mit allen Fasern gleichzeitig.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-033","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Definiere intermuskuläre Koordination und grenze sie von der intramuskulären Koordination ab.","a":"• Intermuskulär: Zusammenspiel verschiedener Muskeln (Agonisten, Synergisten, Antagonisten) bei einer Bewegung\n• Intramuskulär: Zusammenspiel der motorischen Einheiten innerhalb eines Muskels","e":"Verbessert sich die intermuskuläre Koordination, werden Agonisten und Synergisten zeitlich optimal eingesetzt und Antagonisten rechtzeitig entspannt – das bringt mehr Nettokraft und eine ökonomischere Bewegung. Sie wird v. a. durch technikorientiertes Training und am Anfang jedes Krafttrainings verbessert. Beispiel: Ein Anfänger an der Langhantel-Kniebeuge wackelt, weil Bein-, Rumpf- und Hüftmuskeln nicht abgestimmt sind – nach wenigen Wochen hebt er mehr, ohne dass seine Muskeln größer geworden sind.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.2-034","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Definiere Hypertrophie und erläutere, wodurch sie entsteht.","a":"Querschnittszunahme der einzelnen Muskelfasern durch Vermehrung der kontraktilen Proteine (Aktin, Myosin); Faserzahl bleibt gleich.\nAuslöser: hohe Muskelspannung über ausreichende Dauer (z. B. 8–12 Wdh. bis zur Ermüdung).","e":"Mechanischer und metabolischer Stress sowie Mikroverletzungen regen in der Erholungsphase eine gesteigerte Proteinsynthese an (Superkompensation), unterstützt durch Testosteron und ausreichende Eiweißzufuhr. Da die Kraft proportional zum Querschnitt ist, steigt die Maximalkraft. Beispiel: Ein Bodybuilder, der mehrere Monate nach der Hypertrophiemethode trainiert, bekommt sichtbar größere Muskeln, weil jede Faser mehr Myofibrillen eingebaut hat.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.2-035","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Erläutere, was man unter Muskelhyperplasie versteht und wie sie erreicht werden kann.","a":"• Vermehrung der Muskelfaseranzahl (Längsspaltung, Satellitenzellen)\n• Beim Menschen umstritten, allenfalls gering\n• Diskutiert: extrem hohe, lange Belastungen, starke exzentrische und Dehnungsreize","e":"Der Hauptmechanismus des Muskelwachstums bleibt die Hypertrophie. Hyperplasie ist im Tierversuch nachgewiesen, beim Menschen wird sie v. a. bei Spitzen-Bodybuildern vermutet (teils mit Anabolika). Eselsbrücke: Hypertrophie = dickere Fasern, Hyperplasie = Plus an Fasern. Beispiel: Bei Vögeln, deren Flügel lange mit Gewichten gedehnt wurden, entstanden neue Fasern – beim Menschen ist das kaum belegt.","quelle":"L13.5","typ":"zusatz"},{"id":"q2.2-036","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Beschreibe die Mechanismen zur Verbesserung der Maximalkraft.","a":"• Muskelquerschnitt: Hypertrophie (Muskelaufbautraining)\n• Nervale Ansteuerung: intramuskuläre (IK-Training) und intermuskuläre Koordination","e":"Die Kombination aus Muskelaufbau und IK-Training ist das eigentliche Maximalkrafttraining (z. B. Pyramidentraining). In den ersten Wochen dominieren nervale Anpassungen, später zunehmend die Hypertrophie. Mehr Kraft gibt es also durch einen größeren Motor oder eine bessere Steuerung. Beispiel: Ein Anfänger steigert sein Bankdrücken in den ersten 4 Wochen um 15 %, obwohl sein Brustumfang gleich bleibt – das ist fast nur Nervensystem.","quelle":"L13.5","typ":"zusatz"},{"id":"q2.2-037","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Erläutere, auf welche Faktoren der Kraftgewinn beim IK-Training zurückzuführen ist, wenn kaum Muskelzuwachs entsteht.","a":"• Sehr hohe Lasten, wenige Wdh. → kaum Hypertrophie\n• Neuronal: bessere Rekrutierung, Frequenzierung, Synchronisation\n• Biochemisch: verbesserter anaerob-alaktazider Stoffwechsel (Phosphatspeicher)","e":"Untrainierte können nur einen Teil ihrer motorischen Einheiten synchron aktivieren; IK-Training verbessert das und bringt so einen hohen, schnellen Kraftzuwachs. Das Nervensystem lernt, mehr „Personal“ gleichzeitig einzusetzen, statt neues einzustellen. Beispiel: Ein Skispringer wird durch IK-Training stärker, ohne schwerer zu werden – genau das will er.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-038","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Erkläre physiologisch, warum sich in der Pubertät die Kraft- und Schnellkraftleistungen von Jungen und Mädchen (z. B. im Sprint und Weitsprung) auseinanderentwickeln.","a":"• Jungen: starker Testosteronanstieg (ca. 10-fach) → anabol, mehr Hypertrophie (v. a. FT-Fasern) → höhere Maximal-, Schnell-, Reaktivkraft\n• Mädchen: Östrogen → höherer Fettanteil → geringere relative Kraft","e":"Testosteron fördert die Proteinsynthese, dadurch steigt der Muskelanteil an der Körpermasse. Bei gleichem Training wachsen so die Unterschiede in kraftabhängigen Disziplinen wie Sprint und Weitsprung. Das Training ist gleich, aber das Hormon-„Baumaterial“ nicht. Beispiel: Louis und Lena trainieren gleich viel, doch ab etwa 13 Jahren baut Louis deutlich mehr Beinmuskulatur auf und springt dadurch weiter.","quelle":"L13.5","typ":"zusatz"},{"id":"q2.2-039","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Nenne für die vier Trainingswirkungen von Krafttraining (intermuskuläre Koordination, intramuskuläre Koordination, Hypertrophie, Energieversorgung des Muskels) je eine Trainingsform und einen Sportbereich, in dem sie besonders angestrebt wird.","a":"• Intermuskulär: technikorientiertes Krafttraining → Gymnastik, Turnen, Würfe\n• Intramuskulär: IK-Training (90–100 %, 1–5 Wdh.) → Gewichtheben, Skispringen\n• Hypertrophie: Muskelaufbau (70–90 %, 8–12 Wdh.) → Bodybuilding, Kugelstoßen\n• Energieversorgung: Kraftausdauer (35–60 %) → Rudern, Kanu","e":"Technikorientiert heißt: sportartspezifische Bewegungen mit Zusatzlast. Weitere typische Sportarten: Hochsprung (IK), Sportklettern und Rugby (Hypertrophie), Schwimmen (Kraftausdauer mit vielen Wiederholungen). Jede Sportart braucht eine andere Hauptwirkung. Beispiel: Ein Ruderer braucht vor allem Muskeln, die tausende Schläge mit Energie versorgen, eine Gymnastin dagegen das perfekte Zusammenspiel vieler Muskeln.","quelle":"L13.5","typ":"zusatz"},{"id":"q2.2-040","thema":"Q2.2","kapitel":"Muskelfasern und Anpassungen","q":"Begründe, warum folgende Zielsetzungen sinnvoll sind: Rudern – Energieversorgung; rhythmische Sportgymnastik – intermuskuläre Koordination; Gewichtheben – intramuskuläre Koordination; Sportklettern – Hypertrophie.","a":"• Rudern: viele kraftvolle Schläge über Minuten → Kraftausdauer\n• Sportgymnastik: komplexe, präzise Bewegungen → Zusammenspiel wichtiger als hohe Kraft\n• Gewichtheben: Gewichtsklassen → Kraft ohne Gewichtszunahme\n• Klettern: mehr Querschnitt der Fingerbeuger, kaum Gewichtszunahme","e":"Beim Rudern müssen die Muskeln aerob und anaerob gut mit Energie versorgt werden (Kapillarisierung, Enzyme, Glykogen). Der Gewichtheber steigert die Kraft durch bessere Aktivierung der motorischen Einheiten. Beim Klettern sind Unterarm- und Fingerbeuger relativ klein, ein Zuwachs dort kostet kaum Körpergewicht. Die Begründung folgt immer aus dem Anforderungsprofil. Beispiel: Beim Klettern scheitert man oft, weil die Finger nicht mehr halten – dickere Fingerbeuger helfen direkt.","quelle":"L13.5","typ":"zusatz"},{"id":"q2.2-041","thema":"Q2.2","kapitel":"Grundsätze des Krafttrainings","q":"Nenne die allgemeinen Grundsätze des Krafttrainings.","a":"• Zentrale Bedeutung der Maximalkraft\n• Gleichgewicht Agonist/Antagonist\n• Allgemeines und spezielles Krafttraining\n• Intensität/Ausführung bestimmen Fasertyp\n• Bodybuilding und Körpergewicht","e":"Primäres Ziel ist die Steigerung der Maximalkraft; muskuläre Dysbalancen sind zu vermeiden. Allgemeines Training spricht alle Kraftfähigkeiten und Muskelgruppen an, spezielles orientiert sich an der Disziplin. Langsam und niedrig belastet trainiert ST-, hoch oder schnell FT-Fasern. Krafttraining kann auch allein dem Muskelwachstum oder der Gewichtsregulierung dienen. Beispiel: Ein Handballer trainiert zuerst allgemein und ausgewogen (Bauch und Rücken), steigert seine Maximalkraft und baut darauf sportartspezifisches Wurftraining auf.","quelle":"L13.3","typ":"kern"},{"id":"q2.2-042","thema":"Q2.2","kapitel":"Grundsätze des Krafttrainings","q":"Begründe, warum die Maximalkraft eine zentrale Bedeutung im Krafttraining hat.","a":"Die Maximalkraft ist Basisfähigkeit für alle anderen Kraftarten (Schnell-, Explosiv-, Reaktivkraft, Kraftausdauer); daher ist sie das primäre Ziel des Krafttrainings.","e":"Muskelkraft ist Grundlage jeder Aktivität, sportlich wie gesundheitlich. Soll Kraft allgemein verbessert werden, muss zuerst die Maximalkraft als Fundament gesteigert werden. Beispiel: Wer bei der Kniebeuge mehr Maximalkraft hat, kann auch eine leichtere Last (sein Körpergewicht) schneller bewegen und springt höher.","quelle":"L13.3","typ":"kern"},{"id":"q2.2-043","thema":"Q2.2","kapitel":"Grundsätze des Krafttrainings","q":"Was sind muskuläre Dysbalancen und warum müssen sie im Krafttraining vermieden werden?","a":"• Störung des Kräftegleichgewichts zwischen Agonist und Antagonist (durch einseitiges Training)\n• Folgen: verschobene Gelenkstellung, Leistungsminderung, Verletzungsgefahr, Haltungsschäden\n• → Agonist und Antagonist gemeinsam trainieren","e":"Passt sich ein Muskel mit höherer Spannung an (Verkürzung) oder mit niedrigerer (Abschwächung), während der Gegenspieler gleich bleibt, verändert sich das Verhältnis um das Gelenk. Daher verkürzte Muskeln dehnen und abgeschwächte kräftigen. Ein Gelenk ist wie ein Zelt mit zwei Seilen: Zieht eines stärker, steht es schief. Beispiel: Einseitiges Training des Rückenstreckers verkürzt die Rückenmuskulatur, es entsteht ein Hohlkreuz – daher auch die Bauchmuskeln kräftigen und den Rückenstrecker dehnen.","quelle":"L13.3","typ":"kern"},{"id":"q2.2-044","thema":"Q2.2","kapitel":"Grundsätze des Krafttrainings","q":"Unterscheide allgemeines und spezielles Krafttraining und nenne jeweils Anwendungsbereiche.","a":"• Allgemein: alle Kraftfähigkeiten und Muskelgruppen → Kinder/Jugend, Gesundheit, Reha, Basis im Leistungssport\n• Speziell: sportartspezifische Kraftkomponenten nach dem Kraftanforderungsprofil → Leistungssport","e":"Das allgemeine Krafttraining ist im Leistungssport die Basis für die speziellen Kraftfähigkeiten, vergleichbar der Grundlagenausdauer. Das spezielle Training zielt auf Kraftgewinn für einen bestimmten Bewegungsablauf. Beispiel: Ein Fußballer macht in der Vorbereitung ein Ganzkörper-Zirkeltraining (allgemein) und später gezieltes Maximal-, Explosiv- und Schnellkrafttraining der Beinstrecker für Schuss und Kopfball (speziell).","quelle":"L13.3","typ":"kern"},{"id":"q2.2-045","thema":"Q2.2","kapitel":"Grundsätze des Krafttrainings","q":"Welche Ziele kann Krafttraining im Bodybuilding und zur Regulierung des Körpergewichts verfolgen?","a":"• Bodybuilding: gezielte Hypertrophie einzelner Muskeln (Funktion unwichtig)\n• Gewichtsregulierung: Abnehmen (mehr Muskeln → höherer Grundumsatz) oder Zunehmen bei Untergewicht","e":"Spezielle Kraftfähigkeiten spielen hier nur eine untergeordnete Rolle; es geht um Aussehen oder Körperzusammensetzung, nicht um Leistung. Beispiel: Ein Bodybuilder trainiert seinen Bizeps isoliert für den Umfang, obwohl er im Alltag nie eine Kurzhantel beugen muss.","quelle":"L13.3","typ":"kern"},{"id":"q2.2-046","thema":"Q2.2","kapitel":"Belastungsnormative und Organisation","q":"Wie werden die Belastungskomponenten Intensität, Dauer, Umfang und Dichte im Krafttraining angegeben?","a":"• Intensität: % Kmax, Bewegungstempo, Krafteinsatz, Arbeitsweise\n• Dauer: Zeit oder Wiederholungszahl\n• Umfang: Anzahl der Serien\n• Dichte: Pausen (WP, ÜP, SP)","e":"WP = Wiederholungspause, ÜP = Übungspause, SP = Serienpause. Der Krafteinsatz wird subjektiv angegeben (gering bis maximal), das Tempo z. B. langsam, zügig oder explosiv (nach Grosser & Zintl; Steinhöfer). Beispiel: „80 % Kmax, zügig, hoher Krafteinsatz, dynamisch – 10 Wdh. – 5 Serien zu 3 Übungen – WP keine, ÜP 2 min, SP 4 min“ beschreibt eine Hypertrophieeinheit vollständig.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-047","thema":"Q2.2","kapitel":"Belastungsnormative und Organisation","q":"Unterscheide Stationstraining, Serientraining und Zirkeltraining als Organisationsformen des Krafttrainings.","a":"• Stationstraining: alle Serien einer Übung, dann nächste Übung\n• Serientraining: Serie aus 2–4 Übungen nacheinander, dann nächste Serie\n• Zirkeltraining: > 5 Stationen nacheinander, meist mehrfach","e":"Statt „Serie“ sagt man auch „Satz“. Beispiel: Stationstraining: 5 × 12 Bankdrücken, dann 5 × 12 Beinpresse. Serientraining: 12 Bankdrücken, 12 Beinpresse – und das fünfmal. Zirkel: Kastensprünge, enge Liegestütze, Rückenstrecker, weite Liegestütze, Prellfedern, Seilspringen je 30–60 s, dreimal.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-048","thema":"Q2.2","kapitel":"Belastungsnormative und Organisation","q":"Nenne die zentralen Krafttrainingsmethoden und ihr jeweiliges Haupttrainingsziel (Tab. 13.4).","a":"• Muskelaufbautraining → Maximalkraft (Hypertrophie)\n• IK-Training → Maximalkraft (Aktivierungsfähigkeit)\n• Schnellkraft-/Muskelleistungsmethode → Schnellkraft\n• Reaktivkraftmethode → Reaktivkraft\n• Kraftausdauermethode → Kraftausdauer","e":"Jede Methode zielt auf eine bestimmte „Stellschraube“: Muskelquerschnitt, intramuskuläre Koordination, schnelle Kontraktionsfähigkeit der ST- und FT-Fasern, reaktive Spannungsfähigkeit im Dehnungs-Verkürzungs-Zyklus bzw. Ermüdungswiderstandsfähigkeit. Beispiel: Ein Volleyballer, der höher springen will, nutzt die Reaktivkraftmethode, um die reaktive Spannungsfähigkeit beim Blocksprung zu verbessern.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-049","thema":"Q2.2","kapitel":"Belastungsnormative und Organisation","q":"Warum wird in der Praxis die Last im dynamischen Krafttraining oft über die Wiederholungszahl statt über Prozentangaben bestimmt? Beschreibe das Vorgehen für Einsteiger.","a":"• Prozentangaben brauchen einen Maximalkrafttest (aufwendig, Verletzungsgefahr)\n• Einstieg: 3–5 Serien × 10–15 Wdh., ab Wdh. 12 „anstrengend“ (Borg 13–15)\n• Bei 3–5 × 15 problemlos → Gewicht steigern","e":"Deshalb wählt man durch Ausprobieren ein Gewicht, das die gewünschte Wiederholungszahl zulässt (Boeckh-Behrens & Buskies). Das subjektive Empfinden passt sich automatisch an Tagesform und Leistungsstand an; die Steigerung folgt dem Prinzip der progressiven Belastung. Beispiel: Ein Schüler beginnt an der Beinpresse mit 50 kg, ab Wiederholung 12 wird es anstrengend. Nach drei Wochen schafft er 3 × 15 locker und erhöht auf 55 kg.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-050","thema":"Q2.2","kapitel":"Belastungsnormative und Organisation","q":"Ordne den Krafttrainingsmethoden ihre typische Intensität (% Kmax) und Wiederholungszahl zu (Gesamtüberblick).","a":"• Kraftausdauer: 35–60 %, ca. 20–30 Wdh.\n• Schnellkraft: 35–50 %, 6–12 explosiv\n• Muskelleistung: 50–60 %, 6–8 explosiv\n• MA-Anfänger: 40–65 %, 8–20\n• MA-Fitness: 70–85 %, 8–15\n• Hypertrophie: 80–90 %, 5–10\n• IK: 90–100 %, 1–5\n• Reaktivkraft: maximal, 6–10","e":"Bei der Reaktivkraftmethode bedeutet „maximal“: 100 % der reaktiven Sprung- oder Wurfleistung mit Körpergewicht oder geringer Zusatzlast; Kraftausdauer wird bis zur Ermüdung trainiert. Faustregel: Je höher die Last, desto weniger Wiederholungen; explosive Methoden nutzen leichte Lasten mit maximaler Geschwindigkeit. Beispiel: Mit 90 % schaffst du etwa 3 Wiederholungen (IK), mit 50 % viele (Kraftausdauer) – oder du bewegst die 50 % explosiv (Schnellkraft).","quelle":"L13.4","typ":"kern"},{"id":"q2.2-051","thema":"Q2.2","kapitel":"Belastungsnormative und Organisation","q":"Welche Krafttrainingsmethoden nutzen die Wiederholungsmethode, welche die Intervallmethode? Begründe.","a":"• Wiederholungsmethode: IK, Schnellkraft/Muskelleistung, Reaktivkraft → jede Wdh. in maximaler Qualität\n• Intervallmethode: Kraftausdauer, Anfänger- (extensiv), Fitness-/Hypertrophiemethode (intensiv) → Ermüdung soll sich aufsummieren","e":"Fitness- und Hypertrophiemethode nutzen teilweise auch die Wiederholungsmethode. In den vollständigen Pausen füllen sich die Phosphatspeicher und das Nervensystem erholt sich. Die aufsummierte Ermüdung ist dagegen der Reiz für Hypertrophie bzw. Ermüdungswiderstandsfähigkeit. Beispiel: Zwischen zwei IK-Serien wartet der Athlet 4 Minuten, im Kraftausdauerzirkel nur 30–60 Sekunden.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-052","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Aus welchen Trainingsformen setzt sich das Maximalkrafttraining zusammen?","a":"Maximalkrafttraining = Muskelaufbautraining (MA, Hypertrophie) + IK-Training (synchrone Aktivierung); Reihenfolge: erst MA, dann IK.","e":"Die Reihenfolge ergibt sich, weil ein großer Querschnitt v. a. der schnellen Fasern Voraussetzung für eine optimale IK-Steigerung ist: Erst baut man einen größeren Motor, dann lernt man, ihn voll auszufahren. Beispiel: Ein Kugelstoßer trainiert in der frühen Vorbereitungsphase Hypertrophie und kurz vor der Wettkampfphase IK mit sehr schweren Lasten.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-053","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Charakterisiere das Muskelaufbautraining (Hypertrophietraining) allgemein.","a":"• Mittlere bis hohe Intensität, mittlere Wiederholungszahl (typisch 8–12, letzte „anstrengend“)\n• Langsam bis zügig, dynamisch, keine Wiederholungspausen\n• Intervall- bzw. Wiederholungsmethode","e":"Muskelaufbau ist der erste Schritt zur Maximalkraftsteigerung, weil er den Faserquerschnitt vergrößert. Der Muskel wächst, wenn er lange genug unter hoher Spannung steht – nicht zu leicht (zu wenig Reiz) und nicht zu schwer (zu kurz). Beispiel: 4 Sätze à 10 Wiederholungen Kniebeugen mit einem Gewicht, bei dem die letzten 2 Wiederholungen richtig schwer fallen.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-054","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Nenne die Regel für die Ausführung einer Wiederholung im Muskelaufbautraining und begründe sie.","a":"• 1 Zeiteinheit konzentrisch, 2 Zeiteinheiten exzentrisch\n• Begründung: Exzentrisch ist mehr Kraft möglich → Muskel wird stärker ausgereizt (Hypertrophie, IK)","e":"Durch die verlängerte Bremsphase wird die Muskulatur maximal gefordert, was Hypertrophie und intramuskuläre Koordination verbessert. Viele lassen das Gewicht einfach fallen und verschenken den wertvollsten Teil der Wiederholung. Beispiel: Beim Bizepscurl in 1 Sekunde hochbeugen und in 2 Sekunden kontrolliert ablassen.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-055","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Nenne die Belastungsnormative der Anfängermethode im Muskelaufbautraining (Tab. 13.5).","a":"• Extensive Intervallmethode\n• 40–65 % Kmax, mittlerer Krafteinsatz, langsam–zügig, dynamisch\n• 8–20 Wdh.; 6–8 Serien × 3–4 Übungen\n• WP keine, ÜP lohnend, SP 1–2 min\n• Gesundheits-/Einsteigertraining","e":"Wirkung: bessere intermuskuläre Koordination, mehr Rekrutierung der ST-Fasern, geringe bis mittlere Hypertrophie, verbesserter aerob-anaerober Stoffwechsel und mittlerer Maximalkraftzuwachs. Anfänger brauchen zuerst Technik und eine Gewöhnung von Sehnen und Bändern – deshalb moderate Lasten. Beispiel: Ein Neuling im Fitnessstudio absolviert einen Ganzkörperplan mit je 15 Wiederholungen bei mittlerer Anstrengung.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-056","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Nenne die Belastungsnormative der Fitnessmethode im Muskelaufbautraining (Tab. 13.5).","a":"• Intensive Intervall- und Wiederholungsmethode\n• 70–85 % Kmax, mittlerer–hoher Krafteinsatz, langsam–zügig, dynamisch\n• 8–15 Wdh.; 6–8 Serien × 3 Übungen\n• WP keine, ÜP 30–60 s, SP 2–3 min\n• Leistungssport, Fitness","e":"Wirkung: bessere intermuskuläre Koordination, stärkere Rekrutierung und Frequenzierung beider Fasertypen, mittlere bis starke Hypertrophie, verbesserter aerob-anaerober Stoffwechsel, starker Maximalkraftzuwachs. Die Fitnessmethode ist der Mittelweg zwischen Einsteiger- und Bodybuildingtraining. Beispiel: Ein Handballer trainiert in der Vorbereitung Bankdrücken mit 75 % Kmax, 12 Wiederholungen und 2–3 Minuten Serienpause.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-057","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Nenne die Belastungsnormative der Hypertrophiemethode (Tab. 13.5).","a":"• Intensive Intervall- und Wiederholungsmethode\n• 80–90 % Kmax, hoher Krafteinsatz, langsam–zügig, dynamisch\n• 5–10 Wdh.; 5–10 Serien × 3 Übungen\n• WP keine, ÜP 2–3 min, SP 3–5 min\n• Leistungssport, Bodybuilding","e":"Wirkung: bessere intermuskuläre Koordination, stärkere Rekrutierung und Frequenzierung beider Fasertypen, starke bis sehr starke Hypertrophie, verbesserter anaerober Stoffwechsel, sehr starker Maximalkraftzuwachs. Je höher die Intensität, desto weniger Wiederholungen und desto längere Pausen. Beispiel: Ein Bodybuilder trainiert Beinpresse mit 85 % Kmax, 8 Wiederholungen, 4 Minuten Serienpause.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-058","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Vergleiche Anfänger-, Fitness- und Hypertrophiemethode: Wie verändern sich Intensität, Wiederholungszahl, Pausen und Hypertrophiewirkung?","a":"Anfänger → Fitness → Hypertrophie:\n• Intensität: 40–65 → 70–85 → 80–90 %\n• Wdh.: 8–20 → 8–15 → 5–10\n• SP: 1–2 → 2–3 → 3–5 min\n• Hypertrophie: gering–mittel → mittel–stark → stark–sehr stark","e":"Außerdem steigt der Krafteinsatz (mittel → hoch), die Übungspausen werden länger (lohnend → 30–60 s → 2–3 min), der Stoffwechsel wird anaerober und die Maximalkraftwirkung stärker. Gemeinsam sind dynamische, langsame bis zügige Ausführung ohne Wiederholungspausen. Merkhilfe: Je schwerer, desto kürzer der Satz und desto länger die Pause. Beispiel: Ein Schüler beginnt mit der Anfängermethode und wechselt nach einigen Monaten zur Fitnessmethode.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-059","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Charakterisiere das IK-Training und begründe, warum es nur für Fortgeschrittene geeignet ist.","a":"• Hohe bis höchste Intensität (> 80 %, z. B. 90 %), wenige Wdh. (2–3), Wiederholungsmethode\n• Nur für Fortgeschrittene: starke Belastung des passiven Bewegungsapparats; braucht saubere Technik und MA-Muskelbasis","e":"Erst Lasten über 80 % der aktuellen Maximalkraft erhöhen die Aktivierung der motorischen Einheiten, typisch 3–5 Serien zu 3–4 Übungen. Die vollständigen Pausen füllen die Phosphatspeicher wieder auf. Sehnen, Bänder, Gelenke und Wirbelsäule werden stark beansprucht – mit fast maximalen Gewichten ist ein Technikfehler schnell eine Verletzung. Beispiel: Ein Anfänger, der gleich 95 % seiner Maximalkraft beim Kreuzheben versucht, riskiert einen Bandscheibenschaden.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-060","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Nenne die Belastungsnormative des IK-Trainings (Tab. 13.6).","a":"• Wiederholungsmethode\n• 90–100 % Kmax, maximaler Krafteinsatz, zügig–explosiv, dynamisch\n• 1–5 Wdh.; 3–5 Serien × 3–4 Übungen\n• WP 5 s, ÜP = SP 3–5 min\n• Ende Vorbereitung/Wettkampfphase; nicht Gesundheits- oder Kindertraining","e":"Pro Muskelgruppe ergeben sich 30–60 Einzelbelastungen; geeignet v. a. für Schnellkraftdisziplinen. Wirkung: bessere inter- und intramuskuläre Koordination (Rekrutierung, Frequenzierung aller Fasern), geringe Hypertrophie, verbesserter anaerob-alaktazider Stoffwechsel; Maximal-, Schnell- und Relativkraft steigen, das Kraftdefizit sinkt. Beispiel: Ein Gewichtheber macht 4 Serien à 2 Wiederholungen mit 95 % und pausiert jeweils 4 Minuten, damit jede Wiederholung mit voller Energie erfolgt.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-061","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"In welchen Sportarten wird zur Steigerung der Maximalkraft verstärkt auf IK-Training zurückgegriffen? Begründe.","a":"In Sportarten, in denen geringes Körpergewicht die Leistung begünstigt (Hochsprung, Skispringen, Turnen, Gewichtsklassen): IK-Training steigert die Maximalkraft ohne großen Muskelzuwachs → relative Kraft steigt.","e":"Mehr Muskelmasse würde bei gleicher Maximalkraft das Körpergewicht erhöhen und die Leistung verschlechtern. Wer sein eigenes Gewicht bewegen muss, will stärker, aber nicht schwerer werden. Beispiel: Ein Hochspringer muss seinen Körper senkrecht nach oben beschleunigen; mehr Muskelmasse bei gleicher Maximalkraft würde die Sprunghöhe verringern.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-062","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Erläutere das Pyramidentraining.","a":"• Kombination aus MA- und IK-Training\n• Mit steigendem Gewicht sinkt die Wiederholungszahl (z. B. 70 % × 10 → 80 % × 6 → 90 % × 3 → 95 % × 1)","e":"So werden beide Wege der Maximalkraftsteigerung genutzt: Hypertrophie durch geringe bis mittlere Widerstände mit vielen Wiederholungen und intramuskuläre Koordination durch hohe Widerstände mit wenigen Wiederholungen. Die Pyramide hat eine breite Basis und eine schmale Spitze. Beispiel: Beim Bankdrücken steigert sich ein Athlet von 60 kg × 10 über 70 kg × 6 bis 80 kg × 2.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-063","thema":"Q2.2","kapitel":"Maximalkrafttraining","q":"Erläutere die Bedeutung der Maximalkraft für einen Gewichtheber, einen Basketballer und einen Skispringer und begründe, welche Art von Maximalkrafttraining im Vordergrund stehen sollte.","a":"• Gewichtheber: direkt leistungsbestimmend; leichte Klassen IK, Superschwergewicht MA + IK\n• Basketballer: Basis für Sprung-/Antrittskraft; Center auch MA, Aufbauspieler eher IK\n• Skispringer: Basis für Absprung, geringes Gewicht → IK","e":"Der Center braucht Masse für Körperkontakt und Rebound, der Aufbauspieler soll leicht und schnell bleiben. Der Skispringer muss Hypertrophie vermeiden, weil das Gewicht in der Flugphase schadet. Entscheidend ist immer: Hilft mehr Masse oder schadet sie? Beispiel: Ein Skispringer mit zwei Kilo mehr Muskeln fliegt schlechter – er setzt daher auf IK-Training.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-064","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Wodurch ist Schnellkrafttraining allgemein gekennzeichnet?","a":"• Mittlere Intensität und Wiederholungszahl\n• Konzentrisch, maximal schnell (explosiv)\n• Relativ geringe Widerstände, vollständige Pausen\n• Abbruch bei Geschwindigkeitsabfall","e":"Jede Wiederholung zählt nur, wenn sie wirklich maximal schnell ist – müde Wiederholungen trainieren eher Langsamkeit. Beispiel: Medizinballstöße mit 3 kg so explosiv wie möglich, nach 8 Stößen Pause, sobald die Weite nachlässt.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-065","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Unterscheide Schnellkraftmethode und Muskelleistungsmethode hinsichtlich ihres Einsatzbereichs (Zeit für die Impulserzeugung).","a":"• < 250 ms (Fechten, Boxen, Sprint): große Kraft in kürzester Zeit, Startkraft → Schnellkraftmethode\n• > 250 ms (Würfe, Kugelstoß, Volleyballsprung): große konzentrische Kräfte → Muskelleistungsmethode","e":"Bei kurzen Bewegungen sind Startkraft und Kraftanstieg entscheidend, bei längeren die muskuläre Leistungsfähigkeit. Die 250-ms-Grenze trennt „blitzschnell“ von „schnell, aber mit etwas Anlauf“. Beispiel: Ein Boxer braucht die Schnellkraftmethode, ein Kugelstoßer, der den Stoß über eine längere Strecke beschleunigt, die Muskelleistungsmethode.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-066","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Nenne die Belastungsnormative der Schnellkraftmethode und der Muskelleistungsmethode (Tab. 13.7).","a":"Gemeinsam: Wiederholungsmethode, maximaler Krafteinsatz, explosiv, konzentrisch; 4–5 Serien × 3–4 Übungen; WP 5–10 s, ÜP = SP 3–5 min\n• Schnellkraftmethode: 35–50 % Kmax, 6–12 Wdh.\n• Muskelleistungsmethode: 50–60 % Kmax, 6–8 Wdh.","e":"Abgebrochen wird, sobald die Geschwindigkeit abfällt; bei alternierenden Bewegungen ist auch keine Wiederholungspause nötig. Einsatz am Ende der Vorbereitungs- und v. a. in der Wettkampfphase in allen Schnellkraftdisziplinen, nicht im Gesundheitstraining; Kinder und Jugendliche mit reduzierter Intensität. Beispiel: Sprungkniebeugen mit 40 % Kmax (Schnellkraftmethode) für einen Sprinter oder mit 55 % (Muskelleistungsmethode) für einen Kugelstoßer, jeweils mit 4 Minuten Pause.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-067","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Welche Wirkungen haben Schnellkraft- und Muskelleistungsmethode (Tab. 13.7)?","a":"• ZNS: schnellere Kontraktionsfähigkeit, bessere inter- und intramuskuläre Koordination\n• Hypertrophie: keine bzw. gering (Muskelleistung)\n• Anaerob-alaktazide Kapazität ↑\n• Schnellkraft; Muskelleistung zusätzlich Maximal- und Explosivkraft","e":"Schnellkrafttraining macht die Muskeln vor allem schneller, nicht dicker – die Verbesserung kommt aus der neuronalen Aktivierungsfähigkeit. Beispiel: Ein Tischtennisspieler verbessert seine Schlaggeschwindigkeit, ohne an Gewicht zuzulegen.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-068","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Wie wird Schnellkrafttraining in den Sportspielen durchgeführt und warum?","a":"Technikorientiert: direkte Sprung-, Wurf-, Stoß-, Schuss- und Antrittsübungen (isoliert oder im Spielphasentraining) statt Schnellkraft-/Muskelleistungsmethode; bessere Übertragung auf die Technik.","e":"Die klassischen Methoden haben in den Sportspielen kaum Bedeutung, u. a. wegen des großen Zeitaufwands. Das technikorientierte Training verbessert zugleich die intermuskuläre Koordination der sportartspezifischen Bewegung. Spieler trainieren Schnellkraft lieber mit dem Ball als an der Hantel. Beispiel für Basketball: Antritt nach Ballannahme mit Korbleger, Sprungwürfe nach Stopp, Rebound-Serien am Brett mit sofortigem Wiederabsprung.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-069","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Wodurch ist das Reaktivkrafttraining gekennzeichnet?","a":"• Schneller Dehnungs-Verkürzungs-Zyklus\n• Maximale Intensität\n• Inhalte: Mehrfach-, Nieder-, Anlaufsprünge, schnelle Laufschritte, reaktive Liegestütze","e":"Leistungsbestimmend sind Querschnitt und Zusammensetzung der Muskelfasern sowie das Elastizitäts- und Innervationsverhalten von Muskeln, Sehnen und Bändern (reaktive Spannungsfähigkeit). Reaktivkrafttraining heißt: landen und sofort wieder abspringen, so kurz wie möglich am Boden. Beispiel: Hürdensprünge in Serie über 5 niedrige Hürden mit minimaler Bodenkontaktzeit.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-070","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Beschreibe den Drop-Jump als Standardübung des Reaktivkrafttrainings sowie eine Übung für die obere Extremität.","a":"• Drop-Jump: aus 15–60 cm vom Kasten fallen lassen, mit kurzem Bodenkontakt ohne große Ausholbewegung senkrecht auf gleich hohen Kasten springen\n• Reaktive Liegestütze: aus dem Kniestand in den Liegestütz fallen, sofort abdrücken","e":"Der Drop-Jump trainiert die Knie- und Fußstrecker, die reaktiven Liegestütze die Ellbogenstrecker. Der Boden soll „heiß“ sein: Ein tiefes Einknicken würde den Dehnungs-Verkürzungs-Zyklus verlängern und die Reaktivkraftwirkung zerstören. Beispiel: Ein Volleyballer springt von einem 40-cm-Kasten und sofort auf den nächsten Kasten.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-071","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Wie sollte die Belastung beim Reaktivkrafttraining (plyometrisches Training) aufgebaut werden und welche Voraussetzung ist nötig?","a":"• Steigerung: Hüpfübungen → Sprungübungen (z. B. über niedrige Hürden) → Tief-Hoch-Sprünge (Drop-Jumps)\n• Voraussetzung: gute Maximalkraftbasis (im Nachwuchs nur vereinfacht)","e":"Bei Tief-Hoch-Sprüngen wirkt ein Vielfaches des Körpergewichts auf Sehnen und Gelenke. Ohne Kraftbasis knickt man ein oder verletzt sich; deshalb im Nachwuchsbereich gar nicht oder nur in vereinfachten Formen. Beispiel: Ein 12-Jähriger macht Seilspringen und Hüpfspiele statt Drop-Jumps aus 60 cm.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-072","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Nenne die Belastungsnormative der Reaktivkraftmethode (Tab. 13.8).","a":"• Wiederholungsmethode\n• 100 % (max. Sprung-/Wurfleistung, Körpergewicht oder geringe Zusatzlast), explosiv, ohne Umkehrpause\n• 6–10 Wdh.; 2–10 Serien (je nach Niveau) × 2–3 Übungen\n• WP 5–10 s, ÜP = SP 5–10 min","e":"Serien: Anfänger 2–3, Fortgeschrittene 3–5, Hochleistung 6–10. Nur im frischen Zustand trainieren. Einsatz ganzjährig, besonders am Ende der Vorbereitung und in der Wettkampfphase, für reaktive Sprungdisziplinen; nicht im Gesundheitstraining, bei Kindern vorsichtig. Wirkung: bessere reaktive Spannungsfähigkeit, Rekrutierung aller Fasern, kaum Hypertrophie, anaerob-alaktazider Stoffwechsel; Reaktiv- und Schnellkraft. Beispiel: Ein Hochspringer macht 4 Serien à 8 Hürdensprünge und pausiert jeweils 6–8 Minuten.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-073","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Warum ist extremes Reaktivkrafttraining für Spielsportler nicht zu empfehlen?","a":"• Extreme Belastungen (große Fallhöhe, sehr kurze Bremsphase) → verletzungsträchtige Belastungsspitzen\n• Entspricht nicht den Spielanforderungen\n• Wichtiger: propriozeptives Training","e":"Ein Fußballer springt im Spiel nie von 80 cm herab und sofort maximal ab – solches Training bringt ihm wenig, kostet aber Gelenke. Beispiel: Statt Drop-Jumps aus großer Höhe trainiert er lieber Sprünge und Landungen auf dem Kippbrett.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-074","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Was ist propriozeptives Training und warum ist es für Spielsportler besonders wichtig?","a":"• Training an instabilen Geräten (Kippbrett, Kreisel, Minitrampolin)\n• Schult Gleichgewicht, Reaktion auf unerwartete Reize, Schnellkraft zu Bewegungsbeginn\n• Verletzungsprophylaxe (Umknicken)","e":"Die Schnellkraft verbessert sich reflexinduziert, v. a. in den ersten 100 ms nach dem Reiz. Für Spieler ist das wichtig, weil sie ständig auf unvorhersehbare Reize schnellkräftig reagieren müssen. Es gibt einen fließenden Übergang zum Koordinationstraining. Propriozeption ist die Eigenwahrnehmung über Rezeptoren in Muskeln, Sehnen und Gelenken. Beispiel: Ein Handballer, der regelmäßig auf dem Therapiekreisel steht, fängt ein Umknicken bei der Landung schneller reflektorisch ab.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-075","thema":"Q2.2","kapitel":"Schnellkraft- und Reaktivkrafttraining","q":"Erläutere die Bedeutung der Reaktivkraft für eine Hochspringerin, eine Volleyballerin und eine Handballerin und nenne geeignete Trainingsformen.","a":"• Hochspringerin: schneller DVZ beim Absprung → Reaktivkraft leistungsbestimmend; Hürden-, Sprungserien, Drop-Jumps\n• Volleyballerin: viele Block-/Angriffssprünge → Reaktiv-, Explosivkraft; Sprungserien, moderate Drop-Jumps\n• Handballerin: Sprungwurf, Stopps → Reaktiv-, Startkraft; spielnahes Sprungtraining, Propriozeption","e":"Die Bodenkontaktzeit der Hochspringerin liegt bei ca. 150–200 ms; Drop-Jumps nur mit guter Maximalkraftbasis. Die Volleyballerin hat teils längere Bodenkontakte und profitiert auch von technikorientierten Blocksprüngen. Die Handballerin braucht eher moderate Plyometrie statt extremer Tief-Hoch-Sprünge. Je kürzer der Bodenkontakt in der Sportart, desto wichtiger die Reaktivkraft. Beispiel: Die Hochspringerin profitiert am stärksten von klassischer Plyometrie, die Handballerin eher von spielnahen Sprung- und Gleichgewichtsübungen.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-076","thema":"Q2.2","kapitel":"Kraftausdauertraining","q":"Wodurch ist das Kraftausdauertraining gekennzeichnet?","a":"• Geringe bis mittlere Last, viele Wiederholungen bis zur völligen Erschöpfung\n• Intervallmethode (extensiv eher aerob, intensiv eher anaerob)","e":"Je nach Sportart ist das Training eher ausdauer- oder kraftorientiert. Entscheidend ist die Erschöpfung am Ende eines Satzes – es fühlt sich an wie „brennende Muskeln“. Beispiel: 25 Kniebeugen mit leichter Langhantel bis nichts mehr geht, danach eine Minute Pause.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-077","thema":"Q2.2","kapitel":"Kraftausdauertraining","q":"Nenne die Belastungsnormative der Kraftausdauermethode (Tab. 13.10).","a":"• Intervallmethode\n• 35–60 % Kmax, geringer–mittlerer Krafteinsatz, langsam–zügig, dynamisch\n• Viele Wdh. bis zur Ermüdung; 6 Serien × 3–4 Übungen oder 3 Zirkel à 6–8 Stationen\n• WP keine, ÜP 30–60 s, SP 0,5–3 min","e":"Die Serienpause ist bei höherer Last länger (1–3 min) als bei geringer (0,5–2 min). Anwendung: Kraftausdauerdisziplinen, sanftes Krafttraining (Körperformung, Abnehmen), Reha, Prophylaxe, kompensatorisches Training. Wirkung: keine ZNS-Wirkung, geringe bis mittlere Hypertrophie, bessere aerobe und anaerobe Glykolyse, Kraftausdauer. Beispiel: Ein Zirkel mit 6 Stationen (Liegestütze, Sit-ups, Kniebeugen …), jeweils bis zur Ermüdung, dreimal durchlaufen.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-078","thema":"Q2.2","kapitel":"Kraftausdauertraining","q":"Wie wird die Last im Kraftausdauertraining in der Praxis gewählt und wann wird abgebrochen?","a":"• Last, die 20–30 Wdh. zulässt (durch Ausprobieren)\n• Abbruch bei „sehr anstrengend“ (Borg-Skala)\n• Folgeserien: Abbruch, wenn die Anfangs-Wiederholungszahl nicht mehr erreicht wird","e":"Die Wiederholungszahl ist hier der Gradmesser für die passende Last. Beispiel: Schafft jemand beim Latziehen mit 30 kg 28 Wiederholungen, passt die Last; schafft er in Serie 3 nur noch 20, wird die Übung beendet.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-079","thema":"Q2.2","kapitel":"Kraftausdauertraining","q":"Begründe, warum Kraftausdauertraining für Spielsportler nicht die Methode der ersten Wahl ist.","a":"Spieler brauchen v. a. häufige schnellkräftige, reaktive Aktionen (meist anaerob-alaktazid); die Kraftausdauermethode (viele Wdh., geringe Last, langsam) trainiert das kaum – nur als Basis sinnvoll.","e":"Die Aktionen sind zyklisch und azyklisch und werden über die ganze Spielzeit mit unterschiedlichen Pausen erbracht; reicht die Pause nicht zur Phosphatresynthese, wird es teilweise laktazid. Fußball besteht aus vielen kurzen Sprints, Sprüngen und Zweikämpfen, nicht aus 30 langsamen Wiederholungen. Beispiel: Wiederholte Antritte mit kurzen Pausen sind spielnäher als ein klassischer Kraftausdauerzirkel.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-080","thema":"Q2.2","kapitel":"Kraftausdauertraining","q":"Was ist HIIT und wie ist das Tabata-Training aufgebaut?","a":"• HIIT: Kraftausdauertraining mit kurzen, sehr intensiven Belastungen, kurzen Pausen, geringem Umfang\n• Tabata: Zirkel aus 4–8 Übungen, je 20 s maximal, 10 s Pause, 60–120 s Serienpause","e":"Das Tabata-Training geht auf den japanischen Professor Izumi Tabata zurück und folgt dem Prinzip der intensiven Intervallmethode. 20 Sekunden Vollgas, 10 Sekunden Pause – kurz, aber extrem anstrengend. Beispiel: Ein Tabata-Zirkel mit Crunches, Push-ups und Squats dauert pro Durchgang nur wenige Minuten, bringt aber Puls und Muskeln an die Grenze.","quelle":"L13.4","typ":"kern"},{"id":"q2.2-081","thema":"Q2.2","kapitel":"Kraftausdauertraining","q":"Unterscheide Maximalkraftausdauer, dynamische Kraftausdauer mit mittleren Krafteinsätzen und dynamische Kraftausdauer mit geringem Kraftaufwand hinsichtlich der Energiebereitstellung.","a":"• Maximalkraftausdauer: anaerob-laktazid\n• Mittlere Krafteinsätze: anaerob-aerob\n• Geringer Kraftaufwand: überwiegend aerob","e":"Maximalkraftausdauer ist eine extreme, meist statische Belastung. Je höher der Krafteinsatz pro Bewegung, desto stärker werden die Kapillaren abgedrückt und desto anaerober wird es. Beispiel: Turner im Kreuzhang (laktazid), Ruderer oder Sprintschwimmer (gemischt), Langstreckenschwimmer (aerob).","quelle":"L13.4","typ":"kern"},{"id":"q2.2-082","thema":"Q2.2","kapitel":"Krafttests","q":"Welche Kraftfähigkeiten werden mit Krafttests überprüft? Nenne jeweils passende Tests.","a":"• Maximalkraft: Handkrafttest, 1RM (bzw. Mehrfachwiederholungen)\n• Schnell-/Reaktivkraft Beine: SJ, CMJ, Drop-Jump, Jump-and-Reach, Standweitsprung\n• Schnellkraft Arme: Medizinball-Stoß\n• Kraftausdauer: kraft- und ausdauerbetonte Tests","e":"Die 1RM wird meist über Mehrfachwiederholungen mit Umrechnung bestimmt. Kraftausdauer: kraftbetont z. B. 30 CMJs in 60 s, ausdauerbetont z. B. maximale Liegestütze in 40 s. Beispiel: Ein Leichtathletiktrainer nutzt CMJ und Drop-Jump, um zu sehen, ob ein Springer eher Schnellkraft- oder Reaktivkraftdefizite hat.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-083","thema":"Q2.2","kapitel":"Krafttests","q":"Beschreibe den Handkrafttest und begründe, warum er sich für den Kinder- und Jugendbereich eignet.","a":"• Greifkraftmessung mit Handdynamometer (beide Hände; absolut in kg oder relativ pro kg Körpergewicht)\n• Einziger Maximalkrafttest ohne hohes Verletzungsrisiko; korreliert hoch mit allgemeiner Maximalkraft","e":"Im Kinder- und Jugendbereich verzichtet man sonst wegen der Verletzungsgefahr auf Maximalkrafttests. Die Handkraft korreliert hoch mit maximaler Armkraft sowie Rücken- und Bauchkraft und bestimmt so schnell das allgemeine Kraftniveau. Relative Werte über 1,0 erreichen nur Kletterer und Turner. Beispiel: Ein Schüler der 10. Klasse drückt mit der dominanten Hand ca. 50 kg, bei 70 kg Körpergewicht ergibt das eine relative Handkraft von etwa 0,7.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-084","thema":"Q2.2","kapitel":"Krafttests","q":"Was überprüft die Einer-Wiederholung und warum wird sie in der Praxis meist über Mehrfachwiederholungen ermittelt?","a":"• 1RM = dynamische Maximalkraft (Gewicht, das genau einmal bewegt werden kann)\n• Praxis: Mehrfachwiederholungen wegen Verletzungsgefahr\n• MK = W / (1,0278 – 0,0278 · x) (Ferrauti; x = Wdh.)","e":"Der Zusammenhang zwischen Wiederholungszahl und Anteil der Maximalkraft ist linear: y = 1,0278 – 0,0278 · x. Richtwerte: 1 Wdh. = 100 %, 5 Wdh. ≈ 88 %, 10 Wdh. ≈ 75 %, 15 Wdh. ≈ 61 %. Statt das gefährliche Maximum zu testen, rechnet man es aus. Beispiel: Wer 60 kg genau 10-mal drücken kann, hat eine geschätzte Maximalkraft von 60 / (1,0278 – 0,278) ≈ 80 kg.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-085","thema":"Q2.2","kapitel":"Krafttests","q":"Begründe, warum die Wiederholungszahl bei der indirekten Maximalkraftbestimmung im Bereich von etwa 10 ± 5 Wiederholungen liegen sollte.","a":"• Wenige Wdh.: Last nahe Maximum → Verletzungsrisiko\n• Viele Wdh.: Kraftausdauer bestimmt die Leistung, Formel wird ungenau\n• 5–15 Wdh.: praktikabel und ausreichend genau","e":"Bei vielen Wiederholungen wirken sich kleine Zählfehler stark aus, und der Nenner der Formel (1,0278 – 0,0278 · x) nähert sich der Null – die Schätzung wird extrem empfindlich. Zu wenige Wiederholungen sind gefährlich, zu viele messen Ausdauer statt Kraft. Beispiel: Ob jemand mit 30 kg 35 oder 37 Wiederholungen schafft, hängt stark von Motivation und Ermüdung ab – die errechnete Maximalkraft würde stark schwanken.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-086","thema":"Q2.2","kapitel":"Krafttests","q":"Unterscheide Squat-Jump, Counter-Movement-Jump und Drop-Jump hinsichtlich Durchführung und überprüfter Kraftfähigkeit.","a":"• Squat-Jump: aus tiefer Hocke ohne Auftakt → Schnellkraft (konzentrisch)\n• CMJ: mit Ausholbewegung → exzentrisch-konzentrische Schnellkraft\n• Drop-Jump: aus 15–60 cm, kürzester Bodenkontakt → Reaktivkraft\n(jeweils ohne Armeinsatz)","e":"Gemessen werden Sprunghöhe und Bodenkontaktzeit mit einer Kraftmessplatte; der Drop-Jump erfasst auch die elementare azyklische Schnelligkeit. Die Sprünge unterscheiden sich im Dehnungs-Verkürzungs-Zyklus: SJ keiner, CMJ ein langsamer, DJ ein schneller. Beispiel: Springt ein Athlet beim CMJ deutlich höher als beim SJ, nutzt er die exzentrische Vordehnung gut.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-087","thema":"Q2.2","kapitel":"Krafttests","q":"Beschreibe den Jump-and-Reach-Test und den Standweitsprung als Tests der Sprungkraft.","a":"• Jump-and-Reach: seitlich an der Wand hochspringen, mit Kreide antippen; Sprunghöhe = Reichhöhe im Sprung – im Stand → vertikale Sprungkraft\n• Standweitsprung: beidbeinig mit Armeinsatz in die Weite → horizontale Sprungkraft","e":"Der Jump-and-Reach-Test (Differenzsprung) ist die Alternative, wenn keine Kraftmessplatte vorhanden ist; er misst die dynamische Schnellkraft der Beine. Beide Sprungkräfte sollten getrennt erfasst werden, da teilweise unterschiedliche Muskelgruppen beteiligt sind (Weineck). Beispiel: Ein Volleyballer schneidet beim Jump-and-Reach-Test sehr gut ab, ein Weitspringer eher beim Standweitsprung – beide Fähigkeiten müssen unterschiedlich trainiert werden.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-088","thema":"Q2.2","kapitel":"Krafttests","q":"Welche Muskelgruppen sind beim Jump-and-Reach-Test, beim Standweitsprung und beim beidarmigen Medizinball-Stoß-Test besonders beteiligt?","a":"• Jump-and-Reach: Knie-, Hüft-, Fußstrecker (Quadrizeps, Gluteus maximus, Triceps surae)\n• Standweitsprung: dieselben, Hüftstrecker und Rumpf stärker\n• Medizinball-Stoß: Trizeps, großer Brustmuskel, vorderer Deltamuskel","e":"Beim Jump-and-Reach helfen zusätzlich Rückenstrecker und Armschwung. Beim Standweitsprung sind Gesäß und ischiocrurale Muskulatur stärker beteiligt. Beim Medizinballstoß stabilisiert der Rumpf. Stell dir die Bewegung vor: Welche Gelenke werden gestreckt? Deren Strecker arbeiten. Beispiel: Beim Medizinballstoß werden die Ellbogen gestreckt und die Arme nach vorn gebracht → Trizeps und Brustmuskel.","quelle":"L16.3","typ":"zusatz"},{"id":"q2.2-089","thema":"Q2.2","kapitel":"Krafttests","q":"Beschreibe den beidarmigen Medizinball-Stoß-Test.","a":"Ball mit angewinkelten Armen vor der Brust halten und aus dem Stand möglichst weit stoßen; gemessen wird die Weite → Schnellkraft der oberen Extremitäten.","e":"Der Medizinballstoß ist das Gegenstück zum Sprungtest für die Arme und prüft die Wurf- bzw. Stoßkraft. Beispiel: Ein Handballer oder Basketballer kann so überprüfen, ob sein Schnellkrafttraining für Arme und Brust wirkt.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-090","thema":"Q2.2","kapitel":"Krafttests","q":"Unterscheide kraftbetonte und ausdauerbetonte Kraftausdauertests.","a":"Jeweils 30–60 s:\n• Kraftbetont: maximale Kraftleistung wiederholt, gemessen wird der Abfall (z. B. 30 CMJs in 60 s)\n• Ausdauerbetont: mittlere Kraftimpulse möglichst oft, gemessen wird die Anzahl (z. B. Liegestütze in 40 s)","e":"Beim kraftbetonten Test gilt: Je langsamer die Sprunghöhe abnimmt, desto besser die Ermüdungswiderstandsfähigkeit. Kraftbetont: Wie gut bleibt die Leistung hoch? Ausdauerbetont: Wie oft schaffe ich es? Beispiel: Sinkt die CMJ-Höhe eines Volleyballers in 60 s nur von 50 auf 45 cm, hat er eine sehr gute Sprungkraftausdauer.","quelle":"L16.3","typ":"kern"},{"id":"q2.2-091","thema":"Q2.2","kapitel":"Krafttests","q":"Beurteile den Standweitsprung als sportmotorischen Test (z. B. im Rahmen einer Bewertungstabelle) kritisch.","a":"• Positiv: objektiv, reliabel, einfach, ohne teure Geräte\n• Kritisch: Validität eingeschränkt (Technik, Koordination, Körpergröße, -gewicht); nur horizontale Sprungkraft; Normtabellen berücksichtigen Alter, Körperbau, Trainingszustand nicht fair","e":"Konkret: Bei Mädchen gelten gleiche Normwerte für 15–17 Jahre, bei Jungen sind sie altersgestaffelt – Entwicklungsunterschiede werden also uneinheitlich behandelt; das biologische Alter bleibt unberücksichtigt. Ein guter Test sollte objektiv, zuverlässig und gültig sein, die Bewertung fair. Beispiel: Ein großer, schwerer Schüler kann trotz guter Beinkraft im Standweitsprung schlechter abschneiden als ein kleiner, leichter.","quelle":"L16.3","typ":"zusatz"},{"id":"q2.2-092","thema":"Q2.2","kapitel":"Krafttests","q":"Erkläre, warum die relative Handkraft (kg pro kg Körpergewicht) aussagekräftiger sein kann als die absolute Handkraft.","a":"• Absolute Kraft steigt mit Körpergröße und -masse\n• Relative Kraft berücksichtigt das Gewicht → fairer Vergleich\n• Leistungslimitierend, wenn der eigene Körper bewegt wird (Klettern, Turnen)","e":"Nur Kletterer und Turner erreichen Werte über 1,0. Bei Jugendlichen steigt die absolute Handkraft in der Pubertät sprunghaft (z. B. von ca. 32 kg in Klasse 9 auf ca. 53 kg in Klasse 10), die relative moderater. Absolut: Wie stark bist du? Relativ: Wie stark für dein Gewicht? Beispiel: Ein 50-kg-Kletterer mit 55 kg Handkraft (1,1) hält sich an kleinen Leisten besser als ein 90-kg-Ruderer mit 70 kg Handkraft (0,78).","quelle":"L16.3","typ":"kern"},{"id":"q2.3-001","thema":"Q2.3","kapitel":"Grundbegriffe Schnelligkeit","q":"Definiere den Begriff Schnelligkeit bei sportlichen Bewegungen.","a":"Schnelligkeit ist die konditionell und koordinativ bestimmte Fähigkeit, auf Reize schnellstmöglich zu reagieren und/oder zyklische bzw. azyklische Bewegungen bei geringen Widerständen mit höchster Geschwindigkeit auszuführen (Steinhöfer).","e":"Schnelligkeit hat zwei Seiten: schnell loslegen (reagieren) und schnell bewegen. Wichtig ist der Zusatz „geringe Widerstände“, sonst wäre es eher Schnellkraft. Beispiel: Der Startschuss beim 100-m-Sprint verlangt Reaktion, der anschließende Lauf schnelle zyklische Bewegungen.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-002","thema":"Q2.3","kapitel":"Grundbegriffe Schnelligkeit","q":"Warum gilt Schnelligkeit als konditionell UND koordinativ bestimmte Fähigkeit?","a":"• Konditionell: Energiebereitstellung (ATP/KP), Muskelfasertyp, Kraft\n• Koordinativ: neuromuskuläre Steuerung (intra-/intermuskuläre Koordination, Agonist–Antagonist)\n→ Zwischenstellung","e":"Ein Sprinter braucht volle Energiespeicher (anaerob-alaktazid) und kräftige schnelle Muskelfasern, aber das Nervensystem muss die Muskeln auch perfekt im richtigen Moment an- und ausschalten. Beispiel: Ein kräftiger, aber unkoordinierter Läufer „bremst“ sich mit verkrampften Gegenspielern selbst aus.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-003","thema":"Q2.3","kapitel":"Grundbegriffe Schnelligkeit","q":"Wie wird Schnelligkeit physikalisch erfasst, und wodurch grenzt die biologische Definition sie von der Schnellkraft ab?","a":"• Physikalisch: Geschwindigkeit v = s / t\n• Biologisch: zusätzlich „geringer Widerstand“\n• Schnellkraft: höhere Widerstände möglichst schnell überwinden","e":"Die biologische Definition übernimmt die Geschwindigkeit aus der Physik und grenzt sich über den Widerstand ab. Merke: Schnelligkeit = schnell gegen wenig Widerstand, Schnellkraft = schnell gegen viel Widerstand (z. B. Körpergewicht beim Absprung). Beispiel: Schnelles Fußtippen auf der Stelle ist Schnelligkeit, ein Kugelstoß ist Schnellkraft.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-004","thema":"Q2.3","kapitel":"Grundbegriffe Schnelligkeit","q":"Unterscheide zyklische und azyklische Bewegungen.","a":"• Zyklisch: aufeinanderfolgende, gleiche (wiederholte) Bewegungen\n• Azyklisch: Einzelbewegungen, nicht fortlaufend wiederholt","e":"Zyklisch heißt „im Kreis“: Die Bewegung läuft immer wieder gleich ab, ob vom ganzen Körper oder von Körperteilen. Azyklisch ist eine einmalige Aktion. Beispiel: Laufen, Schwimmen und Radfahren sind zyklisch, Werfen, Springen oder ein Tischtennisschlag sind azyklisch.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-005","thema":"Q2.3","kapitel":"Grundbegriffe Schnelligkeit","q":"Beschreibe den Zusammenhang zwischen Schnelligkeit und Kraft.","a":"• Maximalkraft ist Basis der Schnellkraft und damit vieler Schnelligkeitsleistungen.\n• Je höher der Widerstand, desto größer der Krafteinfluss (komplexe Schnelligkeit).\n• Bei sehr geringen Widerständen dominiert die nervale Steuerung.","e":"Gemeinsame Grundlage von Kraft und Schnelligkeit sind intra- und intermuskuläre Koordination und viele schnelle FT-Fasern. Je schwerer das, was du beschleunigen musst, desto wichtiger wird Kraft, etwa bei Kraftschnelligkeit und Sprintkraft. Beim Beschleunigen aus dem Startblock musst du deinen ganzen Körper in Gang bringen. Beispiel: Ein schnelles Tippen mit dem Finger braucht kaum Kraft, ein Antritt im Basketball dagegen viel Beinkraft.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-006","thema":"Q2.3","kapitel":"Arten der Schnelligkeit","q":"Wie lässt sich die motorische Schnelligkeit nach Grosser und Zintl einteilen?","a":"• Reaktionsschnelligkeit\n• Elementar: Aktions- (azyklisch), Frequenzschnelligkeit (zyklisch)\n• Komplex:\n  – Kraftschnelligkeit (azyklisch, Kraft)\n  – Kraftschnelligkeitsausdauer (azyklisch, Ausdauer)\n  – Sprintkraft (zyklisch, Kraft)\n  – Sprintausdauer (zyklisch, Ausdauer)","e":"Stell dir einen Baum vor: Ganz unten die Reaktion, dann die „reine“ (elementare) Schnelligkeit und die „gemischte“ (komplexe) Schnelligkeit, bei der Kraft oder Ausdauer mitspielen. Kraftschnelligkeitsausdauer heißt auch Schnellkraftausdauer. Beispiel: Ein Sprinter braucht fast alle Äste: Reaktion beim Start, Sprintkraft beim Beschleunigen, Frequenzschnelligkeit im Höchsttempo und Sprintausdauer am Ende.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-007","thema":"Q2.3","kapitel":"Arten der Schnelligkeit","q":"Definiere Reaktionsschnelligkeit.","a":"Fähigkeit, schnellstmöglich auf Reize (akustisch, optisch, taktil) zu reagieren. Maß: Reaktionszeit vom Reiz bis zum Bewegungsbeginn.","e":"Es geht nicht darum, wie schnell du läufst, sondern wie schnell du nach dem Signal überhaupt losgehst. Beispiel: Der Start beim 100-m-Sprint auf den Startschuss oder das Reagieren auf eine Täuschung des Gegners im Basketball 1:1.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-008","thema":"Q2.3","kapitel":"Arten der Schnelligkeit","q":"Was versteht man unter elementaren Schnelligkeitsfähigkeiten?","a":"Schnelligkeit bei zyklischen und azyklischen Bewegungen gegen geringe Widerstände, bestimmt v. a. durch neuromuskuläre Steuerung (Zeitprogramme <170 ms).\n• Aktionsschnelligkeit (azyklisch)\n• Frequenzschnelligkeit (zyklisch)","e":"Elementar heißt hier „rein nervlich“: Die Leistung wird über elementare Zeitprogramme bestimmt; Kraft und Ausdauer spielen kaum eine Rolle. Ein hohes Niveau setzt kurze Zeitprogramme unter 170 Millisekunden voraus – diese Grenze taucht auch beim Drop-Jump-Test wieder auf. Beispiel: Ein Tischtennisspieler, der blitzschnell den Schläger durchzieht.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-009","thema":"Q2.3","kapitel":"Arten der Schnelligkeit","q":"Definiere Aktionsschnelligkeit und Frequenzschnelligkeit und grenze sie voneinander ab.","a":"Höchste Geschwindigkeit gegen geringe Widerstände bei\n• Aktionsschnelligkeit: azyklischen Bewegungen (Einzelbewegung)\n• Frequenzschnelligkeit: zyklischen Bewegungen (Wiederholungen)","e":"Beide sind elementare Schnelligkeit; der Unterschied liegt nur in der Bewegungsstruktur. Aktion = eine einzelne schnelle Aktion, Frequenz = viele schnelle Wiederholungen hintereinander. Beispiel: Der Schmetterschlag im Tischtennis erfordert Aktionsschnelligkeit, Kniehebelauf oder ein fliegender 20-m-Sprint erfordern Frequenzschnelligkeit.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-010","thema":"Q2.3","kapitel":"Arten der Schnelligkeit","q":"Warum kommen reine Frequenz- und Aktionsschnelligkeit in den Sportspielen eher selten vor?","a":"Im Spiel kommen fast immer Kraft (Körpergewicht/Gerät beschleunigen) und Ausdauer (Ermüdung) hinzu → es dominieren komplexe Schnelligkeit und Handlungsschnelligkeit.","e":"Die elementare Schnelligkeit ist sozusagen die „Laborform“. Spieler müssen meist höhere Widerstände beschleunigen und wiederholt unter Ermüdung agieren. Beispiel: Ein Fußballer sprintet nicht ausgeruht 20 m geradeaus, sondern startet aus dem Stand, wechselt die Richtung und das zum zehnten Mal in der Halbzeit.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-011","thema":"Q2.3","kapitel":"Komplexe Schnelligkeit","q":"Was versteht man unter komplexen Schnelligkeitsfähigkeiten?","a":"Schnelle Bewegungen, bei denen neben der elementaren Schnelligkeit auch Kraft und Ausdauer großen Einfluss haben (höhere Widerstände, ermüdungsbedingter Leistungsabfall).\nFormen: Kraftschnelligkeit, Kraftschnelligkeitsausdauer, Sprintkraft, Sprintausdauer","e":"Komplex heißt: Schnelligkeit plus etwas anderes, nämlich Kraft (höherer Widerstand) oder Ausdauer (Ermüdung). Die Einteilung in die vier Formen ist praxisorientiert, nicht wissenschaftlich begründet. Beispiel: Ein Speerwurf nach Anlauf ist schnell, braucht aber eben auch viel Kraft.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-012","thema":"Q2.3","kapitel":"Komplexe Schnelligkeit","q":"Definiere Kraftschnelligkeit.","a":"Schnelligkeitsleistungen gegen höheren Widerstand in azyklischen Bewegungen (komplex, kraftakzentuiert).","e":"Eine einzelne, explosive Bewegung, bei der ein spürbarer Widerstand überwunden werden muss. Beispiel: Absprung nach einem Anlauf, Kugelstoß, Armausstoß oder Speerabwurf.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-013","thema":"Q2.3","kapitel":"Komplexe Schnelligkeit","q":"Definiere Kraftschnelligkeitsausdauer (Schnellkraftausdauer).","a":"Widerstandsfähigkeit gegen ermüdungsbedingten Geschwindigkeitsabfall bei azyklischen Schnellkraftbewegungen (= Schnellkraftausdauer; komplex, ausdauerakzentuiert).","e":"Es geht darum, viele explosive Einzelaktionen nacheinander gleich schnell auszuführen, ohne dass sie durch Ermüdung langsamer werden. Beispiel: wiederholte Kampfaktionen im Judo oder viele Würfe nacheinander im Handballtraining.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-014","thema":"Q2.3","kapitel":"Komplexe Schnelligkeit","q":"Definiere Sprintkraft.","a":"Schnelligkeitsleistungen gegen höhere Widerstände in zyklischen Bewegungen (komplex, kraftakzentuiert); v. a. in der Beschleunigungsphase.","e":"Wenn du aus dem Stand losläufst, musst du mit jedem Schritt deinen Körper weiter beschleunigen, das kostet viel Kraft. Beispiel: das Beschleunigen beim Sprintlauf, beim Radfahren (Antritt) oder beim Rudern.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-015","thema":"Q2.3","kapitel":"Komplexe Schnelligkeit","q":"Definiere Sprintausdauer und nenne ihre zeitliche Begrenzung.","a":"Widerstandsfähigkeit gegen ermüdungsbedingten Geschwindigkeitsabfall bei maximalen zyklischen Schnelligkeitsleistungen.\nGrenze: ca. 30 s (bis ca. 250 m).","e":"Sprintausdauer heißt auch maximale Schnelligkeitsausdauer; sie ist komplex, zyklisch und ausdauerakzentuiert. Gemeint ist: das Höchsttempo möglichst lange halten. Nach etwa 30 Sekunden geht das nicht mehr mit voller Intensität. Beispiel: Ein 200-m-Läufer muss auf der Zielgeraden gegen das Langsamerwerden ankämpfen.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-016","thema":"Q2.3","kapitel":"Komplexe Schnelligkeit","q":"Grenze Sprintausdauer und Schnelligkeitsausdauer voneinander ab.","a":"• Sprintausdauer: maximale Schnelligkeit bis ca. 30 s (Schnelligkeit i. e. S.)\n• Darüber nur noch hohe, nicht höchste Intensität → Ausdauer (Kurzzeitausdauer)","e":"Schnelligkeitsausdauer ist im engeren Sinn nur dann eine Schnelligkeitsleistung, wenn das Tempo maximal ist. Faustregel: Bis 30 Sekunden ist es noch Schnelligkeit, danach Ausdauer. Beispiel: Ein 200-m-Lauf (ca. 20–25 s) ist Sprintausdauer, ein 400-m-Lauf (ca. 45–60 s) ist schon Kurzzeitausdauer, weil das Tempo nicht mehr maximal sein kann.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-017","thema":"Q2.3","kapitel":"Handlungsschnelligkeit","q":"Definiere Handlungsschnelligkeit.","a":"Fähigkeit, technisch-taktische Handlungen situationsgerecht und präzise in optimaler Zeit und Intensität effektiv zu realisieren (Steinhöfer).","e":"Der Begriff stammt aus den Sportspielen und ergänzt die rein motorische Schnelligkeit. Im Spiel zählt nicht nur, wie schnell du rennst, sondern wie schnell du die richtige Entscheidung triffst und umsetzt. „Optimal“ statt „maximal“: Manchmal ist ein gut getimter Pass besser als der schnellstmögliche. Beispiel: Ein Point Guard erkennt die Lücke, entscheidet sich zum Durchbruch und spielt im richtigen Moment ab.","quelle":"L14.1","typ":"kern"},{"id":"q2.3-018","thema":"Q2.3","kapitel":"Handlungsschnelligkeit","q":"Aus welchen Komponenten setzt sich die Handlungsschnelligkeit zusammen (Steinhöfer)?","a":"• Motorisch: koordinativ (inter-/intramuskuläre Koordination, Techniken) und konditionell (Antritts-, Sprung-, Wurfkraft)\n• Kognitiv: Informationsaufnahme und -verarbeitung (Wahrnehmen, Antizipieren, Entscheiden)","e":"Die motorische Komponente beruht auf neurophysiologischen, die kognitive auf psychischen Vorgängen. Handlungsschnelligkeit = Kopf plus Körper. Der Kopf nimmt wahr, sagt voraus und entscheidet, der Körper führt technisch sauber und kraftvoll aus. Beispiel: Ein Handball-Torwart muss den Wurf des Gegners vorausahnen (kognitiv) und dann explosiv in die Ecke springen (motorisch).","quelle":"L14.1","typ":"kern"},{"id":"q2.3-019","thema":"Q2.3","kapitel":"Einflussfaktoren","q":"Nenne und erläutere die wichtigsten Einflussfaktoren (leistungsbestimmenden Faktoren) der Schnelligkeit.","a":"• Neuronal: Ansteuerung motorischer Einheiten, Nervenleitgeschwindigkeit\n• Muskulär: FT-Faser-Anteil, Querschnitt\n• Koordination/Technik\n• Kraft (Maximal-, Schnell-, Reaktivkraft)\n• Energie: ATP/KP\n• Elastizität, Entspannungsfähigkeit\n• Psyche: Konzentration, Antizipation\n• Weitere: Temperatur, Ermüdung, Alter","e":"Schnelligkeit hängt von vielen Rädchen ab. Neuronal zählen Rekrutierung und Frequenzierung motorischer Einheiten und der schnelle Wechsel von Erregung und Hemmung. Eine entspannungsfähige Muskulatur senkt innere Widerstände. Gut trainierbar sind Technik und Kraft, kaum dagegen der genetisch festgelegte Fasertyp; auch Geschlecht und Körperbau spielen mit. Beispiel: Zwei gleich kräftige Sportler sprinten unterschiedlich schnell, weil einer mehr FT-Fasern und eine bessere Lauftechnik hat.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.3-020","thema":"Q2.3","kapitel":"Einflussfaktoren","q":"Welche Bedeutung hat die Muskelfaserzusammensetzung für die Schnelligkeit?","a":"• FT-Fasern (Typ II) kontrahieren schneller und kräftiger als ST-Fasern, ermüden aber rascher.\n• Hoher FT-Anteil = wesentliche Voraussetzung.\n• Verteilung weitgehend genetisch; trainierbar v. a. Querschnitt und Ansteuerung.","e":"Die Muskelfasern sind wie die Motoren: Manche Menschen haben von Geburt an mehr „Sportwagenmotoren“, und Training kann die Verteilung nur begrenzt verändern. Deshalb sagt man oft, Sprinter würden geboren. Beispiel: Spitzensprinter haben häufig 70–80 % FT-Fasern in der Wadenmuskulatur, Marathonläufer eher ST-Fasern.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.3-021","thema":"Q2.3","kapitel":"Einflussfaktoren","q":"Welche Rolle spielt die Energiebereitstellung bei Schnelligkeitsleistungen?","a":"• Bis ca. 5–7 s: anaerob-alaktazid über ATP/KP, kaum Laktat\n• Bis ca. 30 s (Sprintausdauer): zunehmend anaerob-laktazid","e":"Für einen kurzen Sprint nutzt der Muskel seinen „Sofortspeicher“ KP, der schnell, aber klein ist. Training mit Belastungen von ca. 5 s verbessert gezielt diese KP-Speicher. Darum sind kurze Sprints mit langen Pausen ideal: Der Speicher kann sich wieder auffüllen. Beispiel: Ein 40-m-Sprint dauert ca. 5 s und wird fast nur aus dem KP-Speicher bezahlt.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-022","thema":"Q2.3","kapitel":"Einflussfaktoren","q":"Erläutere die Bedeutung der Maximalkraft für einen 100-m-Sprinter.","a":"• Basis der Schnell- und Reaktivkraft\n• Start/Beschleunigung: Körper gegen Trägheit beschleunigen (Sprintkraft)\n• Höchsttempo: kurze Bodenkontakte mit hohem Kraftstoß (Reaktivkraft)\n• Training über IK-Methode (ohne viel Masse)","e":"Je mehr Kraft in kurzer Zeit auf den Boden gebracht wird, desto stärker wird der Körper nach vorn geschoben. Das Training der intramuskulären Koordination verbessert die Ansteuerung der FT-Fasern; zu viel Muskelmasse wäre dagegen zusätzliches Gewicht. Beispiel: Sprinter trainieren schwere Kniebeugen mit wenigen Wiederholungen, um explosiver aus dem Block zu kommen.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-023","thema":"Q2.3","kapitel":"Einflussfaktoren","q":"Nimm Stellung zur Aussage „Gute Sprinter werden als solche geboren!“","a":"Teilweise richtig:\n• genetisch: FT-Anteil, nervale Grundgeschwindigkeit, Reaktionszeit, Körperbau; elementare Schnelligkeit kaum trainierbar\nAber:\n• trainierbar: Kraft, Technik, anaerobe Energie, Sprintausdauer, Antizipation\nFazit: Anlage notwendig, Spitzenleistung erst durch Training","e":"Eine frühzeitige Schulung im Kindesalter legt wichtige Grundlagen. Talent ist der Rohdiamant, Training der Schliff. Ohne Talent wird man kaum Weltklasse, ohne Training aber auch nicht. Beispiel: Ein Kind mit vielen schnellen Fasern, das nie Sprinttechnik und Kraft trainiert, wird von einem weniger begabten, aber gut trainierten Sprinter geschlagen.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-024","thema":"Q2.3","kapitel":"Einflussfaktoren","q":"Wie gut sind die verschiedenen Schnelligkeitsarten trainierbar?","a":"• Reaktionsschnelligkeit: kaum (über Technik, Antizipation)\n• Elementare Schnelligkeit: stark genetisch, am besten im Kindesalter\n• Komplexe Schnelligkeit: gut (Kraft und Ausdauer trainierbar)","e":"Die Reaktionszeit ist an angeborene Komponenten der neuralen Steuerung gebunden. Je mehr Kraft und Ausdauer in einer Schnelligkeitsart stecken, desto mehr kannst du durch Training herausholen. Beispiel: Deine Reaktionszeit auf einen Startschuss wirst du kaum halbieren, deine Zeit über 30 m aber durch Krafttraining deutlich verbessern.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-025","thema":"Q2.3","kapitel":"Einflussfaktoren","q":"Beschreibe den Ablauf (die Komponenten) der Reaktionszeit.","a":"Zeit vom Reiz bis zum Bewegungsbeginn:\n• Reizaufnahme (Rezeptor)\n• afferente Leitung zum ZNS\n• Verarbeitung im ZNS\n• efferente Leitung zum Muskel\n• Muskelerregung bis Kraftentwicklung\nEinfach- vs. Wahlreaktion (länger)","e":"Die Reaktion ist wie eine Staffel durch den Körper: Sinnesorgan, Nerv, Gehirn, Nerv, Muskel. Am meisten Zeit kostet das Gehirn (Wahrnehmung, Entscheidung, Programmierung), vor allem bei der Wahlreaktion mit mehreren Signalen oder Antworten. Beispiel: Beim Sprintstart (Einfachreaktion) reagieren Topathleten in ca. 0,12–0,15 s, ein Torwart beim Elfmeter (Wahlreaktion) braucht deutlich länger und muss deshalb antizipieren.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.3-026","thema":"Q2.3","kapitel":"Antizipation","q":"Was versteht man unter Antizipation, und welche Bedeutung hat sie für die Reaktionsschnelligkeit?","a":"Antizipation: gedankliche Vorwegnahme von Ereignissen, Bewegungen oder Zeitpunkten.\nBedeutung: verkürzt die effektive Reaktionszeit; unter Zeitdruck (Sportspiel) unverzichtbar.","e":"Im Sportspiel wäre eine reine Reaktion oft zu langsam, darum ist die Antizipationsfähigkeit für die Reaktionsschnelligkeit ganz wesentlich. Wer vorausahnt, was passiert, kann schon früher anfangen zu handeln; das gilt auch für das Startsignal (Zeitwahrnehmung). Beispiel: Ein Volleyball-Abwehrspieler erkennt am Anlauf und an der Armhaltung des Angreifers, wohin geschmettert wird, und steht schon richtig.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-027","thema":"Q2.3","kapitel":"Antizipation","q":"Welche Ansatzpunkte hat die Reaktionsmethode, und warum ist die Reaktionsschnelligkeit nur begrenzt trainierbar?","a":"Ansatzpunkte:\n• Einschleifen der Technik mit Übergang in die Beschleunigung\n• Antizipation (Zeitwahrnehmung)\nBegrenzt trainierbar, da an angeborene Komponenten der neuralen Steuerung gebunden (Grosser & Zintl).","e":"Die „Leitungsgeschwindigkeit“ der Nerven kannst du kaum verändern, aber du kannst die Bewegung so automatisieren, dass sie ohne Zögern abläuft, und lernen, das Signal vorauszuahnen. Beispiel: Ein Sprinter übt den Start so oft, bis die Bewegung aus dem Block automatisch abläuft und direkt in die Beschleunigung übergeht.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-028","thema":"Q2.3","kapitel":"Antizipation","q":"Erläutere, warum das Starttraining im Sprint ein gutes Beispiel für die Schulung der Antizipation ist.","a":"Reaktion auf wechselnde Zeitintervalle zwischen „Fertig“ und Startsignal (Zeitwahrnehmung). Geschult werden:\n• Konzentration (sensorischer Anteil)\n• optimale Muskelvorspannung (motorischer Anteil)","e":"Der Sprinter kann das genaue Signal nicht vorhersagen, aber er lernt das typische Zeitfenster einzuschätzen und ist dann voll konzentriert und vorgespannt. Beispiel: Im Training variiert der Trainer die Zeit zwischen „Fertig“ und Pfiff, damit der Sportler nicht einfach losrät, sondern präzise reagiert.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-029","thema":"Q2.3","kapitel":"Antizipation","q":"Wie erfolgt die Reaktionsschulung bei Spielsportlern?","a":"• im Technik- und Taktiktraining\n• mehrere verschiedene Reaktionshandlungen nacheinander (Vorbereitung auf Wahlreaktionen)\n• spielspezifisch statt nur allgemein","e":"Im Spiel gibt es nie nur ein Signal, sondern viele Möglichkeiten. Deshalb reicht allgemeine Reaktionsschulung nicht; die Reaktion muss im Spielkontext an komplexen Handlungen geübt werden. Beispiel: Ein Basketballer übt Verteidigung im 1:1 und reagiert dabei auf die echten Täuschungen eines Mitspielers.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-030","thema":"Q2.3","kapitel":"Antizipation","q":"Was ist die Antizipationsmethode (nach Steinhöfer)?","a":"Reaktionstraining im Rahmen des Technik-/Taktiktrainings zur Schulung spielspezifischer Reaktions- und Antizipationshandlungen auf komplexe Signale (Gegner, Ball, Mitspieler).","e":"Begründung: Reaktionen im Spiel erfolgen unter Zeitdruck, daher muss antizipiert werden. Die Antizipationsmethode trainiert das „Lesen“ des Spiels: Der Spieler soll Hinweise sammeln, bevor die eigentliche Aktion passiert. Beispiel: Feldabwehr im Volleyball, Schussabwehr beim Torwart oder Reaktionsleistungen im Basketball im Spiel 1:1.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-031","thema":"Q2.3","kapitel":"Antizipation","q":"Nenne Inhalte eines allgemeinen Reaktionstrainings.","a":"• Starts aus verschiedenen Positionen\n• Richtungswechsel/Antritte auf Signal\n• Bälle fangen/abwehren unter Zeitdruck\n• Hinlegen, Aufstehen, Springen auf Signal\n• Reaktionsspiele\n• Signalart variieren (akustisch, optisch, taktil)","e":"Allgemeines Reaktionstraining ist ein guter Einstieg, z. B. im Aufwärmen. Für Spielsportler muss es aber später spielspezifisch werden. Beispiel: Beim Spiel „Schwarz-Weiß“ liegen zwei Gruppen am Boden und müssen auf Zuruf blitzschnell fliehen oder fangen.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-032","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Nenne die vier im Buch beschriebenen Methoden bzw. Inhalte des Schnelligkeitstrainings.","a":"• Sprintlauf\n• Koordinationsmethode\n• Sprintausdauermethode\n• Reaktionsmethode (inkl. Antizipationsmethode)","e":"Jede Methode zielt auf eine andere Schnelligkeitsart: Sprintlauf auf Beschleunigung, Koordinationsmethode auf das Zusammenspiel der Muskeln, Sprintausdauermethode auf das Halten des Tempos und Reaktionsmethode auf den schnellen Start. Ergänzt werden sie durch trainingspraktische Grundsätze. Beispiel: Ein Sprinter kombiniert alle vier über die Trainingswoche.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-033","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Was schult der Sprintlauf mit einer Länge von 15–50 m?","a":"• Beschleunigungsvermögen\n• anaerob-alaktazide Kapazität (KP)\n• intermuskuläre Koordination","e":"Kurze Sprints sind kurz genug, dass fast kein Laktat entsteht, und lang genug, um Beschleunigung zu trainieren. Beispiel: Ein Fußballer sprintet im Training 6 × 30 m mit voller Pause, um seinen Antritt zu verbessern.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-034","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"In welche Abschnitte wird eine Sprintstrecke nach ihren Geschwindigkeitswerten eingeteilt (nach Jonath et al.)?","a":"• Reaktionsabschnitt\n• positive Beschleunigung (bis Maximalgeschwindigkeit)\n• gleichförmige (maximale) Geschwindigkeit\n• negative Beschleunigung (Geschwindigkeitsabfall)","e":"Merke: reagieren, beschleunigen, halten, langsamer werden. Wer am Ende am wenigsten abbaut, gewinnt oft. Beispiel: Beim 100-m-Lauf ist der Startschuss der Reaktionsabschnitt, die ersten ca. 30–40 m sind Beschleunigung, danach folgt das Höchsttempo und auf den letzten Metern der Geschwindigkeitsabfall.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-035","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Beschreibe den typischen Geschwindigkeits-Weg-Verlauf eines 100-m-Sprints.","a":"• starke Beschleunigung nach der Reaktion (Hauptarbeit auf ca. 30 m)\n• dann annähernd gleichförmige Höchstgeschwindigkeit\n• am Ende ermüdungsbedingter Abfall\n• Bessere Läufer: längeres Plateau, geringerer Abfall","e":"Die Beschleunigungsphase dauert je nach Leistungsstand ca. 30–40 m, bei Topsprintern bis zu 60–90 m; ab ca. 20–30 m nimmt die Geschwindigkeit aber nur noch gering zu. Die Kurve sieht aus wie ein steiler Anstieg, ein Plateau und ein leichter Abfall. Beispiel: Weltklassesprinter erreichen ihr Maximaltempo oft erst nach 60 m und werden auf den letzten 20 m kaum langsamer.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-036","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Welche Schnelligkeitsarten werden beim 100-m-Lauf benötigt? Ordne sie den Abschnitten zu.","a":"• Reaktion: Reaktionsschnelligkeit (Einfachreaktion)\n• Beschleunigung: Sprintkraft (Blockabdruck: Kraftschnelligkeit)\n• Höchstgeschwindigkeit: Frequenzschnelligkeit, Reaktivkraft\n• Geschwindigkeitsabfall: Sprintausdauer","e":"Der 100-m-Lauf ist eine Reise durch fast alle Schnelligkeitsarten: Beim Beschleunigen muss die eigene Körpermasse als hoher Widerstand bewegt werden, im Höchsttempo sind die Widerstände gering. Beispiel: Ein Sprinter mit tollem Start, aber schwacher Sprintausdauer führt bei 50 m und wird auf den letzten Metern noch abgefangen.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-037","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Warum werden Beschleunigungs- und Sprintschnelligkeit komplex trainiert, und mit welchen Sprints?","a":"Höchsttempo erst nach ca. 30 m → nicht sinnvoll trennbar.\n• Beschleunigungssprints 30–40 m\n• standardisierte, optimale Bedingungen\n• Wiederholungsmethode (ca. 5 s, anaerob-alaktazid)","e":"Belastungen von etwa 5 Sekunden werden aus ATP und KP gedeckt und führen kaum zu Laktat, deshalb passt die Wiederholungsmethode. Um schnell zu laufen, musst du erst einmal schnell werden, darum werden beide Teile gemeinsam geübt. Beispiel: 4 × 40 m aus dem Hochstart mit voller Pause trainieren Antritt und Höchsttempo zugleich.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-038","thema":"Q2.3","kapitel":"Belastungsnormative","q":"Nenne die Belastungsnormative für das Training der Beschleunigungs- und Sprintschnelligkeit (Sprintlauf).","a":"Wiederholungsmethode (Steinhöfer):\n• Intensität: 100 %\n• Dauer: 15–50 m\n• Umfang: 3–4 Serien à 4–5 Sprints\n• Pausen: 2–3 min, Serienpause 4–5 min","e":"Das Training verbessert die anaerob-alaktazide Energiebereitstellung (KP-Speicher) und die intermuskuläre Koordination. Maximal schnell, kurz, nicht zu viele Wiederholungen und lange Pausen, damit jeder Sprint wirklich mit vollem Tempo gelaufen wird. Beispiel: 3 Serien à 4 × 30 m, nach jedem Sprint 3 min Gehpause, zwischen den Serien 5 min.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-039","thema":"Q2.3","kapitel":"Belastungsnormative","q":"Welche Faustregel gilt für die Pausenlänge beim Training der Beschleunigungs- und Sprintschnelligkeit?","a":"Pro 10 m Sprintstrecke ca. 1 Minute Pause (Weineck).","e":"Die Pause muss vollständig sein: Die KP-Speicher füllen sich wieder auf und das Nervensystem erholt sich, sodass jeder Sprint maximal schnell erfolgen kann – eine lohnende Pause reicht nicht. Einfach zu merken: 10 m = 1 Minute. Beispiel: Nach einem 40-m-Sprint gönnst du dir ca. 4 Minuten Pause, nach einem 20-m-Sprint ca. 2 Minuten.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-040","thema":"Q2.3","kapitel":"Belastungsnormative","q":"Warum muss Schnelligkeit nach der Wiederholungsmethode trainiert werden?","a":"• Training nur mit maximaler Geschwindigkeit spricht FT-Fasern und anaerob-alaktazide Energie an.\n• Vollständige Pausen verhindern Ermüdung und das Einschleifen langsamer Bewegungsmuster.","e":"Die Wiederholungsmethode ist gekennzeichnet durch maximale Intensität, geringen Umfang und vollständige Pausen. Wer müde sprintet, trainiert langsames Sprinten. Die langen Pausen sind daher kein Faulenzen, sondern Teil der Methode. Beispiel: Ein Sprinter, der 10 × 50 m mit nur 30 s Pause läuft, trainiert eher Ausdauer als Schnelligkeit.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-041","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Was beinhaltet die Koordinationsmethode im Schnelligkeitstraining?","a":"Spezifische Übungen zur Schulung des Zusammenspiels von Agonist und Antagonist bei optimaler Amplitude und Frequenz (Steinhöfer); Schwierigkeit kontinuierlich steigern.\nWirkung: inter- und intramuskuläre Koordination","e":"Die Schwierigkeit wird über Informationsanforderungen und Druckbedingungen gesteigert, damit die Schnelligkeit nicht stagniert; geübt wird korrekt und ausgeruht. Wenn der Beuger arbeitet, muss der Strecker locker lassen, sonst bremst er die Bewegung. Genau dieses Timing wird trainiert. Beispiel: Beim Sprint-ABC (Skippings, Anfersen, Kniehebelauf) übt der Sportler schnelle Wechsel von An- und Entspannung.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-042","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Beschreibe die Koordinationsmethode nach Bewegungscharakteristik, Trainingsinhalten, besonderen Hinweisen und Trainingswirkung.","a":"• Charakteristik: An-/Entspannungswechsel, kleine/große Amplituden, kurze Bodenkontakte\n• Inhalte: Koordinations-, Steigerungs-, Sprung-, Treppenläufe, Sprint-ABC, Sprünge/Antritte über kleine Hindernisse\n• Hinweise: ausgeruht, korrekte Ausführung\n• Wirkung: inter-/intramuskuläre Koordination","e":"Das ist die „Tabelle“ zur Koordinationsmethode, die man gut auswendig lernen kann. Zur Bewegungscharakteristik gehören auch einfache und simultane Bewegungen; bei der Ausführung ist besonders auf Armarbeit und Körperspannung zu achten. Ergänzt werden sportartspezifische Koordinationsübungen. Beispiel: Eine Koordinationsleiter auf dem Boden, durch die der Sportler mit möglichst kurzen Bodenkontakten in schneller Folge läuft.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-043","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Begründe den Einsatz der Koordinationsmethode zur Verbesserung der Schnelligkeit eines Sprinters und eines Basketballers.","a":"Sprinter:\n• besseres Agonist-Antagonist-Zusammenspiel → höhere Schrittfrequenz, kurze Bodenkontakte, ökonomische Technik\nBasketballer:\n• schnellere Antritte, Richtungswechsel, Stopps; Informationsanforderungen → Handlungsschnelligkeit\nBeide: bessere inter-/intramuskuläre Koordination","e":"Beim Sprinter werden durch saubere Armarbeit und Körperspannung innere Widerstände reduziert. Beim Basketballer überträgt sich die Steigerung der Informationsanforderungen (Signale, Ball) auf das Spiel. Für beide gilt: Wer seine Muskeln besser koordiniert, wird schneller, ohne stärker zu werden. Beispiel: Der Sprinter arbeitet mit Sprint-ABC, der Basketballer mit Defense-Slides und Antritten über kleine Hürden auf Zuruf.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-044","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Was kennzeichnet die Sprintausdauermethode?","a":"• Strecken bis 200 m mit maximaler Intensität, Wiederholungsmethode (lange Pausen)\n• Ziel: Höchstintensität bis ca. 30 s halten\n• Limitierend: Programmermüdung, nicht Laktat","e":"Der begrenzende Faktor ist mit großer Wahrscheinlichkeit nicht Laktatanstieg oder Sauerstoffschuld, sondern das Nachlassen der differenzierten Steuerung der Bewegungsprogramme. Dass die Nervensteuerung „müde“ wird, merkt man daran, dass der Laufstil verkrampft. Beispiel: Ein 200-m-Läufer läuft 3 × 150 m maximal mit 8–10 Minuten Pause.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-045","thema":"Q2.3","kapitel":"Methoden Schnelligkeitstraining","q":"Was versteht man unter Programmermüdung?","a":"Nachlassen der differenzierten Steuerung der Bewegungsprogramme durch das ZNS bei maximalen Schnelligkeitsleistungen; wahrscheinlich limitierender Faktor der Sprintausdauer.","e":"Nicht Laktatanstieg oder Sauerstoffschuld bremsen in den ersten 30 Sekunden, sondern das Steuerprogramm im Kopf ermüdet. Koordination und Bewegungsfrequenz verschlechtern sich, die Geschwindigkeit sinkt. Beispiel: Auf den letzten 30 m eines 200-m-Laufs wird der Laufstil „unrund“, die Schritte werden kürzer und verkrampfter.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-046","thema":"Q2.3","kapitel":"Belastungsnormative","q":"Welche Belastungsnormative kennzeichnen die Sprintausdauermethode?","a":"Wiederholungsmethode:\n• Intensität: maximal (95–100 %)\n• Dauer: bis 200 m / ca. 30 s\n• Umfang: gering (z. B. 2–3 Serien à 2–4 Läufe)\n• Dichte: lange, vollständige Pausen","e":"Die Methode verbessert die Widerstandsfähigkeit gegen ermüdungsbedingten Geschwindigkeitsabfall und stabilisiert die Bewegungsprogramme. Das Buch nennt die Grundsätze (bis 200 m, maximal, lange Pausen), die Zahlen zum Umfang sind übliche Richtwerte; zwischen den Serien wird länger pausiert. Beispiel: 2 Serien à 3 × 120 m in maximalem Tempo mit 6 min Pause zwischen den Läufen und 12 min zwischen den Serien.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-047","thema":"Q2.3","kapitel":"Trainingsgrundsätze","q":"Auf welche drei Bereiche beziehen sich wichtige trainingspraktische Grundsätze zum Schnelligkeitstraining?","a":"• Biologische Parameter (z. B. Körperkerntemperatur)\n• Trainingsprinzipien (z. B. frühzeitige Schulung)\n• Belastungsparameter (z. B. Wiederholungsmethode)","e":"Diese drei Bereiche helfen dir, die vielen Grundsätze zu sortieren: Körper, Trainingslehre und Belastungsgestaltung. Beispiel: „Gut aufwärmen“ gehört zu den biologischen Parametern, „maximal schnell mit langen Pausen“ zu den Belastungsparametern.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-048","thema":"Q2.3","kapitel":"Trainingsgrundsätze","q":"Nenne die trainingspraktischen Grundsätze zum Schnelligkeitstraining (nach Weineck).","a":"• erhöhte Körperkerntemperatur\n• technische/koordinative Präzision\n• Elastizität, Entspannungsfähigkeit\n• optimale äußere Bedingungen\n• Leistungskontrolle, Feedback\n• maximale Willensanspannung\n• maximale Geschwindigkeit, Wiederholungsmethode\n• keine muskuläre Ermüdung\n• Schnelligkeit vor Kraft vor Ausdauer\n• Verbindung mit Kraft-/Koordinationstraining\n• frühzeitige Schulung","e":"Elf Grundsätze sind viel, aber logisch: warm, technisch sauber, locker, ungestört, mit Rückmeldung, voll motiviert, maximal schnell, ausgeruht, am Anfang der Einheit, mit Kraft und Koordination kombiniert und schon im Kindesalter. Beispiel: Ein gutes Sprinttraining beginnt nach 20 min Aufwärmen mit gemessenen 30-m-Sprints, bevor das Krafttraining folgt.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-049","thema":"Q2.3","kapitel":"Trainingsgrundsätze","q":"Erläutere den Grundsatz der erhöhten Körperkerntemperatur beim Schnelligkeitstraining.","a":"Körperkerntemperatur deutlich erhöht, ca. 38,5 °C: 15–30 min aufwärmen und Temperatur halten.","e":"Die Wärme beschleunigt Stoffwechsel- und Nervenleitungsprozesse und senkt innere Widerstände – die Leistung steigt deutlich. Gehalten wird die Temperatur z. B. durch Kleidung und aktiv gestaltete Pausen. Ein warmer Muskel ist wie ein warmgelaufener Motor: Er reagiert schneller und reißt seltener. Beispiel: Sprinter tragen zwischen den Läufen Trainingsjacken, damit die Muskulatur in den langen Pausen nicht wieder abkühlt.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-050","thema":"Q2.3","kapitel":"Trainingsgrundsätze","q":"Erläutere die Grundsätze „technische und koordinative Präzision“ sowie „Elastizität und Entspannungsfähigkeit der Muskulatur“.","a":"• Präzision: erst schnell ausführen, wenn die Technik stabil ist\n• Elastizität/Entspannung: Muskulatur vorher dehnfähig machen (Antagonist darf nicht bremsen); dynamisch statt statisch dehnen","e":"Falsche Technik in hohem Tempo schleift Fehler ein. Kontrahiert ein Muskel, muss sein Gegenspieler leicht dehnbar sein, sonst wirkt er wie eine Handbremse; so werden innere Widerstände minimiert. Statisches Dehnen sollte zugunsten tonisierenden Dehnens vermieden werden. Beispiel: Vor dem Sprinttraining macht man dynamisches Dehnen wie Beinschwingen statt langem Halten einer Dehnposition, das den Muskeltonus senken würde.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-051","thema":"Q2.3","kapitel":"Trainingsgrundsätze","q":"Erläutere die Grundsätze „optimale äußere Bedingungen“, „Leistungskontrolle und Feedback“ und „maximale Willensanspannung“.","a":"• Äußere Bedingungen: ohne Störfaktoren, standardisiert\n• Leistungskontrolle/Feedback: ständige Rückmeldung (Zeitmessung)\n• Willensanspannung: hoch motiviert, voller Leistungswille","e":"Nur unter störungsfreien Bedingungen lassen sich schnelle Bewegungsabläufe einschleifen; die Zeitmessung macht Leistungsveränderungen genau sichtbar. Schnelligkeit braucht volle Konzentration und klare Rückmeldung. Wer seine Zeit kennt, strengt sich mehr an. Beispiel: Sprints werden mit Lichtschranken gemessen, auf trockener Bahn, bei Windstille und mit Vergleich zur Bestzeit.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-052","thema":"Q2.3","kapitel":"Trainingsgrundsätze","q":"Erläutere die Grundsätze „Vermeidung muskulärer Ermüdung“ und „Schnelligkeit vor Kraft vor Ausdauer“.","a":"• Keine Ermüdung: Schnelligkeit am Anfang der Einheit (nach dem Aufwärmen) oder separat\n• Reihenfolge: Schnelligkeit vor Kraft vor Ausdauer","e":"Trainiert wird im Zustand optimaler Leistungsbereitschaft. Ausnahme: Für Spielsportler kann Training unter Ermüdung gezielt gewünscht sein (z. B. Sprintausdauer, Willenskraft). Schnelligkeit ist die empfindlichste Fähigkeit: Schon leichte Ermüdung macht dich langsamer. Darum kommt sie zuerst dran. Beispiel: Eine Fußballeinheit beginnt nach dem Aufwärmen mit Antritten, danach folgen Kraftübungen und am Ende Ausdauerläufe.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-053","thema":"Q2.3","kapitel":"Trainingsgrundsätze","q":"Erläutere die Grundsätze „Verbindung zum Kraft- und Koordinationstraining“ und „frühzeitige Schulung“.","a":"• Kombination mit Kraft- und Koordinationstraining, da Schnelligkeit von Maximal-/Schnellkraft und inter-/intramuskulärer Koordination abhängt\n• Frühzeitige Schulung im Kindesalter (sensible Phasen)","e":"Im Rahmen eines langfristigen Trainingsaufbaus werden im Kindesalter wichtige koordinative und konditionelle Grundlagen gelegt (Gesetz der Trainierbarkeit). Kinder haben ein besonders lernfähiges Nervensystem, deshalb lohnt sich Schnelligkeitstraining dort am meisten. Beispiel: Fang- und Reaktionsspiele in der Grundschule legen den Grundstein für spätere Sprintleistungen.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-054","thema":"Q2.3","kapitel":"Schnelligkeitsbarriere","q":"Was versteht man unter der Schnelligkeitsbarriere, und wie entsteht sie?","a":"Stagnation der Schnelligkeit auf einem Niveau.\nUrsache: gleichförmige Wiederholung mit immer gleichem Tempo → stabiles Bewegungsmuster (dynamischer Stereotyp) im ZNS.","e":"Dieses Muster mit festgelegten räumlich-zeitlichen Parametern lässt sich nur schwer überwinden; auch einseitiges Training ohne Variation begünstigt die Barriere. Das Nervensystem „speichert“ die Bewegung mit einem festen Tempo ab, wie eine eingefahrene Spur. Beispiel: Ein Läufer, der immer nur 30-m-Sprints auf derselben Bahn läuft, wird irgendwann trotz Training nicht mehr schneller.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.3-055","thema":"Q2.3","kapitel":"Schnelligkeitsbarriere","q":"Wie kann die Schnelligkeitsbarriere vermieden oder überwunden werden?","a":"• Variation (vielseitig, v. a. im Kindesalter)\n• erleichterte Bedingungen: Bergab, Zugseil, Windschatten\n• erschwerte Bedingungen: Bergauf, Zugwiderstand, Gewichtsweste\n• Kontrastmethode\n• höhere Informations-/Druckbedingungen\n• Krafttraining","e":"Erleichterte Bedingungen erlauben supramaximale Geschwindigkeiten, auch auf dem Laufband. Bei der Kontrastmethode wechseln erschwerte, normale und erleichterte Bedingungen. Wenn das Nervensystem einmal eine höhere Geschwindigkeit erlebt, kann es ein neues, schnelleres Muster lernen. Beispiel: Ein Sprinter läuft mit einem Gummiseil, das ihn leicht zieht, und erfährt so Schrittfrequenzen, die er allein noch nicht schafft.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q2.3-056","thema":"Q2.3","kapitel":"Anwendung und Transfer","q":"Ordne folgenden Übungen die Schnelligkeitsart zu, die sie beim 100-m-Lauf verbessern: Bergabläufe, Läufe mit unterstützendem Zugseil, Skippings auf hartem Untergrund mit maximaler Frequenz, maximale Trittfrequenz auf dem Fahrradergometer ohne Widerstand, fliegender 20-m-Sprint.","a":"Alle: Frequenzschnelligkeit (zyklisch, geringer Widerstand).\n• Bergab/Zugseil: supramaximales Tempo, gegen Schnelligkeitsbarriere\n• Skippings: Frequenz, kurze Bodenkontakte\n• Ergometer: reine Frequenz\n• Fliegender Sprint: Höchsttempo ohne Beschleunigung","e":"Gemeinsamer Nenner: kaum Widerstand, maximale Frequenz. Bergab- und Zugseilläufe sind erleichterte Bedingungen. Beispiel: Beim fliegenden 20-m-Sprint läuft man 20–30 m an und misst erst ab Erreichen des Höchsttempos, so wird nur die Frequenzschnelligkeit des gleichförmigen Abschnitts geprüft.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-057","thema":"Q2.3","kapitel":"Anwendung und Transfer","q":"Ordne folgenden Übungen die Schnelligkeitsart zu, die sie beim 100-m-Lauf verbessern: Sprünge mit Bleiweste, Bergaufläufe, Läufe gegen Zugwiderstand, einbeinige Kniebeugen mit Sandsack, Skippings auf einer Weichbodenmatte, Antritt nach taktilem Kontakt, Steigerungsläufe, Überdistanzläufe.","a":"• Bleiweste-Sprünge, Kniebeugen mit Sandsack: Kraftschnelligkeit/Kraftbasis\n• Bergauf, Zugwiderstand, Skippings auf Weichboden: Sprintkraft\n• Antritt nach taktilem Kontakt: Reaktionsschnelligkeit\n• Steigerungsläufe: Beschleunigung, intermuskuläre Koordination\n• Überdistanzläufe: Sprintausdauer","e":"Wo zusätzlicher Widerstand im Spiel ist, wird Kraft bzw. Sprintkraft trainiert (erschwerte Bedingungen), wo ein Signal kommt, Reaktion, und wo die Strecke länger als 100 m ist (z. B. 120–150 m), Sprintausdauer. Steigerungsläufe gehören zur Koordinationsmethode. Beispiel: Ein Schlitten, der an einem Gurt hinterhergezogen wird, trainiert den kraftvollen Abdruck in der Beschleunigungsphase.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-058","thema":"Q2.3","kapitel":"Anwendung und Transfer","q":"Beschreibe das Schnelligkeitsanforderungsprofil eines Basketballers und die Bedeutung der Maximalkraft im Basketball.","a":"• Handlungsschnelligkeit\n• Reaktionsschnelligkeit (Wahlreaktionen)\n• Sprintkraft (Antritte <20 m, Richtungswechsel)\n• Kraftschnelligkeit (Sprünge, Würfe)\n• Kraftschnelligkeits-/Sprintausdauer\nMaximalkraft: Basis für Antritte, Stopps, Sprünge; Stabilität im Kontakt, Verletzungsschutz","e":"Handlungsschnelligkeit heißt hier: unter Zeitdruck wahrnehmen, antizipieren und entscheiden, z. B. im 1:1. Die Ausdauerformen werden für wiederholte Aktionen über das ganze Spiel gebraucht; die Maximalkraft ist Basis der Schnell- und Reaktivkraft, etwa bei Rebound und Block. Ein Basketballer braucht keine 100 m Höchsttempo, sondern viele explosive kurze Aktionen mit Köpfchen. Beispiel: Beim Fastbreak muss er den Ballgewinn erkennen, nach 2 Schritten antreten, nach 15 m abstoppen und hochspringen.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-059","thema":"Q2.3","kapitel":"Anwendung und Transfer","q":"Vergleiche das Schnelligkeitstraining eines Sprinters mit dem eines Basketballers.","a":"Gemeinsam: Wiederholungsmethode, maximal, ausgeruht; Koordinations- und Krafttraining\nSprinter: geradlinige Sprints, Einfachreaktion, Frequenz, Sprintkraft, Sprintausdauer\nBasketballer: Antritte, Richtungswechsel, Sprünge mit Ball; Wahlreaktion, Antizipation, Handlungsschnelligkeit; teils unter Ermüdung","e":"Der Sprinter optimiert eine einzige, immer gleiche zyklische Bewegung mit dem Ziel maximaler Laufgeschwindigkeit (Sprints 15–50 m, Überdistanzen). Der Basketballer trainiert viele unterschiedliche Aktionen in wechselnden Situationen, Reaktion und Antizipation im Technik- und Taktiktraining; Ermüdung entspricht der Spielrealität. Beispiel: Der Sprinter läuft 4 × 40 m aus dem Block, der Basketballer reagiert im Linienlauf auf Handzeichen des Trainers mit Antritt, Slide oder Sprung.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-060","thema":"Q2.3","kapitel":"Anwendung und Transfer","q":"Beurteile, inwiefern es für einen Basketballer sinnvoll ist, seine Schnelligkeit durch „Linienpendel“ (Pendelsprints zu den Feldlinien) zu verbessern.","a":"Sinnvoll: basketballtypische Antritte, Stopps, Richtungswechsel (Sprintkraft, Kraftschnelligkeit)\nAber:\n• vorhersehbar → kaum Reaktion/Handlungsschnelligkeit\n• oft kurze Pausen → eher Ausdauertraining\n• ohne Ball/Gegner\nFazit: Ergänzung, wenn maximal mit langen Pausen und mit Signalen","e":"Bei vielen Wiederholungen wird auch die Sprint- bzw. Schnellkraftausdauer geschult. Linienpendel ist ein Klassiker, oft aber eher Kondition als Schnelligkeit, weil man müde wird; außerdem ist die Spielnähe gering. Besser ist eine Kombination mit Wahlreaktionen und Ball. Beispiel: Wenn der Trainer erst auf Zuruf die Ziel-Linie nennt und lange Pausen lässt, wird daraus ein deutlich besseres Schnelligkeitstraining.","quelle":"L14.2","typ":"kern"},{"id":"q2.3-061","thema":"Q2.3","kapitel":"Anwendung und Transfer","q":"Beurteile die Aussage „Schnelligkeit kann nur durch Schnelligkeit trainiert werden!“","a":"Weitgehend richtig: nur maximales Tempo spricht FT-Fasern und anaerob-alaktazide Energie an; langsames Training schleift langsame Muster ein.\nAber: Kraft, Koordination, Beweglichkeit zusätzlich trainieren; Technik erst langsam stabilisieren.","e":"Hinter der Aussage stehen das Prinzip der Spezifität und die Wiederholungsmethode: Schnelle Bewegungsprogramme werden nur durch schnelle Ausführung eingeschliffen. Der Kern stimmt also: Wer schneller werden will, muss schnell trainieren. Aber Kraft- und Techniktraining sind wichtige Zulieferer. Beispiel: Ein Sprinter verbessert sich durch Sprints, zusätzlich aber auch durch Kniebeugen und Sprint-ABC.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-062","thema":"Q2.3","kapitel":"Anwendung und Transfer","q":"Beurteile die Aussagen „Zu viel Schnelligkeit macht stumpf!“ und „Intensives Ausdauertraining verschlechtert die Schnelligkeitsleistungen!“","a":"„Zu viel Schnelligkeit macht stumpf“: richtig\n• Monotonie → Schnelligkeitsbarriere; zu viel/zu kurze Pausen → Ermüdung\n„Ausdauertraining verschlechtert Schnelligkeit“: weitgehend richtig\n• fördert ST-Eigenschaften, langsame Muster, Ermüdung\n• aber Grundlagenausdauer hilft bei der Erholung zwischen Sprints","e":"Gegen das Stumpfwerden helfen Variation, geringer Umfang und vollständige Pausen; sonst droht auch ein Übertraining des Nervensystems. Umfangreiches Ausdauertraining kann schnelle Fasern in ihren Eigenschaften in Richtung langsamer Fasern verschieben und das Schnelligkeitstraining danach durch Ermüdung beeinträchtigen. Viel langsames Laufen macht den Körper eher zum Diesel als zum Sportwagen. Beispiel: Ein Fußballer braucht trotzdem Grundlagenausdauer, damit er sich zwischen den Sprints im Spiel schneller erholt.","quelle":"L14.3","typ":"kern"},{"id":"q2.3-063","thema":"Q2.3","kapitel":"Schnelligkeitstests","q":"Mit welchen Tests können die elementare zyklische und die elementare azyklische Schnelligkeit überprüft werden?","a":"• Zyklisch (Frequenzschnelligkeit): Fußtapping\n• Azyklisch (Aktionsschnelligkeit): Nieder-Hoch-Sprung (Drop-Jump), Bodenkontaktzeit","e":"Merke: Tapping = viele Wiederholungen (zyklisch), Drop-Jump = ein einzelner Sprung (azyklisch). Beispiel: Ein Fußballtrainer testet seine Jugendspieler mit beiden Tests auf einer Kontaktmatte, um schnelle Talente zu erkennen.","quelle":"L16.4","typ":"kern"},{"id":"q2.3-064","thema":"Q2.3","kapitel":"Schnelligkeitstests","q":"Beschreibe Durchführung, Messgröße und Bewertung des Fußtapping-Tests.","a":"• Ziel: elementare zyklische Schnelligkeit\n• Durchführung: mit dem Fuß mit minimaler Amplitude maximal schnell tippen\n• Messgröße: Frequenz (Hz = Kontakte/s)\n• Bewertung: >12 Hz perspektivisch günstig","e":"Weil die Bewegung so klein ist, spielt Kraft keine Rolle: Der Test misst fast nur, wie schnell das Nervensystem An- und Entspannung wechseln kann – die nervale Voraussetzung für hohe Fortbewegungsgeschwindigkeiten. Fußtapping ist aussagekräftiger als Handtapping. Beispiel: Spitzen-Leichtathleten erreichen im Mittel ca. 12 Hz, 6-jährige Kinder ca. 6 Hz.","quelle":"L16.4","typ":"kern"},{"id":"q2.3-065","thema":"Q2.3","kapitel":"Schnelligkeitstests","q":"Welche Ergebnisse zeigt der Vergleich der Fußtappingfrequenzen verschiedener Gruppen (nach Weineck)?","a":"Mittelwerte: 6-J. 6,4 Hz · 10-J. 8,4 Hz · Spitzenleichtathleten 11,9 Hz · Handballer 10,6 Hz · Fußballer 10,5 Hz\n• Zunahme im Kindesalter\n• Leichtathleten am höchsten, Spielsportler darunter\n• große Streuung","e":"Die Spannweiten (Min–Max): 6-Jährige 4,2–8,4; 10-Jährige 5–11,2; Leichtathleten 10,6–14; Handballer 7,8–11,6; Fußballer 8–12,8 Hz. Die Zunahme im Kindesalter zeigt Reifung und die Bedeutung frühzeitiger Schulung, die Streuung individuelle Anlagen. Die Zahlen muss man nicht genau auswendig können, aber die Tendenz. Beispiel: Ein 10-Jähriger mit 11 Hz liegt schon im Bereich von Handballern und könnte ein Schnelligkeitstalent sein.","quelle":"L16.4","typ":"kern"},{"id":"q2.3-066","thema":"Q2.3","kapitel":"Schnelligkeitstests","q":"Beschreibe Durchführung, Messgröße und Bewertung des Nieder-Hoch-Sprungs (Drop-Jump) als Schnelligkeitstest.","a":"• Ziel: elementare azyklische Schnelligkeit der Beine\n• Durchführung: Niedersprung aus ca. 20 cm auf Kontaktmatte, sofort abspringen\n• Messgröße: Bodenkontaktzeit (ms)\n• Bewertung: <170 ms günstig","e":"Der Test prüft die Qualität der zugrunde liegenden Bewegungsprogramme; die Kontaktzeit kann getrennt für links und rechts gemessen werden. Je kürzer der Fuß am Boden bleibt, desto schneller arbeitet das Nerv-Muskel-System. Die 170-ms-Grenze kennst du schon von den elementaren Zeitprogrammen. Beispiel: Spitzen-Leichtathleten kommen im Mittel auf ca. 155 ms, 6-Jährige auf über 210 ms.","quelle":"L16.4","typ":"kern"},{"id":"q2.3-067","thema":"Q2.3","kapitel":"Schnelligkeitstests","q":"Welche Ergebnisse zeigt der Vergleich der Kontaktzeiten beim Nieder-Hoch-Sprung (nach Weineck)?","a":"Mittelwerte links/rechts: 6-J. 218/212 · 10-J. 176/173 · Spitzenleichtathleten 158/153 · Handballer 197/196 · Fußballer 185/192 ms\n• nur Leichtathleten <170 ms\n• Verkürzung im Kindesalter\n• Spielsportler deutlich darüber, teils Seitenunterschiede","e":"Wieder gilt: Leichtathleten sind am schnellsten, Kinder verbessern sich mit dem Alter. Spielsportler haben eine geringere elementare azyklische Schnelligkeit; interessant ist, dass manche 10-Jährige schon bessere Werte haben als viele Handballer. Beispiel: Ein Handballer mit 200 ms könnte durch Sprung- und Koordinationstraining (kurze Bodenkontakte) schneller werden.","quelle":"L16.4","typ":"kern"},{"id":"q2.3-068","thema":"Q2.3","kapitel":"Schnelligkeitstests","q":"Nenne weitere gebräuchliche Tests zur Überprüfung von Schnelligkeitsfähigkeiten und ordne sie zu.","a":"• 30-m-Sprint (Hoch-/Tiefstart): Beschleunigung, Sprintkraft\n• fliegender 20/30-m-Sprint: Frequenzschnelligkeit\n• 20-m-Sprint (FoSS): Antrittsschnelligkeit\n• Fallstab-/Lichtsignaltest: Reaktionsschnelligkeit\n• Pendel-/Richtungswechselsprints: komplexe Schnelligkeit","e":"Für Tests gilt: Was gemessen wird, muss zur Schnelligkeitsart passen (Validität). Gemessen wird meist mit Lichtschranken, um eine hohe Objektivität zu erreichen. Pendelsprints prüfen eine sportspielspezifische Schnelligkeit. Beispiel: Beim Fallstab-Test lässt ein Partner ein Lineal fallen, und die Fangstrecke in cm zeigt die Reaktionszeit an.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-001","thema":"Q3.1","kapitel":"Grundlagen motorisches Lernen","q":"Definiere sportmotorisches Lernen.","a":"Umgebungsbezogene, relativ überdauernde Ausbildung und Korrektur von sportmotorischem Gedächtnisbesitz (Olivier et al., 2013).","e":"Lernen heißt nicht, dass etwas einmal klappt, sondern dass es dauerhaft im Kopf (und Körper) abgespeichert ist. Umgebungsbezogen: Lernen entsteht durch Auseinandersetzung mit der Umwelt (Üben, Erfahrung). Relativ überdauernd: die Veränderung bleibt längerfristig. Ausbildung und Korrektur: Neues wird angeeignet, Vorhandenes verändert. Gedächtnisbesitz: das Gelernte liegt im motorischen Gedächtnis. Beispiel: Wer Radfahren gelernt hat, kann es auch nach zehn Jahren Pause noch, weil das Bewegungsmuster im Gedächtnis gespeichert ist.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-002","thema":"Q3.1","kapitel":"Grundlagen motorisches Lernen","q":"Erläutere das Verhältnis von Lernprozess und Lernergebnis beim sportmotorischen Lernen.","a":"Der Lernprozess führt zu einem Ergebnis, der sportmotorischen Verhaltensänderung. Der Prozess ist nicht beobachtbar – man kann nur vom Ergebnis auf ihn zurückschließen.","e":"Die Verhaltensänderung ist das eigentliche Ziel des Lernens. Man kann nicht in den Kopf des Sportlers schauen, sondern nur sehen, was er zeigt. Beispiel: Ein Trainer sieht, dass ein Schüler nach drei Wochen den Korbleger sauber ausführt, und schließt daraus, dass ein Lernprozess stattgefunden hat.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-003","thema":"Q3.1","kapitel":"Grundlagen motorisches Lernen","q":"Warum kann man nicht immer vom gezeigten Bewegungsergebnis sicher auf den Lernstand schließen?","a":"Leistung (Performanz) ≠ Lernen:\n• Angst, Ermüdung können Gelerntes verdecken\n• Emotionen, hohe Motivation, Medikamente können Leistung kurzzeitig steigern, ohne dass gelernt wurde","e":"Was jemand an einem Tag zeigt, ist nur eine Momentaufnahme: Eine Bewegung kann im Gedächtnis angeeignet sein und trotzdem nicht gelingen – oder umgekehrt kurzzeitig besser klappen. Beispiel: Eine Turnerin beherrscht den Flickflack im Training, traut sich aber in der Prüfung vor Angst nicht – gelernt hat sie ihn trotzdem.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-004","thema":"Q3.1","kapitel":"Grundlagen motorisches Lernen","q":"Grenze sportmotorisches Lernen von anderen Ursachen für Verhaltensänderungen ab.","a":"Kein Lernen sind:\n• Reifung und Wachstum (biologisch bedingt)\n• kurzfristige Änderungen durch Emotionen, Motivation, Medikamente\nLernen ist umweltbedingt und relativ überdauernd.","e":"Wenn ein Jugendlicher plötzlich weiter wirft, weil er gewachsen und stärker geworden ist, hat er nicht unbedingt gelernt. Kurzfristige Einflüsse verschwinden wieder, sobald sie wegfallen. Beispiel: Ein Spieler, der nur im Finale mit Adrenalin besser trifft, hat die Technik nicht dauerhaft verbessert – nach dem Spiel ist der Effekt weg.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-005","thema":"Q3.1","kapitel":"Grundlagen motorisches Lernen","q":"Was beschreiben Phasenmodelle des motorischen Lernens allgemein?","a":"Meist zwei- bis dreiphasige Entwicklung im Lernverlauf bezüglich:\n• Verhalten (Bewegungsergebnis und -ausführung)\n• Codierung im Gedächtnis\n• Automatisierung der motorischen Kontrolle","e":"Phasenmodelle zeigen, dass Lernen in Stufen verläuft: vom holprigen Anfang bis zur automatischen Bewegung. Beispiel: Beim Jonglieren muss man anfangs jede Ballbewegung bewusst steuern, später läuft es automatisch, während man sich unterhält.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-006","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Nenne die drei Lernphasen nach Meinel und Schnabel (1977).","a":"1. Grobkoordination\n2. Feinkoordination\n3. Stabilisierung der Feinkoordination und variable Verfügbarkeit (Feinstkoordination)","e":"Eselsbrücke: Grob – Fein – Feinst. In der Grobkoordination findet das Neulernen statt, in den folgenden Phasen wird die Bewegung automatisiert und stabilisiert. Beispiel: Beim Positionswurf im Basketball kommt der Ball erst irgendwie zum Korb (grob), dann sauber unter Trainingsbedingungen (fein) und schließlich auch im Spiel unter Gegnerdruck (variabel verfügbar).","quelle":"L05.1","typ":"kern"},{"id":"q3.1-007","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Auf welcher theoretischen Grundlage beruht das Lernphasenmodell von Meinel und Schnabel und welche Perspektiven bezieht es ein?","a":"Grundlage: Informationsverarbeitungsansatz.\n• Innenperspektive: Informationsverarbeitung, Programmspeicherung, Automatisierung\n• Außenperspektive: beobachtbare (morphologische) Bewegungsmerkmale","e":"Das Modell schaut sowohl darauf, wie die Bewegung aussieht, als auch darauf, was im Kopf passiert; aus beiden Perspektiven werden praktische Hinweise für das Lehren abgeleitet. Beispiel: Beim Anfänger im Volleyball sieht man den unsauberen Pritschbewegungsablauf (außen) und weiß, dass er die Infos über Ballflug und Körperstellung noch schlecht verarbeitet (innen).","quelle":"L05.1","typ":"kern"},{"id":"q3.1-008","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Welche allgemeinen Eigenschaften haben die drei Lernphasen nach Meinel und Schnabel?","a":"• bauen aufeinander auf\n• nicht umkehrbar\n• fließende Übergänge\n• gegliedert nach beobachtbaren (morphologischen) Merkmalen","e":"Die Phasen sind wie Treppenstufen, nur dass die Übergänge eher eine Rampe sind. Jede Phase zeigt charakteristische, von außen sichtbare Veränderungen der Bewegungskoordination. Beispiel: Ein Schwimmer wechselt nicht an einem bestimmten Tag von Grob- zu Feinkoordination beim Kraulen, sondern verbessert sich allmählich.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-009","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Wie wird die Phase der Grobkoordination abgegrenzt (Beginn und Ende)?","a":"Vom Erfassen der Lernaufgabe bis zur Ausführung unter günstigen Bedingungen: Grundstruktur erkennbar, gelingt aber nur bei voller Konzentration.","e":"Nach dem Erfassen der Aufgabe und einer groben Bewegungsvorstellung folgen erste Versuche. Am Ende der Grobkoordination erkennt man die Bewegung schon, sie ist aber noch wackelig. Beispiel: Ein Anfänger schafft die Rolle vorwärts auf der weichen Matte mit Hilfe, aber noch nicht auf hartem Boden.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-010","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Beschreibe die Ausprägung der Bewegungsmerkmale in der Phase der Grobkoordination.","a":"Alle Merkmale schwach, unökonomisch, verkrampft:\n• Kopplung fehlerhaft\n• Rhythmus verkrampft\n• Fluss stockend\n• Präzision gering\n• Konstanz gering\n• Stärke übermäßig\n• Umfang zu groß\n• Tempo zu hastig/zu langsam","e":"Alle acht Bewegungsmerkmale sind beim Anfänger noch schlecht – man kann sie wie eine Checkliste durchgehen. Der verkrampfte Rhythmus entsteht durch zu viel Kraft, Muskeleinsatz zum falschen Zeitpunkt und falsches Wechselspiel von An- und Entspannung; Ausholbewegungen sind unzweckmäßig. Beispiel: Beim Positionswurf wird die Armstreckung nicht vollständig ausgeführt und das Handgelenk zu früh nachgedrückt, der Wurf ist dadurch zu flach (Rhythmus, Kopplung, Präzision mangelhaft).","quelle":"L05.1","typ":"kern"},{"id":"q3.1-011","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Wie ist die motorische Kontrolle (Informationsverarbeitung) in der Phase der Grobkoordination gekennzeichnet?","a":"• mangelhafte Informationsaufnahme und -verarbeitung, v. a. propriozeptiv (kinästhetisch, Gleichgewicht)\n• unvollkommene Speicherung der GMP\n• Steuerung v. a. optisch und bewusst","e":"Der Anfänger spürt noch nicht, was sein Körper genau macht; er verlässt sich auf die Augen und bewusst eingesetztes Zusatzwissen. Beispiel: Beim ersten Handstand weiß man oft nicht, ob man gerade steht oder schon im Hohlkreuz hängt – das Körpergefühl fehlt noch.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-012","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Welche methodischen Konsequenzen ergeben sich für die Phase der Grobkoordination?","a":"• Aufgabe verbal und optisch präzise stellen\n• günstige, konstante Bedingungen (Erleichterungen, Hilfen)\n• koordinative Vorübungen\n• sparsame Korrektur (Hauptfehler)\n• keine Informationsflut","e":"Anfänger können nur wenig auf einmal verarbeiten, deshalb lieber ein klares Bild und ein Tipp statt zehn Korrekturen. Ziel ist eine konkrete Bewegungsvorstellung. Beispiel: Beim Positionswurf helfen ein Video eines Profis und der Hinweis „Mittel- und Zeigefinger zeigen dem Ball hinterher“.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-013","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Wie wird die Phase der Feinkoordination abgegrenzt und wodurch ist sie gekennzeichnet?","a":"Von der Grobkoordination bis zur annähernd fehlerfreien Ausführung: präzise, konstant, flüssig, bessere Kraftdosierung – aber nur unter gewohnten Bedingungen; unter erschwerten noch Mängel.","e":"In der Feinkoordination stabilisieren sich räumlich-zeitliche und dynamische Parameter, die intermuskuläre Koordination verbessert sich. Die Bewegung klappt im Training gut, aber Störungen werfen den Lernenden noch aus der Bahn. Beispiel: Ein Basketballer trifft den Positionswurf aus mittlerer Distanz ohne Gegner zuverlässig, verfehlt aber sobald ein Verteidiger die Hand hebt.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-014","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Wie verändert sich die Informationsverarbeitung in der Phase der Feinkoordination und welche methodischen Konsequenzen folgen daraus?","a":"• erweiterte Informationsverarbeitung, kinästhetischer Analysator wirksamer, GMP-Speicherung optimiert\n• Methodik: viele konzentrierte Wiederholungen, fehlerfrei unter konstanten Bedingungen, Hinweise zum Bewegungsempfinden","e":"Jetzt kann der Lernende auf Gefühlshinweise reagieren, weil er seinen Körper besser spürt: Innere und äußere Rückmeldungen werden bewegungsoptimierend verarbeitet, das Bewegungsgefühl wird besser. Auch verbalisierende Informationen helfen. Beispiel: Der Hinweis „Der Abwurf muss sich leicht anfühlen!“ hilft beim Basketballwurf erst in der Feinkoordination, ein Anfänger könnte damit wenig anfangen.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-015","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Beschreibe die dritte Lernphase nach Meinel und Schnabel (Stabilisierung der Feinkoordination und variable Verfügbarkeit).","a":"Von der Feinkoordination bis zur sicheren Ausführung auch unter ungewohnten, schwierigen Bedingungen (Wettkampf, Ermüdung, Druck); automatisiert, Aufmerksamkeit frei.","e":"Variable Verfügbarkeit bedeutet: Die Technik funktioniert immer und überall mit sehr hoher Präzision und Konstanz, und der Kopf ist frei für Taktik. Auch auf hohem Niveau ist weiteres Lernen nötig. Beispiel: Ein Profi-Basketballer trifft den Sprungwurf aus dem Dribbling, müde in der letzten Minute und gegen einen Verteidiger, während er gleichzeitig das Spiel liest.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-016","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Wie ist die Informationsverarbeitung in der Phase der variablen Verfügbarkeit gekennzeichnet und wie sollte geübt werden?","a":"• Informationsverarbeitung weiter optimiert, sehr genaues Bewegungsempfinden → bewusste Korrektur möglich\n• Üben unter variablen Wettkampfbedingungen mit hohem psychischem und physischem Druck","e":"Jetzt muss das Training dem Wettkampf ähneln und gezielt Druck aufbauen; die variablen Programmparameter werden erweitert. Weil das Bewegungsempfinden sehr genau ist, kann man mit Zusatzinformationen gezielt korrigieren. Beispiel: Beim Positionswurf werden Würfe gegen eine Verteidigerhand (Präzisionsdruck), Sprungwürfe aus dem Dribbling (Komplexitätsdruck) oder eine Mindesttrefferzahl pro Minute (Belastungsdruck) geübt.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-017","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Nenne die praktischen Hinweise für das Üben in den drei Lernphasen (Tab. 5.2).","a":"• Grob: verbale/visuelle Hinweise für Bewegungsvorstellung, koordinative Vorübungen\n• Fein: fehlerfrei unter konstanten Bedingungen, Hinweise zum Bewegungsempfinden\n• Feinst: variable, schwierige Bedingungen, Parameter erweitern","e":"Die Methodik passt sich dem Lernstand an: erst zeigen, dann konstant festigen, dann variieren. Beispiel: Beim Tennisaufschlag erst Demonstration und Vorübungen, dann viele gleiche Aufschläge aufs selbe Feld, später Aufschläge bei Wind, unter Zeitdruck und auf wechselnde Ziele.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-018","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Vergleiche die drei Lernphasen nach Meinel und Schnabel hinsichtlich Bewegungsqualität, Informationsverarbeitung und Bedingungen der Ausführung.","a":"• Grob: Grundstruktur, verkrampft; Infoaufnahme mangelhaft; nur unter günstigen Bedingungen\n• Fein: annähernd fehlerfrei; Kinästhetik besser; unter gewohnten Bedingungen\n• Variabel: sehr präzise, automatisiert; auch unter schwierigen Bedingungen","e":"Für die Klausur lohnt sich eine Tabelle mit den drei Phasen als Spalten. In der Grobkoordination ist v. a. die propriozeptive Aufnahme schlecht und die Programmspeicherung unvollkommen; in der Feinkoordination wird sie optimiert; in der variablen Verfügbarkeit ist das Bewegungsempfinden sehr genau und die Bewegung hält Ermüdung, Gegner und psychischem Druck stand. Beispiel Kraulschwimmen: erst hektisches Paddeln mit Wasserschlucken, dann saubere Technik im ruhigen Becken, schließlich auch im Freiwasser mit Wellen und Konkurrenten.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-019","thema":"Q3.1","kapitel":"Lernphasen nach Meinel/Schnabel","q":"Woran kann man den Übergang von der Grob- zur Feinkoordination und von der Fein- zur Feinstkoordination in der Praxis erkennen?","a":"• Grob → Fein: unter einfachen Bedingungen technisch korrekt; spricht auf Hinweise zum Bewegungsempfinden an\n• Fein → variabel: technisch stabil auch unter kleinen Stressfaktoren (Serien, Zeitvorgaben)","e":"Man testet den Lernstand, indem man die Bedingungen schrittweise erschwert; danach werden Präzisions-, Komplexitäts- und Belastungsdruck gezielt erhöht. Beispiel aus dem Buch: Wer 10 Freiwürfe in Folge oder 10 Mitteldistanzwürfe in zwei Minuten trifft, ist auf dem Weg in die Phase der variablen Verfügbarkeit.","quelle":"L05.1","typ":"kern"},{"id":"q3.1-020","thema":"Q3.1","kapitel":"Weitere Lernphasenmodelle","q":"Beschreibe das Drei-Phasen-Modell des motorischen Lernens nach Fitts und Posner (1967).","a":"1. Kognitiv: Aufgabe verstehen, bewusste Steuerung, viele Fehler\n2. Assoziativ: Verfeinerung, weniger Fehler, Selbstkorrektur teilweise möglich\n3. Autonom: automatisiert, konstant, Doppeltätigkeiten möglich","e":"Das Modell ähnelt Meinel/Schnabel: kognitiv ≈ grob, assoziativ ≈ fein, autonom ≈ variable Verfügbarkeit. In der kognitiven Phase ist die Variabilität hoch und der Bedarf an Instruktion und Demonstration groß; in der autonomen Phase ist kaum noch Aufmerksamkeit nötig. Beispiel: Ein Fahranfänger denkt beim Schalten noch über jeden Schritt nach (kognitiv), später klappt es mit gelegentlichem Ruckeln (assoziativ), schließlich nebenbei beim Unterhalten (autonom).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-021","thema":"Q3.1","kapitel":"Weitere Lernphasenmodelle","q":"Beschreibe das Zwei-Phasen-Modell des motorischen Lernens nach Gentile.","a":"1. Erwerb der Bewegungsidee: Grundstruktur und Ziel erfassen, relevante Umweltmerkmale erkennen\n2. Fixierung (geschlossene Fertigkeiten, konstante Ausführung) bzw. Diversifikation (offene Fertigkeiten, Anpassung an Situationen)","e":"Gentile betont, dass das Ziel der zweiten Phase von der Art der Fertigkeit abhängt: In stabiler Umwelt soll die Bewegung gleich bleiben, in wechselnder Umwelt anpassbar werden. Die erste Phase heißt im Original „getting the idea of the movement“. Beispiel: Ein Turner will seine Kür immer gleich turnen (Fixierung), ein Fußballer muss den Pass an jede neue Spielsituation anpassen (Diversifikation).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-022","thema":"Q3.1","kapitel":"Weitere Lernphasenmodelle","q":"Ordne die Lernphasenmodelle von Meinel/Schnabel und Fitts/Posner einander zu und nenne Gemeinsamkeiten.","a":"• Grob ↔ kognitiv\n• Fein ↔ assoziativ\n• variable Verfügbarkeit ↔ autonom\nGemeinsam: von bewusster zu automatisierter Kontrolle; Fehler und Aufmerksamkeitsbedarf sinken, Präzision und Störresistenz steigen.","e":"Verschiedene Autoren nutzen unterschiedliche Namen, beschreiben aber denselben Grundverlauf; auch die Variabilität nimmt ab, die Konstanz zu. Beispiel: Beim Tennisaufschlag denkt der Anfänger an Ballwurf und Schlag (kognitiv/grob), der Fortgeschrittene trifft konstant (assoziativ/fein), der Profi platziert unter Matchdruck (autonom/variabel).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-023","thema":"Q3.1","kapitel":"Weitere Lernphasenmodelle","q":"Was versteht man unter Automatisierung einer Bewegung und woran erkennt man sie?","a":"Übergang von bewusster zu weitgehend unbewusster Bewegungssteuerung.\nKennzeichen:\n• geringer Aufmerksamkeitsbedarf\n• Doppeltätigkeiten ohne Leistungsverlust\n• hohe Konstanz und Störresistenz\n• schnell, ökonomisch","e":"Eine automatisierte Bewegung läuft wie von selbst; die frei gewordene Aufmerksamkeit kann z. B. für Taktik genutzt werden, auch Ermüdung und Druck stören kaum. Beispiel: Ein guter Basketballspieler dribbelt, ohne auf den Ball zu schauen, und kann dabei Mitspieler suchen – ein Anfänger muss den Ball ständig ansehen.","quelle":"L05.1","typ":"zusatz"},{"id":"q3.1-024","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Erläutere die Teillernmethode (analytisch-synthetische Methode).","a":"• Einzelne Teile der Gesamtbewegung werden isoliert geübt (Analyse = Zerlegung).\n• Erst wenn die Einzelteile beherrscht werden, werden sie zur Gesamtbewegung (Zielübung) zusammengesetzt (Synthese).","e":"Man baut die Bewegung wie aus Bausteinen zusammen. Beispiel: Beim Speerwurf übt man erst den Abwurf aus dem Stand, dann den Dreierrhythmus und erst später den vollen Anlauf.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-025","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Erläutere die Ganzheitsmethode.","a":"Die Bewegung wird von Beginn an in ihrer Gesamtstruktur geübt, ohne Zerlegung (ggf. unter erleichterten Bedingungen).","e":"Man übt immer die ganze Bewegung, auch wenn sie anfangs unsauber ist; Verbesserungen erfolgen im ganzheitlichen Vollzug. In vielen Studien ist sie der Teillernmethode überlegen. Beispiel: Der Hochspringer Igor Paklin trainierte nicht einzelne Elemente, sondern den Sprung als harmonische Einheit – Überflüssiges falle dann von selbst weg.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-026","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Erläutere die Ganz-Teil-Ganz-Methode.","a":"1. Gesamtbewegung darbieten und üben\n2. nicht beherrschte Teile gezielt schulen\n3. Rückführung in die Gesamtbewegung","e":"Erst ganz, dann gezielt reparieren, dann wieder ganz – eine „Zwischenmethode“. Vorteil ist die Binnendifferenzierung: Jeder bestimmt sein Lerntempo; Begabte steigen schnell ins Anwendungstraining mit Druckbedingungen ein, andere werden durch Teilübungen unterstützt. Beispiel: Der Korbleger wird ganzheitlich eingeführt; wer ihn sofort kann, probiert ihn von links, die anderen üben gezielt das rhythmische Dribbling oder den einbeinigen Absprung.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-027","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Nenne die vier Aspekte, die das Anwenden der Teillernmethode sinnvoll erscheinen lassen (nach Loosch/Rosinski).","a":"• hohe Komplexität der Bewegung\n• Auffrischen selten abgeforderter Bewegungsabschnitte\n• Ausloten biomechanischer Grenzbereiche einzelner Phasen\n• bessere Trainingsökonomie (z. B. Stationsbetrieb)","e":"Teillernen lohnt sich vor allem bei sehr schwierigen Bewegungen oder wenn man gezielt an einer Stelle feilen will; vereinfachte Technikumgebungen machen das Training ökonomischer. Beispiel: Ein Stabhochspringer übt Einstich und Absprung isoliert, weil komplette Sprünge sehr aufwendig sind und die Phasen sonst zu selten trainiert werden.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-028","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Nenne und erläutere die Nachteile der Teillernmethode (nach Loosch/Rosinski).","a":"• Phaseneinteilung: morphologisch, passt evtl. nicht zur subjektiven Vorstellung\n• Timing: Gesamtkoordination leidet, „Bewegungspausen“ werden einprogrammiert\n• funktionelle Variabilität wird nicht geschult\n• subjektive Geschlossenheit: Bewegungsgefühl nur im Ganzen","e":"Wenn man Teile zu lange getrennt übt, passen sie später nicht mehr gut zusammen, und die Bewegung wird nicht mehr als harmonische Einheit erlebt. Ausgleich zwischen Bewegungsteilen gelingt nur im Gesamtvollzug. Techniken werden zudem mit emotionalen Begleitphänomenen erlebt, die früh zeigen, ob sie gelingen. Beispiel: Wer beim Weitsprung Anlauf und Absprung lange getrennt trainiert, stockt vor dem Brett kurz – genau diese Pause hat er sich „einprogrammiert“.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-029","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Was versteht man unter dem Prinzip der funktionellen Variabilität und warum spricht es für ganzheitliches Lernen?","a":"Abweichungen in einzelnen Bewegungsteilen werden durch andere Abschnitte ausgeglichen. Diese Ausgleichsleistung ist nur im ganzheitlichen Vollzug möglich und muss so geschult werden.","e":"Der Körper kann kleine Fehler selbst ausgleichen, wenn er die ganze Bewegung kennt; beim isolierten Teilüben fehlt diese Fähigkeit. Beispiel: Setzt ein Hochspringer einen etwas zu kurzen letzten Schritt, kann er das durch einen stärkeren Armeinsatz beim Absprung ausgleichen – das lernt man nur im kompletten Sprung.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-030","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Welches Fazit zieht das Buch aus empirischen Studien zum Vergleich von Ganzheits- und Teillernmethode?","a":"Ganzheitsmethode ist überlegen; bei sehr komplexen Bewegungen ist Teillernen z. T. einzige Möglichkeit – dann immer wieder zum Gesamtvollzug zurückkehren.","e":"Grundsätzlich ganzheitlich, aber bei zu schweren Bewegungen geht es nicht ohne Zerlegung. Beispiel: Ein Rad am Boden kann man ganzheitlich lernen, eine Kür am Stufenbarren dagegen muss man in Elementen erlernen und dann wieder zusammenfügen.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-031","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Nenne die drei Merkregeln zur Wahl zwischen Ganzheits-, Teil- und Ganz-Teil-Ganz-Methode.","a":"• Lehre so weit wie möglich ganzheitlich.\n• Komplexbewegungen sollten mithilfe der Teillernmethode geschult werden.\n• Bei Bewegungen mittlerer Komplexität eignet sich die Ganz-Teil-Ganz-Methode.","e":"Die Komplexität der Bewegung entscheidet über die Methode. Beispiel: Einen Strecksprung lehrt man ganzheitlich, den Korbleger mit Ganz-Teil-Ganz und den Stabhochsprung oder die Kugelstoß-Angleittechnik eher mit Teillernmethode.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-032","thema":"Q3.1","kapitel":"Ganzheits- und Teillernmethode","q":"Vergleiche Ganzheits- und Teillernmethode in Bezug auf Vor- und Nachteile.","a":"• Ganzheit: + Rhythmus/Timing, funktionelle Variabilität, Bewegungsgefühl, motivierend, empirisch überlegen; – Überforderung bei komplexen/gefährlichen Bewegungen\n• Teil: + weniger Komplexität, gezieltes Üben, ökonomisch; – Timingprobleme, Zusammensetzen schwierig","e":"In Abiturklausuren wird oft eine begründete Methodenwahl verlangt – dann diese Vor- und Nachteile auf die konkrete Bewegung anwenden. Ein weiterer Nachteil des Teillernens: Die morphologische Zerlegung entspricht evtl. nicht der subjektiven Bewegungsvorstellung, und es drohen „einprogrammierte Pausen“. Beispiel: Für den Flopsprung spricht der hohe Anteil des Rhythmus im Anlauf-Absprung-Übergang für ganzheitliches Lernen, die Komplexität aber für ein Ganz-Teil-Ganz-Vorgehen.","quelle":"L05.2","typ":"kern"},{"id":"q3.1-033","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Nenne die bereichsübergreifende Grundlogik des Neulernens komplexer Bewegungen (nach Roth, 2007).","a":"Schwierigkeit sinnvoll reduzieren: zunächst vereinfachte Probleme üben, diese nach angemessener Zeit zur Gesamtaufgabe aufschalten.","e":"So wird der überforderte Schüler unterstützt – und so lernt man nicht nur im Sport, sondern auch in Mathe oder Musik: erst Einfaches, dann Zusammensetzen. Beispiel: Ein Grundschüler lernt erst Addieren und Multiplizieren, bevor er komplizierte Terme mit Punkt-vor-Strich-Regel löst.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-034","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Welche zwei zentralen Fragen stellen sich beim Neulernen komplexer sportlicher Bewegungen?","a":"1. Welche Vereinfachungsstrategien gibt es?\n2. Wie ist die Reihung der Lernschritte zu gestalten, also der Weg von den Teilzielen zum Ziel (methodische Übungsreihen)?","e":"Erst überlegt man, wie man die Bewegung leichter macht, dann, in welcher Reihenfolge man die Erleichterungen wieder zurücknimmt. Beispiel: Beim Kraulen nutzt man ein Schwimmbrett als Vereinfachung und plant, wann das Brett wegfällt.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-035","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Was versteht man unter einem generalisierten motorischen Programm (GMP) und welche Merkmale sind invariant bzw. variabel?","a":"Lernen genormter Fertigkeiten = Aneignung von GMP.\n• Invariant: Reihenfolge, relatives Timing, Relation der Muskelkräfte\n• Variabel (Parameter): Gesamtdauer, Gesamtkraft, Muskelauswahl","e":"Ein GMP ist wie ein Bauplan, bei dem die Reihenfolge fest ist, Größe und Tempo aber angepasst werden können. Diese Sicht stammt aus dem Informationsverarbeitungsansatz. Beispiel: Beim Wurf ist der Ablauf immer gleich, ob man 5 m oder 20 m weit wirft – nur Kraft und Dauer (Parameter) ändern sich.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-036","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Nenne die Überforderungsaspekte beim Neulernen und die jeweils zugeordneten Vereinfachungsstrategien (Tab. 5.3).","a":"• Programmlänge → Programmlängenverkürzung\n• Programmbreite → verringerte Programmbreite, Invariantenunterstützung\n• Parameteranforderung → Parameterveränderung\n• Angst → Sicherheitsvorkehrungen, systematische Desensibilisierung","e":"Eselsbrücke: Eine Bewegung kann zu lang, zu breit, zu schnell/stark oder zu beängstigend sein. Gegen Angst helfen auch empathische Ansprache und Entspannungstechniken. Beispiel: Ein Salto ist für einen Anfänger vor allem ein Angst- und Parameterproblem, eine Schwimmtechnik eher ein Programmbreitenproblem.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-037","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Erläutere den Überforderungsaspekt Programmlänge und das Prinzip der Programmlängenverkürzung.","a":"• Problem: zu viele nacheinander ablaufende Bestandteile\n• Strategie: Programm in zeitlich aufeinanderfolgende Abschnitte teilen, einzeln üben, dann aufschalten","e":"Man schneidet die Bewegung zeitlich in Stücke. Das passt vor allem bei azyklischen Fertigkeiten mit vielen hintereinandergeschalteten, wechselwirkungsarmen Elementen. Beispiel: Beim Speerwurf wird zunächst aus dem Stand geworfen, beim Kastensprung beginnt man mit dem Prellfedern statt mit dem ganzen Anlauf.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-038","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Nenne die Einsatzregel für Programmlängenverkürzungen (nach Roth, 2007).","a":"Lernwirksam bei gut isolierbaren, nacheinander ablaufenden Bewegungsteilen; bei enger Verzahnung der Abschnitte keine Trennung.","e":"Nur wenn sich die Phasen sauber trennen lassen, darf man sie zerschneiden. Beispiel: Beim Speerwurf funktioniert das gut, beim Kraulschwimmen nicht, weil Haupt- und Zwischenphasen ineinander übergehen.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-039","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Bei welchen Bewegungen ist eine Programmlängenverkürzung nicht sinnvoll? Begründe.","a":"• zyklische Bewegungen (Phasenverschmelzung)\n• nicht bremsbare azyklische Bewegungen (z. B. Salti)\n• wenn der verkürzte Abschnitt strukturell zu stark abweicht (Umlernen)","e":"Bei Laufen, Radfahren oder Schwimmen gibt es keine trennbaren Abschnitte. Ein Salto oder eine Schraube muss, einmal begonnen, zu Ende geführt werden – man kann nicht „einen halben Salto“ üben. Weicht der Teil zu stark von der Zielbewegung ab, drohen aufwendige Umlernprozesse. Beispiel: Beim Laufen gibt es keinen Punkt, an dem man den Schritt sinnvoll zerlegen könnte, da Schwung- und Stützphase fließend ineinander übergehen.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-040","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Welche Kritik äußern Grosser und Neumaier an scheinbar offensichtlichen Programmlängenverkürzungen und welche Alternative schlagen sie vor?","a":"• Kritik: verkürzte Abschnitte (Kugelstoß aus dem Stand) weichen in den Invarianten zu stark von der Zielbewegung ab → Umlernen\n• Alternative: wegzulassende Elemente durch einfachere ersetzen (Angehen statt Angleiten)","e":"Ein verkürzter Teil darf nicht zu einer eigenen, anderen Bewegung werden; Fehler darin müssen sonst aufwendig umgelernt werden. Zielbewegung beim Kugelstoßen ist die O’Brien-Technik. Beispiel: Wer ewig aus dem Stand stößt, gewöhnt sich eine Stoßbewegung an, die nicht zum Angleiten passt – das Angehen ist eine bessere Brücke.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-041","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Erläutere den Überforderungsaspekt Programmbreite und das Prinzip der Verringerung der Programmbreite.","a":"• Problem: zu viele gleichzeitig zu koordinierende Elemente\n• Strategie: simultane Teilbewegungen isoliert üben, später aufschalten\n• v. a. bei asynchronen zyklischen Bewegungen (Schwimmen)","e":"Hier schneidet man nicht zeitlich, sondern „nach Körperteilen“ – typisch etwa für Arm- und Beinbewegung beim Schwimmen. Beispiel: Beim Kraulen üben Lernende den Beinschlag mit Schwimmbrett und den Armzug mit Pull Buoy getrennt; beim Basketballwurf betont Werfen im Sitzen auf dem Kasten die Arm-Hand-Führung.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-042","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Nenne die Einsatzregel für Reduktionen der Programmbreite (nach Roth, 2007).","a":"Lernwirksam bei gut isolierbaren, gleichzeitig ablaufenden Bestandteilen (z. B. Schwimmtechniken); bei eng verzahnten simultanen Aktivitäten ohne Schnittstellen keine Trennung (z. B. Rudern, Radfahren).","e":"Nur was im Körper unabhängig voneinander läuft, darf man getrennt üben. Bei Paddeln, Rudern oder Radfahren fehlen „horizontale Schnittstellen“. Beispiel: Beim Rudern hängen Beinstoß, Rückenzug und Armzug so eng zusammen, dass getrenntes Üben kaum hilft – beim Kraul dagegen schon.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-043","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Erläutere den Unterschied zwischen Programmlängenverkürzung und Programmbreitenverringerung.","a":"• Längenverkürzung: trennt zeitlich nacheinander ablaufende Teile (Längsschnitt)\n• Breitenverringerung: trennt gleichzeitig ablaufende Teile (Querschnitt)\n• Beide setzen gut isolierbare Bestandteile voraus.","e":"Länge = nacheinander, Breite = gleichzeitig. Im Bild: Bei der Längenverkürzung werden Halbkreise nacheinander zum ganzen Kreis zusammengesetzt; bei der Breitenverringerung wird ein kleiner Kreis durch weitere simultane Bestandteile zum großen Kreis erweitert. Beispiel: Kugelstoßen erst als Standstoß (A) und dann mit Angleiten (B) ist Längenverkürzung; Kraulen nur mit Armeinsatz ist Breitenverringerung.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-044","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Definiere Invariantenunterstützung und nenne ihre Formen.","a":"Ausführungshilfen für die invarianten Merkmale einer Bewegung:\n• Rhythmusvorgaben (akustisch)\n• Orientierungsvorgaben (visuell)\n• bewegungsführende Hilfen (taktil-kinästhetisch)\n• Hilfen zur Erhöhung der Fehlertoleranz","e":"Der Lehrer hilft beim „Wie“ der Bewegung, ohne sie zu zerlegen. Rhythmusvorgaben stützen den zeitlich-dynamischen Ablauf, Markierungen die räumlich-zeitliche Genauigkeit, Hilfestellung macht Winkelstellungen bewusst; mehr Fehlertoleranz senkt den Präzisionsdruck. Beispiel: Beim Hürdenlauf gibt ein rhythmisches „ta-ta-ta-hopp“ den Dreierrhythmus vor, Markierungen am Boden zeigen den Absprungpunkt, und niedrige Schaumstoffhürden erhöhen die Fehlertoleranz.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-045","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Welchem Überforderungsaspekt ist die Invariantenunterstützung zugeordnet und für welche Bewegungen eignet sie sich besonders?","a":"Überforderungsaspekt Programmbreite; besonders für Bewegungen mit hohen räumlichen, zeitlichen und dynamischen Präzisionsanforderungen (z. B. Turnen).","e":"Wenn man die Bewegung nicht zerlegen kann, kann man sie trotzdem führen: Anders als bei der Breitenverringerung bleibt die Bewegung vollständig, die Ausführung wird aber durch Hilfen gelenkt. Beispiel: Bei der Kippe am Reck übt man die ganze Bewegung, aber der Lehrer gibt Hilfestellung am Rücken und ruft im richtigen Moment „jetzt!“.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-046","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Erläutere den Überforderungsaspekt Parameteranforderung und das Prinzip der Parameterveränderung.","a":"• Problem: Invarianten sind erlernbar, aber die Parameter überfordern (zu schnell, zu kurz, zu kraftvoll)\n• Strategie: Zeit-, Präzisions- und Belastungsdruck senken\n• Bedingung: Invarianten dürfen nicht zerfallen","e":"Die Bewegung bleibt gleich, aber man macht sie langsamer, länger oder leichter – etwa durch Zeitlupe, erhöhten Absprungort, leichteres Gerät oder begleitendes Krafttraining. Beispiel: Die Drehung beim Diskuswurf wird zunächst in Zeitlupe geübt, und Anfänger stoßen mit einer leichteren Kugel.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-047","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Nenne die Möglichkeiten der Parameterveränderung je nach Art der Überforderung.","a":"• zu hohe Geschwindigkeit → langsamer üben\n• zu kurze Dauer → Bewegungszeit durch Gerätehilfen verlängern\n• zu hohe Kraft → leichtere Geräte, niedrigere Hindernisse, Partnerhilfe","e":"Je nachdem, welcher Parameter überfordert, dreht man an einer anderen „Stellschraube“: z. B. Gehen statt Laufen im Anlauf, erhöhte Absprungstellen für eine längere Flugphase, kürzere Haltedauer bei statischen Elementen. Beispiel: Beim Kastensprung wird ein Minitramp als Absprunghilfe genutzt, damit mehr Zeit in der Flugphase bleibt; beim Hürdenlauf werden die Hürden niedriger gestellt.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-048","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Welche Grenze hat das Üben in Zeitlupe (zeitliche Dehnung) als Parameterveränderung?","a":"Die Invarianten (z. B. relatives Timing) dürfen nicht zerfallen; schwungabhängige Bewegungen brauchen eine Mindestgeschwindigkeit – zu starke Verlangsamung erzeugt eine andere Bewegung.","e":"Manche Bewegungen brauchen Schwung, sonst sind es andere Bewegungen mit einem anderen Programm. Kippbewegungen im Turnen lassen sich daher nur sehr wenig zeitlich dehnen. Beispiel: Eine Kippe am Reck in Zeitlupe gelingt nicht, weil der Schwung für das Hochkommen fehlt – man übt dann etwas völlig anderes.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-049","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Nenne die Anwendungsfelder der Vereinfachungsstrategien laut Tab. 5.3.","a":"• Längenverkürzung: azyklisch, viele nacheinander ablaufende Elemente\n• Breitenverringerung/Invariantenunterstützung: viele gleichzeitige Elemente, hohe Präzision\n• Parameterveränderung: hohe Geschwindigkeit, kurze Dauer, hohe Kraft\n• Sicherheit/Desensibilisierung: ungewisser Ausgang","e":"Die Tabelle ist eine typische Abiturgrundlage – man sollte zu jeder Strategie sagen können, wann sie passt. Typische Beispiele: Speerwurf und Kastensprung (Länge), Schwimmtechniken und Turnen (Breite/Invarianten), Speerwurf, Turnsprünge, Würfe und Stöße (Parameter). Beispiel: Für die Rückwärtsrolle am Reck (ungewisser Ausgang) helfen eher Sicherheitsmaßnahmen, für den Speerwurf eher Längenverkürzung und Parameterveränderung.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-050","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Wie kann dem Überforderungsaspekt Angst beim Neulernen begegnet werden?","a":"• Sicherheitsvorkehrungen (Matten, Hilfestellung)\n• systematische Desensibilisierung\n• empathische Ansprache\n• Entspannungstechniken","e":"Angst vor Verletzung oder Blamage behindert das Lernen: Wer Angst hat, verkrampft. Das betrifft vor allem Bewegungen mit ungewissem Ausgang. Systematische Desensibilisierung heißt schrittweise Gewöhnung an die angstauslösende Situation. Beispiel: Beim Kopfsprung vom 3-m-Brett springt man zuerst vom Beckenrand, dann vom 1-m-Brett und erst danach vom 3-m-Brett.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-051","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Welcher Merksatz gilt neben den Vereinfachungsstrategien beim Erlernen neuer Bewegungen?","a":"Immer prüfen, ob die koordinativen und konditionellen Voraussetzungen erfüllt sind – nicht alle Schwierigkeiten lassen sich durch Vereinfachung beseitigen (Roth, 2007).","e":"Ohne die nötige Kraft oder Beweglichkeit hilft auch die beste Methodik nichts. Beispiel: Der Handstützüberschlag am Boden scheitert, wenn Stützkraft in den Armen oder Rumpfbeweglichkeit fehlen.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-052","thema":"Q3.1","kapitel":"Vereinfachungsstrategien","q":"Begründe, bei welchen Fertigkeiten man auf eine Programmlängenverkürzung, Programmbreitenverringerung, Invariantenunterstützung oder zeitliche Dehnung verzichten sollte.","a":"• Längenverkürzung: zyklische und nicht bremsbare Bewegungen\n• Breitenverringerung: eng verzahnte simultane Teile (Rudern)\n• Invariantenunterstützung: bei Abhängigkeit oder verfälschter Struktur\n• zeitliche Dehnung: schwungabhängige Bewegungen (Kippen)","e":"Jede Strategie hat Grenzen: Zyklische Bewegungen verschmelzen ihre Phasen, ein Salto ist nicht bremsbar, eine Hilfe kann abhängig machen oder bei bereits stabiler Bewegung überflüssig sein, und ohne Schwung zerfallen die Invarianten. Das Buch fordert in Aufgabe 44, diese Grenzen zu begründen. Beispiel: Eine Riesenfelge am Reck lässt sich weder zeitlich dehnen noch sinnvoll in Abschnitte zerlegen – hier helfen eher Sicherungsgürtel und Hilfestellung.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-053","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Definiere methodische Übungsreihen (MÜR).","a":"Nach methodischen Grundsätzen geordnete Übungsfolgen, die zum Erlernen einer Zielübung (oder einer motorischen Eigenschaft) führen (Grössing, 2007).","e":"Eine MÜR ist wie eine Treppe aus Übungen, die zur Zielbewegung führt. In ihr sind die Vereinfachungsprinzipien und deren schrittweise Rücknahme fertigkeitsspezifisch festgelegt; sie beruht meist auf bewährter Praxiserfahrung. Beispiel: Für den Speerwurf geht es vom Schlagballwurf über Würfe mit Hilfsgeräten und aus der Wurfauslage bis zum Wurf aus dem Fünferrhythmus.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-054","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Nenne die allgemeinen methodischen Grundsätze für den Aufbau methodischer Übungsreihen.","a":"• vom Leichten zum Schweren\n• vom Einfachen zum Komplexen\n• vom Bekannten zum Unbekannten\n• vom Sicheren zum Risikoreichen\nAllgemein gilt: Im Verlauf des Lernprozesses werden die Erleichterungen schrittweise zurückgenommen.","e":"Diese vier „vom … zum …“-Regeln sollte man auswendig können. Beispiel: Beim Handstand übt man erst an der Wand mit Partnerhilfe (leicht, sicher), dann frei auf der Matte und schließlich frei mit Abrollen (schwer, risikoreicher).","quelle":"L05.3","typ":"kern"},{"id":"q3.1-055","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Unterscheide vorbereitende Übungen und Vorübungen im Rahmen methodischer Übungsreihen.","a":"• Vorbereitende Übungen: grundlegende Fertigkeiten und Fähigkeiten, nicht zwingend bewegungsverwandt\n• Vorübungen: bewegungsverwandte Fertigkeiten zur Annäherung an die Zielübung","e":"Vorbereitende Übungen machen fit für die Bewegung, Vorübungen ähneln ihr schon (strukturverwandt). Beide schaffen Lernvoraussetzungen für die Zielübung. Beispiel Speerwurf: Ballspiele mit Würfen oder Wurfmehrkämpfe sind vorbereitend, das Werfen verschiedener Geräte aus dem Dreischrittrhythmus ist eine Vorübung.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-056","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Erläutere den methodischen Dreischritt bei methodischen Übungsreihen.","a":"1. Vorbereitende Übungen: koordinative und konditionelle Voraussetzungen\n2. Vorübungen: bewegungsverwandte Annäherung\n3. Zielübung: Gesamtform","e":"Der Dreischritt ist das zentrale Charakteristikum von MÜR: erst das Fundament, dann die Annäherung, dann das Ziel. Beispiel Handstützüberschlag: Stützkraft- und Beweglichkeitsübungen (vorbereitend), Handstand-Abrollen und Überschlag vom Kasten mit Hilfe (Vorübungen), freier Handstützüberschlag am Boden (Zielübung).","quelle":"L05.3","typ":"kern"},{"id":"q3.1-057","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Nenne die drei Haupttypen methodischer Übungsreihen.","a":"1. Serielle Übungsreihen: Aufbau „von vorne nach hinten“\n2. Funktionale Übungsreihen: Aufbau „von der Mitte nach außen“\n3. Programmierte Übungsreihen: empirisch überprüfter, kleinschrittiger Aufbau","e":"Eselsbrücke: Seriell = in Reihenfolge, funktional = vom Kern (Hauptaktion) aus, programmiert = Lernkarten in kleinen Schritten. Beispiel: Den Korbleger kann man seriell, das Kugelstoßen funktional aufbauen.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-058","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Erläutere die serielle Übungsreihe.","a":"Aufbau „von vorne nach hinten“ (Programmlängenverkürzung): Teilbewegungen werden in der Reihenfolge des Bewegungsablaufs aufgeschaltet.","e":"Man beginnt mit dem ersten Teil der Bewegung und hängt die folgenden nach räumlich-zeitlichen Aspekten nacheinander an. Beispiel: Beim Korbleger wird erst das rhythmische Dribbling geschult, dann mit dem Stoppen und schließlich mit dem Werfen verbunden.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-059","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Erläutere die funktionale Übungsreihe.","a":"Aufbau „von der Mitte nach außen“ (Programmlängenverkürzung): Start mit der Hauptaktion, dann Ergänzung der Hilfsaktionen; geübt werden genau die Aktionen der Zielbewegung.","e":"Man beginnt mit dem wichtigsten Teil, der über das Ergebnis entscheidet (Hauptfunktionsphase), und ergänzt dann vorbereitende und überleitende Phasen. Beispiel: Beim Kugelstoßen startet man mit dem Stoß aus der Stoßauslage (Hauptaktion) und ergänzt dann das Angleiten aus der Grundstellung.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-060","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Erläutere die programmierte Übungsreihe.","a":"Kleinschrittige, empirisch überprüfte Übungsfolge, oft als programmierte Lernkarten zum selbstständigen Arbeiten.","e":"Wie eine Bauanleitung mit vielen kleinen, geprüften Schritten – sie orientiert sich an logischen und empirisch gestützten Kriterien. Beispiel: Kruber und Fuchs bieten für das Kugelstoßen Lernkarten an – vom Halten der Kugel über Ausgangsstellung, Beinstreckung und Rumpfdrehung bis zum Stoßen aus dem Angleiten.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-061","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Vergleiche serielle und funktionale Übungsreihen.","a":"Gemeinsam: Programmlängenverkürzung, schrittweises Zusammensetzen.\n• Seriell: nach zeitlichem Ablauf, Start mit erster Phase\n• Funktional: nach Funktion, Start mit Hauptaktion → Hauptphase wird am häufigsten geübt","e":"Seriell folgt der Uhr („von vorne nach hinten“), funktional folgt der Wichtigkeit („von der Mitte nach außen“); funktional werden dabei genau die Aktionen der Zielbewegung geübt. Beispiel Weitsprung: seriell erst Anlauf, dann Absprung, dann Flug; funktional erst Absprung aus kurzem Anlauf, dann wird der Anlauf verlängert.","quelle":"L05.3","typ":"kern"},{"id":"q3.1-062","thema":"Q3.1","kapitel":"Methodische Übungsreihen","q":"Welche Aspekte musst du berücksichtigen, wenn du eine methodische Übungsreihe begründet entwickeln sollst (z. B. Handballsprungwurf)?","a":"• Analyse der Zielbewegung (Phasen, Hauptaktion, Überforderungsaspekte)\n• Lernmethode und MÜR-Typ\n• Dreischritt\n• Vereinfachungsstrategien und ihre Rücknahme\n• methodische Grundsätze\n• Voraussetzungen und Lernphase der Lernenden","e":"Bei Abituraufgaben gibt es Punkte für die Begründung, nicht für die bloße Übungsliste. Die Methode (ganzheitlich, Teil, Ganz-Teil-Ganz) richtet sich nach der Komplexität, der Typ ist seriell, funktional oder programmiert; die Grundsätze lauten leicht→schwer, einfach→komplex, bekannt→unbekannt, sicher→risikoreich. Beispiel Handballsprungwurf: Wurf aus dem Stand (Hauptaktion), dann aus dem Dreischrittrhythmus, dann mit Absprung über ein Hindernis, später gegen Abwehrspieler – jeweils mit Bezug zu Vereinfachungsprinzipien begründet.","quelle":"L05.4","typ":"kern"},{"id":"q3.1-063","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Welche Arten von Informationen bzw. Lernhilfen können Lehrende beim Bewegungslernen einsetzen?","a":"• verbal/akustisch: Beschreibung, Anweisungen, Rhythmusvorgaben\n• visuell: Demonstration, Video, Bildreihen, Markierungen\n• taktil-kinästhetisch: Hilfestellung, Bewegungsführung\n• Feedback über Ergebnis und Ausführung","e":"Je mehr Sinneskanäle (Analysatoren) man passend nutzt, desto klarer wird die Bewegungsvorstellung. Laut Buch helfen in der Grobkoordination v. a. verbale und visuelle Hinweise, in der Feinkoordination Hinweise zum Bewegungsempfinden. Beispiel: Beim Brustschwimmen zeigt der Lehrer den Beinschlag (visuell), sagt „anziehen – grätschen – schließen“ (verbal) und führt die Füße eines Schülers am Beckenrand (taktil).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-064","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Was versteht man unter Feedback (Rückmeldung) beim motorischen Lernen? Unterscheide intrinsisches und extrinsisches Feedback.","a":"Feedback = Information über Bewegungsausführung oder -ergebnis zur Korrektur.\n• Intrinsisch: aus den eigenen Sinnesorganen\n• Extrinsisch (augmentiert): zusätzlich von außen (Trainer, Video, Messgeräte)","e":"Intrinsisch = was ich selbst spüre und sehe (kinästhetisch, vestibulär, visuell, akustisch, taktil), extrinsisch = was mir jemand sagt oder zeigt. In der Feinkoordination werden beide bewegungsoptimierend verarbeitet. Beispiel: Ein Tennisspieler spürt, dass der Ball nicht sauber getroffen wurde (intrinsisch), der Trainer sagt ihm, dass der Schläger zu spät kam (extrinsisch).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-065","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Unterscheide Knowledge of Results (KR) und Knowledge of Performance (KP).","a":"• KR (Ergebnisrückmeldung): Information über das Ergebnis (Weite, Zeit, Treffer)\n• KP (Verlaufsrückmeldung): Information über die Ausführung (Gelenkwinkel, Timing)","e":"KR sagt, was passiert ist, KP sagt, warum. KR ist oft schon intrinsisch verfügbar; KP hilft besonders bei komplexen Techniken, weil sie Fehlerursachen benennt. Beispiel: „Der Wurf war 30 cm zu kurz“ ist KR, „Du hast den Arm nicht ganz gestreckt“ ist KP.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-066","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Nenne Regeln für den wirksamen Einsatz von Feedback und Fehlerkorrekturen beim Bewegungslernen.","a":"• sparsam: nur Hauptfehler (Ursache)\n• zeitnah, mit Pause zur Selbsteinschätzung\n• nicht nach jedem Versuch\n• positiv, konkret\n• an Lernphase anpassen\n• selbstkontrolliertes Feedback nutzen","e":"Zu viel Feedback macht abhängig und überfordert (Guidance-Hypothese); seltenes oder zusammenfassendes Feedback fördert Selbstständigkeit und Behalten. Anfänger brauchen einfache, bildhafte Hinweise, Fortgeschrittene Hinweise zum Bewegungsempfinden. Beispiel: Statt einem Anfänger beim Aufschlag fünf Fehler zu nennen, sagt der Trainer nur „Wirf den Ball höher“ – denn der zu niedrige Ballwurf verursacht die anderen Fehler.","quelle":"L05.1","typ":"zusatz"},{"id":"q3.1-067","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Welche Bedeutung hat Instruktion beim Neulernen und was unterscheidet einen internalen von einem externalen Aufmerksamkeitsfokus?","a":"Instruktion vermittelt Ziel und Ablauf (Bewegungsvorstellung), anfangs knapp und präzise.\n• Internaler Fokus: auf eigene Körperbewegung\n• Externaler Fokus: auf Bewegungseffekt in der Umwelt – meist lernwirksamer (Wulf)","e":"Wer an den Effekt denkt statt an die Muskeln, bewegt sich flüssiger und automatisierter. Beispiel: „Lass den Ball in einem hohen Bogen in den Korb fallen“ (external) wirkt meist besser als „Klapp das Handgelenk nach vorn“ (internal).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-068","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Welche Funktion hat die Demonstration (Lernen am Modell) beim Neulernen?","a":"Schafft eine konkrete visuelle Bewegungsvorstellung (Grobstruktur, Rhythmus, Ziel) – besonders in der Grobkoordination.","e":"Ein Bild sagt mehr als tausend Worte – besonders für Anfänger. Möglich sind Lehrer- oder Schülerdemonstration, Video oder Bildreihen. Regeln: zentrale Merkmale per Beobachtungsauftrag hervorheben, mehrfach, aus guter Perspektive und ggf. verlangsamt zeigen, mit kurzer verbaler Info kombinieren. Auch lernende Mitschüler sind wirksame Modelle (Bandura). Beispiel: Das Buch empfiehlt beim Positionswurf eine Videosequenz eines Profispielers, damit die Schüler den Bewegungsablauf vor Augen haben.","quelle":"L05.1","typ":"zusatz"},{"id":"q3.1-069","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Was ist eine Bewegungsvorstellung und warum ist sie für das Bewegungslernen wichtig?","a":"Innere Repräsentation eines Bewegungsablaufs (visuell, kinästhetisch, verbal). Bedeutung:\n• Grundlage für Planung/Programmierung\n• Sollwert für den Soll-Ist-Vergleich und Korrekturen","e":"Man kann nur das gut ausführen, was man sich klar vorstellen kann. Die Vorstellung wird im Lernprozess präziser: anfangs grob und visuell, später differenziert und kinästhetisch; Lehrende fördern sie durch verbale und visuelle Hinweise. Beispiel: Wer sich den Flickflack nicht vorstellen kann, weiß nicht, wann er die Arme nach hinten führen soll – erst Video und Erklärung bauen die Vorstellung auf.","quelle":"L05.1","typ":"zusatz"},{"id":"q3.1-070","thema":"Q3.1","kapitel":"Lernhilfen und Feedback","q":"Wie lassen sich Druckbedingungen in der Phase der variablen Verfügbarkeit gezielt erhöhen?","a":"• Präzisionsdruck\n• Zeitdruck\n• Komplexitätsdruck\n• Situationsdruck\n• Belastungsdruck\n• Organisationsdruck","e":"In der dritten Lernphase wird die Technik gezielt „gestresst“, damit sie im Wettkampf hält: z. B. gegen eine Verteidigerhand werfen (Präzision), Sprungwurf aus dem Dribbling (Komplexität), wechselnde Situationen, Mindesttrefferzahl pro Minute oder Ermüdung (Belastung), mehrere Aufgaben gleichzeitig (Organisation). Beispiel: Ein Handballer übt den Sprungwurf nach einem Sprint (Belastungsdruck) und gegen einen aktiven Abwehrspieler (Situations- und Präzisionsdruck).","quelle":"L05.1","typ":"kern"},{"id":"q3.1-071","thema":"Q3.1","kapitel":"Mentales Training","q":"Definiere mentales Training.","a":"Planmäßig wiederholtes, bewusstes Sich-Vorstellen einer Bewegung ohne gleichzeitige praktische Ausführung – zum Erlernen, Verbessern und Stabilisieren.","e":"Beim mentalen Training übt das Gehirn, ohne dass sich der Körper bewegt. Grundlage ist eine präzise Bewegungsvorstellung; die Wirkung erklärt u. a. der Carpenter-Effekt: Die Vorstellung löst minimale Innervationen der beteiligten Muskeln aus. Beispiel: Ein Skirennläufer geht vor dem Start mit geschlossenen Augen jedes Tor der Strecke im Kopf durch und bewegt dabei leicht die Hände mit.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-072","thema":"Q3.1","kapitel":"Mentales Training","q":"Nenne die Formen des mentalen Trainings im weiteren Sinne.","a":"• Subvokal: inneres Selbstgespräch über den Ablauf\n• Verdecktes Wahrnehmungstraining: Außensicht, wie im Film\n• Ideomotorisch: Innensicht mit Bewegungsgefühl (i. e. S., am wirksamsten)","e":"Die Formen werden von „Reden“ über „Zuschauen“ zu „Fühlen“ immer intensiver. Ergänzend gibt es das observative Training, also das reale Beobachten anderer. Beispiel: Eine Turnerin sagt sich ihre Übung vor (subvokal), sieht sich selbst im Kopf turnen (verdeckt) und spürt schließlich jede Drehung (ideomotorisch).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-073","thema":"Q3.1","kapitel":"Mentales Training","q":"Wann ist mentales Training besonders sinnvoll und wo liegen seine Grenzen?","a":"Sinnvoll: bei Verletzung/Pausen, Wettkampfvorbereitung, komplexen Abläufen, in Kombination mit Praxis.\nGrenzen: braucht Bewegungsvorstellung und -erfahrung (für Anfänger kaum wirksam), ersetzt Üben nicht.","e":"Mentales Training funktioniert nur, wenn man die Bewegung schon kennt und spüren kann; es erfordert Konzentration und Übung. Es hilft auch, den Ablauf einzuprägen, Konzentration und Selbstvertrauen zu stärken und Lernzeiten zu verkürzen, besonders bei Bewegungen mit hohem kognitivem Anteil. Beispiel: Ein verletzter Hochspringer kann seinen Flop im Kopf weiter üben, ein Anfänger, der nie gefloppt hat, hätte dagegen kaum ein inneres Bild davon.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-074","thema":"Q3.1","kapitel":"Mentales Training","q":"Was besagt der Carpenter-Effekt (ideomotorisches Prinzip)?","a":"Intensive Bewegungsvorstellung löst minimale, messbare Innervationen in der beteiligten Muskulatur aus – Erklärung für die Wirkung mentalen Trainings.","e":"Denken an eine Bewegung ist eine Art „Mini-Bewegung“ im Nervensystem: Die Vorstellung aktiviert ähnliche neuronale Strukturen wie die echte Bewegung. Beispiel: Wer sich intensiv einen Elfmeterschuss vorstellt, bei dem lassen sich im Oberschenkelmuskel winzige elektrische Aktivitäten messen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-075","thema":"Q3.1","kapitel":"Weitere Lernansätze","q":"Unterscheide offene und geschlossene Fertigkeiten und erläutere Konsequenzen für das Lernen.","a":"• Geschlossen: stabile, vorhersehbare Umwelt → Ziel konstante Ausführung (Fixierung)\n• Offen: wechselnde Umwelt → Ziel variable Anpassung (Diversifikation)\n• Konsequenz: offene Fertigkeiten früh variabel und spielnah üben","e":"Bei geschlossenen Fertigkeiten (Turnen, Kugelstoßen) bestimmt man selbst, wann es losgeht, und kann die Bewegung vorab planen; bei offenen (Sportspiele, Zweikampf) bestimmen Gegner, Ball und Mitspieler die Situation – hier müssen auch Wahrnehmung und Entscheidung geschult werden. Beispiel: Der Freiwurf im Basketball ist eher geschlossen, der Pass im Fastbreak ist offen.","quelle":"L05.3","typ":"zusatz"},{"id":"q3.1-076","thema":"Q3.1","kapitel":"Weitere Lernansätze","q":"Was versteht man unter variablem Üben und dem Effekt der kontextuellen Interferenz?","a":"• Variables Üben: Fertigkeit mit wechselnden Parametern üben → stabiles Schema (Schmidt)\n• Kontextuelle Interferenz: gemischtes statt geblocktes Üben senkt die Übungsleistung, verbessert aber Behalten und Transfer","e":"Abwechslung macht das Üben schwerer, aber das Gelernte haltbarer: Das ständige Neuplanen der Bewegung erfordert tiefere Verarbeitung. Variiert werden etwa Distanz, Kraft oder Tempo. Beispiel: Wer Würfe von 3, 5 und 7 m durchmischt übt, trifft im Training seltener, im Spiel aus neuen Positionen aber besser als jemand, der 50-mal von derselben Stelle wirft.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.1-077","thema":"Q3.1","kapitel":"Weitere Lernansätze","q":"Erläutere den Ansatz des differenziellen Lernens (nach Schöllhorn).","a":"Systemdynamischer Ansatz ohne Idealbild: möglichst viele unterschiedliche Bewegungsvarianten ohne Wiederholung und Korrektur → Lernender findet durch Selbstorganisation seine individuelle Lösung.","e":"Beim differenziellen Lernen werden „Fehler“ absichtlich eingebaut, damit der Körper selbst den besten Weg findet. Begründung: Kein Bewegungsablauf ist exakt wiederholbar, und Variabilität ist Grundlage der Anpassungsfähigkeit. Das ist der Gegensatz zu klassischen MÜR mit festem Leitbild. Beispiel: Kugelstoßer stoßen mit geschlossenen Augen, mit gebeugtem Knie, mit verschiedenen Armhaltungen – jedes Mal anders.","quelle":"L05.3","typ":"zusatz"},{"id":"q3.1-078","thema":"Q3.1","kapitel":"Weitere Lernansätze","q":"Wie unterscheiden sich der Informationsverarbeitungsansatz und systemdynamische Ansätze in Bezug auf die Vermittlung sportlicher Fertigkeiten?","a":"• Informationsverarbeitung: Steuerung über GMP; Lernen durch Wiederholung, Feedback, Korrektur; Technikleitbild, MÜR\n• Systemdynamisch: Selbstorganisation aus Person, Aufgabe, Umwelt; Lernen durch Variabilität; Bedingungen gestalten, wenig Korrektur","e":"Der eine Ansatz sieht das Gehirn als Computer mit Programmen, der andere als System, das sich selbst organisiert und unter den Rahmenbedingungen (Constraints) stabile Bewegungsmuster findet. Methodisch heißt das Vereinfachungsstrategien auf der einen, variables bzw. differenzielles Üben auf der anderen Seite. Beispiel: Nach dem Informationsansatz übt man den Korbleger nach MÜR mit Korrektur, nach dem systemdynamischen Ansatz verändert man Korbhöhe, Ballgröße und Anlaufwinkel und lässt die Schüler selbst Lösungen finden.","quelle":"L05.3","typ":"zusatz"},{"id":"q3.1-079","thema":"Q3.1","kapitel":"Weitere Lernansätze","q":"Wodurch kann ein Bewegungsablauf in der Praxis automatisiert und stabilisiert werden?","a":"• viele konzentrierte Wiederholungen\n• variables Üben\n• Druckbedingungen steigern\n• Üben unter Ermüdung und psychischem Druck\n• Doppeltätigkeiten\n• weniger externes Feedback","e":"Stabil ist eine Technik erst, wenn sie auch unter Störungen funktioniert. Erst wird in der Feinkoordination konstant wiederholt, dann unter wechselnden Bedingungen und mit Zeit-, Präzisions-, Komplexitäts-, Situations- und Belastungsdruck; weniger Fremdfeedback fördert die Eigenwahrnehmung. Beispiel: Ein Volleyballer übt den Aufschlag erst konstant, dann auf wechselnde Zielfelder, nach Sprints und schließlich mit Zuschauerlärm vom Band.","quelle":"L05.1","typ":"zusatz"},{"id":"q3.2-001","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Womit beschäftigt sich die Sportmotorik und wie unterscheidet sie sich von der Bewegungsbeobachtung von außen?","a":"• Sportmotorik: Innensicht – untersucht Teilsysteme/-prozesse (Nervensystem, Sinne, Muskeln), die Bewegungen auslösen und kontrollieren\n• Biomechanik/Bewegungslehre: Außensicht (Phasen, Zweckmäßigkeit, Kräfte)","e":"Die Außensicht fragt: Wie sieht die Bewegung aus? Die Innensicht fragt: Was passiert im Körper, damit die Bewegung überhaupt entsteht? Beispiel: Beim Hochsprung beschreibt die Außensicht Anlauf, Absprung und Lattenüberquerung, die Sportmotorik fragt, wie Gehirn, Sinne und Muskeln den Absprung steuern.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-002","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Was versteht man unter motorischer Kontrolle?","a":"Aufgabe von Teilsystemen und -prozessen (v. a. Nervensystem), die Freiheitsgrade des Körpers so zu kontrollieren, dass eine koordinierte Bewegung entsteht.","e":"Unser Körper hat sehr viele Gelenke und Muskeln, die sich theoretisch unabhängig bewegen könnten; motorische Kontrolle sorgt dafür, dass sie sinnvoll zusammenspielen. Das dabei auftretende Freiheitsgradeproblem ist bis heute eine große Herausforderung der Motorikforschung. Beispiel: Bei Autos ist nur ein Teil der Räder lenkbar. Wären alle vier Räder einzeln lenkbar, wäre schon Geradeausfahren schwierig, weil zu viele Freiheitsgrade kontrolliert werden müssten.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-003","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Erläutere das Freiheitsgradeproblem nach Bernstein.","a":"• Bernstein: Wie werden die vielen Muskeln so kontrolliert, dass eine koordinierte Bewegung entsteht?\n• Pro Muskel zu steuern: Kontraktionsbeginn, -dauer, -stärke\n• Bei ca. 792 Muskeln riesige Zahl an Freiheitsgraden, die das ZNS reduzieren muss","e":"Nikolai Bernstein war ein russischer Physiologe. Da die Muskeln im Prinzip unabhängig voneinander agieren könnten, stellt sich die Frage, wie das ZNS diese Freiheitsgrade beherrscht. Stell dir ein Orchester mit fast 800 Musikern vor, die alle zur richtigen Zeit, gleich lang und passend laut spielen müssen. Beispiel: Ein Anfänger beim Tennisaufschlag hält viele Gelenke steif (friert Freiheitsgrade ein), erst mit Übung werden sie nach und nach freigegeben.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-004","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Erkläre das EVA-Prinzip der Informationsverarbeitung im ZNS.","a":"• Eingabe: Rezeptoren nehmen Reize auf, afferente Weiterleitung ins ZNS\n• Verarbeitung: erkennen, bewerten, speichern, mit Gespeichertem vergleichen\n• Ausgabe: efferente Nerven aktivieren Muskeln → Bewegung","e":"Die Informationen werden als Aktionspotenziale weitergeleitet; die Muskeln setzen sie in Kontraktion um. Das EVA-Prinzip stammt aus der Computerwelt: Tastatur, Prozessor, Bildschirm. Beispiel: Der Torwart sieht den Ball kommen (Eingabe), das Gehirn berechnet Flugbahn und wählt eine Abwehraktion (Verarbeitung), dann springt er in die Ecke (Ausgabe).","quelle":"L03.1","typ":"kern"},{"id":"q3.2-005","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Wie wird der Sportler im kognitiven Ansatz der motorischen Kontrolle charakterisiert?","a":"Als informationsverarbeitendes System: nimmt Meldungen aus Umwelt und Körper auf, verrechnet sie wie ein Computer und wählt Handlungen mithilfe gespeicherter Bewegungsprogramme; begrenzte Verarbeitungskapazität.","e":"Der kognitive Ansatz nutzt die Computermetapher: Der Mensch nimmt Daten auf, rechnet und gibt Befehle an die Muskeln. Wie ein Computer kann er nur begrenzt viel gleichzeitig verarbeiten. Beispiel: Ein Basketballer sieht die Entfernung zum Korb, ruft seinen gespeicherten Wurf ab und passt ihn an die Distanz an.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-006","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Erläutere die Schallplatten-Metapher (Roth/Schmidt) zur Bewegungssteuerung.","a":"• Im ZNS sind „Bewegungsplatten“ (Bewegungsprogramme) gespeichert, die bei Bedarf abgespielt werden\n• Abspielen erzeugt motorische Kommandos an die Muskulatur → räumlich-zeitlich geordnete Bewegung","e":"Muskeln und Gliedmaßen sind die „Lautsprecher“, der Sportler ist wie ein Discjockey, der seine Programme auswählt. Die Metapher zeigt, dass Bewegungen nicht jedes Mal neu „erfunden“, sondern als fertige Programme abgerufen werden. Beispiel: Ein geübter Schwimmer muss nicht über jeden Kraularmzug nachdenken – er „legt die Kraul-Platte auf“ und der Ablauf läuft.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-007","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Was besagen das Hick'sche und das Fitts'sche Gesetz?","a":"• Hick: Wahlreaktionszeit steigt mit der Zahl der Reaktionsalternativen\n• Fitts: Bewegungszeit steigt mit der geforderten Zielgenauigkeit (Geschwindigkeits-Genauigkeits-Austausch)","e":"Beide Gesetze beschreiben die begrenzte Verarbeitungskapazität („Ladezeiten“) des Menschen. Beispiel Hick: Ein Verteidiger, der nur einen Pass erwarten muss, reagiert schneller als einer, der Pass, Wurf und Dribbling bedenken muss. Beispiel Fitts: Ein Dartwurf aufs Bullseye wird langsamer und kontrollierter ausgeführt als ein Wurf auf die ganze Scheibe.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-008","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Warum gilt beim 100-m-Sprint eine Reaktion unter 100 ms als Fehlstart?","a":"Reiz aufnehmen, verarbeiten und an die Muskeln weitergeben braucht eine Mindestzeit; unter 100 ms kann keine echte Reaktion auf den Schuss vorliegen, nur Raten/Vorwegnahme.","e":"Die menschliche Informationsverarbeitung hat Grenzen der Verarbeitungsgeschwindigkeit; das Regelwerk nutzt dieses Ergebnis der Motorikforschung und wertet z. B. schon einen Druck auf den Startblock 95 ms nach dem Schuss als Fehlstart. Beispiel: Reagiert ein Sprinter nach 0,09 s, hat er nicht auf den Schuss reagiert, sondern losgelaufen, bevor er ihn verarbeiten konnte – er hat also gepokert.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-009","thema":"Q3.2","kapitel":"Grundbegriffe Sportmotorik","q":"Was versteht man unter Emergenz (Selbstorganisation) von Bewegungen?","a":"Selbstorganisation koordinierter Bewegungen, die sich nicht mit Informationsverarbeitung (Programmen) erklären lässt; v. a. bei zyklischen Bewegungen untersucht (Hossner et al.).","e":"Emergent heißt: Die Ordnung „taucht von selbst auf“, ohne dass ein zentraler Befehl sie plant. Beispiel: Erhöht man beim Gehen ständig das Tempo, geht man ab einer bestimmten Geschwindigkeit automatisch ins Laufen über – und die Übergangsgeschwindigkeit ist beim Wechsel vom Laufen zum Gehen eine andere.","quelle":"L03.1","typ":"kern"},{"id":"q3.2-010","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Welche Funktionen haben sensorische und motorische Systeme?","a":"• Sensorisch: Informationen über Körper und Umwelt aufnehmen und verarbeiten\n• Motorisch: Bewegungen starten, ausführen, überwachen, bewerten, speichern (efferent)\n• Beide untrennbar verbunden (sensomotorisch)","e":"Motorische Systeme verbinden ZNS und Muskel über efferente Bahnen (Olivier et al.). Für Überwachung und Ergebnisbewertung brauchen sie die Wahrnehmungsanalysatoren – ohne Sinne wüsste der Körper nicht, was er tun soll und ob es geklappt hat. Beispiel: Beim Basketballfreiwurf fühlt der Spieler den Abwurf (kinästhetisch, taktil), hört das „Swish“ (auditiv), sieht den Ball fallen (visuell) und merkt, ob er stabil steht (vestibulär).","quelle":"L03.2","typ":"kern"},{"id":"q3.2-011","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Erkläre die Begriffe afferent und efferent.","a":"• Afferent: zum Zentralnervensystem hinführend (sensorische Bahnen; Informationen von Rezeptoren ins ZNS).\n• Efferent: vom ZNS wegführend, zum Muskel (Effektor) hin (motorische Bahnen; Befehle an die Muskeln).","e":"Eselsbrücke: Afferent = Ankommend im Gehirn, Efferent = Exit aus dem Gehirn. Beispiel: Die Meldung „Knie ist stark gebeugt“ läuft afferent ins Rückenmark, der Befehl „Oberschenkelmuskel anspannen“ läuft efferent zum Muskel.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-012","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Was sind Wahrnehmungsanalysatoren und aus welchen Bestandteilen bestehen sie?","a":"Systeme zur Aufnahme und Verarbeitung von Gleichgewichts-, Bewegungs-, auditiven, visuellen und taktilen Informationen.\nBestandteile: Rezeptoren, afferente Nervenbahnen, sensorische Zentren im Gehirn","e":"Je effektiver ein Sportler Bewegung und Umwelt erfasst, desto besser kann er sich auf veränderte Bedingungen einstellen. Ein Analysator ist mehr als das Sinnesorgan: Er umfasst den ganzen Weg vom Fühler bis zur Auswertung im Gehirn. Beispiel: Beim Sehen gehören Netzhaut, Sehnerv und Sehrinde im Hinterhauptslappen zum optischen Analysator.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-013","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Nenne die fünf Wahrnehmungsanalysatoren und ordne sie Propriozeptoren bzw. Exterozeptoren zu.","a":"• Propriozeptoren (eigener Körper): vestibulär, kinästhetisch\n• Exterozeptoren (außen): optisch, akustisch, taktil","e":"Lateinisch proprius = eigen, exter = außen. Wichtige Propriozeptoren sind Muskelspindeln (Längenkontrolle), Sehnenspindeln/Golgi-Organe (Spannungskontrolle) und das Gleichgewichtsorgan im Innenohr. Beispiel: Beim Salto meldet das Innenohr die Drehung (proprio), die Augen sehen den Boden (extero).","quelle":"L03.2","typ":"kern"},{"id":"q3.2-014","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Welche Wahrnehmungsaspekte erfasst jeder der fünf Analysatoren (nach Schnabel)?","a":"• Vestibulär: Gleichgewicht, Lage, Beschleunigung\n• Kinästhetisch: Muskelspannung, Gelenkstellung, Körperraumlage\n• Optisch: Helligkeit, Farbe, Form\n• Akustisch: Lautstärke, Tonhöhe, Geräusche\n• Taktil: Temperatur, Objektgröße, -form, -oberfläche","e":"Vestibulär gehören auch Orientierung und Haltungsstabilität dazu (nach Schnabel). Jeder Analysator liefert eine eigene Art von Information. Beispiele: vestibulär beim Abstoppen und Richtungswechsel, kinästhetisch beim Basketballwurf aus verschiedenen Entfernungen oder beim Salto, optisch beim peripheren Sehen im Sportspiel, akustisch beim Tanzen, taktil beim Werfen mit Leder- vs. Gummiball.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-015","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Nenne für jeden Wahrnehmungsanalysator die „Hauptzentrale“ (Rezeptorort) und die motorische Hauptfunktion.","a":"• Vestibulär: Bogengänge/Maculaorgane (Innenohr) – Haltungskontrolle\n• Kinästhetisch: Muskelspindeln – Bewegungsempfinden\n• Optisch: Netzhaut – räumlich-zeitliche Informationen\n• Auditiv: Innenohr – Unterstützung des Bewegungsvollzugs\n• Taktil: Hautrezeptoren – Bewegungsgefühl","e":"Die Bogengänge registrieren Rotation, die Maculaorgane Translation. Zum kinästhetischen Analysator gehören neben den Muskelspindeln weitere Rezeptoren in Sehnen und Gelenken; er kontrolliert Stellungs-, Kraft-, Muskel- und Körpersinn. Beispiel: Beim Turnen auf dem Schwebebalken sichert das Innenohr die Haltung, die Fußsohlen liefern taktile Rückmeldung und die Muskelspindeln melden die Gelenkstellung.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-016","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Warum hat der kinästhetische Analysator eine herausragende Bedeutung?","a":"• Jede Bewegung löst kinästhetische Signale aus → enger mit allen anderen Analysatoren verbunden als diese untereinander\n• Zentral für komplexe Bewegungen; besonders eng mit dem optischen Analysator","e":"Visuelle Informationen aktivieren gespeicherte kinästhetische (sowie taktile und vestibuläre) Informationen – der optische Analysator hat deren Bewegungserfahrung gleichsam „mit übernommen“ (Schnabel). Beispiel: Ein erfahrener Turner sieht einen Salto eines anderen und „spürt“ ihn beinahe im eigenen Körper – das Sehen ruft das gespeicherte Bewegungsgefühl ab.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-017","thema":"Q3.2","kapitel":"Wahrnehmungsanalysatoren","q":"Welche Bedeutung hat das Zusammenwirken der Wahrnehmungsanalysatoren für die sportliche Leistung?","a":"• Analysatoren bestimmen die Güte des Bewegungsablaufs und die Qualität der koordinativen Fähigkeiten\n• Wirken zusammen, Gewichtung je nach Sportart verschieden\n• Kinästhetischer Analysator dominant","e":"Koordination beginnt bei der Wahrnehmung: Wer schlecht wahrnimmt, kann auch schlecht steuern. Der kinästhetische Analysator verbindet die anderen. Beispiel: Im Turnen dominieren vestibulärer und kinästhetischer Analysator, im Volleyball der optische (Ball, Gegner) – aber immer arbeiten mehrere zusammen.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-018","thema":"Q3.2","kapitel":"Muskel und motorische Einheit","q":"Beschreibe den Aufbau eines Skelettmuskels vom Muskel bis zum Sarkomer.","a":"Muskel → Muskelfaserbündel → Muskelfasern (Muskelzellen) → Myofibrillen → Sarkomere (kleinste kontraktile Einheit, zwischen Z-Scheiben; Aktin und Myosin)","e":"Muskelfasern sind vielkernig, 20–100 µm dick und bis 20 cm lang. Sie enthalten einige hundert Myofibrillen (ca. 80 % der Faser), umgeben von Sarkoplasma, sarkoplasmatischem Retikulum (Kalziumspeicher) und Mitochondrien. Ein Sarkomer ist ca. 2–2,5 µm lang; jedes Myosinfilament ist hexagonal von sechs Aktinfilamenten umgeben. Beispiel: Im Bizeps stecken Hunderttausende Muskelfasern, jede Myofibrille ist eine lange Kette winziger Sarkomere, die sich bei der Kontraktion alle ein Stück verkürzen.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-019","thema":"Q3.2","kapitel":"Muskel und motorische Einheit","q":"Wie entsteht die Querstreifung der Skelettmuskulatur?","a":"• I-Band (hell): nur Aktin\n• A-Band (dunkel): Aktin und Myosin überlappen\n• H-Zone: nur Myosin\n• Sarkomere liegen in allen Myofibrillen auf gleicher Höhe → Querstreifung","e":"Die Streifen kommen von den unterschiedlich dichten Filamentbereichen; das I-Band liegt um die Z-Scheibe, die H-Zone in der Mitte des A-Bands. Beispiel: Bei einer Kontraktion werden I-Band und H-Zone schmaler, das A-Band bleibt gleich lang – ein wichtiger Beleg für die Gleitfilamenttheorie.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-020","thema":"Q3.2","kapitel":"Muskel und motorische Einheit","q":"Welche Rolle spielt das Titin im Muskel?","a":"• Elastisches Protein; verankert die Filamente an der Z-Scheibe\n• Federmechanismus: Feinabstimmung von An- und Entspannung\n• Zieht den Muskel nach Dehnung in die Ausgangslänge zurück","e":"Mit dieser Erkenntnis wurden viele angeblich positive Wirkungen des statischen Dehnens widerlegt. Titin wirkt wie ein Gummiband im Sarkomer. Beispiel: Dehnst du deinen Oberschenkel, wird Titin gespannt, nach dem Loslassen zieht es den Muskel wieder auf seine Ruhelänge zurück – eine dauerhafte „Verlängerung“ durch Stretching gibt es so nicht.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-021","thema":"Q3.2","kapitel":"Muskel und motorische Einheit","q":"Erkläre die Filamentgleittheorie der Muskelkontraktion.","a":"• Bei Innervation gleiten Aktinfilamente zwischen die Myosinfilamente\n• Filamente selbst verkürzen sich nicht\n• Viele hintereinandergeschaltete Sarkomere verkürzen sich → sichtbare Kontraktion","e":"Jedes Sarkomer verkürzt sich nur minimal, aber da sehr viele hintereinanderliegen, summiert sich das zur Muskelkontraktion. Stell dir zwei ineinandergeschobene Kämme vor: Sie werden nicht kürzer, sondern greifen tiefer ineinander. Beispiel: Beim Bizepscurl gleiten in Millionen Sarkomeren gleichzeitig die Aktinfäden ins Myosin – zusammen ergibt das die Beugung des Arms.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-022","thema":"Q3.2","kapitel":"Muskel und motorische Einheit","q":"Beschreibe den Querbrückenzyklus.","a":"1. Myosinkopf fest an Aktin gebunden\n2. ATP-Anlagerung löst ihn\n3. ATP-Spaltung spannt den Kopf (ca. 90°)\n4. Kalzium: Querbrücke zum nächsten Aktin\n5. Abgabe von ADP + P: Kopf kippt auf ca. 45° („Ruderschlag“), Aktin wird gezogen\n6. Zyklus beginnt neu","e":"ATP ist der Treibstoff fürs Lösen und Spannen, Kalzium das Startsignal für die Bindung. Bei der Freisetzung von Phosphat und ADP wird die gespeicherte Spannung in mechanische Energie umgesetzt. Die Myosinköpfe arbeiten wie Ruderer, die immer wieder eintauchen, ziehen und loslassen. Beispiel: Fehlt nach dem Tod ATP, können sich die Köpfe nicht mehr lösen – deshalb entsteht die Totenstarre.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-023","thema":"Q3.2","kapitel":"Muskel und motorische Einheit","q":"Definiere die motorische Einheit.","a":"Funktionsgefüge aus einem Motoneuron (im Rückenmark), seinem Motoaxon und allen von ihm innervierten Muskelfasern; diese kontrahieren immer gemeinsam (Alles-oder-nichts).","e":"Die motorischen Einheiten eines Muskels arbeiten nie alle gleichzeitig, sondern phasenverschoben – so entsteht eine gleichmäßige Kontraktion des ganzen Muskels. Eine motorische Einheit ist wie ein Trupp Arbeiter mit einem Vorarbeiter: Ruft er, arbeiten alle. Beispiel: Hebst du eine leichte Tasse, werden nur wenige Einheiten aktiviert, beim schweren Kasten Wasser viele – abwechselnd, damit die Bewegung gleichmäßig bleibt.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-024","thema":"Q3.2","kapitel":"Muskel und motorische Einheit","q":"Welcher Zusammenhang besteht zwischen der Größe der motorischen Einheiten und der Feinmotorik eines Muskels?","a":"Je feinmotorischer ein Muskel, desto weniger Fasern pro motorischer Einheit:\n• fein abgestuft: ca. 5–10 Fasern (z. B. Augenmuskel)\n• grob abgestuft: > 1.000 Fasern (z. B. Oberarmbeuger), viel Kraft","e":"Kleine Einheiten erlauben eine sehr genaue Abstufung, bringen aber wenig Kraft pro Einheit; große entwickeln viel Spannung, sind aber schlecht fein steuerbar. Zahlen (Tab. 3.2): äußerer Augenmuskel ca. 2.000 Einheiten mit ca. 20.000 Fasern (≈ 10 pro Einheit), Oberarmbeuger ca. 1.000 Einheiten mit ca. 1.000.000 Fasern (≈ 1.000 pro Einheit). Beispiel: Der Augenmuskel muss den Blick millimetergenau ausrichten, der Bizeps soll vor allem Kraft bringen.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-025","thema":"Q3.2","kapitel":"Reflexe, Stütz- und Zielmotorik","q":"Definiere den Reflex und nenne die fünf Komponenten des Reflexbogens.","a":"Reflex: festgelegte, unwillkürliche motorische Reaktion auf einen Reiz (einfachster koordinierter motorischer Prozess).\n1. Rezeptor\n2. afferente Fasern\n3. Reflexzentrum (z. B. Rückenmark)\n4. efferente Fasern\n5. Effektor (Muskel)","e":"Reflexe erledigen schnelle Routineaufgaben, die kein Nachdenken erfordern dürfen; sie laufen ohne Umweg über das Bewusstsein und sind deshalb extrem schnell. Beispiele: Lidschlussreflex bei einem heranfliegenden Ball, Patellarsehnenreflex beim Schlag unter die Kniescheibe, Beugereflex beim Berühren einer heißen Herdplatte.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-026","thema":"Q3.2","kapitel":"Reflexe, Stütz- und Zielmotorik","q":"Erkläre Funktion und Ablauf des Dehnungsreflexes.","a":"• Funktion: Längenstabilisierung des Muskels\n• Ablauf: Dehnung → Muskelspindeln → afferent zum Rückenmark → efferent → derselbe Muskel kontrahiert","e":"Der Dehnungsreflex ist ein Eigenreflex: Reiz und Reaktion liegen im selben Muskel. Er ist in der Sportmotorik besonders wichtig, z. B. für die Haltung und den Dehnungs-Verkürzungs-Zyklus. Beispiel: Beim Patellarsehnenreflex wird der Oberschenkelstrecker durch den Schlag kurz gedehnt und zieht sich sofort zusammen – der Unterschenkel schnellt nach vorne.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-027","thema":"Q3.2","kapitel":"Reflexe, Stütz- und Zielmotorik","q":"Erläutere den kombinierten Beuge- und gekreuzten Streckreflex.","a":"• Beugereflex (gleiche Seite): Beuger kontrahieren, Strecker gehemmt → Bein weg vom Schmerzreiz\n• Gekreuzter Streckreflex (Gegenseite): Strecker aktiviert, Beuger gehemmt → anderes Bein sichert den Stand","e":"Der Schutzreflex verschlechtert die Standsicherheit, deshalb stabilisiert die Streckung des anderen Beins sofort den Stand. Zwei Reflexe arbeiten als Team: Einer schützt, der andere hält dich aufrecht. Beispiel: Tritt man am Strand auf eine Scherbe, zuckt der Fuß hoch und das andere Bein streckt sich, damit man nicht umfällt.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-028","thema":"Q3.2","kapitel":"Reflexe, Stütz- und Zielmotorik","q":"Was versteht man unter Stützmotorik?","a":"Teil der Motorik, der durch ständige Regulation von Bein- und Rumpfmuskulatur die aufrechte Haltung und das Gleichgewicht sichert; bereitet Zielbewegungen vor.","e":"Bei Haltebewegungen wirken verschiedene Muskelgruppen zusammen. Die Stützmotorik arbeitet meist unbemerkt im Hintergrund und sorgt für eine vorbereitende Haltungsanpassung. Beispiel: Will man in den Zehenstand gehen, reicht es nicht, die Wade anzuspannen – sonst kippt man nach hinten. Vorher verlagert die Schienbeinmuskulatur den Körper leicht nach vorne über die Fußballen.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-029","thema":"Q3.2","kapitel":"Reflexe, Stütz- und Zielmotorik","q":"Was versteht man unter Zielmotorik und wie unterscheidet sie sich von der Stützmotorik?","a":"• Zielmotorik: steuert geplante, willkürliche Bewegungen (beansprucht viele Hirnareale)\n• Stützmotorik: sichert Haltung und Gleichgewicht","e":"Planung, Ausführung und Kontrolle zielgerichteter Bewegungen sind komplex. Stützmotorik ist das Fundament, Zielmotorik das, was man darauf baut. Beispiel: Beim Torschuss hält die Stützmotorik das Standbein und den Rumpf stabil, die Zielmotorik steuert den Schussbein-Schwung zum Ball.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-030","thema":"Q3.2","kapitel":"Reflexe, Stütz- und Zielmotorik","q":"Fasse die Teilsysteme der motorischen Systeme mit ihrer jeweiligen Hauptfunktion zusammen.","a":"• Muskelkontraktion → Körperbewegungen erzeugen\n• Reflexe → schnelle Routineaufgaben\n• Stützmotorik → Gleichgewichtssicherung\n• Zielmotorik → geplante Bewegungen steuern","e":"Insgesamt sorgen motorische Systeme für Starten und Ausführen einer Bewegung sowie für Überwachung, Bewertung und Speicherung des Ergebnisses (Tab. 3.4). Beispiel: Beim Volleyballaufschlag erzeugen Muskelkontraktionen die Bewegung, die Stützmotorik hält den Körper im Gleichgewicht, die Zielmotorik steuert den Schlag, und ein Reflex lässt dich blinzeln, wenn dir Staub ins Auge fliegt.","quelle":"L03.2","typ":"kern"},{"id":"q3.2-031","thema":"Q3.2","kapitel":"Reflexe, Stütz- und Zielmotorik","q":"Welche Muskulatur und welche Analysatoren sichern das Gleichgewicht beim einbeinigen Stand bzw. bei der Standwaage?","a":"• Muskeln: Fuß- und Unterschenkelmuskulatur, Oberschenkel- und Gesäßmuskulatur (v. a. Gluteus medius), Rumpfmuskulatur\n• Analysatoren: vestibulär, kinästhetisch, taktil, optisch","e":"Wade, Schienbeinmuskel und Peroneusmuskeln regeln ständig die Lage über dem Fuß; der Gluteus medius verhindert das seitliche Abkippen des Beckens; Rücken- und Bauchmuskeln halten bei der Standwaage Rumpf und Spielbein waagerecht. Die Analysatoren melden Lage, Gelenkstellung, Druck an der Fußsohle und einen Fixpunkt; der kinästhetische verbindet sie. Beispiel: Schließt man bei der Standwaage die Augen, fällt der optische Analysator weg und man wackelt sofort stärker.","quelle":"L03.4","typ":"kern"},{"id":"q3.2-032","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Erkläre den Unterschied zwischen Steuerung (open loop) und Regelung (closed loop) von Bewegungen.","a":"• Steuerung (open loop): Ablauf nach festem Programm ohne Rückmeldung; schnelle Bewegungen (< ca. 150–200 ms)\n• Regelung (closed loop): laufender Soll-Ist-Vergleich mit Korrektur; langsame, genaue Bewegungen","e":"Bei ballistischen Bewegungen bleibt für Korrekturen keine Zeit. Im Sport wirken meist beide zusammen: Grobe Abläufe werden programmgesteuert, Feinanpassungen geregelt. Steuerung ist wie ein abgeschossener Pfeil, Regelung wie Autofahren mit ständigem Nachlenken. Beispiel: Ein Boxjab wird gesteuert, das Balancieren auf einem Schwebebalken wird geregelt.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-033","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Nenne die Elemente eines Regelkreises und übertrage sie auf die menschliche Bewegungsregulation.","a":"• Regler: ZNS\n• Sollwert: Bewegungsziel/-programm\n• Stellglied: Muskulatur\n• Stellgröße: efferente Impulse\n• Regelgröße: ablaufende Bewegung\n• Messfühler: Rezeptoren/Analysatoren\n• Istwert: afferente Rückmeldung\n• Störgrößen: z. B. Gegner, Wind, Ermüdung","e":"Der Regler vergleicht Soll- und Istwert und korrigiert bei Abweichung. Das Modell stammt aus der Technik (z. B. Heizungsthermostat). Beispiel: Ein Radfahrer will geradeaus fahren (Sollwert), eine Windböe (Störgröße) drückt ihn zur Seite, Gleichgewichtsorgan und Augen melden die Abweichung (Istwert), das Gehirn korrigiert über Lenk- und Rumpfbewegungen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-034","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Beschreibe das Modell der Bewegungskoordination (Regelkreismodell) nach Meinel/Schnabel.","a":"1. Afferenzsynthese (Informationen + Erfahrung + Ziel)\n2. Programmierung mit Antizipation (Sollwert)\n3. Efferenzsynthese (Impulse an Muskeln, Efferenzkopie)\n4. Bewegungsausführung (Störgrößen)\n5. Reafferenz (innere/äußere Rückmeldung)\n6. Soll-Ist-Vergleich → Korrektur","e":"Bei der Afferenzsynthese werden Informationen der Analysatoren mit Bewegungserfahrung und Motivation zusammengeführt. Die Efferenzkopie bleibt im ZNS als Vergleichswert. Die Rückmeldung läuft über innere (kinästhetisch, vestibulär, taktil) und äußere (optisch, akustisch) Kanäle; Abweichungen korrigieren das laufende Programm oder werden für die nächste Ausführung gespeichert. Beispiel: Beim Basketballwurf erwartet der Spieler einen Treffer. Fühlt er, dass die Hand zu kräftig war, und sieht den Ball auf den Ring prallen, korrigiert er den nächsten Wurf.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-035","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Was versteht man unter der Afferenzsynthese?","a":"Erste Phase der Bewegungsregulation (Anochin; Meinel/Schnabel): Zusammenführung von aktuellen Informationen (Analysatoren), Bewegungserfahrung und Ziel/Motivation vor der Bewegung.","e":"Ergebnis ist die Entscheidung, welche Bewegung wie ausgeführt wird; sie ist Grundlage für Programmierung und Antizipation. Bevor man handelt, verschafft sich das Gehirn ein Gesamtbild. Beispiel: Ein Handballer vor dem Wurf erfasst Torhüterposition, Abwehr, eigene Körperlage und erinnert sich, was gegen diesen Torwart schon funktioniert hat – erst dann wird der Wurf geplant.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-036","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Was ist eine Efferenzkopie und welche Funktion hat sie?","a":"• Kopie der motorischen Befehle, die im ZNS abgelegt wird\n• Dient als Sollwert: Vergleich mit den Reafferenzen → bei Abweichung Korrektur\n• Unterscheidung selbst erzeugter von fremden Reizen","e":"Die Efferenzkopie ist die Erwartung, wie sich die Bewegung anfühlen und welches Ergebnis sie haben soll. Stimmen Rückmeldung und Kopie überein, ist die Bewegung korrekt. Sie ist wie die Kopie einer Bestellung, mit der man die Lieferung kontrolliert. Beispiel: Ein Turner, der einen Salto startet, erwartet ein bestimmtes Drehgefühl. Fühlt sich die Drehung zu langsam an, öffnet er nicht zu früh, sondern bleibt länger gehockt.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-037","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Erläutere das Reafferenzprinzip (von Holst/Mittelstaedt).","a":"• ZNS sendet Efferenzen und speichert eine Efferenzkopie\n• Rückmeldungen der eigenen Bewegung (Reafferenzen) werden mit ihr verglichen\n• Übereinstimmung → Bewegung wie geplant; Abweichung (Exafferenz) → Korrektur","e":"Formuliert von Erich von Holst und Horst Mittelstaedt (1950). Exafferenzen sind Rückmeldungen durch äußere Einwirkungen; sie werden an höhere Zentren gemeldet. Das Prinzip ist Grundlage der Bewegungsregulation und des Bewegungslernens. Beispiel: Bewegst du die Augen, scheint die Welt nicht zu wackeln, weil das Gehirn die selbst erzeugte Bildverschiebung erwartet. Wirst du beim Laufen geschubst (Exafferenz), merkt das Gehirn sofort die Abweichung und korrigiert.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-038","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Unterscheide Reafferenzen und Exafferenzen.","a":"• Reafferenzen: Rückmeldungen durch die eigene Bewegung\n• Exafferenzen: Rückmeldungen durch äußere Ereignisse (Umwelt, Störungen)","e":"Durch den Vergleich mit der Efferenzkopie kann das ZNS beide Anteile trennen. Re- heißt „zurück“: Was meine Bewegung zurückmeldet; Ex- heißt „von außen“. Beispiel: Spürt ein Schwimmer den Wasserdruck an der Hand bei seinem Zug, ist das Reafferenz. Trifft ihn eine Welle, ist das Exafferenz.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-039","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Welche Formen der Rückmeldung (Feedback) unterscheidet man in der Bewegungsregulation?","a":"• Innere (intrinsische) Rückmeldung: aus dem eigenen Körper\n• Äußere (extrinsische): von außen\n  – KR: Knowledge of Result (Ergebnis)\n  – KP: Knowledge of Performance (Verlauf)\n• Zeitpunkt: begleitend oder nachträglich","e":"Innere Rückmeldung kommt über kinästhetischen, vestibulären und taktilen Analysator sowie die eigene Wahrnehmung der Bewegung; äußere z. B. über Trainer, Video oder Messwerte. Rückmeldungen schließen den Regelkreis und ermöglichen Korrektur und Lernen. Beispiel: Ein Speerwerfer spürt selbst, dass der Abwurf „hakte“ (innere Rückmeldung), sieht die Weite von 45 m (KR) und hört vom Trainer, dass sein Wurfarm zu früh kam (KP).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-040","thema":"Q3.2","kapitel":"Bewegungssteuerung und Regelkreis","q":"Warum können sehr schnelle Bewegungen nicht während ihrer Ausführung korrigiert werden?","a":"Die Rückkopplung (Rezeptor → ZNS → Muskel) dauert mindestens ca. 150–200 ms; kürzere ballistische Bewegungen laufen programmgesteuert (open loop) und sind erst bei der nächsten Ausführung korrigierbar.","e":"Visuelle Rückmeldungen dauern eher noch länger. Deshalb ist eine präzise Vorprogrammierung (Antizipation) wichtig. Unbewusste Reflexkorrekturen auf Rückenmarksebene sind schneller (ca. 30–50 ms), aber nur begrenzt anpassbar. Beispiel: Ein Tischtennis-Topspin dauert nur Sekundenbruchteile – merkt man den Fehler, ist der Ball schon unterwegs. Korrigieren kann man erst beim nächsten Schlag.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-041","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Vergleiche kognitive und systemdynamische Ansätze der motorischen Kontrolle.","a":"• Kognitiv: Informationsverarbeitung (Computermetapher); Kontrolle durch generalisierte motorische Programme (3 Invarianten, 3 Parameter)\n• Systemdynamisch: Selbstorganisation (Emergenz); Lernen durch veränderte Randbedingungen (Constraints), keine gespeicherten Programme","e":"Der kognitive Ansatz sagt: Im Kopf liegt ein Plan. Der dynamische sagt: Die Ordnung entsteht aus dem Zusammenspiel von Körper, Aufgabe und Umwelt. Beispiel: Der Wurf aus verschiedenen Distanzen lässt sich gut mit einem GMP erklären, der automatische Wechsel von Gehen zu Laufen eher durch Selbstorganisation.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-042","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Definiere das generalisierte motorische Programm (GMP) nach Schmidt.","a":"Programm, das eine ganze Klasse von Bewegungen steuert (Schmidt, 1975); gekennzeichnet durch konstante Invarianten und situativ aufgeschaltete variable Parameter.","e":"Vorteil: Das Gedächtnis muss nicht für jede Variante ein eigenes Programm speichern (Speicherproblem), und neue Varianten können ausgeführt werden (Neuigkeitsproblem). Ein GMP ist wie eine Grundmelodie, die man schneller, langsamer, lauter oder leiser spielen kann. Beispiel: Alle Oberarmwürfe – ob leichter Pass oder harter Schlagwurf – können von einem GMP gesteuert werden; die Grundstruktur bleibt gleich.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-043","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Nenne und erläutere die drei Invarianten eines GMP.","a":"• Reihenfolge der Teilbewegungen (order of events)\n• Relatives Timing: prozentuale Zeitanteile der Phasen (phasing)\n• Relatives Kraftverhältnis der Teilbewegungen (relative force)","e":"Invarianten bleiben bei allen Bewegungen der Klasse gleich – auch wenn sich die Gesamtdauer ändert, bleiben die Zeitanteile der Phasen gleich. Sie sind die „Melodie“ einer Bewegung. Beispiel Positionswurf: Erst Stoßphase, dann Handgelenkswurf (order of events); das Zeitverhältnis von Stoß- und Wurfphase bleibt gleich (phasing); das Verhältnis von Stoß- zu Wurfkraft bleibt gleich (relative force) – egal ob aus 3 oder 6 Metern.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-044","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Nenne und erläutere die drei variablen Parameter eines GMP.","a":"• Gesamtdauer (overall duration): schneller/langsamer\n• Gesamtkraft (overall force): kräftiger/schwächer\n• Muskelauswahl (muscle selection): andere Muskeln/Gliedmaßen","e":"Parameter werden je nach Situation aufgeschaltet – sie sind die Regler, mit denen man das Programm anpasst. Beispiel Basketball: Für einen weiteren Wurf wird die overall force erhöht, eventuell unterstützt durch stärkeres Nach-vorne-Drücken der Schulter (muscle selection). Auch dass man seinen Namen mit der Hand oder mit dem Fuß in den Sand schreiben kann, zeigt die Muskelauswahl.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-045","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Erläutere das GMP mithilfe der Schallplatten-Analogie nach Schmidt.","a":"• Schallplatte = GMP, Lautsprecher = Muskeln\n• Melodie = Invarianten\n• Lautstärke = overall force\n• Tempo = overall duration\n• Ansteuern einer Box = muscle selection","e":"Die Analogie hilft, Invarianten und Parameter auseinanderzuhalten: Die Melodie bleibt, die Einstellung am Verstärker ändert sich. Die Lautsprecher setzen das Programm in wahrnehmbare Bewegung um. Beispiel: Ein Lied klingt auch leise oder schneller abgespielt immer noch wie dasselbe Lied – so bleibt ein Sprungwurf ein Sprungwurf, egal wie kraftvoll.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-046","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Erkläre am Beispiel des Basketball-Positionswurfs, wie ein GMP Würfe aus verschiedenen Entfernungen steuert.","a":"• Ein GMP für alle Druckwürfe\n• Parameter angepasst: mehr overall force, ggf. Schulter (muscle selection)\n• Invarianten konstant: Stoß- vor Wurfphase, gleiches Zeit- und Kraftverhältnis","e":"Die Stoßphase überträgt den Impuls von unten nach oben, in der Wurfphase drückt das Handgelenk nach. Beim Sprungwurf entfällt der Kraftstoß der Beine in Abwurfrichtung weitgehend; das gleiche Arm-Hand-GMP erzeugt dann einen stärkeren Impuls. So erklärt die Theorie, warum man aus nie geübten Entfernungen treffen kann. Beispiel: Wer Freiwürfe und Dreier trainiert hat, trifft auch aus 5,5 m, weil nur der Kraftparameter neu eingestellt werden muss.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-047","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Wie kann mit dem GMP die Ausführung neuer Bewegungen erklärt werden?","a":"Gehört die neue Bewegung zur Klasse eines vorhandenen GMP, liefert dieses die Invarianten; nur die Parameter (Dauer, Kraft, Muskelauswahl) werden neu gewählt.","e":"Die Bewegung muss also nicht komplett neu programmiert werden. Methodisch heißt das: erst die Invarianten (Grundstruktur) lernen, dann durch Variation der Parameter das Programm generalisieren (variables Üben). Beispiel: Wer den Schlagwurf im Handball beherrscht, kann schnell den Speerwurf oder den Schlagball-Weitwurf ausführen, weil die Grundstruktur des Oberarmwurfs gleich ist und nur Kraft, Tempo und Muskelauswahl angepasst werden.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-048","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Welche Befunde sprechen für selbstorganisierte (emergente) Bewegungen, die nicht durch motorische Programme erklärbar sind?","a":"• Pendelbewegung des fallengelassenen Arms (Pendelgesetze)\n• Patellarsehnenreflex\n• Katzen mit durchtrenntem Hirnstamm koordinieren Schritte\n• Spontaner Übergang Gehen ↔ Laufen","e":"Der fallengelassene Arm lässt sich besser physikalisch als mit Programmen beschreiben; das Hochschnellen beim Patellarsehnenreflex wirkt nicht programmiert. Beim Gehen-Laufen-Wechsel liegen die Übergangsgeschwindigkeiten je nach Richtung verschieden. Nicht jede koordinierte Bewegung braucht einen „Plan“ im Großhirn. Beispiel: Die Katze läuft auch ohne Verbindung zum Großhirn – die Bewegungsmuster entstehen im Rückenmark und aus dem Zusammenspiel von Körper und Umwelt.","quelle":"L03.3","typ":"kern"},{"id":"q3.2-049","thema":"Q3.2","kapitel":"Kognitive und dynamische Systeme","q":"Analysiere den Korbleger aus dem Dribbling nach Invarianten und Parametern eines GMP (Teilablauf nach dem letzten Dribbling).","a":"Invarianten:\n• order of events: Ballaufnahme → langer 1. Schritt → kurzer 2. Schritt → Absprung → Ablage\n• phasing: Rhythmus „lang–kurz–hoch“\n• relative force: Absprung- zu Ablagekraft\nParameter: Tempo, Kraft (Abstand), Seite/Ablageart","e":"Zu den Parametern im Detail: overall duration je nach Dribbeltempo und Gegnerdruck; overall force je nach Abstand und Höhe; muscle selection beim Korbleger links oder rechts (andere Hand, anderes Sprungbein) bzw. Unter- oder Überhandablage. Der zweite Schritt ist ein Stemmschritt, beim Absprung geht das Schwungbein hoch. Beispiel: Ob ein Spieler im Fastbreak mit Vollgas oder im Halbfeld langsam zum Korb zieht – die Schrittfolge „lang-kurz-hoch“ bleibt gleich, nur Tempo und Kraft ändern sich.","quelle":"L03.4","typ":"kern"},{"id":"q3.2-050","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Definiere den Begriff Antizipation im Sport.","a":"Gedankliche Vorwegnahme zukünftiger Ereignisse, Handlungen und Bewegungsabläufe bzw. ihrer Ergebnisse auf Basis von Hinweisreizen und Erfahrung.\n• Selbstantizipation\n• Fremdantizipation","e":"Lateinisch anticipare = vorwegnehmen. Ziel ist, rechtzeitig und angemessen zu handeln, Zeit zu gewinnen und die eigene Bewegung optimal vorzubereiten. Selbstantizipation betrifft die eigene Bewegung, Fremdantizipation das Verhalten anderer und Flugbahnen von Objekten. Beispiel: Ein Volleyballblocker springt nicht erst, wenn der Angreifer schlägt, sondern sobald er an Anlauf und Zuspiel erkennt, wohin der Angriff geht.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-051","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Erläutere den Begriff Selbstantizipation.","a":"Vorwegnahme des eigenen Bewegungsablaufs und -ergebnisses (Sollwert der Programmierung); bezogen auf Gesamtablauf/Ergebnis, nachfolgende Bewegungsphasen und erwartete Bewegungsempfindungen.","e":"Vor und während der Bewegung bildet man ein Bild davon, wie sie verlaufen soll. Die Vorbereitungsphase ist so auf die Hauptphase ausgerichtet (Bewegungskopplung). Ohne Selbstantizipation gäbe es keinen Soll-Ist-Vergleich und keine zielgerichtete Korrektur. Beispiel: Ein Weitspringer stellt seine letzten Anlaufschritte (kurzer vorletzter Schritt, Senken des KSP) bereits auf den kommenden Absprung ein.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-052","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Erläutere den Begriff Fremdantizipation.","a":"Vorwegnahme von Handlungen anderer (Gegner, Mitspieler) sowie von Objektbewegungen (z. B. Ballflug) anhand von Hinweisreizen und Erfahrung; v. a. in Spiel-, Rückschlag- und Zweikampfsportarten.","e":"Hinweisreize sind z. B. Körperhaltung, Ausholbewegung, Blickrichtung oder der Ballflug; dazu kommt das Wissen über typisches Verhalten. Die eigene Handlung wird dann auf das vorweggenommene Geschehen abgestimmt – eine Art „Gedankenlesen“ anhand von Körpersprache. Beispiel: Ein Elfmeter-Torwart achtet auf Anlaufwinkel, Standbein und Hüftstellung des Schützen, um die Ecke vorherzusagen und früh genug abzuspringen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-053","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Unterscheide Ereignisantizipation und Zeitantizipation.","a":"• Ereignisantizipation: WAS bzw. WO etwas geschieht\n• Zeitantizipation: WANN es geschieht (Timing)","e":"Für eine erfolgreiche Handlung müssen meist beide zusammenkommen: das richtige Ereignis zum richtigen Zeitpunkt. Zeitantizipation ist z. B. beim Sprintstart (Zeit zwischen Kommando und Schuss) oder beim Abfangen eines Balls zentral. Beispiel: Ein Tennisspieler erkennt am Ballwurf des Gegners, dass ein Kick-Aufschlag nach außen kommt (Ereignis), und muss den Treffpunkt zeitlich passend erwarten, um rechtzeitig den Split-Step zu machen (Zeit).","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-054","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Welche Rolle spielt die Antizipation in der Bewegungssteuerung (Regelkreismodell)?","a":"• Bei der Programmierung werden Verlauf und Ergebnis antizipiert → Sollwert für den Soll-Ist-Vergleich\n• Ermöglicht rechtzeitige Vorbereitung (z. B. Haltungsanpassung)\n• Ersetzt bei sehr schnellen Bewegungen die fehlende Korrektur","e":"Im Regelkreismodell (Meinel/Schnabel) bildet die Antizipation zusammen mit der Efferenzkopie den Sollwert; nur so können die Reafferenzen verglichen und Fehler korrigiert werden. Antizipation ist also das „Soll“ im Soll-Ist-Vergleich. Beispiel: Wer im Zehenstand den Körper schon vor dem Hochdrücken nach vorne verlagert, antizipiert die Folgen für das Gleichgewicht – sonst würde er nach hinten kippen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-055","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Warum ist Antizipation in Sportspielen so wichtig?","a":"• Zeitdruck: reine Reaktion käme oft zu spät → Zeitgewinn\n• Weniger wahrscheinliche Alternativen (Hick'sches Gesetz)\n• Bessere Entscheidungen, Stellungsspiel, Abstimmung mit Mitspielern","e":"Viele Spielsituationen laufen schneller ab, als die Reaktionszeit es erlaubt. Antizipation ermöglicht frühzeitiges Abfangen, Blocken, Abwehren sowie abgestimmte Pass- und Laufwege. Gegner versuchen deshalb, mit Finten falsche Antizipationen auszulösen. Beispiel: Ein Innenverteidiger, der den Steilpass schon am Blick und an der Körperstellung des Spielmachers erkennt, startet früher und erreicht den Ball vor dem Stürmer.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-056","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Worin unterscheiden sich Experten und Anfänger in ihrer Antizipationsleistung?","a":"Experten:\n• nutzen frühere, relevantere Hinweisreize\n• haben zielgerichteteres Blickverhalten\n• haben mehr Wissen über Wahrscheinlichkeiten\n→ antizipieren früher und genauer","e":"Anfänger achten eher auf späte Informationen wie den Ball selbst; Experten fixieren seltener, aber länger aussagekräftige Körperbereiche (Hüfte, Schulter, Schläger). Die Reaktionszeit selbst ist bei Profis kaum kürzer – sie wissen nur früher, was kommt. Antizipation ist sportartspezifisch und erfahrungsabhängig, also trainierbar. Beispiel: Ein Profi-Badmintonspieler erkennt an der Schlägerhaltung des Gegners, ob ein Drop oder ein Clear kommt, ein Anfänger sieht es erst am Ballflug.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-057","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Welcher Zusammenhang besteht zwischen Antizipation und Täuschungshandlungen (Finten)?","a":"Eine Finte soll beim Gegner eine falsche Fremdantizipation auslösen: Hinweisreize einer Handlung zeigen, dann eine andere ausführen; der Gegner muss seine Bewegung hemmen und umstellen (Zeitverlust).","e":"Das Umstellen erfordert Umstellungsfähigkeit (Inhibition). Je besser ein Gegner antizipiert, desto wirksamer, aber auch riskanter kann eine Finte sein; gute Spieler lernen, echte von falschen Hinweisreizen zu unterscheiden. Beispiel: Ein Handballer täuscht einen Wurf an, der Torwart geht in die Bewegung – dann legt der Angreifer den Ball in die andere Ecke.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-058","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Wie kann die Reaktionsschnelligkeit nach der Reaktionsmethode verbessert werden und welche Rolle spielt die Antizipation dabei?","a":"• Reaktionsschnelligkeit nur begrenzt trainierbar (angeboren)\n• Ansatzpunkte: Technik bis in die Beschleunigung einschleifen; Antizipation (Zeitwahrnehmung) schulen, z. B. Starts nach variablen Zeitintervallen","e":"Die Begrenzung ergibt sich, weil Reaktionsschnelligkeit an angeborene Komponenten der neuronalen Steuerung gebunden ist (Grosser/Zintl). Beim Starttraining verbessern sich Konzentration (sensorischer Anteil) und optimale Muskelvorspannung (motorischer Anteil). Beispiel: Beim Sprintstart kommt der Schuss nach „Fertig“ nach unterschiedlich langen Pausen – so lernt der Sprinter, den Zeitpunkt besser einzuschätzen und optimal vorgespannt zu warten.","quelle":"L14.2","typ":"kern"},{"id":"q3.2-059","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Was versteht man unter der Antizipationsmethode (Steinhöfer) im Sportspiel?","a":"Spielspezifisches Reaktions- und Antizipationstraining komplexer Handlungen unter Zeitdruck im Rahmen des Technik- und Taktiktrainings (Steinhöfer).","e":"Allgemeine Reaktionsschulung reicht für Sportspieler nicht aus, weil sie Spielsituationen lesen müssen. Häufig werden mehrere Reaktionshandlungen hintereinander trainiert, um spätere Wahlreaktionen auf unterschiedliche Signale vorzubereiten. Beispiele: Feldabwehr im Volleyball, Schussabwehr beim Torwart, Reaktionsleistungen im Basketball im 1:1.","quelle":"L14.2","typ":"kern"},{"id":"q3.2-060","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Wie kann die Antizipationsfähigkeit trainiert werden?","a":"• Spielnahe Übungen mit echten Gegnern\n• Aufmerksamkeit auf relevante Hinweisreize lenken\n• Video-/Okklusionstraining\n• Zeitintervalle variieren\n• Gegner- und Spielanalyse\n• Zeit- und Situationsdruck erhöhen (KAR)\n• viel Spielerfahrung","e":"Spielnah heißt z. B. 1:1 oder Über- und Unterzahlspiele statt reiner Signalreaktion. Beim Okklusionstraining wird ein Video kurz vor dem entscheidenden Moment gestoppt und der Sportler sagt den Ausgang vorher. Antizipation ist stark erfahrungsabhängig. Beispiel: Torhüter schauen Elfmetervideos, die beim Ballkontakt abbrechen, und tippen auf die Ecke – so lernen sie, auf Standbein und Hüfte zu achten.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-061","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Welche Beziehung besteht zwischen Antizipation und den koordinativen Fähigkeiten?","a":"Antizipation ist Grundlage von:\n• Reaktionsfähigkeit\n• Orientierungsfähigkeit\n• Umstellungsfähigkeit\n• Kopplungs- und Rhythmisierungsfähigkeit (Selbstantizipation)","e":"Reaktion wird durch Vorwegnahme schneller, Orientierung braucht die Vorhersage künftiger Positionen von Körper, Ball und Gegnern, Umstellung das frühe Erkennen von Situationsänderungen. Manche Modelle nennen Antizipation als eigene koordinative Fähigkeit. Voraussetzung für Fremdantizipation sind gute Analysatoren, v. a. der optische. Beispiel: Beim Kopfball (Orientierungsfähigkeit) muss man den Ballflug vorhersehen, um im richtigen Moment am richtigen Ort abzuspringen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-062","thema":"Q3.2","kapitel":"Bewegungsantizipation","q":"Welche Risiken bzw. Grenzen hat die Antizipation?","a":"• Beruht auf Wahrscheinlichkeiten → Fehlantizipation möglich\n• Umstellen kostet mehr Zeit als reine Reaktion (Finten)\n• Zu frühes Handeln kann ausgenutzt werden\n• Teils regelwidrig (Fehlstart < 100 ms)","e":"Optimal ist ein Kompromiss zwischen früher Antizipation und Sicherheit. Wer zu früh rät, wird leicht ausgetrickst. Beispiel: Springt ein Elfmeter-Torwart sehr früh in die linke Ecke, kann der Schütze den Ball einfach in die rechte schieben.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q3.2-063","thema":"Q3.2","kapitel":"Koordination und Technik","q":"Woher stammt der Begriff Koordination und wie definieren Hollmann/Strüder Koordination aus sportmedizinischer Sicht?","a":"• Herkunft: lat. „cum ordo“ = „mit Ordnung“\n• Hollmann/Strüder: Zusammenwirken von ZNS und Skelettmuskulatur innerhalb eines gezielten Bewegungsablaufs","e":"Koordination bringt „Ordnung“ in das Zusammenspiel von Nerven und Muskeln (Herleitung nach Vele). Beispiel: Beim Seilspringen müssen Arme, Beine und Sprungrhythmus genau aufeinander abgestimmt sein – das leistet das Zusammenwirken von ZNS und Muskulatur.","quelle":"L04.1","typ":"kern"},{"id":"q3.2-064","thema":"Q3.2","kapitel":"Koordination und Technik","q":"Nenne die Definition von Koordination als Leistungskomponente (Hohmann et al.) und die Definition für Sportspiele (Voigt/Westphal).","a":"• Hohmann et al.: Sammelbezeichnung für koordinative Fähigkeiten\n• Voigt/Westphal (Sportspiel): Zusammenwirken von Informationsaufnahme, Verarbeitung, nervöser Steuerung und muskulärer Ausführung","e":"Die Sportspiel-Definition entspricht dem EVA-Prinzip: Wahrnehmen, Denken, Steuern, Ausführen. Beispiel: Ein Point Guard sieht den freien Mitspieler (Informationsaufnahme), entscheidet sich für den Pass (Verarbeitung), das Gehirn sendet Befehle (Steuerung) und er passt (Ausführung).","quelle":"L04.1","typ":"kern"},{"id":"q3.2-065","thema":"Q3.2","kapitel":"Koordination und Technik","q":"Erkläre am Beispiel der Fahrzeuglenkung, worin die Bedeutung der Koordination liegt.","a":"• Vier unabhängig lenkbare Räder wären kaum beherrschbar\n• Lösung: Hinterräder starr, Vorderräder gekoppelt → weniger Freiheitsgrade\n• Koordination = Freiheitsgrade des Körpers durch Kopplung beherrschbar machen","e":"Schon Geradeausfahren und erst recht Rückwärtseinparken wären mit vier frei lenkbaren Rädern extrem schwierig. Übertragen auf den Körper ist das Bernsteins Freiheitsgradeproblem: Koordination ist im Kern Freiheitsgrad-Management. Beispiel: Anfänger beim Inlineskaten halten Knie und Hüfte steif – sie reduzieren Freiheitsgrade, um die Bewegung überhaupt kontrollieren zu können.","quelle":"L04.1","typ":"kern"},{"id":"q3.2-066","thema":"Q3.2","kapitel":"Koordination und Technik","q":"Definiere die sportliche Technik und erläutere ihren Zusammenhang mit koordinativen Fähigkeiten.","a":"• Technik (Fertigkeit): konkrete Bewegungshandlung zur Lösung einer sporttypischen Bewegungsaufgabe (Bösing et al.)\n• Koordinative Fähigkeiten: allgemeine Leistungsvoraussetzungen für das Erlernen und Beherrschen von Techniken","e":"Eine Fertigkeit ist eine konkrete, erlernte Bewegung (z. B. Flop, Delfin), eine Fähigkeit eine übergreifende Voraussetzung (z. B. Rhythmisierungs-, Kopplungsfähigkeit). Fähigkeiten sind das Fundament, Fertigkeiten das Haus darauf. Beispiel: Der Hochspringer braucht für den Flop-Anlauf Rhythmisierungsfähigkeit, Kugelstoßer und Delfinschwimmer brauchen Kopplungsfähigkeit, um Arm- und Beinbewegungen präzise zu verbinden.","quelle":"L04.1","typ":"kern"},{"id":"q3.2-067","thema":"Q3.2","kapitel":"Koordination und Technik","q":"Welche Arten von Modellen zur Bewegungskoordination unterscheidet man? Nenne jeweils ein Beispiel.","a":"• Fähigkeitsorientiert: Modell der koordinativen Fähigkeiten (Blume, Hirtz)\n• Fertigkeitsorientiert: KAR-Modell (Neumaier et al.)\n• Gemischt: Fähigkeits-Fertigkeits-Modell (Rostock & Zimmermann), Allgemeine Ballschule (Kröger & Roth)","e":"Fähigkeitsorientierte Modelle fragen: Welche allgemeinen Fähigkeiten hat der Sportler? Fertigkeitsorientierte fragen: Welche Anforderungen stellt eine konkrete Bewegungsaufgabe? Beispiel: Für den Basketballsprungwurf kann man nach beteiligten Fähigkeiten (Kopplung, Differenzierung) oder nach den Anforderungen (hoher Präzisions- und Zeitdruck) fragen.","quelle":"L04.1","typ":"kern"},{"id":"q3.2-068","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Nenne die sieben koordinativen Fähigkeiten im Modell der koordinativen Fähigkeiten.","a":"• Kopplungsfähigkeit\n• Differenzierungsfähigkeit\n• Gleichgewichtsfähigkeit\n• Orientierungsfähigkeit\n• Rhythmisierungsfähigkeit\n• Reaktionsfähigkeit\n• Umstellungsfähigkeit\n(Blume, Hirtz)","e":"Sie gelten als koordinative Leistungsvoraussetzungen für sportliche Fertigkeiten. Eselsbrücke: „KoDi GOR RU“. Beispiel: Ein Turner braucht vor allem Gleichgewicht, Orientierung und Differenzierung, ein Fußballer zusätzlich viel Reaktion und Umstellung.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-069","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Welche Grundannahmen und Bewertung kennzeichnen das Modell der koordinativen Fähigkeiten?","a":"• Frühe, vielseitige Schulung allgemeiner koordinativer Fähigkeiten als Basis für späteres Techniklernen (Transfer)\n• Bestes Lernalter 7–12 Jahre\n• Breit akzeptiert, aber wissenschaftlich umstritten (Steinhöfer)","e":"Das Modell ist im Schulsport, in der Grundausbildung und in der Übungsleiterausbildung verbreitet. Angezweifelt werden v. a. die Existenz allgemeiner Fähigkeiten und ihr Transfer. Die Idee: Wer allgemein gut koordiniert ist, lernt jede Sportart leichter – die Forschung zweifelt aber, ob Balancieren auf der Bank wirklich das Gleichgewicht beim Snowboarden verbessert. Beispiel: Im Grundschulsport werden trotzdem vielseitige Parcours mit Balancieren, Rollen und Werfen eingesetzt.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-070","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Wie lautet der Merksatz zur koordinativen Grundausbildung im Grundschulbereich?","a":"• Eine umfassende und vielseitig orientierte Grundausbildung im Grundschulbereich verlangt ein spielerisches Schulen vielfältiger Bewegungsformen,\n• die die breite Palette der koordinativen Fähigkeiten berücksichtigt.","e":"Kinder sollen möglichst viele verschiedene Bewegungen spielerisch erleben, statt früh nur eine Sportart zu üben. Beispiel: Fangspiele, Klettern, Balancieren, Werfen und Tanzen in einer Sportstunde fördern viele koordinative Fähigkeiten gleichzeitig.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-071","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Welche Funktion haben koordinative Fähigkeiten und in welcher Beziehung stehen sie zueinander und zu den konditionellen Fähigkeiten?","a":"• Funktion: Impulse eines Bewegungsablaufs zeitlich, in Stärke und Umfang abstimmen und an die richtigen Muskeln leiten\n• Wirken nie isoliert, sondern im Beziehungsgefüge\n• Oft mit konditionellen Fähigkeiten verbunden","e":"Entscheidend ist das Zusammenspiel der Fähigkeiten in der jeweiligen Fertigkeit bzw. Sportart. Beispiel Beweglichkeit: Sie hat konstitutionelle (Gelenkmobilität), energetisch-konditionelle (Muskelkraft) und koordinative Anteile (inter- und intramuskuläre Koordination). Beispiel: Ein Hürdenläufer braucht Rhythmisierungs- und Kopplungsfähigkeit, aber auch Beweglichkeit und Schnelligkeit, damit die Technik funktioniert.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-072","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Unterscheide intermuskuläre und intramuskuläre Koordination.","a":"• Intermuskulär: Zusammenspiel verschiedener Muskeln (Agonisten, Antagonisten, Synergisten)\n• Intramuskulär: Zusammenspiel innerhalb eines Muskels (Rekrutierung, Frequenzierung, Synchronisation)","e":"Intramuskulär geht es darum, wie viele motorische Einheiten gleichzeitig, wie hochfrequent und wie synchron aktiviert werden. Inter = zwischen den Muskeln, intra = innerhalb eines Muskels. Beispiel: Beim Kniebeugen müssen Oberschenkelstrecker und -beuger abgestimmt arbeiten (inter); für maximale Kraft muss der Quadrizeps möglichst viele motorische Einheiten gleichzeitig aktivieren (intra).","quelle":"L04.2","typ":"kern"},{"id":"q3.2-073","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Erläutere die Gliederung der koordinativen Fähigkeiten in Grundfähigkeiten nach Hirtz.","a":"• Steuerungsfähigkeit: Bewegungen genau steuern (Kopplung, Differenzierung, Gleichgewicht, Orientierung, Rhythmisierung)\n• Adaptionsfähigkeit: an wechselnde Bedingungen anpassen (Gleichgewicht, Orientierung, Rhythmisierung, Reaktion, Umstellung)\n• Motorische Lernfähigkeit (alle sieben)","e":"Gleichgewichts-, Orientierungs- und Rhythmisierungsfähigkeit gehören zu beiden Gruppen (Hirtz, 1985). Die Lernfähigkeit meint das sichere und schnelle Erlernen von Bewegungen. Steuern heißt genau ausführen, Anpassen heißt auf Veränderungen reagieren. Beispiel: Beim Kunstturnen dominiert die Steuerungsfähigkeit (geschlossene Fertigkeit), beim Skifahren im unbekannten Gelände die Adaptionsfähigkeit.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-074","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Definiere die Differenzierungsfähigkeit.","a":"Fähigkeit zur hohen Feinabstimmung einzelner Bewegungsphasen und Teilkörperbewegungen, die sich in großer Bewegungsgenauigkeit und -ökonomie zeigt.","e":"Grundlage ist v. a. die genaue Verarbeitung kinästhetischer Informationen, z. B. zur Dosierung von Kraft und Spannung. Differenzierung ist das „Fingerspitzengefühl“. Beispiele: Ballgefühl beim Lob im Tennis, Schneegefühl beim Skifahren, Wassergefühl beim Schwimmen.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-075","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Definiere die Reaktionsfähigkeit.","a":"Fähigkeit zur schnellen Einleitung und Ausführung zweckmäßiger motorischer Aktionen auf Signale (Einfach- und Wahlreaktionen).","e":"Signale können optisch, akustisch, taktil oder kinästhetisch sein. Entscheidend ist nicht nur die Schnelligkeit, sondern dass die Reaktion zweckmäßig ist – schnell und richtig auf ein Signal antworten. Beispiele: Antritte, Reaktion auf Täuschungen, Richtungswechsel, Sprints auf den Startschuss in der Leichtathletik.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-076","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Definiere die Kopplungsfähigkeit.","a":"• Fähigkeit, Teilkörperbewegungen bezüglich eines bestimmten Handlungsziels räumlich, zeitlich und dynamisch aufeinander abzustimmen.\n• Betrifft sowohl gleichzeitige (simultane) als auch aufeinanderfolgende (sukzessive) Teilbewegungen.","e":"Kopplung bedeutet: Arme, Beine und Rumpf arbeiten wie ein Zahnradgetriebe zusammen. Beispiele: Kraulschwimmen (Arm- und Beinschlag mit Atmung), Hochsprung (Anlauf und Absprung mit Armeinsatz), Sprungwurf.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-077","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Definiere die Orientierungsfähigkeit.","a":"Fähigkeit zur Bestimmung und zielangepassten Veränderung der Lage und Bewegung des Körpers in Raum und Zeit (bezogen auf Spielfeld, Geräte, Mitspieler, Gegner, Ball).","e":"Zur Orientierungsfähigkeit gehören auch Timing und peripheres Sehen. Orientierung heißt: Wo bin ich, wo ist der Ball, wo sind die anderen? Beispiele: Kopfball im Fußball, Kempa-Trick im Handball, Tipp-in im Basketball.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-078","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Definiere die Gleichgewichtsfähigkeit.","a":"Fähigkeit, den Körper im Gleichgewicht zu halten (statisch) bzw. während und nach Körperverlagerungen das Gleichgewicht beizubehalten oder wiederherzustellen (dynamisch).","e":"Beteiligt sind v. a. der vestibuläre, kinästhetische, taktile und optische Analysator. Gleichgewicht ist mehr als „nicht umfallen“ – es geht auch um schnelles Wiederherstellen. Beispiele: Balancieren, Einradfahren, Rebound im Basketball, Stoppen, Körperkontakt mit dem Gegner.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-079","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Definiere die Rhythmisierungsfähigkeit.","a":"• Fähigkeit, einen von außen vorgegebenen Rhythmus zu erfassen und motorisch umzusetzen,\n• sowie die Fähigkeit, einen verinnerlichten Rhythmus einer Bewegung in der eigenen Bewegungstätigkeit zu realisieren.","e":"Es gibt also einen fremden (z. B. Musik) und einen eigenen Rhythmus (z. B. Bewegungsrhythmus). Beispiele: Tanzsportarten, Ballett, Dribbling, Diskuswurf, Hürdenlauf (Dreierrhythmus).","quelle":"L04.2","typ":"kern"},{"id":"q3.2-080","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Definiere die Umstellungsfähigkeit.","a":"• Fähigkeit, während des Handlungsvollzugs das Handlungsprogramm veränderten Umgebungsbedingungen anzupassen\n• oder ein neues, adäquates Handlungsprogramm zu starten.\n• Die Veränderungen können vorhersehbar oder überraschend sein.","e":"Umstellung heißt: Plan B während der Bewegung. Beispiele: Kooperation mit Mitspielern in Mannschaftsspielen, Anpassung an das Verhalten des Gegners, z. B. wenn ein Pass abgefälscht wird und man noch im Lauf die Richtung ändern muss.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-081","thema":"Q3.2","kapitel":"Koordinative Fähigkeiten","q":"Warum liegt die sensible Phase für koordinative Fähigkeiten zwischen dem 7. und 12. Lebensjahr?","a":"• Koordinative Fähigkeiten müssen erlernt werden\n• 7–12 Jahre: beschleunigte Reifung von ZNS und Analysatoren + starkes Bewegungsbedürfnis\n• Verpasst man die Phase, ist späteres Lernen deutlich aufwendiger","e":"In dieser sensiblen Phase treffen biologische Reifungsprozesse und große Bewegungsfreude zusammen, deshalb spricht man vom „goldenen Lernalter“ – Kinder lernen Bewegungen oft auf Anhieb. Beispiel: Wer als Kind Inlineskaten oder Jonglieren lernt, tut sich viel leichter als jemand, der als Erwachsener damit beginnt.","quelle":"L04.2","typ":"kern"},{"id":"q3.2-082","thema":"Q3.2","kapitel":"KAR-Modell","q":"Beschreibe den Aufbau des Koordinations-Anforderungs-Regler-Modells (KAR-Modell) nach Neumaier.","a":"Fertigkeitsorientiertes Modell (Neumaier) zur Analyse koordinativer Anforderungen:\n• Informationsanforderungen: optisch, akustisch, taktil, kinästhetisch, vestibulär, Gleichgewicht\n• Druckbedingungen: Präzision, Zeit, Komplexität, Situation, Belastung\nJe ein Regler von niedrig bis hoch","e":"Die Informationsanforderungen betreffen die afferente Seite, also die Analysatoren; das Gleichgewicht gilt als integrative Anforderung mehrerer Analysatoren. Die Gesamtkonstellation aller Reglerstellungen ergibt das koordinative Anforderungsprofil einer Bewegungsaufgabe. Man kann sich das Modell wie ein Mischpult vorstellen. Beispiel: Ein Freiwurf hat einen hohen Präzisionsregler, aber einen niedrigen Zeitdruckregler.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-083","thema":"Q3.2","kapitel":"KAR-Modell","q":"Was beschreiben die Informationsanforderungen im KAR-Modell?","a":"Anforderungen an die Informationsaufnahme und -verarbeitung über die Analysatoren: optisch, akustisch, taktil, kinästhetisch, vestibulär sowie Gleichgewicht (integrativ).","e":"Gefragt wird: Welche Sinne braucht man für diese Aufgabe besonders? Das Gleichgewicht ist eine integrative Leistung mehrerer Analysatoren. Beispiel: Beim Tempodribbling im Fußball ist der optische Anteil mittel bis hoch (Gegner, Raum, Ball), der akustische dagegen gering.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-084","thema":"Q3.2","kapitel":"KAR-Modell","q":"Woraus ergeben sich die Druckbedingungen im KAR-Modell?","a":"Aus Zielstellung der Aufgabe, einzusetzenden Bewegungen sowie äußeren und inneren Ausführungsbedingungen.\nArten: Präzisions-, Zeit-, Komplexitäts-, Situations-, Belastungsdruck","e":"Die Druckbedingungen kennzeichnen, unter welchem „Druck“ eine Bewegung koordiniert werden muss; sie machen eine Bewegung schwerer, ohne die Bewegung selbst zu ändern. Beispiel: Ein Korbleger ohne Gegner ist leicht, mit Verteidiger, Zeitdruck und müden Beinen wird er deutlich anspruchsvoller.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-085","thema":"Q3.2","kapitel":"KAR-Modell","q":"Definiere den Präzisionsdruck und den Zeitdruck im KAR-Modell.","a":"• Präzisionsdruck: Anforderungen an Bewegungsgenauigkeit (Verlaufs- und Ergebnisgenauigkeit); z. B. Freiwurf\n• Zeitdruck: Anforderungen an verfügbare Bewegungszeit und/oder Bewegungsgeschwindigkeit; z. B. 100-m-Sprint","e":"Verlaufsgenauigkeit meint einen genauen Bewegungsablauf, Ergebnisgenauigkeit das genaue Treffen eines Ziels. Präzision fragt: Wie genau? Zeit fragt: Wie schnell bzw. wie viel Zeit habe ich? Beispiel: Beim Turnen auf dem Balken zählt Verlaufsgenauigkeit, beim Dart die Ergebnisgenauigkeit; ein Volleyballblock steht unter hohem Zeitdruck.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-086","thema":"Q3.2","kapitel":"KAR-Modell","q":"Definiere den Komplexitätsdruck und nenne seine Teilaspekte.","a":"Anforderungen an gleichzeitige und/oder aufeinanderfolgende Bewegungsanteile und den Umfang der Muskelgruppen (z. B. Kugelstoß).\n• K1: Simultankoordination\n• K2: Sukzessivkoordination\n• K3: Muskelauswahl","e":"Je mehr Teilbewegungen gleichzeitig oder nacheinander zusammenpassen müssen und je mehr Muskelgruppen beteiligt sind, desto höher der Komplexitätsdruck. Beispiel: Beim Kugelstoßen müssen Angleiten, Hüftstreckung, Rumpfdrehung und Armstoß in der richtigen Reihenfolge und teils gleichzeitig mit vielen Muskelgruppen ablaufen.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-087","thema":"Q3.2","kapitel":"KAR-Modell","q":"Definiere den Situationsdruck und nenne seine Teilaspekte.","a":"Anforderungen an Variabilität und Komplexität der Umgebungs- und Situationsbedingungen (z. B. Orientierungslauf).\n• S1: Situationskomplexität\n• S2: Situationsvariabilität","e":"Situationskomplexität fragt, wie viele Elemente gleichzeitig zu beachten sind (z. B. Mit- und Gegenspieler), Situationsvariabilität, wie stark sich Bedingungen ändern (z. B. Untergrund, Gegnerverhalten). Beispiel: Beim Orientierungslauf wechseln Gelände, Wege und Sicht ständig; im Handballspiel ändern sich die Spielsituationen pausenlos.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-088","thema":"Q3.2","kapitel":"KAR-Modell","q":"Definiere den Belastungsdruck und nenne seine Teilaspekte.","a":"Anforderungen an physisch-konditionelle und psychische Belastungsbedingungen (z. B. 400-m-Hürden).\n• B1: physische Beanspruchung\n• B2: psychische Beanspruchung","e":"Physisch sind das z. B. Ermüdung oder Schnellkrafteinsatz, psychisch Konzentration, Willenseinsatz oder das Risiko des Misslingens. Koordination wird schwerer, wenn man müde oder nervös ist. Beispiel: Beim 400-m-Hürdenlauf müssen die Hürden auch in der letzten Kurve mit übersäuerten Beinen sauber überlaufen werden.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-089","thema":"Q3.2","kapitel":"KAR-Modell","q":"Warum lässt sich der Schwierigkeitsgrad einer Bewegungsaufgabe nicht an einem einzelnen Regler des KAR-Modells ablesen?","a":"Ein Regler zeigt nur die Schwierigkeit einer Kategorie; die Gesamtschwierigkeit ergibt sich erst aus der Konstellation aller Regler (koordinatives Anforderungsprofil).","e":"Jede Kategorie kann zwischen „niedrig“ (−) und „hoch“ (+) eingestellt werden. Eine einzige hohe Anforderung macht eine Aufgabe nicht automatisch schwer, das Gesamtpaket entscheidet. Beispiel: Ein 100-m-Sprint hat zwar maximalen Zeitdruck, aber geringen Situationsdruck; ein Sprungwurf mit Verteidiger hat mehrere hohe Regler gleichzeitig.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-090","thema":"Q3.2","kapitel":"KAR-Modell","q":"Analysiere die Informationsanforderungen des Tempodribblings im Fußball nach dem KAR-Modell (Neumaier).","a":"• Optisch: mittel–hoch (Gegner, Ball, Raum)\n• Akustisch: gering\n• Taktil: mittel (Ballkontakt am Fuß)\n• Kinästhetisch: mittel (Krafteinsatz)\n• Vestibulär: gering–mittel\n• Gleichgewicht: mittel–hoch","e":"Begründungen: Peripheres Sehen dient der Gegner- und Ballkontrolle und der Vorbereitung des Abspiels; Geräusche sind kaum relevant; die Füße nehmen Druck für Laufen und Ballkontrolle wahr; der Krafteinsatz muss Laufbewegung und Ballkontrolle abstimmen; es gibt nur geringe Richtungs- und Tempowechsel bei hoher Dynamik; das Gleichgewicht integriert beim Laufen mehrere Sinne. Beispiel: Wer mit Ball sprintet, muss gleichzeitig nach vorne schauen – deshalb ist der optische Regler hoch.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-091","thema":"Q3.2","kapitel":"KAR-Modell","q":"Analysiere die Druckbedingungen des Tempodribblings im Fußball nach dem KAR-Modell (Neumaier).","a":"• Präzision: mittel\n• Zeit: gering–mittel\n• K1 Simultan: mittel; K2 Sukzessiv: mittel; K3 Muskelauswahl: mittel\n• S1 Komplexität: gering; S2 Variabilität: gering\n• B1 physisch: hoch; B2 psychisch: hoch","e":"Begründungen: Schrittlänge und -frequenz müssen auf den Ball abgestimmt werden (Präzision); die Laufgeschwindigkeit ist submaximal (Zeit); Laufen und Balltreiben laufen gleichzeitig und im Wechsel, mit großen Muskelgruppen (Komplexität); nur ein Mit- und ein Gegenspieler, gute Platzbedingungen (Situation); hohe Schnellkrafteinsätze sowie Wille und Konzentration, v. a. für Abspiel/Torschuss (Belastung). Für die Klausur jede Reglerstellung kurz begründen. Beispiel: Steht der Verteidiger direkt am Dribbler, würden Situations- und Zeitdruck sofort steigen.","quelle":"L04.3","typ":"kern"},{"id":"q3.2-092","thema":"Q3.2","kapitel":"KAR-Modell","q":"Worin liegt die praktische Relevanz des KAR-Modells?","a":"• Analyse: koordinative Anforderungsprofile differenziert beschreiben und vergleichen\n• Übungsgestaltung: beherrschte Bewegungen durch Variation von Informationsanforderungen und Druckbedingungen erschweren (oder erleichtern)","e":"Aus dem Modell lassen sich mithilfe von Variationsprinzipien zahlreiche Koordinationsübungen ableiten – es ist ein Werkzeugkasten für Lehrer und Trainer. Beispiel: Laufen lässt sich variieren über Informationsanforderungen (mit geschlossenen Augen, rückwärts) und Druckbedingungen (auf Zeit, auf verschiedenen Untergründen, mit Zusatzgewichten, Treppen).","quelle":"L04.3","typ":"kern"},{"id":"q3.2-093","thema":"Q3.2","kapitel":"KAR-Modell","q":"Analysiere den Basketball-Sprungwurf aus der Ballannahme mit Verteidiger nach koordinativen Fähigkeiten und KAR-Modell.","a":"Fähigkeiten: Kopplung, Differenzierung, Gleichgewicht, Orientierung, Reaktion/Umstellung\nKAR: optisch und kinästhetisch hoch, akustisch gering; Präzisions- und Zeitdruck hoch; Komplexität mittel–hoch; Situation mittel; Belastung mittel–hoch","e":"Begründungen: Annahme, Stopp, Absprung und Wurfarm müssen gekoppelt werden; das Handgelenk dosiert die Kraft (Differenzierung); Stopp und Landung müssen auch bei Kontakt stabil sein; Position zu Korb und Verteidiger sowie das Timing erfordern Orientierung; auf den Verteidiger muss man reagieren (z. B. Pass statt Wurf). Gleichgewicht/vestibulär mittel bis hoch, taktil mittel. Präzision wegen des Korbs, Zeitdruck durch den Verteidiger, Belastung durch Ermüdung und Spielstand. Beispiel: Steht der Verteidiger eng, steigen Zeit- und Situationsdruck; beim freien Wurf im Training wären diese Regler niedrig.","quelle":"L04.6","typ":"kern"},{"id":"q3.2-094","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Wie lautet die methodische Grundformel zur Koordinationsschulung?","a":"Koordinationsschulung = einfache, sicher beherrschte Fertigkeiten + Variation der Informationsanforderungen + Variation der Druckbedingungen (nach Neumaier; Roth)","e":"Koordinationsübungen sollten in erholtem Zustand und in allen Altersstufen stattfinden. Die beherrschten Fertigkeiten sind die „Zutaten“, Informationsanforderungen und Druckbedingungen das „Gewürz“. Beispiel: Prellen (beherrschte Fertigkeit) + mit geschlossenen Augen bzw. auf einer Bank stehend (Information) + unter Zeitdruck (Druckbedingung).","quelle":"L04.4","typ":"kern"},{"id":"q3.2-095","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Worin unterscheidet sich das methodische Vorgehen bei der Koordinationsschulung vom Vorgehen beim Techniklernen?","a":"• Techniklernen: schwere Bewegung, Bedingungen werden vereinfacht (Vereinfachung schrittweise abbauen)\n• Koordinationsschulung: einfache, beherrschte Bewegung, Bedingungen werden erschwert (Informationsanforderungen, Druckbedingungen)","e":"Beim Techniklernen macht man es also leichter, bei der Koordinationsschulung schwerer – aber mit einer leichten Grundbewegung. Beispiel: Den Sprungwurf lernt man zunächst ohne Gegner und aus kurzer Distanz; zur Koordinationsschulung dribbelt man dagegen den längst beherrschten Ball, aber rückwärts, mit zwei Bällen und unter Zeitdruck.","quelle":"L04.4","typ":"kern"},{"id":"q3.2-096","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Wann und in welchem Teil einer Sportstunde sollte Koordinationstraining stattfinden? Begründe.","a":"In allen Altersstufen, im Aufwärmen oder zu Beginn des Hauptteils – im erholten Zustand, weil Ermüdung die Bewegungssteuerung verschlechtert (Ausnahme: gezielter Belastungsdruck).","e":"Im erholten Zustand können die Steuerungsprozesse des ZNS optimal geschult werden; ein müdes Nervensystem lernt feine Bewegungen schlecht. Bewusstes Üben unter Vorermüdung ist dagegen eine gewollte Variation der Druckbedingungen. Beispiel: Koordinationsleiter-Übungen macht man am Anfang des Trainings, nicht nach dem Ausdauerlauf – außer man will gerade Koordination unter Ermüdung trainieren.","quelle":"L04.4","typ":"kern"},{"id":"q3.2-097","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Wie entsteht nach der methodischen Grundformel ein vielfältiges Koordinationsprogramm? Nenne die drei Varianten der Schwerpunktsetzung.","a":"Ein Summand der Grundformel bleibt konstant, die anderen beiden werden variiert:\n1. konstante Elementarfertigkeit\n2. konstanter Wahrnehmungsanalysator\n3. konstante Druckbedingung","e":"Beispiele: 1. immer Laufen, 2. immer vestibulär, 3. immer Komplexitätsdruck (Simultankoordination). So sind vorübergehende Schwerpunkte und koordinative Profilbildungen möglich – drei Stellschrauben, eine wird festgehalten. Beispiel zu Variante 2: Balancieren auf umgedrehten Bänken, auf Kastenteilen auf Medizinbällen, auf Stelzen – immer liegt der Schwerpunkt auf dem Gleichgewichtsorgan.","quelle":"L04.4","typ":"kern"},{"id":"q3.2-098","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Nenne elementare motorische Fertigkeiten, die sich für ein sportartübergreifendes Koordinationstraining eignen (nach Roth).","a":"Z. B. Gehen, Laufen, Hüpfen, Springen, Rollen, Wälzen, Kriechen, Fallen, Stützen, Schwingen, Werfen, Stoßen, Prellen, Schlagen, Schießen, Köpfen, Ziehen, Schieben (Auswahl; Roth).","e":"Weitere sind z. B. Armkreisen, Auf- und Umschwünge, Federn, Gleiten, Galopp, Schaukeln und Schweben. Voraussetzung ist, dass sie sicher beherrscht werden und daher nach der Grundformel variiert werden können; sie sind die Grundbausteine fast aller Sportarten. Beispiel: Werfen kann man variieren mit der schwachen Hand (Information), auf bewegte Ziele (Situationsdruck) oder nach Sprints (Belastungsdruck).","quelle":"L04.4","typ":"kern"},{"id":"q3.2-099","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Welche Organisationsformen und Grundsätze gelten für eine sportartübergreifende Koordinationsschulung?","a":"• Formen: Einzel-/Partnerübungen, Parcours, Hindernisläufe, Koordinationszirkel, Lauf- und Staffelspiele\n• Grundsätze: abwechslungsreich, Freude; Geräte und Ideen der Kinder nutzen; Spielformen besonders wertvoll","e":"Hindernisparcours kombinieren elementare Fertigkeiten (Gehen, Laufen, Springen, Rollen, Klettern, Prellen, Werfen) mit Anforderungen an Analysatoren und Druckbedingungen; geeignet sind Kästen, Bänke, Bälle, Turngeräte und Matten. Spielformen enthalten Zeitdruck, Festigkeitssteigerung und Überraschungsmomente (Allgemeine Ballschule). Beispiel: Ein Parcours nach Kosel mit Wippe, Kastentreppe, Rollen über verschiedene Matten, Balancieren auf der Reckstange und Zielwerfen fordert viele Analysatoren und Druckbedingungen nacheinander.","quelle":"L04.4","typ":"kern"},{"id":"q3.2-100","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Zeige am Beispiel Laufen, wie die Elementarfertigkeit nach der Grundformel variiert werden kann.","a":"• Information: Augen zu, rückwärts\n• Zeit: Slalom-, Hindernisläufe, Staffeln\n• Präzision: Balancieren, rhythmisches Laufen\n• Situation: Schatten-/Spiegelläufe, wechselnder Untergrund\n• Komplexität: Armbewegungen, Drehungen, Skippings\n• Belastung: nach Vorbelastung","e":"Weitere Varianten: kleine Spiele und Pendelstaffeln (Zeitdruck), Formationsläufe (Präzision), Anpassung an das Lauftempo anderer und Geländeformen (Situation), Knieheben und Anfersen (Komplexität); die Vorbelastung kann konditionell oder koordinativ sein. Aus einer Grundbewegung entstehen so Dutzende Übungen. Beispiel: Ein Spiegellauf, bei dem man die Richtungswechsel des Partners nachmachen muss, erhöht vor allem den Situationsdruck.","quelle":"L04.4","typ":"kern"},{"id":"q3.2-101","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Welche Druckbedingungen und Informationsanforderungen werden verändert, wenn man statt auf einer Turnmatte auf einer Weichbodenmatte oder von einer schiefen Ebene rollt?","a":"• Weichboden: höhere vestibuläre, kinästhetische, taktile Anforderungen; mehr Präzisions-, Situations-, Belastungsdruck\n• Schiefe Ebene: schnellere Rotation → mehr Zeitdruck, vestibuläre und Orientierungsanforderung\n• Fertigkeit Rollen bleibt gleich","e":"Der Weichboden ist instabil und nachgebend, die Druckempfindung verändert sich und man braucht mehr Kraft. Auf der Schräge steigt die Drehbeschleunigung, und das Aufstehen bzw. Abfangen verlangt mehr Präzision. Beispiel: Auf dem Weichboden „versinkt“ man und muss mehr Spannung aufbauen, auf der Schräge wird die Rolle schneller und das Aufstehen schwieriger.","quelle":"L04.4","typ":"kern"},{"id":"q3.2-102","thema":"Q3.2","kapitel":"Koordinationsschulung","q":"Warum haben Spielformen eine herausragende Bedeutung für das Koordinationstraining?","a":"Spielformen enthalten die Spielidee eines Sportspiels und neben Zeitdruck und Festigkeitssteigerung situative Überraschungsmomente → viele koordinative Anforderungen gleichzeitig und spielnah.","e":"Die Spielidee im Basketball lautet z. B. „Körbe erzielen und Körbe des Gegners verhindern“. Allgemeine Ballschule und vielseitige Sportspielvermittlung nutzen diesen koordinativen Aspekt systematisch. Im Spiel passiert ständig Unvorhergesehenes – genau das fordert Koordination. Beispiel: Beim 3:3 auf einen Korb muss man prellen, passen und werfen, während Gegner und Mitspieler ständig ihre Position ändern.","quelle":"L04.4","typ":"kern"},{"id":"q3.2-103","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Was sind exekutive Funktionen und welche drei Komponenten gehören dazu?","a":"Selbstregulierende Kontrollfunktionen (präfrontaler Kortex), die eingreifen, wenn Routinen nicht ausreichen.\n• Arbeitsgedächtnis\n• Inhibition (Impulskontrolle)\n• Kognitive Flexibilität","e":"Zusammen steuern sie die Selbstregulation: Entscheidungen treffen, planvoll, flexibel und zielgerichtet handeln, das eigene Handeln reflektieren und korrigieren (Kubesch). Im Sport sind sie fast ständig gefordert und durch physisch-kognitives Koordinationstraining förderbar. Beispiel: Ein Basketballer muss sich in der Auszeit den Spielzug merken (Arbeitsgedächtnis), ihn trotz Nervosität ruhig umsetzen (Inhibition) und beim Freilaufen Tempo und Richtung wechseln (Flexibilität).","quelle":"L04.5","typ":"kern"},{"id":"q3.2-104","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Beschreibe das Arbeitsgedächtnis als exekutive Funktion.","a":"Verbaler und visuell-räumlicher Kurzzeitspeicher: Informationen kurz speichern (7 ± 2 Elemente, wenige Sekunden), mit ihnen arbeiten und sie ins Langzeitgedächtnis überführen.","e":"Das Arbeitsgedächtnis ist wie ein Notizzettel im Kopf. Beispiel: Ein Volleyballspieler merkt sich das Handzeichen des Zuspielers für den nächsten Spielzug und hat es parat, wenn der Ball kommt.","quelle":"L04.5","typ":"kern"},{"id":"q3.2-105","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Beschreibe die Inhibition als exekutive Funktion.","a":"Impulskontrolle: spontane Impulse und Emotionen unterdrücken, Aufmerksamkeit willentlich lenken, Störreize ausblenden.","e":"Im Sport ist Inhibition z. B. für Go-/No-go-Entscheidungen und zum Widerstehen gegen Täuschungen wichtig – die „Bremse“ im Kopf. Beispiel: Der Batter im Baseball muss bei einem Ball mit Effet, der knapp außerhalb der Strike Zone fliegt, den Schlagimpuls unterdrücken – sonst wird ihm ein Strike angerechnet.","quelle":"L04.5","typ":"kern"},{"id":"q3.2-106","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Beschreibe die kognitive Flexibilität als exekutive Funktion.","a":"• Kognitive Flexibilität = kognitive Umstellungsfähigkeit.\n• Fähigkeit, den Fokus der Aufmerksamkeit zu wechseln,\n• sich schnell auf neue Situationen einzustellen\n• und andere Perspektiven einzunehmen.","e":"Flexibilität ist das schnelle „Umschalten“ im Kopf. Beispiel: Nach einem Ballverlust muss ein Handballer sofort von Angriff auf Abwehr umschalten und seine Aufgabe neu denken.","quelle":"L04.5","typ":"kern"},{"id":"q3.2-107","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Was zeigt der Stroop-Test im Zusammenhang mit exekutiven Funktionen?","a":"• Farbwörter in anderer Druckfarbe: Farbe benennen dauert länger als Lesen\n• Automatisiertes (Lesen) läuft von selbst, Ungewohntes braucht Aufmerksamkeit\n• Leseimpuls muss gehemmt werden → Inhibition","e":"Der Test geht auf John Ridley Stroop zurück: Man liest z. B. das Wort ROT, das in Blau gedruckt ist, und soll „Blau“ sagen. Er macht spürbar, wie mühsam es ist, einen Automatismus zu unterdrücken. Beispiel: Im Sport ist es ähnlich, wenn man eine eingeschliffene Bewegung plötzlich anders ausführen muss, etwa invers auf Handzeichen reagieren.","quelle":"L04.5","typ":"kern"},{"id":"q3.2-108","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Wie können exekutive Funktionen gefördert werden und welche Rolle spielt das Koordinationstraining dabei?","a":"• Durch kognitive und physische Reize, am wirksamsten kombiniert (physisch-kognitives Training; Kubesch)\n• Umsetzung über Spiele, Übungen, Bewegungsaufgaben\n• Koordinationstraining: beherrschte Bewegungen durch Druckbedingungen und Informationsanforderungen erschweren","e":"Wegen ihrer großen Bedeutung für die Leistung sollte das Training der exekutiven Funktionen systematisch in den Trainingsprozess eingebaut werden (Kubesch et al.; Kubesch & Walk). Koordinationstraining ist so gleichzeitig Gehirntraining. Beispiel: Wer beim Laufen auf Zahlen mit unterschiedlichen Bewegungen reagieren muss, trainiert Koordination (Zeit-, Komplexitätsdruck) und Arbeitsgedächtnis zugleich.","quelle":"L04.5","typ":"kern"},{"id":"q3.2-109","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Nenne mögliche Inhalte eines physisch-kognitiven Trainings für jede exekutive Funktion (nach Stöglehner).","a":"• Arbeitsgedächtnis: Bewegungsaufgaben behalten, Änderungen abspeichern\n• Inhibition: Routinen durchbrechen, erzeugte Routinen hemmen, Gewohntes verändern\n• Kognitive Flexibilität: Aufgaben/Regeln verändern, passende Lösung auswählen, eigene Lösungswege entwickeln","e":"Jede exekutive Funktion bekommt eigene Übungsprinzipien. Beispiel: Für die Inhibition wird erst eine Routine aufgebaut (in die gezeigte Richtung springen) und dann gezielt durchbrochen (in die Gegenrichtung springen).","quelle":"L04.5","typ":"kern"},{"id":"q3.2-110","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Beschreibe je eine Übungsform zur Förderung von Arbeitsgedächtnis, Inhibition und kognitiver Flexibilität und begründe ihre Wirkung.","a":"• Arbeitsgedächtnis: Zahlen 1–6 bestimmten Bewegungen zuordnen, auf gezeigte Zahl ausführen → Zuordnungen behalten und abrufen\n• Inhibition: Handzeichen-Reaktion, später invers → Automatismus hemmen\n• Flexibilität: Fangspiel mit wechselnder Fänger-Eigenschaft → schnell umstellen","e":"Zahlenbeispiel: 1 = Hocke, 2 = halbe Drehung, 3 = ganze Drehung, 4 = Hampelmann, 5 = Strecksprung, 6 = Liegestütz. Handzeichen beim Laufen auf der Stelle: oben = springen, unten = hocken, Seite = Ausfallschritt; nach der Automatisierung umgekehrt. Beim Fangspiel sind z. B. alle mit weißem T-Shirt Fänger, in jedem Durchgang eine neue Eigenschaft. Beispiel: Beim inversen Handzeichen-Spiel will der Körper „von selbst“ in die gezeigte Richtung – genau dieses Unterdrücken trainiert die Inhibition.","quelle":"L04.5","typ":"kern"},{"id":"q3.2-111","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Setze das Training der exekutiven Funktionen in Beziehung zum KAR-Modell und zu den koordinativen Fähigkeiten.","a":"• KAR: beherrschte Fertigkeiten + mehr Zeit-, Situations-, Komplexitäts-, psychischer Belastungsdruck sowie optische/akustische Informationsanforderungen\n• Gefördert v. a. Reaktions-, Umstellungs-, Orientierungs-(und Gleichgewichts-)fähigkeit\n• Beide nutzen Variation und Erschwerung","e":"Zeitdruck entsteht durch schnelle Ausführung auf Signal, Situationsdruck durch wechselnde Signale und Rollen, Komplexitätsdruck durch Bewegung plus Denkaufgabe. Zahlenaufgabe: Reaktion, Umstellung, Gleichgewicht und Orientierung (Drehungen); inverse Handzeichen: Reaktion, Umstellung, Orientierung; Fangspiel: Orientierung, Reaktion, Umstellung. KAR beschreibt die Anforderungen, die exekutiven Funktionen die geistigen Prozesse dahinter. Beispiel: Kognitive Flexibilität ähnelt stark der koordinativen Umstellungsfähigkeit – einmal geistig, einmal motorisch.","quelle":"L04.5","typ":"kern"},{"id":"q3.2-112","thema":"Q3.2","kapitel":"Exekutive Funktionen","q":"Erläutere die Bedeutung der exekutiven Funktionen für die sportliche Leistung am Beispiel der Baseball-Situation Batter gegen Pitcher.","a":"Der Batter muss in kürzester Zeit entscheiden, ob der Ball mit Effet in der Strike Zone ist (Go/No-go), und eine angebahnte Schlagbewegung ggf. unterdrücken → hohe Inhibition nötig.","e":"Schlägt er auf einen Ball außerhalb der Strike Zone, zählt es als Strike gegen ihn; der Pitcher versucht ihn genau dazu zu verleiten. Leistung besteht also nicht nur aus Kraft und Technik, sondern auch aus Impulskontrolle. Beispiel: Ähnlich muss ein Tennisspieler beim Return entscheiden, ob ein Ball ins Aus fliegt, und dann den Schlagimpuls stoppen.","quelle":"L04.5","typ":"kern"},{"id":"q4.1-001","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Welche drei zentralen gesellschaftlichen Trends nennt Schildmacher (1998), die sich auch auf den Sport übertragen lassen?","a":"• Suche nach Authentizität (Echtheit, eigener Stil)\n• Konsumismus (Sport als Konsumgut)\n• Eventorientierung (Sport als inszeniertes Erlebnis)\nIm Sport münden sie in Trendsportarten.","e":"Ein Trend ist eine besonders tief greifende und nachhaltige Entwicklung, keine kurze Mode – er erfasst die ganze Gesellschaft, und der Sport spiegelt ihn wider (Selbstverwirklichung; Ausrüstung, Mode, Lifestyle; Inszenierung). Beispiel: Beim Surfen oder Skaten geht es um einen eigenen Stil (Authentizität), man kauft passende Kleidung und Boards (Konsum) und trifft sich bei Contests mit Musik und Party (Event).","quelle":"L08.3","typ":"kern"},{"id":"q4.1-002","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Wie nutzt die Wirtschaft Trendsportarten und welche Folgen haben Trends für den traditionellen Sport?","a":"Wirtschaft: nutzt Trendsportarten als Werbeträger (Imagetransfer: jung, authentisch).\nFolgen:\n• Wandel traditioneller Strukturen des Sporttreibens\n• Mitgliederrückgang in Vereinen\n• Neuausrichtung des Sportunterrichts","e":"Firmen wollen cool und jung wirken und schmücken sich deshalb mit Trendsportlern. Betroffen sind vor allem traditionelle, wettkampforientierte Sportarten; der Sportunterricht nimmt Trendsportarten auf. Beispiel: Ein Energydrink-Hersteller sponsert Freeskier und Mountainbike-Events, damit seine Marke für Abenteuer und Freiheit steht. Gleichzeitig verlieren klassische Vereine Mitglieder, weil Jugendliche lieber ungebunden im Skatepark fahren.","quelle":"L08.3","typ":"kern"},{"id":"q4.1-003","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Inwiefern verstehen sich Trendsportarten nach Lamprecht und Stamm (2002) als Gegenbewegung zum traditionellen Sport?","a":"Anderes Sportverständnis, quer zum traditionellen Sport:\n• Spaß statt Leistung\n• Informelle Gruppe statt Verein/Verband\n• Spontane, kreative statt normierter Bewegungen\n• Individueller „Style“, Freiheit, Innovation","e":"Trendsportarten sind nicht nur neue Bewegungsformen mit neuen Geräten. Der traditionelle Sport hat feste Regeln, Vereine, Ligen und Ergebnislisten – Trendsport will genau das Gegenteil sein und steht für jugendliche Freiheit und Erneuerung. Beispiel: Beim Streetbasketball gibt es keinen Schiedsrichter und keinen Verein, man spielt mit Freunden auf dem Freiplatz, und ein spektakulärer Move zählt oft mehr als der Sieg.","quelle":"L08.3","typ":"kern"},{"id":"q4.1-004","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Nenne und beschreibe die fünf Entwicklungsphasen von Trendsportarten (nach Lamprecht und Stamm, 2002).","a":"1. Invention: Erfindung durch Pioniere\n2. Innovation: lokale Marktnischen, Kleinserien\n3. Entfaltung/Wachstum: überregionaler Markt, Massenproduktion\n4. Reife/Diffusion: breite Bevölkerung\n5. Sättigung: etablierte Sportart","e":"Merke die Reihenfolge mit „Erfinden, Einführen, Entfalten, Verbreiten, Sättigen“. In der Innovationsphase verlässt die Sportart den Kreis der Pioniere, in der Wachstumsphase wird die Erfindung weiterentwickelt. Beispiel Snowboarden: Erst bastelten ein paar Tüftler Bretter, dann gab es kleine Firmen für Insider, später Massenproduktion und Boom, heute ist Snowboarden eine ganz normale, sogar olympische Wintersportart.","quelle":"L08.3","typ":"kern"},{"id":"q4.1-005","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Warum ähnelt die Entwicklung von Trendsportarten wirtschaftlichen Innovations- und Produktzyklen? Erläutere die Rolle des Marktes.","a":"• Verlauf gleicht wirtschaftlichen Innovations- und Produktzyklen\n• Gekoppelt an die Verbreitung der Sportgeräte: handgefertigt → Marktnische → Massenproduktion → Sättigung\n• Sportartikelindustrie treibt die Verbreitung und profitiert","e":"Diese Zyklen erklären die Dynamik von Wachstum und Krise durch neue Produkte. Eine Trendsportart verhält sich wie ein neues Handy: Erst haben es nur wenige Technikfans, dann alle, und irgendwann ist der Markt voll – der Absatz stagniert, Hersteller suchen den nächsten Trend. Beispiel: Als Stand-up-Paddling bekannt wurde, gab es zunächst teure Spezialboards, später aufblasbare Boards im Discounter. Da war der Trend in der Massenphase angekommen.","quelle":"L08.3","typ":"kern"},{"id":"q4.1-006","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Nenne die fünf Entwicklungsschritte im Freizeitsport nach Schildmacher (1998).","a":"• vom Indoorsport zur Outdoorvariante\n• vom normierten zum nicht normierten Sport\n• vom großen Mannschaftssport zum kleinen Gruppensport\n• vom geschützten zum risikoreichen Sport\n• vom verbindlichen zum unverbindlichen Sport","e":"Diese Thesen beschreiben, wohin sich der Freizeitsport bewegt: raus aus der Halle, weg von festen Regeln und festen Terminen. Beispiel: Aus dem Hallenvolleyball (6 gegen 6, im Verein, fester Trainingstermin) wird Beachvolleyball (2 gegen 2, draußen, spontan mit Freunden). Für die Wirtschaft entstehen dadurch neue Märkte für Ausrüstung und Events.","quelle":"L08.3","typ":"kern"},{"id":"q4.1-007","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Erläutere, welche Faktoren zur Popularisierung des Beachvolleyballs beigetragen haben und warum das Medieninteresse am Hallenvolleyball vergleichsweise gering ist.","a":"Beachvolleyball:\n• Lifestyle-Image\n• Eventcharakter\n• 2er-Teams → Stars\n• telegen, sponsorenattraktiv, olympisch\nHallenvolleyball:\n• traditionelles Vereinsimage\n• 6er-Teams → wenig Personalisierung\n• wenig Sendezeit und Sponsoren (Kreislauf)","e":"Medien suchen Bilder, Emotionen und Gesichter. Beachvolleyball passt zu den Trends Authentizität, Konsum und Event, hat ein übersichtliches Feld, kurze Ballwechsel, Musik und Moderation (oft in Innenstädten) und ist für Freizeitsportler leicht zugänglich. Weniger Sendezeit bringt der Halle weniger Sponsoren und Bekanntheit – ein Kreislauf. Beispiel: Ein Beach-Turnier auf einem Stadtplatz mit DJ und Zuschauertribüne wirkt im Fernsehen wie ein Sommerfest, ein Hallenspiel in einer Sporthalle eher wie normaler Ligaalltag.","quelle":"L08.4","typ":"kern"},{"id":"q4.1-008","thema":"Q4.1","kapitel":"Trendsport und Kommerz","q":"Bewerte das Engagement von Firmen im Sport unter Abwägung von Pro- und Kontraargumenten.","a":"Pro:\n• Finanzierung von Sportlern, Vereinen, Events\n• Professionalisierung, Infrastruktur\n• Entlastung öffentlicher Haushalte\nKontra:\n• Abhängigkeit, Einflussnahme\n• Geld v. a. für Mediensportarten\n• Erfolgsdruck (Doping)\n• Image für fragwürdige Produkte\nFazit: sinnvoll, wenn die Autonomie des Sports gewahrt bleibt","e":"Bei Bewertungsaufgaben immer beide Seiten abwägen und zu einem begründeten Urteil kommen. Sponsoring finanziert auch Nachwuchs, macht manche Randsportarten erst möglich und zeigt gesellschaftliche Verantwortung (Breitensport, Gesundheit); andererseits nehmen Geldgeber Einfluss auf Termine und Regeln, und der Sport wird z. B. für ungesunde Lebensmittel oder Wetten genutzt. Beispiel: Ein Autohaus, das die Jugendmannschaft des Dorfvereins mit Trikots ausstattet, wird anders bewertet als ein Konzern, der einen Bundesligaverein so stark finanziert, dass er Entscheidungen mitbestimmt.","quelle":"L08.3","typ":"kern"},{"id":"q4.1-009","thema":"Q4.1","kapitel":"Magisches Dreieck","q":"Was versteht man unter dem „magischen Dreieck“ von Sport, Medien und Wirtschaft?","a":"Modell der wechselseitigen Abhängigkeit von Spitzensport, Medien und Wirtschaft („Geben und Nehmen“):\n• Sport: Inhalte, Aufmerksamkeit\n• Medien: Öffentlichkeit, Reichweite\n• Wirtschaft: Geld\nIm Zentrum: das Publikum.","e":"„Magisch“, weil sich die Beziehungen gegenseitig verstärken: Mehr Medienpräsenz bringt mehr Sponsorengeld, mehr Geld mehr Spitzenleistungen, diese mehr Medieninteresse. Alle drei konkurrieren um die Aufmerksamkeit von Zuschauern, Fans und Konsumenten. Beispiel Fußball-Bundesliga: Die Liga verkauft Übertragungsrechte an Sender, die Sender verkaufen Werbezeit an Unternehmen, und die Unternehmen sponsern zusätzlich die Vereine. Ohne Zuschauer vor dem Bildschirm würde dieses Dreieck zusammenbrechen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-010","thema":"Q4.1","kapitel":"Magisches Dreieck","q":"Was geben sich Sport und Medien im magischen Dreieck gegenseitig?","a":"Sport → Medien:\n• attraktive Inhalte (Spannung, Emotion, live)\n• hohe Quoten\n• planbares Programm, Stars\nMedien → Sport:\n• Öffentlichkeit, Reichweite\n• Geld für Übertragungsrechte\n• Sponsoren, Popularität","e":"Der Sport ist für Medien ein Publikumsmagnet, die Medien sind für den Sport ein Lautsprecher und eine Geldquelle. Beispiel: Ein Länderspiel bei einer WM gehört regelmäßig zu den meistgesehenen Sendungen des Jahres, und der Sender zahlt dafür viel Geld an den Rechteinhaber.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-011","thema":"Q4.1","kapitel":"Magisches Dreieck","q":"Was geben sich Sport und Wirtschaft im magischen Dreieck gegenseitig?","a":"Wirtschaft → Sport:\n• Geld (Sponsoring, Ausrüster)\n• Sachleistungen, Know-how\nSport → Wirtschaft:\n• Werbeplattform\n• Imagetransfer\n• Absatzmärkte\n• Kundenbindung (VIP)","e":"Firmen kaufen sich mit Sponsoring ein Stück der positiven Gefühle, die Sport auslöst, und erreichen gezielt ihre Zielgruppen; mit ihrem Geld finanzieren sie Profisport, Veranstaltungen und Infrastruktur. Absatzmärkte sind Sportartikel, Fanartikel und Tickets. Beispiel: Ein Versicherungskonzern ist Hauptsponsor eines Handballvereins. Der Verein bekommt Geld für Gehälter, die Versicherung bekommt ihr Logo auf jedes Trikot und lädt Geschäftskunden in die VIP-Lounge ein.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-012","thema":"Q4.1","kapitel":"Magisches Dreieck","q":"Welche Beziehung besteht im magischen Dreieck zwischen Medien und Wirtschaft?","a":"Medien → Wirtschaft:\n• Werbezeiten im Sportumfeld\n• Reichweite, Zielgruppen\n• Sichtbarkeit von Banden-/Trikotwerbung\nWirtschaft → Medien:\n• Werbeeinnahmen\n• Finanzierung der Übertragungsrechte","e":"Sender können teure Sportrechte nur bezahlen, weil Unternehmen in den Werbepausen werben wollen – besonders Privatsender; bei Pay-TV und Streaming zahlen zusätzlich die Abonnenten. Banden- und Trikotwerbung ist indirekte Werbung. Beispiel: In der Halbzeitpause eines großen Finales sind Werbespots besonders teuer, weil Millionen Menschen zuschauen. Gleichzeitig sieht man auf den Banden im Stadion die ganze Spielzeit über Firmennamen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-013","thema":"Q4.1","kapitel":"Magisches Dreieck","q":"Welche Eigenschaften machen Sport für Medien und Wirtschaft so attraktiv?","a":"• Spannung, offener Ausgang\n• Emotionen, Identifikation\n• leicht verständlich, global\n• Live-Charakter\n• Planbarkeit\n• Stars und Geschichten\n• positive Werte\n• schwer erreichbare Zielgruppen","e":"Sport ist eine „Seifenoper ohne Drehbuch“: Niemand weiß, wie es ausgeht. Er ist sprach- und kulturübergreifend verständlich, läuft in festen Spieltagen und Saisons, und live gesehene Werbung wird nicht übersprungen. Er erreicht auch schwer erreichbare Gruppen wie junge Männer. Beispiel: Ein Elfmeterschießen hält Millionen vor dem Fernseher, die Werbung davor und danach wird live gesehen. Bei einer Serie, die man streamt, würde man sie einfach überspringen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-014","thema":"Q4.1","kapitel":"Magisches Dreieck","q":"Welche Risiken entstehen aus der gegenseitigen Abhängigkeit im magischen Dreieck für den Sport?","a":"• Autonomieverlust (Termine, Regeln)\n• Finanzielle Abhängigkeit\n• Verdrängung medienunattraktiver Sportarten\n• Erfolgsdruck (Doping)\n• Sport als Ware\n• Glaubwürdigkeitsverlust durch Skandale","e":"Wer bezahlt, will mitbestimmen. Fallen Sponsoren oder Medienverträge weg, geraten Vereine und Verbände in Krisen. Werte wie Spiel, Gemeinschaft und Gesundheit treten hinter Unterhaltung zurück, und Skandale schaden allen drei Partnern. Beispiel: Wenn Anstoßzeiten so gelegt werden, dass Spiele in anderen Zeitzonen live laufen können, richtet sich der Sport nach dem Fernsehmarkt und nicht mehr nach Spielern oder Stadionbesuchern.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-015","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Definiere den Begriff Kommerzialisierung des Sports.","a":"Prozess, in dem Sport zunehmend nach marktwirtschaftlichen Prinzipien organisiert und als Ware bzw. Dienstleistung vermarktet wird; Gewinnziele treten neben oder vor sportliche Ziele.","e":"Kommerzialisierung heißt: Mit Sport wird Geld verdient – über Tickets, Medienrechte, Sponsoring und Merchandising, außerdem dient er als Werbemedium. Das betrifft vor allem den Spitzensport, zunehmend aber auch Freizeit- und Breitensport (Fitnessstudios, Events, Ausrüstung). Beispiel: Ein Stadtmarathon ist heute nicht nur ein Lauf, sondern auch ein Produkt mit Startgebühren, Sponsoren, Medaillen-Merchandise und einer Messe für Laufschuhe.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-016","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Was versteht man unter Professionalisierung im Sport?","a":"Entwicklung vom Amateur- zum Berufssport: Sport wird als Beruf ausgeübt – von Athleten und Umfeld (Trainer, Manager, Funktionäre); Vereine werden zu Wirtschaftsunternehmen.","e":"Ursache sind die hohen Leistungsanforderungen im Spitzensport, die Vollzeittraining erfordern, finanziert über Medien und Sponsoring. Historisch bedeutet das die Abkehr vom olympischen Amateurideal; seit den 1980er-Jahren wurden Profis schrittweise bei Olympia zugelassen. Im Profifußball sind Vereine oft ausgegliederte Kapitalgesellschaften. Beispiel: Ein Bundesligaverein hat nicht nur Spieler, sondern Hunderte Angestellte von der Physiotherapie über Datenanalyse bis zur Marketingabteilung.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-017","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Definiere Mediatisierung bzw. Medialisierung des Sports.","a":"Prozess, in dem sich der Sport zunehmend an die Logik der Massenmedien anpasst (Regeln, Formate, Termine, Präsentation); Sport wird v. a. medial erlebt und als Medienprodukt inszeniert.","e":"Medienlogik heißt: Spannung, Kürze, Bildhaftigkeit, Personalisierung, Emotionalisierung, Planbarkeit. Die meisten Menschen sehen Spitzensport nur über Medien, die dadurch zum mitbestimmenden Akteur werden. Beispiel: Im Biathlon wurden Formate wie Verfolgung und Massenstart eingeführt. Dort sieht man direkt, wer vorne liegt, das ist für Zuschauer viel spannender als ein Einzelrennen mit Intervallstart.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-018","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Wie verändern Medien Sportarten und ihre Regeln? Nenne typische Veränderungsbereiche.","a":"• Regeländerungen (Zählweise, Satzlänge)\n• Telegene Formate\n• TV-Timeouts für Werbung\n• Sichtbarere Geräte\n• Termine nach Sendeplätzen\n• Videobeweis\n• Inszenierung, Show","e":"Viele Regeln, die heute selbstverständlich wirken, sind wegen des Fernsehens entstanden – für mehr Spannung, Tempo und kalkulierbare Spieldauer; Spieltage werden für Sendeplätze und internationale Märkte zersplittert. Beispiele: Im Tennis begrenzt der Tiebreak die Satzlänge, im Volleyball macht die Rallypoint-Zählweise die Spieldauer planbarer, im Tischtennis wurde der Ball größer und damit langsamer und besser sichtbar.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-019","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Was bedeutet Eventisierung bzw. Inszenierung des Sports?","a":"Sportveranstaltungen werden als Gesamterlebnis (Event) gestaltet, bei dem Unterhaltung neben den Wettkampf tritt (Show, Musik, Moderation, Fan-Zonen; mediale Inszenierung).\nZiel: breiteres Publikum, höherer Vermarktungswert.","e":"Ein Wettkampf wird zur Show, damit nicht nur echte Fans kommen. Medial gehören viele Kameras, Zeitlupen, Grafiken, Statistiken, Interviews sowie Vor- und Nachberichte dazu. Kritik: Der Sport selbst kann zur Kulisse für Unterhaltung werden. Beispiel: Beim Super Bowl schauen viele Menschen hauptsächlich wegen der Halbzeitshow und der Werbespots zu, das Spiel ist für sie fast Nebensache.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-020","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Erläutere Personalisierung und Starkult im Mediensport.","a":"• Medien stellen Personen (Stars) statt Sachverhalte in den Mittelpunkt.\n• Stars: Identifikationsfiguren, Werbeträger, eigene Marken\n• Folgen: Superstar-Effekt (große Einkommensunterschiede), öffentliches Privatleben, Druck","e":"Menschen interessieren sich mehr für Personen als für Tabellen, deshalb werden Geschichten über Personen erzählt. Superstar-Effekt: Über die Medien erreichen die Besten ein riesiges Publikum, sodass kleine Leistungsunterschiede zu riesigen Einkommensunterschieden führen. Beispiel: Ein Tennismatch wird als Duell zweier Superstars mit ihrer Vorgeschichte vermarktet, und einer der beiden wirbt danach in der Werbepause für Uhren, Autos oder Kaffee.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-021","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Was versteht man unter der Globalisierung des Sports und wie hängt sie mit Medien und Wirtschaft zusammen?","a":"Weltweite Verbreitung, Vernetzung und Vermarktung von Sportarten, Wettbewerben, Vereinen und Stars.\n• Medien machen Ereignisse weltweit live verfügbar.\n• Wirtschaft: Vereine, Ligen und Konzerne erschließen globale Märkte.","e":"Satellit, Internet und Streaming bringen Spiele überallhin; Vereine verkaufen Auslandsrechte, reisen ins Ausland und bauen internationale Fanbasen auf, Spielertransfers sind international. Folgen: höhere Einnahmen für Top-Akteure, aber Verlust regionaler Bindung, Termine nach Zeitzonen und Konzentration auf wenige globale Marken. Beispiel: Große Fußballklubs fahren im Sommer auf Asien- oder USA-Tour, um dort Trikots zu verkaufen und neue Sponsoren zu gewinnen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-022","thema":"Q4.1","kapitel":"Kommerzialisierung und Medialisierung","q":"Wie hat sich das Verhältnis von Amateurideal und Kommerz bei den Olympischen Spielen entwickelt?","a":"• Ursprünglich (Coubertin): Amateurideal, Amateurparagraph\n• Seit den 1980er-Jahren: Öffnung für Profis, umfassende Vermarktung\n• Heute: globales Medien- und Wirtschaftsereignis\n• Kritik: Gigantismus, Kosten, Kommerz","e":"Die olympische Idee war bewusst gegen Geld im Sport gerichtet: Teilnahme wichtiger als Sieg, Völkerverständigung, Erziehung; wer mit Sport Geld verdiente, durfte nicht starten. Heute sind Fernsehrechte und Top-Sponsoren die Haupteinnahmequellen des IOC, und Kritiker sehen Kommerz statt olympischer Werte. Beispiel: Bei den Spielen 1992 traten erstmals NBA-Profis als „Dream Team“ für die USA an. Das war ein Symbol für das Ende des Amateurgedankens.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-023","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Definiere Sportsponsoring und grenze es von Mäzenatentum und Spende ab.","a":"• Sponsoring: Geld, Sach- oder Dienstleistungen gegen vertragliche Gegenleistung, für Marketingziele des Unternehmens\n• Mäzenatentum: uneigennützig, ohne Gegenleistung, meist ungenannt\n• Spende: freiwillig, ohne Gegenleistung","e":"Sponsoring ist ein Geschäft, kein Geschenk: Leistung gegen Gegenleistung, Ziel sind Bekanntheit und Image. Spenden sind oft steuerlich begünstigt. Beispiel: Die örtliche Bäckerei zahlt dem Fußballverein 2000 Euro und bekommt dafür eine Bandenwerbung (Sponsoring). Gibt die Inhaberin das Geld anonym, weil ihr der Verein am Herzen liegt, ist das Mäzenatentum.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-024","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Welche Arten von Sportsponsoring lassen sich nach dem Gesponserten unterscheiden?","a":"• Einzelsportler (Personensponsoring)\n• Mannschaft/Verein\n• Verband\n• Veranstaltung/Event\n• Sportstätte (Naming Rights)\n• Medien (Sendungen)\n• Breiten- und Nachwuchssport","e":"Gesponsert werden kann fast alles, was im Sport sichtbar ist – vom Ausrüstervertrag über Trikot- und Hauptsponsoring bis zu Schul- und Jugendprojekten. Beispiele: ein Skispringer mit Logo auf dem Helm, ein Verein mit Firmennamen auf der Brust, ein Stadion, das den Namen einer Versicherung trägt, oder eine Sportsendung mit dem Hinweis „präsentiert von …“.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-025","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Welche Ziele verfolgen Unternehmen mit Sportsponsoring?","a":"Ökonomisch: Absatz-/Umsatzsteigerung, neue Märkte\nKommunikativ:\n• Bekanntheit\n• Imagetransfer\n• Kundenbindung (Hospitality)\n• Mitarbeitermotivation\n• Gesellschaftliche Verantwortung zeigen\n• Produktpräsentation/-test","e":"Sponsoring wirkt meist nicht direkt auf den Verkauf, sondern langfristig über Bekanntheit und Image. Gesellschaftliche Verantwortung zeigt sich etwa in regionalem Engagement und Nachwuchsförderung; Produkttests betreffen v. a. Ausrüster. Beispiel: Ein regionaler Energieversorger sponsert den Handballklub der Stadt. Er will zeigen, dass er zur Region gehört, lädt Geschäftspartner zu Heimspielen ein und macht die eigenen Mitarbeiter stolz.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-026","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Erläutere den Imagetransfer beim Sponsoring und seine Risiken.","a":"Übertragung von Werten eines Sportlers oder Events (Leistung, Dynamik, Fairness) auf eine Marke; Voraussetzung: Passung.\nRisiken:\n• negativer Transfer bei Skandalen\n• Misserfolg\n• fehlende Glaubwürdigkeit","e":"Das gute Gefühl, das wir mit einem Sportler verbinden, soll auf die Marke „abfärben“ – dazu müssen beide häufig gemeinsam wahrgenommen werden. Skandale sind etwa Doping, Manipulation, Gewalt oder Fehlverhalten; Verträge enthalten deshalb oft Moral- bzw. Ausstiegsklauseln. Beispiel: Ein Sportwagenhersteller passt zum Motorsport (Geschwindigkeit, Technik). Wird aber ein gesponserter Athlet des Dopings überführt, färbt das genauso negativ ab, weshalb Sponsoren dann oft sofort den Vertrag kündigen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-027","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Nenne die wichtigsten Einnahmequellen eines professionellen Sportvereins.","a":"• Medienrechte\n• Sponsoring und Werbung\n• Spieltagseinnahmen (Tickets, Logen)\n• Merchandising, Lizenzen\n• Transfererlöse\n• Prämien aus Wettbewerben\n• Sonstiges: Investoren, Mitgliedsbeiträge","e":"Ein Profiverein ist wie ein Unternehmen mit mehreren Standbeinen; im Spitzenfußball sind die Medienrechte (meist über die Liga verteilt) oft die größte Einnahmequelle. Beispiel: Ein Bundesligaklub verdient Geld durch die TV-Verträge der Liga, den Trikotsponsor, die Eintrittskarten, verkaufte Fanschals und gelegentlich durch den Verkauf eines Talents an einen großen ausländischen Verein.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-028","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Was sind Übertragungs- bzw. Medienrechte im Sport und wer vergibt sie?","a":"Recht, ein Sportereignis in TV, Hörfunk, Internet oder Streaming zu übertragen.\n• Vergabe durch Veranstalter (Ligen, Verbände, IOC, FIFA) bzw. Vereine\n• Verkauf gegen Entgelt, oft in Paketen","e":"Wer ein Spiel zeigen will, muss dafür bezahlen, wie für die Lizenz eines Films – live oder zeitversetzt, ganz oder in Ausschnitten. Die Konkurrenz von öffentlich-rechtlichen, privaten, Pay-TV-Sendern und Streamingdiensten hat die Preise stark steigen lassen; Zuschauer brauchen teils mehrere Abos. Beispiel: Die Bundesligarechte werden für mehrere Spielzeiten in Paketen versteigert, sodass manche Spiele beim einen und andere beim anderen Anbieter laufen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-029","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Unterscheide Zentralvermarktung und Einzelvermarktung von Medienrechten und nenne Vor- und Nachteile.","a":"• Zentralvermarktung: Liga verkauft gemeinsam, verteilt Erlöse\n + solidarisch, ausgeglichener\n – Topvereine erhalten weniger\n• Einzelvermarktung: jeder Verein selbst\n + Höchsteinnahmen für Attraktive\n – Schere Groß/Klein wächst","e":"Zentral heißt: Alle verhandeln gemeinsam und teilen nach einem Schlüssel. Das stärkt die Verhandlungsposition gegenüber Sendern und hilft kleinen Vereinen, wirft aber kartellrechtliche Fragen auf. Beispiel: In der Bundesliga werden die TV-Rechte zentral vermarktet, deshalb bekommt auch ein Aufsteiger einen ordentlichen Anteil. Bei Einzelvermarktung, wie sie in Spanien lange üblich war, kassierten die großen Klubs den Löwenanteil.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-030","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Was regelt die sogenannte Schutzliste für Sportereignisse im Free-TV und warum gibt es sie?","a":"Gesetzliche Regelung (Medienstaatsvertrag): Ereignisse von erheblicher gesellschaftlicher Bedeutung (z. B. Olympia, wichtige Spiele der Nationalmannschaft bei WM/EM) müssen frei empfangbar übertragen werden.\nZiel: Zugang für alle.","e":"Manche Ereignisse sollen nicht nur für zahlende Abonnenten zu sehen sein. Dazu gehören bei WM/EM Eröffnungsspiel, Halbfinale, Finale und Spiele mit deutscher Beteiligung. Es besteht ein Spannungsfeld zwischen Vermarktungsinteresse der Rechteinhaber und öffentlichem Interesse an Teilhabe. Beispiel: Selbst wenn ein Pay-TV-Sender Rechte an einer Fußball-EM hält, müssen die Spiele der deutschen Mannschaft auch im frei empfangbaren Fernsehen laufen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-031","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Was versteht man unter Merchandising und Lizenzierung im Sport?","a":"• Merchandising: Vermarktung von Fanartikeln mit Name, Logo oder Abbild von Vereinen, Events oder Sportlern\n• Lizenzierung: Hersteller darf die Marke gegen Gebühr nutzen\nBedeutung: Einnahmen, Fanbindung","e":"Fans kaufen nicht einfach ein T-Shirt, sondern ein Stück Zugehörigkeit. Voraussetzung ist eine starke Marke mit emotionaler Bindung durch Erfolg, Stars oder Tradition. Beispiel: Wechselt ein Weltstar zu einem neuen Verein, verkauft dieser innerhalb weniger Tage große Mengen Trikots mit dessen Namen. Der Verein verdient daran über Lizenzgebühren und eigenen Verkauf.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-032","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Was ist Ambush-Marketing (Trittbrettfahrer-Marketing)?","a":"Ein Unternehmen ohne offizielle Sponsorenrechte erweckt den Eindruck, mit einem Sportereignis verbunden zu sein, um ohne Sponsoringkosten von dessen Aufmerksamkeit und Image zu profitieren.","e":"Ambush heißt Hinterhalt: Man schleicht sich ans Event heran – mit Werbung im Stadionumfeld, Anspielungen in Spots, Fanaktionen oder Athletenwerbung. Veranstalter schützen ihre Sponsoren durch Markenrechte, Werbeverbote im Umfeld und strenge Regeln für Teilnehmer. Beispiel: Ein Getränkehersteller ist kein offizieller WM-Sponsor, macht aber während des Turniers Werbung mit Fußballbildern und dem Slogan „Sommer der Fans“, sodass viele ihn trotzdem mit der WM verbinden.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-033","thema":"Q4.1","kapitel":"Sponsoring und Vermarktung","q":"Welche Formen der Werbung im und mit Sport gibt es?","a":"• Werbung am Sportler (Trikot, Helm, Startnummer)\n• Ausrüsterverträge\n• Werbung an der Sportstätte (Bande, Namensrechte)\n• Testimonialwerbung\n• Werbespots, Sendungssponsoring\n• Digitale Werbung (Social Media, Influencer, virtuelle Werbung)","e":"Werbung ist im Profisport fast überall zu finden, auch als digitale LED-Bande oder virtuell ins TV-Bild eingeblendet. Beispiel: Ein Biathlet trägt das Logo seines Sponsors auf der Mütze, die er nach dem Rennen extra in die Kamera hält. Genau dafür bekommt er Geld, denn dieses Bild wird im Fernsehen und in Zeitungen gezeigt.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-034","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Erörtere, ob das Fernsehen die Berichterstattung über eine Sportart (z. B. die Tour de France) einstellen sollte, solange es gehäuft zu Dopingverstößen kommt.","a":"Pro Ausstieg:\n• TV-Geld finanziert dopingbelastetes System\n• Druck über Sponsoren\n• Glaubwürdigkeit, Vorbild\nKontra:\n• bestraft saubere Sportler\n• Informationsauftrag\n• kritischer Journalismus deckt Doping auf\nUrteil: begründet abwägen","e":"Das Fernsehen ist für viele Sportarten die wichtigste Geldquelle, also ist ein Ausstieg ein starkes Druckmittel – gerade öffentlich-rechtliche Sender haben eine Vorbildfunktion. Eine Kollektivstrafe trifft aber auch Nachwuchs und Breitensport; ein Mittelweg ist kritische statt reiner Jubelberichterstattung. Beispiel: Als ARD und ZDF 2007 wegen Dopingfällen vorübergehend aus der Live-Übertragung der Tour de France ausstiegen, zogen sich danach auch Sponsoren aus dem deutschen Radsport zurück.","quelle":"L22.5","typ":"kern"},{"id":"q4.1-035","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Welchen Einfluss haben Werbung und Medien auf Körperideale und welche Folgen kann das haben?","a":"• Werbung zeigt sehr schlanke Frauen, austrainierte Männer als Ideal\n• Folgen: gestörtes Essverhalten bis Essstörungen, auch im Nachwuchsleistungssport\n• Besonders gefährdet: gewichtsbezogene Sportarten","e":"Medien zeigen uns ständig, wie ein „perfekter“ Körper angeblich aussieht – wer sich daran misst, kann krank werden; das propagierte Frauenideal ist gesundheitlich abzulehnen. Gefährdet sind v. a. Sportarten mit Gewichtsklassen, ästhetische Sportarten und Skispringen. Beispiel: Eine Studie zum olympischen Nachwuchsleistungssport (GOAL) fand bei einem großen Teil der befragten jugendlichen Kaderathleten ein gestörtes Ernährungsverhalten.","quelle":"L23.2","typ":"kern"},{"id":"q4.1-036","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Welche Funktionen erfüllt die Sportberichterstattung in den Medien?","a":"• Information\n• Unterhaltung\n• Kritik und Kontrolle\n• Meinungsbildung\n• Integration und Identifikation\n• Sozialisation und Vorbild\n• Ökonomische Funktion","e":"Sportberichte sollen nicht nur Tore zeigen, sondern auch kritisch hinschauen (Doping, Korruption, Funktionäre). Sie bieten Gesprächsstoff und Zugehörigkeit, vermitteln Werte und regen zum Sporttreiben an; ökonomisch liefern sie Werbeumfeld und Reichweite. Beispiel: Dieselbe Sendung kann am Samstag die Bundesligatore unterhaltsam zusammenfassen und in einer Dokumentation über systematisches Doping in einer Sportart berichten.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-037","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Welche typischen Merkmale und Kritikpunkte werden der Sportberichterstattung zugeschrieben?","a":"• Fokus auf wenige Sportarten (Fußball)\n• Erfolgs- und Ergebnisorientierung\n• Personalisierung, Boulevardisierung\n• Nationale Perspektive\n• Frauensport unterrepräsentiert\n• Wenig kritischer Journalismus\n• Interessenkonflikt als Rechteinhaber","e":"Sportjournalismus wird oft als „Jubeljournalismus“ kritisiert: Fokus auf Sieger und Rekorde, Emotionalisierung und Dramatisierung, Privates der Stars, teils Nationalismus, stereotype Darstellung von Sportlerinnen und zu viel Nähe zu den Akteuren („Hofberichterstattung“). Beispiel: Ein Sender, der viel Geld für die Rechte an einem Turnier bezahlt hat, hat wenig Interesse daran, das Turnier durch kritische Berichte über die Vergabe oder Menschenrechte schlechtzureden.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-038","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Erläutere, wie Medien als „Gatekeeper“ die Wahrnehmung von Sportarten steuern.","a":"• Gatekeeping: Medien wählen aus, worüber berichtet wird.\n• Agenda-Setting: Häufig Berichtetes gilt als wichtig.\n• Folge: präsente Sportarten gewinnen Mitglieder und Sponsoren, andere bleiben unsichtbar.","e":"Medien sind wie ein Türsteher. Sie wählen nach Nachrichtenfaktoren: Prominenz, nationale Beteiligung, Erfolg, Emotion, Konflikt, Überraschung, Bildhaftigkeit, Quotenerwartung. So beeinflussen sie indirekt Popularität und wirtschaftliche Entwicklung von Sportarten. Beispiel: Gewinnt ein deutsches Team überraschend eine Medaille in einer Randsportart, wird plötzlich ausführlich berichtet, und Vereine melden danach mehr Anfragen von Kindern.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-039","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Wie verändern Internet, Streaming und soziale Medien die Beziehung zwischen Sport, Medien und Wirtschaft?","a":"• Streamingdienste konkurrieren um Rechte; auch Randsportarten sichtbar\n• Zersplitterung: mehrere Abos\n• Soziale Medien: direkter Fankontakt; Sportler als Medienmarken\n• Risiken: Hass, Desinformation","e":"Früher brauchte ein Sportler die Zeitung, um bekannt zu werden, heute reicht ein Smartphone – Journalisten sind als Vermittler nicht mehr nötig, Vereine kontrollieren ihre Berichterstattung teils selbst. Live-Sport wird teurer; Randsportarten profitieren von geringen Kosten und Verbandsplattformen. Genutzt wird interaktiv (Second Screen, Clips, Highlights auf Abruf). Beispiel: Ein Fußballprofi hat auf Instagram mehrere Millionen Follower und bekommt für einen einzelnen Werbepost Geld, ohne dass ein Sender beteiligt ist.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-040","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Was ist E-Sport und inwiefern ist er ein Medienphänomen?","a":"Wettkampfmäßiges Spielen von Computer- und Videospielen.\nMedienphänomen: über das Internet entstanden, v. a. per Livestream verfolgt; finanziert durch Sponsoring, Werbung, Medienrechte; junge Zielgruppe.\nOb E-Sport „Sport“ ist, ist umstritten.","e":"E-Sport zeigt, wie sehr Medien und Wirtschaft „Sport“ prägen können: Ligen, Turniere und Events in großen Hallen, Preisgelder; die Rechte an den Spielen liegen bei den Publishern. Gegen den Sportbegriff sprechen geringe Bewegung, kommerzielle Spielinhalte und teils Gewalt; der DOSB trennt virtuelle Sportarten (Simulationen realer Sportarten) von anderen Spielen. Beispiel: Ein großes Finale eines Strategiespiels wird weltweit von Millionen im Livestream geschaut, und Sportartikelhersteller und Getränkefirmen sponsern die Teams, weil sie so junge Zielgruppen erreichen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-041","thema":"Q4.1","kapitel":"Sportberichterstattung","q":"Wie nutzen Menschen Sport in den Medien und welche Motive stehen dahinter?","a":"Formen: Live-Übertragungen, Zusammenfassungen, Print/Online, soziale Medien\nMotive:\n• Spannung, Unterhaltung, Emotionen\n• Identifikation\n• soziale Motive (gemeinsam schauen)\n• Information\n• Entspannung, Eskapismus\n• ästhetischer Genuss","e":"Menschen schauen Sport aus ganz verschiedenen Gründen (Nutzen-Ansatz) und über viele Kanäle: Liveticker, Podcasts, Fanforen, Second Screen. Identifikation bezieht sich auf Team, Region, Nation oder Stars. Beispiel: Beim Public Viewing einer WM interessieren sich manche kaum für Taktik, sie wollen einfach mit Freunden feiern und mitfiebern. Der Fachmann dagegen schaut wegen der taktischen Details zu.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-042","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Wie beeinflusst die Kommerzialisierung des Sports nach Pilz (1995) das faire Verhalten von Sportlern?","a":"• Kommerzialisierung erzeugt hohen Erfolgsdruck.\n• Unfairness („faires Foul“) wird subjektiv sinnhaft.\n• Fairnessappelle wirken kaum, solange der Druck nicht sinkt – Fairplay einzufordern sei sonst unredlich.","e":"Wenn es um Millionen, Verträge und Titel geht, wird der Sieg wichtiger als die Fairness; in Konfliktsituationen fällt die faire Entscheidung besonders schwer. Pilz sagt: Schuld ist nicht nur der Spieler, sondern das System. Beispiel: Der türkische Verteidiger Alpay ließ bei der EM 1996 einen Gegner fair laufen, wurde danach von den Medien als „Weichling“ kritisiert und fiel später durch grobe Fouls auf.","quelle":"L19.3","typ":"kern"},{"id":"q4.1-043","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche Rolle spielen Medien für Fairness und Aggression im Sport?","a":"• Kritik der Medien kann Unfairness fördern\n• „Psychologische Kriegsführung“ verletzt die Chancengleichheit\n• ISSP: keine Verherrlichung von Aggression\n• Positiv: Fairnesskampagnen, Berichte über faire Gesten","e":"Medien sind wie ein Verstärker: Sie können Fairness feiern oder Härte verherrlichen. Psychologische Kriegsführung zählt zu den verdeckten betrügerischen Handlungen. Beispiel: Wird ein brutales Foul in Zeitlupe zehnmal gezeigt und als „echtes Kämpferherz“ gelobt, lernen junge Zuschauer daraus etwas Falsches.","quelle":"L19.2","typ":"kern"},{"id":"q4.1-044","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Warum ist Chancengleichheit im kommerzialisierten Sport problematisch?","a":"• Chancengleichheit = gleiche Bedingungen im Wettkampf und in der Vorbereitung\n• Ressourcen (Budget, Material, Training) sind sehr ungleich verteilt → strukturelle Vorteile der Reichen\n• Ausgleich z. B. durch Draft-System (NBA)","e":"Auf dem Platz gelten für alle die gleichen Regeln, aber vor dem Spiel ist das Geld ungleich verteilt. Beim Draft dürfen die schwächsten Teams der Vorsaison zuerst die besten Nachwuchsspieler wählen (nach Schwier, 2001). Beispiel: Ein reicher Verein kann die besten Spieler kaufen, ein kleiner nicht. In den US-Ligen versucht man das mit Draft und Gehaltsobergrenzen auszugleichen, damit die Liga spannend bleibt.","quelle":"L19.3","typ":"kern"},{"id":"q4.1-045","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Wie kann laut Buch ein Gegengewicht zur egoorientierten Ausrichtung des kommerziellen Showsports geschaffen werden?","a":"• Bessere technisch-taktische Ausbildung statt nur moralischer Appelle\n• Grenze zwischen assertivem und aggressivem Verhalten lernen\n• Aufgabenorientierung statt Egoorientierung fördern","e":"Der ethisch gute Sport ist weit von der Realität des Showsports entfernt. Wer technisch gut ist, braucht keine Fouls. Assertiv heißt: sich regelgerecht durchsetzen. Aufgabenorientiert heißt: Leistung als Bemühen, die eigene Grenze zu erreichen, statt nur andere zu besiegen. Beispiel: Ein Verteidiger, der automatisiert sauber tackelt, greift auch im Stress auf faire Lösungen zurück, und Dirk Nowitzki punktete lieber mit seinem Fadeaway-Wurf vom Gegner weg als mit überhartem Körpereinsatz.","quelle":"L19.4","typ":"kern"},{"id":"q4.1-046","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Wie wirken Sport, Politik, Wirtschaft und Medien bei Fairness- und Anti-Doping-Kampagnen zusammen und wie ist deren Erfolg einzuschätzen?","a":"• Kampagnen (z. B. DOSB „Gemeinsam gegen Doping“): Aufklärung, moralischer Appell\n• Akteure aus Sport, Politik, Wirtschaft; Verbreitung durch Medien\n• Ergänzt durch Strafen und Forschung\n• Erfolg fraglich, Erfolge im Kleinen","e":"Anlass sind zunehmende Fairnessverstöße wie Doping, Schwalben und instrumentelle Aggression; Schulen, Vereine und Verbände setzen auf Fairnessprojekte. Kampagnen sind gut gemeint, ändern aber wenig, wenn das System weiter Siege belohnt. Beispiel: Ein Plakat „Sauber gewinnen“ hilft wenig, wenn der Sponsorvertrag nur bei Medaillen verlängert wird. Im Kleinen klappt es besser, etwa bei einer Kinderliga mit klarem Verhaltenskodex für Spieler, Trainer und Eltern.","quelle":"L19.4","typ":"kern"},{"id":"q4.1-047","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Erläutere die beiden soziologischen Erklärungsansätze für Doping (Homo sociologicus und Homo oeconomicus) mit Blick auf wirtschaftliche Anreize.","a":"• Homo sociologicus: Doping als Systemproblem; der Athlet unterwirft sich den Erwartungen von Verband, Sponsoren, Medien\n• Homo oeconomicus: Athlet handelt rational nach Kosten-Nutzen-Abwägung (Prämien, Verträge vs. Strafe, Gesundheit)","e":"Einmal ist der Sportler Opfer des Systems mit eingeschränkter Entscheidungsfreiheit (methodologischer Kollektivismus), einmal ein nüchterner Rechner (methodologischer Individualismus). Die Soziologie betrachtet Doping zunächst amoralisch und fragt, welche Bedingungen es unwahrscheinlich machen. Beispiel: Ein Radprofi, dessen Vertrag nur bei Top-Platzierungen verlängert wird, kann als Homo oeconomicus abwägen: Bringt Doping mehr Geld, als das Risiko einer Sperre kostet? Der Homo-sociologicus-Ansatz betont den Druck des Umfelds.","quelle":"L22.4","typ":"kern"},{"id":"q4.1-048","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche Rolle spielen die Massenmedien bei der Bewertung von Dopingfällen und warum ist die öffentliche Verurteilung einzelner Sportler aus soziologischer Sicht problematisch?","a":"• Medien bewerten Doping moralisch und stellen den einzelnen Sportler an den Pranger.\n• Soziologisch ein Systemproblem: Erfolgsdruck durch Verbände, Sponsoren, Medien, Publikum – Medien sind selbst Teil des Systems.","e":"Die Medien jubeln über Rekorde und verurteilen dann den Gedopten – ein Widerspruch, weil sie selbst nach Sensationen verlangen. Der Sportler trägt allein Rufverlust und finanzielle Nachteile. Gerecht wäre, Umfeld und Strukturen einzubeziehen, ohne den Einzelnen freizusprechen. Beispiel: Ein Langläufer wird erwischt und ist in allen Schlagzeilen, über Trainer, Ärzte und Verbandsfunktionäre wird dagegen kaum gesprochen.","quelle":"L22.4","typ":"kern"},{"id":"q4.1-049","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche intervenierenden Bedingungen machen Doping nach Bette und Schimank (2006) unwahrscheinlicher (Moraläquivalente)?","a":"• Angst vor Krankheit, Sucht, Schäden\n• Angst vor Entdeckung, Diffamierung\n• Funktionierendes Kontrollsystem\n• Sozial-moralisches Milieu\n• Außergewöhnliches Talent\n• Relative Verletzungsfreiheit\n• Positionsalternativen (Herkunft, Ausbildung)\n• Kein Zugang zu „Doping-Gruppen“\n• Geldknappheit","e":"Diese Bedingungen ersetzen sozusagen die Moral: Auch ohne gute Absicht wird Doping weniger wahrscheinlich. Wirtschaftlich wichtig sind vor allem die Positionsalternativen. Beispiel: Eine Athletin mit abgeschlossenem Studium ist nicht existenziell auf Sponsorengeld angewiesen und hat daher weniger Grund, für den Erfolg alles zu riskieren.","quelle":"L22.4","typ":"kern"},{"id":"q4.1-050","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Wo liegen die Grenzen des Chancengleichheitsarguments gegen Doping aus ökonomischer Sicht?","a":"• Ungleiche ökonomische und infrastrukturelle Bedingungen\n• Unterschiedlich strenge Kontrollen je Land\n→ Doping wird subjektiv als „Ausgleich“ legitimiert\n• Freigabe brächte auch keine Chancengleichheit (Reiche dopen effizienter)","e":"Chancengleichheit ist im Spitzensport schon ohne Doping nicht gegeben (Einkommen, Trainingsstätten, nationale Förderung). Bei Freigabe wäre zudem ausgeschlossen, wer nicht dopen will. Das Argument trägt nur, wenn Kontrollen international wirksam sind und Dopingsünder sehr wahrscheinlich bestraft werden. Beispiel: Ein Sportler aus einem Land mit strengen Kontrollen fühlt sich benachteiligt, wenn Konkurrenten aus Ländern mit laschen Kontrollen antreten, und redet sich Doping als „Ausgleich“ schön.","quelle":"L22.3","typ":"kern"},{"id":"q4.1-051","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche Interessen haben Verband, Sponsor, Trainer und Mediziner im Umfeld eines jungen Leistungssportlers und was würde sich ändern, wenn eine Diskussion über Doping öffentlich (z. B. im Fernsehen) stattfände?","a":"• Verband: Erfolge (Fördergelder), guter Ruf\n• Sponsor: Erfolge, v. a. guter Ruf\n• Trainer: Erfolg des Sportlers und eigener\n• Mediziner: sauberer Aufbau oder „unterstütztes“ Training\nÖffentlich: alle sozial erwünscht gegen Doping, Druck wird verschwiegen.","e":"Hinter verschlossenen Türen zählt oft der Erfolg, vor der Kamera die Moral. Der Sportler selbst will sportlichen Erfolg, z. B. die Weltspitze. Medienöffentlichkeit erzeugt zwar Kontrolle, aber auch eine Fassade. Beispiel: Ein Sponsor erwartet intern Top-Platzierungen, würde öffentlich aber nie etwas anderes sagen als „Wir stehen für sauberen Sport“. Das zeigt, wie stark wirtschaftliche Interessen im Verborgenen wirken können.","quelle":"L22.4","typ":"kern"},{"id":"q4.1-052","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche Chancen bietet die Kommerzialisierung für den Sport?","a":"• Finanzierung des Leistungssports (Profis)\n• Bessere Trainings- und Betreuungsbedingungen\n• Popularität, Vorbilder\n• Große Veranstaltungen\n• Arbeitsplätze\n• Weiterentwicklung von Material\n• Querfinanzierung von Nachwuchs/Breitensport","e":"Ohne Geld gäbe es keinen Profisport in seiner heutigen Form: Athleten können vom Sport leben, Infrastruktur, Medizin und Wissenschaft werden finanziert, und Vorbilder motivieren zum eigenen Sporttreiben. Beispiel: Durch Sponsoren kann eine Sportlerin Vollzeit trainieren, statt nebenbei arbeiten zu müssen. Ein Erfolg bei Olympia begeistert dann Kinder, die sich im Verein anmelden.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-053","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche Risiken und Probleme sind mit der Kommerzialisierung und Medialisierung des Sports verbunden?","a":"• Erfolgsdruck: Doping, Unfairness, Überlastung\n• Wettbewerbsverzerrung durch ungleiche Finanzkraft\n• Kluft Profi-/Breitensport, Rand-/Mediensportarten\n• Autonomieverlust\n• Korruption, Manipulation\n• Entfremdung der Fans\n• Sport als Ware\n• Instrumentalisierung des Nachwuchses","e":"Das Geld bringt nicht nur Vorteile, es verändert auch den Charakter des Sports: Medien und Sponsoren bestimmen Termine und Regeln mit, Ticketpreise und Anstoßzeiten vergraulen Fans, Kinder werden früh spezialisiert. Beispiel: Wenn ein Verein Jahr für Jahr Meister wird, weil er ein Vielfaches des Budgets der Konkurrenz hat, verliert die Liga an Spannung, die eigentlich ihr wichtigstes Verkaufsargument ist.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-054","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Erläutere den Zusammenhang zwischen Kommerzialisierung, Medien und Doping.","a":"• Medien und Wirtschaft belohnen v. a. Sieger\n• Verträge und Prämien hängen am Erfolg → Anreiz zum Doping\n• Dichte Wettkampfkalender erhöhen Druck\n• Doppelmoral: Rekorde fordern, Doping verurteilen","e":"Wenn nur der Sieger Geld bekommt, lohnt sich Betrug wirtschaftlich – wenige Hundertstel entscheiden über große Einkommensunterschiede. Langfristig schadet Doping aber dem ganzen System, weil aufgedeckte Fälle Sponsoren und Medien vertreiben. Beispiel: Ein Radfahrer, der knapp an den Top-Platzierungen scheitert, verliert womöglich seinen Profivertrag. Für ihn steht also die ganze Existenz auf dem Spiel, nicht nur eine Medaille.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-055","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Was versteht man unter Wett- und Spielmanipulation und warum gefährdet sie den Sport?","a":"• Spielmanipulation: absichtliche, regelwidrige Beeinflussung von Verlauf oder Ergebnis für einen (meist finanziellen) Vorteil\n• Wettbetrug: Manipulation, um darauf zu wetten\nGefahr: zerstört Ergebnisoffenheit und Glaubwürdigkeit","e":"Sport lebt davon, dass niemand das Ergebnis kennt – das macht ihn für Zuschauer, Medien und Sponsoren attraktiv. Beteiligt sind Spieler, Schiedsrichter oder Funktionäre, oft gesteuert von kriminellen Netzwerken; Ursachen sind riesige Online-Wettmärkte und geringe Bezahlung in unteren Ligen. Auch Einzelereignisse (Karten, Ecken) werden manipuliert. In Deutschland ist das strafbar. Beispiel: Ein Schiedsrichter, der gegen Geld Elfmeter pfeift, betrügt nicht nur den Gegner, sondern alle Zuschauer, Wettenden und Sponsoren.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-056","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Erläutere die Situation von Randsportarten im magischen Dreieck (Teufelskreis der Medienabwesenheit).","a":"Teufelskreis: wenig Medienpräsenz → geringe Bekanntheit → keine Sponsoren → schlechtere Bedingungen, weniger Erfolge → weniger Medieninteresse.\nAuswege: telegenere Formate, Streaming/Social Media, Förderung","e":"Randsportarten stecken oft in einer Abwärtsspirale mit kaum Profis und wenig Nachwuchs. Gegenstrategien sind Regeländerungen, Eventformate, Personalisierung, Multisport-Events und öffentliche Förderung. Bei medienstarken Sportarten verstärkt sich der Erfolg dagegen selbst (Matthäus-Effekt: „Wer hat, dem wird gegeben“). Beispiel: Ein Weltklasse-Kanute ist trotz Olympiamedaille kaum bekannt und findet keinen Sponsor. Gleichzeitig erhält ein durchschnittlicher Fußballprofi mehr Werbeangebote, weil Fußball jeden Tag in den Medien ist.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-057","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Wie wirkt sich die Kommerzialisierung auf das Verhältnis von Profisport und Breitensport aus?","a":"• Geld fließt in wenige Spitzenligen; Breitensport ist ehrenamtlich und beitragsfinanziert → Kluft wächst\n• Positiv: Vorbilder, Mitgliederzuwachs\n• Negativ: Erfolgsdruck, Konkurrenz durch kommerzielle Anbieter","e":"Oben ist Geld im Überfluss, unten fehlt es oft an Übungsleitern, Hallenzeiten und Sanierungsmitteln; der Breitensport lebt von Beiträgen und öffentlichen Mitteln. Teils fördern Profiligen über Abgaben und Programme. Der Breitensport übernimmt aber auch Profivorbilder mit Erfolgsdruck, früher Spezialisierung und Unfairness; Fitnessstudios konkurrieren mit Vereinen. Beispiel: Während im Profifußball hohe Ablösesummen gezahlt werden, sucht der Dorfverein händeringend einen Trainer für die F-Jugend und kann den Kunstrasen nicht reparieren.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-058","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Was ist die 50+1-Regel im deutschen Profifußball und welche Bedeutung hat sie im Spannungsfeld von Sport und Wirtschaft?","a":"DFL-Regel: Bei Ausgliederung der Profiabteilung muss der Mutterverein die Stimmenmehrheit (50 % + 1) behalten.\nZiel: Investoreneinfluss begrenzen, Mitbestimmung der Mitglieder sichern.","e":"In anderen Ländern können Milliardäre oder Staatsfonds einen Verein einfach kaufen; in Deutschland sollen die Mitglieder das letzte Wort behalten. Befürworter sehen Schutz vor Abhängigkeit, Tradition und Fankultur; Kritiker beklagen weniger Kapital und internationale Wettbewerbsfähigkeit. Für langjährige Förderer gab es Ausnahmen. Die Regel zeigt den Konflikt zwischen Sport als Gemeinschaftsgut und als Wirtschaftsunternehmen. Beispiel: Ein Investor darf zwar Anteile an der Profi-GmbH eines Vereins kaufen, aber nicht die Mehrheit der Stimmen übernehmen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-059","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche Folgen hat die Kommerzialisierung für Fans und Zuschauer?","a":"• Steigende Kosten (Tickets, mehrere Abos)\n• Anstoßzeiten nach TV-Interessen\n• Eventpublikum statt traditioneller Fans\n• Entfremdung vom Verein\n• Fanproteste\n• Aber: bessere Stadien, mehr Übertragungen, Spitzenspiele","e":"Viele Fans wollen ihren Verein nicht als Produkt sehen. Zerstückelte Spieltage, Spiele unter der Woche und späte Termine erschweren Auswärtsfahrten; Investoren und Namensrechte verstärken die Entfremdung. Beispiel: In deutschen Stadien gab es wiederholt Proteste mit Bannern und Tennisbällen auf dem Rasen gegen den geplanten Einstieg eines Investors bei der Vermarktung der Medienrechte.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-060","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche gesundheitlichen und sozialen Folgen kann der kommerzialisierte Spitzensport für Athleten haben?","a":"• Überlastung (dichte Wettkampfkalender)\n• Verletzungen, Schmerzmittel\n• Psychischer Druck\n• Frühe Spezialisierung, vernachlässigte Ausbildung\n• Unsichere Karriere","e":"Körper und Psyche der Sportler sind das Kapital, das im kommerziellen Sport oft übernutzt wird – mit mehr Spielen, Reisen und kurzer Regeneration; der Druck durch Öffentlichkeit und soziale Netzwerke kann bis zu psychischen Erkrankungen führen. Nur wenige verdienen viel. Beispiel: Profifußballer bestreiten in einer Saison mit Liga, Pokal, internationalen Wettbewerben und Länderspielen sehr viele Spiele, Spielergewerkschaften warnen deshalb immer wieder vor Überlastung.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-061","thema":"Q4.1","kapitel":"Folgen und Probleme","q":"Welche Vorbildfunktion haben mediale Sportstars und welche Probleme können sich daraus ergeben?","a":"Positiv:\n• Motivation zum Sporttreiben\n• Werte (Leistung, Fairness, Teamgeist)\n• gesellschaftliches Engagement\nProblematisch:\n• Nachahmung unfairen Verhaltens\n• Werbung für Ungesundes/Glücksspiel\n• einseitige Körperideale\n• Konsumdruck","e":"Kinder machen nach, was sie bei ihren Idolen sehen, im Guten wie im Schlechten – vom Engagement gegen Rassismus bis zu Respektlosigkeit gegenüber Schiedsrichtern oder teurer Markenkleidung. Beispiel: Nach einer großen Fußball-WM melden Vereine mehr Kinder an. Gleichzeitig beobachten Jugendtrainer, dass Kinder Jubelposen und leider auch Schwalben ihrer Vorbilder kopieren.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-062","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Was ist Sportökonomie und mit welchen Fragen beschäftigt sie sich?","a":"Teildisziplin der Sport- und Wirtschaftswissenschaft, die wirtschaftliche Aspekte des Sports untersucht: Finanzierung und Vermarktung, volkswirtschaftliche Bedeutung, Märkte (Medienrechte, Spieler), Kosten-Nutzen von Großevents.","e":"Sportökonomie schaut auf den Sport mit der Brille eines Ökonomen. Sie untersucht auch Arbeitsmarkt, Sponsoringmärkte sowie Organisationsformen (Verein, Verband, Unternehmen) und Wettbewerbsregeln, etwa die Ausgeglichenheit einer Liga. Beispiel: Eine sportökonomische Studie könnte untersuchen, ob eine Stadt durch ein neues Stadion wirklich mehr Steuereinnahmen und Arbeitsplätze gewinnt oder ob nur Geld aus anderen Freizeitbereichen umgelenkt wird.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-063","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Inwiefern ist Sport ein bedeutender Wirtschaftsfaktor? Nenne die wichtigsten Wirtschaftsbereiche.","a":"• Sportartikelindustrie, Handel\n• Kommerzielle Anbieter (Fitnessstudios)\n• Sporttourismus\n• Profisport, Veranstaltungen\n• Medien, Werbung, Sponsoring\n• Sportstätten\n• Gesundheitswesen\n• Wetten, E-Sport\n• Dienstleistungen\nSport sichert viele Arbeitsplätze und einige Prozent des BIP.","e":"Sport ist viel mehr als die Bundesliga. Seine Wirtschaftsleistung wird in Deutschland über das Sportsatellitenkonto auf wenige Prozent des Bruttoinlandsprodukts geschätzt – vergleichbar mit großen Industriezweigen. Beispiel: Wer im Winter Ski fährt, gibt Geld für Ausrüstung, Skipass, Hotel, Anreise und Essen aus. Daran verdienen Händler, Liftbetreiber, Hotels und Gastronomie, ohne dass ein einziges Profispiel stattfindet.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-064","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Welche Rolle spielt die Sportartikelindustrie im Sport und welche Kritik gibt es?","a":"Rolle: globale Ausrüster und Sponsoren, treiben Innovationen und Trends, machen Sport zum Lifestyle-Gut.\nKritik:\n• Niedriglohnproduktion\n• „Technodoping“\n• Konsumdruck","e":"Sportartikelhersteller verkaufen nicht nur Schuhe, sondern ein Lebensgefühl – auch an Nicht-Sportler. Verbände müssen bei neuem Material oft erst nachträglich Regeln anpassen. Beispiel: Neue Laufschuhe mit Carbonplatte haben die Bestzeiten im Straßenlauf deutlich verbessert, sodass der Leichtathletik-Weltverband Regeln für erlaubte Schuhe einführen musste.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-065","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Unterscheide gemeinnützigen Vereinssport und kommerzielle Sportanbieter.","a":"Verein:\n• gemeinnützig, Mitglieder\n• Beiträge, Zuschüsse\n• Ehrenamt, Mitbestimmung\n• breites Angebot, soziale Funktionen\nKommerzieller Anbieter:\n• gewinnorientiert, Kunden\n• Preise, Verträge\n• hauptamtlich, flexibel\n• Trends, zahlungskräftige Zielgruppen","e":"Im Verein ist man Mitglied und gestaltet mit, im Studio ist man Kunde. Vereine bieten Wettkampfsport, Integration und Gemeinschaft zu günstigen Beiträgen; Studios setzen auf Fitness, Gesundheit, Figur und Kundenorientierung. Beispiel: Im Turnverein trainiert die Übungsleiterin ehrenamtlich eine Kindergruppe für einen kleinen Beitrag, im Fitnessstudio kann man rund um die Uhr trainieren, zahlt aber deutlich mehr.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-066","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Welche Bedeutung hat das Ehrenamt für die Ökonomie des Sports?","a":"• Organisierter Sport beruht großteils auf Ehrenamt (Vorstände, Trainer, Schiedsrichter).\n• Hoher ökonomischer Wert → niedrige Beiträge, flächendeckendes Angebot\n• Probleme: sinkende Bindungsbereitschaft, Überlastung, Bürokratie","e":"Ohne Freiwillige würde der Vereinssport zusammenbrechen; ihre Arbeit müssten sonst Staat oder Mitglieder bezahlen. Steigende Anforderungen an Qualifikation und Verwaltung schrecken ab. Das Ehrenamt steht im Gegensatz zum bezahlten Spitzensport. Beispiel: Ein Vater, der jeden Samstag das Jugendspiel pfeift und unter der Woche das Training leitet, leistet unbezahlt Arbeit, die bei einem kommerziellen Anbieter mehrere hundert Euro im Monat kosten würde.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-067","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Welche Kosten und welchen Nutzen haben Sportgroßveranstaltungen (z. B. Olympische Spiele, Weltmeisterschaften) für Ausrichter?","a":"Nutzen:\n• Besucherausgaben, Tourismus\n• Infrastruktur\n• Image, Standortmarketing\n• „Feel-Good-Effekt“\nKosten:\n• sehr hohe Kosten für öffentliche Haushalte\n• Nachnutzungsprobleme\n• Umwelt, steigende Mieten\nLangfristige Effekte meist geringer als versprochen.","e":"Großveranstaltungen werden oft mit großen Wirtschaftsversprechen beworben, die sich selten erfüllen: Arbeitsplätze entstehen meist nur vorübergehend, Kosten explodieren, Einnahmen fließen großteils an die Verbände, ungenutzte Stadien werden zu „weißen Elefanten“, normale Touristen bleiben fern. Beispiel: Nach manchen Olympischen Spielen verfielen teure Wettkampfstätten, weil niemand sie danach brauchte. In Deutschland lehnten Bürger in München und Hamburg Olympiabewerbungen per Bürgerentscheid bzw. Referendum ab.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-068","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Welche gesellschaftlich-politischen Probleme werden bei der Vergabe von Sportgroßveranstaltungen diskutiert?","a":"• Korruption, intransparente Vergabe\n• Vergabe an Staaten mit Menschenrechtsproblemen\n• „Sportswashing“: Imagepolitur durch Sport\n• Gigantismus, fehlende Nachhaltigkeit\n• Neutralität des Sports vs. Instrumentalisierung","e":"Großevents sind auch Politik. Kritisiert werden schlechte Arbeitsbedingungen beim Stadionbau und eingeschränkte Pressefreiheit; Staaten nutzen Events oder Vereinsbeteiligungen, um von Missständen abzulenken. Verbände betonen dagegen Neutralität und Chancen zur Öffnung. Beispiel: Bei der Vergabe einer Fußball-WM an einen Staat mit Menschenrechtskritik diskutierten Medien, Fans und Sponsoren weltweit, ob man dort spielen und werben darf, und einige Spieler setzten öffentlich Zeichen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-069","thema":"Q4.1","kapitel":"Sport als Wirtschaftsfaktor","q":"Warum verdienen wenige Spitzensportler so außergewöhnlich viel Geld? Erkläre ökonomisch.","a":"• Superstar-Ökonomie: Medien bündeln die Nachfrage auf wenige Top-Akteure\n• „The winner takes it all“: kleine Leistungsunterschiede, große Einkommensunterschiede\n• Wettbewerb der Vereine um knappe Talente\n• Werbeverträge (Spieler als Marke)","e":"Es gibt nur wenige Weltstars, aber viele Vereine wollen sie haben, deshalb steigt ihr Preis; die Einnahmen aus Medienrechten und Sponsoring werden so an die Spieler weitergegeben. Seit dem Bosman-Urteil (1995) können Spieler nach Vertragsende frei wechseln. Die große Mehrheit der Sportler verdient dagegen wenig oder nichts. Beispiel: Der Weltranglistenerste im Tennis verdient ein Vielfaches des Hundertsten, obwohl der Leistungsunterschied auf dem Platz relativ klein ist.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-070","thema":"Q4.1","kapitel":"Leistungssport und Gesellschaft","q":"Erläutere das Leistungsprinzip im Sport und seine Beziehung zur Gesellschaft.","a":"• Status und Belohnung nach erbrachter Leistung; im Sport objektiv messbar und unter Chancengleichheit vergleichbar\n• Sport als Spiegel/Modell der Leistungsgesellschaft\n• Kritik: Verabsolutierung von Sieg, Doping, Ausgrenzung Schwächerer","e":"Im Sport sieht man schwarz auf weiß, wer der Beste ist (Zeit, Weite, Punkte) – er verkörpert Anstrengung, Disziplin, Konkurrenz und Aufstieg durch eigene Leistung. Kritisiert wird, dass andere Sinnperspektiven wie Gesundheit, Spaß und Gemeinschaft zu kurz kommen; Gegenmodelle sind Freizeit-, Gesundheits- und Trendsport. Beispiel: Eine 100-m-Zeit ist eindeutig, im Beruf oder in der Schule ist Leistung viel schwerer zu messen. Deshalb gilt der Sport oft als Vorbild für „ehrlichen“ Wettbewerb.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-071","thema":"Q4.1","kapitel":"Leistungssport und Gesellschaft","q":"Welche Funktionen erfüllt der Spitzensport für die Gesellschaft (Begründung staatlicher Förderung)?","a":"• Repräsentation\n• Identifikation, Integration\n• Vorbild\n• Unterhaltung\n• Wirtschaft\n• Wissenschaft (Erkenntnisse für alle)\n• Zugpferd für den Breitensport","e":"Der Staat fördert den Spitzensport, weil er sich davon mehr verspricht als nur Medaillen – etwa Zusammengehörigkeitsgefühl, Nachwuchsgewinnung und Erkenntnisse aus Trainingswissenschaft und Sportmedizin. Beispiel: Eine erfolgreiche Heim-Weltmeisterschaft kann ein ganzes Land für Wochen begeistern, viele Menschen zum Sporttreiben bewegen und das Bild des Gastgeberlandes im Ausland verbessern.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-072","thema":"Q4.1","kapitel":"Leistungssport und Gesellschaft","q":"Beschreibe die Strukturen der Spitzensportförderung in Deutschland.","a":"• Bund (BMI) und Länder\n• DOSB, Spitzenverbände\n• Olympia-/Bundesstützpunkte\n• Deutsche Sporthilfe\n• Sportfördergruppen (Bundeswehr, Polizei, Zoll)\n• Eliteschulen des Sports\n• Leistungssportreform 2016","e":"Spitzensportförderung ist ein Netz aus vielen Partnern: Der Bund finanziert Verbände, Trainer und Stützpunkte, die Länder Nachwuchs, Sportschulen und Sportstätten. Stützpunkte bieten Training, medizinische und soziale Betreuung; die Sporthilfe fördert Athleten individuell über Spenden und Sponsoren. Die Reform richtet die Förderung nach Erfolgspotenzial aus (Potenzialanalyse). Beispiel: Eine junge Ruderin besucht eine Eliteschule des Sports, trainiert am Bundesstützpunkt, wird von der Sporthilfe unterstützt und später in eine Sportfördergruppe der Bundeswehr aufgenommen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-073","thema":"Q4.1","kapitel":"Leistungssport und Gesellschaft","q":"Was versteht man unter einer dualen Karriere im Leistungssport und warum ist sie wichtig?","a":"Gleichzeitige Verfolgung von Leistungssport und schulischer, akademischer oder beruflicher Ausbildung.\nWichtig, weil nur wenige vom Sport leben können und Karrieren kurz sind → Absicherung, weniger Druck, Dopingprävention.","e":"Wer nur auf den Sport setzt, hat alles zu verlieren – Karrieren sind kurz und durch Verletzungen gefährdet. Positionsalternativen machen Doping unwahrscheinlicher (Bette & Schimank). Instrumente sind Eliteschulen des Sports, Partnerhochschulen, flexible Studienmodelle und Sportfördergruppen. Beispiel: Ein Hockeynationalspieler studiert parallel Medizin über eine Partnerhochschule des Spitzensports mit gestrecktem Stundenplan. Nach dem Karriereende hat er einen sicheren Beruf und muss nicht um jeden Preis gewinnen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-074","thema":"Q4.1","kapitel":"Leistungssport und Gesellschaft","q":"Erläutere das Pyramidenmodell des Verhältnisses von Breiten- und Spitzensport und nenne Kritikpunkte.","a":"Modell: breite Basis (Breitensport) bringt Talente für die Spitze hervor; die Spitze wirkt als Vorbild zurück.\nKritik:\n• Spitzen- und Breitensport weit auseinander\n• viel Sport ohne Wettkampfbezug\n• Talente werden gezielt gesichtet","e":"Das Bild der Pyramide (Breitensport – Leistungssport – Hochleistungssport) ist einleuchtend, stimmt aber nur teilweise: Ziele, Strukturen und Finanzierung haben sich getrennt, Gesundheits-, Fitness- oder Trendsportler gehören gar nicht zur „Pyramide“, und die Vorbildwirkung von Stars führt nicht unbedingt zu dauerhaftem Sporttreiben. Beispiel: Ein Joggingboom hat kaum Einfluss auf die Zahl deutscher Marathon-Spitzenläufer, weil die meisten Läufer gar keinen Leistungssport anstreben und Spitzenathleten über eigene Förderwege kommen.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-075","thema":"Q4.1","kapitel":"Leistungssport und Gesellschaft","q":"Diskutiere Pro- und Kontraargumente zur staatlichen Förderung des Spitzensports.","a":"Pro:\n• gesellschaftliche Funktionen (Repräsentation, Vorbild)\n• Motivation für Breitensport\n• Hilfe für Sportarten ohne Sponsoren\nKontra:\n• hohe Kosten für Wenige, Breiten-/Schulsport unterfinanziert\n• Instrumentalisierung (Medaillenspiegel)\n• Leistungsdruck, Doping\nFazit: begründete Abwägung","e":"Bei dieser Frage gibt es keine richtige Lösung, sondern gute Argumente auf beiden Seiten. Weitere Pro-Argumente sind wirtschaftliche Effekte und Erkenntnisse für Sportwissenschaft und Medizin; dagegen spricht, dass sich Profisport mit hohen Einnahmen selbst finanzieren könnte. Ein möglicher Mittelweg: Förderung nach klaren Kriterien wie Athletenwohl, Fairness und Anti-Doping. Beispiel: Steuergeld für eine Bobbahn kann man begründen, weil der Bobsport kaum Sponsoren findet, man kann aber auch fragen, ob das Geld in maroden Schulturnhallen nicht besser aufgehoben wäre.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"q4.1-076","thema":"Q4.1","kapitel":"Leistungssport und Gesellschaft","q":"Welche Rolle spielt nationale Identifikation im Mediensport und welche Gefahren birgt sie?","a":"• Medien inszenieren Sport national („wir“, Medaillenspiegel).\n• Positiv: Zusammengehörigkeit, Integration\n• Wirtschaftlich: höhere Quoten, Werbewert\n• Gefahren: Nationalismus, Abwertung anderer, politische Instrumentalisierung","e":"Mit „unserer“ Mannschaft mitzufiebern ist normal und kann verbinden, gerade bei vielfältigen Teams. Problematisch wird es, wenn andere abgewertet werden oder Staaten den Sport als Beweis für ihr politisches System nutzen. Beispiel: Im Kalten Krieg galten Medaillen von BRD und DDR als Beweis für das bessere politische System, was in der DDR auch zu staatlich organisiertem Doping beitrug.","quelle":"Zusatzwissen","typ":"zusatz"},{"id":"vk-001","thema":"VK","kapitel":"Kondition ↔ Koordination","q":"Erläutere, warum sich konditionelle und koordinative Fähigkeiten in der sportlichen Leistung nicht trennen lassen.","a":"• Kondition: v. a. energetisch bestimmt; Koordination: v. a. informationell (Steuerung/Regelung)\n• In jeder Bewegung wirken beide zusammen\n• Schnelligkeit = Mischfähigkeit\n• Ermüdung verschlechtert die Koordination","e":"Zu den konditionellen Fähigkeiten zählen Ausdauer, Kraft und Schnelligkeit. Kraft kann nur so gut umgesetzt werden, wie die Muskeln intra- und intermuskulär koordiniert angesteuert werden; umgekehrt nehmen bei Ermüdung Präzision und Timing ab. Für das Training heißt das: Technik und Koordination im ausgeruhten Zustand üben, Kondition nicht ohne saubere Technik trainieren. Stell dir einen Motor (Kondition) und ein Lenkrad (Koordination) vor: Ein starker Motor nützt nichts, wenn man nicht lenken kann. Beispiel: Ein kräftiger Werfer wirft nur weit, wenn er seine Kraft in der richtigen Reihenfolge (Beine → Rumpf → Arm) einsetzt.","quelle":"Verknüpfung L4/L11/L13/L14","typ":"kern","bezug":["Q1.1","Q3.2","Q2.3"]},{"id":"vk-002","thema":"VK","kapitel":"Kondition ↔ Koordination","q":"Was hat die intramuskuläre und intermuskuläre Koordination mit dem Krafttraining zu tun?","a":"• Intramuskulär: Zusammenspiel der motorischen Einheiten eines Muskels (Rekrutierung, Frequenzierung, Synchronisation)\n• Intermuskulär: Zusammenspiel von Agonist, Antagonist, Synergisten\n• Erste Kraftzuwächse neuronal, später Hypertrophie","e":"Krafttraining ist deshalb immer auch ein Training des Nervensystems und damit koordinatives Training. Am Anfang wird man schnell stärker, obwohl die Muskeln noch nicht dicker sind: Das Gehirn lernt, mehr Muskelfasern gleichzeitig und besser abgestimmt einzusetzen. Beispiel: Nach drei Wochen Kniebeugen schaffst du deutlich mehr Gewicht, ohne sichtbar mehr Muskeln zu haben.","quelle":"Verknüpfung L13/L4","typ":"kern","bezug":["Q2.2","Q3.2"]},{"id":"vk-003","thema":"VK","kapitel":"Training ↔ Biologie","q":"Erkläre, wie das Prinzip der Superkompensation die Trainingsmethoden im Ausdauer-, Kraft- und Schnelligkeitstraining bestimmt.","a":"• Belastung → Ermüdung → Erholung → Superkompensation\n• Nächster Reiz in der Phase erhöhter Leistungsfähigkeit\n• Erholungszeiten je nach Energiesystem/Struktur verschieden → unterschiedliche Pausen und Trainingshäufigkeit","e":"Das entspricht dem Prinzip der optimalen Relation von Belastung und Erholung. Kreatinphosphatspeicher sind schnell wieder aufgefüllt, Glykogen braucht Stunden bis Tage, Muskelstrukturen (Hypertrophie) mehrere Tage. Deshalb gibt es lange vollständige Pausen im Schnelligkeitstraining, lohnende Pausen im Intervalltraining und mehrere Tage Regeneration zwischen Krafteinheiten. Training ist wie ein Bauprojekt: Erst wird abgerissen (Ermüdung), dann stabiler aufgebaut. Zu früher Reiz → Übertraining, zu später → Vorteil verpufft. Beispiel: Nach einem harten Intervalltraining braucht der Körper etwa 1–2 Tage, bevor die nächste harte Einheit sinnvoll ist.","quelle":"Verknüpfung L11/L12/L13/L14","typ":"kern","bezug":["Q1.1","Q2.1","Q2.2","Q2.3"]},{"id":"vk-004","thema":"VK","kapitel":"Training ↔ Biologie","q":"Vergleiche, wie sich die Belastungsnormative (Intensität, Dauer, Umfang, Dichte) zwischen Ausdauer-, Kraft- und Schnelligkeitstraining grundsätzlich unterscheiden.","a":"• Ausdauer: niedrige–hohe Intensität, großer Umfang, keine oder lohnende Pausen\n• Kraft: hohe–maximale Intensität, kurze Reizdauer, Pausen je nach Ziel\n• Schnelligkeit: maximal, sehr kurz, geringer Umfang, lange vollständige Pausen","e":"Die Kraftintensität wird in % der Maximalkraft angegeben. Im Ausdauertraining gibt es bei der Dauermethode keine Pausen, bei der Intervallmethode unvollständige „lohnende“ Pausen. Im Krafttraining macht man wenige Wiederholungen für Maximalkraft, mehr für Kraftausdauer. Im Schnelligkeitstraining sind die Pausen lang, damit jede Wiederholung ohne Ermüdung erfolgt. Erst das Zusammenspiel der Normative entscheidet, welches Energiesystem und welche Anpassung angesprochen wird. Merkhilfe: Ausdauer = lange und oft, Kraft = schwer, Schnelligkeit = kurz, maximal und ausgeruht. Beispiel: 10 × 30 m Sprint mit 3 Minuten Pause trainiert Schnelligkeit, 10 × 400 m mit 90 s Pause dagegen die Ausdauer.","quelle":"Verknüpfung L11/L12/L13/L14","typ":"kern","bezug":["Q1.1","Q2.1","Q2.2","Q2.3"]},{"id":"vk-005","thema":"VK","kapitel":"Training ↔ Biologie","q":"Wie hängen die Wege der Energiebereitstellung mit Ausdauer-, Kraft- und Schnelligkeitsleistungen zusammen?","a":"• Anaerob-alaktazid (bis ca. 6–10 s) → Schnelligkeit, Schnell-, Maximalkraft\n• Anaerob-laktazid (bis ca. 1–2 min) → Schnelligkeits-, Kraft-, Kurzzeitausdauer\n• Aerob (lange Belastung) → Mittel-, Langzeitausdauer\n• Systeme überlappen, eines dominiert","e":"Alaktazid liefern ATP und Kreatinphosphat die Energie, laktazid die Glykolyse ohne ausreichend Sauerstoff, aerob Glykogen und Fette mit Sauerstoff. Welches System dominiert, hängt von Intensität und Dauer ab; Trainingsmethoden werden so gewählt, dass gezielt das gewünschte System beansprucht wird. Der Körper hat verschiedene „Tanks“: einen kleinen Turbo-Tank (Kreatinphosphat), einen Notfall-Tank, der sauer macht (Laktat), und einen großen Spar-Tank (aerob). Beispiel: 100-m-Sprint vor allem Turbo, 400 m stark laktazid, Marathon fast nur aerob.","quelle":"Verknüpfung L12/L13/L14","typ":"kern","bezug":["Q2.1","Q2.3","Q2.2"]},{"id":"vk-006","thema":"VK","kapitel":"Training ↔ Biologie","q":"Welche Rolle spielen die Muskelfasertypen für Ausdauer-, Kraft- und Schnelligkeitsleistungen?","a":"• Typ I: langsam, ermüdungsresistent, oxidativ → Ausdauer\n• Typ II: schnell, kraftvoll, schnell ermüdend, anaerob → Schnelligkeit, Schnell-, Maximalkraft\n• Verteilung weitgehend genetisch","e":"Typ I heißt auch slow twitch und hat viele Mitochondrien, Typ II heißt fast twitch. Die Faserverteilung begrenzt das Leistungspotenzial, besonders in der Schnelligkeit. Training kann die Eigenschaften der Fasern verändern (z. B. verbessert Ausdauertraining die oxidative Kapazität), eine echte Umwandlung ist aber nur begrenzt möglich. Typ I ist wie ein Diesel (sparsam, ausdauernd), Typ II wie ein Sportwagen (schnell, aber durstig). Beispiel: Sprinter haben meist viele Typ-II-Fasern, Marathonläufer viele Typ-I-Fasern.","quelle":"Verknüpfung L13/L14/L12","typ":"kern","bezug":["Q2.2","Q2.3","Q2.1"]},{"id":"vk-007","thema":"VK","kapitel":"Training ↔ Biologie","q":"Wende die Trainingsprinzipien (z. B. progressive Belastungssteigerung, Variation, Individualität) auf das Training aller konditionellen Fähigkeiten an.","a":"• Wirksamer Belastungsreiz (Reizschwelle überschreiten)\n• Progressive Belastungssteigerung (Umfang, Intensität, Dichte)\n• Variation der Belastung\n• Optimale Relation von Belastung und Erholung\n• Individualität und Altersgemäßheit\n• Periodisierung/Zyklisierung","e":"Diese Prinzipien gelten für jede konditionelle Fähigkeit: Ohne überschwelligen Reiz keine Anpassung; steigt die Leistungsfähigkeit, müssen Umfang, Intensität oder Dichte steigen. Variation verhindert Stagnation (z. B. Schnelligkeitsbarriere, Gewöhnung im Krafttraining). Belastung und Erholung folgen der Superkompensation, Belastungen werden an Leistungsstand, Alter und Ziel angepasst, und das Trainingsjahr wird in Phasen gegliedert. Beispiel: Wer immer dieselbe 5-km-Runde im gleichen Tempo läuft, wird irgendwann nicht mehr besser, weil der Reiz nicht mehr steigt.","quelle":"Verknüpfung L11/L12/L13/L14","typ":"kern","bezug":["Q1.1","Q2.1","Q2.2","Q2.3"]},{"id":"vk-008","thema":"VK","kapitel":"Training ↔ Biologie","q":"Wie hängen sportmotorische Tests (Gütekriterien) mit der Trainingssteuerung zusammen?","a":"• Tests erfassen den Ist-Zustand\n• Nur objektive, reliable, valide Tests sind aussagekräftig\n• Nutzen: Ziele setzen, Belastung dosieren, Training überprüfen\n• Regelkreis: testen → planen → trainieren → testen → anpassen","e":"Testergebnisse dienen z. B. dazu, die Belastung als % der Maximalkraft oder über Herzfrequenzbereiche festzulegen. Ein Test ist wie ein Navi-Standort: Ohne ihn weiß man nicht, wo man steht und ob das Training wirkt. Beispiel: Ein Cooper-Test vor und nach acht Wochen Lauftraining zeigt, ob sich die Ausdauer verbessert hat.","quelle":"Verknüpfung L16/L10","typ":"kern","bezug":["Q2.1","Q2.2","Q2.3"]},{"id":"vk-009","thema":"VK","kapitel":"Lernen ↔ Koordination","q":"Erläutere den Zusammenhang zwischen koordinativen Fähigkeiten und dem Lernen sportlicher Bewegungen (Techniken).","a":"• Koordinative Fähigkeiten erleichtern und beschleunigen das Techniklernen\n• Vielseitiges Bewegungslernen verbessert umgekehrt die Koordination\n• Technik = konkrete Lösung; koordinative Fähigkeiten = allgemeine Grundlage","e":"Wer gut ausgeprägte koordinative Fähigkeiten hat, durchläuft die Lernphasen (Grobkoordination → Feinkoordination → variable Verfügbarkeit) schneller. Koordinative Fähigkeiten sind wie das Grundvokabular, Techniken wie einzelne Sätze: Wer viele Wörter kennt, lernt neue Sätze schneller. Beispiel: Wer im Turnen eine gute Orientierungsfähigkeit entwickelt hat, lernt auch einen Salto beim Wasserspringen leichter.","quelle":"Verknüpfung L4/L5","typ":"kern","bezug":["Q3.1","Q3.2"]},{"id":"vk-010","thema":"VK","kapitel":"Lernen ↔ Koordination","q":"Wie hängt das Modell der Bewegungsregulation (Regelkreis, Soll-Ist-Vergleich, Reafferenzen) mit den Lernphasen nach Meinel/Schnabel zusammen?","a":"• Regelkreis: Soll → Ausführung → Reafferenzen → Soll-Ist-Vergleich → Korrektur\n• Grobkoordination: ungenauer Sollwert, v. a. optisch\n• Feinkoordination: kinästhetisch, genauerer Vergleich\n• Variable Verfügbarkeit: automatisiert, schnelle unbewusste Anpassung","e":"Der Sollwert ist das Bewegungsprogramm. In der Grobkoordination werden Rückmeldungen bewusst verarbeitet und nur grob korrigiert. Rückmeldungen kommen über die Analysatoren. Lernen bedeutet also, das Bewegungsprogramm (Soll) und die Verarbeitung der Rückmeldungen zu verbessern; in der variablen Verfügbarkeit gelingt die Anpassung auch unter wechselnden Bedingungen. Am Anfang ist man wie ein Fahranfänger, der auf alles schauen muss, später fährt man „nach Gefühl“. Beispiel: Beim ersten Tennis-Aufschlag schaut man auf jeden Schritt, ein Profi spürt dagegen sofort, ob der Schlag gut war.","quelle":"Verknüpfung L3/L5","typ":"kern","bezug":["Q3.1","Q3.2","Q1.2"]},{"id":"vk-011","thema":"VK","kapitel":"Lernen ↔ Koordination","q":"Begründe, warum die methodische Grundformel der Koordinationsschulung (Fertigkeit + Variation + Druckbedingungen) auch für das Techniktraining fortgeschrittener Lerner wichtig ist.","a":"• Ziel: Technik situationsangepasst anwenden (variable Verfügbarkeit)\n• Variation + Druckbedingungen bereiten genau darauf vor\n• Voraussetzung: Grundform wird beherrscht","e":"So wird der Übergang von der Feinkoordination zur variablen Verfügbarkeit gezielt gefördert. Typische Druckbedingungen sind Zeit-, Präzisions-, Situations-, Komplexitäts- und Belastungsdruck. Wird die Grundform noch nicht beherrscht, überfordern diese Zusatzanforderungen. Im Spiel ist nie alles perfekt: Gegner, Zeitdruck, Müdigkeit, und Training muss genau das simulieren. Beispiel: Ein Basketballer übt den Korbleger nicht nur allein, sondern auch mit Verteidiger, unter Zeitdruck und nach einem Sprint.","quelle":"Verknüpfung L4/L5","typ":"kern","bezug":["Q3.1","Q3.2"]},{"id":"vk-012","thema":"VK","kapitel":"Lernen ↔ Koordination","q":"Erkläre die Bedeutung der Antizipation für Schnelligkeit und Spielhandlungen im Sportspiel.","a":"• Antizipation = gedankliche Vorwegnahme von Bewegungen, Handlungen, Situationen\n• Verkürzt Reaktions- und Handlungszeit → Handlungsschnelligkeit\n• Erfahrungsbasiert, daher trainierbar","e":"Sie beruht auf Erfahrung, der Wahrnehmung von Hinweisreizen und taktischem Wissen. Selbstantizipation betrifft die eigene Bewegung, Fremdantizipation die Bewegung anderer oder den Ballflug. Weil die Entscheidung schon vor dem eigentlichen Signal vorbereitet wird, handelt ein Spieler trotz gleicher „reiner“ Schnelligkeit schneller. Trainiert wird sie z. B. in spielnahen Übungsformen. Gute Torhüter springen nicht erst, wenn der Ball fliegt, sondern lesen vorher Anlauf und Hüfte des Schützen. Beispiel: Beim Elfmeter erkennt ein erfahrener Torwart an der Stellung des Standbeins die wahrscheinliche Ecke.","quelle":"Verknüpfung L14/L3/L18","typ":"zusatz","bezug":["Q3.2","Q2.3","Q1.4"]},{"id":"vk-013","thema":"VK","kapitel":"Bewegungsstruktur ↔ Lernen","q":"Wie können Bewegungsanalysen (morphologisch, biomechanisch, funktional) beim Lehren und Lernen von Bewegungen genutzt werden?","a":"• Morphologisch: Beobachtungskriterien, Bewegungsvorstellung\n• Biomechanisch: begründet Technik und Korrekturen\n• Funktional: unverzichtbare Teile (Hauptfunktionsphase) → Vereinfachungen, Übungsreihen\n• Zusammen: gezieltes Feedback, Methodenwahl","e":"Die morphologische Analyse gibt Lehrkräften Beobachtungskriterien und Lernenden eine klare Bewegungsvorstellung. Die biomechanische Analyse erklärt mit Kräften, Impuls und biomechanischen Prinzipien, warum eine Technik so ausgeführt werden sollte. Die funktionale Analyse ist die Basis für methodische Übungsreihen und die Wahl zwischen Ganzheits- und Teillernmethode. Beispiel: Wer weiß, dass beim Weitsprung der Absprung die Hauptfunktionsphase ist, übt gezielt den Absprung statt nur die Landung.","quelle":"Verknüpfung L2/L5","typ":"kern","bezug":["Q1.2","Q3.1"]},{"id":"vk-014","thema":"VK","kapitel":"Bewegungsstruktur ↔ Lernen","q":"Erläutere den Zusammenhang zwischen der Phasenstruktur einer Bewegung und der Entscheidung für die Ganzheits- oder Teillernmethode.","a":"• Eng gekoppelte, fließende Phasen → Ganzheitsmethode\n• In eigenständige Funktionsphasen zerlegbar → Teillernmethode\n• Funktionale Analyse zeigt, was isoliert geübt werden kann\n• Oft: Ganzheit – Teile – Ganzheit","e":"Bei eng gekoppelten Bewegungen würde eine Zerlegung Bewegungsfluss und Timing zerstören; komplexe Bewegungen mit relativ eigenständigen Teilen lernt man in Teilen und verbindet sie anschließend. Manche Bewegungen sind wie ein Satz, den man nicht in einzelne Buchstaben zerlegen sollte. Beispiel: Den Kugelstoß kann man in Angleiten und Ausstoß zerlegen, einen Flickflack eher nicht, weil die Phasen fließend ineinander übergehen.","quelle":"Verknüpfung L2/L5","typ":"kern","bezug":["Q1.2","Q3.1"]},{"id":"vk-015","thema":"VK","kapitel":"Bewegungsstruktur ↔ Training","q":"Erläutere den Zusammenhang zwischen dem Impulssatz/dem Prinzip des optimalen Beschleunigungswegs und dem Schnellkraft- bzw. Schnelligkeitstraining.","a":"• Impulssatz: Kraftstoß (Kraft × Zeit) bestimmt die Endgeschwindigkeit\n• Optimaler Beschleunigungsweg: lang, geradlinig bzw. stetig gekrümmt\n• Schnellkrafttraining: hoher Kraftanstieg in kurzer Zeit\n• → Explosivkraft und Technik gehören zusammen","e":"Der Beschleunigungsweg soll so gestaltet sein, dass keine Kraft verloren geht. Weil im Sport meist wenig Zeit zur Kraftentfaltung bleibt, zielt das Schnellkrafttraining auf einen steilen Kraftanstieg. Die Biomechanik liefert so die Begründung, warum Training und Technik zusammenpassen müssen. Je länger und stärker du einen Gegenstand beschleunigst, desto schneller fliegt er. Beispiel: Ein Kugelstoßer nutzt den Angleitschritt, um den Beschleunigungsweg zu verlängern, und braucht viel Schnellkraft, um diesen Weg explosiv zu nutzen.","quelle":"Verknüpfung L2/L13/L14","typ":"kern","bezug":["Q1.2","Q2.2","Q2.3"]},{"id":"vk-016","thema":"VK","kapitel":"Bewegungsstruktur ↔ Training","q":"Wie hängen Dehnungs-Verkürzungs-Zyklus, Reaktivkraft und das Prinzip der Anfangskraft zusammen?","a":"• Anfangskraft (Hochmuth): Gegenbewegung → positive Anfangskraft → größerer Kraftstoß\n• Grundlage: Dehnungs-Verkürzungs-Zyklus (elastische Energie, Dehnungsreflex)\n• Reaktivkraft: hoher Kraftstoß im kurzen DVZ (Plyometrie)","e":"Der Muskel arbeitet erst exzentrisch, dann konzentrisch. In der Gegenbewegung wird der Muskel gedehnt und kontrahiert danach kräftiger, weil elastische Energie gespeichert und der Dehnungsreflex ausgelöst wird. Plyometrisches Training sind z. B. Sprungserien und Niedersprünge. Wie bei einer Feder: Erst zusammendrücken, dann schnellt sie stärker zurück. Beispiel: Beim Strecksprung springst du höher, wenn du vorher kurz in die Knie gehst, als aus einer tiefen, ruhigen Hockposition.","quelle":"Verknüpfung L2/L13","typ":"kern","bezug":["Q1.2","Q2.2"]},{"id":"vk-017","thema":"VK","kapitel":"Sportspiel ↔ Lernen","q":"Vergleiche die Vermittlung von Sportspielen mit dem Lernen geschlossener Techniken (z. B. Turnen).","a":"• Sportspiel: offene, wechselnde Bedingungen → situative Anwendung; Technik + Wahrnehmung + Entscheidung\n• Geschlossene Techniken: stabile Bedingungen → konstante, präzise Ausführung (Feinkoordination, Übungsreihen)","e":"Im Spiel sind variable Verfügbarkeit, Taktik und Antizipation gefragt, bei geschlossenen Techniken vor allem eine klare Bewegungsvorstellung. Im Spiel wechseln Mit- und Gegenspieler, Ball, Raum und Zeit. Spielvermittlungskonzepte (spielgemäß, integrativ, TGfU) verbinden deshalb Technik mit Wahrnehmung und Entscheidung. Beide Bereiche durchlaufen Lernphasen, im Spiel steht aber früher das Handeln in Situationen im Mittelpunkt. Turnen ist wie ein auswendig gelerntes Gedicht, ein Sportspiel wie ein Gespräch mit jemandem, der ständig Unerwartetes sagt. Beispiel: Ein Handball-Sprungwurf muss jedes Mal an Abwehr und Torwart angepasst werden, eine Rolle vorwärts nicht.","quelle":"Verknüpfung L18/L5","typ":"kern","bezug":["Q1.4","Q3.1","Q3.2"]},{"id":"vk-018","thema":"VK","kapitel":"Sportspiel ↔ Lernen","q":"Ordne die Ganzheits- und Teillernmethode den Konzepten der Sportspielvermittlung zu.","a":"• Spielgemäße Konzepte (Spielreihen, genetisch, TGfU) → Ganzheitsmethode\n• Technikorientierte Konzepte (Übungsreihen, Einzeltechniken zuerst) → Teillernmethode\n• Integrative Konzepte → Ganzheit – Teil – Ganzheit","e":"Spielgemäße Konzepte beginnen mit vereinfachten Spielformen, das Spiel als Ganzes bleibt erhalten. Technikorientierte Konzepte arbeiten zergliedernd-synthetisch, integrative wechseln Spielen und gezieltes Üben ab. Die Vor- und Nachteile übertragen sich: Ganzheitlich ist motivierend und situationsnah, aber technisch ungenauer; Teillernen bringt präzise Technik, aber Transferprobleme ins Spiel. Beispiel: Kleinfeldspiele 3 gegen 3 sind ganzheitlich, isolierte Passübungen in Reihen sind Teillernen.","quelle":"Verknüpfung L18/L5","typ":"kern","bezug":["Q1.4","Q3.1"]},{"id":"vk-019","thema":"VK","kapitel":"Sportspiel ↔ Training","q":"Welche konditionellen Anforderungen stellen Sportspiele und wie berücksichtigt man sie im Training?","a":"• Intervallartiges Profil: kurze intensive Aktionen + ruhigere Phasen\n• Nötig: Grundlagenausdauer, Schnelligkeit, Schnellkraft, Schnelligkeitsausdauer\n• Training: Dauer-/extensive Intervallmethode, spielnahe Schnelligkeit","e":"Kurze Aktionen sind Sprints, Sprünge und Richtungswechsel. Die Grundlagenausdauer sorgt für schnellere Erholung zwischen den Aktionen. Schnelligkeit trainiert man möglichst in komplexen Spielformen mit Ball, Wahrnehmung und Entscheidung. Ermüdung beeinträchtigt Technik und Entscheidungsqualität, Kondition sichert die Spielfähigkeit bis zum Schluss. Ein Fußballspiel ist ein 90-minütiges Intervalltraining. Beispiel: Ein Spieler mit guter Grundlagenausdauer erholt sich zwischen zwei Sprints schneller und trifft auch in der 85. Minute noch gute Entscheidungen.","quelle":"Verknüpfung L18/L12/L14","typ":"zusatz","bezug":["Q1.4","Q2.1","Q2.3"]},{"id":"vk-020","thema":"VK","kapitel":"Leistung ↔ Training","q":"Erläutere das Modell der Leistungsfaktoren und ordne die Themen der Qualifikationsphase ein.","a":"• Faktoren: Kondition, Koordination/Technik, Taktik/Kognition, Psyche, Konstitution, äußere Bedingungen\n• Q1/Q2 Kondition, Q1.2/Q3 Bewegung/Lernen, Q1.4 Taktik, Q4 Medien/Wirtschaft\n• Faktoren beeinflussen sich gegenseitig","e":"Zu den äußeren Bedingungen zählen Umwelt und soziales Umfeld. Q1/Q2 behandeln Ausdauer, Kraft, Schnelligkeit und ihre biologischen Grundlagen; Q1.2/Q3 Bewegungsstruktur, Bewegungslernen, Koordination und Antizipation; Q4 gesellschaftliche Rahmenbedingungen, die Leistung z. B. durch Förderung oder Leistungsdruck beeinflussen. Die Leistung ist mehr als die Summe der Teile, wie ein Puzzle. Beispiel: Ein Tennisprofi braucht Ausdauer (Q2.1), eine perfekte Vorhand (Q3.1), Antizipation (Q3.2) und Nervenstärke, und er spielt in einem von Medien und Sponsoren geprägten Umfeld (Q4).","quelle":"Verknüpfung L10","typ":"kern","bezug":["Q1.1","Q2.1","Q2.2","Q2.3","Q3.2"]},{"id":"vk-021","thema":"VK","kapitel":"Leistung ↔ Training","q":"Erkläre den Unterschied zwischen Belastung und Beanspruchung und seine Bedeutung für die Steuerung des Ausdauertrainings.","a":"• Belastung: von außen vorgegebene Anforderung\n• Beanspruchung: individuelle Reaktion (HF, Laktat, Anstrengungsempfinden)\n• Gleiche Belastung → unterschiedliche Beanspruchung → Steuerung über HF-Bereiche, Laktatschwellen","e":"Eine Belastung ist z. B. „30 min Laufen mit 10 km/h“. Weil Trainierte und Untrainierte darauf ganz verschieden reagieren, steuert man die Intensität nicht nur über die Geschwindigkeit. Belastung ist der Rucksack, Beanspruchung, wie schwer er sich für dich anfühlt. Beispiel: Ein Tempo von 10 km/h ist für einen Trainierten locker (Puls 130), für einen Untrainierten sehr anstrengend (Puls 180).","quelle":"Verknüpfung L11/L12","typ":"kern","bezug":["Q1.1","Q2.1"]},{"id":"vk-022","thema":"VK","kapitel":"Leistung ↔ Training","q":"Welche Wechselwirkungen gibt es zwischen Ausdauer-, Kraft- und Schnelligkeitstraining, wenn man sie kombiniert?","a":"• Grundlagenausdauer verbessert Erholung und Belastbarkeit\n• Kraft ist Voraussetzung für Schnelligkeit\n• Viel Ausdauertraining kann Maximal-/Schnellkraft bremsen (Interferenz)\n• Reihenfolge: Schnelligkeit/Technik → Kraft → Ausdauer","e":"Die Interferenz entsteht, weil gegensätzliche Anpassungen gefordert werden. Schnelligkeit und Technik kommen zuerst, weil sie Ausgeruhtheit verlangen. Die Kombination muss also auf das Ziel der Sportart abgestimmt werden: Kraft und Schnelligkeit sind Freunde, viel Ausdauertraining kann bei Sprintern bremsen. Beispiel: Ein Sprinter läuft keine langen Dauerläufe, ein Fußballer braucht dagegen beides in einer guten Mischung.","quelle":"Verknüpfung L11/L12/L13/L14","typ":"zusatz","bezug":["Q2.1","Q2.2","Q2.3","Q1.1"]},{"id":"vk-023","thema":"VK","kapitel":"Lernen ↔ Koordination","q":"Warum sollten Technik-, Koordinations- und Schnelligkeitstraining im ausgeruhten Zustand stattfinden?","a":"• Hohe Anforderungen an das ZNS (Präzision, Timing, maximale Ansteuerung)\n• Ermüdung → Steuerungsfehler, falsche Muster festigen sich\n• Kein maximales Tempo → kein Schnelligkeitsreiz\n• Ausnahme: Fortgeschrittene unter Belastungsdruck","e":"Wer ermüdet übt, riskiert, falsche Bewegungsmuster einzuschleifen. Fortgeschrittene nutzen Ermüdung dagegen gezielt, um die Stabilität der Technik zu prüfen bzw. zu verbessern. Ein müdes Gehirn lernt schlecht und steuert ungenau. Beispiel: Freiwürfe am Ende eines harten Trainings gehen öfter daneben. Wer neu lernt, sollte das deshalb zu Beginn tun.","quelle":"Verknüpfung L4/L5/L14","typ":"kern","bezug":["Q3.1","Q2.3","Q3.2"]},{"id":"vk-024","thema":"VK","kapitel":"Gesellschaft ↔ Leistung","q":"Erläutere, wie Medien und Wirtschaft den Leistungssport und das Training beeinflussen können.","a":"• Medien/Sponsoren ermöglichen Professionalisierung\n• Steigender Erfolgsdruck → Übertraining, Verletzungen, Doping\n• Termine, Regeln, Formate an Medien angepasst → beeinflusst Periodisierung","e":"Professionalisierung heißt: Vollprofis, bessere Trainingsbedingungen, Wissenschaft und Material. Nur Sieger und Rekorde werden vermarktet, deshalb wächst der Druck. Zu dichte Wettkampfkalender begünstigen Verletzungen und Übertraining, Manipulation wie Doping wird verlockender. Wenn Termine, Regeln und Formate sich nach Medienbedürfnissen richten, wirkt sich das auf Periodisierung und Belastungssteuerung aus. Geld und Aufmerksamkeit sind Antrieb und Gefahr zugleich. Beispiel: Profifußballer spielen durch TV-Verträge sehr viele Spiele in kurzer Zeit, was Regeneration und Trainingsplanung schwierig macht.","quelle":"Verknüpfung Q4.1/L10/L22","typ":"zusatz","bezug":["Q4.1","Q1.1"]},{"id":"vk-025","thema":"VK","kapitel":"Gesellschaft ↔ Leistung","q":"Wie verändern Medien Sportspiele und ihre Regeln? Nenne Gründe und mögliche Folgen.","a":"• Gründe: Attraktivität, Spannung, planbare Dauer, Vermarktung\n• Veränderungen: Regeln für mehr Tempo/Tore, Werbepausen, neue Formate, Videobeweis\n• Folgen: mehr Einnahmen, veränderte Taktik/Belastung, Zuschauerorientierung","e":"Werbepausen, Sendezeiten und feste Spielzeiten sind für die Vermarktung entscheidend. Der Sport richtet sich dadurch zunehmend am Zuschauer statt an sich selbst aus. Auch der Schulsport kann sich an veränderten Spielformen orientieren. Was im Fernsehen gut aussieht, setzt sich oft durch. Beispiel: Beim Volleyball wurde die Rallypoint-Zählweise eingeführt, damit Spiele kürzer und für das Fernsehen besser planbar werden.","quelle":"Verknüpfung Q4.1/L18","typ":"zusatz","bezug":["Q4.1","Q1.4"]},{"id":"vk-026","thema":"VK","kapitel":"Bewegungsstruktur ↔ Koordination","q":"Erläutere den Zusammenhang zwischen Außenaspekt und Innenaspekt einer sportlichen Bewegung und den koordinativen Fähigkeiten.","a":"• Außenaspekt: sicht- und messbares Erscheinungsbild\n• Innenaspekt: unsichtbare Steuerung/Regelung (Wahrnehmung, Informationsverarbeitung)\n• Koordinative Fähigkeiten = Voraussetzungen des Innenaspekts","e":"Zum Außenaspekt gehören Phasen, Bewegungsmerkmale und biomechanische Größen, zum Innenaspekt auch Bewegungsprogramm und Motivation. Die Qualität des Außenaspekts, z. B. Bewegungsrhythmus und Präzision, ist das Ergebnis eines gut funktionierenden Innenaspekts. Was man sieht, ist nur die Spitze des Eisbergs; darunter arbeitet das Nervensystem. Beispiel: Ein flüssiger Hürdenlauf (außen) ist das Ergebnis von guter Rhythmisierungs- und Kopplungsfähigkeit (innen).","quelle":"Verknüpfung L1/L3/L4","typ":"kern","bezug":["Q1.2","Q3.2"]},{"id":"vk-027","thema":"VK","kapitel":"Lernen ↔ Koordination","q":"Welche Rolle spielen die Analysatoren (optisch, akustisch, kinästhetisch, taktil, vestibulär) in den verschiedenen Lernphasen?","a":"• Grobkoordination: optischer und akustischer Analysator dominieren\n• Feinkoordination: kinästhetischer Analysator wichtiger\n• Variable Verfügbarkeit: unbewusste Verarbeitung, Blick frei\n• Lernhilfen an die Phase anpassen","e":"Anfänger lernen durch Zuschauen und Erklärungen, ihre Eigenwahrnehmung ist noch wenig differenziert. In der Feinkoordination werden Bewegungen über Rückmeldungen aus Muskeln, Sehnen und Gelenken „erfühlt“. Später wird der optische Analysator frei für Gegner und Mitspieler. Deshalb: Demonstration früh, Bewegungsgefühl später. Beispiel: Beim Dribbeln im Basketball schaut man anfangs auf den Ball, ein Könner spürt ihn und schaut auf das Spielfeld.","quelle":"Verknüpfung L3/L5","typ":"kern","bezug":["Q3.1","Q3.2"]},{"id":"vk-028","thema":"VK","kapitel":"Training ↔ Biologie","q":"Wie wirken sich die biologischen Anpassungen durch Ausdauertraining auf andere Bereiche (Erholung, Gesundheit, Spiel) aus?","a":"• Herz: größeres Schlagvolumen, niedrigere Herzfrequenz\n• Muskel: mehr Mitochondrien, Kapillaren, Glykogen; bessere Fettverbrennung\n• Folge: schnellere Erholung, höhere Belastbarkeit\n• Gesundheit: Prävention, positive psychische Wirkung","e":"Ausdauertraining beugt Herz-Kreislauf- und Stoffwechselerkrankungen vor. Bei intensivem Training kann ein Sportherz entstehen; Ruhe- und Belastungsherzfrequenz sinken. Die schnellere Erholung zwischen intensiven Belastungen nützt im Intervall-, Kraft- und Spieltraining. Ausdauer ist das Fundament, auf dem alles andere steht. Beispiel: Wer eine gute Grundlagenausdauer hat, kann im Krafttraining mehr Sätze schaffen und ist im Handballspiel länger konzentriert.","quelle":"Verknüpfung L12/L21","typ":"kern","bezug":["Q2.1","Q1.1"]},{"id":"vk-029","thema":"VK","kapitel":"Bewegungsstruktur ↔ Training","q":"Erläutere, warum die Arbeitsweisen der Muskulatur (konzentrisch, exzentrisch, isometrisch) sowohl für die Bewegungsanalyse als auch für das Krafttraining wichtig sind.","a":"• Bewegungsanalyse: pro Phase bestimmen, welche Muskeln wie arbeiten\n• Krafttraining: geforderte Arbeitsweise und Bewegungsrichtung trainieren (Spezifität)\n• Aus der Analyse folgen passende Kraftfähigkeit und Übungen","e":"Typisch ist exzentrisches Abbremsen bei der Landung und konzentrische Streckung beim Absprung. Aus der Analyse lässt sich ableiten, ob Maximal-, Schnell- oder Reaktivkraft gefragt ist. Die Analyse sagt dir, was der Muskel in der Sportart tut, und das Training soll genau das verbessern. Beispiel: Basketballer brauchen exzentrische Kraft für Landungen und reaktive Kraft für schnelle Sprünge, also trainieren sie Niedersprünge und Sprungserien.","quelle":"Verknüpfung L2/L13","typ":"kern","bezug":["Q1.2","Q2.2","Q3.1"]},{"id":"vk-030","thema":"VK","kapitel":"Gesellschaft ↔ Leistung","q":"Welche Verbindung besteht zwischen Kommerzialisierung, Leistungsdruck und Doping?","a":"• Erfolg bestimmt Einkommen, Sponsoring, Aufmerksamkeit\n• Hoher Leistungsdruck begünstigt Doping (Systemzwang)\n• Doping ersetzt trainingsbedingte Anpassungen\n• Folgen: Gesundheitsrisiken, Wettbewerbsverzerrung, Glaubwürdigkeitsverlust","e":"Die soziologische Erklärung sieht Doping als Folge von Systemzwängen, nicht nur als individuelle Schuld. Doping ersetzt genau die Anpassungen, die sonst durch Training entstehen: EPO verbessert den Sauerstofftransport (Ausdauer), Anabolika fördern den Muskelaufbau (Kraft). Wenn nur der Sieg zählt und viel Geld daran hängt, wächst die Versuchung zu betrügen. Beispiel: Radsport-Skandale zeigten, wie ein ganzes System aus Teams, Sponsoren und Medien Doping begünstigen kann.","quelle":"Verknüpfung Q4.1/L22/L12/L13","typ":"zusatz","bezug":["Q4.1","Q2.1","Q2.2"]}];
